\section{Appendix: Proofs}
%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%

\emph{Proof of Proposition~\ref{prop:unitcube}.}
%%%%%%%%%%%%%%%%%%%%%%%
Consider the 
closed-loop system~\eqref{eq:closedloop}.
%%%%%%%%
Fix an initial condition~$x(0)=a\in[0,1]^n$. Suppose that there exist~$i
\in\{1,\dots,n\}$ and~$t\geq 0$ such that~$x_i(t,a)=0$. 
Then there exists a minimal index~$j$ such that~$x_j(t,a)=0$.
If~$j=1$ then
\[
\dot x_1(t)=\lambda_{0} k  g(\lambda_nx_n(t))>0.
\]
If~$j\in\{2,\dots,n-1\}$ then
\[
\dot x_j(t)=\lambda_{j-1} x_{j-1}(t)>0.
\]
This implies that~$x_\ell(t)>0$ for all~$\ell\in\{1,\dots,n\}$ and all~$t>0$. A similar argument shows that~$x_\ell(t)<1$ for all~$\ell\in\{1,\dots,n\}$ and all~$t>0$, and this completes the proof. 



%%%%%%%%%%%
\emph{Proof of Proposition~\ref{prop:uniequ_e}.}
%%%%%%%%
Since~$[0,1]^n$ is convex  and compact, it follows from Proposition~\ref{prop:unitcube} and  Brouwer's fixed point theorem~\cite{kellogg1976constructive} that the closed-loop system admits at least one equilibrium~$e\in[0,1]^n$. Using Proposition~\ref{prop:unitcube} implies that in fact~$e\in(0,1)^n$. 
By~\eqref{eq:closedloop}, the equilibrium satisfies
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\begin{align} \label{eq:eq_point}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
 \lambda_0  k g(\lambda_n e_n) (1-e_1)   &=\lambda_1 e_1(1-e_2)\nonumber\\
 &=  \lambda_2 e_2(1-e_3)\nonumber \\
&\vdots\\
 &= \lambda_{n-2} e_{n-2}(1-e_{n-1})\nonumber\\
 &= \lambda_{n-1} e_{n-1}(1-e_n)\nonumber\\
 &= \lambda_n e_n.  \nonumber
\end{align}
These equations imply in particular that~$e_n$ uniquely determines~$e_{i}$ for all~$i$. In order to prove uniqueness of the equilibrium, seeking a contradiction, suppose that~$p,q\in(0,1)^n$ are two different equilibrium points. Then~$p_n\not=q_n$, and we may assume that~$p_n>q_n$. By~\eqref{eq:eq_point},
$
e_{n-1}=\frac{\lambda_{n}e_n} {\lambda_{n-1}(1-e_n)} 
$, so~$p_{n-1}>q_{n-1}$. 
Eq.~\eqref{eq:eq_point} also gives
$e_{n-2}= \frac{\lambda_n e_n}{ \lambda_{n-2} (1-e_{n-1})} $,  so~$p_{n-2}>q_{n-2}$. Continuing in this way, we find that~$p_i>q_i$ for all~$i$. Now~\eqref{eq:eq_point} and the fact that~$g$ is decreasing give
\begin{align*}
    \lambda_n p_n &= \lambda_0 k  g(\lambda_n p_n)(1-p_1)\\
  &<  \lambda_0  k g(\lambda_n q_n)(1-q_1)\\
  &= \lambda_n q_n,
\end{align*}
so~$p_n<q_n$. This contradiction shows that the equilibrium is unique. 



The Jacobian of the closed-loop system is
\be\label{eq:jacob}
J(x)=\left[ \begin{smallmatrix}
-\lambda_0  k g(\lambda_n x_n) -\lambda_1(1-x_2)& \lambda_1 x_1 &0&0&\dots&0&   \lambda_0\lambda_n (1-x_1)kg'(\lambda_n x_n) \\
%%%%%%%
\lambda_1(1-x_2) & -\lambda_1 x_1 -\lambda_2(1-x_3) & \lambda_2 x_2 &0 &    \dots&0&0  \\
%%%%%%%%%%
&&\vdots\\
%%%%%%
                0&0&0&0&\dots& \lambda_{n-1} (1-x_n)&-\lambda_{n-1}x_{n-1}-\lambda_n
%%%%%%
\end{smallmatrix}\right ] .
%%%    
\ee
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
Let~$s_i(x)$ denote the sum of the entries in column~$i$ of~$J(x)$, with the off-diagonal terms taken with absolute value. Then 
\begin{align*}
    s_1(x)  & = -\lambda_0 k  g(\lambda_n x_n) \leq -\lambda_0 k  g(\lambda_n  ),\\
    s_2(x) & =\dots=s_{n-1}(x)=0,\\
    s_n(x) &= -\lambda_n+\lambda_0\lambda_n (1-x_1)k|   g'(\lambda_n x_n)  | \leq
   -\lambda_n - \lambda_0\lambda_n  k   \min_{r\in[0,1]} g'(\lambda_n r )  .
\end{align*}
For any~$k>0$ sufficiently small, we have that~$s_1(x),s_n(x)<0$ for all~$x\in[0,1]^n$. 
Recall that the matrix measure 
induced by the~$L_1$ norm is~$\mu_1(J(x))=\max  \{ s_1(x),\dots,s_n(x) \} $ (see, e.g.,~\cite{sontag_cotraction_tutorial}). Using a scaled~$L_1$ norm, as in~\cite{RFM_entrain}, yields that the system is contractive. This implies that~$e$ is globally asymptotically stable.  



%%%%%%%%%%%%%%%%%%%%%%%
\emph{Proof of Theorem~\ref{thm:main}.}
%%%%%%%%%%%%%%%%%%
Since~$g'(z)<0$ for all~$z\geq 0$, Eq.~\eqref{eq:jacob} implies that  
$J(x)$ has the sign pattern of a 2-cooperative system~\cite{Eyal_k_posi} for all~$x\in[0,1]^n$,
and it is irreducible for all~$x\in(0,1)^n$. Using Theorem~2 in~\cite{KATZ_GIORDANO_MARG_2COOP} 
completes the proof of Theorem~\ref{thm:main}.





