\subsection{Proof of Proposition~\ref{prop:forward_ode}}
\begin{quote}\it
    The forward transition matrix is the solution of the system of ordinary differential equations
    \begin{equation}
        \frac{\mathrm{d}H^{(n)}}{\mathrm{d}u}(u)=H^{(n)}(u)\left(Q-\Lambda_{t_{n-1}+u}\right)\notag,\hspace{0.3cm} u\in]0, x_n],
    \end{equation}
    with initial condition $H^{(n)}(0)=\mathbb{I}_M$.
\end{quote}
\begin{proof}
    Let $1\leq i, j\leq M$, $u,\,\Delta u\,> 0$. With elementary probability calculus and by using the Markov property of $S$, we get
    \begin{align}
        H_{ij}^{(n)}(u+\Delta u)&=\mathbb{P}\left(S_{t_{n-1}+u+\Delta u}=j, N_{t_{n-1}+u+\Delta u}-N_{t_{n-1}}=0\,|\,S_{t_{n-1}}=i,\mathcal{F}_{t_{n-1}}\right)\notag\\
        &\hspace{-2.2cm}=\sum_{k=1}^M\mathbb{P}\left(S_{t_{n-1}+u+\Delta u}=j,S_{t_{n-1}+u}=k,N_{t_{n-1}+u+\Delta u}-N_{t_{n-1}}=0\,|\,S_{t_{n-1}}=i,\mathcal{F}_{t_{n-1}}\right)\notag\\
        &\hspace{-2.2cm}=\sum_{k=1}^M\mathbb{P}\big(S_{t_{n-1}+u+\Delta u}=j,S_{t_{n-1}+u}=k,N_{t_{n-1}+u+\Delta u}-N_{t_{n-1}+u}=0, \notag
        \\ & N_{t_{n-1}+u}-N_{t_{n-1}}=0\,|\, S_{t_{n-1}}=i,\mathcal{F}_{t_{n-1}}\big)\notag\\
        &\hspace{-2.2cm}=\sum_{k=1}^M\mathbb{P}\left(S_{t_{n-1}+u}=k,N_{t_{n-1}+u}-N_{t_{n-1}}=0\,|\,S_{t_{n-1}}=i,\mathcal{F}_{t_{n-1}}\right)\times\,\mathbb{P}\big(S_{t_{n-1}+u+\Delta u}=j,\notag\\
        & N_{t_{n-1}+u+\Delta u}-N_{t_{n-1}+u}=0\,|\,S_{t_{n-1}+u}=k,S_{t_{n-1}}=i,N_{t_{n-1}+u}-N_{t_{n-1}}=0,\mathcal{F}_{t_{n-1}}\big)\notag\\
        &\hspace{-2.2cm}=\sum_{k=1}^MH_{ik}^{(n)}(u)\mathbb{P}\big(S_{t_{n-1}+u+\Delta u}=j,N_{t_{n-1}+u+\Delta u}-N_{t_{n-1}+u}=0\notag\\
        &\hspace{-2.2cm}\hspace{3.5cm}|\,S_{t_{n-1}+u}=k,S_{t_{n-1}}=i,N_{t_{n-1}+u}-N_{t_{n-1}}=0,\mathcal{F}_{t_{n-1}}\big)\notag\\
        &\hspace{-2.2cm}=\sum_{k=1}^MH_{ik}^{(n)}(u)\mathbb{P}\big(S_{t_{n-1}+u+\Delta u}=j,N_{t_{n-1}+u+\Delta u}-N_{t_{n-1}+u}=0\,|\,S_{t_{n-1}+u}=k,\notag
        \\ & N_{t_{n-1}+u}-N_{t_{n-1}}=0,\mathcal{F}_{t_{n-1}}\big)\notag\\
        &\hspace{-2.2cm}=\sum_{k=1}^MH_{ik}^{(n)}(u)\mathbb{P}\big(S_{t_{n-1}+u+\Delta u}=j\,|\,S_{t_{n-1}+u}=k,N_{t_{n-1}+u}-N_{t_{n-1}}=0,\mathcal{F}_{t_{n-1}}\big)\notag\\
        &\hspace{-2.2cm}\hspace{1cm}\times\mathbb{P}\big(N_{t_{n-1}+u+\Delta u}-N_{t_{n-1}+u}=0\,|\,S_{t_{n-1}+u+\Delta u}=j,S_{t_{n-1}+u}=k,N_{t_{n-1}+u}-N_{t_{n-1}}=0,\mathcal{F}_{t_{n-1}}\big)\notag\\
        &\hspace{-2.2cm}=\sum_{k=1}^MH_{ik}^{(n)}(u)\mathbb{P}\big(S_{t_{n-1}+u+\Delta u}=j\,|\, S_{t_{n-1}+u}=k\big)\notag\\
        &\hspace{-2.2cm}\hspace{1cm}\times\mathbb{P}\big(N_{t_{n-1}+u+\Delta u}-N_{t_{n-1}+u}=0\,|\,S_{t_{n-1}+u+\Delta u}=j,S_{t_{n-1}+u}=k,N_{t_{n-1}+u}-N_{t_{n-1}}=0,\mathcal{F}_{t_{n-1}}\big)\notag.
    \end{align}
    By applying a Taylor series expansion with $\Delta u\to0$, we get
    \begin{align}
        \hspace{-2cm}H_{ij}^{(n)}(u+\Delta u)&=\sum_{k=1}^MH_{ik}^{(n)}(u)\left(\delta_{kj}+q_{kj}\Delta u+o(\Delta u)\right)\left(1-\lambda_{t_{n-1}+u}^k\Delta u+o(\Delta u)\right)\notag\\
        &=\sum_{k=1}^MH_{ik}^{(n)}(u)\left\{\delta_{kj}+\left(q_{kj}-\delta_{kj}\lambda_{t_{n-1}+u}^k\right)\Delta u+o(\Delta u)\right\},\label{eq:recurrence_H}
    \end{align}
    where
    \begin{equation}
        \lambda_{t_{n-1}+u}^k=\mu^k+\sum_{t_l\leq t_{n-1}}\phi^k(t_{n-1}-t_l+u)\notag.
    \end{equation}
    Using Equation \eqref{eq:recurrence_H},
    \begin{align}
        \frac{1}{\Delta u}\left(H_{ij}^{(n)}(u+\Delta u)-H_{ij}^{(n)}(u)\right)&=\frac{1}{\Delta u}\sum_{k\neq j}H_{ik}^{(n)}(u)\big(q_{kj}\Delta u+o(\Delta u)\big)\notag\\
        &\hspace{0.5cm}-\frac{1}{\Delta u}H_{ij}^{(n)}(u)\big((q_j+\lambda_{t_{n-1}+u}^j)\Delta u+o(\Delta u)\big)\notag,
    \end{align}
    which leads to
    \begin{equation}
        \lim_{\Delta u \to 0^+}\frac{1}{\Delta u}\left(H_{ij}^{(n)}(u+\Delta u)-H_{ij}^{(n)}(u)\right)\,=\,-H_{ij}^{(n)}(u)\left(q_j+\lambda_{t_{n-1}+u}^j\right)+\sum_{k\neq j}H_{ik}^{(n)}(u)q_{kj}\notag.
    \end{equation}
    Since $H_{ij}^{(n)}(0)=\delta_{ij}$, $1\leq i,j \leq M$ we obtain the desired result.
\end{proof}

\subsection{Proof of Lemma~\ref{lemma:forward_backward_equation}}
\begin{quote}\it
    The forward and backward transition matrices follow the equality
    \begin{equation}
        H^{(n)}(t_n-t_{n-1})=H^{(n)}(t-t_{n-1})G^{(n)}(t_n-t)\notag, \hspace{0.3cm}t_{n-1}\leq t\leq t_n.
    \end{equation}
\end{quote}
\begin{proof}
    Let $1\leq i, j\leq M$, $t_{n-1}\leq t\leq t_n$. By using the Markov property of $S$, we have
    \begin{align}
        H_{ij}^{(n)}(t_n^--t_{n-1})&=\mathbb{P}\left(S_{t_n}=j,N_{t_n^-}-N_{t_{n-1}}=0\,|\,S_{t_{n-1}}=i,\mathcal{F}_{t_{n-1}}\right)\notag\\
        &=\mathbb{P}\left(S_{t_n}=j,N_{t_n^-}-N_t=0,N_t-N_{t_{n-1}}=0\,|\,S_{t_{n-1}}=i,\mathcal{F}_{t_{n-1}}\right)\notag\\
        &=\sum_{k=1}^M\mathbb{P}\left(S_{t_n}=j,S_t=k,N_{t_n^-}-N_t=0,N_t-N_{t_{n-1}}=0\,|\,S_{t_{n-1}}=i,\mathcal{F}_{t_{n-1}}\right)\notag\\
        &=\sum_{k=1}^M\mathbb{P}\left(S_t=k,N_t-N_{t_{n-1}}=0\,|\,S_{t_{n-1}}=i,\mathcal{F}_{t_{n-1}}\right)\notag\\
        &\hspace{1.5cm}\times\mathbb{P}\left(S_{t_n}=j,N_{t_n^-}-N_t=0\,|\,S_t=k,S_{t_{n-1}}=i,N_t-N_{t_{n-1}}=0,\mathcal{F}_{t_{n-1}}\right)\notag\\
        &=\sum_{k=1}^MH_{ik}^{(n)}(t-t_{n-1})\mathbb{P}\left(S_{t_n}=j,N_{t_n^-}-N_t=0\,|\,S_t=k,N_t-N_{t_{n-1}}=0,\mathcal{F}_{t_{n-1}}\right)\notag\\
        &=\sum_{k=1}^MH_{ik}^{(n)}(t-t_{n-1})\mathbb{P}\left(S_{t_n}=j,N_{t_n^-}-N_t=0\,|\,S_t=k,\mathcal{F}_t\right)\notag\\
        &=\sum_{k=1}^MH_{ik}^{(n)}(t-t_{n-1})G_{kj}^{(n)}(t_n-t)\notag.
    \end{align}
\end{proof}

\subsection{Proof of Proposition~\ref{prop:backward_ode}}
\begin{quote}\it
    The backward transition matrix is the solution of the system of ordinary differential equations
    \begin{equation}
        \frac{\mathrm{d}G^{(n)}}{\mathrm{d}u}(u)=\left(Q-\Lambda_{t_n-u}\right)G^{(n)}(u)\notag,\hspace{0.3cm}u\in]0, x_n],
    \end{equation}
    with initial condition $G^{(n)}(0)=\mathbb{I}_M$.
\end{quote}
\begin{proof}
    Let $0\leq u\leq x_n$ and write the equation of Lemma \ref{lemma:forward_backward_equation} with the change of variable $u:=t_n-t$ 
    \begin{equation}\label{eq:forward_backward_with_u}
        H^{(n)}(t_n-t_{n-1})=H^{(n)}(t_n-t_{n-1}-u)G^{(n)}(u)\notag.
    \end{equation}
    Differentiating both sides of Equation \eqref{eq:forward_backward_with_u} with respect to $u$ leads to
    \begin{equation}
        H^{(n)}(t_n-t_{n-1}-u)\frac{\mathrm{d}G^{(n)}}{\mathrm{d}u}(u)=\frac{\mathrm{d}H^{(n)}}{\mathrm{d}u}(t_n-t_{n-1}-u)G^{(n)}(u)\notag.
    \end{equation}
    We then use Proposition \ref{prop:forward_ode} to obtain
    \begin{align}
        \frac{\mathrm{d}G^{(n)}}{\mathrm{d}u}(u)&=\left[H^{(n)}(t_n-t_{n-1}-u)\right]^{-1}\frac{\mathrm{d}H^{(n)}}{\mathrm{d}u}(t_n-t_{n-1}-u)G^{(n)}(u)\notag\\
        &=\left(Q-\Lambda_{t_n-u}\right)G^{(n)}(u)\notag.
    \end{align}
\end{proof}

\subsection{Proof of Proposition~\ref{prop:forward_backward_formulas}}
\begin{quote}\it
    If the intensity is given by Equation \eqref{eq:piecewise_constant_intensity}, the forward transition matrix is
    \begin{equation}
        H^{(n)}(u)=\Xi^{(n)}_{\ell(t_{n-1}+u)}e^{(Q-\Lambda_{t_{n-1}+\ell(t_{n-1}+u)\delta})(u-\ell(t_{n-1}+u)\delta)},\hspace{0.3cm} 0\leq u\leq x_n,
    \end{equation}
    for which we define the following quantity
    \begin{equation}
        \Xi^{(n)}_k:=\prod_{r=1}^{k}e^{((Q-\Lambda_{t_{n-1}+(r-1)\delta})\delta)}, \hspace{0.3cm} 1\leq n\leq K,\hspace{0.1cm} 1\leq k \leq \ell_n.
    \end{equation}

    Similarly, the backward transition matrix is written as, for $u\in[0, x_n]$
    \begin{equation}
        \begin{cases} G^{(n)}(u)=e^{(Q-\Lambda_{t_{n-1}+\ell_n\delta})u}\hspace{0.2cm}\text{if}\;u\leq\Delta_n,\\\\  G^{(n)}(u)=e^{(Q-\Lambda_{t_{n-1}+\ell(t_n-u)\delta})(u-((\ell_n-\ell(t_n-u)-1)\delta+\Delta_n))}\Psi^{(n)}_{\ell_n-\ell(t_n-u)-1}e^{(Q-\Lambda_{t_{n-1}+\ell_n\delta})\Delta_n}\hspace{0.2cm}\text{else},
    \end{cases}
    \end{equation}
    for which we define the following quantity
    \begin{equation}
        \Psi^{(n)}_k:=\prod_{r=1}^{k}e^{(Q-\Lambda_{t_{n-1}+(\ell_n-(k-r)-1)\delta})\delta}, \hspace{0.3cm} 1\leq n\leq K,\hspace{0.1cm} 1\leq k \leq \ell_n.
    \end{equation}
    Here, the notation $e^A$ stands for the matrix exponential of $A$ and we use the convention $\prod_{r=1}^{0}A_r=\mathbb{I}_M$.
\end{quote}
\begin{proof}
    Under the $\delta$-piecewise constant intensity of Equation \eqref{eq:piecewise_constant_intensity}, Equation \eqref{eq:ode_forward} is
    \begin{align}
        \frac{\mathrm{d}H^{(n)}}{\mathrm{d}u}(u)&=H^{(n)}(u)\left(Q-\Lambda_{t_{n-1}+\ell(t_{n-1}+u)\delta}\right),\hspace{0.3cm}0< u\leq x_n,\notag\\
        H^{(n)}(0)&=\mathbb{I}_M.
    \end{align}
    Note that for all $u\in[0, x_n]$, $\Lambda_{t_{n-1}+u}=\Lambda_{t_{n-1}+\ell(t_{n-1}+u)\delta}$ and that $\Lambda_{t_{n-1}+\ell(t_{n-1}+u)\delta}$ is the same whether $\Lambda$ is the MMHP-$\delta$ intensity or its continuous counterpart. We apply a discretization to the domain $]0,x_n]$ with intervals of the form $]k\delta,(k+1)\delta]$, and we get the following set of ODEs
    \begin{equation}
        \frac{\mathrm{d}H^{(n)}}{\mathrm{d}u}(u)=H^{(n)}(u)\left(Q-\Lambda_{t_{n-1}+k\delta}\right),\hspace{0.3cm}u\in]k\delta, (k+1)\delta],\hspace{0.1cm}0\leq k\leq \ell_n.
    \end{equation}
    This system is easily solved iteratively, using the initial condition, for $k=0$, $H^{(n)}(0)=\mathbb{I}_M$ and for $1\leq k\leq \ell_n$,
    \begin{equation}
        H^{(n)}(k\delta)=\prod_{r=1}^ke^{(Q-\Lambda_{t_{n-1}+(r-1)\delta})\delta},
    \end{equation}

    leading to the desired expression of the forward transition matrix.

    The same idea is applied to the backward transition matrix. Indeed, Equation \eqref{eq:ode_backward} is
    \begin{align}
        \frac{\mathrm{d}G^{(n)}}{\mathrm{d}u}(u)&=\left(Q-\Lambda_{t_{n-1}+\ell(t_n-u)\delta}\right)G^{(n)}(u),\hspace{0.3cm}0< u\leq x_n,\notag\\
        G^{(n)}(0)&=\mathbb{I}_M.
    \end{align}
    By operating a discretization to the domain $]0,x_n]$ with intervals of the form $]k\delta+\Delta_n,(k+1)\delta+\Delta_n]$ and $]0,\Delta_n]$, we first get the ODE over the residual time to $t_n$
    \begin{align}
        \frac{\mathrm{d}G^{(n)}}{\mathrm{d}u}(u)&=\left(Q-\Lambda_{t_{n-1}+\ell_n\delta}\right)G^{(n)}(u),\hspace{0.3cm}0<u<\Delta_n,\notag\\
        G^{(n)}(0)&=\mathbb{I}_M,
    \end{align}
    and then the following ODEs over the $\delta$-intervals
    \begin{equation}
        \frac{\mathrm{d}G^{(n)}}{\mathrm{d}u}(u)=\left(Q-\Lambda_{t_{n-1}+(\ell_n-k-1)\delta}\right)G^{(n)}(u),\hspace{0.3cm}k\delta+\Delta_n < u \leq (k+1)\delta+\Delta_n,\hspace{0.1cm}0\leq k\leq \ell_n-1.
    \end{equation}
    Again, this system is iteratively solved at each step $k$ and we obtain the initial conditions
    \begin{equation}
        G^{(n)}(k\delta+\Delta_n)=\prod_{r=1}^ke^{(Q-\Lambda_{t_{n-1}+(\ell_n-(k-r)-1)\delta})\delta}e^{(Q-\Lambda_{t_{n-1}+\ell_n\delta})\Delta_n},\hspace{0.1cm}0\leq k\leq \ell_n-1.
    \end{equation}
    We finally get the desired expression of the backward transition matrix.
\end{proof}



\subsection{Proof of Proportion~\ref{prop:complete_likelihood}}

\begin{quote}\it
    The log-likelihood of an MMHP with parameters $\Theta:=\Theta^M\cup\Theta^H$ over the observations $\mathcal{T}$ can be written as
    \begin{equation}
        \mathcal{L}(\Theta,\mathcal{T})=\log \mathcal{L}^M(\Theta^M,\mathcal{T})+\log \mathcal{L}^H(\Theta^H,\mathcal{T})\notag,
    \end{equation}
    where
    \begin{equation}
        \log \mathcal{L}^M(\Theta^M,\mathcal{T})=\sum_{i=1}^M\left\{\mathds{1}_{\{S_0=i\}}\log \xi_0^i-D_iq_i+\sum_{j=1,j\neq i}^Mw_{ij}\log q_{ij}\right\}\notag,
    \end{equation}
    and
    \begin{equation}
        \log \mathcal{L}^H(\Theta^H,\mathcal{T})=\sum_{i=1}^M\left\{\sum_{n=1}^K\mathds{1}_{\{S_{t_n}=i\}}\log \lambda_{t_n}^i(\Theta^H)\,-\,\int_0^T\mathds{1}_{\{S_t=i\}}\lambda_t^i(\Theta^H)\,\mathrm{d}t\right\}\notag,
    \end{equation}
    for which we define the time $S$ spends in state $i$ over $[0,T]$
    \begin{equation}
        D_i:=\int_0^T\mathds{1}_{\{S_t=i\}}\mathrm{d}t=\sum_{p=1}^{m+1} \mathds{1}_{\{s_p=i\}}(u_p-u_{p-1})\notag,
    \end{equation}
    and the number of times $S$ jumps from state $i$ to state $j$ over $[0,T]$
    \begin{equation}
        w_{ij}:=\int_0^T\underset{\Delta\to0^+}{\lim}\frac{1}{\Delta}\mathds{1}_{\{S_{t-\Delta}=i,\, S_t=j\}}\mathrm{d}t=\sum_{p=1}^m \mathds{1}_{\{s_p=i, s_{p+1}=j\}}\notag.
    \end{equation}
\end{quote}

\begin{proof}
    Denote by $(u_p)_{1\leq p\leq m}$ the ordered sequence of unobserved transition times of the Markov chain $S$ over the time interval $[0,T]$, with the conventions $u_0=0$, $u_{m+1}=T$. Let $(s_p)_{1\leq p \leq m}$ be the sequence of states such that $S_t=s_p$, for any $t\in[u_{p-1},u_p)$. Let $z_p:=N_{u_p}-N_{u_{p-1}}$, $1\leq p\leq m+1$, be the number of events between the two state transition times $u_{p-1}$ and $u_p$, with the convention $z_0=0$. Define
    \begin{equation}
        \rho_k:=\sum_{p=0}^kz_p\notag,\hspace{0.3cm} 0\leq k\leq m+1,
    \end{equation}
    the number of events in the interval $[0,u_k]$. The likelihood of the model is
    \begin{align}
        \mathcal{L}(\Theta,\mathcal{T})&=\xi_0^{s_1}\left(\prod_{p=1}^m e^{-q_{s_p}(u_p-u_{p-1})}q_{s_ps_{p+1}}\right)e^{-q_{s_{m+1}}(T-u_m)}\prod_{p=1}^{m+1}\prod_{k=1}^{z_p}\lambda_{t_{\rho_{p-1}+k}}^{s_p}e^{-\int_{t_{\rho_{p-1}+k-1}}^{t_{\rho_{p-1}+k}}\lambda_t^{s_p}\mathrm{d}t}\notag\\
        &=\left(\sum_{i=1}^M\mathds{1}_{\{s_0=i\}}\xi_0^i\right)\exp\left(-\sum_{p=1}^m \sum_{i=1}^M \mathds{1}_{\{s_p=i\}}q_i(u_p-u_{p-1})\right)\left(\prod_{p=1}^m \sum_{1\leq i,j \leq M,i\neq j} \mathds{1}_{\{s_p=i, s_{p+1}=j\}}q_{ij}\right)\notag\\
        &\hspace{0.5cm}\times \exp\left(-\sum_{i=1}^M\mathds{1}_{\{s_{m+1}=i\}}q_i(T-u_m)\right)\prod_{p=1}^{m+1}\left(\sum_{i=1}^M \mathds{1}_{\{s_p=i\}}\exp\left(-\int_{t_{\rho_{p-1}}}^{t_{\rho_p}}\lambda_t^i\mathrm{d}t\right)\prod_{k=1}^{z_p}\lambda_{t_{\rho_{p-1}+k}}^i\right)\notag.
    \end{align}
    By taking the logarithm of both sides of the equation, we obtain
    \begin{align}
        \log\mathcal{L}(\Theta,\mathcal{T})&=\sum_{i=1}^M\mathds{1}_{\{s_0=i\}}\log\xi_0^i - \sum_{i=1}^M \sum_{p=1}^{m+1} \mathds{1}_{\{s_p=i\}}(u_p-u_{p-1})q_i + \sum_{1\leq i,j \leq M,i\neq j} \sum_{p=1}^m \mathds{1}_{\{s_p=i, s_{p+1}=j\}}\log q_{ij}\notag\\
        &\hspace{0.5cm}+ \sum_{i=1}^M \sum_{p=1}^{m+1} \mathds{1}_{\{s_p=i\}}\left(\sum_{k=1}^{z_p}\log\lambda_{t_{\rho_{p-1}+k}}^i-\int_{t_{\rho_{p-1}}}^{t_{\rho_p}}\lambda_t^i\mathrm{d}t\right)\notag\\
        &=\sum_{i=1}^M\left(\mathds{1}_{\{s_0=i\}}\log\xi_0^i - \sum_{p=1}^{m+1} \mathds{1}_{\{s_p=i\}}(u_p-u_{p-1})q_i + \sum_{j=1,j\neq i}^M \sum_{p=1}^m \mathds{1}_{\{s_p=i, s_{p+1}=j\}}\log q_{ij}\right)\notag\\
        &\hspace{0.5cm}+ \sum_{i=1}^M \sum_{n=1}^{K} \left(\mathds{1}_{\{s_{t_n}=i\}}\log\lambda_{t_n}^i-\int_{t_{n-1}}^{t_n}\mathds{1}_{\{s_t=i\}}\lambda_t^i\mathrm{d}t\right)\notag.
    \end{align}
    Use the definitions of $D_i$ and $w_{ij}$ in Equations \eqref{eq:D_i} and \eqref{eq:w_ij} to complete the proof.
\end{proof}


\subsection{Proof of Proposition~\ref{prop:e_step_likelihood}}

\begin{quote}\it
    Given an estimated set of parameters $\widehat{\Theta}$, the expected log-likelihood of the E-step can be written as
    \begin{equation}
        \mathbb{E}\left(\log \mathcal{L}(\Theta,\mathcal{T})|\mathcal{F}_T,\widehat{\Theta}\right)=\mathbb{E}\left(\log \mathcal{L}^M(\Theta,\mathcal{T})\Big|\mathcal{F}_T,\widehat{\Theta}\right)+\mathbb{E}\left(\log \mathcal{L}^H(\Theta,\mathcal{T})\Big|\mathcal{F}_T,\widehat{\Theta}\right)\notag,
    \end{equation}
    with
    \begin{equation}
        \mathbb{E}\left(\log \mathcal{L}^M(\Theta,\mathcal{T})\Big|\mathcal{F}_T,\widehat{\Theta}\right)=\sum_{i=1}^M\left\{\xi_{0|T}^i(\widehat{\Theta})\log \xi_0^i-\mathbb{E}(D_i|\mathcal{F}_T,\widehat{\Theta})q_i+\sum_{j=1,j\neq i}^M\mathbb{E}(w_{ij}|\mathcal{F}_T,\widehat{\Theta})\log q_{ij}\right\}\notag,
    \end{equation}
    and
    \begin{equation}
        \mathbb{E}\left(\log \mathcal{L}^H(\Theta,\mathcal{T})\Big|\mathcal{F}_T,\widehat{\Theta}\right)=\sum_{i=1}^M\left\{\sum_{n=1}^K\xi_{t_n|T}^i(\widehat{\Theta})\log \lambda_{t_n}^i(\Theta)-\int_0^T\xi_{t|T}^i(\widehat{\Theta})\lambda_t^i(\Theta)\mathrm{d}t\right\}\notag.
    \end{equation}

    Furthermore, we have the analytic expressions

    \begin{equation}
        \mathbb{E}\left(D_i|\mathcal{F}_T,\widehat{\Theta}\right)=\sum_{n=1}^K\frac{1}{c_n}\left[\sum_{k=0}^{\ell_n-1}\left[e^{C^{(n)}_k\delta}\right]^{M\boxtimes M}+\left[e^{D^{(n)}\Delta_n}\right]^{M\boxtimes M}\right]_{ii}\notag,
    \end{equation}

    \begin{equation}
        \mathbb{E}\left(w_{ij}|\mathcal{F}_T,\widehat{\Theta}\right)=\widehat{q}_{ij}\sum_{n=1}^K\frac{1}{c_n}\left[\sum_{k=0}^{\ell_n-1}\left[e^{C^{(n)}_k\delta}\right]^{M\boxtimes M}+\left[e^{D^{(n)}\Delta_n}\right]^{M\boxtimes M}\right]_{ji}\notag,
    \end{equation}

    \begin{equation}
        \int_0^T\xi_{t|T}^i(\widehat{\Theta})\lambda_t^i\mathrm{d}t=\sum_{n=1}^K\frac{1}{c_n}\left[\sum_{k=0}^{\ell_n-1}\Lambda_{t_{n-1}+k\delta}\,\odot\,\left[e^{C^{(n)}_k\delta}\right]^{M\boxtimes M}+\Lambda_{t_{n-1}+\ell_n\delta}\,\odot\,\left[e^{D^{(n)}\Delta_n}\right]^{M\boxtimes M}\right]_{ii}\notag,
    \end{equation}

    and the smoothed probabilities are given by Equations \eqref{eq:filtered_prob_vs_forward_backward} and \eqref{eq:smoothed_prob_vs_forward_backward}.
\end{quote}
\begin{proof}
    \begin{equation}
        \mathbb{E}\left(\log \mathcal{L}^M(\Theta,\mathcal{T})\Big|\mathcal{F}_T,\widehat{\Theta}\right)=\sum_{i=1}^M\left\{\xi_{0|T}^i(\widehat{\Theta})\log \xi_0^i-\mathbb{E}(D_i|\mathcal{F}_T,\widehat{\Theta})q_i+\sum_{j=1,j\neq i}^M\mathbb{E}(w_{ij}|\mathcal{F}_T,\widehat{\Theta})\log q_{ij}\right\}\notag,
    \end{equation}
    Using the work of \cite{ryden1994parameter}, we can write
    \begin{align}
        \mathbb{E}\left(D_i|\mathcal{F}_T,\widehat{\Theta}\right)&=\int_0^T\frac{\alpha_t^i\beta_t^i}{\mathcal{L}}\mathrm{d}t\notag,\hspace{0.3cm}1\leq i\leq M,\\
        \mathbb{E}\left(w_{ij}|\mathcal{F}_T,\widehat{\Theta}\right)&=\int_0^Tq_{ij}\frac{\alpha_t^i\beta_t^j}{\mathcal{L}}\mathrm{d}t\notag,\hspace{0.3cm}1\leq i,j\leq M,i\neq j.
    \end{align}
    We now aim at computing the integrals
    \begin{equation}
        \int_0^T\frac{\alpha_t^i\beta_t^j}{\mathcal{L}}\,\mathrm{d}t,\hspace{0.3cm}\int_0^T\frac{\alpha_t^i\beta_t^i}{\mathcal{L}}\lambda_t^i\,\mathrm{d}t\notag,\hspace{0.3cm}1\leq i,j\leq M.
    \end{equation}
    Using the $\delta$-piecewise constant kernel hypothesis, write
    \begin{align}
        \int_0^T\frac{\alpha_t^i\beta_t^i}{\mathcal{L}}\lambda_t^i\mathrm{d}t&=\sum_{n=1}^K\frac{1}{\mathcal{L}}\int_{t_{n-1}}^{t_n}\alpha_t^i\beta_t^i\lambda_t^i\mathrm{d}t\notag\\
        &=\sum_{n=1}^K\frac{1}{\prod_{k=1}^Kc_k}\int_{t_{n-1}}^{t_n}\pi\prod_{k=1}^{n-1}f^{(k)}(x_k)\lambda_t^iH^{(n)}\left(t-t_{n-1}\right)\mathds{1}_i\mathds{1}_i'G^{(n)}\left(t_n-t\right)\Lambda_{t_n^-}\prod_{k=n+1}^Kf^{(k)}(x_k)\mathds{1}\mathrm{d}t\notag\\
        &=\sum_{n=1}^K\frac{1}{c_n}\left[\int_0^{x_n}\Lambda_{t_{n-1}+x}\odot G^{(n)}(x_n-x)P^{(n)}H^{(n)}(x)\mathrm{d}x\right]_{ii}\notag\\
        &=\sum_{n=1}^K\frac{1}{c_n}\bigg[\sum_{k=0}^{\ell_n-1}\Lambda_{t_{n-1}+k\delta}\odot\int_{k\delta}^{(k+1)\delta}G^{(n)}(x_n-x)P^{(n)}H^{(n)}(x)\mathrm{d}x\notag\\
        &\hspace{1cm}+\Lambda_{t_{n-1}+\ell_n\delta}\odot\int_{\ell_n\delta}^{\ell_n\delta+\Delta_n}G^{(n)}(x_n-x)P^{(n)}H^{(n)}(x)\mathrm{d}x\bigg]_{ii}\notag\\
        &=\sum_{n=1}^K\frac{1}{c_n}\bigg[\sum_{k=0}^{\ell_n-1}\Lambda_{t_{n-1}+k\delta}\odot\int_{0}^{\delta}G^{(n)}(x_n-(x+k\delta))P^{(n)}H^{(n)}(x+k\delta)\mathrm{d}x\notag\\
        &\hspace{1cm}+\Lambda_{t_{n-1}+\ell_n\delta}\odot\int_{0}^{\Delta_n}G^{(n)}(x_n-(x+\ell_n\delta))P^{(n)}H^{(n)}(x+\ell_n\delta)\mathrm{d}x\bigg]_{ii}\notag\\
        &=\sum_{n=1}^K\frac{1}{c_n}\bigg[\sum_{k=0}^{\ell_n-1}\Lambda_{t_{n-1}+k\delta}\odot\int_{0}^{\delta}e^{(Q-\Lambda_{t_{n-1}+k\delta})(\delta-x)}\Omega^{(n)}_ke^{(Q-\Lambda_{t_{n-1}+k\delta})x}\mathrm{d}x\notag\\
        &\hspace{1cm}+\Lambda_{t_{n-1}+\ell_n\delta}\odot\int_{0}^{\Delta_n}e^{(Q-\Lambda_{t_{n-1}+\ell_n\delta})(\Delta_n-x)}P^{(n)}\Xi^{(n)}_{\ell_n}e^{(Q-\Lambda_{t_{n-1}+\ell_n\delta})\Delta_n}\mathrm{d}x\bigg]_{ii}.\notag
    \end{align}
    We end up computing integrals of matrix exponentials. Following \cite{van1978computing}, as recommended in \cite{roberts2006ryde}, we get
    \begin{equation}
        \int_{0}^{\delta}e^{(Q-\Lambda_{t_{n-1}+k\delta})(\delta-x)}\Omega^{(n)}_ke^{(Q-\Lambda_{t_{n-1}+k\delta})x}\mathrm{d}x=\left[e^{C^{(n)}_k\delta}\right]^{M\boxtimes M}\notag,
    \end{equation}
    and
    \begin{equation}
        \int_{0}^{\Delta_n}e^{(Q-\Lambda_{t_{n-1}+\ell_n\delta})(\Delta_n-x)}P^{(n)}\Xi^{(n)}_{\ell_n}e^{(Q-\Lambda_{t_{n-1}+\ell_n\delta})\Delta_n}\mathrm{d}x=\left[e^{D^{(n)}\Delta_n}\right]^{M\boxtimes M}\notag.
    \end{equation}
    Finally, we obtain
    \begin{equation}
        \int_0^T\frac{\alpha_t^i\beta_t^i}{\mathcal{L}}\lambda_i(t)\mathrm{d}t=\sum_{n=1}^K\frac{1}{c_n}\left[\sum_{k=0}^{\ell_n-1}\Lambda_{t_{n-1}+k\delta}\odot\left[e^{C^{(n)}_k\delta}\right]^{M\boxtimes M}+\Lambda_{t_{n-1}+\ell_n\delta}\odot \left[e^{D^{(n)}\Delta_n}\right]^{M\boxtimes M}\right]_{ii}\notag.
    \end{equation}
    In particular, we have the following formula for the integrated transition probability
    \begin{equation}
        \int_0^T\frac{\alpha_t^i\beta_t^j}{\mathcal{L}}\mathrm{d}t=\sum_{n=1}^K\frac{1}{c_n}\left[\sum_{k=0}^{\ell_n-1}\left[e^{C^{(n)}_k\delta}\right]^{M\boxtimes M}+\left[e^{D^{(n)}\Delta_n}\right]^{M\boxtimes M}\right]_{ji}\notag,
    \end{equation}
    which completes the proof.
\end{proof}

