\title{Loss of integrability in a system with two-photon interactions}
\author{Fabrizio Ram\'irez}
\affiliation{Instituto de Ciencias Nucleares, Universidad Nacional Aut\'onoma de M\'exico, Apdo. Postal 70-543, C.P. 04510 Mexico City, Mexico}
\author{David Villase\~nor}
