\section{Mean-field analysis with coherent states}
\label{app:MeanField}


A mean-field approximation is achieved by taking a trial state and computing the expectation value of an algebraic quantum Hamiltonian. The two-photon Dicke model is an algebraic Hamiltonian composed of two Hilbert subspaces, one bosonic $\mathcal{H}_{\text{B}}$ with infinite dimension, and one atomic $\mathcal{H}_{\text{A}}$ with finite dimension $2j+1$. Therefore, we use Glauber and Bloch coherent states of minimum uncertainty~\cite{Arecchi1972,Zhang1990}, given in Eq.~\eqref{eq:GlauberState} and Eq.~\eqref{eq:BlochState}, which are related to the bosonic and atomic subspace, respectively. By taking the expectation value of the two-photon Dicke Hamiltonian in Eq.~\eqref{eq:DickeHamiltonian} under tensor product of the last coherent states in Eq.~\eqref{eq:GlauberBlochState}, we get the expression
\begin{align}
    \label{eq:ClassicalHamiltonian}
    \langle\mathbf{x}|\hat{H}_{\text{D}}|\mathbf{x}\rangle
    = & \omega|\alpha|^{2}-j\omega_{0}\frac{1-|\beta|^{2}}{1+|\beta|^{2}} \\
    & + \gamma\left[(\alpha^{\ast})^{2} + \alpha^{2}\right]\frac{\beta^{\ast} + \beta}{1+|\beta|^{2}} . \nonumber
\end{align}

Each coherent state parameter, $(\alpha,\beta)\in\mathbb{C}$, can be linked to a pair of canonical position and momentum variables in phase space~\cite{Villasenor2024ARXIV}
\begin{align}
    \alpha & = \sqrt{\frac{j}{2}}(q+ip), \label{eq:qp1}\\
    \beta & = \frac{Q+iP}{\sqrt{4-Q^{2}-P^{2}}},
    \label{eq:qp2}
\end{align}
such that, $(q,p)$ identify the bosonic classical coordinates and $(Q,P)$ the atomic classical coordinates. By substituting the coherent state parameters $\alpha$ and $\beta$ in Eq.~\eqref{eq:ClassicalHamiltonian} and scaling the expectation value by the system size $j$, we get the classical two-photon Dicke Hamiltonian given in Eq.~\eqref{eq:ClassicalDickeHamiltonian}.


\section{Bogoliubov transformation}
\label{app:Bogoliubov}


The Hamiltonian in Eq.~\eqref{eq:DickeHamiltonian} becomes integrable when setting $\omega_0=0$,
\begin{equation}
    \label{eq:Htilde}
    \hat{H}'_{\text{D}} = \omega \hat{a}^{\dagger}\hat{a} + \frac{2\gamma}{\mathcal{N}} \left( \hat{a}^{\dagger 2} + \hat{a}^{2} \right) \hat{J}_{x},
\end{equation}
where we used the expression $\hat{J}_{x}=(\hat{J}_{+}+\hat{J}_{-})/2$.

The last Hamiltonian commutes with the operator $\hat{J}_{x}$, $[\hat{H}'_{\text{D}},\hat{J}_x]=0$. Both operators share a set of eigenstates $|n; j, m_x\rangle = |n\rangle\otimes|j,m_x\rangle$, such that, $\hat{a}^{\dagger}\hat{a}|n; j,m_x\rangle = n|n; j,m_x\rangle$ and $\hat{J}_x|n; j,m_x\rangle = m_x|n; j,m_x\rangle$. Using the basis $|j,m_x\rangle$, we obtain $2j+1$ Hamiltonians for each eigenvalue $m_x$,
\begin{align}
    \label{eq:Htildemx}
    \hat{H}'_{m_x} = & \langle j, m_x | \hat{H}_{\text{D}} | j, m_x \rangle \\
    = & \omega \hat{a}^{\dagger}\hat{a} + \frac{2\gamma}{\mathcal{N}} \left( \hat{a}^{\dagger 2} + \hat{a}^{2} \right) m_x , \nonumber
\end{align}
which can be diagonalized employing a Bogoliubov transformation of the form~\cite{Emary2002}
\begin{align}
    \label{eq:aadaggertrans}
    \hat{a} = & \frac{\hat{c} + \sigma \hat{c}^\dagger}{\sqrt{1 - |\sigma|^2}} , \\
    \hat{a}^\dagger = & \frac{\hat{c}^\dagger + \sigma^{\ast}
    \hat{c}}{\sqrt{1 - |\sigma|^2}},
\end{align}
where $\sigma \in \mathbb{C}$ and the operators $\hat{c}$ and $\hat{c}^\dagger$ satisfy the Heisenberg-Weyl algebra with $[\hat{c},\hat{c}^{\dagger}]=\hat{\mathbb{I}}$.

The new Hamiltonian is given by
\begin{equation}
    \label{eq:Htildemx_transf}
    \hat{H}'_{m_x} = A_{m_x} \hat{c}^{\dagger} \hat{c} + B_{m_x} \hat{c}^{\dagger2} +  B_{m_x}^{\ast} \hat{c}^2 + C_{m_x} ,
\end{equation}
where
\begin{align}
    A_{m_x} = & \frac{1}{1 - |\sigma|^2}\left[ \omega\left(1 + |\sigma|^2\right) + \frac{4\gamma m_x}{\mathcal{N}}(\sigma^{\ast}+\sigma) \right] , \\
    B_{m_x} = & \frac{1}{1 - |\sigma|^2}\left[ \omega\sigma + \frac{2\gamma m_x}{\mathcal{N}}\left(1 + \sigma^2\right) \right] , \\
    C_{m_x} = & \frac{1}{1 - |\sigma|^2}\left[ \omega|\sigma|^2 + \frac{2\gamma m_x}{\mathcal{N}}(\sigma + \sigma^{\ast})\right] ,
\end{align}
and it becomes diagonal for the condition 
\begin{equation}
    \label{eq:sigmapm}
   \sigma_{m_x} = \sigma_{m_x}^{\ast} =\frac{-1 \pm \sqrt{1 - 4 \lambda_{m_x}^2}}{2 \lambda_{m_x}}, 
\end{equation}
where $\lambda_{m_x} \equiv 2\gamma m_x / (\omega\mathcal{N})$.

The spectral collapse occurs at $\gamma_{\text{sc}} = \omega / 2$. In this work we work in the region $\gamma < \gamma_{\text{sc}}$, where $\sigma$ is a real quantity. In addition, we study the spectrum characterized by increasing energy values. The last condition is satisfied by selecting the positive root of Eq.~\eqref{eq:sigmapm}, giving a positive coefficient of the operator $\hat{c}^\dagger\hat{c}$. Taking the last considerations, we arrive at the Hamiltonian presented in Eq.~\eqref{eq:Hanalytic}.


\section{Numerical diagonalization and convergence}
\label{app:Diagonalization}


The diagonalization of the two-photon Dicke Hamiltonian in Eq.~\eqref{eq:DickeHamiltonian} is performed using a basis formed by the tensor product of Fock states, $|n\rangle$, for the bosonic subspace and angular-momentum states, $|j,m_{z}\rangle$, for the atomic subspace
\begin{equation}
    \label{eq:FockBasis}
    |n;j,m_z\rangle \equiv |n\rangle\otimes|j,m_z\rangle ,
\end{equation}
where $n=0,1,\dots,\infty$ and $m_{z}=-j,-j+1,\ldots,j-1,j$. The matrix elements of the Hamiltonian in this basis are given by
\begin{gather}
    \langle n';j,m'_{z}|\hat{H}_{\text{D}}|n;j,m_{z}\rangle = \left(\omega n + \omega_{0} m_{z}\right)\delta_{n',n}\delta_{m'_{z},m_{z}} \\
    + \frac{\gamma}{\mathcal{N}}\left( A_{n}\delta_{n',n+2} + A_{n-2}\delta_{n',n-2} \right)B_{m'_{z},m_{z}} , \nonumber
\end{gather}
where $A_{n} = \sqrt{(n+1)(n+2)}$, 
\begin{equation}
    B_{m'_{z},m_{z}} = C_{m_{z}}^{+}\delta_{m'_{z},m_{z}+1} + C_{m_{z}}^{-}\delta_{m'_{z},m_{z}-1},
\end{equation}
and $C_{m_{z}}^{\pm} = \sqrt{j(j+1)-m_{z}(m_{z}\pm1)}$.

For numerical calculations, the Hilbert space is truncated to a finite dimension by imposing a maximum photon number $n_{\max}$. Such truncation can lead to spurious numerical solutions, necessitating a convergence criterion. Here, we define a convergence criterion for the eigenstates of the two-photon Dicke Hamiltonian analogous to that used for the single-photon Dicke Hamiltonian~\cite{Bastarrachea2014PSa,Bastarrachea2014PSb}.

The eigenstates of the two-photon Dicke Hamiltonian satisfy the eigenvalue equation $\hat{H}_{\text{D}}|E_{k}\rangle = E_{k}|E_{k}\rangle$, and can be expanded in the diagonalization basis as
\begin{equation}
    \label{eq:EigenstatesFock}
    |E_{k}\rangle = \sum_{n,m_{z}}c_{n,m_{z}}^{k}|n;j,m_{z}\rangle,
\end{equation}
where $c_{n,m_{z}}^{k}=\langle n;j,m_{z}|E_{k}\rangle$. We define the probability distribution of finding $n$ photons in the $k$-th eigenstate
\begin{equation}
    P_{n}^{k} = \sum_{m_{z}}|c_{n,m_{z}}^{k}|^{2},
\end{equation}
where $n=0,1,\ldots,n_{\max}$. By evaluating this distribution at the truncation values $n_{\max}$ and $n_{max}-1$, we impose the condition
\begin{equation}
    P_{n_{\max}}^{k} + P_{n_{\max}-1}^{k} \leq \delta,
\end{equation}
where $\delta$ is a small tolerance parameter. When this condition is satisfied, it guarantees that the wavefunction of the $k$-th. eigenstate is converged within the truncated Hilbert space and will remain unchanged upon further increasing $n_{\max}$. This criterion is checked for each eigenstate, ordered by ascending energy. The lowest energy eigenstate that violates this inequality determines the set of converged eigenstates (eigenenergies).


