The following properties, sometimes called the Eilenberg--Steenrod axioms, are useful:
\begin{enumerate}[label=(\alph*)]
\item\label{it:dim}\textit{Dimension axiom}: $H_k(\{p\})= \delta_{k,0}\Z$, where $\delta_{i,j}$ is the Kronecker delta;
\item\label{it:*}  \textit{Functoriality and naturality:} $(\id_X)_*=\id$,  $(g\circ f)_* = g_* \circ f_*$ and $\p\circ f_* = (f|_A)_*\circ \p$;
\item\label{it:inv} \textit{Homotopy invariance}: if $f_0,f_1\colon (X,A)\to (Y,B)$ are homotopic, i.e.\ if there is $h\colon [0,1]\times (X,A)\to (Y,B)$ such that $h(0,\cdot) = f_0$ and $h(1,\cdot) =f_1$, then $(f_0)_*=(f_1)_*$;
\item\label{it:excision} \textit{Excision}: if $W\subset X$ is open and $\overline W \subseteq \tp{int}(A)$ then the inclusion $i\colon (X\setminus W, A\setminus W) \to (X,A)$ induces an isomorphism $i_*$;
\item\label{it:exact} \textit{Exactness}: if $ B \subseteq A\subseteq X$, the inclusions $i\colon (A,B)\to (X,B)$ and $j\colon (X,B)\to (X,A)$ induce an \emph{exact} sequence:
$$\dots \stackrel{}{\longrightarrow} H_{k+1}(X,A) \stackrel{\p}{\longrightarrow} H_k(A,B)  \stackrel{i_*}{\longrightarrow} H_k(X,B)  \stackrel{j_*}{\longrightarrow} H_k(X,A) \stackrel{}{\longrightarrow} \dots  $$
Recall that a sequence is \emph{exact} if the image of any map of the sequence equals the kernel of the next map in the sequence.
\end{enumerate}	
%		Concretely, the above objects can be constructed using \textit{singular homology}, see e.g.\  \cite{Hatcher2002}.

%	,
% following \cite{Hatcher2002}. Given a space $X$, let $C_k(X)$ be the group of \textit{$k$-chains} in $X$, i.e.\ the group of finite formal sums $\sum_i n_i \sigma_i$, where each $\sigma_i\colon \Delta^k \to X$ is a continuous map from the $k$-simplex. There is a natural \textit{boundary operator}	 $\p\colon C_k(X)\to C_{k-1}(X)$ which sends each $k$-simplex to its $(k-1)$-dimensional boundary and satisfies $\p\circ \p = 0$.

	Given a subset $Y\subseteq X$, we say that $Y$ is a \textit{deformation retract} of $X$ if there is a homotopy $h\in C([0,1]\times X,X)$ such that $h(0,\cdot)= \id_X$, $h(1,X)\subseteq Y$ and $h(t,\cdot)|_{Y} = \id|_Y$ for any $t\in [0,1]$. The next lemma is then easy to deduce from the above properties:
%	 following simple lemma:

	\begin{lemma}\label{lemma:ret}
	Suppose that $A'\subseteq A\subseteq X'\subseteq X$.
	\begin{enumerate}
	\item\label{it:def1} If $X'$ is a deformation retract of $X$, then $H_k(X,A) \cong H_k(X',A)$ for all $k$;
	\item\label{it:def2} If  $A'$ is a deformation retract of $A$, then $H_k(X,A) \cong H_k(X,A')$ for all $k$.
	\end{enumerate}
	\end{lemma}

		\begin{proof}
	We first prove \ref{it:def1}, so let $h$ be the corresponding homotopy and $i\colon X'\to X$ be the inclusion map.\ Let $r \equiv h(1,\cdot)
\colon (X,A)\to (X,A)$ and let $\tilde r\colon (X,A) \to (X',A)$ simply be defined by $\tilde r(x) = r(x)$ for all $x \in X$.\ Then we have $\tilde r \circ i = \id_{X'}$, and hence by property \ref{it:*} that $\tilde r_* \circ i_* = \id$. Since $i \circ \tilde r = r$, by properties \ref{it:*} and \ref{it:inv} we have $i_*\circ \tilde r_* = r_* = \id$. This yields the fact that $i_*: H_k(X',A) \to H_k(X,A)$ is a isomorphism of groups for every $k$.
	%With $r\equiv h(1,\cdot)$ and $i\colon (X',A)\to (X,A)$ the inclusion, using properties \ref{it:*} and \ref{it:inv} we see that $(i\circ r)_* = (\id_X)_* = \id$ and $(r\circ i)_* = (\id_Y)_* = \id$. 
	Then \ref{it:def2} follows from property \ref{it:exact}, since by \ref{it:def1} we have $H_k(A,A')\cong H_k(A',A')=\{0\}$.
	\end{proof}


