	\section{Local Morse theory and critical groups}
\label{sec:morse}

In this section we establish some Morse-theoretic results for functions with isolated critical points. We are interested in the \textit{local setting} (the function is defined only on an open subset $\Omega\subset \R^n$) in \textit{low regularity} (the function is only $C^1$), and so we present complete proofs for the sake of readability, but we refer the reader to the monographs \cite{Chang1993,Mawhin1989,Milnor1963} for analogous results.

The fundamental idea of Morse theory is that the topology of the sublevel sets of a function can only change when one crosses a critical value, as otherwise the sublevel sets can be deformed into each other using a (pseudo)-gradient flow.  As one crosses a critical value, the change in topology can be captured by the \textit{critical groups}:

%classical idea of deforming sublevel sets of a function using (pseudo)-gradient flows. We want to work in a local, low-regularity setting

	\begin{definition}[Critical group]\label{def:crit}
	Let $u\in C^1(\Omega)$, let $x_0\in \Omega$ and write $c\equiv u(x_0)$. Given  $U\subseteq \Omega$ a neighborhood\footnote{That is, $U$ is a set such that there is $\delta>0$ with $B_\delta(x_0)\subset U$.} of $x_0$ and $k\in \{0,\dots,n\}$,  we set
	$$C_{k}(u,x_0)\equiv H_k(\{u\leq c\} \cap U, \{u\leq c\}\cap U\setminus \{x_0\} ).$$
	\end{definition}

%	One of the main goals of this section is to show that the groups $C_{k,\e,U}$ are independent of $\e$ small and of $U$. 
One can readily check that the definition of critical group does not depend on $U$: if $V$ is another neighborhood of $x_0$ then, by the excision property \ref{it:excision} applied with $X=\{u\leq c\}\cap U$, $A=X\setminus \{x_0\}$ and $W=X\setminus V$, one finds an isomorphism between the critical groups computed with respect to $U$ or to $U\cap V$.	In order to simplify the notation, we now suppose $\Omega=\mb B^n$ and that $u\in C^1(\mb B^n)$ satisfies
\begin{equation}
\label{eq:assum}
u(0)=0, \qquad \{x\in \mb B^n: \D u(x)=0\}=\{0\}.
\end{equation}	
Since $u$ is only $C^1$, we need the following:

\begin{lemma}[Pseudo-gradient vector field]\label{lemma:pseudo}
Given $u\in C^1(\mb B^n)$ satisfying \eqref{eq:assum}, there is a vector field $X\in C^{\infty}(\mb B^n\setminus \{0\}, \R^n)$ such that, in $\mb B^n\setminus \{0\}$, we have
\begin{equation}
\label{eq:pgvf}
|X|\leq 2 |\D u|\quad  \text{ and }\quad |\D u|^2 \leq \langle \D u, X\rangle.
\end{equation}
\end{lemma}

\begin{proof}
Since $\D u(x)\neq 0$ if $x\in \mb B^n\setminus \{0\}$, for any such $x$ one can find a vector $w_x\in \R^n$ such that the inequalities in \eqref{eq:pgvf} hold at $x$ with $X(x)=w_x$; by continuity of $\D u$, they must in fact hold in a neighborhood $W_x$ of $x$.  Taking a locally finite cover $\{W_{x_i}\}_{i\in I}$ of $\mb B^n\setminus \{0\}$ with associated partition of unity $\{\varphi_i\}_{i\in I}$, we set $X\equiv \sum_{i\in I} \varphi_{i} w_{x_i}. $
\end{proof}

%	\begin{lemma}
%	at an isolated critical point, 
%	$$C_k(f,x) \cong H_k\left(\{f\leq c\}\cap W, (\{f\leq c\}\setminus \{x\})\cap W\right)$$
%	\end{lemma}

In particular, we can define a pseudo-gradient flow $\phi_t \equiv \phi(t,\cdot)\colon \mb B^n\backslash \{0\}\to \R^n$ as the unique solution of the Cauchy problem
\begin{equation}
\label{eq:flow}
\begin{cases}
\frac{\d}{\d t} \phi_t(x) = - \frac{X(\phi_t(x))}{|X(\phi_t(x))|^2},\\
\phi_0(x) =x,
\end{cases}
\end{equation}
which is defined in a maximal interval of existence $t\in \left]t_-(x),t_+(x)\right[$. The choice $-X/|X|^2$ is convenient as it ensures that the flow reaches every point, including the origin, in finite time. Before giving the proof of the main Lemmas \ref{lemma:ngbd}-\ref{lemma:def}, it is better to record a few facts about (pseudo)-gradient flows of functions fulfilling \eqref{eq:assum}. This will be done in the next Subsection \ref{sub:GTR}, while the proof of the main Lemmas is the content of Subsection \ref{sub:male}. These will be instrumental to get the crucial properties of the critical groups of Subsection \ref{sub:crit}.

\subsection{Some general results}\label{sub:GTR}

The next two lemmas provide simple but important estimates.

 \begin{lemma}\label{lemma:tec1}
 	Let $u\in C^1(\mb B^n)$ satisfy \eqref{eq:assum}. Then, for any $x \in \mb B^n$ and any $0 < t \le s < t_+(x)$, we have:
 	\begin{equation}
 		\label{eq:cauchyuphi}
 		u(\phi_{s}(x)) - u(\phi_{t}(x))\leq - \frac{s-t}{4}.
 	\end{equation}
 	In particular, $t_+(x) <+ \infty$ for all $x \neq 0$.
 \end{lemma}
 \begin{proof}
 To see \eqref{eq:cauchyuphi}, we write
 \[
 u(\phi_{s}(x)) - u(\phi_{t}(x)) =  \int_{t}^{s} \frac{\d}{\d z} u(\phi_z(x)) \d z\overset{\eqref{eq:flow}}{=} -\int_{t}^{s} \frac{ \langle \D u (\phi_z(x)), X( \phi_z(x))\rangle}{|X(\phi_z(x))|^2} \d z\overset{\eqref{eq:pgvf}}{\leq} - \frac{s-t}{4}.
 \]
 Due to the boundedness of $u$, we infer $t_+(x) <+ \infty$ for all $x \neq 0$.
 \end{proof}

 %Some of the computations needed in the previous Lemma will be useful for the forthcoming Lemma \ref{lemma:def} as well, hence we record them in a separate:
	\begin{lemma}\label{lemma:tec2}
		Let $u\in C^1(\mb B^n)$ satisfy \eqref{eq:assum} and let $K$ be a compact set such that $0 \notin K$.
		If we have $\phi_t(x) \in K$ for all $t_1\le t \le t_2$, then 
		\begin{equation}
			\label{eq:cauchygen}
			|\phi_{t_2}(x)- \phi_{t_1}(x)| \leq \frac{t_2-t_1}{\min_{K}|Du|}.
		\end{equation}
	\end{lemma}
	\begin{proof}
We get \eqref{eq:cauchygen} by estimating
		\[
		|\phi_{t_2}(x)- \phi_{t_1}(x)|= \left\lvert \int_{t_2}^{t_1}  \frac{\d}{\d s} \phi_s(x) \d s\right\rvert \leq \int_{t_1}^{t_2} \frac{\d s}{|X(\phi_s(x))|} \leq \frac{t_2-t_1}{\min_{K}|Du|}
		\]
		using \eqref{eq:pgvf}--\eqref{eq:flow}.
	\end{proof}

	\begin{corollary}\label{cor:tec2}
			Let $0 < r < 1$ and set
		\begin{equation}\label{eq:delta}
			\delta(r)\equiv \min_{\overline{B_r(0)}\setminus B_{r/2}(0)} |\D u|\overset{\eqref{eq:assum}}{>}0.
		\end{equation} 
		For any $x \in \overline{B_{\frac{r}{2}}}$, if $|\phi_t(x)|>r$ for some $t\in \left]0,t_+(x)\right[$, then there exist $0 < t_1 < t_2 < t$ fulfilling 
		\begin{equation}\label{eq:conti}
			|\phi(t_1,x)|=\tfrac r 2,\quad  |\phi(t_2,x)| = r, \quad \phi([t_1,t_2],x)\subseteq \{\tfrac r 2 \leq |x|\leq r\},
		\end{equation}
		\begin{equation}
			\label{eq:cauchyphi}
			\frac r 2 \leq |\phi_{t_1}(x)- \phi_{t_2}(x)| \leq \frac{t_2-t_1}{\delta}.
		\end{equation}
	\end{corollary}

	\begin{proof}
Note that	\eqref{eq:conti} follows by continuity of the flow and \eqref{eq:cauchyphi} follows from \eqref{eq:cauchygen}-\eqref{eq:conti}.
%		and intervals   and just as in Lemma \ref{lemma:ngbd}, we can find intervals such that $t_j,t_j'\nearrow t_a(x)$ and
%		$$|\phi(t_j,x)| = \tfrac r 2,\quad  |\phi(t_j',x)| = r,\quad  \phi([t_j,t_j'], x) \subseteq \{ \tfrac r 2 \leq |x|\leq r\}$$
%		for some $r>0$. Thus, arguing exactly as in \eqref{eq:cauchyphi} and with $\delta = \inf_{B_r(0)\setminus B_{r/2}(0)} |\D u|$, we see that $\tfrac r 2 \leq \delta^{-1}(t_j'-t_j)\to 0$ as $j\to \infty$, a contradiction.
	\end{proof}

The next lemma provides an important continuity statement:\	if the trajectory starting from a point $x_0$ gets arbitrarily close to the origin, then trajectories starting at points close to $x_0$ will also get arbitrarily close to the origin.

	\begin{lemma}\label{lemma:contragen}
Assume $\{x_j\}_j \subset \mb B^n\setminus \{0\}$ is a sequence converging to a point $x_0 \in \mb B^n$ such that either $x_0=0$ or there exists $T > 0$ such that $\inf_{t \in [0,T[ }|\phi_t(x_0)|=0$. Then, if $x_0\neq 0$, we have $T = t_+(x_0)$. Setting also $T = 0$ in the case $x_0 = 0$, if $0\le T_j < t_+(x_j)$ and $T_j\to T$, we have
		\begin{equation}\label{eq:conv}
			\lim_{j \to \infty}\phi_{T_j}(x_j) = 0.
		\end{equation}
	\end{lemma}
\begin{proof}
Suppose by contradiction that \eqref{eq:conv} fails. We would then find $\e > 0$ such that
	\begin{equation}\label{eq:contrale}
		|\phi_{T_j}(x_j)|\ge \eps > 0, \quad \forall j.
	\end{equation}
	Above and in what follows we do not relabel subsequences.\ If $x_0 \neq 0$ then clearly $T = t_+(x_0)$ and there exists a sequence of times $r_j \to T$ such that
	\[
	|\phi_{r_j}(x_0)| \le \frac{\eps}{4}, \quad \forall j.
	\]
Using the lower semicontinuity of $t_+$, we see that $\lim_{j\to \infty}\phi_{t}(x_j) = \phi_t(x_0)$ for each $t < T = t_+(x_0) \le \liminf_jt_+(x_j)$. Thus, through a diagonal argument we can find an increasing sequence $s_j \to T$ with $s_j < T_j$ for all $j$ such that
	\begin{equation}\label{eq:contrafin5}
		|\phi_{s_j}(x_j)| < \frac{\eps}{2}, \quad \forall j.
	\end{equation}
	If $x_0 = 0$, simply set $s_j = 0$, and notice that \eqref{eq:contrafin5} holds due to $\phi_0(x_j) = x_j \to x_0 = 0$.\ In either case, we apply Corollary \ref{cor:tec2} to find sequences $[t_j,t_j']\subset [s_j,T_j]$ such that $t_j,t_j'\to T$ and
	\[
	|\phi(t_j,x_j)|= \frac\eps 2, \quad |\phi(t_j',x_j)| = \eps , \quad \phi([t_j,t_j'],x_j) \subseteq \{\tfrac \eps 2 \leq |x|\leq \eps\}.
	\]
	By \eqref{eq:cauchyphi} we then get a $\delta > 0$ such that, for all $j \in \N$,
	\begin{equation}\label{eq:contrfin6}
		\frac{\e}{2} \le |\phi_{t_j'}(x_j)-\phi_{t_j}(x_j)| \le \frac{|t_j - t_j'|}{\delta}.
	\end{equation}
	This is a contradiction for large $j$, as $t_j,t_j' \to T$ and $T < +\infty$ in both cases, see Lemma \ref{lemma:tec1}.
%	 Then we would find $r >0 $ and sequences $\{s_j\}, \{s_j'\}$ with $s_j < s_j' < s_{j + 1}$ for all $j$, $\lim_js_j = \lim_j s_j' = T$, such that
%	\[
%	|\phi_{s_j}(x)| <\frac{r}{2} \text{ and } |\phi_{s'_j}(x)| > r.
%	\]
