\end{proof}

\subsection{Main lemmas}\label{sub:male}

To use $\phi_t$ to deform the sublevel sets of $u$, we first need a suitable neighborhood of the origin:

		\begin{lemma}[Construction of $W$]\label{lemma:ngbd}
	Let $u\in C^1(\mb B^n)$ satisfy \eqref{eq:assum}.
	There is $\e>0$ and a neighborhood $W\subset  \mb B^n$ of $0$ such that:
	\begin{enumerate}
	\item\label{it:posinv}  $W$ is a neighborhood of 0, closed in $\mb B^n$, such that $W\setminus\{0\}$ is positively invariant\footnote{The need to exclude 0 in this definition stems from the technical issue that the vector field whose flow we are considering is not defined at that point.} for $\{\phi_t\}$, i.e.\ if $x\in W\setminus\{0\}$ and $t\in [0,t_+(x)[$ then also $\phi_t(x) \in W\setminus\{0\}$;
	\item\label{it:complete} $\{-\eps \le u \leq \e\}\cap W\subseteq\tfrac 1 2 \overline{\mb B^n}$ and so in particular this set is compact.
	\end{enumerate}
	\end{lemma}



\begin{proof}
%As some of the calculations will be useful later on we take an arbitrary $r\in \left]0,1\right[$, but the desired $\e,W$ follow simply by choosing $r=\tfrac 1 2$. 
Consider $\delta= \delta(\tfrac 1 2)>0$, defined as in \eqref{eq:delta}. Take $A\equiv \overline{ \frac{1}{4}\mathbb{B}^n}\cap \{u\leq \frac{\delta }{32}\}$, and let $W$ be the closure in $\mb B^n$ of the set
$$Y\equiv \left\{\phi_t(x): x \in A\setminus\{0\}, t\in [0,t_+(x)[\right\}.$$
Since $W\setminus \{0\}$ is the closure of $Y$ in $\mb B^n\setminus \{0\}$, and since the (relative) closure of a positively invariant set is also positively invariant, clearly \ref{it:posinv} holds. We now prove that \ref{it:complete} holds with $\e=\tfrac{\delta }{128}$. In fact, it suffices to show that 
\[
\{-2\e<u<2\e\}\cap Y \subseteq \frac{1}{2} \overline{\mathbb{B}^n}.
\]
By contradiction, let $y \in \{-2\e<u<2\e\}\cap Y$ with $|y|> 1/2$. By definition of $Y$ there would then be $x\in A\setminus\{0\}$ with $|x| \le 1/4$ and $t \in \left]0,t_+(x)\right[$ such that $y =\phi_t(x) \notin {\frac{1}{2}\overline{\mathbb{B}^n}}$. Thus Corollary \ref{cor:tec2} yields $[t_1,t_2]\subset \left[0,t\right[$ fulfilling \eqref{eq:conti}-\eqref{eq:cauchyphi}. Using that $x \in A$ so that $u(x) \le \tfrac {\delta}{32}$, we deduce
$$-2\e < u(y) = u(\phi_t(x)) \le u(\phi_{t_2}(x)) \overset{\eqref{eq:cauchyuphi},\eqref{eq:cauchyphi}}{\leq} u(\phi_{t_1}(x)) - \frac{\delta }{16} \leq u(x) - \frac{\delta}{16} \leq - \frac{\delta }{32} = - 4 \e$$
which gives the desired contradiction.
\end{proof}	

The next lemma, which is the key technical tool of this section, gives a precise statement to the effect that the topology of sublevel sets can only change while crossing a critical value. For simplicity let us introduce the notation $W^b\equiv \{u\leq b\} \cap W$ and $K_b \equiv \{0\}\cap \{u=b\}$. Note that, by \eqref{eq:assum}, $K_b$ is non-empty only if $b=0$.

\begin{lemma}[Deformation lemma]\label{lemma:def}
Let $u\in C^1(\mb B^n)$ be as in \eqref{eq:assum}.  We assume that:
\begin{enumerate}
\item\label{it:propW} $W\subset \mb B^n$ is a closed neighborhood of 0 for which $W\setminus \{0\}$ is positively invariant for $\{\phi_t\}$;
\item\label{it:nocp} $\{a\leq u \leq b\}\cap W$ is compact and $0\not \in \{a<u<b\}$, where $a<b$.
\end{enumerate}
% Suppose also that $\{a\leq u \leq b\}\cap W$ is compact and does not contain 0. 
 Then $W^a$ is a deformation retract of $W^b \setminus K_b$.
\end{lemma}		

\begin{proof}
We split the proof into several steps.
\smallskip \\ 
\textbf{Step 1.} \textit{Let $x\in (\{a< u \leq b\} \cap W) \setminus K_b$. Then there is a unique arrival time $t_a(x)\in [0,t_+(x)]$ such that $\lim_{t\nearrow t_a(x)} u(\phi_t(x)) = a$.}
%\textcolor{red}{The fact that $t_+(x)<\infty$ follows from \eqref{eq:cauchyuphi} and the boundedness of $u$.}
%From \eqref{eq:cauchyuphi}, with $t_1=0$ and $t_2=t\in [0,t_+(x)[$ we see that  $u(\phi_t(x)) - u(x)\leq -\tfrac t 4$,
%To see this, we first note that for $t\in [0,t_+(x)[$ we have
%$$u(\phi_t(x)) - u(x) = -\int_0^t \langle \D u (\phi_s(x)), \frac{\d}{\d s} \phi_s(x)\rangle \d s \leq - \frac{t}{2}$$
%and since $u$ is bounded in $\mb B^n$ we must have $t_+(x)<\infty$. 
\newline \indent From \eqref{eq:cauchyuphi} we see that  $t\mapsto u(\phi_t(x))$ is strictly decreasing, and so $\ell\equiv \lim_{t\nearrow t_+(x)} u(\phi_t(x))$ exists. We only need to show that we cannot have $\ell>a$. % If $\ell<a$  then clearly there is a unique arrival time $t_a(x)<t_+(x)$. On the other hand, we cannot have . 
Hence assume by contradiction that $\ell>a$, so that we could find $a<a'<\ell<b'<b$. Consider $K \equiv W \cap \{a' \leq u \leq b'\}$, which is a compact set not containing $0$ by \ref{it:nocp}. Then, if $t_1$ is such that $u(\phi_{t_1}(x)) \leq b'$, we have  $\phi_t(x) \in K$ for all $t_1 \le t < t_+(x)$. We then deduce from \eqref{eq:cauchygen} that
	% which is  If $0\leq t_1\leq t_2<t_+(x)$ are such that $u(\phi_{t_1}(x)) \leq b'$, then we can use assumption \ref{it:nocp} {\color{red}{}} to repeat the argument leading to \eqref{eq:cauchyphi}, finding that 
\[
|\phi_{s}(x)-\phi_{t}(x)|\leq \frac{s-t}{\min_K|\D u|}, \quad \text{whenever } t_1 \le t \le s <  t_+(x)
\]
Thus, since $t_+(x) < + \infty$ by Lemma \ref{lemma:tec1}, we obtain that $x_0 \equiv \lim_{t\nearrow t_+(x)} \phi_t(x)$ exists and belongs to the compact set $K$. Since $0 \notin K$, the flow can be continued at $x_0$, contradicting the definition of the maximal time of existence $t_+(x)$.
%\textbf{Step 2.} For $x\in (\{a< u \leq b\} \cap W)\setminus \{0\}$ the limit $\lim_{t\to t_a(x)^-} \phi_t(x)$ exists.
\smallskip \\
\textbf{Step 2.} \textit{$\phi_{t_a(x)}(x) \equiv \lim_{t\nearrow t_a(x)} \phi_t(x)$ exists for $x\in (\{a< u \leq b\} \cap W)\setminus K_b$.}

There are two cases to consider: writing $L \equiv \inf_{t\in [0, t_a(x)[} |\phi_t(x)|$, either $L>0$ or $L=0$. In the former case we set $K \equiv (\{a\leq u\leq b\}\cap W)\setminus B_L(0)$, which is a compact set not containing $0$ by \eqref{eq:assum}-\ref{it:nocp}, and use \eqref{eq:cauchygen} to find that for all  $0\leq t_1\leq t_2<t_a(x)$:
