\begin{proof}
Let $W,\e$ be as in Lemma \ref{lemma:ngbd}, applied with $u=u_1$, and take $r>0$ so that 
\begin{equation}
\label{eq:chooser}
B_r(0)\subseteq \{-\tfrac \e 2\leq u \leq \tfrac \e 2\}\cap W.
\end{equation}
Take a cutoff $\eta\in C^\infty_c(B_r(0))$  with $0\leq \eta \leq 1$, $\eta=1$ in $B_{r/2}(0)$ and $|\D \eta|\leq Cr^{-1}$, for a dimensional constant $C$, and set 
$$\widetilde u_2 \equiv u_1 + \eta (u_2-u_1),$$
thus $\widetilde u_2= u_1$ outside $B_r(0)$. Since $|\widetilde u_2 - u_1| \leq \gamma$, if we choose $\gamma < \frac \e 2$ then by \eqref{eq:chooser} we have 
\begin{equation}
\label{eq:samesublevelsets}
\{u_1\leq \pm \e\}=\{\widetilde u_2\leq\pm \e\}
\end{equation}
and so $\{-\e \leq \widetilde u_2 \leq \e\}\cap W = \{-\e \leq u_1 \leq \e\}\cap W$ is a compact set. 
As usual let us take $0<\delta \equiv \inf_{B_r(0)\setminus B_{r/2}(0)} |\D u|$.  We then estimate, in $B_r(0)\setminus B_{r/2}(0)$, 
%|\tilde u_2 - u_1| = \eta |u_2- u_1|\leq \gamma,
$$
|\D \widetilde u_2| \geq |\D u_1| - \eta |\D u_1 - \D u_2| - |\D \eta| |u_1 -u_2|\geq \delta -(1+Cr^{-1})\gamma \geq  \frac \delta 2,
$$
provided that we also choose $\gamma \leq \frac{\delta}{2(1+Cr^{-1})}$. Since $\widetilde u_2=u_2$ in $B_{r/2}(0)$ and $\widetilde u_2=u_1$ outside $B_r(0)$, we see that $\widetilde u_2$ still satisfies \eqref{eq:assum}. Moreover $W \setminus \{0\}$ is also positively invariant for a suitable pseudo-gradient flow of $\widetilde u_2$ which matches the one of $u_1$ outside $B_r(0)$, since $B_r(0)$ is contained in the interior of $W$. Thus Proposition \ref{prop:nicecritgroup} is applicable also to $\widetilde u_2$, and we infer:
\[
C_k(\widetilde u_2,0) = H_k(W\cap \{\widetilde u_2 \le \eps\},W\cap \{\widetilde u_2 \le -\eps\}) \overset{\eqref{eq:samesublevelsets}}{=} H_k(W\cap \{u_1 \le \eps\},W\cap \{u_1 \le -\eps\}) = C_k(u_1,0).
\]
In addition, since $\widetilde u_2 = u_2$ in $B_{\frac{r}{2}}(0)$, we can exploit the independence of the critical groups on the choice of neighborhood, see Definition \ref{def:crit}, to write
\begin{align*}
C_k(u_2,0) &= H_k(B_\frac{r}{2}(0)\cap \{u_2 \le 0\},B_\frac{r}{2}(0)\cap \{u_2 \le 0\}\setminus \{0\}) \\
&= H_k(B_\frac{r}{2}(0)\cap \{\widetilde u_2 \le 0\},B_\frac{r}{2}(0)\cap \{\widetilde u_2 \le 0\}\setminus \{0\}) = C_k(\widetilde u_2,0),
\end{align*}
and conclude the proof.
\end{proof}

We conclude this section computing the critical groups of some simple but important examples:

\begin{proposition}[Examples of critical groups]\label{prop:ex}
Let $u\in C^1(\mb B^n)$.
\begin{enumerate}
\item\label{it:min} If $x_0$ is an isolated local minimum of $u$ then $C_k(u,x_0) = \delta_{k,0} \Z$.
\item\label{it:nomin} If $x_0$ is an isolated critical point which is not a local minimum of $u$ then $C_0(u,x_0) = \{0\}$.
\item\label{it:quad} For non-singular $A\in \Sym(n)$  and $q_A(x) \equiv \tfrac 1 2\langle Ax,x\rangle$ we have $C_k(q_A,0) = \delta_{k,\ind(A)} \Z$.
\item\label{it:morse} If $x_0$ is an isolated critical point of $u$ and $u$ is twice differentiable at $x_0$ with $A\equiv \D^2 u(x_0)$ non-singular, then $C_k(u,x_0) = \delta_{k,\ind(A)} \Z.$
\end{enumerate}
\end{proposition}

\begin{proof}
Since the calculation of the critical groups is local we can suppose without loss of generality that $x_0=0$ and, by adding a constant to $u$,  that  \eqref{eq:assum} holds. 

Observe that \ref{it:min} is a direct consequence of the dimension axiom \ref{it:dim}. 

For \ref{it:nomin} we can  apply Lemma \ref{lemma:ngbd} to find $\e>0$ and $W$  such that 
$$C_0(u,0)=H_0(W^0, W^{0}\setminus \{0\}) = H_0(W^\e,W^0\setminus \{0\}),$$
where the last equality follows from Lemmas \ref{lemma:ret}\ref{it:def1} and \ref{lemma:def}, since there is a deformation retract $h\colon [0,1]\times W^\e \to W^\e$ which deforms $W^\e$ to $W^0$.  To see that $H_0(W^\e,W^0\setminus \{0\})=\{0\}$ it suffices to note that every point $x\in W^\e$ can be connected to a point in $W^0\setminus \{0\}$ through a path in $W^\e$: indeed, $h(\cdot,x)\colon [0,1]\to W^\eps$ is a path between $x$ and a point in $W^0$; moreover $0\in \tp{int}(W)$, not being a local minimum, can itself be connected to points in $W^0\setminus \{0\}$ through paths in $W^\e$.
%, as there is a To prove that $H_0(W^\e,W^0\setminus \{0\})=0$, 

For \ref{it:quad}, by changing coordinates we can suppose that $A=\tp{diag}(-1,	\dots,-1,1\dots, 1)$ so let us write $\ell= \ind(A)$, $x_-=(x_1,\dots, x_\ell,0\dots, 0)$ and $x_+=(0,\dots, 0, x_{\ell+1},\dots, x_n)$, thus $q_A(x) =\tfrac 1 2 ( |x_+|^2 - |x_-|^2)$. By considering the function $h\colon [0,1]\times \mb B^n\to \mb B^n, (t,x)\mapsto  x_- +(1-t) x_+$ we see that $\{x_+=0\}\cap \mb B^n$ is a deformation retract of $\{q_A\leq 0\}\cap \mb B^n$, and that $\{x_+=0\}\cap \mb B^n\setminus \{0\}$ is a deformation retract of $\{q_A\leq 0\}\cap \mb B^n\setminus \{0\}$. Thus, applying Lemmas \ref{lemma:ret} and \ref{lemma:computationhom}, we have 
\begin{align*}
H_k(\{q_A\leq 0\}\cap \mb B^n, \{q_A\leq 0\}\cap \mb B^n\setminus \{0\})& 
 \cong H_k(\{x_+=0\} \cap \mb B^n, \{x_+=0\}\cap \mb B^n\setminus \{0\}) \\
 & \cong H_k(\mb B^\ell, \mb B^\ell\setminus \{0\})\cong \delta_{k,\ell} \Z;
\end{align*}
note that by the dimension axiom \ref{it:dim} this calculation holds even when $\ell=0$.

For \ref{it:morse}, the assumption that $0$ is a point of twice differentiability of $u$ guarantees that the sequence of rescalings $u_r(x) \equiv u(r x)/r^2$ converges to $q_A$ in $C^1(\mb B^n)$, as $r\to 0$.  Since $u_r$ still satisfy \eqref{eq:assum}, by \ref{it:quad} and Corollary \ref{cor:continuity} we have $C_k(u_r,x_0) = \delta_{k,\ind(A)} \Z$ for all $r$ small enough. But clearly $C_k(u_r, 0)$ is independent of $r$, so the claim follows.
\end{proof}


\section{Proofs of the main results}

Let $\Omega\subset \R^n$ be a connected open set.  We begin with the following:

\begin{theorem}[Constancy of the critical groups]\label{thm:constcritgroup}
Let $u\in C^1(\Omega)$ be such that $\D u$ is locally injective. For $x_0\in \Omega$, let 
$$u_{x_0}(x) \equiv u(x)- u(x_0) - \langle \D u(x_0), x-x_0\rangle.$$ Then
$ C_k(u_{x_0}, x_0) $ is independent of $x_0\in \Omega$. 
\end{theorem}

\begin{proof}
Fix an arbitrary $x_0\in \Omega$; it suffices to show that $y\mapsto C_k(u_y,y)$ is constant in a neighborhood of $x_0$. By changing coordinates we can suppose that $x_0=0$ and that $\D u$ is injective in $4\mb B^n$. Let us write 
$$\widetilde u_y(x) \equiv u_y(y+ x) = u(y+x) - u(y) - \langle \D u(y),x\rangle,$$
so that $\widetilde u_y$ satisfies \eqref{eq:assum} for all $y\in \mb B^n$.
If $\omega$ is a modulus of continuity for $\D u$ in $4\mb B^n$ and $L\equiv \sup_{4\mb B^n} |\D u|$, then it is easy to see that
 $$\sup_{x\in \mb B^n} \left[|\widetilde u_y-\widetilde u_0|(x)+|\D \widetilde u_y- \D \widetilde u_0|(x) \right]\leq 2L|y|  + 3\omega(|y|),$$
 and the right-hand side vanishes as $|y|\to 0$.
Thus there is a small $\delta>0$, depending only on $\widetilde u_0$, such that for $|y|\leq \delta$ we can apply Corollary \ref{cor:continuity} to deduce that $C_k(\widetilde u_y,0)=C_k(\widetilde u_0,0)$.
Since the set $ \{u_y\leq 0\}$ is just a translation of  $\{\widetilde u_y\leq 0\}$,  we infer that the groups $C_k(u_y,y)$ are independent of $y$ whenever $|y|\leq \delta$. 
% Thus we can find $\e>0$ such that 
\end{proof}

As a consequence of Theorem \ref{thm:constcritgroup} and the results of Section \ref{sec:morse}, we obtain a new proof of a theorem due to Ball \cite{Ball1980a}.
It is easy to see that if $\Omega$ is convex and if $u\in C^1(\Omega)$ is a strictly convex function then its gradient is injective. In fact,  the converse is also true, in a strong form: if $\D u$ is locally injective and if $u$ admits a locally supporting hyperplane at a single point (condition \eqref{eq:suphyp} below) then $u$ is strictly convex:

\begin{corollary}[Ball \cite{Ball1980a}]\label{cor:ball}
Assume that $\Omega$ is convex and let $u\in C^1(\Omega)$ be such that $\D u$ is locally injective. If there is $x_0\in \Omega$ such that
\begin{equation}
\label{eq:suphyp}
u_{x_0}\geq 0 \text{ in a neighborhood of } x_0, 
\end{equation}
then $u$ is strictly convex. 
\end{corollary}

\begin{proof}
Since $u_{x_0}(x_0)=0$, \eqref{eq:suphyp} asserts that $x_0$ is a local minimum of $u_{x_0}$, and in fact it must be isolated: if not, there would be $x_j\to x_0$ with $x_j$ local minima of $u_{x_0}$, thus we would have $0 = \D u_{x_0}(x_j) = \D u(x_j) - \D u(x_0)$, contradicting the local injectivity of $\D u$ at $x_0$. Hence, by Proposition \ref{prop:ex}\ref{it:min} we see that $C_{k}(u_{x_0},x_0) = \delta_{k,0}\Z$ and so by Theorem \ref{thm:constcritgroup} we must in fact have $C_k(u_y,y)= \delta_{k,0} \Z$ for all $y\in \Omega$. Since $y$ is always a critical point of $u_y$, by Proposition \ref{prop:ex}\ref{it:nomin} we deduce that every $y\in \Omega$ is a local minimum of $u_y$, which as before must be isolated. This implies that $u$ is strictly convex in $\Omega$: if not, there would be distinct $y_0,y_1\in \Omega$ and $\lambda \in (0,1)$ such that
$$u(y_\lambda ) \geq \lambda u(y_1) + (1-\lambda) u(y_0), \qquad y_\lambda \equiv \lambda y_1 + (1-\lambda) y_0.$$
But then the function $\varphi \colon t\mapsto u(y_t ) - [t u(y_1) + (1-t) u(y_0)]$ attains a maximum at some $t^*\in\left]0,1\right[$ and thus  $\varphi'(t^*)=0$, or equivalently $\langle \D u(y_{t^*}), y_1-y_0\rangle = u(y_1)-u(y_0)$. Hence, for $t\in [0,1]$, 
%the condition $\varphi(t) \leq \varphi(t^*)$ can be rewritten as
%$$u(y_t) + \langle \D u(y_{t^*}), y_t - y_{t^*}\rangle =  u(y_t)+ (t^*-t) [u(y_1) - u(y_2)]  \leq u(y_{t^*}) $$
$$0 \geq\varphi(t) -  \varphi(t^*) = u(y_t) - u(y_{t^*}) - \langle \D u(y_{t^*}), y_t-y_{t^*}\rangle = u_{y_{t^*}}(y_t),$$
while for $t$ close to $t^*$ we also have, by \eqref{eq:suphyp},
\[
u_{y_{t^*}}(y_t)\geq 0.
\]
Combining these two inequalities we infer that $y_{t^*}$ is not an isolated local minimum of $u_{y_{t^*}}$, which leads to a contradiction.
\end{proof}

