\section{Introduction}

\subsection{Motivation}~


Algebroid solutions of complex ODEs have been studied extensively  since the notion of  algebroid functions  was  introduced by H. Poincar\'e. 
 It has been discovered that  many  complex  ODEs have   algebroid solutions. 
For instance,   $4zW'^2-1=0$   is of   an algebroid solution $W=\sqrt{z}.$
What about  an algebroid solution of a complex system of   PDEs?
   Let $F_i(z, W_1,\cdots, W_d)$   $(i=1,\cdots,k)$ be $k$  partial differential polynomials
   in $W_1,\cdots,W_d$ over the field $\mathscr M(\mathbb C^m)$ of 
 all  meromorphic functions on $\mathbb C^m,$ 
   where  $z=(z_1,\cdots,z_m)\in\mathbb C^m.$
    A solution  $(W_1, \cdots, W_n)$ of a given  complex system of PDEs 
	\begin{equation}\label{d0}
	F_i\big(z, W_1,\cdots,W_d\big)=0, \ \ \ \ i=1,\cdots,k
	\end{equation}
is called an algebroid solution, if it is defined by a system of $d$  independent   algebraic  equations 
\begin{equation}\label{d1}
P_i\big(z, W_1,\cdots, W_d\big)=0, \ \ \ \   i=1,\cdots, d
\end{equation}
in $W_1,\cdots, W_d$  over $\mathscr M(\mathbb C^m).$  
 Here, the ``independent" means that  
$$\left|\frac{\partial(P_1,\cdots, P_d)}{\partial(W_1,\cdots,W_d)}\right|\not\equiv0.$$
Note that  a  meromorphic solution of Eq. (\ref{d0}) is always    an algebroid solution. 
To  our knowledge,   a large number of  complex systems of  PDEs, particularly,  lots of complex systems of  algebraic PDEs,     have  
non-meromorphic   algebroid solutions.  

\noindent\textbf{Examples}
\begin{itemize} 
\item The complex system of PDEs 
			   $$\begin{cases}
	\frac{\partial W}{\partial z_1}=\frac{z_2}{2W} \\
	  \frac{\partial W}{\partial z_2}=\frac{z_1}{2W} \\
	    \frac{\partial^2 W}{\partial z_1\partial z_2}=\frac{1}{4W}
	   \end{cases}$$
on $\mathbb C^2$ has an algebroid solution  $$W=\sqrt{z_1z_2}.$$ 
\item The complex system of PDEs
   $$\begin{cases}
W_1\frac{\partial^2 W_1}{\partial z_1\partial z_2}+W_2\frac{\partial^2 W_2}{\partial z_1\partial z_2}+\frac{\partial W_1}{\partial z_1}\frac{\partial W_1}{\partial z_2}
+\frac{\partial W_2}{\partial z_1}\frac{\partial W_2}{\partial z_2}-\frac{1}{2}=0 \\
W_2\frac{\partial^2 W_1}{\partial z_1\partial z_2}+W_1\frac{\partial^2 W_2}{\partial z_1\partial z_2}+\frac{\partial W_1}{\partial z_1}\frac{\partial W_2}{\partial z_2}
+\frac{\partial W_2}{\partial z_1}\frac{\partial W_1}{\partial z_2}-1=0
   \end{cases}$$
on $\mathbb C^2$ has an algebroid solution  $(W_1, W_2)$ defined by  
$$W_1^2+W_2^2=z_1z_2, \ \ \ \    W_1W_2=z_1+z_2.$$ 
\item The complex system of PDEs 
			   $$\begin{cases}
	\frac{\partial^2 W_1}{\partial z_1\partial z_2}=\frac{1}{W_2} \\
	 \frac{\partial^2 W_2}{\partial z_1\partial z_2}=\frac{1}{W_1}
	   \end{cases}$$
on $\mathbb C^2$ has  algebroid solutions $(W_1, W_2)$ of the form 
  $$W_1=W_2=\pm2\sqrt{(\lambda z_1+c_1)(\lambda^{-1}z_2+c_2)},$$
  where $\lambda\not=0, c_1,c_2$ are arbitrary constants. However, this system of PDEs  has no meromorphic solutions. In fact, otherwise, we consider the local behavior of $W_1,W_2$ near  a zero   $(z_1^0,z_2^0)\in\mathbb C^2.$  Using   Taylor  expansion, we may assume that 
  $$\ \ \ \ \ \ \ \ \  W_1\sim a(z_1-z_1^0)^m(z_2-z_2^0)^n, \ \ \ \  W_2\sim b(z_1-z_1^0)^p(z_2-z_2^0)^q$$
  near $(z_1^0,z_2^0).$ Substituting them into the above system, we get 
$$\ \ \ \ \ \  \ \ \   amn(z_1-z_1^0)^{m-1}(z_2-z_2^0)^{n-1}\sim b^{-1}(z_1-z_1^0)^{-p}(z_2-z_2^0)^{-q}, $$
$$\ \ \ \ \ \  \ \ \  \  \ \ \    bpq(z_1-z_1^0)^{p-1}(z_2-z_2^0)^{q-1}\sim a^{-1}(z_1-z_1^0)^{-m}(z_2-z_2^0)^{-n}. $$
         Then, we obtain 
         $$ab=4, \ \ \ \    m=n=p=q=\frac{1}{2},$$
which  contradicts  with that $m,n,p,q\in\mathbb Z.$ It implies that the system has no meromorphic solutions.   
\end{itemize} 

In the viewpoint of mappings, 
 any algebroid solution $(W_1,\cdots, W_d)$ of Eq. (\ref{d0})    corresponds  to  a multi-valued analytic  mapping
		$$F=\big[1: W_1:\cdots: W_d\big]: \ \mathbb C^m\to\mathbb P^d(\mathbb C).$$ 
	On the other hand, if the above $F$ is a multi-valued  mapping defined by Eq. (\ref{d1}), then $(W_1,\cdots, W_d)$ can be viewed  as an algebroid solution of a 
		complex system of  PDEs by differentiating  Eq. (\ref{d1}).  It is a   one-to-one correspondence.
This observation   motivates us to introduce the notion of algebroid mappings.

Let $M, N$ be  complex manifolds of complex dimensions $m, n,$ respectively. 
Let   $\mathscr M(M)$ denote the field of all  meromorphic functions on $M.$
We give the following definition of algebroid mappings (see Definition \ref{defi11} in Section \ref{s11}). 

\noindent\emph{Definition.}
 We say that a  multi-valued mapping  $F: M\to N$ is     an algebroid mapping,
    if  for  every point  $y\in f(x)$ with  all $x\in M,$ 
    $\xi_1\circ F,  \cdots, \xi_n\circ F$
 are   local solutions  of  a  system of $n$ independent  algebraic equations 
 $$P_i\big(x, W_1,\cdots, W_n\big)=0, \ \ \ \   i=1,\cdots, n$$
 in  $W_1,\cdots,W_n$  over $\mathscr M(M),$   where $\xi=(\xi_1,\cdots,\xi_n)$ is a  local holomorphic coordinate near $y.$

According to the definition,  we can see that algebroid mappings generalize the notions of  meromorphic mappings and algebroid functions. 


\noindent\textbf{Examples}

	\begin{itemize} 
		\item A  2-valued  rational algebroid mapping  
					 $$F=\left[\frac{\zeta_1}{\zeta_0}: \frac{\zeta_0\zeta_2}{\zeta_1^2}: \frac{\sqrt{\zeta_2}}{\sqrt{\zeta_1}}\right]: \ \mathbb P^2(\mathbb C)\to \mathbb P^2(\mathbb C).$$
						\item A  6-valued  transcendental algebroid curve 
					 $$F=\left[z: \sqrt{z}: \sqrt[3]{z}:e^z\right]: \ \mathbb C\to \mathbb P^3(\mathbb C).$$
			\item A  12-valued transcendental  algebroid mapping 
							 $$F=\big[z_1:  \sin z_2: \sqrt{z_1}\sqrt[4]{z_2} : \sqrt[3]{z_3}e^{z_4}\big]: \ \mathbb C^4\to \mathbb P^3(\mathbb C).$$
		\end{itemize} 	

It is well-known that Nevanlinna theory \cite{ru} plays a useful  role in the study of meromorphic and algebroid solutions of  complex ODEs (see \cite{H-X, Laine,  S-G}). 
It seems helpful to develop a value distribution theory of  algebroid mappings,  
as a theoretical tool of  investigating   algebroid solutions of a complex system of PDEs. 
Since R. Nevanlinna established  Nevanlinna theory,  many  scholars  such as 
G. R\'emoundos, H. Selberg, 
  E. Ullrich and G. Valiron, etc.  have been exploring    the value distribution theory of algebroid functions. 
  For   instance, G. R\'emoundos \cite{GR} proved  a Picard's theorem   which      
   says   that   
   a nonconstant $\nu$-valued algebroid function on $\mathbb C$   omits $2\nu$ distinct  values at most; and then,  
  G. Valiron  \cite{GV}  showed    without details 
      a five-value type theorem 
             which says   that  two nonconstant $\nu$-valued algebroid functions
   on $\mathbb C$
   are identical if they share $4\nu$+1 distinct  values ignoring multiplicities. 
     For  more details, we refer  the reader    to     J. Noguchi \cite{No0}, 
 Niino-Ozawa \cite{NO, Oz}, 
   J. Suzuki \cite{JS},  L. Selberg \cite{LS1, LS2}, N. Toda \cite{To1, To2} and  E. Ullrich \cite{EU};  and  see   
 Hu-Yang \cite{HY}, 
 He-Xiao \cite{H-X}, M. Ru \cite{ru0} and 
 Sun-Gao \cite{S-G}, etc. 

However, 
there is very  little   literature about   the value distribution theory of multi-valued analytic mappings, although the researchers  have a relatively profound  understanding of  single-valued analytic mappings (see \cite{No, ru, Sha}).
  In this  paper, we  shall explore  equidistribution theory  of algebroid mappings from a complete  K\"ahler manifold into a complex projective manifold.  
This is a generalization of Carlson-Griffiths equidistribution theory of holomorphic mappings from $\mathbb C^m$ into a complex projective manifold (see \cite{gri}). 

\subsection{Main Results}~


Let $M$ be a complex manifold, and $N$ a complex projective manifold. 

   \begin{theorem}[=Theorem \ref{cover}]
   A $\nu$-valued algebroid mapping $F: M\to N$ defines   a $\nu$-leaf complex manifold $\mathcal M_F,$ which  is a  $\nu$-sheeted ramified analytic covering of $M.$
      \end{theorem} 


 \begin{cor}[=Corollary \ref{uniform}]\label{}
 An algebroid mapping $F: M\to N$ can be lifted to a meromorphic mapping $f:  \mathcal M_F\to N$ via the natural projection $\pi: \mathcal M_F\to M$  
such that $F=f\circ\pi^{-1}.$
\end{cor}

Let $(M, \alpha)$ be an $m$-dimensional  complete non-compact K\"ahler manifold with Ricci form $\mathscr R,$ and $(N, \omega)$ an $n$-dimensional   K\"ahler projective manifold.  Let $F: M\to N$ be a $\nu$-valued algebroid mapping.  
Referring  to  Sections \ref{61} and \ref{63}, one can define  Nevanlinna's functions $T_F(r, \omega), m_F(r, D), \overline{N}_F(r, D)$ and $T(r, \mathscr R)$
under different curvature conditions.  Since $N$ is projective, one can embed $N$ holomorphically into a complex projective space with Fubini-Study form $\omega_{FS}.$ 
Let  $\omega_{FS}|_N$ be the restriction of  $\omega_{FS}$ to $N.$
 Set
  $$\left[\frac{\omega_{FS}|_N}{\omega}\right]=\inf\big\{s>0: \  \omega_{FS}|_N\leq s\omega\big\}.$$


$a)$  $M$ has non-positive sectional curvature. Set  
\begin{equation}\label{ricci}
 \kappa(r)=\frac{1}{2m-1}\inf_{x\in B(r)}R(x),
 \end{equation}
   where   
    $$R(x)=\inf_{X\in T_xM, \ \|X\|=1}{\rm{Ric}}(X, X)$$
    is   the pointwise lower bound of Ricci curvature of $M,$ and $B(r)$ is the geodesic ball in $M$ centered at a fixed reference  point $o$ with radius $r.$


  \begin{theorem}[=Theorem \ref{main3}]  Let $M$ be a  
     complete non-compact  K\"ahler manifold   with non-positive sectional curvature.  
Let $(N,\omega)$ be a   K\"ahler  projective manifold  of  dimension not greater than  that  of $M.$ 
  Let $D_1,\cdots,D_q$ be effective divisors in general position on $N$ such that each $D_j$ is cohomologous to  $\omega.$
  Let  $F: M\rightarrow N$ be a  differentiably non-degenerate $\nu$-valued algebroid mapping.  
  Assume that $q\omega-{\rm Ric}(\omega^n)>0.$
  Then  for any  $\delta>0,$ there exists a subset $E_\delta\subset(1, \infty)$ of finite Lebesgue measure such that 
        \begin{eqnarray*}
&&\left(q-(2\nu-2)\left[\frac{\omega_{FS}|_N}{\omega}\right]\right)T_F(r,\omega)+T_F(r, K_N)+T(r, \mathscr R) \\
&\leq& \sum_{j=1}^q\overline N_F(r,D_j)+O\big(\log T_{F}(r, \omega)+\sqrt{-\kappa(r)}r+\delta\log r\big)
         \end{eqnarray*}
    holds for all  $r>1$ outside $E_\delta,$  where $\kappa$ is defined by $(\ref{ricci}).$          
\end{theorem}  

