\section{Comparison results associated with the scale-invariant Cassinian metric}\label{u-tau}
This section is devoted to the comparison of the average scale-invariant Cassinian metric with other hyperbolic-type metrics. First, we compare the scale-invariant Cassinian metric with the $u_D$-metric in once punctured metric spaces followed by the comparison of the average scale-invariant Cassinian metric with the $u_D$ metric in arbitrary metric spaces.
\begin{theorem}
Let $(X,d)$ be a metric space, and let $D=X\setminus \{p\}$, $p\in X$. Then for $x,y\in D$,
$$\tau_p(x,y)\le u_p(x,y)\le 2\tau_p(x,y),
$$
where $u_p(x,y):= u_{X\setminus\{p\}}(x,y)$. The right inequality is sharp.
\end{theorem}
\begin{proof}
Let $x,y\in D$ with $d(x,p)\ge d(y,p)$.
By definition,
\begin{eqnarray*}
u_p(x,y) &=& 2\log \left(\frac{d(x,y)+d(x,p)}{\sqrt{d(x,p)d(y,p)}}\right)\ge 
2\log \left(1+\frac{d(x,y)}{\sqrt{d(x,p)d(y,p)}}\right)\\
&\ge & \log \left(1+2\frac{d(x,y)}{\sqrt{d(x,p)d(y,p)}}\right)=\tau_p(x,y),
\end{eqnarray*}
where the first inequality follows from the assumption and the second inequality follows
from \eqref{bernoulli}.

To prove the second inequality, it is enough to show that
$$ \frac{d(x,y)+d(x,p)}{\sqrt{d(x,p)d(y,p)}} \le 1+2 \frac{d(x,y)}{\sqrt{d(x,p)d(y,p)}},
$$
i.e, 
$$ d(x,y)+d(x,p)\le 2 d(x,y)+\sqrt{d(x,p)d(y,p)},
$$
which is true because
$$ d(x,y)+d(x,p)\le 2d(x,y)+d(y,p) \le 2d(x,y)+\sqrt{d(x,p)d(y,p)}.
$$
Here the first inequality follows from the triangle inequality and the second one from the assumption. 

To prove the sharpness, consider the punctured Euclidean space $\Rn\setminus\{0\}$ and the points $x=e_1=(1,0,\ldots,0)$, and $y=te_1,\, 0<t<1$.
Now,
$$ \tilde{\tau}_0(x,y)=\log \left(1+\frac{2(1-t)}{\sqrt{t}}\right), \quad 
u_0(x,y)=2\log \left(\frac{2-t}{t}\right),
$$
and
$$ \lim_{t\to 0} \frac{\tilde{\tau}_0}{u_0}= \lim_{t\to 0} \frac{(1+t)(2-t)}{(2+t)(\sqrt{t}+2(1-t))}=\frac{1}{2}.
$$
This completes the proof.
\end{proof}

\begin{theorem}
Let $(X,d)$ be a metric space, and let $p_1,p_2,\ldots,p_k\in X$. Then, for $D=X\setminus \{p_1,p_2,\ldots,p_k\}$ and $x,y\in D$, we have
$$\hat{\tau}_D(x,y)\le u_D(x,y).
$$
%\le 2 \hat{\tau}_D(x,y)
The inequality is sharp.
\end{theorem}

\begin{proof}
Suppose that $d(x)=d(x,p_r)$ and $d(y)=d(y,p_s)$ and assume that $d(x)\ge d(y)$. Clearly, for all $i=1,2,\ldots,k$, 
$$d(x,p_i)\ge d(x)\, , d(y,p_i)\ge d(y) \mbox{ and } 	\sqrt{d(x,p_i)d(y,p_i)}\ge \sqrt{d(x)d(y)}.
$$
Now, with the help of \eqref{bernoulli} and the assumption, we deduce that
\begin{eqnarray*}
\hat{\tau}_D(x,y) &=& \frac{1}{k} \log \prod_{i=1}^k \left(1+\frac{2 d(x,y)}{\sqrt{d(x,p_i)d(y,p_i)}}\right) \le \frac{1}{k} \log \prod_{i=1}^k \left(1+ \frac{2 d(x,y)}{\sqrt{d(x)d(y)}}\right)\\
&=& \log \left(1+ \frac{2 d(x,y)}{\sqrt{d(x)d(y)}}\right) \le 2 \log \left(1+ \frac{ d(x,y)}{\sqrt{d(x)d(y)}}\right)\\
&\le & 2 \log \left(\frac{d(x)+ d(x,y)}{\sqrt{d(x)d(y)}}\right) = u_D(x,y). 
\end{eqnarray*}

We will prove the sharpness in the doubly punctured Euclidean space $D=\Rn\setminus\{-e_1,e_1\}$. Consider the points $x=-te_1, y=te_1, 0<t<1$.
Then,
$$ u_D(x,y)=2\log \left(\frac{1+t}{1-t}\right), \quad \hat{\tau}_D(x,y)=\log \left(1+\frac{4t}{\sqrt{1-t^2}}\right),
$$
and
$$ \lim_{t\to 0} \frac{u_D}{\zeta_D}=\lim_{t\to 0} \big(4t+\sqrt{1-t^2}\big)=1.
$$
The proof is complete.
%{\color{red}{The second inequality is to be established with sharpness.}}
