%\tilde{\tau}_D(x,y)=\frac{1}{2} \left[\log\left(1+\frac{2t}{\sqrt{1-t}}\right)+
%\log\left(1+\frac{2t}{\sqrt{1+t}}\right)\right].
%$$
\end{proof}

Next, we compare the scale-invariant Cassinian metric to the $\tilde{j}$-metric in once punctured metric spaces. 

\begin{theorem}
Let $(X,d)$ be a metric space, and let $D=X\setminus \{p\}, p\in X$. Then for $x,y\in D$,
$$\frac{1}{2}\tilde{j}_p(x,y)\le \tau_p(x,y)\le 2\tilde{j}_p(x,y).
$$
%\tilde{j}_p(x,y)\le 
The inequalities are sharp.
\end{theorem}

\begin{proof}
Without loss of generality assume that $d(x)\le d(y)$. Now,
\begin{eqnarray*}
\tau_p(x,y) &=& \log \left(1+2 \frac{d(x,y)}{\sqrt{d(x,p) d(y, p)}}\right)\le \log \left(1+2 \frac{d(x,y)}{d(x,p)}\right)\\
&\le & 2 \log \left(1+ \frac{d(x,y)}{d(x)}\right)= 2 \tilde{j}_p(x,y),
\end{eqnarray*}
where the first inequality follows from the assumption and the second inequality follows from \eqref{bernoulli}.

To establish the first inequality it is enough to prove that
$$ 1+\frac{d(x,y)}{d(x)}\le \left(1+2\frac{d(x,y)}{\sqrt{d(x)d(y)}}\right)^2.
$$ 
That is to show
$$ \frac{1}{d(x)}\le \frac{4d(x,y)}{d(x)d(y)}+\frac{4}{\sqrt{d(x)d(y)}}.
$$
Clearly,
\begin{eqnarray*}
\frac{4d(x,y)}{d(x)d(y)}+\frac{4}{\sqrt{d(x)d(y)}} &\ge & \frac{4d(x,y)}{d(x)d(y)}+\frac{4}{d(y)}= \frac{4}{d(y)} \left(1+\frac{d(x,y)}{d(x)}\right)\\
&\ge & \frac{4}{d(x)} \ge \frac{1}{d(x)}.
\end{eqnarray*}
Here the first inequality follows from the assumption and the second inequality follows from the triangle inequality.

For the sharpness, consider $D=\Rn\setminus\{0\}$ with $x=e_1$ and $y=te_1,0<t<1$. For this choice of points, we have
$$ \tilde{j}_D(x,y)=-\log t, \quad \mbox{ and } \tilde{\tau}_D(x,y)=\log \left(1+\frac{2(1-t)}{\sqrt{t}}\right).
$$
Clearly,
$$ \lim_{t\to 1} \frac{\tilde{j}_D}{\tilde{\tau}_D}=\lim_{t\to 1} \frac{\sqrt{t}+2(1-t)}{1+t}=\frac{1}{2},
$$
and 
$$ \lim_{t\to 0} \frac{\tilde{j}_D}{\tilde{\tau}_D}=\lim_{t\to 0} \frac{\sqrt{t}+2(1-t)}{1+t}=2.
$$
The proof is complete.
\end{proof}


The next result compares the average scale-invariant Cassinian metric with the $\tilde{j}$-metric in arbitrary metric spaces.
\begin{theorem}
Let $(X,d)$ be a metric space, and let $p_1,p_2,\ldots,p_k\in X$. Then, for $D=X\setminus \{p_1,p_2,\ldots,p_k\}$ and $x,y\in D$ we have
$$\hat{\tau}_D(x,y)\le 2\tilde{j}_D(x,y).
$$
The inequality is sharp.
\end{theorem}

\begin{proof}
Let $d(x,p):=\min\{d(x,p_i),d(y,p_i)\},i=1,2,\ldots,k$. Now,
\begin{eqnarray*}
\hat{\tau}_D(x,y) &=& \frac{1}{k} \sum_{i=1}^k \tau_{p_i}(x,y)=\frac{1}{k} \sum_{i=1}^k \log \left(1+2 \frac{d(x,y)}{\sqrt{d(x,p_i)d(y,p_i)}}\right)\\
 &=& \frac{1}{k} \log \prod_{i=1}^k \left(1+2 \frac{d(x,y)}{\sqrt{d(x,p_i)d(y,p_i)}}\right) \le \frac{1}{k} \log \prod_{i=1}^k \left(1+2 \frac{d(x,y)}{d(x,p)}\right)\\
 &=& \frac{1}{k} \log \left(1+2 \frac{d(x,y)}{d(x,p)}\right)^k = \log \left(1+2 \frac{d(x,y)}{d(x,p)}\right) \le 2 \log \left(1+ \frac{d(x,y)}{d(x,p)}\right)\\
 &=& 2 \tilde{j}_D(x,y).
\end{eqnarray*}
Here the first and the second inequalities respectively follow from the assumption and \eqref{bernoulli}. 

We will prove the sharpness part in the twice punctured Euclidean space $D=\Rn\setminus \{-e_1,e_1\}$. Choose the points $x=0$ and $y=te_1, 0<t<1$. Clearly,
$$ \tilde{j}_D(x,y)=-\log(1-t), \quad \zeta_D=\frac{1}{2} \left[\log\left(1+\frac{2t}{\sqrt{1-t}}\right)+
\log\left(1+\frac{2t}{\sqrt{1+t}}\right)\right],
$$
and
$$ \lim_{t\to 0} \frac{\tilde{j}_D}{\zeta_D}= \lim_{t\to 0}
%2\lim_{t\to 0} \left[\frac{2-t}{2t+\sqrt{1-t}}+\frac{2+t}{(1+t)(2t+\sqrt{1+t})}\right]^{-1}
-\frac{2}{{\left(t - 1\right)} {\left(\frac{\frac{2}{\sqrt{t + 1}} - \frac{t}{{\left(t + 1\right)}^{3/2}}}{\frac{2 \, t}{\sqrt{t + 1}} + 1} + \frac{\frac{t}{{\left(-t + 1\right)}^{3/2}} + \frac{2}{\sqrt{-t + 1}}}{\frac{2 \, t}{\sqrt{-t + 1}} + 1}\right)}}
=\frac{1}{2}.
$$
The proof is complete.
\end{proof}

We now compare the scale-invariant Cassinian metric with the $j$-metric in once punctured metric spaces.

\begin{theorem}
Let $(X,d)$ be a metric space and $D=X\setminus \{p\}, p\in X$. Then for $x,y\in D$
$$j_p(x,y)\le \tau_p(x,y)\le 2 j_p(x,y).
$$
The inequalities are sharp.
\end{theorem}

\begin{proof}
Without loss of generality assume that $d(x,p)\le d(y,p)$. To prove the first inequality it is enough to show that
$$\left(1+\frac{d(x,y)}{d(x,p)}\right) \left(1+\frac{d(x,y)}{d(y,p)}\right) \le \left(1+2\frac{d(x,y)}{\sqrt{d(x,p)d(y,p)}}\right)^2,
$$
i.e., 
$$ (d(x,p)+d(x,y))(d(y,p)+d(x,y))\le (\sqrt{d(x,p)d(y,p)}+2d(x,y))^2.
$$
To this end, it is sufficient to show that
$$ d(x,p)+d(y,p)\le 3 d(x,y)+ 4 \sqrt{d(x,p)d(y,p)}.
$$
Now,
\begin{eqnarray*}
d(x,p)+d(y,p)\le 2 d(x,p)+d(x,y) &\le& 2 \sqrt{d(x,p)d(y,p)}+ d(x,y)\\
&\le & 3 d(x,y)+ 4 \sqrt{d(x,p)d(y,p)},
\end{eqnarray*}
where the first inequality follows from the triangle inequality and second inequality follows from the assumption.

To establish the second inequality, we need to prove that
$$ \left(1+ 2 \frac{d(x,y)}{\sqrt{d(x,p)d(y,p)}} \right) \le \left(1+\frac{d(x,y)}{d(x,p)}\right) \left(1+\frac{d(x,y)}{d(y,p)}\right).
$$
i.e., 
$$ 2 \sqrt{d(x,p)d(y,p)} \le d(x,p)+d(y,p)+d(x,y)
$$
which follows from \eqref{am-gm}. 

To prove the sharpness, consider the punctured Euclidean space $\Rn\setminus\{0\}$ and choose the points $x=e_1$ and $y=te_1,\, 0<t<1$.
Simple computations yield,
$$ \tilde{\tau}_0(x,y)=\log \left(1+\frac{2(1-t)}{\sqrt{t}}\right), \quad 
j_0(x,y)=\frac{1}{2}\log \left(\frac{2-t}{t}\right).
$$
Therefore,
$$ \lim_{t\to 0} \frac{\tilde{\tau}_0}{j_0}= \lim_{t\to 0} \frac{(1+t)(2-t)}{\sqrt{t}+2(1-t)}=1
$$
and 
$$ \lim_{t\to 1} \frac{\tilde{\tau}_0}{j_0}= \lim_{t\to 1} \frac{(1+t)(2-t)}{\sqrt{t}+2(1-t)}=2.
$$
The proof is complete.
\end{proof}

The following result compares the average scale-invariant Cassinian metric with the $j$ metric in arbitrary metric spaces.
\begin{theorem}
Let $(X,d)$ be a metric space and $p_1,p_2,\ldots,p_k\in X$. Then, for $D=X\setminus \{p_1,p_2,\ldots,p_k\}$ and $x,y\in D$ we have
$$\hat{\tau}_D(x,y)\le 2 j_D(x,y).
$$
