\section{Preliminaries}
Throughout the paper we freely use Sweedler notation and the Kronecker symbol $\delta^i_j$.  Symbol $\otimes$ denotes the tensor product of vector spaces over the ground field $\genfd$.

\subsection{Yetter--Drinfeld module algebra} 



\begin{definition}\label{rlydma} 
	Let $H$ be a $\genfd$-bialgebra. A \emph{right-left Yetter--Drinfeld module algebra} over $H$ is a triple $(A,\btl,\lambda)$ such that 
	\begin{enumerate} 
		\item[(1)] $A$ is a $\genfd$-algebra 
		\item[(2)] $(A,\btl)$ is a right $H$-module  
		\item[(3)] $(A,\lambda\colon a\mapsto a_{[-1]}\otimes a_{[0]})$ is a left $H$-comodule		
		\item[(4)] action and coaction satisfy the \emph{right-left Yetter--Drinfeld condition} 
		\begin{equation} \label{eq:YDrl1}
		\sum a_{[-1]} h_{(1)}\otimes (a_{[0]} \btl h_{(2)}) = \sum h_{(2)}(a \btl h_{(1)} )_{[-1]} \otimes  (a \btl h_{(1)})_{[0]}, \quad \forall h \in H, a\in A
		\end{equation}	
		\item[(5)] action $\btl$ is \emph{Hopf}, that is 
		\begin{equation}
		(ab) \btl h = \sum 	(a \btl h_{(1)})(b \btl h_{(2)}), \quad 1_A \btl h = \epsilon(h) 1_A, \quad \forall h\in H, a,b\in A
		\end{equation}		
		\item[(6)] coaction $\lambda$ satisfies 
		\begin{equation} \label{eq:marl}
		\sum (ab)_{[-1]} \otimes (ab)_{[0]} = \sum b_{[-1]}a_{[-1]} \otimes a_{[0]} b_{[0]}, \quad \lambda(1_A) = 1_H\otimes 1_A, \quad \forall a,b\in A
		\end{equation} 
		called the \emph{comodule algebra property} (over $H^\op$).
	\end{enumerate}
	We say that a Yetter--Drinfeld module algebra $(A,\btl,\lambda)$ is \emph{braided commutative} if
	\begin{equation} \label{eq:bcrl}
	\sum (a \btl b_{[-1]})b_{[0]} = ba, \quad \forall a,b\in A.
	\end{equation} 
\end{definition}

Axioms (2), (3) and (4) from Definition \ref{rlydma} together comprise the axioms for $(A,\btl,\lambda)$ being a \emph{right-left Yetter--Drinfeld module} over $H$. Morphisms of Yetter--Drinfeld $H$-modules are $H$-module morphisms which are also $H$-comodule morphisms. Right-left Yetter--Drinfeld $H$-modules form a category ${}^H\mathcal{Y}\mathcal{D}_H$ carrying a canonical monoidal structure with a pre-braiding, which is a braiding if $H$ is a Hopf algebra. 

Axioms (1), (2) and (5) from Definition \ref{rlydma} together say that $(A,\btl)$ is a \emph{right module algebra} over $H$.  Given any right module $H$-algebra $(A,\btl)$, the vector space $H\otimes A$ carries a structure of an associative $\genfd$-algebra with the multiplication bilinearly extending formula
\begin{equation}
(h\otimes a)\cdot(h'\otimes a') = \sum h h'_{(1)}\otimes (a\blacktriangleleft h'_{(2)}) a', \quad  \text{ for } h,h'\in H \text{ and } a,a' \in A
\end{equation} 
and the unit $1_H\otimes 1_A$. This algebra is called the \emph{smash product algebra} and is denoted	$H\sharp_{\btl} A$. If it is clear from the context which action induces the smash product multiplication, we denote this smash product algebra simply by $H\sharp A$. Smash product algebra $H\sharp A$ comes along with the canonical algebra monomorphisms $A\hookrightarrow H \sharp A$ and $H\hookrightarrow H\sharp A$. The images of these two embeddings are denoted $1\sharp A$ and $H\sharp 1$. A general element $a\otimes h$ of $A\sharp H$ is denoted by $a\sharp h$.


Written in terms of the corresponding smash product algebra $H\sharp A$, the right-left Yetter--Drinfeld property is
\begin{align}
\lambda(a) \cdot h
&= h_{(2)} \cdot \lambda(a \btl h_{(1)} ), \quad  \text{ for all } a\in A \text{ and } h\in H. \label{eq:YDrl}
\end{align}


Axioms (1), (3) and (4) from Definition \ref{rlydma} define a \emph{left $H^\op$-comodule algebra} $(A,\lambda)$. Therefore, a right-left Yetter--Drinfeld $H$-module algebra is a right-left Yetter--Drin\-feld $H$-module and an algebra that is a right $H$-module algebra and a left $H^\op$-comodule algebra.

\subsection{Hopf pairing}
Pairings of vector spaces are bilinear maps into the ground field $\genfd$ which are in this work not required to be nondegenerate. 
\begin{definition} 
	A pairing between two Hopf algebras $A$ and $H$ is a \emph{Hopf pairing} if
	$\langle \Delta_A(a), h\otimes k\rangle = \langle a, h\cdot k\rangle$ where on the left hand side the pairing is a product of pairings in each tensor factor and likewise $\langle a\otimes b, \Delta_H(h)\rangle = \langle a\cdot b,h\rangle$,
	as well as $\epsilon_A(a) = \langle a,1\rangle$, $\epsilon_H(h) = \langle 1,h\rangle$ and $\langle S_A(a), h \rangle = \langle a, S_H(h)\rangle$, for all $a\in A$ and $h,k\in H$.
\end{definition}

If $A$ is a Hopf $\genfd$-algebra and $(H,\str)$ is a left module $A$-algebra, the vector space $H\otimes A$ carries a structure of an associative $\genfd$-algebra with the multiplication bilinearly extending formula
\begin{equation}
(h\otimes a)\cdot( h'\otimes a') = \sum h (a_{(1)}\str h')\otimes a_{(2)} a', \quad \text{ for } h,h'\in H \text{ and } a,a' \in A
\end{equation} 
and the unit $1_H\otimes 1_A$. This algebra is also called the \emph{smash product algebra} and is denoted by $H\sharp_{\str} A$, or simply $H\sharp A$ if the action is clear from the context. 

\begin{proposition}\label{prop:leftright}
	A Hopf pairing $\langle \,,\rangle \colon A \otimes H \to \genfd$ between Hopf algebras $A$ and $H$ induces a left action and a right action
	\begin{align}
	\str &\colon A\otimes H \to H, \quad a\str h = \sum h_{(1)}\langle a, h_{(2)} \rangle , \\
	\btl &\colon A \otimes H \to A, \quad a \btl h = \sum \langle a_{(1)}, h \rangle a_{(2)}, \quad \text{for } a\in A \text{ and } h\in H,
		\end{align} which both induce the same smash product algebra $H\sharp A$. 
\end{proposition}
\begin{proof}
	The proof is straightforward. For $a,b \in A$ and $f,h\in H$, we have that 
	\begin{align*}
	f \sharp a \cdot h \sharp b & = \sum f a_{(1)} \langle a_{(1)}, h_{(2)} \rangle a_{(2)}b \\
	& = \sum f (a_{(1)} \str h) \sharp a_{(2)} b \\
	& = \sum f h_{(1)} \sharp (a \btl h_{(2)})b.
	\end{align*}


\end{proof}
\subsection{Hopf algebroid}

Given a Hopf algebra $H$, each right-left Yetter-Drinfeld $H$-module algebra $A$ gives rise to an associative $A$-bialgebroid structure on the smash product algebra $H \sharp A$ \cite{BrzMilitaru, stojic}. There is also an antimultiplicative antipode map making $H\sharp A$ the total algebra of a Hopf algebroid over $A$ \cite{BrzMilitaru,stojic}. A generalized version of the scalar extension construction is provided in \cite{stojic}. Its input is a compatible pair $A$ and $A^{\op}$ of a right-left and a left-right braided commutative Yetter-Drinfeld $H$-module algebras, and the output is a symmetric Hopf algebroid $A^\op\sharp H \cong H\sharp A$ over base algebras $A^\op,A$. The construction in \cite{stojic} does not require that the antipode of $H$ is invertible. 

\subsection{Representative functions} 
If $G$ is a group, the multiplication $m$ of $G$ induces a map $m^* \colon \mathcal F(G,\genfd) \to \mathcal F(G\times G,\genfd)$ by $m^*(f) = f \circ m$, for a function $f \in \mathcal F(G,\genfd)$. We say that $f \in \mathcal F(G, \genfd)$ is a \emph{representative function} if $m^*(f)$ is in the image of the canonical map $\mathcal F(G,\genfd)\otimes \mathcal F(G,\genfd) \to \mathcal F(G\times G,\genfd)$ \cite{HochMost}. The set $\mathcal R$  of representative functions on a group $G$ is a Hopf algebra with the structure maps for the comultiplication, the counit and the antipode transposed from the structure maps of $G$, 
$$\Delta(f)(a\otimes b) = f(ab), \quad \epsilon(f)=f(e), \quad S(f)(a)= f(a^{-1}) ,\quad \text{ for } f\in \mathcal R \text{ and } a,b\in G .$$
If $G$ is an affine algebraic group over a field $\genfd$, then $\genfd$-valued representative functions on $G$ are automatically regular. If $G$ is a Hausdorff topological group, then $\genfd$-valued representative functions on $G$ are automatically continuous.   %Equivalenty, $f$ is representative if the span of all functions $\{g \cdot f : g\in G\}$, where $g \cdot f$ denotes the function with mapping rule $a \mapsto f(ag)$ for $a \in A$, is finite dimensional. 


\section{Overview of results}\label{sec:cases}

We consider the following cases:
\begin{enumerate}
	\item[(I)] $G$ is a Lie group over a field $\genfd$ equal to $\mathbb{R}$ or $\mathbb{C}$, $\mathcal{L}$ is the tangent space at the unit of $G$, and
	\begin{enumerate} 
		\item[(a)] $\mathcal{F}$ is the algebra $C^\infty(G)$ of smooth functions on $G$, $\mathcal{D}$ is the Lie algebra %$\Gamma^\infty(G)$ 
		of smooth vector fields on $G$,   or
		\item[(b)] $\mathcal{F}$ is the algebra $C^\infty(G,e)$ of germs of smooth functions around the unit of $G$, $\mathcal{D}$ is the Lie algebra of germs of smooth vector fields around the unit on $G$, or
	\end{enumerate}
	\item[(II)] $G$ is an affine algebraic group over any field $\genfd$, $\mathcal{F}$ is the Hopf algebra $\OO(G)$ of regular functions on $G$, $\mathcal{L}$ is the algebra of differentiations $\OO(G) \to \genfd$, $\mathcal{D}$ is the Lie algebra of derivations $\OO(G) \to \OO(G)$, or
	\item[(III)] \begin{enumerate}
		\item[(a)] $G$ is a Lie group over a field $\genfd$ equal to $\mathbb{R}$ or $\mathbb{C}$, $\mathcal{L}$ is the tangent space at the unit of $G$, $\mathcal{F}$ is the algebra $J^\infty(G,e)$ of $\infty$-jets of smooth functions around the unit of $G$,  $\mathcal{D}$ is the Lie algebra  of $\infty$-jets  of smooth vector fields around the unit of $G$, or
		\item[(b)] $\mathfrak{g}$ is a Lie algebra over any field $\genfd$, $\mathcal{F}$ is the dual $\Ug^*$ of the universal enveloping algebra $U(\ggf)$.
	\end{enumerate}
\end{enumerate} 
In cases (I) and (II), we consider algebras $\mathcal H \subset \mathcal F \cap \mathcal R$, that is, Hopf algebras of some representative functions on $G$, and in case (III) $\mathcal H$ is a Hopf subalgebra of $\Ug^\circ$.
We prove that $\Ug$ is a braided commutative right-left Yetter--Drinfeld module algebra over $\mathcal H$ if $\mathcal H$ contains as elements components of a certain matrix $\OO$ in cases (I) and~(II), or components of a certain matrix $\UU$ in case (III). Matrix $\OO$ is a
the matrix of the adjoint representation $\Ad$ of group~$G$, and matrix $\UU$ is likewise derived from adjoint representation $\ad$ of Lie algebra $\ggf$, with regard to a chosen basis of $\ggf$, and the resulting minimal Hopf algebras $\OO^{min}(G)$ and $\Ug^{min}$ that contain their components do not depend on the choice of the basis for $\ggf$. This makes $\mathcal H \sharp \Ug \cong \Ug^\op \sharp \mathcal H$ into a scalar extension Hopf algebroid over base algebras $\Ug^\op, \Ug$ \cite{stojic}. 




\section{Yetter--Drinfeld module algebra over a Hopf algebra of functions}

We consider now cases (I) and (II) described in Section \ref{sec:cases}. In case (II), $\mathcal F$ is a Hopf algebra. In case (I) we usually work with some Hopf algebra $\mathcal H \subset \mathcal F$ of representative functions, and in case (II) with whole $\mathcal F$.

\subsection{Hopf algebra of some representative functions on $G$}
Let $\mathcal{H}$ be a subalgebra of $\mathcal{F}$ and a Hopf algebra such that its coalgebra structure and antipode are the \emph{transpose of the group structure} of $G$, that is $\Delta_\mathcal{H}(f)(a\otimes b) = f(ab)$, $\epsilon_\mathcal{H}(f) = f(e)$, and $S_\mathcal{H}(f)(a) = f(a^{-1})$, for all $f\in \mathcal{H}$ and $a,b \in G$. In other words, $\mathcal H$ is a subset of the Hopf algebra $\mathcal R \cap \mathcal F$ of representative functions on $G$, with the inherited Hopf algebra structure. Note that even though the algebra $\mathcal F$ in case (I) of smooth functions is not a Hopf algebra, maps $\epsilon$ and $S$ are defined, as follows. Denote by $\epsilon$ the $\genfd$-linear map $\mathcal F \to \genfd$ such that $\epsilon(f) = f(e)$ for all $f\in\mathcal F$, and by $S$  the $\genfd$-linear map $\mathcal F \to \mathcal F $ such that $S(f)(a) = f (a^{-1}) $ for all $f\in\mathcal F$ and $a\in G$. In case (II), $\mathcal H$ is any Hopf subalgebra of $\mathcal F$ since $\mathcal F$ is a subset of the Hopf algebra $\mathcal R$ of representative functions on $G$.

\subsection{Left invariant and right invariant derivations} 
A \emph{derivation} of a $\genfd$-algebra $\mathcal F$ is any $\genfd$-linear map $D \colon \mathcal F \to \mathcal F$ such that $$D(fh) = D(f)h + f D(h), \quad \text{ for all } f,h \in \mathcal F.$$ Denote by $\mathcal D$ the Lie algebra of derivations of $\mathcal F$. The Lie algebra bracket is simply the commutator of elements. 
Let $\gL$ denote the Lie algebra of \emph{left invariant} derivations, that is, elements $D \in \mathcal{D}$ such that for every $g\in G$ we have that $D(f\circ L_g) = D(f) \circ L_g$, where $L_g \colon G \to G $, $L_g(a) = ga$ for $a \in G$. Let $\gR$ denote the Lie algebra of \emph{right invariant} elements of $\mathcal{D}$, that is, elements $D \in \mathcal{D}$ such that for every $g\in G$ we have that $D(f\circ R_g) = D(f) \circ R_g$, where $R_g \colon G \to G $, $R_g(a) = ag$ for $a \in G$. It is easy to see that $\gL$ and $\gR$ are indeed  Lie algebras as subalgebras of the Lie algebra $\mathcal D$. Denote by $\UgL$ and $\UgR$ the universal enveloping algebras of $\gL$ and $\gR$ respectively. 

Denote by $\mathcal L$ the $\genfd$-vector space of differentiations of $\mathcal F$. A \emph{differentiation} of $\mathcal F$ is any $\genfd$-linear map $\nu \colon \mathcal F \to \genfd$ such that $\nu(fg) = \nu(f) \epsilon(g) + \epsilon(f) \nu(g)$. All differentiations on $\mathcal F$ comprise a "tangent space" $\mathcal{L}$ at the unit of $G$. It is finite-dimensional in the case of an affine algebraic group $G$ \cite{Hochschild}. Result $\nu(f)$ is often denoted $\langle \nu, f \rangle$, for $\nu \in \mathcal L$ and $f \in \mathcal F$, since $\nu$ is a linear functional on $\mathcal F$.

\begin{proposition}

	Dimension of $\genfd$-vector space $\mathcal{L} $ of differentiations of $\mathcal F$ is finite.
\end{proposition}
\begin{proof}
	For case (II), vector $\genfd$-space $\mathcal L$ is finite-dimensional, because a differentiation of $\mathcal F$ is determined by its values on a finite system of $\genfd$-algebra generators \cite{Hochschild}.  For case (I), this is the tangent space at the unit of a Lie group. 
\end{proof}


If $D\in \mathcal D$, then $\epsilon \circ D \in \mathcal L$. For case~(I), differentiation $\epsilon\circ D$ is the tangent vector at the unit of $G$ that corresponds to the vector field $D$. Therefore we have a $\genfd$-linear map $\epsilon \circ - \colon \mathcal D \to \mathcal L$. The next proposition proves that this map is surjective.

\begin{proposition}
For each differentiation $\nu \in \mathcal L$ there exists a unique left invariant derivation $X_\nu$ and a unique right invariant derivation $Y_\nu$ such that $\epsilon \circ X_\nu = \epsilon \circ Y_\nu = \nu$. In case (II), they are given by formulas: $$X_\nu(f) = \sum  f_{(1)} \langle \nu, f_{(2)}  \rangle, \quad Y_\nu(f) = \sum f_{(1)} \langle \nu, f_{(2)} \rangle, \text{ for all } f\in \mathcal F.$$ In case (I), the above formulas are true for elements $f$ of the Hopf algebra $\mathcal H \subset \mathcal F \cap \mathcal R$.
\end{proposition}
\begin{proof} The right invariant derivation $Y_\nu$ is uniquely determined by the formula $Y_\nu(f)(g) = \nu(f\circ R_g)$ for all $f\in \mathcal F$ and $g\in G$, and similarly for the left invariant one. For case (I), $Y_\nu$ is the right invariant vector field with the corresponding tangent vector $\nu$ at the unit, and similarly for $X_\nu$. For any Hopf algebra $\mathcal H \subset \mathcal F$, in both cases (I) and (II),  for $f \in \mathcal H$, $Y_\nu(f)(a) = Y_{\nu}(f)(e \cdot a) = Y_\nu(f \circ R_a)(e) = \sum \langle \nu, f_{(1)} f_{(2)}(a) \rangle = \sum \langle \nu, f_{(1)} \rangle f_{(2)}(a),$ and therefore $Y_\nu(f) = \sum \langle \nu, f_{(1)} \rangle f_{(2)}$, and similarly for $X_\nu$  \cite{Hochschild}.
\end{proof}

Lie algebra $\mathcal D$ of derivations is a left $\mathcal F$-module in a usual way.  
\begin{proposition} \label{prop:isoleft} The mapping  $$\mathcal{F} \otimes \mathcal{L} \to \mathcal{D}, \quad f \otimes \nu \mapsto fX_\nu,$$ is an $\mathcal F$-module isomorphism.  The image of $\genfd \otimes \mathcal L$ is $\gL \subset \mathcal{D}$.
\end{proposition}
\begin{proof}
	See \cite{Hochschild}, Theorem III.3.1.
\end{proof}	
\begin{proposition} \label{prop:isoright} The mapping  $\mathcal{F} \otimes \mathcal{L} \to \mathcal{D}$ defined by the rule $f \otimes \nu \mapsto fY_\nu$ is an $\mathcal F$-module isomorphism.  The image of $\genfd \otimes \mathcal L$ is $\gR \subset \mathcal{D}$.
\end{proposition}
\begin{proof}
	Similar as Proposition \ref{prop:isoleft}.
\end{proof}
It follows that each right invariant derivation can be written as a product of functions and elements of a basis of the Lie algebra of left invariant derivations in a unique way, and likewise for left invariant derivations. It can be proven that functions that appear thereat as coefficients are always representative. 




\subsection{Hopf actions and pairings}

\begin{proposition}\label{prop:action}
	The action $\mathcal D \otimes \mathcal F \to \mathcal F$ restricted to $\gL \otimes \mathcal F \to \mathcal F$ induces a unique left Hopf action $$\str \colon \UgL \otimes \mathcal F \to \mathcal F,$$ that is, differentiation of a function by a left invariant differential operator. 

\end{proposition}
\begin{proof} 
	In case (I), every left invariant vector field  $X \in \ggf_L$ defines a first order differential operator $D_X \colon C^\infty(G) \to C^\infty(G)$ by $D_Xf = Xf$. By multiplicativity and linearity, the mapping $X \mapsto D_X$ extends to an injective homomorphism of unital algebras $$D \colon \UgL \hookrightarrow \End_{\mathbb{R}}(C^\infty(G)), \quad P \mapsto D_P.$$ Explicitly, element  $P = X_1\cdots X_r \in U(\ggf_L)$, where $X_1,\ldots,X_r \in \ggf_L$, maps to a diferential operator $D_{P}$ defined by  %\ref{Timmermann}
$$(D_{P}f)(y) = (D_{X_1} \cdots D_{X_r}f)(y) 
= \lim_{t_1,\ldots,t_r\to 0}\frac{\partial^{r}}{\partial t_1 \cdots \partial t_r} f(y \cdot \exp(t_1X_1)\cdots\exp(t_rX_r)).
$$
This formula is obtained by starting with the formula for a left invariant vector field~$X$,
$$(D_X f)(y) = \lim_{t\to 0}\frac{\partial}{\partial t} f(y \cdot \exp(t X)),$$ 
where the argument $y$ is multiplied on the right with the exponential for the formula to be left invariant, and by using induction on the order of the differential operator, with the step of induction simply
$$(D_{X_1} \cdots D_{X_r}f)(y) 
= \lim_{t\to 0}\frac{\partial }{\partial t_1} (D_{X_2} \cdots D_{X_r}f)(y \cdot \exp(t_1X_1)) .$$
%The aforementioned pairing is defined as	$$\langle\,,\rangle \colon U(g_L) \otimes \mathcal F \to \genfd, \quad \langle P,f\rangle = (D_P f)(e),$$
%the pairing of Hopf algebra  $U(\ggf_L)$ and algebra $\mathcal F$. 
This action is Hopf due to Leibniz rule.  

In case (II), we define the action of $T(\gL)$ in the same way, simply by composing left invariant derivations. Let $X_1,\ldots,X_n$ be a basis of $\gL$. The derivation $X_iX_j - X_j X_i$ is again a left invariant derivation and acts in the same way as $[X_i,X_j]$ because it is the same. Hence we have a well defined action of $\UgL$ on $\mathcal F$. It is easy to check that the action is Hopf.
\end{proof}

\begin{proposition}\label{prop:actionR}
	The action $\mathcal D \otimes \mathcal F \to \mathcal F$ restricted to $\gR \otimes \mathcal F \to \mathcal F$ induces a unique right Hopf action $$\str \colon \UgR \otimes \mathcal F \to \mathcal F,$$ that is, differentiation of a function by a right invariant differential operator. 

\end{proposition}
\begin{proof}
	Analogous to the proof of Proposition \ref{prop:action}. This pairing is defined by using formula
	$$(D_{P}f)(y) = (D_{Y_1} \cdots D_{Y_r}f)(y) 
	= \lim_{{t_1,\ldots,t_r\to 0}}\frac{\partial^{r}}{\partial t_1 \cdots \partial t_r} f(\exp(t_rY_r)\cdots\exp(t_1Y_1) \cdot y)
	$$
	for $P = Y_1\cdots Y_r \in U(\ggf_R)$, where $Y_1,\ldots,Y_r \in \ggf_R$. Note that the exponentials here are on the left and that the order of the arguments is reversed, due to $P$ being right invariant instead of left invariant.
\end{proof}

The pairing of the universal enveloping algebra and the algebra of functions is defined as applying the invariant differential operator to a function and then evaluating the result at the unit.

\begin{proposition}\label{prop:pair} The Hopf action $\str \colon \UgL \otimes \mathcal F \to \mathcal F$ from Proposition \ref{prop:action}
	induces a pairing 
	$$\langle\,,\rangle \colon \UgL \otimes \mathcal{F} \to \genfd,$$ 
	by formula
	\begin{equation}\label{eq:pair}  \langle D, f\rangle = \epsilon(D(f)), \quad \text{ for all } D \in \UgL \text{ and } f \in \mathcal F.
	\end{equation}  
	Its restriction  to a pairing with a Hopf algebra $\mathcal H \subset \mathcal F \cap \mathcal R$ is a Hopf pairing $$\langle\,,\rangle \colon \UgL \otimes \mathcal{H} \to \genfd.$$
	Moreover, action $\str$ satisfies the formula
	\begin{equation}\label{eq:actpair} D \str h = \sum h_{(1)} \langle D,h_{(2)} \rangle, \quad \text{ for all } D\in \UgL \text{ and } h \in \mathcal{H}
	\end{equation}
	and it restricts to a left Hopf action  
	$\str \colon \UgL \otimes \mathcal H \to \mathcal H.$
\end{proposition}

\begin{proof} 


	For case (I), first we check the compatibility of the multiplication on $\UgL$ and the comultiplication on $H$,
\begin{align*}
\langle {X_1}\cdots{X_r}, f \rangle & = \lim_{t_1,\ldots,t_r\to 0}\frac{\partial^{r}}{\partial t_1 \cdots \partial t_r} f(\exp(t_1X_1)\cdots\exp(t_rX_r)) 
\\
& = \lim_{t_1,\ldots,t_r\to 0} \frac{\partial^{r}}{\partial t_1 \cdots \partial t_r}\left(\sum f_{(1)}(\exp(t_1X_1))\cdots f_{(r)}(\exp(t_rX_r))\right) 
\\
&  = \sum \frac{\partial}{\partial t_1 }\Big|_{t_1=0}  f_{(1)}(\exp(t_1X_1)) \cdots \frac{\partial}{\partial t_r}\Big|_{t_r=0} f_{(s)}(\exp(t_rX_r)) 
\\
& = \sum \langle X_1, f_{(1)}\rangle\cdots \langle X_r , f_{(r)} \rangle.
\end{align*}
Second, we check the compatibility of the multiplication on $H$ and the comultiplication on  $\UgL$. For $X\in \ggf_L$ we have Leibniz rule
$$ \langle \Delta(X), fg \rangle = f(e) \langle X,g\rangle + \langle X, f \rangle g(e)
$$
and it is easy to show inductively that the claim  holds for all  $P \in \UgL$.
Third, we check the compatibility of units and counits, for $P = X_1 \cdots X_r$:
$$\langle P, 1_H \rangle = 0 = \epsilon(P), \quad \langle 1_{\Ug}, f\rangle = f(e) = \epsilon(f)  $$
$$\langle 1_{\Ug}, 1_\mathcal H \rangle = 1 = \epsilon(1_{\Ug}).$$
Finally, we check the compatibility of antipodes: for $X \in \ggf_L$  we have
$$\langle X, Sf \rangle = \lim_{t\to 0} \frac{\partial}{\partial t }  f((\exp(tX))^{-1}) =\lim_{t\to 0} \frac{\partial}{\partial t }   f(\exp(-tX)) = - \langle X,f\rangle = \langle SX, f\rangle$$
and it is easy to prove inductively that the claim holds for all  $P \in \UgL$.

For case (I), we prove the formula, for $P \in \UgL$ and $f \in H$,
\begin{equation}
D_P f = \sum f_{(1)} \langle P, f_{(2)}\rangle.
\end{equation}

We check this first for $X \in \ggf_L$,
\begin{align*}
(D_X f)(y) &= \lim_{t\to 0} \frac{\partial}{\partial t} f(y \cdot \exp(tX)) \\
& = \lim_{t\to 0} \frac{\partial}{\partial t} \sum f_{(1)}(y) f_{(2)} (\exp(tX)) \\
& = \sum f_{(1)}(y) \langle X, f_{(2)} \rangle
\end{align*}
and then the claim is easily proven inductively for all $P \in \UgL$. 

For case (II), define the pairing by formula (\ref{eq:pair}). It is straightforward to check similarly as above that it is Hopf pairing and that it satisfies formula (\ref{eq:actpair}). 
\end{proof}

Since $\mathcal H$ is commutative, $\mathcal{H}^\co$ is again a Hopf algebra over $\genfd$. 

\begin{proposition} Hopf action $\str \colon \UgR \otimes \mathcal F \to \mathcal F$ from Proposition \ref{prop:actionR} induces a pairing 
	$$\langle\,,\rangle \colon \UgR \otimes \mathcal{F} \to \genfd$$ by formula 
	\begin{equation} \langle D, f\rangle = \epsilon(D(f)), \quad \text{ for all } D \in \UgR \text{ and } f \in \mathcal F.
	\end{equation} %The pairing thus consists of applying a right invariant differential operator to a function and then evaluating the result at the unit.
	Its restriction  to a pairing with a Hopf algebra $\mathcal H \subset \mathcal F \cap \mathcal R$ is a Hopf pairing $$\langle\,,\rangle \colon \UgR \otimes \mathcal{H}^\co \to \genfd.$$ 
	Moreover, action $\str$ satisfies the formula
	\begin{equation}
	D \str h = \sum \langle D,h_{(1)} \rangle h_{(2)} , \quad \text{ for all } D\in \UgR \text{ and } h \in \mathcal{H}
	\end{equation}
	and it restricts to a right Hopf action  
	$\str \colon \UgR \otimes \mathcal H \to \mathcal H.$


\end{proposition}
\begin{proof}

Similar as proof of Proposition \ref{prop:pair}.
\end{proof}	



\subsection{Algebra of differential operators}

\begin{proposition}\label{prop:smash} The actions  $\str \colon \UgL \otimes \mathcal F \to \mathcal F$ and $\str \colon \UgR \otimes \mathcal F \to \mathcal F$ induce smash product algebra structures $\mathcal F \sharp_{\str} \UgL$ and $\mathcal F \sharp_{\str} \UgR$ on the corresponding tensor products. As algebras
	$$\operatorname{Diff}(G) \cong \mathcal F \sharp_{\str} \UgL \cong \mathcal F \sharp_{\str} \UgR.$$
Both actions extend to actions of the whole smash product algebra such that $\mathcal F\sharp 1$ acts on $\mathcal F$ by multiplication. These actions are precisely actions of differential operators on functions.   


\end{proposition}
\begin{proof}
The multiplication in the smash product algebra is by definition $$f \sharp P \cdot h\sharp D = \sum f (P_{(1)} \str h) \sharp P_{(2)} D, \quad \text{ for } f,h\in\mathcal F \text{ and } P,D \in \UgL \text{ or } \UgR.$$ 	The proof is straightforward. 
\end{proof}

\subsection{Definition of Hopf algebra $\OO^{min}(G)$}


\begin{proposition}\label{minus}
	Let $X_1,\ldots, X_n$ be a basis of the Lie algebra $\gL$  of left invariant derivations of $\mathcal F$, and denote by $Y_1,\ldots, Y_n$ the corresponding basis of the Lie algebra $\gR$  of right invariant derivations of $\mathcal F$, that is, the one such that $\epsilon \circ X_i = \epsilon \circ Y_i$ for every $i \in \{1,\ldots,n\}$. Define the structure constants $C_{ij}^k$ from $$[X_i,X_j] = \sum_k C_{ij}^k X_k, \quad \text{ for } i,j\in\{1,\ldots,n\}.$$ Then $$[Y_i,Y_j] = - \sum_k C^k_{ij} Y_k, \quad \text{ for all } i,j\in\{ 1,\ldots,n\}.$$

\end{proposition}
\begin{proof} For case (I), this is well known. For case (II), $\mathcal F$ is a Hopf algebra and for every $f \in \mathcal F$ and every $i,j\in\{1,\ldots,n\}$, we have  that 
	\begin{align*}
	[Y_i,Y_j](f) & = \sum \langle Y_iY_j - Y_jY_i, f_{(1)} \rangle f_{(2)} \\
	& = \sum \langle Y_i, f_{(2)}\rangle \langle Y_j, f_{(1)} \rangle f_{(3)} - \sum \langle Y_j, f_{(2)} \rangle \langle Y_i, f_{(1)}\rangle f_{(3)} \\
	&= \sum \langle X_i, f_{(2)}\rangle \langle X_j, f_{(1)} \rangle f_{(3)} - \sum \langle X_j, f_{(2)} \rangle \langle X_i, f_{(1)}\rangle f_{(3)} \\
	&= \sum \langle X_jX_i - X_i X_j,f_{(1)}\rangle f_{(2)} = \sum \langle C_{ji}^k X_k,f_{(1)}\rangle f_{(2)} \\
	& = \sum C_{ji}^k \langle Y_k, f_{(1)}\rangle f_{(2)} = \left(\sum C_{ji}^k Y_k\right)(f).
	\end{align*}
\end{proof}
\begin{proposition}\label{prop:comm}
	Every left invariant derivation commutes with every right invariant derivation  in $\mathcal{D}$.	

\end{proposition} 
\begin{proof}
	For case (I), this is well known. For case (II), see Proposition I.2.2. in \cite{Hochschild}. 	
\end{proof} 
\begin{theorem}\label{prop:OO} 
	Let $\nu_1,\ldots,\nu_n$ be a basis for $\mathcal L$. Denote by $X_1,\ldots, X_n$ the corresponding basis of the Lie algebra $\gL$ of left invariant derivations of $\mathcal F$, and by $Y_1,\ldots, Y_n$ the corresponding basis of the Lie algebra $\gR$ of right invariant derivations of $\mathcal F$, that is, the ones such that $\epsilon \circ X_i = \epsilon \circ Y_i = \nu_i$ for every $i \in \{1,\ldots,n\}$. Denote the structure constants by $C_{ij}^k$ such that $[X_i,X_j] = \sum_k C_{ij}^k X_k$ for $i,j,k\in\{1,\ldots,n\}$. 

	Then there exist functions $$\OO^i_j, \bar\OO^i_j \in \mathcal F \cap \mathcal R, \quad i,j\in \{1,\ldots,n\} $$   such that $Y_j = \bar\OO^i_j X_i$ and $X_j = \OO^i_j  Y_i$ as elements of $\mathcal D$. Furthermore, these functions satisfy formulas 	
	\begin{equation}
	\epsilon (X_k(\OO^i_j)) = C^i_{kj},
	\end{equation}
	\begin{equation}\sum_{l,m} C_{lm}^k {\mathcal{O}}_i^l \mathcal{O}_j^m  = \sum_{r}  \mathcal{O}_r^k C_{ij}^r, \label{COOisOC}
	\end{equation}
	\begin{equation} 
	\sum_j \mathcal{O}_j^i \bar{\mathcal{O}}_k^j = \delta_k ^i = \sum_j \bar{\mathcal{O}}_j^i \mathcal{O}_k^j, \label{ObarOisI}
	\end{equation} 
	for $i,j,k\in \{1,\ldots,n\}$.
	Let $\mathcal H \subset \mathcal F$ be any Hopf algebra with the coalgebra structure and the antipode transposed from the group structure of $G$ such that it contains functions $\OO^i_j, \bar\OO^i_j, i,j\in\{1,\ldots,n\}$. Then the Hopf algebra $\mathcal H$ structure maps on them are
	\begin{equation} 
	\Delta(\mathcal{O}_j^i)= \sum_k \mathcal{O}_k^i \otimes \mathcal{O}_j^k, \quad \Delta(\bar{\mathcal{O}}_j^i)= \sum_k \bar{\mathcal{O}}_j^k \otimes \bar{\mathcal{O}}_k^i,  
	\end{equation} 
	\begin{equation}  
	%\vspace{-1em}
	\epsilon(\mathcal{O}_j^i)= \delta_j^i = \epsilon(\bar{\mathcal{O}}_j^i), 
	\end{equation} 
	\begin{equation} 
	S(\mathcal{O}_j^i) = \bar{\mathcal{O}}_j^i, \quad S(\bar{\mathcal{O}}_j^i) = \mathcal{O}_j^i,
	\end{equation} 
	for $i,j\in \{1,\ldots,n\}$.

\end{theorem}
\begin{proof}
	For case (I), denote by $\OO(g)$ the composition $({L_g}_* \circ {R_{g^{-1}}}_*)_g \colon T_g G \to T_g G$. Then $\OO(g) (Y_\nu) = X_\nu$ for every tangent vector  $\nu \in T_eG =\mathcal L$. The right invariant derivations $Y_1,\ldots,Y_n$ comprise a basis of the module $\mathcal D$ of all smooth vector fields over $\mathcal F$. In this basis, the matrix of the operator $\OO$ is precisely the matrix of the adjoint representation $\Ad$ in the basis $\nu_1,\ldots, \nu_n$. 	
	Indeed, we have for $\Ad_g \colon T_e G \to T_e G$, $\Ad_g = (L_{g*} \circ R_{g^{-1}*})_e$,
	\begin{align*}
	\Ad_g ((Y_j)_e) & = \Ad_g ((X_j)_e) = (L_{g*} \circ R_{g^{-1}*})_e ((X_j)_e) = (R_{g^{-1}*} \circ L_{g*})_e ((X_j)_e)  \\
	& = (R_{g^{-1}*})_g (( L_{g*})_e ((X_j)_e)) =  (R_{g^{-1}*})_g ((X_j)_g)   \\
	& = \sum_i (R_{g^{-1}*})_g (\OO^i_j(g) (Y_i)_g) = \sum_j\OO^i_j(g) (R_{g^{-1}*})_g ((Y_i)_g) \\
	& = \sum_i \OO^i_j(g) (Y_i)_e,
	\end{align*}
	and therefore, we conclude that 
	\begin{equation}\label{OAd}
	\OO^i_j(g) = [\Ad_g]^i_j.
	\end{equation}
	Note that we are only comparing matrix entries here; the matrix on the left is the matrix of a linear operator on $T_gG$ with respect to the basis  $(Y_1)_g, \ldots, (Y_n)_g$ and the matrix on the right is the matrix of a linear operator on $T_eG$ with respect to the basis $(Y_1)_e, \ldots, (Y_n)_e$, equal to the basis $(X_1)_e, \ldots, (X_n)_e$. 


	Therefore, the functions $\OO^i_j$ that are the components of the matrix of $\OO$ in the basis $Y_1,\ldots,Y_n$ are representative functions, and $X_j = \sum_i \OO^i_j Y_i $ in $\mathcal D$. Denote  for every $g \in G$ the inverse of $\OO(g)$ by $\bar \OO(g)$. Then $Y_j = \sum_i \bar \OO^i_j X_i$.

	Since $\Ad_{gh} = \Ad_g \circ \Ad_h$ for every $g,h\in G$, we conclude that $$\OO^i_j(gh) = \sum_m \OO^i_m(g) \OO^m_j(h)$$ and therefore $\Delta(\OO^i_j) = \sum_m \OO^i_m\otimes \OO^m_j$. In a similar way, we conclude that $\Delta(\bar\OO^i_j) = \bar\OO^m_j \otimes \bar\OO^i_m$. Since the inverse of $\Ad_g$ is $\Ad_{g^{-1}}$, it is evident that $S(\OO^i_j) = \bar \OO^i_j $ and $S(\bar\OO^i_j) = \OO^i_j$. Since  $\epsilon(\OO^i_j) = \OO^i_j(e)$ and this is a component of matrix $\Ad_e$, we conclude that $\epsilon(\OO^i_j) = \delta^i_j$ and analogously that $\epsilon(\bar\OO^i_j) = \delta^i_j$. We calculate, for every $i,j,k \in \{1,\ldots,n\}$, 
	\begin{align*}
	\epsilon(X_k(\OO^i_j)) = &\lim_{t\to 0} \frac{d}{dt}\OO^i_j(\exp(t \nu_k)) = \lim_{t\to 0} \frac{d}{dt}[\Ad_{\exp(t \nu_k)}]^i_j \\
	& = \lim_{t\to 0} \,[\ad_{t\nu_k}]^i_j = C^i_{kj}.
	\end{align*}
	The property $C\OO\OO = \OO C$ in (\ref{COOisOC}) follows from the fact that $\Ad_g$ is a Lie algebra automorphism for every $g\in G$, with the identification $\gL \cong T_eG$, $X_i \mapsto \epsilon\circ X_i = (X_i)_e$, for $i\in\{1,\ldots,n\}$. Indeed, by writting $$\Ad_g ([X_i,X_j]_e) = [\Ad_g(X_i)_e , \Ad_g(X_j)_e], \quad \text{ for } i,j\in\{1,\ldots,n\}$$ in terms of the structure constants for $\gL$ and in terms of the matrix elements for $\Ad$ from formula (\ref{OAd}), we have that,  for every $g\in G$,
	\begin{align*}
	\Ad_g \Big(\sum_k C_{ij}^k (X_k)_e\Big) & = [\Ad_g(X_i)_e , \Ad_g(X_j)_e] \\
	\sum_k C_{ij}^k \OO_k^m(g) (X_m)_e & = \Big[\sum_l \OO^l_i(g) (X_l)_e, \sum_r \OO_j^r (g)(X_r)_e\Big] \\
	\sum_k C_{ij}^k \OO_k^m(g) (X_m)_e & = \sum_{l,r} \OO^l_i (g)\OO_j^r(g) C_{lr}^m (X_m)_e.
	\end{align*}The property $\OO \bar \OO = I = \bar\OO \OO$ in (\ref{ObarOisI}) follows from the fact that $\bar\OO(g)$ is a left and a right inverse to $\OO(g)$ for every $g \in G$. 

	For case (II), the unique functions exist by Propositions \ref{prop:isoleft} and \ref{prop:isoright} and they are representable because $\mathcal F \subset \mathcal R$. If we denote them by $\OO^ i_j$ and $\bar\OO^i_j$ such that $Y_j = \bar\OO^i_j X_i $ and $X_j = \OO^i_j Y_i$, we can prove the required equalities. Denote by $\OO$ and $\bar\OO$ matrices with components $\OO^i_j$ and $\bar\OO^i_j$ respectively. Since 
	\begin{align*}\sum_{m,i} \OO^i_m \bar\OO^m_j Y_i &= \sum_m \bar\OO^m_j X_m = Y_j = \delta^i_j Y_i, \\
	\sum_{m,i} \bar\OO^i_m \OO^m_j X_i & = \sum_m \OO^m_j Y_m = X_j = \delta^i_j X_i,
	\end{align*} for every $i \in \{ 1,\ldots, n \}$, we conclude that $\OO \bar \OO = I = \bar\OO \OO$, because the presentation of a derivation by a function and a basis of left (resp.\ right) invariant derivations is unique by Propositions \ref{prop:isoleft} and \ref{prop:isoright}. 
	Similarly, since in $\mathcal D$ we have 
	\begin{align*}
	[X_i, X_j] &= \sum_n C^n_{ij} X_n = \sum_{k,n} C^n_{ij} \OO^k_n Y_k,\\
	[X_i, X_j] &= [X_i, \sum_k \OO^k_j Y_k] \\
	&=   X_i \circ \sum_{k} \OO^k_j Y_k - \sum_k\OO^k_j  Y_k \circ X_i \\
	&= \sum_k X_i(\OO^k_j) Y_j + \sum_k \OO^k_j X_i \circ Y_j - \sum_k \OO^k_j Y_j \circ X_i \\
	&= \sum_k X_i(\OO^k_j) Y_j, \quad \text{ by Proposition } \ref{prop:comm},
	\end{align*} we conclude that $$X_i(\OO^k_j) = \sum_{n} C^n_{ij} \OO^k_n $$ and hence that 
	$$\epsilon(X_i(\OO^k_j)) = \langle \nu_i , \OO^k_j \rangle = C^k_{ij}.$$ 
	%	Furthermore, we know that 
	%	\begin{align*}
	%	[\sum_i \bar\OO^i_j X_i, X_m] 
	%	& = [Y_j, X_m] = 0,\\
	%	[\sum_i \bar\OO^i_j X_i, X_m] 
	%	&= [\sum_i \bar\OO^i_j X_i, X_m] = \sum_i \bar\OO^i_j X_i\circ  X_m - X_m \circ \sum_i \bar\OO^i_j X_i \\
	%	& = \sum_i \bar \OO^i_j X_i\circ X_m - \sum_i X_m(\bar\OO^i_j)X_i - \sum_i\bar\OO^i_j  X_m \circ X_i \\
	%	&= \sum_i \bar\OO^i_j [X_i,X_m] - \sum_i X_m(\bar\OO^i_j)X_i \\
	%	&= \sum_{i,k} \bar\OO^i_j C_{im}^k X_k - \sum_k X_m(\bar\OO^k_j)X_k ,
	%	\end{align*} we conclude that $$X_m(\bar\OO^k_j) = \sum_{i} C^k_{im} \bar\OO^i_j $$ and hence that 
	%	$$\epsilon(X_m(\bar\OO^k_j)) = C^k_{jm} = - C^k_{mj}.$$ 
	%In an analogous way, we can prove that $$Y_k(\OO^i_j) = \sum_n \tilde C^n_{kj} \OO^i_n.$$ ???
	It remains to prove $C\OO\OO = \OO C$. This follows from the identity 
	$$[X_i,X_j] = -\sum_{m,k}\OO_i^k \OO_j^m [Y_k,Y_m], \text{ for all } i,j \in \{1,\ldots,n\}$$ because this identity is equivalent to 
	$$C_{ij}^n \OO^k_n Y_k = C^k_{sm} \OO_i^s \OO_j^m Y_k, \text{ for all } i,j,k \in \{1,\ldots,n\},$$ 
	by using $[Y_i,Y_j] = -C_{ij}^k Y_k$ from Proposition \ref{minus}. 
	We have that 
	\begin{align*}
	[X_i,X_j] &=  [\sum_m \OO_i^m Y_m, \sum_k \OO^k_j Y_k] \\
	&= \sum_m \OO_i^m Y_m \circ \sum_k \OO^k_j Y_k -  \sum_k \OO^k_j Y_k \circ \sum_m \OO_i^m Y_m \\
	&= \sum_{m,k} \OO_i^m Y_m (\OO^k_j) Y_k  +  \sum_{m,k} \OO_i^m  \OO^k_j [Y_m, Y_k] -  \sum_{m,k} \OO^k_j Y_k (\OO_i^m) Y_m \\
	& = \sum_{k} X_i (\OO^k_j) Y_k +  \sum_{m,k} \OO_i^m  \OO^k_j [Y_m, Y_k] - \sum_{m} X_j (\OO_i^m) Y_m .
	\end{align*}	
	We have that
	\begin{align*}
	\sum_{k} X_i (\OO^k_j) Y_k  - \sum_{m} X_j (\OO_i^m) Y_m 
	&= \sum_{k,n} C^n_{ij}\OO_n^k Y_k  - \sum_{m,n} C^n_{ji}\OO^m_n Y_m \\
	& = \sum_{n} C_{ij}^n X_n   - \sum_{n} C^n_{ji}X_n \\
	& = [X_i,X_j] - [X_j,X_i] = 2[X_i,X_j],
	\end{align*}
	and therefore we conclude that 
	$$[X_i,X_j] + \sum_{m,k} \OO_i^m  \OO^k_j [Y_m, Y_k] = 0. $$ 
\end{proof}	

\begin{definition} Denote by $\OO^{min}(G)$ the smallest Hopf subalgebra of $\mathcal R \cap \mathcal F$ that contains functions $\OO^i_j, \bar\OO^i_j ,i,j\in \{1,\ldots,n\} $ from Theorem \ref{prop:OO}, in both cases (I) and~(II).
\end{definition}



\subsection{Left coaction}




\begin{theorem}\label{prop:lambdaO} The map $\gL \to \mathcal L \to \gR \hookrightarrow \mathcal F \otimes \gL$, that sends the left invariant derivation to the corresponding right invariant one written as an element of $\mathcal F \otimes  \gL$, extends to a unique antimultiplicative unital linear map $\lambda \colon \UgL \to  \mathcal F \sharp_{\str} \UgL$.

Furthermore, for every Hopf algebra $\mathcal H$ such that $\OO^{min}(G) \subset \mathcal H  \subset \mathcal F \cap\mathcal R$, the corestriction $$\lambda \colon \UgL \to \mathcal H \sharp_{\str} \UgL$$ exists and it is a left coaction. The elements of $\Img \lambda$ commute with the elements of $1\sharp \UgL$ in $\mathcal H \sharp \UgL$.

\end{theorem}
\begin{proof}

		(i) We prove that such $\lambda$ exists. We first define an auxiliary map $\tilde\lambda$ as a linear map $\gL \to \mathcal H \sharp U(\gL)$ such that $\tilde\lambda (X_j) = \sum_i \bar{\mathcal{O}}_j^i \sharp X_i$ for $j \in \{1,\ldots,n\}$ and expand it to $\tilde \lambda \colon T(\gL) \to \mathcal H \sharp U(\gL)$ by antimultiplicativity, and then we check that $\tilde\lambda([X,Z] - X\otimes X' + X'\otimes X) = 0$ for every $X,X' \in \gL$. We have 
		\begin{align*} \tilde\lambda(X_j) \cdot \tilde\lambda(X_i) &= (\sum_k \bar{\mathcal O}_j^k\sharp X_k) \cdot( \sum_m \bar{\mathcal O}_i^m \sharp X_m) = \sum_{k,m,p} \bar{\mathcal O}_j^k \bar{\mathcal O}^p_i (X_k \btl \bar{\mathcal O}_p^m) X_m \\
		& = \sum_{k,m,p} \bar{\mathcal O}_j^k \bar{\mathcal O}^p_i \sharp (\delta_p^m X_k  - C_{kp}^m) X_m   \\
		&= \sum_{k,m} \bar{\mathcal O}_j^k \bar{\mathcal O}^m_i \sharp X_k X_m - \sum_{k,m,p} \bar{\mathcal O}_j^k \bar{\mathcal O}^p_i  C_{kp}^m\sharp X_m  
		\end{align*}
		and, analogously, we have
		\begin{align*}
		\tilde\lambda(X_i) \cdot \tilde\lambda(X_j) &= \sum_{k,m} \bar{\mathcal O}^m_i \bar{\mathcal O}^k_j \sharp X_m X_k  - \sum_{k,m,p} \bar{\mathcal O}^m_i \bar{\mathcal O}^p_j  C_{mp}^k\sharp X_k.
		\end{align*}  
		On the other hand, we have
		$$\tilde\lambda([X_i,X_j]) = \tilde\lambda(\sum_p C^p_{ij} X_p) = \sum_{p,m} C_{ij}^p \bar{\mathcal O}_{p}^m \sharp X_m.$$
		Equality $\tilde\lambda(X_j)\tilde\lambda(X_i) - \tilde\lambda(X_i)\tilde\lambda(X_j) = \tilde\lambda([X_i,X_j])$ now follows from commutativity of $\mathcal H$ and identities $$\sum_{l,m} C_{lm}^k \bar{\mathcal{O}}_i^l \bar{\mathcal{O}}_j^m = \sum_{r} \bar{\mathcal{O}}_r^k C_{ij}^r , \qquad  i,j, k \in \{1,\ldots,n\},$$ 
		which are easily deduced from   
		$$\sum_{l,m} C_{lm}^k{\mathcal{O}}_i^l \mathcal{O}_j^m = \sum_{r}  \mathcal{O}_r^k C_{ij}^r, \qquad  i,j, k\in \{1,\ldots,n\}.$$ Therefore, by quotienting the domain of $\tilde \lambda$ with the ideal generated by all elements of the form $[X,X'] - X\otimes X' + X'\otimes X$, where $X\in \gL$, we induce a well defined map $\lambda \colon U(\gL) \to \mathcal H \sharp U(\gL)$.
		Additionally, we note that clearly 
		\begin{equation}\label{eq:antimult} 
		\lambda(DP) = \lambda(P)\lambda(D),\quad \text{ for all } D,P \in U(\gL).
		\end{equation}
		(ii) We prove that the elements of $\operatorname{Im}\lambda $ commute with the elements of $1\sharp \UgL$ in $\mathcal H\sharp \UgL$.
		First we check this for generators. For any $j,k \in \{1,\ldots,n\}$ we have
		\begin{align*}
		X_k \cdot \lambda(X_j) &=  X_k \cdot \sum_i  \bar{\mathcal O}_j^i \sharp X_i = \sum_{i,m} \bar\OO^m_j \sharp(X_k \btl \bar{\mathcal O}_m^i ) X_i \\
		&=		\sum_{i,m} \bar\OO^m_j \sharp(\delta_m^i X_k + C_{mk}^i)X_i = \sum_{m} \bar\OO^m_j \sharp(X_k X_m + [X_m,X_k]) = \\
		&= 	\sum_{m} \bar\OO^m_j \sharp X_m X_k = \lambda(X_j) \cdot X_k.
		\end{align*} Then by using antimultiplicativity (\ref{eq:antimult}) of $\lambda$, it is easy to prove the claim inductively for all elements of $\UgL$,
		\begin{equation}\label{eq:imacom}
		P \cdot \lambda(D) = \lambda(D) \cdot P, \quad \text{ for all } D,P \in \UgL.
		\end{equation}  


		(iii) We prove that $\lambda$ is a coaction. First, we prove that if the coassociativity identity is true for  $D,P \in U(\gL)$, then it is true for the product $DP \in U(\gL)$. We use these properties: $\lambda$ is an antihomomorphism of algebras as proven in (i), $\btl$ is a Hopf action, properties (\ref{eq:imacom}) proven in (ii), and compatibility of comultiplication and multiplication of $\mathcal H$. We thus have that
		\begin{align}\lambda(DP) &= \lambda(P) \lambda(D) = \sum P_{[-1]}\sharp P_{[0]} \cdot \lambda(D) = \nonumber \\
		&= \sum P_{[-1]} \cdot \lambda(D) \cdot P_{[0]} \quad \text{ by (\ref{eq:imacom})} \nonumber\\
		&= \sum P_{[-1]} D_{[-1]} \sharp D_{[0]} P_{[0]}  \label{eq:coabc}
		\end{align}
		from which it follows, assuming the coassociativity identity holds for $D$ and $P$,
		\begin{align*}
		((\id \otimes \lambda)\circ \lambda)(PD) 
		& = \sum D_{[-1]} P_{[-1]} \otimes \lambda( P_{[0]} D_{[0]})  \\
		&=  \sum D_{[-1]} P_{[-1]} \otimes D_{[0][-1]} P_{[0][-1]} \otimes P_{[0][0]} D_{[0][0]} \\
		& = \sum D_{[-1](1)} P_{[-1](1)} \otimes D_{[-1](2)} P_{[-1](2)} \otimes P_{[0]} D_{[0]} \\
		& = \sum (D_{[-1]} P_{[-1]})_{(1)} \otimes (D_{[-1]}P_{[-1]})_{(2)}  \otimes P_{[0]} D_{[0]}
		\end{align*}
		and, on the other hand,  
		\begin{align*}
		((\Delta \otimes \id) \circ \lambda)(PD) & = (\Delta \otimes \id)(\sum D_{[-1]} P_{[-1]} \sharp P_{[0]} D_{[0]}) \\
		& = \sum (D_{[-1]}P_{[-1]})_{(1)} \otimes (D_{[-1]}P_{[-1]})_{(2)}  \otimes P_{[0]} D_{[0]}.
		\end{align*}
		Now we see that it is sufficient to check the claim on generators, and this is trivial:
		$$\sum_{k,i} \bar{\mathcal O}_j^k \otimes \bar{\mathcal O}_k^i \sharp X_i = \sum_{i,m} \bar{\mathcal O}_j^i \otimes \bar{\mathcal O}_i^m \sharp X_m.$$
		This proves the coassociativity of $\lambda$. The counitality of $\lambda$ is checked similarly, first on generators, for every $j\in \{1,\ldots,n\}$, $((\epsilon \otimes \id) \circ \lambda)(X_j) = \epsilon(\bar\OO^i_j) X_i = X_j,$ and then easily proven inductively by using formula (\ref{eq:coabc}).




\end{proof}


\begin{theorem}\label{prop:lambdaOR} The map $\gR \to \mathcal L \to \gL \hookrightarrow \mathcal F \otimes \gR$, that sends the right invariant derivation to the corresponding left invariant one written as an element of $\mathcal F \otimes  \gR$, extends to a unique antimultiplicative unital linear map $\lambda \colon \UgR \to  \mathcal F \sharp_{\str} \UgR$.

Furthermore, for every Hopf algebra $\mathcal H$ such that $\OO^{min}(G) \subset \mathcal H  \subset \mathcal F$, the corestriction $$\lambda \colon \UgR \to \mathcal H \sharp_{\str} \UgR$$ exists and it is a left coaction. The elements of $\Img \lambda$ commute with the elements of $1\sharp \UgL$ in $\mathcal H \sharp \UgL$.
\end{theorem}
\begin{proof}
	Analogous to the proof of Theorem \ref{prop:lambdaO}.
\end{proof}

\subsection{Right action that produces the same smash product algebra}

\begin{proposition}\label{prop:rightact} Maps  
	$$\btl \colon \UgL \otimes \mathcal H \to \UgL, \quad \btl \colon \UgR \otimes \mathcal H^\co \to \UgR$$ defined by the same formula 
	$$D \btl f = \langle D_{(1)}, f \rangle D_{(2)}, \quad \text{ for } f \in \mathcal H \text{ and } D \in \UgL \text{ or } \UgR,$$ are right Hopf actions and they induce smash product algebras isomorphic to the ones induced by the left actions in Proposition \ref{prop:smash},
	$$\mathcal H \sharp_{\str} \UgL \cong \mathcal H \sharp_{\btl} \UgL, \quad \mathcal H \sharp_{\str} \UgR \cong \mathcal H^\co \sharp_{\btl} \UgR.$$


\end{proposition}
\begin{proof} See Proposition \ref{prop:leftright}.
\end{proof}
\subsection{Yetter--Drinfeld property and the main theorem}

\begin{theorem}\label{prop:YDO} Let a Hopf algebra $\mathcal H$ be a subalgebra of $\mathcal F$ with the coalgebra structure and the antipode transposed from the group structure on $G$ and assume that $\OO^{min}(G) \subset \mathcal H$. 

	Then $(\UgL, \btl, \lambda)$ is a  braided commutative Yetter--Drinfeld module algebra over~$\mathcal H$. Similarly, $(\UgR, \btl, \lambda)$  is a  braided commutative Yetter--Drinfeld module algebra over~$\mathcal H^\co$. Here symbols $\btl$ and $\lambda$ denote the appropriate action and coaction in each case, from Proposition \ref{prop:rightact} and Theorems \ref{prop:lambdaO} and \ref{prop:lambdaOR}.

\end{theorem}
\begin{proof} (i) We prove the Yetter--Drinfeld property for $(\UgL, \btl, \lambda)$,
	$$\sum f_{(2)} \cdot \lambda(D\btl f_{(1)}) = \lambda(D) \cdot f, \quad \text{ for all } D\in \UgL \text{ and } f\in \mathcal H.$$ 
	It is sufficient to prove this for generators  $X_k, 1_{\UgL} \in \UgL$, because $\btl$ is a Hopf action and $\lambda$ is antimultiplicative. Indeed, if we assume that the equality holds for some $D$ and $P$ in $\UgL$ and every $f\in\mathcal H$, then it also holds for the product $DP$ and all $f\in\mathcal H$, by
	\begin{align*}
	\sum f_{(2)} \lambda((DP) \btl f_{(1)}) & = \sum f_{(3)} \lambda((D \btl f_{(1)})(P \btl f_{(2)})) \\
	& = \sum f_{(3)} \lambda(P \btl f_{(2)})\lambda(D \btl f_{(1)}) \\
	& =\sum\lambda(P)\cdot f_{(2)} \lambda(D \btl f_{(1)}) \\
	&= \lambda(P) \lambda(D) \cdot f \\
	&= \lambda(DP) \cdot f.
	\end{align*}
	The check for $1_{\UgL}$ is trivial. Let us prove the claim now for generators:	
	$$f_{(2)} \lambda(X_k \btl f_{(1)}) = \lambda(X_k) \cdot f, \quad \text{ for every } k \in \{1,\ldots,n\} \text{ and every } f \in \mathcal H.$$ By the definition of the right action of $\mathcal H$ on $\UgL$, this is $$f_{(2)}\langle (X_k)_{(1)}, f_{(1)} \rangle \lambda((X_k)_{(2)}) = \lambda(X_k) \cdot f,$$ and since $\Delta(X_k) = X_k \otimes 1 + 1 \otimes X_k$ and the pairing is Hopf, we have that this is $$f_{(2)}\langle X_k, f_{(1)} \rangle \lambda(1) + f_{(2)}\langle 1, f_{(1)} \rangle \lambda(X_k) = \lambda(X_k) \cdot f,$$ that is $$f_{(2)}\langle X_k, f_{(1)} \rangle + f \lambda(X_k) = \lambda(X_k) \cdot f.$$ 
	Since $\langle X_k, f \rangle = \langle Y_k, f \rangle$ for all $f \in \mathcal H$, this is equivalent to $$f_{(2)}\langle Y_k, f_{(1)} \rangle + f \lambda(X_k) = \lambda(X_k) \cdot f,$$ that is $$Y_k \str f = Y_k \cdot f - f \cdot Y_k,$$ which holds because this left action is a differentiation by a right invariant derivation. 


	(ii) The comodule algebra property follows from the antimultiplicativity of $\lambda$ and the commuting of elements of $\Img \lambda$ with elements of $1\sharp \UgL$, proven in Theorem~\ref{prop:lambdaO}.  

	(iii) The braided commutativity property is: 
	\begin{equation}\label{eq:lambdact} P \btl \lambda(D) = DP, \quad \text{ for all } D,P \in U(\gL).
	\end{equation} First we check this on generators. For any $j,k \in \{1,\ldots,n\}$ we have
	$$X_k \btl \sum_i \bar{\mathcal O}_j^i \sharp X_i = \sum_i (\delta_j^i X_k X_i + C_{jk}^i X_i) = X_k X_j + [X_j,X_k] = X_j X_k.$$ 
	Next, we use induction on the length of the word acted on by $\lambda(X_j)$ on the right, for every $X_j, j\in\{1,\ldots,n \}$. The step of induction is: 
	$$(PD) \btl \sum_i \bar{\mathcal O}_j^i \sharp X_i = \sum_{i,m} (P  \btl  \bar{\mathcal O}_j^m)(D \btl \bar{\mathcal O}_m^i )X_i = \sum_{i,m} (P  \btl  \bar{\mathcal O}_j^m)X_m D =  X_j PD.$$ 
	At last, we use induction on the length of the word on the right. The step of induction is:
	$$D\btl \lambda(PT) = (D \btl \lambda(T)) \btl \lambda(P) = (TD) \btl \lambda(P) = PTD.$$

	The proof of (i), (ii) and (iii) for $(\UgR, \btl,\lambda)$ is analogous.
\end{proof}

\begin{corollary}
	Let a Hopf algebra $\mathcal H$ be a subalgebra of $\mathcal F$ with the coalgebra structure and the antipode transposed from the group structure on $G$ and assume that $\OO^{min}(G) \subset \mathcal H$. 

	Then $\mathcal H \sharp \UgL \cong \UgR \sharp \mathcal H$ is a scalar extension Hopf algebroid over base algebras $\UgR, \UgL$ and the isomorphic algebra $\mathcal H^\co \sharp \UgR \cong \UgL \sharp \mathcal H^\co$ is a scalar extension Hopf algebroid over base algebras $\UgL, \UgR$

\end{corollary}
\begin{proof}
	See Remark 4.1 and Theorem 4.2 in \cite{stojic}.
\end{proof}


\section{Yetter--Drinfeld module algebra over a Hopf algebra of functionals}

Here we consider case (III) described in Section \ref{sec:cases}.  Let now $\ggf$ be any finite-dimesional Lie algebra over any field $\genfd$. Denote by $\Ug^*$ the dual of the universal enveloping algebra $\Ug$. The Hopf algebra structure on the finite dual $\Ug^\circ \subset \Ug^*$ is such that the restriction $\Ug \otimes \Ug^\circ \to \genfd$ of the canonical pairing $\Ug \otimes \Ug^* \to \genfd$ is a Hopf pairing.

\subsection{Definition of Hopf algebra $\Ug^{min}$}

We now choose a basis of $\ggf$ and define matrices $\UU \in M_n(\Ug^\circ)$ and $\bar{\UU} \in M_n(\Ug^\circ)$ such that, if there were an affine algebraic group whose Lie algebra is $\ggf$, functionals that are components of $\UU$ would pair with $\Ug$ precisely as functions that are components of~$\OO$, that is, the smallest Hopf algebra $\Ug^{min}$ generated by these functionals would be the image of $\OO^{min}(G)$ in $\Ug^*$ under mapping $\OO(G) \to \Ug^*$ defined by $f \mapsto \langle - , f \rangle$ for $f\in \OO(G)$.
$$
\begin{tikzcd}
\Ug^* & \ar{l}{} \OO(G)  & \\
\Ug^{min} \ar[hook]{u}  &  \ar[two heads]{l} \OO^{min}(G) \ar[hook]{u}  & \text{ for }\ggf = \gL & &
\end{tikzcd}
$$
All maps in the diagram are Hopf algebra morphisms that commute with the pairings with $\Ug$, provided that we assume the completed version of a Hopf algebra structure on $\Ug$. Similarly, for the right invariant case, we have the diagram
$$
\begin{tikzcd}
\Ug^* & \ar{l}{} \OO(G)^\co  & \\
\Ug^{min} \ar[hook]{u}  &  \ar[two heads]{l} \OO^{min}(G)^\co \ar[hook]{u}  & \text{ for }\ggf = \gR. & &
\end{tikzcd}
$$
We do this by requiring that $\langle X,\UU\rangle$ is the matrix presentation of $\ad_X$ with respect to the chosen basis and that $\langle X,\bar\UU\rangle$ is the matrix presentation of $-\ad_X$ with respect to the chosen basis, for every $X \in \ggf$, and such that certain equations regarding the comultiplication of their components hold. 

\begin{theorem}\label{prop:U}
	Let $X_1,\ldots, X_n$ be a basis for a Lie algebra $\ggf$ over a field $\genfd$. Let the structure constants $C^i_{jk}$ be defined from $[X_i,X_j] = \sum_k C^i_{jk} X_k$, for $i,j\in \{1,\ldots,n\}$.

	Then there exist unique functionals $$\UU^i_j, \bar\UU^i_j \in \Ug^\circ, \quad i,j\in \{1,\ldots,n\} $$   such that, for all $i,j,k \in \{1,\ldots,n\}$, 	
	$$\langle X_k, \UU^i_j \rangle = C^i_{kj},  $$
	$$\Delta(\mathcal{U}_j^i)= \sum_k \mathcal{U}_k^i \otimes \mathcal{U}_j^k, \quad \Delta(\bar{\mathcal{U}}_j^i)= \sum_k \bar{\mathcal{U}}_j^k \otimes \bar{\mathcal{U}}_k^i,   $$ 
	\vspace{-1em}
	$$ \epsilon(\mathcal{U}_j^i)= \delta_j^i = \epsilon(\bar{\mathcal{U}}_j^i), $$
	$$S(\mathcal{U}_j^i) = \bar{\mathcal{U}}_j^i, \quad S(\bar{\mathcal{U}}_j^i) = \mathcal{U}_j^i.$$
	These functionals satisfy the following identities, for all $i,j,k\in \{1,\ldots,n\}$,
	\begin{align}
	&\sum_{l,m} C_{lm}^k {\mathcal{U}}_i^l \mathcal{U}_j^m = \sum_{r}  \mathcal{U}_r^k C_{ij}^r, \label{ccu}\\
	&\sum_j \mathcal{U}_j^i \bar{\mathcal{U}}_k^j = \delta_k ^i = \sum_j \bar{\mathcal{U}}_j^i \mathcal{U}_k^j. \label{cui}
	\end{align}
\end{theorem} 
\begin{proof} 

	\emph{Uniqueness.}  If matrices $\UU,\bar\UU \in M_n(\Ug^\circ)$ with these properties exists, then they are unique since for all $i,j\in \{1,\ldots,n\}$ we have that 
	$$\langle X_{i_1} \cdots X_{i_m}, \UU^i_j  \rangle = \langle  X_{i_1} \otimes \cdots \otimes X_{i_m}, \Delta_{m}(\UU^i_j) \rangle, \quad \text{ for all } X_{i_1},\ldots,X_{i_n} \in \ggf $$ and comultiplication of $\UU^i_j$ is written in terms of tensor products of these functionals. Next, we have for all $i,j\in \{1,\ldots,n\}$ 
	$$\langle  X_{i_1} \cdots X_{i_m}, \bar\UU^i_j \rangle = \langle  S(X_{i_1} \cdots X_{i_m} ), \UU^i_j\rangle, \quad \text{ for all } X_{i_1},\ldots,X_{i_n} \in \ggf .$$

	\emph{Existence and formulas.} Denote by $\mathcal{C}_k = [C_{kj}^i]^i_j$ the matrix of $\ad_{X_k}$ in this basis. 
	We define $\UU$ and $\bar\UU$ first as elements of $M_n(T(\ggf)^*)$ by
	$$\langle 1, \UU \rangle = I = \langle 1, \bar\UU \rangle$$ 
	$$\langle X_{i_1} \cdots X_{i_m}, \UU \rangle = \mathcal{C}_{i_1} \cdots \mathcal{C}_{i_m}, \quad \langle X_{i_1} \cdots X_{i_m}, \bar\UU \rangle = (-1)^{m} \mathcal{C}_{i_m} \cdots \mathcal{C}_{i_1}$$ 
	and then check that they are well defined as elements of $M_n(\Ug^*)$. We have that
	\begin{align*}
	\langle [X_i,X_j], \UU^k_m \rangle &= \langle \sum_s C_{ij}^s X_s,\UU^k_m \rangle = \sum_s C_{ij}^s C^k_{sm}.
	\end{align*}
	Next, we have that
	\begin{align}
	\sum_k \langle X_iX_j - X_j X_i, \mathcal U^k_m \rangle X_k 
	&= \sum_{k,s} C_{is}^k C_{jm}^s X_k - C^k_{js}  C^s_{im} X_k \nonumber\\
	& = \sum_{s} [X_i,X_s] C_{jm}^s- \sum_s [X_j,X_s]   C^s_{im} \nonumber \\
	& = [X_i,[X_j,X_m]] - [X_j,[X_i,X_m]] \nonumber \\ 
	&= [[X_i,X_j], X_m] = \sum_{s,k} C_{ij}^s C_{sm}^k X_k \label{cc}
	\end{align}
	from which we conclude that $$\langle X_iX_j - X_j X_i, \mathcal U^k_m \rangle = \sum_{s} C_{ij}^s C_{sm}^k.$$
	The claim for generators $\bar\UU^i_j$ is proven analogously. Therefore, they are well defined as elements of $\Ug^*$. It is easy to verify that the Hopf algebra structure maps indeed are as should be. Therefore, $\UU, \bar\UU \in M_n(\Ug^\circ)$. 

	\emph{Identities}. The identity (\ref{ccu}) is proven as follows. For every $i,j,k,s \in \{1,\ldots,n\}$
	\begin{align*}
	\langle  X_s, \sum_{l,m} C_{lm}^k {\mathcal{U}}_i^l \mathcal{U}_j^m \rangle 
		&= \sum_{l,m} C_{lm}^k  \langle X_s, {\mathcal{U}}_i^l  \rangle \delta_j^m + \sum_{l,m} C_{lm}^k \delta_i^l \langle    X_s , \mathcal{U}_j^m \rangle \\
		&= \sum_{l} C_{lj}^k  C^l_{si} + \sum_{m} C_{im}^k  C_{sj}^m, \\
	\langle \sum_{r}  \mathcal{U}_r^k C_{ij}^r ,X_s \rangle 
		&= \sum_{r}  C^k_{rs}C^r_{ij}.
		\end{align*}
	The equality is now proven similarly as in calculation (\ref{cc}). 

\end{proof}	

