\subsection{Yetter--Drinfeld property and the main theorem}
\begin{theorem} Let $\ggf$ be a finite-dimesional Lie algebra over any field $\genfd$. Let $\mathcal H$ be any Hopf algebra such that $\Ug^{min} \subset \mathcal H \subset \Ug^\circ$. 
	Then the non-degenerate pairing $\Ug \otimes\mathcal  H \to \genfd$ induces a unique right Hopf action $\btl \colon \Ug \otimes\mathcal  H \to \Ug$ such that $\langle D\btl f, k \rangle = \langle D, fk\rangle$ for all $D \in \Ug$ and all $f,k \in\mathcal  H$ and this action induces a smash product algebra structure $\mathcal H \sharp \Ug$. 

	Let $\lambda \colon \Ug \to\mathcal  H \sharp \Ug$ be as defined in Proposition \ref{prop:lambdaU}. Then $(\Ug,\btl, \lambda)$ is a braided commutative Yetter--Drinfeld module algebra over $\mathcal H$.
\end{theorem}
\begin{proof} (i) We prove the Yetter--Drinfeld property:
	$$\sum f_{(2)} \cdot \lambda(X\btl f_{(1)}) = \lambda(X) \cdot f, \quad \text{ for all } X\in \UgL \text{ and } f\in\mathcal  H.$$

	It is sufficient to prove this for generators  $X_k, 1_{\Ug} \in \Ug$ because we have that: $\btl$ is a Hopf action and $\lambda$ is an antihomomorphism of algebras. Indeed, if we assume that the equality holds for $X$ and $X'$ in $\Ug$, then it also holds for $XX'$:
	\begin{align*}
	\sum f_{(2)} \lambda((XX') \btl f_{(1)}) & = \sum f_{(3)} \lambda((X \btl f_{(1)})(X' \btl f_{(2)})) \\
	& = \sum f_{(3)} \lambda(X' \btl f_{(2)})\lambda(X \btl f_{(1)}) \\
	& =\sum\lambda(X')\cdot f_{(2)} \lambda(X \btl f_{(1)}) \\
	&= \lambda(X') \lambda(X) \cdot f \\
	&= \lambda(XX') \cdot f.
	\end{align*}
	The check for $1_{\Ug}$ is trivial. Let us prove the claim now for generators:	
	$$f_{(2)} \lambda(X_k \btl f_{(1)}) = \lambda(X_k) \cdot f, \quad \text{ for every } k \in \{1,\ldots,n\} \text{ and every } f \in H.$$ 
	Extend the Hopf action $\str \colon \Ug \otimes\mathcal  H \to\mathcal  H$ defined by $D \str f = f_{(1)} \langle D,f_{(2)}\rangle$, to an action of the whole smash product algebra $\str \colon\mathcal  H \sharp \Ug \otimes\mathcal  H \to\mathcal  H $ by formula $f \sharp D \str g := f \cdot (D\str g)$ for $f,g \in \mathcal  H$ and $D \in \Ug$. The action $\btl \colon \Ug \otimes\mathcal  H \to \Ug$ also extends to an action of the whole smash product algebra $\btl \colon \Ug \otimes\mathcal  H\sharp \Ug \to \Ug$ by formula $X \btl f \sharp Z = (X \btl f) Z$. It is proven in Proposition \ref{prop:lambdaU} that the elements of $\Img \lambda$ commute with the elements of $1\sharp \Ug$ in $\mathcal H \sharp \Ug$. The pairing of $\Ug$ with $\mathcal H$ has the property $\langle D , f \rangle = \langle 1, D \str f \rangle$, and we extend it to the pairing $\mathcal H \sharp \Ug \otimes\mathcal  H \to \genfd$ by formula $\langle f\sharp D , g \rangle = \langle 1, (f\sharp D)\str g\rangle$, for for $f,g \in \mathcal  H$ and $D \in \Ug$. 
	Now we check the Yetter--Drinfeld property equation for $X\in \ggf$ and $f \in\mathcal  H$,
	$$\langle X, f_{(1)}\rangle f_{(2)} = \lambda(X) \cdot f - f \cdot \lambda(X).$$ 
	First, we check that $$\lambda(X) \str f = \lambda(X) \cdot f - f \cdot \lambda(X), \quad \text{ for all }X \in \ggf\text{ and }	f\in\mathcal  H,$$ 
	which is straightforward and uses the  commutativity of $\mathcal H$. 
	 Next, we prove that $$\langle X, f_{(1)}\rangle f_{(2)} = \lambda(X) \str f, \quad \text{ for all }X \in \ggf \text{ and } 
	f\in\mathcal  H. $$ Since the pairing is non-degenerate in the second variable, this is equivalent to  
	$\langle D, \langle X, f_{(1)} \rangle f_{(2)} \rangle = \langle D ,\lambda(X) \str f \rangle$ being true for all $X\in\ggf$, $ D\in\Ug$ and $f\in\mathcal  H$. The equation is $\langle X, f_{(1)}\rangle \langle D, f_{(2)} \rangle = \langle D \lambda(X), f \rangle $, that is $\langle XD, f \rangle = \langle D \lambda(X), f \rangle$. Since the elements of the image of $\lambda$ commute with the elements of $\Ug$, this is then $\langle XD, f \rangle = \langle \lambda(X) D, f \rangle$. For $X \in \ggf$ it is easy to check that $\langle XD, f \rangle = \langle \lambda(X)D, f \rangle$, by using $\epsilon(\UU) = I$.  

	(ii) The comodule algebra property and (iii) the braided commutativity property are proven in the same way as those properties in the proof of Theorem \ref{prop:YDO}.
\end{proof}

\begin{corollary}
	Let $\mathcal H$ be a subalgebra of $\UgL^*$ that is in a Hopf pairing with $\UgL$ and assume that $\UgL^{min} \subset \mathcal H$. 

	Then $\mathcal H \sharp \UgL \cong \UgR \sharp \mathcal H$ is a scalar extension Hopf algebroid over base algebras $\UgR, \UgL$ and the isomorphic algebra $\mathcal H^\co \sharp \UgR \cong \UgL \sharp \mathcal H^\co$ is a scalar extension Hopf algebroid over base algebras $\UgL, \UgR$.

\end{corollary}
\begin{proof}
	See Remark 4.1 and Theorem 4.2 in \cite{stojic}.
\end{proof}


\section{Theorem with all intermediate algebras} 
\begin{theorem} \label{prop:general}
	Let $\ggf$ be a finite-dimensional Lie algebra over a field $\genfd$, with structure constants $C^k_{ij}$ determined from $$[X_i,X_j] = C^k_{ij} X_k, \quad \text{ for } i,j\in\{1,\ldots,n\}.$$ Let $\mathcal H$ be a Hopf $\genfd$-algebra in a  Hopf pairing $\langle\,,\rangle \colon \Ug \otimes \mathcal H \to \genfd$ with $\Ug$. 

	If there exist some elements $\mathcal{O}^i_j, \bar{\mathcal{O}}^i_j, i,j\in \{1,\ldots,n\}$ of $\mathcal H$  such that %they generate all elements of $H$ as an algebra and such that	
	$$\langle X_k, \OO^i_j \rangle = C^i_{kj}, $$
	$$\sum_{l,m} C_{lm}^k {\mathcal{O}}_i^l \mathcal{O}_j^m = \sum_{r}  \mathcal{O}_r^k C_{ij}^r, $$ 
	$$\sum_j \mathcal{O}_j^i \bar{\mathcal{O}}_k^j = \delta_k ^i = \sum_j \bar{\mathcal{O}}_j^i \mathcal{O}_k^j, \quad \text{ for all } i,j,k\in \{1,\ldots,n\}$$
	and such that the coalgebra structure maps and the antipode of $\mathcal H$ satisfy 
	$$\Delta(\mathcal{O}_j^i)= \sum_k \mathcal{O}_k^i \otimes \mathcal{O}_j^k, \quad \Delta(\bar{\mathcal{O}}_j^i)= \sum_k \bar{\mathcal{O}}_j^k \otimes \bar{\mathcal{O}}_k^i,   $$ 
	\vspace{-1em}
	$$ \epsilon(\mathcal{O}_j^i)= \delta_j^i = \epsilon(\bar{\mathcal{O}}_j^i),  $$
	$$S(\mathcal{O}_j^i) = \bar{\mathcal{O}}_j^i, \quad S(\bar{\mathcal{O}}_j^i) = \mathcal{O}_j^i, \quad \text{ for all } i,j \in \{1,\ldots,n\}$$
	and if any one of these conditions is met: 
	\begin{itemize}
		\item[(a)] %$H$ is commutative with $S = S^{-1}$ and there is a Hopf action $\str \colon \Ug \otimes H \to \genfd $ such that $X \str f = \langle X, f_{(1)} \rangle f_{(2)}$ and a Hopf action $\str \colon \Ug^\op \otimes H \to \genfd$ such that $Y \str f = \langle \phi(Y), f_{(2)} \rangle f_{(1)}$, where $\phi \colon \Ug^\op \to \Ug$ antiisomorphism, such that $H \sharp \Ug \cong H^\co \sharp \Ug^\op$ via $h \mapsto h, X \mapsto \sum \OO^i_j \sharp Y_j$ 
		$\genfd$ is $\mathbb{R}$ or $\mathbb{C}$, $G$ is a Lie group, $\mathcal H \subset C^\infty(G)$ as an algebra and its coalgebra structure and antipode are transpose of the group structure of $G$, and $\OO^i_j,\bar{\OO}^i_j, i,j\in \{1,\ldots,n\}$ are exactly compontents of the matrix of $\Ad$ and its inverse in the chosen basis of $\ggf$, or
		\item[(b)] $\genfd$ is $\mathbb{R}$ or $\mathbb{C}$, $G$ is a Lie group, $\mathcal H \subset C^\infty(G,e)$ as an algebra and its coalgebra structure and antipode are transpose of the group structure of $G$, and $\OO^i_j,\bar{\OO}^i_j, i,j\in \{1,\ldots,n\}$ are exactly the germs of the components of the matrix of $\Ad$ and its inverse in the chosen basis of $\ggf$, or
		\item[(c)] $\genfd$ is any field, $G$ is an affine algebraic group over $\genfd$ and $\mathcal H$ is a Hopf algebra such that $ \mathcal H \subset \OO(G)$ as a Hopf subalgebra, or
		%\item[(b)] elements $\mathcal{O}^i_j, \bar{\mathcal{O}}^i_j, i,j\in \{1,\ldots,n\}$ generate all elements of $H$ as an algebra, or
		\item[(d)] the pairing $\Ug \otimes \mathcal H \to \genfd$ is non-degenerate in the second variable, that is, $\mathcal H$ is essentially a Hopf subalgebra of the finite dual $\Ug^\circ$ of $\Ug$,
	\end{itemize}
	then $(\Ug,\btl',\lambda')$ is a braided commutative right-left Yetter--Drinfeld module algebra over $\mathcal H$, where the right action is induced by the pairing by formula $X \btl' f = \langle X_{(1)} , f \rangle X_{(2)}$ and the left coaction is defined on the Lie algebra generators by formula 
	$$\lambda'(X_j) = \sum \bar{\mathcal{O}}^i_j\otimes X_i.$$
	Likewise, $(\Ug^\op, \btl, \lambda)$ is a braided commutative right-left Yetter--Drinfeld module algebra over $\mathcal H^\co$, where the right action is induced by the pairing by formula $Y \btl f = \langle Y_{(1)} , f \rangle Y_{(2)}$ and the left coaction is defined on the Lie algebra generators by formula 
	$$\lambda(Y_j) = \sum {\mathcal{O}}^i_j\otimes Y_i.$$


\end{theorem}

\begin{proof}
	This is proven in previous theorems.
\end{proof}
This theorem covers the cases of any Hopf algebra $\mathcal H$ such that $\OO^{min}(G) \subset \mathcal H \subset C^\infty(G) \cap \mathcal R$ for a Lie group $G$ when $\genfd$ is $\mathbb{R}$ or $\mathbb{C}$, any Hopf algebra $\mathcal H$ such that $\OO^{min}(G) \subset\mathcal  H \subset \OO(G)$ when $G$ is an affine algebraic group over any field $\genfd$, and any Hopf algebra $\mathcal H$ such that $\Ug^{min}\subset\mathcal  H \subset \Ug^\circ$ for any field $\genfd$. 

\begin{corollary} Let $\mathfrak{h}$ be a finite-dimensional Leibniz algebra over any field $\genfd$. Then $U(\operatorname{Der}(\mathfrak{h}))$ is a braided commutative right-left Yetter--Drinfeld module algebra over $\OO(\Aut(\mathfrak{h}))$ and the smash product algebra $\OO(\Aut(\mathfrak{h})) \sharp U(\operatorname{Der}(\mathfrak{h}))$ is a scalar extension Hopf algebroid over base algebras $U(\operatorname{Der}(\mathfrak{h}))^\op, U(\operatorname{Der}(\mathfrak{h}))$. 
\end{corollary}

