%%%%\subsection{Yetter--Drinfeld property and the main theorem}
%%%%
%%%%\begin{theorem}\label{prop:main} Let $G$ be an affine algebraic group over any field $\genfd$. Then the pairing $\UgL \otimes \OO(G) \to \genfd$ that is a composition of counit and differentiation is a Hopf pairing and it induces a unique right Hopf action $\btl \colon \UgL \otimes \OO(G) \to \UgL$ such that $(D\btl f)(k) = D(fk)$ for all $D \in \UgL$ and all $f,k \in \OO(G)$. This action further induces the smash product algebra structure $\OO(G) \sharp \UgL$ on the algebra $\operatorname{Diff}(G)$ of regular differential operators. Let $\lambda \colon \UgL \to \OO(G) \sharp \UgL$ be the map that maps left invariant differential operators to the corresponding right invariant ones. Then $(\UgL,\btl, \lambda)$ is a braided commutative Yetter--Drinfeld module algebra over $\OO(G)$.
%%%%\end{theorem}
%%%%
%%%%
%%%%\begin{theorem}\label{prop:mainR} Let $G$ be an affine algebraic group over any field $\genfd$. Then the pairing $\UgR \otimes \OO(G)^\co \to \genfd$ that is a composition of counit and differentiation is a Hopf pairing and it induces a unique right Hopf action $\btl \colon \UgR \otimes \OO(G)^\co \to \UgR$ such that $(D\btl f)(k) = D(fk)$ for all $D \in \UgR$ and all $f,k \in \OO(G)$. This action further induces the smash product algebra structure $\OO(G)^\co \sharp \UgR$ on the algebra $\operatorname{Diff}(G)$ of regular differential operators. Let $\lambda \colon \UgR \to \OO(G) \sharp \UgR$ be the map that maps right invariant differential operators to the corresponding left invariant ones. Then $(\UgR,\btl, \lambda)$ is a braided commutative Yetter--Drinfeld module algebra over $\OO(G)^\co$.
%%%%\end{theorem}
%%%%\begin{proof}
%%%%	Analogous to the proof of Theorem \ref{prop:main}.
%%%%\end{proof}
%%%%
%%%%
%%%%\subsection{Minimal Hopf algebra $\OO^{min}(G)$} 
%%%%The statements of the main theorems actually hold not only for $\OO(G)$ but for all Hopf algebras $H$ such that $\OO^{min}(G) \subset H \subset \OO(G)$. 
%%%% 
%%%%\begin{theorem} Let $G$ be an affine algebraic group over any field $\genfd$. Let $H$ be any Hopf algebra such that $\OO^{min}(G) \subset H \subset \OO(G)$. Then the pairing $\UgL \otimes H \to \genfd$ that is a composition of counit and differentiation is a Hopf pairing and it induces a unique right Hopf action $\btl \colon \UgL \otimes H \to \UgL$ such that $(D\btl f)(k) = D(fk)$ for all $D \in \UgL$ and all $f,k \in H$. This action further induces the smash product algebra structure $H \sharp \UgL$ on the (sub)algebra of algebra $\operatorname{Diff}(G)$ of regular differential operators. Let $\lambda \colon \UgL \to H \sharp \UgL$ be the map that maps left invariant differential operators to the corresponding right invariant ones. Then $(\UgL,\btl, \lambda)$ is a braided commutative Yetter--Drinfeld module algebra over $\OO(G)$.
%%%%\end{theorem}
%%%%
%%%%\begin{proof}
%%%%	Essentially the same as proof of Theorem  \ref{prop:main} with $H$ instead of $\OO(G)$.
%%%%\end{proof}
