\section{Vanishing of the commutator terms}\label{appendix:identity}
In this appendix we show that given the conditions \eqref{AF-general-EOM-for-identity}, here reported for simplicity,
\begin{equation}\label{assumptions-appendix}
\begin{aligned}
D_{+}\mathcal{B}_{-}\!+\!D_{-}\mathcal{B}_{+} \deq & \, 0 
\quad\,\,\,\,\, \text{with} \quad\,\,\,\,\,
\mathcal{B}_{\pm} := -(\mathcal{A}_{\pm}+2v_{\pm}) \, ,
\\
\mathcal{A}_{\pm}+v_{\pm}+\Delta_{\pm} \deq & \, 0 
\quad\,\,\,\,\, \text{with} \quad\,\,\,\,\, 
\Delta_{\pm}:= \delta_{v_{\pm}}E(v) 
\quad \text{and} \quad [\Delta_{\pm},v_{\mp}]\deq \, 0 \, ,
\\
D_{+}\mathcal{A}_{-} \!-\!D_{-}\mathcal{A}_{+} \!+\! a \,[\mathcal{A}_{+},\mathcal{A}_{-}] \deq & \, 0 
\quad\,\,\,\,\, \text{with} \quad\,\,\,\,\, 
 D_{\pm}:=\partial_{\pm}\!+\![\mathcal{C}_{\pm},-]
\quad \text{and} \quad a \! \in \! \mathbb{R} \, \text{const.} 
\end{aligned}
\end{equation}
the commutator terms in the last step of \eqref{identity-steps} vanish, namely
\begin{equation}\label{desired-appendix}
\mathrm{tr}\Bigl(v_{\pm}^{n-1}[\mathcal{A}_{+},\mathcal{A}_{-}] \Bigr) \deq \, 0  
\qquad \qquad \text{and} \qquad \qquad  
\mathrm{tr}\Bigl(v_{\pm}^{n-1}[\mathcal{C}_{\pm},\Delta_{\mp}]\Bigr) \deq 0 \, .
\end{equation}
To begin we recall an identity, holding for any Lie-algebra valued $A,B,C$
\begin{equation}\label{Lie-algebra-identity}
\mathrm{tr}\Bigl( C^{n-1}[A,B] \Bigr) = \sum_{k=0}^{n-2}   \mathrm{tr} \Bigl( AC^{k}[B,C]C^{n-2-k} \Bigr)  \, ,
\end{equation}
which can be explicitly derived starting from
\begin{equation}
\mathrm{tr}\Bigl( C^{n-1}[A,B] \Bigr) = \mathrm{tr}\Bigl( ABC^{n-1} \Bigr) - \mathrm{tr}\Bigl( AC^{n-1}B \Bigr)
\end{equation}
and repeatedly commuting $B$ through $C^{n-1}$ in both terms on the right hand side. The second relation in \eqref{desired-appendix} is then readily verified by using \eqref{Lie-algebra-identity} with $A\!\equiv\! \mathcal{C_{\pm}}$, $B\!\equiv\! \Delta_{\mp}$, $C\!\equiv\! v_{\pm}$ and exploiting the commutator $[\Delta_{\pm},v_{\mp}]\deq 0$ in \eqref{assumptions-appendix}. The latter assumption also implies 
\begin{equation}\label{commutator[A,v]}
[\mathcal{A}_{\pm},v_{\mp}] \deq -[v_{\pm},v_{\mp}] \, ,
\end{equation}
which combined with \eqref{Lie-algebra-identity} for $A\!\equiv\! \mathcal{A}_{+}$, $B\!\equiv\! \mathcal{A}_{-}$, $C\!\equiv\! v_{+}$ brings the first relation in \eqref{desired-appendix} to
\begin{equation}
\mathrm{tr}\Bigl(v_{+}^{n-1}[\mathcal{A}_{+},\mathcal{A}_{-}] \Bigr) \!=\! \sum_{k=0}^{n-2}  \mathrm{tr} \Bigl( \mathcal{A}_{+}v_{+}^{k}[\mathcal{A}_{-},v_{+}]v_{+}^{n-2-k} \Bigr) \!\deq\!  - \! \sum_{k=0}^{n-2}   \mathrm{tr} \Bigl( \mathcal{A}_{+}v_{+}^{k}[v_{-},v_{+}]v_{+}^{n-2-k} \Bigr) \, .
\end{equation}
Using now \eqref{Lie-algebra-identity}, this time in the reversed direction with $A\!\equiv\! \mathcal{A}_{+}$, $B\!\equiv\! v_{-}$, $C\!\equiv\! v_{+}$, and exploiting once again \eqref{commutator[A,v]},  one finally arrives at
\begin{equation}
\begin{aligned}
\mathrm{tr}\Bigl(v_{+}^{n-1}[\mathcal{A}_{+},\mathcal{A}_{-}] \Bigr) \deq  - \mathrm{tr}\Bigl(v_{+}^{n-1}[\mathcal{A}_{+},v_{-}] \Bigr) \deq \mathrm{tr}\Bigl(v_{+}^{n-1}[v_{+},v_{-}] \Bigr) = 0 \, ,
\end{aligned}
\end{equation}
which is the desired first relation in \eqref{desired-appendix} for the choice of upper sign in $v_{\pm}$. The argument remains unchanged, up to an overall sign, for the choice of lower sign in $v_{\pm}$.

