\section{Derivative identities for $\mathfrak{su}(3)$}\label{app:su3der}
Here we collect the identities involving $\partial_{\pm}\mathrm{tr}(v_{\mp}^3)$ and $\partial_{\pm}\mathrm{tr}(v_{\mp}^2)$ derived using the relation \eqref{important-identity} and used in section \ref{sec:solution-spin-3-flow} to solve the spin-$3$ flow equation.
To begin, note that $\Delta_{\pm}:=\delta_{v_{\mp}}E(v) $ is linear in derivatives of $E$ along the Lorentz invariant variables $\nu _{2}, \, \nu_{3}, \, \omega,\, \widetilde \omega $ and hence we can compute the derivative identities using \eqref{important-identity} term by term, adding up all the contributions -- proportional to $\del _{\nu _{2}}E$, $\del _{\nu _{3}}E$, $\del _{\omega}E$ and $\del _{\widetilde \omega}E$ -- at the end. 

\subsection*{$\del _{\nu _3}E$ contributions}
We only present a detailed derivation of the $E_{3}:=\del _{\nu _3}E$ terms, since these rely on some specific properties of $\mathfrak {su }(3)$. The $E_{\nu _2}$, $E_{\omega} $ and $E_{\widetilde \omega }$ terms can be derived in a similar way. The equations of motion imply 
 \begin{equation}\label{rel-appendix-c}
    \begin{split}
        \frac 13 \del _- \, \ttr {v_+^3}&=  \del _+(3\, E_3\, \ttr{v_-^3}\, v_+{}^A\, v_+{}^B\,)v_+{}^C\, v_+{}^D\, d_{ABE}\, \ttr {T^E\, T_C\,T_D}+ \ldots
        \,,
    \end{split}
 \end{equation}
where the dots stand for omitted terms and we specialised the definitions in \eqref{d-symmetric-tensor} to
\begin{equation}
d_{ABC}:=\mathrm{tr}(T_{(A}T_{B}T_{C)}) \,.
\end{equation}
The indices $CD$ in \eqref{rel-appendix-c} are symmetrised, so we can in fact write 
\begin{equation}
     d_{ABE}\, \ttr{T^E\, T_C\,T_D} 
     \qquad 
     \rightarrow 
     \qquad 
     d_{ABE}\, d^E{}_{CD}
     \,,
\end{equation}
having used the Cartan-Killing form $\gamma_{AB}:=\mathrm{tr}(T_{A}T_{B})$ and its inverse $\gamma^{AB}$ to lower/raise indices as $d^{E}{}_{CD}:=\gamma^{EF}d_{FCD}$.
In addition, the derivative can only hit at most one $v_+$, so 3 out of the four indices will also be symmetrised, hence we really get 
\begin{equation}
    d_{ABE}\, d^E{}_{CD}
    \qquad \rightarrow \qquad 
    d_{E(AB}\, d^E{}_{CD)}= \frac 16 \gamma _{(AB}\gamma _{CD)}\,.
\end{equation}
The full expansion becomes
\begin{equation}
    \begin{split}
        \frac 13 \del _- \ttr {v_+^3}&= \frac12 \del _+ (E_3\, \tr(v_-^3))\ttr{v_+^2 }^2 +  E_3 \, \ttr{v_-^3}\,\del_+ v_+{}^A\, v_+{}^B\, v_+ {}^C\, v_+{}^D\gamma_{(AB}\,\gamma _{CD)}\\[0.6em]
        &= \frac 12 \del _+ (E_3\, \tr(v_-^3))\ttr{v_+^2 }^2 +\frac 12  E_3 \, \ttr{v_-^3}\,\del_+\ttr{v_+^2}\, \ttr{v_+^2}
        \,,
    \end{split}
\end{equation}
and flipping signs gives us 
\begin{equation}\label{eq:E3terms}
\frac 13 \del _{\mp} \, \ttr{v_{\pm}^3} =\frac 12 \del _{\pm} (E_3\, \tr(v_{\mp}^3))\ttr{v_{\pm}^2 }^2 + \frac12 E_3 \, \ttr{v_{\mp}^3}\,\del_{\pm}\ttr{v_{\pm}^2}\, \ttr{v_{\pm}^2}\,.
\end{equation}
The analogous expressions for $\ttr {v_{\pm}^2}$ are simpler 
\begin{equation}
    \begin{split}
        \frac 12 \del _- \, \ttr{v_+^2} &= \tr \left (\del _+(3 E_3\ttr{v_-^3}\,v_+{}^A\, v_+{}^B)T^C \, v_+\right)\, d_{ABC}\\
        &= 3 \del _+\left(E_3\tr (v_-^3)\right)\tr (v_+^3)+ 2E_3\tr (v_-^3)\del _+\tr (v_+^3)\,,
    \end{split}
\end{equation}
and finally 
\begin{equation}
\frac 12 \del _{\mp} \, \tr (v_{\pm}^2) =3 \del _{\pm}\left(E_3\tr (v_{\mp}^3)\right)\tr (v_{\pm}^3)+ 2E_3\tr (v_{\mp}^3)\del _{\pm}\tr (v_{\pm}^3) \, .
\end{equation}



