\includegraphics[width=\linewidth]{Figures/Accessible_phi.pdf}
\caption{Range of packing fractions for which mechanical equilibrium under gravity is possible for a granular pile, as a function of the microscopic solid friction coefficient~$\mu_p$.}
\label{figure_comp_dil_phi}
\end{center}
