If $(i,K)$ is active with $i<K$, then $\MR (i,K)=0$ can be formulated as:
\begin{equation*}
\MR (i,K)=\int^{b^{i}}_{a^{i}}\Phi (x_{1})\dd x_{1}=0,
\end{equation*}
where
\begin{equation}
\label{Eqn_Phi}
\Phi (x_{1})=\int^{1}_{\max(1-\overline{u}(x_{1}),x_{1})}\phi(\mathbf{x})\dd x_{2}-f(x_{1},1).
\end{equation}
If $(K,K)$ is active, $\int^{b^{K}}_{a^{K}}\Phi (x_{1})\dd x_{1}=0$ should also hold because the environment is symmetric. Hence, we have a refined representation of the MR condition.

\begin{observation}
\label{Obs_3}
If $(i,K)$ is active, then $\int^{b^{i}}_{a^{i}}\Phi (x_{1})\dd x_{1}=0$.
\end{observation}

If $(i,K)$ is inactive, then $a^{i}=b^{i}$, and $\mathcal{D}(i,K)=\{\mathbf{x}\in \mathcal{X}: x_{1}=a^{i}\text{, }\max (1-\overline{u}(x_{1}),x_{1})\leq x_{2}\leq 1\}$. Consider changing $p(i,K)$ by $\varepsilon<0$. The demand set of $(i,K)$ after this price change will belong to a neighborhood of $\mathcal{D}(i,K)$. Computing MR for this perturbed price schedule will give us the left limit of $\MR (i,K)$, which should be nonnegative if $\mathbf{p}$ is a local maximizer of the total revenue. Thus, there must be $\Phi (a^{i})\geq 0$.

As a direct implication, if $(K,K)$ is inactive, then $a^{K}=1$ and $\Phi (a^{K})<0$, a contradiction to our previous analysis. Thus, $(K,K)$ must be active. We summarize these results in the following observation.

\begin{observation}
\label{Obs_4}
If $(i,K)$ is inactive, then $a^{i}=b^{i}$ and $\Phi (a^{i})\geq 0$. $(K,K)$ is active.
\end{observation}

Combining Observations \ref{Obs_3} and \ref{Obs_4}, if $(i,K)$ is active and $(i-1,K)$ (or $(i+1,K)$) is inactive, then $\Phi (a^{i})\geq 0$ (or $\Phi (b^{i})\geq 0$).

\subsection{A Continuum of Quantities}
\label{Sec_2D_Continuum}

Now assume that the seller can deliver any bundle $\mathbf{q}\in [0,1]^{2}$. Then the price schedule becomes a function $p:[0,1]^{2}\mapsto \mathbb{R}$, where $p(\mathbf{q})$ is the price for bundle $\mathbf{q}$ and $p(0,0)=0$. The indirect utility function induced by $p$ is
\begin{equation*}
u(\mathbf{x})=\sup_{\mathbf{q}\in [0,1]^{2}}\{\mathbf{x}\cdot\mathbf{q}-p(\mathbf{q})\}.
\end{equation*}
It can be proved that $u$ is nonnegative, nondecreasing, convex, and 1-Lipschitz with respect to the $\ell^{1}$-norm.
To characterize demand sets, we define the subdifferential of $u$ as:
\begin{equation*}
\partial u(\mathbf{x})=\{\mathbf{q}\in [0,1]^{2}:\mathbf{x}\cdot\mathbf{q}-u(\mathbf{x})\geq \hat{\mathbf{x}}\cdot\mathbf{q}-u(\hat{\mathbf{x}})\text{ for all }\hat{\mathbf{x}}\in \mathcal{X}\}.
\end{equation*}
Then a type-$\mathbf{x}$ buyer purchases $\mathbf{q}$ if $\mathbf{q}\in \partial u(\mathbf{x})$. The demand set of bundle $\mathbf{q}$ is
\begin{equation*}
\mathcal{D}(\mathbf{q})=\{\mathbf{x}\in\mathcal{X}:\mathbf{q}\in \partial u(\mathbf{x})\},
\end{equation*}
and the marginal revenue for $\mathbf{q}$ is
\begin{equation*}
\MR (\mathbf{q})=\int_{\mathcal{D}(\mathbf{q})}\phi(\mathbf{x})\dd \mathbf{x}-\int_{\mathcal{D}(\mathbf{q})\cap \overline{\bd}(\mathcal{X})}f(\mathbf{x})(\mathbf{x}\cdot\mathbf{n}_{\mathbf{x}})\dd \sigma (\mathbf{x})
\end{equation*}
Since $u$ is convex, it is differentiable at almost all $\mathbf{x}\in \mathcal{X}$. For these $\mathbf{x}$, $\mathbf{q}\in \partial u(\mathbf{x})$ boils down to $\mathbf{q}=\nabla u(\mathbf{x})$, and the buyer actually pays $p(\nabla u(\mathbf{x}))=\mathbf{x}\cdot \nabla u(\mathbf{x})-u(\mathbf{x})$ by convex conjugacy. The seller's total revenue is
\begin{equation*}
\TR (p)=\int_{\mathcal{X}}[\mathbf{x}\cdot \nabla u(\mathbf{x})-u(\mathbf{x})]f(\mathbf{x})\dd\mathbf{x}.
\end{equation*}
In what follows, we turn to the task of finding an optimal $u$ subject to its feasibility. By convex conjugacy, this is equivalent to searching for an optimal price schedule.

Slightly different from \Cref{Sec_1D}, now we say that a nonzero bundle $\mathbf{q}$ is \emph{active} if, for any $\delta>0$, $\bigcup_{\lVert\hat{\mathbf{q}}-\mathbf{q}\rVert<\delta} \mathcal{D}(\hat{\mathbf{q}})$ has positive measure with respect to $f$, where $\lVert\cdot\rVert$ represents the Euclidean norm; otherwise, it is \emph{inactive}. An active bundle $\mathbf{q}$ is \emph{pooling} if $\mathcal{D}(\mathbf{q})$ has positive measure with respect to $f$; otherwise, it is \emph{separating}. We also let $\overline{u}(\cdot)=u(\cdot,1)=u(1,\cdot)$, and $[a^{q},b^{q}]=\{x\in [0,1]: \overline{u}'(x-)\leq q\leq \overline{u}'(x+)\}$.

\Cref{Prop_2D} generalizes the four observations from \Cref{Sec_2D_Finite} to the current setting. Since its intuition is transparent from our analysis of the discrete setting, we defer its proof to \Cref{Sec_General}, after we formally introduce \Cref{Thm_MR}.\footnote{Since \eqref{Eqn_2D_MM} reduces the problem to finding the optimal $\overline{u}$, we can also apply a variational approach to derive \Cref{Prop_2D}. Details are provided in \Cref{Sec_2D_Variational}.}

\begin{proposition}
\label{Prop_2D}
Suppose that the environment is SRS. Then in any symmetric optimal mechanism:
\begin{enumerate}
\item If $(q_{1},q_{2})$ is active, then $q_{1}=1$ or $q_{2}=1$, and $(q_{2},q_{1})$ is also active. \label{Prop_2D_1}
\item If $(q,1)$ is pooling, then $\MR (\mathbf{q})=0$, which can be simplified as
\begin{equation}
\label{Eqn_2D_MR}
\int^{b^{q}}_{a^{q}}\Phi (x_{1})\dd x_{1}=0.
\end{equation}
Moreover, $\Phi (a^{q})\geq 0$ unless $q=0$, and $\Phi (b^{q})\geq 0$ unless $q=1$. The grand bundle $\mathbf{1}$ is pooling. \label{Prop_2D_2}
\item If $(q,1)$ is separating, then $a^{q}=b^{q}$ and $\Phi (a^{q})=0$. \label{Prop_2D_3}
\end{enumerate}
\end{proposition}

In \Cref{Prop_2D}, part \ref{Prop_2D_1} summarizes Observations \ref{Obs_1} and \ref{Obs_2}, part \ref{Prop_2D_2} corresponds to Observations \ref{Obs_3} and \ref{Obs_4}, while part \ref{Prop_2D_3} can be viewed as a limiting case of \Cref{Obs_3}. We note that part \ref{Prop_2D_1}, along with \eqref{Eqn_2D_MM}, was first established by \citet{mcafee1988multidimensional} and has since been documented in many subsequent papers that impose similar regularity conditions (see \Cref{Ftn_Reg} for a discussion). The main contribution of \Cref{Prop_2D}, however, lies in the additional conditions presented in parts \ref{Prop_2D_2} and \ref{Prop_2D_3}, which enable us to solve for $\overline{u}$ in various examples. We shall elaborate the mileages in \Cref{Sec_2D_OptMech}.

\subsection{Characterizing Optimal Mechanisms}
\label{Sec_2D_OptMech}

\Cref{Prop_2D}, together with the functional form of $\Phi$, motivates the definition of an auxiliary function $\zeta :[0,1]\mapsto \mathbb{R}$, such that
\begin{equation}
\label{Eqn_Zeta}
\zeta (x_{1})=\sup\left\{\zeta\in [0,1]: \int^{1}_{\zeta }\phi(x_{1},x_{2})\dd x_{2}-f(x_{1},1)\geq 0\right\},
\end{equation}
where we define $\sup \emptyset =0$. By construction, $\zeta$ is continuous because $\phi$ and $f$ are both continuous, $\zeta<1$ because $f$ is bounded away from zero, and the sign of $\Phi (x)$ is the same as the sign of $\zeta (x)-\max(1-\overline{u}(x),x)$. When $x_{1}$ and $x_{2}$ are i.i.d. with marginal p.d.f. $g$ and cumulative distribution function (c.d.f.) $G$, \eqref{Eqn_Zeta} reduces to
\begin{equation}
\label{Eqn_Zeta_iid}
\frac{\zeta (x)g(\zeta (x))}{1-G(\zeta (x))}=\frac{xg'(x)}{g(x)}+2.
\end{equation}
Let $h(x)=xg'(x)/g(x)$. Then strict regularity implies $h>-3/2$ and $0<\zeta<1$. Moreover, when $h$ is differentiable at $x$, the sign of $\zeta'(x)$ is the same as the sign of $h'(x)$. 

When $\zeta>0$ (which can be implied from the i.i.d. assumption), \eqref{Eqn_2D_MR} can alternatively be stated as
\begin{equation}
\label{Eqn_MassCancel}
\int^{b^{q}}_{a^{q}}\int^{1}_{\max(1-\overline{u}(x_{1}),x_{1})}\phi (\mathbf{x})\dd x_{2}\dd x_{1}=\int^{b^{q}}_{a^{q}}\int^{1}_{\zeta (x_{1})}\phi (\mathbf{x})\dd x_{2}\dd x_{1}.
\end{equation}
As we treat $\phi$ as the ``density'' of MR, the condition $\MR=0$ boils down to the cancellation of ``mass'' between $\zeta (x)$ and $\max(1-\overline{u}(x),x)$ for $x\in [a^{q},b^{q}]$. In this sense, $\zeta$ can be regarded as a pointwise solution for $\MR=0$, or a pointwise maximizer of total revenue. The remainder of this section is devoted to illustrating how $\zeta$ can help determine the set of active bundles (or menu size). 

In what follows, we present several corollaries and examples. In all examples (but not corollaries), we maintain the i.i.d. assumption and will simply say that $g$ is strictly regular if $h>-3/2$.

\subsubsection{Nondecreasing or convex $\zeta$}

We first analyze two scenarios where any optimal mechanism has only finitely many active bundles, and all of them are pooling.

When $\zeta$ is nondecreasing and crosses the 45-degree line exactly once, any optimal mechanism is deterministic, that is, the set of active bundles is a subset of $\{\mathbf{e}_{1},\mathbf{e}_{2},\mathbf{1}\}$.

\begin{corollary}
\label{Cor_Inc}
Suppose that $\zeta$ is nondecreasing and crosses the 45-degree line exactly once. Then in any symmetric optimal mechanism, there exists $a^{1}<1$ such that:
\begin{enumerate}
\item $\overline{u}'(x)=0$ for $x\in [0,a^{1})$,
\item $\overline{u}'(x)=1$ for $x\in [a^{1},1]$.
\end{enumerate}
\end{corollary}

When $\zeta$ is convex, there are at most three active bundles in any optimal mechanism.

\begin{corollary}
\label{Cor_Cvx}
Suppose that $\zeta$ is convex on $[0,1]$. Then in any symmetric optimal mechanism, there exist $a^{1}<1$ and $q<1$ such that:
\begin{enumerate}
\item $\overline{u}'(x)=q$ for $x\in [0,a^{1})$,
\item $\overline{u}'(x)=1$ for $x\in [a^{1},1]$.
\end{enumerate}
\end{corollary}

\begin{proof}[Proof of Corollaries \ref{Cor_Inc} and \ref{Cor_Cvx}]
In both corollaries, $\zeta (x)=x$ has a unique solution, which we denote by $x_{\zeta}$. Since $\zeta<1$, we have $\zeta (x)>x$ for $x\in [0,x_{\zeta})$ and $\zeta (x)<x$ for $x\in (x_{\zeta},1]$. By \Cref{Prop_2D}, $\mathbf{1}$ is pooling, and $\max (1-\overline{u}(a^{1}),a^{1})\leq \zeta (a^{1})$, so $a^{1}<x_{\zeta}$. Let $\mathcal{A}=\{x\in [0,1]:\max (1-\overline{u}(x),x)=\zeta (x)\}$. Three cases will be discussed in order.

First, if $\mathcal{A}=[\alpha,\beta]\cup \{x_{\zeta}\}$ with $0\leq \alpha<\beta<x_{\zeta}$, then $\overline{u}'(x)$ is a constant for all $x\in (\alpha, \beta)$, which we denote by $q<1$. When $\zeta$ is nondecreasing, we further have $q=0$. By \Cref{Prop_2D}, there cannot be any active bundle $(\hat{q},1)$ satisfying $[a^{\hat{q}},b^{\hat{q}}]\subseteq [0,\alpha]$ or $[a^{\hat{q}},b^{\hat{q}}]\subseteq [\beta,a^{1}]$, meaning that $a^{q}=0$ and $b^{q}=a^{1}$.

Second, if $\mathcal{A}=\{\alpha,x_{\zeta}\}$ with $\alpha<x_{\zeta}$, then, by a similar argument, there cannot be any active bundle $(q,1)$ satisfying $[a^{q},b^{q}]\subseteq [0,\alpha]$ or $[a^{q},b^{q}]\subseteq [\alpha,a^{1}]$. That is, there must be a pooling bundle $(q,1)$ with $q<1$ satisfying $[0,\alpha)\subset [a^{q},b^{q}]$. However, by \Cref{Prop_2D}, $\max (1-\overline{u}(x),x)\leq \zeta (x)$ for $x=a^{q},b^{q}$, meaning that $\max (1-\overline{u}(x),x)$ intersects $\zeta (x)$ at least twice on $[a^{q},b^{q}]$, a contradiction.

Finally, if $\mathcal{A}=\{x_{\zeta}\}$, then $\mathbf{1}$ is the only active bundle.

Summarizing all the three cases gives us the corollaries.
\end{proof}

\Cref{Fig_CvxInc} depicts Corollaries \ref{Cor_Inc} and \ref{Cor_Cvx}. In each panel, the red curve represents $1-\overline{u}(x_{1})$ and its symmetric counterpart $1-\overline{u}(x_{2})$. The top-right region of the red curve consists of demand sets of all active bundles, while the bottom-left region of the red curve consists of types that receive zero indirect utility. Demand sets are separated by dashed lines. The green curve is $\zeta$. The region colored in blue or red captures the extent to which $\max (1-\overline{u}(x_{1}),x_{1})$ deviates from $\zeta (x_{1})$. The integral of $\phi$ on the blue region is the ``surplus'' of MR, while the integral of $\phi$ on the red region is the ``deficit'' of MR. Panels (a) and (b) correspond to Corollaries \ref{Cor_Inc} and \ref{Cor_Cvx} with $a^{1}>0$. Panel (c) corresponds to the special case of pure bundling, which may occur regardless of the shape of $\zeta$.

