\begin{example}[Power-law distribution]
\label{Exp_PowerPositive}
Let $g(x)=C(x+\theta)^{\eta-1}$, where $\theta\geq 0$, $\eta\geq 1$, and $C$ is a normalization constant. Then $h(x)=(\eta-1)x/(x+\theta)\geq 0$ for all $x\in [0,1]$, so $g$ is strictly regular. It can be proved that $\zeta$ is nondecreasing and crosses the 45-degree line exactly once. In particular, when $\theta=0$, $\zeta$ equals a constant:
\begin{equation*}
\zeta (x)=\left(\frac{\eta+1}{2\eta+1}\right)^{\frac{1}{\eta}}.
\end{equation*}
\end{example}

\begin{example}[Truncated Pareto distribution]
\label{Exp_Pareto}
Let $g(x)=C(1+x)^{-\eta}$, where $\eta\in (0,3]$, and $C$ is a normalization constant. Then $h(x)=-\eta x/(x+1)>-3/2$ for almost all $x\in [0,1]$, so $g$ is strictly regular. It can be proved that $\zeta$ is strictly decreasing and strictly convex.\footnote{We numerically solve for the cutoff $a^{1}$ and find that optimal mechanisms require randomization when $\eta$ is small and become pure bundling when $\eta$ is above 2.9.} 
\end{example}

Under the i.i.d. assumption, \citet{manelli2006bundling} and \citet{hart2010revenue} both prove that deterministic mechanisms are optimal when $h$ (or equivalently $\zeta$) is nondecreasing. Their result does not depend on the number of crossings between $\zeta$ and the 45-degree line. \citet{tang2017optimal} extend the analysis to general rectangular type spaces while maintaining the assumptions of independent distribution and nondecreasing $\zeta$. They find that randomization may arise, but the optimal menu size (excluding the zero bundle) is bounded by five. Note that \Cref{Exp_PowerPositive} with $\theta=0$ is one of the leading examples in \citet{manelli2006bundling} and \citet{tang2017optimal}.

\subsubsection{Concave $\zeta$}

When $\zeta$ is concave, the optimal $\overline{u}$ is characterized by two cutoffs. When $x$ is below the smaller cutoff, $\overline{u}'(x)=0$. When $x$ is above the larger cutoff, $\overline{u}'(x)=1$. When $x$ lies between the two cutoffs, $\overline{u}$ coincides with $1-\zeta$.

\begin{corollary}
\label{Cor_Ccv}
Suppose that $\zeta$ is concave on $[0,1]$. Then in any symmetric optimal mechanism, there exist $0\leq b^{0}\leq a^{1}<1$ such that:
\begin{enumerate}
\item $\overline{u}'(x)=0$ for $x\in [0,b^{0})$,
\item $\overline{u}(x)=1-\zeta (x)$ for $x\in [b^{0},a^{1})$,
\item $\overline{u}'(x)=1$ for $x\in [a^{1},1]$.
\end{enumerate}
\end{corollary}

\begin{proof}
Suppose that $\zeta$ is concave and that $(q,1)$ is pooling with $q\in (0,1)$. By part \ref{Prop_2D_2} of \Cref{Prop_2D}, $\max(1-\overline{u}(x),x)\leq \zeta (x)$ for $x=a^{q},b^{q}$. As depicted in \Cref{Fig_Proof1}, the single-dipped function $\max(1-\overline{u}(x),x)$ lies (weakly) below $\zeta (x)$ on $[a^{q},b^{q}]$. The only way to satisfy \eqref{Eqn_2D_MR} is that $1-\overline{u}(x)>x$ and $1-\overline{u}(x)=\zeta (x)$ for all $x\in [a^{q},b^{q}]$. This result and part \ref{Prop_2D_3} of \Cref{Prop_2D} jointly imply that $\overline{u}(x)=1-\zeta (x)$ for all $x\in [b^{0},a^{1}]$. This proves \Cref{Cor_Ccv}.
\end{proof}

