According to \Cref{Fig_SubsComp}, if $\mathbf{q}$ is active with $q_{1}\leq q_{2}$, then $\mathbf{n}_{k}=(1/k-1,1)$ is an outward normal to $\mathcal{Q}$ at $\mathbf{q}$. In other words, $\mathbf{q}\cdot\mathbf{n}_{k}=\mathbf{e}_{2}\cdot\mathbf{n}_{k}=1$. To highlight the relationship between active bundles and $\mathbf{n}_{k}$, we denote by $\hat{\mathbf{n}}_{k}=(1,1-1/k)$ the vector orthogonal to $\mathbf{n}_{k}$ and use $q\hat{\mathbf{n}}_{k}+\mathbf{e}_{2}$ to represent a generic active bundle. We also let $\hat{\mathbf{n}}_{k}'=(1-1/k,1)$.

Parts \ref{Prop_2D_2} and \ref{Prop_2D_3} of \Cref{Prop_2D} also admit natural generalizations to the current setting. Let $\overline{u}(\cdot)=u(\cdot,1)=u(1,\cdot)$ and $[a^{q},b^{q}]=\{x\in [0,1]: \overline{u}'(x-)\leq q\leq \overline{u}'(x+)\}$. When $q<k$, the demand set of $q\hat{\mathbf{n}}_{k}+\mathbf{e}_{2}$ is\footnote{More precisely, when $k>1$ and $a^{q}=0$, there is an edge case where some buyers with $x_{1}<(k-1)(1-x_{2})/k$ also purchase $q\hat{\mathbf{n}}_{k}+\mathbf{e}_{2}$. Although these buyers may purchase some ``smaller bundle'' $\hat{q}\hat{\mathbf{n}}_{k}+\mathbf{e}_{2}$ with $\hat{q}<q$, that will result in a positive marginal revenue for this smaller bundle in the SRS environment, leading to a contradiction to \Cref{Thm_MR} in \Cref{Sec_General}. In this case, the demand set of $q\hat{\mathbf{n}}_{k}+\mathbf{e}_{2}$ is
\begin{equation*}
\begin{aligned}
\mathcal{D}_{k}(q\hat{\mathbf{n}}_{k}+\mathbf{e}_{2}) & =\{\hat{\mathbf{x}}\in \mathcal{X}:\hat{\mathbf{x}}=(x_{1},1)-(1-x_{2})\mathbf{n}_{k}\text{, }x_{1}\in [0,b^{q}]\text{, and }\max(1-\overline{u}(x_{1}),z_{k}(x_{1}))\leq x_{2}\leq 1\} \\
& \quad \cup \{\hat{\mathbf{x}}\in \mathcal{X}:\hat{\mathbf{x}}=(x_{1},1)-(1-x_{2})\mathbf{n}_{k}\text{, }x_{1}<0\text{, and }\max(1-\overline{u}(0),z_{k}(0))\leq x_{2}\leq 1\}.
\end{aligned}
\end{equation*} \label{Ftn_D_k}}
\begin{equation}
\label{Eqn_D_k}
\begin{aligned}
\mathcal{D}_{k}(q\hat{\mathbf{n}}_{k}+\mathbf{e}_{2}) & =\{\hat{\mathbf{x}}\in \mathcal{X}:\hat{\mathbf{x}}=(x_{1},1)-(1-x_{2})\mathbf{n}_{k}\text{, }x_{1}\in [a^{q},b^{q}], \\
& \quad \quad \text{and }\max(1-\overline{u}(x_{1}),z_{k}(x_{1}))\leq x_{2}\leq 1\},
\end{aligned}
\end{equation}
and $\Phi_{k}$ should be defined as
\begin{equation*}
\Phi_{k}(x_{1})=\int^{1}_{\max(1-\overline{u}(x_{1}),z_{k}(x_{1}))}\phi ((x_{1},1)-(1-x_{2})\mathbf{n}_{k})\dd x_{2}-f(x_{1},1),
\end{equation*}
where\footnote{Suppose that $(x_{1},1)\in \mathcal{D}(q\hat{\mathbf{n}}_{k}+\mathbf{e}_{2})$. Then for $\hat{\mathbf{x}}=(x_{1},1)-(1-x_{2})\mathbf{n}_{k}$, there is $\hat{\mathbf{x}}\in \mathcal{D}(q\hat{\mathbf{n}}_{k}+\mathbf{e}_{2})$ if
\begin{equation*}
\begin{aligned}
x_{2}\geq x_{1}-\frac{1-k}{k}(1-x_{2}) & \geq 0, \\
\overline{u}(x_{1})-(1-x_{2})(\mathbf{n}_{k}\cdot\mathbf{q})=\overline{u}(x_{1})-(1-x_{2}) & \geq 0.
\end{aligned}
\end{equation*}
The solution of these two inequalities is summarized as $\max(1-\overline{u}(x_{1}),z_{k}(x_{1}))\leq x_{2}\leq 1$.}
\begin{equation*}
z_{k}(x_{1})=
\begin{cases}
1-x_{1} & k=1/2, \\
\max \left(\frac{kx_{1}+k-1}{k-1},\frac{kx_{1}+k-1}{2k-1}\right) & 1/2<k<1, \\
\frac{kx_{1}+k-1}{2k-1} & k>1.
\end{cases}
\end{equation*}
When $k=1$, $z_{k}$ degenerates to $x_{1}$, and $\Phi_{k}$ degenerates to $\Phi$ in \Cref{Sec_2D}. Thus, we may expect that some results similar to \Cref{Prop_2D} continue to hold in this more general setting. \Cref{Prop_SubsComp} confirms this intuition. The proof of \Cref{Prop_SubsComp} is also deferred to \Cref{Sec_General}.

\begin{proposition}
\label{Prop_SubsComp}
Suppose that the environment is SRS and $k\geq 1/2$. Then in any symmetric optimal mechanism:
\begin{enumerate}
\item If $(q_{1},q_{2})$ is active with $q_{1}<q_{2}$, then $(q_{1},q_{2})=q_{1}\hat{\mathbf{n}}_{k}+\mathbf{e}_{2}$, and $(q_{2},q_{1})=q_{1}\hat{\mathbf{n}}_{k}'+\mathbf{e}_{1}$ is also active. \label{Prop_SubsComp_1}
\item If $q\hat{\mathbf{n}}_{k}+\mathbf{e}_{2}$ is pooling, then $\MR (q\hat{\mathbf{n}}_{k}+\mathbf{e}_{2})=0$, which can be simplified as
\begin{equation}
\label{Eqn_SubsComp}
\int^{b^{q}}_{a^{q}}\Phi_{k}(x_{1})\dd x_{1}=0
\end{equation}
unless $k>1$ and $a^{q}=0$.
Moreover, $\Phi_{k}(a^{q})\geq 0$ unless $q=0$, and $\Phi_{k}(b^{q})\geq 0$ unless $q=k$. The grand bundle $\mathbf{k}$ is pooling unless $k=1/2$. \label{Prop_SubsComp_2}
\item If $q\hat{\mathbf{n}}_{k}+\mathbf{e}_{2}$ is separating, then $a^{q}=b^{q}$ and $\Phi_{k}(a^{q})=0$. \label{Prop_SubsComp_3}
\end{enumerate}
\end{proposition}

Similar to \eqref{Eqn_Zeta}, we define the auxiliary function $\zeta_{k}$ for each $k$.
\begin{equation*}
\begin{aligned}
\zeta_{k} (x_{1}) & =\sup\bigg\{\zeta\in [0,1]:(x_{1},1)-(1-\zeta)\mathbf{n}_{k}\in \mathcal{X}, \\
& \quad \quad \quad \quad \int^{1}_{\zeta }\phi ((x_{1},1)-(1-x_{2})\mathbf{n}_{k})\dd x_{2}-f(x_{1},1)\geq 0\bigg\}.
\end{aligned}
\end{equation*}
By construction, the sign of $\Phi_{k}(x)$ is the same as the sign of $\zeta_{k}(x)-\max(1-\overline{u}(x),z_{k}(x))$.

Just as in \Cref{Sec_2D}, we will use properties of $\zeta_{k}$ to determine active bundles in optimal mechanisms. The results are summarized in \Cref{Tab_2} with their formal statements, Corollaries \ref{Cor_k=1/2}--\ref{Cor_k>1}, relegated to \Cref{Sec_SubsComp_OptMech}.

