\label{Fig_Uniform_Positive}
\end{figure}

We now present a sufficient condition for the qualification. For any $Q\subseteq \mathcal{Q}$, it can be proved that\footnote{For any $\mathbf{x}\in \mathcal{D}(Q)\cap \mathcal{D}(Q^{c})$, there exist $\mathbf{q}\in Q$ and $\hat{\mathbf{q}}\in Q^{c}$ such that $\mathbf{x}\in \mathcal{D}(\mathbf{q})\cap \mathcal{D}(\hat{\mathbf{q}})$. By convex conjugacy, this implies $\{\mathbf{q},\hat{\mathbf{q}}\}\subseteq \partial u_{p}(\mathbf{x})$, thus $u_{p}$ is nondifferentiable at $\mathbf{x}$. Since $u_{p}$ is convex, it is differentiable at almost all $\mathbf{x}\in \Int (\mathcal{X})$, and the set of nondifferentiable points in $\Int (\mathcal{X})$ must have zero measure with respect to $f$.}
\begin{equation}
\label{Eqn_Qualification}
\mu (\mathcal{D}(Q)\cap \mathcal{D}(Q^{c}))=\mu (\mathcal{D}(Q)\cap \mathcal{D}(Q^{c})\cap \bd(\mathcal{X})).
\end{equation}
For any $\mathbf{x}\in \bd (\mathcal{X})$, denoted by $\NV (\mathbf{x})$ the set of outward unit vectors normal to $\mathcal{X}$ at $\mathbf{x}$. Denote by $\underline{\bd} (\mathcal{X})$ the \emph{bottom boundary} of $\mathcal{X}$, where
\begin{equation*}
\underline{\bd}(\mathcal{X})=\{\mathbf{x}\in \bd (\mathcal{X}):\mathbf{x}\cdot\mathbf{n}_{\mathbf{x}}<0\text{ for some }\mathbf{n}_{\mathbf{x}}\in \NV (\mathbf{x})\}.
\end{equation*}
If $\underline{\bd}(\mathcal{X})$ is $\sigma$-negligible, then we have $\mu (\mathcal{D}(Q)\cap \mathcal{D}(Q^{c}))\geq 0$ from \eqref{Eqn_Qualification}, and
\begin{equation*}
0\leq \MR_{-}(Q)-\MR_{+}(Q)=-\mu (\mathcal{D}(Q)\cap \mathcal{D}(Q^{c}))-\mu (\mathcal{X})-1\leq 0,
\end{equation*}
which implies $\mu (\mathcal{D}(Q)\cap \mathcal{D}(Q^{c}))=0$ and therefore \eqref{Eqn_MR}. In other words, the qualification for \eqref{Eqn_MR} can be omitted if the bottom boundary is $\sigma$-negligible.

\begin{corollary}
\label{Cor_MR}
Suppose that $\underline{\bd}(\mathcal{X})$ is $\sigma$-negligible. Then for any optimal mechanism, \eqref{Eqn_MR} holds for any $Q$ satisfying $\mathbf{0}\notin Q$.
\end{corollary}

\Cref{Cor_MR} applies, in particular, to our leading case where $\mathcal{X}=[0,1]^N$. In this setting, \citet[Theorem 1]{manelli2006bundling} have proved that $\mu(\mathcal{D}(\mathbf{q}))=0$ for any deterministic $\mathbf{q}$, provided the optimal mechanism is deterministic. \Cref{Cor_MR} immediately extends their result to any $\mathbf{q}\in \mathcal{Q}$ for any optimal mechanism.

In \Cref{Sec_Exclusion}, we present an additional application of \Cref{Thm_MR} that generalizes the well-known result on exclusion sets in \citet[Proposition 1]{armstrong1996multiproduct}.

\subsection{Verifying the Optimality of Specific Mechanisms}

An important application of \Cref{Thm_MR} is to certify whether a specific mechanism is optimal. We illustrate this under two settings.

First, consider selling $N$ items to additive buyers whose types are distributed over a hypercube. That is, $\mathcal{X}=[\underline{x},\overline{x}]^{N}$ and $\mathcal{Q}=[0,1]^{N}$. \Cref{Prop_Pure_N} provides three necessary conditions for the optimality of a pure bundling mechanism where only $\mathcal{D}(\mathbf{0})$ and $\mathcal{D}(\mathbf{1})$ have positive measure under $f$. In its statement, we will use $\mathbf{x}_{-n}$ to represent a generic element in $[\underline{x},\overline{x}]^{N-1}$.

\begin{proposition}
\label{Prop_Pure_N}
Let $\mathcal{X}=[\underline{x},\overline{x}]^{N}$ and $\mathcal{Q}=[0,1]^{N}$. Then a pure bundling mechanism $p$ is optimal only if
\begin{align}
\label{Eqn_Pure_N_1}
p(\mathbf{1})-(N-1)\underline{x} & \leq \overline{x}, \\
\label{Eqn_Pure_N_2}
\mu (\mathcal{D}(\mathbf{1})) & =0,
\end{align}
and, provided that $\underline{\bd}(\mathcal{X})$ is $\sigma$-negligible,
\begin{equation}
\label{Eqn_Pure_N_3}
\int^{\overline{x}}_{p(\mathbf{1})-(N-1)\underline{x}}\phi (x_{n},\underline{\mathbf{x}}_{-n})\dd x_{n}-\overline{x}f(x_{n},\underline{\mathbf{x}}_{-n})\geq 0,\quad \forall n\in \mathcal{N}.
\end{equation}
\end{proposition}

Intuitively, if \eqref{Eqn_Pure_N_1} is violated, then we can show that $\mathcal{D}(\mathbf{e}_{n})$ has zero measure under $f$ but positive measure under $\mu$, leading to a contradiction to \eqref{Eqn_MR-}. \eqref{Eqn_Pure_N_2} is an implication of \eqref{Eqn_MR}. Given \eqref{Eqn_Pure_N_1}, the left-hand side of \eqref{Eqn_Pure_N_3} is the limit of ``MR density'' for bundle $\mathbf{e}_{n}$. If \eqref{Eqn_Pure_N_3} is violated, reducing the price of $\mathbf{e}_{n}$ will lead to an increase in the total revenue. In other words, \eqref{Eqn_Pure_N_3} follows from applying \eqref{Eqn_SOC_1} to bundle $\mathbf{e}_{n}$.

It is also worth noting that, when $f$ is strictly regular ($\phi (\mathbf{x})>0$ for almost all $\mathbf{x}\in \mathcal{X}$), we can define the generalized $\zeta$ function as
\begin{equation*}
\zeta (\mathbf{x}_{-n})=\sup\left\{\zeta\in [\underline{x},\overline{x}]:\int^{\overline{x}}_{\zeta}\phi (x_{n},\mathbf{x}_{-n})\dd x_{n}-\overline{x}f(\overline{x},\mathbf{x}_{-n})\geq 0\right\},
\end{equation*}
where we let $\sup \emptyset=\underline{x}$. Then \eqref{Eqn_Pure_N_3} can be simplified as
\begin{equation*}
p(\mathbf{1})-(N-1)\underline{x}\leq \zeta (\mathbf{0}_{-n}).
\end{equation*}

Next, consider selling $N$ items to unit-demand buyers, which amounts to letting $\mathcal{X}=[\underline{x},\overline{x}]^{N}$ and $\mathcal{Q}={\mathbf{q}\in [0,1]^{N}:\mathbf{q}\cdot\mathbf{1}\leq 1}$. This setting is an extension of the $k=1/2$ case in \Cref{Sec_SubsComp} where products are perfect substitutes. \Cref{Prop_Separate_N} provides two necessary conditions for the optimality of a symmetric separate selling mechanism where only $\mathcal{D}(\mathbf{0})$ and $\{\mathcal{D}(\mathbf{e}_{n})\}_{n\in \mathcal{N}}$ have positive measure under $f$.

\begin{proposition}
\label{Prop_Separate_N}
Let $\mathcal{X}=[\underline{x},\overline{x}]^{N}$ and $\mathcal{Q}=\{\mathbf{q}\in [0,1]^{N}:\mathbf{q}\cdot\mathbf{1}\leq 1\}$. Then a symmetric separate selling mechanism $p$ is optimal only if
\begin{align}
\label{Eqn_Separate_N_1}
\mu (\mathcal{D}(\mathbf{e}_{n})) & =0, \quad \forall n\in \mathcal{N}, \\
\label{Eqn_Separate_N_2}
\int^{\overline{x}}_{p(\mathbf{e}_{n})}\phi (x,\dotsc,x)\dd x-\overline{x}f(\overline{\mathbf{x}}) & \geq 0, \quad \forall n\in \mathcal{N}.
\end{align}
\end{proposition}

The intuition of \Cref{Prop_Separate_N} is similar to that of \Cref{Prop_Pure_N}: \eqref{Eqn_Separate_N_1} follows from \eqref{Eqn_MR}. \eqref{Eqn_Separate_N_2} follows from applying \eqref{Eqn_SOC_1} to bundle $(1/N)\mathbf{1}$. Again, when $f$ is strictly regular, we can define the $\zeta_{1/N}$ function as
\begin{equation*}
\begin{aligned}
\zeta_{1/N} (\mathbf{x}_{-n}) & =\sup\bigg\{\zeta\in [\underline{x},\overline{x}]:((\overline{x},\mathbf{x}_{-n})-(\overline{x}-\zeta)\mathbf{1})\in \mathcal{X}, \\
& \quad \quad \quad \quad \int^{\overline{x}}_{\zeta }\phi ((\overline{x},\mathbf{x}_{-n})-(\overline{x}-x)\mathbf{1})\dd x-\overline{x}f(\overline{x},\mathbf{x}_{-n})\geq 0\bigg\}.
\end{aligned}
\end{equation*}
Then \eqref{Eqn_Separate_N_2} can be simplified as
\begin{equation*}
p(\mathbf{e}_{n})\leq \zeta_{1/N} (\overline{\mathbf{x}}_{-n}).
\end{equation*}

When $N=2$, \eqref{Eqn_Separate_N_2} can be inferred from \citet[Theorem 1]{thanassoulis2004haggling}. For general $N$, we believe that both \Cref{Prop_Pure_N} and \Cref{Prop_Separate_N} are novel to the literature. \Cref{Cor_N} leverages the two propositions to examine how variations in the number of products affect the optimal mechanism.

\begin{corollary}
\label{Cor_N}
Suppose that $x_{1},\dotsc,x_{N}$ are i.i.d. over $[\underline{x},\underline{x}+1]$ with p.d.f. $g$.
\begin{enumerate}
\item If buyers are additive and $f$ is strictly regular, then there exists $N^{*}$ such that pure bundling is suboptimal when $N\geq N^{*}$. \label{Cor_N_1}
\item If buyers are unit-demand and $g$ is nonincreasing, then symmetric separate selling is suboptimal when $N\leq \underline{x}$. \label{Cor_N_2}
\end{enumerate}
\end{corollary}

In recent studies, \citet[Theorem 6]{daskalakis2017strong} show that pure bundling is suboptimal for additive buyers when $N$ is sufficiently large. \citet[Theorem 2]{hashimoto2025selling} prove that symmetric separate selling is optimal for unit-demand buyers if and only if $\underline{x}$ is sufficiently small. Both results are derived under uniformly distributed types. \Cref{Cor_N} extends these findings to a broader class of type distributions.

In \Cref{Sec_Verify_2D}, we revisit the problem of selling two products in the SRS environment. With the help of $\zeta$, we establish sufficient and necessary conditions for the optimality of various bundling strategies.

\subsection{Revisiting Propositions \ref{Prop_2D} and \ref{Prop_SubsComp}}

In this section, we use \Cref{Thm_MR} to prove parts \ref{Prop_2D_2} and \ref{Prop_2D_3} of Propositions \ref{Prop_2D} and \ref{Prop_SubsComp}, taking part \ref{Prop_2D_1} of both propositions as given. The settings and notations are the same as those in Sections \ref{Sec_2D} and \ref{Sec_SubsComp}.

\Cref{Cor_Active} focuses on active bundles and makes use of \eqref{Eqn_MR}.

\begin{claim}
\label{Cor_Active}
If $q\hat{\mathbf{n}}_{k}+\mathbf{e}_{2}$ is pooling, then $\int^{b^{q}}_{a^{q}}\Phi_{k}(x_{1})\dd x_{1}=0$ unless $k>1$ and $a^{q}=0$. If $q\hat{\mathbf{n}}_{k}+\mathbf{e}_{2}$ is separating, then $\Phi_{k}(a^{q})=\Phi_{k}(b^{q})=0$.
\end{claim}

\begin{proof}
If $q\hat{\mathbf{n}}_{k}+\mathbf{e}_{2}$ is pooling, its demand set is given by \eqref{Eqn_D_k}, except when $k>1$ and $a^{q}=0$ (see \Cref{Ftn_D_k} for a discussion). The first statement follows from \eqref{Eqn_MR}.

If $q\hat{\mathbf{n}}_{k}+\mathbf{e}_{2}$ is separating, we assume that $q>0$ and let $Q_{\delta}=\{\hat{q}\hat{\mathbf{n}}_{k}+\mathbf{e}_{2}:q-\delta\leq \hat{q}\leq q+\delta\}$ for $\delta<\min (q,k-q)$. By \eqref{Eqn_MR},
\begin{equation*}
\MR (Q_{\delta})=-\int^{b^{q+\delta}}_{a^{q-\delta}}\Phi (x_{1})\dd x_{1}=0.
\end{equation*}
When $\delta\to 0$, $[a^{q-\delta},b^{q+\delta}]\to \{a^{q}\}$, which implies $\Phi (a^{q})=0$. The case where $q=0$ can be proved analogously.
\end{proof}

\Cref{Cor_Inactive} characterizes the boundaries of pooling bundles and makes use of \eqref{Eqn_SOC_1}. Before proceeding, we state a preliminary result from convex analysis.

\begin{lemma}[{\citet[Theorem 24.5]{rockafellar1970}}]
\label{Lem_Continuity}
For any feasible mechanism, any $\mathbf{q}\in \mathcal{Q}$, and any $\delta>0$, there exists $\overline{\varepsilon}_{1},\overline{\varepsilon}_{2}>0$, such that for any $\hat{\mathbf{q}}\in (\mathbf{q}+\overline{\varepsilon}_{1}B^{N})$ and $\varepsilon\in (-\overline{\varepsilon}_{2},\overline{\varepsilon}_{2})$,
\begin{equation*}
\mathcal{D}(\hat{\mathbf{q}};\overline{p}+\varepsilon\mathbb{I}_{Q})\subset \mathcal{D}(\mathbf{q})+\delta B^{N}.
\end{equation*}
\end{lemma}

Intuitively, \Cref{Lem_Continuity} says that demand sets are ``continuous'' in both $\mathbf{q}$ and $p$.

\begin{claim}
\label{Cor_Inactive}
If $q\hat{\mathbf{n}}_{k}+\mathbf{e}_{2}$ is pooling, then $\Phi_{k}(a^{q})\geq 0$ unless $q=0$, and $\Phi_{k}(b^{q})\geq 0$ unless $q=k$.
\end{claim}

\begin{proof}
Suppose that $k\leq 1$, $q>0$, and $\Phi_{k}(a^{q})<0$. We choose $\delta>0$ sufficiently small such that $\delta<\max(1-\overline{u}(x),z_{k}(x))-\zeta_{k}(x)$ for all $x\in (a^{q}-\delta,a^{q}+\delta)$ (which will become $x\in [0,a^{q}+\delta)$ if $a^{q}=0$). By \Cref{Lem_Continuity}, there exists $\overline{\varepsilon}>0$ such that $[a^{\hat{q}},b^{\hat{q}}]\subset (a^{q}-\delta,a^{q}+\delta)$ for any $\hat{q}\in (q-\overline{\varepsilon},q+\overline{\varepsilon})$. The bundle $\hat{q}\hat{\mathbf{n}}_{k}+\mathbf{e}_{2}$ cannot be active because of \eqref{Eqn_MR}. Thus, we can conclude that $\overline{u}'(a^{q}-)<\overline{u}'(a^{q}+)=q$, and any $\hat{\mathbf{q}}=\hat{q}\hat{\mathbf{n}}_{k}+\mathbf{e}_{2}$ satisfying $\overline{u}'(a^{q}-)<\hat{q}<q$ is inactive. We fix such a $\hat{\mathbf{q}}$ and consider the price schedule $\overline{p}+\varepsilon \mathbb{I}_{Q}$, where $\varepsilon<0$ and $Q=\{(\hat{q}_{1},\hat{q}_{2}),(\hat{q}_{2},\hat{q}_{1})\}$. Again, \Cref{Lem_Continuity} implies that $\mathcal{D}(\hat{\mathbf{q}};\overline{p}+\varepsilon \mathbb{I}_{Q})\subset \mathcal{D}(\hat{\mathbf{q}})+\delta B^{2}$. Recall that $\mathcal{D}(\hat{\mathbf{q}})=\{(a^{q},1)-(1-x_{2})\mathbf{n}_{k}:\max(1-\overline{u}(a^{q}),z_{k}(a^{q}))\leq x_{2}\leq 1\}$ and that $\delta<\max(1-\overline{u}(x),z_{k}(x))-\zeta_{k}(x)$ for all $x\in (a^{q}-\delta,a^{q}+\delta)$. There must be
\begin{equation*}
\MR_{-\varepsilon}(Q)=-2\mu (\mathcal{D}(\hat{\mathbf{q}};\overline{p}+\varepsilon \mathbb{I}_{Q}))<0,
\end{equation*}
a contradiction to \eqref{Eqn_SOC_1}. Hence, our supposition is not true, meaning that $\Phi_{k}(a^{q})\geq 0$. When $k>1$, we should take care of the edge case characterized in \Cref{Ftn_D_k}, but the key steps are the same. Also, $\Phi_{k}(b^{q})\geq 0$ can be proved analogously.
\end{proof}

Finally, suppose that $k>1/2$ and that $\mathbf{k}$ is not pooling. Then $a^{k}=b^{k}=1$. Combining Corollaries \ref{Cor_Active} and \ref{Cor_Inactive}, there must be $\Phi_{k}(1)\geq 0$. However, $z_{k}(1)=1$ for any $k>1/2$, meaning that $\Phi_{k}(1)=-f(1,1)<0$, a contradiction. Hence, the grand bundle $\mathbf{k}$ is pooling if $k>1/2$. We therefore complete the proof of parts \ref{Prop_2D_2} and \ref{Prop_2D_3} of Propositions \ref{Prop_2D} and \ref{Prop_SubsComp}. Part \ref{Prop_2D_1} of both propositions will be deferred to \Cref{Sec_Active}, after we introduce \Cref{Thm_Active}.

\subsection{Active Bundles}
\label{Sec_Active}

This section applies the first-order conditions in \Cref{Thm_MR} to characterize active bundles under strict regularity. To this end, we extend several definitions from Sections \ref{Sec_2D} and \ref{Sec_SubsComp} to the current setting and introduce additional concepts as needed.

A nonzero bundle $\mathbf{q}$ is \emph{active} if, for any $\delta>0$, $\mathcal{D}(\mathbf{q}+\delta B^{N})$ has positive measure with respect to $f$; otherwise, it is \emph{inactive}.\footnote{For any $\mathbf{y}\in \mathbb{R}^{N}$, $\mathcal{Y},\mathcal{Z}\subset \mathbb{R}^{N}$, and $\delta\in \mathbb{R}$, we let $\mathbf{y}+\delta\mathcal{Z}=\{\mathbf{y}+\delta \mathbf{z}:\mathbf{z}\in \mathcal{Z}\}$ and $\mathcal{Y}+\delta\mathcal{Z}=\{\hat{\mathbf{y}}+\delta \mathbf{z}:\hat{\mathbf{y}}\in \mathcal{Y}\text{ and }\mathbf{z}\in \mathcal{Z}\}$. Then $\mathbf{q}+\delta B^{N}$ is an open ball centered around $\mathbf{q}$ with radius $\delta$.} Active bundles are important because of their connection to the gradient of $u_{p}$: If $u_{p}$ is differentiable at $\mathbf{x}$, then either $u_{p}(\mathbf{x})=0$, or $\nabla u_{p}(\mathbf{x})$ is active.\footnote{Suppose that $\nabla u_{p}(\mathbf{x})=\mathbf{q}$. By \citet[Theorem 25.5]{rockafellar1970}, for any $\delta>0$, there exists $\varepsilon>0$, such that the differentiable points of $u_{p}$ in $\mathbf{x}+\varepsilon B^{N}$ belongs to $\mathbf{q}+\delta B^{N}$. Since the set of nondifferentiable points of $u_{p}$ has zero measure with respect to $f$, $\mathcal{D}(\mathbf{q}+\delta B^{N})$ must have positive measure with respect to $f$. Hence, either $\mathbf{q}$ is active, or $\mathbf{q}=\mathbf{0}$.}

Denote by $\overline{\bd}(\mathcal{X})$ the \emph{top boundary} of $\mathcal{X}$, where
\begin{equation*}
\overline{\bd}(\mathcal{X})=\{\mathbf{x}\in \bd (\mathcal{X}):\mathbf{x}\cdot\mathbf{n}_{\mathbf{x}}>0\text{ for all }\mathbf{n}_{\mathbf{x}}\in \NV (\mathbf{x})\}.
\end{equation*}
Note that the definitions of $\overline{\bd}(\mathcal{X})$ and $\underline{\bd}(\mathcal{X})$ differ slightly. Intuitively, $\overline{\bd}(\mathcal{X})$ can be viewed as the ``interior'' of the boundary where $\mu$ assigns positive mass.

Finally, recall that $f$ is \emph{strictly regular} if, for almost all $\mathbf{x}\in \mathcal{X}$,
\begin{equation*}
\phi(x)=\mathbf{x}\cdot \nabla f(\mathbf{x})+(N+1)f(\mathbf{x})>0.
\end{equation*}
Under strict regularity, $\mu$ assigns positive mass to $\overline{\bd}(\mathcal{X})$ and negative mass to $\underline{\bd}(\mathcal{X})\cup \Int (\mathcal{X})$.

Now we are ready to introduce the key concepts of this section. Denote by $\NV _{A}$ the set of all outward unit normal vectors associated with points on the top boundary, that is,
\begin{equation*}
\NV _{A}=\bigcup_{\mathbf{x}\in \overline{\bd}(\mathcal{X})}\NV (\mathbf{x}).
\end{equation*}
Denote by $\mathcal{Q}_{A}$ the set of bundles $\mathbf{q}\in \bd (\mathcal{Q})$ such that $(\mathbf{q}+\varepsilon \mathbf{n}_{\mathbf{x}})\notin \mathcal{Q}$ for some $\mathbf{n}_{\mathbf{x}}\in\NV _{A}$ and any $\varepsilon>0$, that is,
\begin{equation*}
\mathcal{Q}_{A}=\{\mathbf{q}\in \bd (\mathcal{Q}):\exists \mathbf{n}_{\mathbf{x}}\in \NV _{A}\text{ such that }(\mathbf{q}+\varepsilon \mathbf{n}_{\mathbf{x}})\notin \mathcal{Q}\text{ for any }\varepsilon>0\}.
\end{equation*}
We are interested in bundles in $\mathcal{Q}_{A}$ because they are ``more likely'' to be sold to buyers on the top boundary than other bundles. By construction, if $\mathbf{q}\notin \mathcal{Q}_{A}$, then for any $\mathbf{x}\in \overline{\bd}(\mathcal{X})$, there exists some $\varepsilon>0$ such that $\mathbf{q}+\varepsilon \mathbf{n}_{\mathbf{x}}\in \mathcal{Q}_{A}$. In \Cref{Lem_Active}, we show that if $\mathbf{x}\in \overline{\bd}(\mathcal{X})$ is an element of $\mathcal{D}(\mathbf{q})$, then it must also be an element of $\mathcal{D}(\mathbf{q}+\varepsilon \mathbf{n}_{\mathbf{x}})$.

\begin{lemma}
\label{Lem_Active}
For any feasible mechanism, if $\mathbf{x}\in \mathcal{D}(\mathbf{q})$ for some $\mathbf{x}\in \bd (\mathcal{X})$, then for any $\varepsilon>0$ and $(\mathbf{q}+\varepsilon\mathbf{n}_{\mathbf{x}})\in \mathcal{Q}$, $\mathcal{D}(\mathbf{q}+\varepsilon\mathbf{n}_{\mathbf{x}})=\mathcal{D}(\mathbf{q})\cap \mathcal{S}(\mathbf{n}_{\mathbf{x}})$, where $\mathcal{S}(\mathbf{n}_{\mathbf{x}})$ is the exposed face of $\mathcal{X}$ with $\mathbf{n}_{\mathbf{x}}$ as its outward normal.
\end{lemma}

\Cref{Thm_Active} states the main result of this section.

\begin{theorem}
\label{Thm_Active}
Suppose that $f$ is strictly regular. Then for any optimal mechanism, $\mathbf{q}$ is active only if $\mathbf{q}\in \mathcal{Q}_{A}$.
\end{theorem}

\begin{proof}
Suppose that $\mathbf{q}\notin \mathcal{Q}_{A}$ is active. To save notation, we will write $Q_{\delta}=\mathbf{q}+\delta B^{N}$. By definition, for any $\delta>0$, $\mathcal{D}(Q_{\delta})$ has positive measure with respect to $f$. If $\mu (\mathcal{D}(Q_{\delta})\cap \overline{\bd}(\mathcal{X}))=0$, then
\begin{equation*}
\mu (\mathcal{D}(Q_{\delta}))<\mu (\mathcal{D}(Q_{\delta})\cap \mathcal{D}(Q_{\delta}^{c}))\leq 0,
\end{equation*}
where the first inequality is due to strict regularity, and the second inequality is due to \eqref{Eqn_Qualification}. Thus,
\begin{equation*}
\mu (\mathcal{D}(Q_{\delta}^{c}))=\mu (\mathcal{X})-\mu (\mathcal{D}(Q_{\delta}))+\mu (\mathcal{D}(Q_{\delta})\cap \mathcal{D}(Q_{\delta}^{c}))>\mu (\mathcal{X})=-1,
\end{equation*}
implying that $\MR_{+}(Q_{\delta})>0$, a contradiction to \eqref{Eqn_MR+}. Hence, $\mu (\mathcal{D}(Q_{\delta})\cap \overline{\bd}(\mathcal{X}))>0$ for any $\delta>0$.

We choose a sufficiently small $\delta$ such that $Q_{\delta}\cap \mathcal{Q}_{A}=\emptyset$. For any $\mathbf{x}\in \mathcal{D}(Q_{\delta})\cap \overline{\bd}(\mathcal{X})$, there exist $\hat{\mathbf{q}}\in Q_{\delta}$ such that $\mathbf{x}\in \mathcal{D}(\hat{\mathbf{q}})$, and $\hat{\varepsilon}>0$ such that $\hat{\mathbf{q}}+\hat{\varepsilon}\mathbf{n}_{\mathbf{x}}\in \mathcal{Q}_{A}$. By \Cref{Lem_Active},
\begin{equation*}
\mathcal{D}(\hat{\mathbf{q}}+\hat{\varepsilon}\mathbf{n}_{\mathbf{x}})=\mathcal{D}(\hat{\mathbf{q}})\cap\mathcal{S}(\mathbf{n}_{\mathbf{x}})\subseteq \overline{\bd}(\mathcal{X}).
\end{equation*}
Let $\hat{Q}$ be the collection of all such $\hat{\mathbf{q}}+\hat{\varepsilon}\mathbf{n}_{\mathbf{x}}$. It can be verified that $\mathcal{D}(\hat{Q})=\mathcal{D}(Q_{\delta})\cap \overline{\bd}(\mathcal{X})$. Thus, $\mu (\mathcal{D}(\hat{Q}))>0$, a contradiction to \eqref{Eqn_MR-}. Hence, $\mathbf{q}\notin \mathcal{Q}_{A}$ is never active.
\end{proof}

If the type space is a hyperrectangle, then $\NV _{A}$ consists of all unit vectors in the nonnegative orthant of the $N$-sphere, and $\mathcal{Q}_{A}$ consists of all bundles $\mathbf{q}$ such that any $\hat{\mathbf{q}}>\mathbf{q}$ does not belong to $\mathcal{Q}$.\footnote{For any two vectors $\mathbf{q},\hat{\mathbf{q}}\in \mathbb{R}^{N}$, we write $\mathbf{q}\leq \hat{\mathbf{q}}$ if $q_{n}\leq \hat{q}_{n}$ for all $n\in \mathcal{N}$, and $\mathbf{q}<\hat{\mathbf{q}}$ if $\mathbf{q}\leq \hat{\mathbf{q}}$ but $\mathbf{q}\neq \hat{\mathbf{q}}$.} In this case, \Cref{Thm_Active} specializes to Proposition 2 in \citet{pavlov2011property}. If we further have $\mathcal{Q}=[0,1]^{N}$, then $\mathcal{Q}_{A}$ consists of all bundles $\mathbf{q}$ such that $q_{n}=1$ for some $n\in \mathcal{N}$. In this case, \Cref{Thm_Active} specializes to Lemma 2 in \citet{mcafee1988multidimensional} and part \ref{Prop_2D_1} of our Propositions \ref{Prop_2D} and \ref{Prop_SubsComp}. The contribution of \Cref{Thm_Active}, in contrast to \citet{pavlov2011property}, is that it applies to any convex type space. In \Cref{Sec_AsyType}, we use \Cref{Thm_Active} to reproduce two key results of \citet[Propositions 1 and 7]{bikhchandani2022selling} where type spaces are not rectangles.

\subsection{Pooling Bundles}

This section invokes the second-order conditions in \Cref{Thm_MR} to obtain a sufficient condition for pooling bundles. Recall that an active bundle $\mathbf{q}$ is \emph{pooling} if $\mathcal{D}(\mathbf{q})$ has positive measure with respect to $f$; otherwise, it is \emph{separating}.

Denote by $\NV _{P}$ the set of unit vectors associated with an exposed face that is bounded away from the bottom boundary, that is,
\begin{equation*}
\NV _{P}=\{\mathbf{n}_{\mathbf{x}}\in \NV _{A}: \exists \overline{\delta}>0 \text{ such that } (\mathcal{S}(\mathbf{n}_{\mathbf{x}})+\delta B^{N})\cap \underline{\bd}(\mathcal{X})=\emptyset\text{ for any }\delta<\overline{\delta}\}.
\end{equation*}
Denote by $\mathcal{Q}_{P}$ the set of bundles $\mathbf{q}\in \bd (\mathcal{Q})$ for which there exists $\mathbf{n}_{\mathbf{x}}\in \NV _{P}$ that lies in the interior of the outward normal cone to $\mathcal{Q}$ at $\mathbf{q}$, denoted by $\NC (\mathbf{q})$, that is,
\begin{equation*}
\mathcal{Q}_{P}=\{\mathbf{q}\in \bd (\mathcal{Q}):\NV _{P}\cap\Int (\NC (\mathbf{q}))\neq \emptyset\}.
\end{equation*}
We are interested in $\NC (\mathbf{q})$ because it determines the demand set of $\mathbf{q}$.

\begin{lemma}
\label{Lem_NormalCone}
For any feasible mechanism, if $\mathbf{x}\in \mathcal{D}(\mathbf{q})$ for some $\mathbf{q}\in \bd (\mathcal{Q})$, then for any $\mathbf{n}_{\mathbf{q}}\in \NC (\mathbf{q})$ and $(\mathbf{x}+\mathbf{n}_{\mathbf{q}})\in \mathcal{X}$, $(\mathbf{x}+\mathbf{n}_{\mathbf{q}})\in \mathcal{D}(\mathbf{q})$. As a result, $((\mathbf{x}+\NC (\mathbf{q}))\cap \mathcal{X})\subseteq \mathcal{D}(\mathbf{q})$.
\end{lemma}

It is helpful to observe the symmetry between Lemmas \ref{Lem_NormalCone} and \ref{Lem_Active}: By \Cref{Lem_Active}, if $\mathbf{x}\in \mathcal{D}(\mathbf{q})$ holds for a \emph{boundary type} $\mathbf{x}$, then $\mathbf{x}\in \mathcal{D}(\mathbf{q}+\varepsilon \mathbf{n}_{\mathbf{x}})$ for any $\varepsilon>0$. By \Cref{Lem_NormalCone}, if $\mathbf{x}\in \mathcal{D}(\mathbf{q})$ holds for a \emph{boundary allocation} $\mathbf{q}$, then $(\mathbf{x}+\mathbf{n}_{\mathbf{q}})\in \mathcal{D}(\mathbf{q})$ for any $\mathbf{n}_{\mathbf{q}}$. Such symmetry is a natural result of the convex conjugacy between $u$ and $p$.

\Cref{Thm_Pooling} states the main result of this section.

\begin{theorem}
\label{Thm_Pooling}
For any optimal mechanism, $\mathbf{q}$ is pooling if $\mathbf{q}\in \mathcal{Q}_{P}$.
\end{theorem}

Due to space limitation, we prove \Cref{Thm_Pooling} for our leading case where $\mathcal{X}=[0,1]^{2}$ and defer the complete proof to Appendix. In this special case, $\underline{\bd}(\mathcal{X})=\emptyset$, so $\NV _{A}=\NV _{P}$. To keep our notation consistent with $\MR_{-\varepsilon}$ and $\MR_{+\varepsilon}$, we let $\mathcal{D}_{\varepsilon}(\mathbf{q})=\mathcal{D}(\mathbf{q};\overline{p}+\varepsilon \mathbb{I}_{\mathbf{q}})$.

\begin{proof}[Proof of the leading case]
Suppose that $\mathbf{e}_{2}\in \Int (\NC (\mathbf{q}))$ for some $\mathbf{q}\in \bd (\mathcal{Q})$ and that $\mathbf{q}$ is not pooling. If there exists $\mathbf{x}\in \mathcal{D}(\mathbf{q})$ such that $\mathbf{x}\notin \mathcal{S}(\mathbf{e}_{2})$, then for sufficiently small $\tau>0$, we have $(\mathbf{x}+\tau \mathbf{e}_{2})\in \Int (\mathcal{X})$. By \Cref{Lem_NormalCone}, $\mathcal{D}(\mathbf{q})$ contains a neighborhood of $\mathbf{x}+\tau \mathbf{e}_{2}$, a contradiction to the supposition that $\mathbf{q}$ is not pooling. Thus, $\mathcal{D}(\mathbf{q})\subseteq \mathcal{S}(\mathbf{e}_{2})$.

Consider the price schedule $\overline{p}+\varepsilon \mathbb{I}_{\mathbf{q}}$ for $\varepsilon<0$. If $(x_{1},1)\in (\mathcal{D}_{\varepsilon}(\mathbf{q})\cap \mathcal{S}(\mathbf{e}_{2}))$, then $(x_{1},x_{2})\in \mathcal{D}_{\varepsilon}(\mathbf{q})$ whenever $\hat{\mathbf{x}}\cdot\mathbf{q}-(\overline{p}(\mathbf{q})+\varepsilon)\geq u_{p}(\hat{\mathbf{x}})$. We denoted the solution to this last inequality (subject to $\hat{\mathbf{x}}\in \mathcal{X}$) by $x_{2}\geq z(x_{1})$. Let $\mathcal{D}_{\varepsilon,1}=\{x_{1}\in [0,1]:(x_{1},1)\in \mathcal{D}_{\varepsilon}(\mathbf{q})\cap \mathcal{S}(\mathbf{e}_{2})\}$, and define $\mathcal{D}_{\varepsilon,2}$ analogously. By \Cref{Lem_MR},
\begin{equation*}
\MR_{-\varepsilon}(\mathbf{q})=\int_{\mathcal{D}_{\varepsilon,1}}\left[\int^{1}_{z(x_{1})}\phi (\hat{\mathbf{x}})\dd x_{2}-f(x_{1},1)\right]\dd x_{1}-\int_{\mathcal{D}_{\varepsilon,2}}f(1,x_{2})\dd x_{2}.
\end{equation*}
Note that $\phi$ is bounded from above and $f$ is bounded away from zero. When $\varepsilon\to 0$, $\mathcal{D}_{\varepsilon}(\mathbf{q})\to \mathcal{D}(\mathbf{q})$, meaning that $z(x_{1})\to 1$. By \Cref{Lem_Continuity}, we can choose $\varepsilon$ sufficiently close to zero such that for any $x_{1}\in \mathcal{D}_{\varepsilon,1}$,
\begin{equation*}
\int^{1}_{z(x_{1})}\phi (\hat{\mathbf{x}})\dd x_{2}-f(x_{1},1)<0,
\end{equation*}
implying that $\MR_{-\varepsilon}(\mathbf{q})<0$, a contradiction to \eqref{Eqn_SOC_1}. Hence, our supposition is not true, and $\mathbf{q}$ must be pooling. The proof can be easily extended to other $\mathbf{n}_{\mathbf{x}}\in \NV _{P}$ such that $\mathbf{n}_{\mathbf{x}}\in \Int (\NC (\mathbf{q}))$.
\end{proof}

Consider extending the settings in Sections \ref{Sec_2D} and \ref{Sec_SubsComp} to $N$ products, that is, $\mathcal{X}=[0,1]^{N}$ and $\mathcal{Q}=\Conv \{\mathbf{0},\mathbf{e}_{1},\dotsc,\mathbf{e}_{N},\mathbf{k}\}$. Since $\underline{\bd}(\mathcal{X})=\emptyset$, we have $\NV _{A}=\NV _{P}$, and both sets consist of all unit vectors in the nonnegative orthant. When $1/N\leq k<1$, $\mathbf{e}_{n}\in \Int (\NC (\mathbf{e}_{n}))$ for any $n\in \mathcal{N}$, so $\mathbf{e}_{n}\in \mathcal{Q}_{P}$. When $k>1/N$, $(1/\sqrt{N})\mathbf{1}\in \NC (\mathbf{k})$, so $\mathbf{k}\in \mathcal{Q}_{P}$. These results are formally stated in \Cref{Cor_Pooling}.

\begin{corollary}
\label{Cor_Pooling}
Suppose that $\mathcal{X}=[0,1]^{N}$ and that $\mathcal{Q}=\Conv \{\mathbf{0},\mathbf{e}_{1},\dotsc,\mathbf{e}_{N},\mathbf{k}\}$. Then in any optimal mechanism:
\begin{enumerate}
\item If $1/N\leq k<1$, then $\mathbf{e}_{1},\dotsc,\mathbf{e}_{N}$ are pooling.
\item If $k>1/N$, then $\mathbf{k}$ is pooling.
\end{enumerate}
\end{corollary}

\Cref{Fig_Pooling} provides a graphical illustration of \Cref{Cor_Pooling} in the case where $N=2$. In the top panel, the red curve represents the top boundary of $\mathcal{X}$. In the bottom panel, each blue-shaded sector represents the normal cone of a bundle in $\mathcal{Q}_{P}$, and vectors in $\NV _{P}$ are colored in red.

