\subsection{Proofs of All Lemmas}

\subsubsection{Proof of Lemma \ref{Lem_MR}}

When $\varepsilon<0$, $0\leq u_{\overline{p}+\varepsilon\mathbb{I}_{Q}}(\mathbf{x})-u_{p}(\mathbf{x})\leq -\varepsilon$ for all $\mathbf{x}\in \mathcal{X}$. Note that $u_{\overline{p}+\varepsilon\mathbb{I}_{Q}}(\mathbf{x})=u_{p}(\mathbf{x})-\varepsilon$ if and only if $\mathbf{x}\cdot\mathbf{q}-\overline{p}(\mathbf{q})=u_{p}(\mathbf{x})$ for some $\mathbf{q}\in Q$, which implies $\{\mathbf{x}\in \mathcal{X}:u_{\overline{p}+\varepsilon\mathbb{I}_{Q}}(\mathbf{x})=u_{p}(\mathbf{x})-\varepsilon\}=\mathcal{D}(Q)$. Let $\mathcal{A}_{(0,-\varepsilon)}=\{\mathbf{x}\in \mathcal{X}:0<u_{\overline{p}+\varepsilon\mathbb{I}_{Q}}(\mathbf{x})-u_{p}(\mathbf{x})<-\varepsilon\}$. Then
\begin{equation*}
\lim_{\varepsilon\to 0-}\int_{\mathcal{X}}\left(\frac{u_{\overline{p}+\varepsilon\mathbb{I}_{Q}}-u_{p}}{\varepsilon}\right)\dd\mu=-\int_{\mathcal{X}}\mathbb{I}_{\mathcal{D}(Q)}\dd \mu+\lim_{\varepsilon\to 0-}\int_{\mathcal{X}}\left(\frac{u_{\overline{p}+\varepsilon\mathbb{I}_{Q}}-u_{p}}{\varepsilon}\right)\mathbb{I}_{\mathcal{A}_{(0,-\varepsilon)}}\dd\mu,
\end{equation*}
where the second term equals zero by $\mathbb{I}_{\mathcal{A}_{(0,-\varepsilon)}}\to 0$ and Lebesgue's dominated convergence theorem. Hence, $\MR_{-}(Q)=-\mu(\mathcal{D}(Q))$.

When $\varepsilon>0$, $-\varepsilon\leq u_{\overline{p}+\varepsilon\mathbb{I}_{Q}}(\mathbf{x})-u_{p}(\mathbf{x})\leq 0$ for all $\mathbf{x}\in \mathcal{X}$. Note that $u_{\overline{p}+\varepsilon\mathbb{I}_{Q}}(\mathbf{x})=u_{p}(\mathbf{x})$ if and only if $\mathbf{x}\cdot\mathbf{q}-\overline{p}(\mathbf{q})=u_{p}(\mathbf{x})$ for some $\mathbf{q}\in Q^{c}$, which implies $\{\mathbf{x}\in \mathcal{X}:u_{\overline{p}+\varepsilon\mathbb{I}_{Q}}(\mathbf{x})=u_{p}(\mathbf{x})\}=\mathcal{D}(Q^{c})$. Let $\mathcal{A}_{(-\varepsilon,0)}=\{\mathbf{x}\in \mathcal{X}:-\varepsilon<u_{\overline{p}+\varepsilon\mathbb{I}_{Q}}(\mathbf{x})-u_{p}(\mathbf{x})<0\}$ and $\mathcal{A}_{-\varepsilon}=\{\mathbf{x}\in \mathcal{X}:u_{\overline{p}+\varepsilon\mathbb{I}_{Q}}(\mathbf{x})-u_{p}(\mathbf{x})=-\varepsilon\}$. Then $\mathcal{A}_{(-\varepsilon,0)}\cup \mathcal{A}_{-\varepsilon}=\{\mathbf{x}\in \mathcal{X}:u_{\overline{p}+\varepsilon\mathbb{I}_{Q}}(\mathbf{x})<u_{p}(\mathbf{x})\}=\mathcal{X}\setminus \mathcal{D}(Q^{c})$, and
\begin{equation*}
\begin{aligned}
\lim_{\varepsilon\to 0+}\int_{\mathcal{X}}\left(\frac{u_{\overline{p}+\varepsilon\mathbb{I}_{Q}}-u_{p}}{\varepsilon}\right)\dd\mu
& =-\int_{\mathcal{X}}\mathbb{I}_{\mathcal{A}_{-\varepsilon}}\dd \mu+\lim_{\varepsilon\to 0+}\int_{\mathcal{X}}\left(\frac{u_{\overline{p}+\varepsilon\mathbb{I}_{Q}}-u_{p}}{\varepsilon}\right)\mathbb{I}_{\mathcal{A}_{(-\varepsilon,0)}}\dd\mu \\
& =-\int_{\mathcal{X}}\mathbb{I}_{\mathcal{A}_{-\varepsilon}\cup \mathcal{A}_{(-\varepsilon,0)}}\dd \mu+\lim_{\varepsilon\to 0+}\int_{\mathcal{X}}\left(1+\frac{u_{\overline{p}+\varepsilon\mathbb{I}_{Q}}-u_{p}}{\varepsilon}\right)\mathbb{I}_{\mathcal{A}_{(-\varepsilon,0)}}\dd\mu.
\end{aligned}
\end{equation*}
Similarly, $\MR_{+}(Q)=\mu (\mathcal{A}_{-\varepsilon}\cup \mathcal{A}_{(-\varepsilon,0)})=\mu (\mathcal{D}(Q^{c}))-\mu (\mathcal{X})=1+\mu (\mathcal{D}(Q^{c}))$.

\subsubsection{Proof of Lemma \ref{Lem_Continuity}}

Let $\tilde{\mathcal{Q}}$ be an open convex set such that $\mathcal{Q}\subset \tilde{\mathcal{Q}}$. Let $\tilde{p}:\tilde{\mathcal{Q}}\mapsto \mathbb{R}$ such that
\begin{equation*}
\tilde{p}(\mathbf{q})=
\begin{cases}
\overline{p}(\mathbf{q}) & \mathbf{q}\in \mathcal{Q}, \\
K & \mathbf{q}\in \tilde{\mathcal{Q}}\setminus \mathcal{Q},
\end{cases}
\end{equation*}
where $K>\sup\{\mathbf{x}\cdot\mathbf{q}:\mathbf{x}\in \mathcal{X}\text{, }\mathbf{q}\in \mathcal{Q}\}$. It can be verified that $\tilde{p}$ is convex on $\tilde{\mathcal{Q}}$, and the subdifferential of $\tilde{p}$ at any $\mathbf{q}\in \mathcal{Q}$ is the same as that of $\overline{p}$. The lemma follows from applying Theorem 24.5 of \citet{rockafellar1970} to $\tilde{p}$.

\subsubsection{Proof of Lemma \ref{Lem_Active}}

Let $\hat{\mathbf{x}}\in \mathcal{D}(\mathbf{q}+\varepsilon\mathbf{n}_{\mathbf{x}})$. Then
\begin{equation}
\label{Eqn_A1}
\mathbf{x}\cdot (\mathbf{q}+\varepsilon\mathbf{n}_{\mathbf{x}}-\mathbf{q})-(\overline{p}(\mathbf{q}+\varepsilon\mathbf{n}_{\mathbf{x}})-\overline{p}(\mathbf{q}))\geq \varepsilon (\mathbf{x}-\hat{\mathbf{x}})\cdot\mathbf{n}_{\mathbf{x}}\geq 0,
\end{equation}
meaning that $\mathbf{x}\in \mathcal{D}(\mathbf{q}+\varepsilon\mathbf{n}_{\mathbf{x}})$. Since the analysis applies to any point in $\mathcal{S}(\mathbf{n}_{\mathbf{x}})$, we actually have $(\mathcal{D}(\mathbf{q})\cap \mathcal{S}(\mathbf{n}_{\mathbf{x}}))\subseteq \mathcal{D}(\mathbf{q}+\varepsilon\mathbf{n}_{\mathbf{x}})$. Moreover, all inequalities in \eqref{Eqn_A1} should be equalities, implying that $\hat{\mathbf{x}}\cdot (\mathbf{q}+\varepsilon\mathbf{n}_{\mathbf{x}}-\mathbf{q})-(\overline{p}(\mathbf{q}+\varepsilon\mathbf{n}_{\mathbf{x}})-\overline{p}(\mathbf{q}))=0$, so $\mathcal{D}(\mathbf{q}+\varepsilon\mathbf{n}_{\mathbf{x}})\subseteq (\mathcal{D}(\mathbf{q})\cap \mathcal{S}(\mathbf{n}_{\mathbf{x}}))$.

\subsubsection{Proof of Lemma \ref{Lem_NormalCone}}

For any $\mathbf{n}_{\mathbf{q}}\in \NC (\mathbf{q})$ such that $(\mathbf{x}+\mathbf{n}_{\mathbf{q}})\in \mathcal{X}$, we have $(\mathbf{x}+\mathbf{n}_{\mathbf{q}}-\mathbf{x})\cdot (\mathbf{q}-\hat{\mathbf{q}})\geq 0$ for any $\hat{\mathbf{q}}\in \mathcal{Q}$, which implies $(\mathbf{x}+\mathbf{n}_{\mathbf{q}})\in \mathcal{D}(\mathbf{q})$. The lemma follows immediately.

\subsection{Proof of Proposition \ref{Prop_Pure_N}}

Suppose that $p(\mathbf{1})-(N-1)\underline{x}>\overline{x}$. Then there exists $c\in (\underline{x},\overline{x})$ such that type $\mathbf{x}=(c,\dotsc,c,\overline{x})$ is indifferent between bundles $\mathbf{0}$ and $\mathbf{1}$. It is easy to see that $\mathbf{x}\cdot\mathbf{e}_{N}-u(\mathbf{x})=\overline{x}\geq \hat{\mathbf{x}}\cdot\mathbf{e}_{N}-u(\hat{\mathbf{x}})$ for any $\hat{\mathbf{x}}\in \mathcal{X}$. Thus, $(c,\dotsc,c,\overline{x})\in \mathcal{D}(\mathbf{e}_{N})$, which also implies $(0,\dotsc,0,\overline{x})\in \mathcal{D}(\mathbf{e}_{N})$. $\mathcal{D}(\mathbf{e}_{N})$ has strictly positive measure with respect to the $(N-1)$-dimensional surface integral on $\overline{\bd}(\mathcal{X})$, implying that $\mu (\mathcal{D}(\mathbf{e}_{N}))>0$, a contradiction to \eqref{Eqn_MR-}. Hence, our supposition is not true, and \eqref{Eqn_Pure_N_1} is proved.

By \eqref{Eqn_Pure_N_1}, $\mathcal{D}(\mathbf{0})$ is the convex hull of $\{\underline{\mathbf{x}}+(p(\mathbf{1})-N\underline{x})\mathbf{e}_{n}\}_{n\in \mathcal{N}}$ and $\mathbf{0}$. For any $\mathbf{q}$ that is neither $\mathbf{0}$ nor $\mathbf{1}$, $\mathcal{D}(\mathbf{q})$ and $\mathcal{D}(\mathbf{0})$ are separated by a hyperplane with normal vector $\mathbf{q}$, meaning that $\mathcal{D}(\mathbf{q})\cap \mathcal{D}(\mathbf{0})$ is a subset of the convex hull of $\{\underline{\mathbf{x}}+(p(\mathbf{1})-N\underline{x})\mathbf{e}_{n}\}_{n\in \mathcal{N}}$, which is exactly $\mathcal{D}(\mathbf{1})\cap \mathcal{D}(\mathbf{0})$. Therefore, if we let $Q=\mathcal{Q}\setminus \{\mathbf{0}\}$, then $\mathcal{D}(Q)\cap \mathcal{D}(\mathbf{0})=\mathcal{D}(\mathbf{1})\cap \mathcal{D}(\mathbf{0})$. It can be verified that $\mu (\mathcal{D}(\mathbf{1})\cap \mathcal{D}(\mathbf{0}))=0$. Thus, \eqref{Eqn_Pure_N_2} follows from \eqref{Eqn_MR}.

For any $n\in \mathcal{N}$, it can be computed that
\begin{equation*}
\mathcal{D}(\mathbf{e}_{n})=\{\mathbf{x}\in \mathcal{X}: x_{m}=\underline{x}\text{ for any }m\neq n\text{ and }x_{n}\geq p(\mathbf{1})-(N-1)\underline{x}\}.
\end{equation*}
Consider changing $p(\mathbf{e}_{n})$ by $\varepsilon<0$. This price change will attract buyers in the neighborhood of $\mathcal{D}(\mathbf{e}_{n})$. Suppose that \eqref{Eqn_Pure_N_3} is false. By \Cref{Lem_Continuity}, when $\varepsilon$ is sufficiently small, $\MR_{-\varepsilon} (\mathbf{e}_{n})=-\mu \mathcal{D}(\mathbf{e}_{n};\overline{p}+\varepsilon \mathbb{I}_{\mathbf{e}_{n}})<0$, a contradiction to \eqref{Eqn_SOC_1}. Hence, our supposition is not true, and \eqref{Eqn_Pure_N_3} is proved.

\subsection{Proof of Proposition \ref{Prop_Separate_N}}

The proof is similar to the proof of \Cref{Prop_Pure_N}. For any $n\in \mathcal{N}$,
\begin{equation*}
\mathcal{D}(\mathbf{e}_{n})=\{\mathbf{x}\in \mathcal{X}: x_{n}\geq \max (x_{1},\dotsc,x_{N})\text{ and }x_{n}\geq p(\mathbf{e}_{n})\}.
\end{equation*}
For any $\mathbf{q}$ that is neither $\mathbf{0}$ nor $\mathbf{e}_{n}$, $\mathcal{D}(\mathbf{q})$ and $\mathcal{D}(\mathbf{e}_{n})$ are separated by a hyperplane with normal vector $\mathbf{q}-\mathbf{e}_{n}$, meaning that either
\begin{equation*}
(\mathcal{D}(\mathbf{q})\cap \mathcal{D}(\mathbf{\mathbf{e}_{n}}))\subseteq \{\mathbf{x}\in \mathcal{X}:x_{n}\geq \max (x_{1},\dotsc,x_{N})\text{ and }x_{n}=p(\mathbf{e}_{n})\},
\end{equation*}
or, for some $m\neq n$,
\begin{equation*}
(\mathcal{D}(\mathbf{q})\cap \mathcal{D}(\mathbf{\mathbf{e}_{n}}))\subseteq \{\mathbf{x}\in \mathcal{X}:x_{n}=x_{m}\geq \max (x_{1},\dotsc,x_{N})\}.
\end{equation*}
In both cases, $\mu (\mathcal{D}(\mathbf{q})\cap \mathcal{D}(\mathbf{\mathbf{e}_{n}}))=0$. Thus, \eqref{Eqn_Separate_N_1} follows from \eqref{Eqn_MR}.

Let $\mathbf{q}=(1/N)\mathbf{1}$. It can be computed that
\begin{equation*}
\mathcal{D}(\mathbf{q})=\{\mathbf{x}\in \mathcal{X}: x_{1}=\cdots=x_{N}\geq p(\mathbf{e}_{1})\}.
\end{equation*}
Consider changing $p(\mathbf{q})$ by $\varepsilon<0$. This price change will attract buyers in the neighborhood of $\mathcal{D}(\mathbf{q})$. Suppose that \eqref{Eqn_Separate_N_2} is false. By \Cref{Lem_Continuity}, when $\varepsilon$ is sufficiently small, $\MR_{-\varepsilon} (\mathbf{q})=-\mu \mathcal{D}(\mathbf{q};\overline{p}+\varepsilon \mathbb{I}_{\mathbf{q}})<0$, a contradiction to \eqref{Eqn_SOC_1}. Hence, our supposition is not true, and \eqref{Eqn_Separate_N_2} is proved.

\subsection{Proof of Corollary \ref{Cor_N}}

Under the i.i.d. assumption,
\begin{equation*}
\phi (\mathbf{x})=\left(\sum_{n\in \mathcal{N}}\frac{x_{n}g'(x_{n})}{g(x_{n})}+N+1\right)f(\mathbf{x}).
\end{equation*}

Part \ref{Cor_N_1}: Suppose that a pure bundling mechanism $p$ is optimal for some $N$. By \eqref{Eqn_Pure_N_1}, $\mathcal{D}(\mathbf{0})=\{\mathbf{x}\in \mathcal{X}:\mathbf{x}\cdot \mathbf{1}\leq p(\mathbf{1})\}$ is a simplex with vertices $\underline{\mathbf{x}}$ and $\{\underline{\mathbf{x}}+c\mathbf{e}_{n}\}_{n\in \mathcal{N}}$, where $c=p(\mathbf{1})-N\underline{x}\leq 1$. Thus, the volume of $\mathcal{D}(\mathbf{0})$ is bounded above by $1/N!$, and the $(N-1)$-dimensional volume of $\mathcal{D}(\mathbf{0})\cap \bd (\mathcal{X})$ is bounded above by $N/(N-1)!$. Let $\xi=\{xg'(x)/g(x):x\in [\underline{x},\overline{x}]\}$ and $\overline{g}=\{g(x):x\in [\underline{x},\overline{x}]\}$. By strict regularity, $\phi (\mathbf{x})\leq (N\xi +N+1)\overline{g}^{N}$. Since $\mu$ assigns only negative mass to points in $\mathcal{D}(\mathbf{0})$, we have
\begin{equation*}
-\mu (\mathcal{D}(\mathbf{0}))\leq \frac{(N\xi +N+1)\overline{g}^{N}}{N!}+\frac{(N\underline{x})\overline{g}^{N}}{(N-1)!}=\left(\frac{N\xi +N+1}{N^{2}}+\underline{x}\right)\frac{N\overline{g}^{N}}{(N-1)!},
\end{equation*}
where the right-hand side converges to zero as $N\to +\infty$. However, by \eqref{Eqn_Pure_N_2}, $\mu (\mathcal{D}(\mathbf{0}))=-1$, meaning that $N$ is bounded above. This proves part \ref{Cor_N_1}.

Part \ref{Cor_N_2}: For any $c\in [\underline{x},\overline{x}]$, the left-hand side of \eqref{Eqn_Separate_N_2} can be reformulated as
\begin{equation*}
\int^{\overline{x}}_{c}\phi (x,\dotsc,x)\dd x-\overline{x}f(\overline{\mathbf{x}})=N\int^{\overline{x}}_{c}g(x)^{N}\dd x-cg(c)^{N}\leq (N(\overline{x}-c)-c)g(c)^{N},
\end{equation*}
where the right-hand side is nonpositive if $N\leq \underline{x}$. This proves part \ref{Cor_N_2}.

\subsection{Proof of Theorem \ref{Thm_Pooling}}

Suppose that $\mathbf{n}\in \Int (\NC (\mathbf{q}))$ for some $\mathbf{n}\in \NV _{P}$ and $\mathbf{q}\in \mathcal{Q}$, and that $\mathcal{D}(\mathbf{q})$ has zero measure with respect to $f$. If there exists $\hat{\mathbf{x}}\in \mathcal{D}(\mathbf{q})$ such that $\hat{\mathbf{x}}\notin \mathcal{S}(\mathbf{n})$, then for sufficiently small $\tau>0$, we have $(\hat{\mathbf{x}}+\tau \mathbf{n})\in \Int\mathcal{X}$. By \Cref{Lem_NormalCone}, $\mathcal{D}(\mathbf{q})$ contains a neighborhood of $\hat{\mathbf{x}}+\tau \mathbf{n}$, a contradiction to the supposition that $\mathbf{q}$ is not pooling. Thus, $\mathcal{D}(\mathbf{q})\subseteq \mathcal{S}(\mathbf{n})$.

Consider the price schedule $\overline{p}+\varepsilon \mathbb{I}_{\mathbf{q}}$ for $\varepsilon<0$. By definition,
\begin{equation*}
\mathcal{D}_{\varepsilon}(\mathbf{q})=\{\mathbf{x}\in \mathcal{X}:\mathbf{x}\cdot\mathbf{q}-(\overline{p}(\mathbf{q})+\varepsilon)-u_{p}(\mathbf{x})\geq 0\}.
\end{equation*}
Since $\mathbf{x}\cdot\mathbf{q}-u_{p}(\mathbf{x})-\overline{p}(\mathbf{q})$ is continuous in $\mathbf{x}$, $\mathcal{D}_{\varepsilon}(\mathbf{q})$ must have positive measure with respect to $f$. By \Cref{Lem_NormalCone}, any $\hat{\mathbf{x}}\in \mathcal{D}_{\varepsilon}(\mathbf{q})$ can be represented as $\mathbf{x}-\tau \mathbf{n}$ for some $\mathbf{x}\in \mathcal{S}(\mathbf{n})$ and $\tau\geq 0$. This mapping is bijective, meaning that we can apply the change of variables formula:
\begin{equation}
\label{Eqn_Pooling_A1}
\int_{\mathcal{D}_{\varepsilon}(\mathbf{q})}\phi(\mathbf{x})\dd \mathbf{x}=\int_{\mathcal{D}_{\varepsilon}(\mathbf{q})\cap \mathcal{S}(\mathbf{n})}\left[\int^{\overline{\tau}(\mathbf{x})}_{0}\phi(\mathbf{x}-\tau \mathbf{n})|\det J(\mathbf{x},\tau)|\dd \tau\right]\dd \sigma (\mathbf{x}),
\end{equation}
where $\overline{\tau}(\mathbf{x})$ is the largest $\tau$ satisfying $(\mathbf{x}-\tau \mathbf{n})\in \mathcal{D}_{\varepsilon}(\mathbf{q})$, and $\det J(\mathbf{x},\tau)$ is the determinant of the Jacobian.

By the construction of $\NV _{P}$, we can choose $\delta>0$ sufficiently small such that $\mathcal{S}(\mathbf{n})+\delta B^{N}$ does not intersect $\underline{\bd}(\mathcal{X})$, and neither does $\mathcal{D}(\mathbf{q})+\delta B^{N}$. By \Cref{Lem_Continuity}, there exists $\overline{\varepsilon}>0$ such that $\mathcal{D}_{\varepsilon}(\mathbf{q})\subset \mathcal{D}(\mathbf{q})+\delta B^{N}$ for any $\varepsilon\in (-\overline{\varepsilon},0)$, which implies $\mathcal{D}_{\varepsilon}(\mathbf{q})\cap \underline{\bd}(\mathcal{X})=\emptyset$. In this case, we can compute from \Cref{Lem_MR} that
\begin{equation*}
\begin{aligned}
\MR_{-\varepsilon}(\mathbf{q}) & =\int_{\mathcal{D}_{\varepsilon}(\mathbf{q})\cap \mathcal{S}(\mathbf{n})}\left[\int^{\overline{\tau}(\mathbf{x})}_{0}\phi(\mathbf{x}-\tau \mathbf{n})|\det J(\mathbf{x},\tau)|\dd \tau-f(\mathbf{x})(\mathbf{x}\cdot\mathbf{n}_{\mathbf{x}})\right]\dd \sigma (\mathbf{x}) \\
& \quad -\int_{\mathcal{D}_{\varepsilon}(\mathbf{q})\cap (\overline{\bd}(\mathcal{X})\setminus\mathcal{S}(\mathbf{n}))}f(\mathbf{x})(\mathbf{x}\cdot\mathbf{n}_{\mathbf{x}})\dd \sigma (\mathbf{x}).
\end{aligned}
\end{equation*}
Note that both $\phi (\mathbf{x})$ and $|\det J(\mathbf{x},\tau)|$ are bounded from above, whereas $f(\mathbf{x})$ is bounded away from zero. When $\varepsilon \to 0$, $\mathcal{D}_{\varepsilon}(\mathbf{q})\to \mathcal{D}(\mathbf{q})$, meaning that $\overline{\tau}(\mathbf{x})\to 0$. By \Cref{Lem_Continuity}, we can choose $\varepsilon$ sufficiently close to zero such that for any $\mathbf{x}\in \mathcal{D}_{\varepsilon}(\mathbf{q})\cap \mathcal{S}(\mathbf{n})$,
\begin{equation*}
\int^{\overline{\tau}(\mathbf{x})}_{0}\phi(\mathbf{x}-\tau \mathbf{n})|\det J(\mathbf{x},\tau)|\dd \tau-f(\mathbf{x})(\mathbf{x}\cdot\mathbf{n}_{\mathbf{x}})<0,
\end{equation*}
implying that $\MR_{-\varepsilon}(\mathbf{q})<0$, a contradiction to \eqref{Eqn_SOC_1}. Hence, our supposition is not true, and $\mathbf{q}$ must be pooling.

\section{Results Omitted from Section \ref{Sec_2D}}

\subsection{Computing Marginal Revenue in Section \ref{Sec_2D_Finite}}
\label{App_MR}

When $(i,j)$ is active, characterizing the shape of $\mathcal{D}(i,j)$ is generally challenging. For illustrative purpose, we will assume that $\mathcal{D}(i,j)$ is a rectangular box, specifically given by $\mathcal{D}(i,j)=[a^{i},b^{i}]\times [a^{j},b^{j}]$. We further assume that $\mathcal{D}(i,j)\cap \bd (\mathcal{X})=\emptyset$, which implies $0<i,j<K$. The boundaries of $\mathcal{D}(i,j)$ are determined by the following indifferent buyers:
\begin{itemize}
\item[(a)] Buyers with $x_{1}=a^{i}$, $x_{2}\in [a^{j},b^{j}]$ are indifferent between $(i,j)$ and $(i-1,j)$.
\item[(b)] Buyers with $x_{1}=b^{i}$, $x_{2}\in [a^{j},b^{j}]$ are indifferent between $(i,j)$ and $(i+1,j)$.
\item[(c)] Buyers with $x_{2}=a^{j}$, $x_{1}\in [a^{i},b^{i}]$ are indifferent between $(i,j)$ and $(i,j-1)$.
\item[(d)] Buyers with $x_{2}=b^{j}$, $x_{1}\in [a^{i},b^{i}]$ are indifferent between $(i,j)$ and $(i,j+1)$.
\end{itemize}

Consider increasing $p(i,j)$ by a small amount $\varepsilon>0$ while ensuring that $(i,j)$ remains active. The direct effect of this price increase is an additional revenue $\varepsilon D(i,j)$. The indirect effect comes from altering the purchasing decisions of buyers on the boundary of $\mathcal{D}(i,j)$. For instance, buyers around boundary (a)---or, more precisely, buyers with $a^{i}\leq x_{1}<a^{i}+\varepsilon K$, $x_{2}\in [a^{j},b^{j}]$---will switch to $(i-1,j)$, leading to a change of revenue
\begin{equation*}
(p(i-1,j)-p(i,j))\int^{a^{i}+\varepsilon K}_{a^{i}}\int^{b^{j}}_{a^{j}}f(\mathbf{x})\dd x_{2}\dd x_{1} \approx -\varepsilon\int^{b^{j}}_{a^{j}}a^{i}f(a^{i},x_{2})\dd x_{2},
\end{equation*}
where the approximation comes from $a^{i}=-(p(i-1,j)-p(i,j))K$. 
Similarly, the revenue change caused by buyers around boundary (b) is
\begin{equation*}
(p(i+1,j)-p(i,j))\int^{b^{i}}_{b^{i}-\varepsilon K}\int^{b^{j}}_{a^{j}}f(\mathbf{x})\dd x_{2}\dd x_{1}\approx \varepsilon\int^{b^{j}}_{a^{j}}b^{i}f(b^{i},x_{2})\dd x_{2}.
\end{equation*}
Summarizing the two boundaries and applying integration by parts:
\begin{equation*}
\varepsilon\int^{b^{j}}_{a^{j}}b^{i}f(b^{i},x_{2})\dd x_{2}-\varepsilon\int^{b^{j}}_{a^{j}}a^{i}f(a^{i},x_{2})\dd x_{2}=\varepsilon\int_{\mathcal{D}(i,j)}\left(x_{1}\frac{\partial f(\mathbf{x})}{\partial x_{1}}+f(\mathbf{x})\right)\dd \mathbf{x}.
\end{equation*}
For buyers around boundaries (c) and (d), we have
\begin{equation*}
\varepsilon\int^{b^{i}}_{a^{i}}b^{j}f(x_{1},b^{j})\dd x_{1}-\varepsilon\int^{b^{i}}_{a^{i}}a^{j}f(x_{1},a^{j})\dd x_{1}=\varepsilon\int_{\mathcal{D}(i,j)}\left(x_{2}\frac{\partial f(\mathbf{x})}{\partial x_{2}}+f(\mathbf{x})\right)\dd \mathbf{x}.
\end{equation*}
Therefore, the total effect of this price change is
\begin{equation*}
\begin{aligned}
\varepsilon & \int_{\mathcal{D}(i,j)}f(\mathbf{x})\dd \mathbf{x}+\varepsilon\int_{\mathcal{D}(i,j)}\left(x_{1}\frac{\partial f(\mathbf{x})}{\partial x_{1}}+f(\mathbf{x})\right)\dd \mathbf{x}+\varepsilon\int_{\mathcal{D}(i,j)}\left(x_{2}\frac{\partial f(\mathbf{x})}{\partial x_{2}}+f(\mathbf{x})\right)\dd \mathbf{x} \\
& =\varepsilon\int_{\mathcal{D}(i,j)}(\mathbf{x}\cdot \nabla f(\mathbf{x})+3f(\mathbf{x}))\dd \mathbf{x},
\end{aligned}
\end{equation*}
which implies
\begin{equation*}
\MR (i,j)=\int_{\mathcal{D}(i,j)}\phi(\mathbf{x})\dd \mathbf{x}.
\end{equation*}

In fact, the assumption that $\mathcal{D}(i,j)$ is a box is without loss of generality, as we can approximate any $\mathcal{D}(i,j)$ by a sequence of boxes. The assumption $\mathcal{D}(i,j)\cap \bd (\mathcal{X})=\emptyset$ is the mirror image of the assumption $0<a^{i}<b^{i}<1$ in \Cref{Sec_1D}. It ensures that buyers will deviate in every direction normal to the boundary of $\mathcal{D}(i,j)$ after a price change. If this assumption fails, then buyers with $\mathbf{x}\in \mathcal{D}(i,j)\cap \overline{\bd}(\mathcal{X})$ will not alter their purchasing decisions after the price change, and we obtain the general formulation \eqref{Eqn_MR_2D}.

\subsection{A Variational Approach to Proposition \ref{Prop_2D}}
\label{Sec_2D_Variational}

This section provides an alternative proof of \Cref{Prop_2D} using a variational approach. The main idea is to apply \eqref{Eqn_2D_MM} and reformulate the seller's problem as finding the optimal $\overline{u}$ subject to feasibility constraints.

We start with the following preliminary result, first established by \citet{hart2010revenue}: Let $\overline{U}$ be the set of nondecreasing, convex, and 1-Lipschitz with respect to the $\ell^{1}$-norm functions from $[0,1]$ to $[0,2]$. Then
\begin{equation*}
\max_{p}\TR (p)=\max_{\overline{u}\in \overline{U}}2\int^{1}_{0}L(\overline{u}(x_{1}),x_{1})\dd x_{1},
\end{equation*}
where $L$ is the total revenue from type-$\mathbf{x}$ buyers satisfying $\max (1-\overline{u}(x_{1}),x_{1})\leq x_{2}\leq 1$:
\begin{equation*}
L(\overline{u}(x_{1}),x_{1})=\overline{u}(x_{1})f(x_{1},1)-\int^{1}_{\max (1-\overline{u}(x_{1}),x_{1})}(\overline{u}(x_{1})-(1-x_{2}))\phi(x_{1},x_{2})\dd x_{2}.
\end{equation*}
It can be verified that
\begin{equation*}
\frac{\partial L}{\partial \overline{u}}=f(x_{1},1)-\int^{1}_{\max (1-\overline{u}(x_{1}),x_{1})}\phi(x_{1},x_{2})\dd x_{2}=-\Phi (x_{1}).
\end{equation*}
Finally, denote by $\mathcal{L}_{\overline{u}}$ the ``twice integration'' of $\Phi$:
\begin{equation*}
\mathcal{L}_{\overline{u}}(x_{1})=-\int^{1}_{x_{1}}\int^{1}_{y}\Phi (z)\dd z\dd y.
\end{equation*}

Since $\overline{u}$ is convex, $\overline{u}'$ exists almost everywhere on $[0,1]$. We let $\overline{u}'(0-)=0$, $\overline{u}'(1+)=1$, and extend the definition of $\overline{u}'$ to the whole $[0,1]$ by right-continuity. Then $\overline{u}'$ is a c.d.f., and its \emph{support}, denoted by $\supp \overline{u}'$, is the set of all $x$ satisfying $\overline{u}'(x-\delta)<\overline{u}'(x+\delta)$ for any $\delta>0$.

\Cref{Prop_2D_Var} provides a simple characterization of the support of $\overline{u}'$.

\begin{proposition}
\label{Prop_2D_Var}
Suppose that the environment is SRS. Then for any optimal $\overline{u}$, $\mathcal{L}_{\overline{u}}'(0)=0$, and
\begin{equation}
\label{Eqn_NC}
\supp \overline{u}' \subseteq \arg\max_{x_{1}\in [0,1]}\mathcal{L}_{\overline{u}}(x_{1}).
\end{equation}
\end{proposition}

\begin{proof}
If $\overline{u}$ is optimal and $\tilde{u}\in \overline{U}$, then $(1-\delta)\overline{u}+\delta \tilde{u}\in \overline{U}$ for any $\delta\in (0,1)$. The Gateaux differential of $\int^{1}_{0}L(\overline{u}(x),x)\dd x$ in the direction $\tilde{u}-\overline{u}$ must be nonpositive. That is,
\begin{equation}
\label{Eqn_Gateaux}
\frac{\dd }{\dd \delta}\int^{1}_{0}L((1-\delta)\overline{u}(x)+\delta \tilde{u}(x),x)\dd x\bigg\vert_{\delta=0}=-\int^{1}_{0}\Phi (x)(\tilde{u}(x)-\overline{u}(x))\dd x\leq 0.
\end{equation}

We first prove \eqref{Eqn_NC}. Let $\tilde{u}$ be an absolutely continuous function such that $\tilde{u}(0)=\overline{u}(0)$, $\tilde{u}'(x)=\mathbb{I}_{[\hat{x},1]}(x)$ for some $\hat{x}\in [0,1]$. It can be verified that $\tilde{u}\in \overline{U}$.
Applying integration by parts twice,
\begin{equation*}
\begin{aligned}
-\int^{1}_{0}\Phi (x)(\tilde{u}(x)-\overline{u}(x))\dd x 
& =-\int^{1}_{0}\mathcal{L}_{\overline{u}}'(x)(\tilde{u}'(x)-\overline{u}'(x))\dd x \\
& =\int^{1}_{0}\mathcal{L}_{\overline{u}}(x)\dd {(\tilde{u}'(x)-\overline{u}'(x))},
\end{aligned}
\end{equation*}
where the first equality comes from $\mathcal{L}_{\overline{u}}'(1)=0$ and $\tilde{u}(0)=\overline{u}(0)$, and the second equality comes from $\mathcal{L}_{\overline{u}}(1)=0$ and $\tilde{u}'(0-)=\overline{u}'(0-)=0$. Here, $\dd \overline{u}'(x)$ represents the Riemann-Stieltjes integral, meaning that the measure associated with $\overline{u}'$ may have mass points. By \eqref{Eqn_Gateaux}, for any $\hat{x}\in [0,1]$,
\begin{equation*}
\int^{1}_{0}\mathcal{L}_{\overline{u}}(x;\overline{u})\dd \tilde{u}'(x)=\mathcal{L}_{\overline{u}}(\hat{x};\overline{u})\leq\int^{1}_{0}\mathcal{L}_{\overline{u}}(x;\overline{u})\dd \overline{u}'(x),
\end{equation*}
which is equivalent to \eqref{Eqn_NC}.

Next, we show $\mathcal{L}_{\overline{u}}'(0)=0$. Let $\varepsilon$ be a sufficiently small and positive real number. If $\overline{u}(0)\in (0,1)$, then setting $\tilde{u}(x)=\overline{u}(x)\pm\varepsilon$ in \eqref{Eqn_Gateaux} yields $\mathcal{L}_{\overline{u}}'(0)=0$.

If $\overline{u}(0)=0$, then setting $\tilde{u}(x)=\overline{u}(x)+\varepsilon$ in \eqref{Eqn_Gateaux} yields $\mathcal{L}_{\overline{u}}'(0)\geq 0$. By definition, $b^{0}\in \supp \overline{u}'$. If $b^{0}=0$, then there must be $\mathcal{L}_{\overline{u}}'(0)=0$. If $b^{0}>0$, then $\overline{u}(0)=0$ and $\mathcal{L}_{\overline{u}}''(x)=f(x,1)>0$ for almost all $x\in [0,b^{0}]$, which means $\mathcal{L}_{\overline{u}}'(b^{0})>0$, a contradiction to $b^{0}\in \supp \overline{u}'$.

If $\overline{u}(0)=1$, then $1-\overline{u}(x)\leq x$ for all $x\in [0,1]$, and
\begin{equation*}
-\mathcal{L}_{\overline{u}}'(0)=\int^{1}_{0}\left[f(x_{1},1)-\int^{1}_{x_{1}}\phi(x_{1},x_{2})\dd x_{2}\right]\dd x_{1}=\frac{1}{2}\mu(\mathcal{X})=-\frac{1}{2}.
\end{equation*}
However, setting $\tilde{u}(x)=\overline{u}(x)-\varepsilon$ in \eqref{Eqn_Gateaux} yields $\mathcal{L}_{\overline{u}}'(0)\leq 0$, a contradiction.

Summarizing the three cases gives us $\mathcal{L}_{\overline{u}}'(0)=0$ and thus completes the proof.
\end{proof}

\Cref{Prop_2D_Var} is closely related to \Cref{Prop_2D}. Recall that $[a^{q},b^{q}]=\{x\in [0,1]: \overline{u}(x-)\leq q\leq \overline{u}(x+)\}$. If $q>0$, then $a^{q}\in \supp \overline{u}'$, which means $\mathcal{L}_{\overline{u}}''(a^{q})=-\Phi (a^{q})\leq 0$ and $\mathcal{L}_{\overline{u}}'(a^{q})=0$. If $q<1$, then $b^{q}\in \supp \overline{u}'$, which means $\mathcal{L}_{\overline{u}}''(b^{q})=-\Phi (b^{q})\leq 0$ and $\mathcal{L}_{\overline{u}}'(b^{q})=0$. Moreover, since $\mathcal{L}_{\overline{u}}'(0)=\mathcal{L}_{\overline{u}}'(1)=0$, $\mathcal{L}_{\overline{u}}'(a^{q})=\mathcal{L}_{\overline{u}}'(b^{q})=0$ can be extended to all $q$, implying that $\mathcal{L}_{\overline{u}}'(b^{q})-\mathcal{L}_{\overline{u}}'(a^{q})=\int^{b^{q}}_{a^{q}}\Phi (x_{1})\dd x_{1}=0$. These results exactly correspond to parts \ref{Prop_2D_2} and \ref{Prop_2D_3} of \Cref{Prop_2D}.

\subsection{Properties of $\zeta$ in all examples}

When $h$ is twice differentiable and $h'(x)\neq 0$, we can compute $\zeta'$ and $\zeta''$ from \eqref{Eqn_Zeta_iid}:
\begin{align}
\label{Eqn_Zeta'}
\zeta'(x) & =\frac{h'(x)\zeta(x)}{[h(x)+2][h(\zeta (x))+h(x)+3]}, \\
\label{Eqn_Zeta''}
\zeta''(x) & =\frac{h''(x)\zeta'(x)}{h'(x)}-\left[\frac{h(\zeta (x))+2h(x)+4}{\zeta (x)}+\frac{h'(\zeta (x))}{h(\zeta (x))+h(x)+3}\right]\zeta'(x)^{2}.
\end{align}

\subsubsection{Power-law distribution}

When $\eta\geq 1$, $h$ is nondecreasing, so $\zeta$ is nondecreasing. Moreover, it is straightforward to compute that $C=\eta /[(1+\theta)^{\eta}-\theta^{\eta}]$ and $G(x)=[(x+\theta)^{\eta}-\theta^{\eta}]/[(1+\theta)^{\eta}-\theta^{\eta}]$. If $\zeta (x)=x$, then $x$ solves
\begin{equation*}
\frac{xg(x)}{1-G(x)}=h(x)+2,
\end{equation*}
which can be simplified as
\begin{equation*}
\frac{\eta}{(1+\theta)^{\eta}-(x+\theta)^{\eta}}=\frac{\eta-1}{x+\theta}+\frac{2}{x}.
\end{equation*}
The left-hand side is strictly increasing in $x$ and ranges from $C$ to $+\infty$, while the right-hand side is strictly decreasing in $x$ and ranges from $+\infty$ to $(\eta-1)/\theta+2$. Therefore, $\zeta (x)=x$ has a unique solution.

\subsubsection{Truncated Pareto distribution}

Insert $h$ into \eqref{Eqn_Zeta''} and apply \eqref{Eqn_Zeta'}:
\begin{equation*}
\begin{aligned}
\zeta''(x) & =-\frac{2\zeta'(x)}{x+1}-\left[\frac{h(\zeta (x))+2h(x)+4}{\zeta (x)}+\frac{h'(\zeta (x))}{h(\zeta (x))+h(x)+3}\right]\zeta'(x)^{2} \\
& =-\left\{\frac{2}{x+1}-\frac{\eta [h(\zeta (x))+2h(x)+4]}{(x+1)^{2}[h(x)+2][h(\zeta (x))+h(x)+3]}\right\}\zeta'(x)-\frac{h'(\zeta (x))\zeta'(x)^{2}}{h(\zeta (x))+h(x)+3}.
\end{aligned}
\end{equation*}
It can be verified that
\begin{equation*}
\begin{aligned}
\frac{h(\zeta (x))+2h(x)+4}{h(\zeta (x))+h(x)+3} & <2, \\
0<\frac{\eta}{(x+1)[h(x)+2]} & <1.
\end{aligned}
\end{equation*}
Thus,
\begin{equation*}
\zeta''(x)>-\left\{\frac{2}{x+1}-\frac{2\eta }{(x+1)^{2}[h(x)+2]}\right\}\zeta'(x)>0.
\end{equation*}

\subsubsection{Truncated normal distribution}

Insert $h$ into \eqref{Eqn_Zeta''}:
\begin{equation*}
\zeta''(x)=-\frac{2\zeta'(x)}{h'(x)}-\left[\frac{h(\zeta (x))+2h(x)+4}{\zeta (x)}+\frac{(\theta-2\zeta (x))}{h(\zeta (x))+h(x)+3}\right]\zeta'(x)^{2}.
\end{equation*}
We then compute a lower bound for $h(\zeta (x))+h(x)$. By integration by parts,
\begin{equation*}
\begin{aligned}
\int^{1}_{x}[1-G(\hat{x})]\dd (\hat{x}-\theta) & =(\theta-x)(1-G(x))+\int^{1}_{x}(\hat{x}-\theta)g(\hat{x})\dd\hat{x} \\
& =(\theta-x)(1-G(x))+g(x)-g(1).
\end{aligned}
\end{equation*}
Since the left-hand side is nonnegative,
\begin{equation*}
\theta-x+\frac{g(x)}{1-G(x)}\geq \frac{g(1)}{1-G(x)}\geq g(1)=e^{-(1-\theta)^{2}/2}\geq 1-\frac{(1-\theta)^{2}}{2}\geq \frac{1}{2},
\end{equation*}
where the last inequality comes from $e^{\tau}\geq 1+\tau$. Therefore,
\begin{equation*}
h(\zeta (x))+h(x)+2=\zeta (x)(\theta-\zeta (x))+\frac{\zeta (x)g(\zeta (x))}{1-G(\zeta (x))}\geq \frac{\zeta (x)}{2}.
\end{equation*}
Since $h(x)\geq -1$, $h(\zeta (x))+2h(x)+4\geq h(\zeta (x))+h(x)+3\geq 1+\zeta (x)/2$. Finally,
\begin{equation*}
[h(\zeta (x))+2h(x)+4][h(\zeta (x))+h(x)+3]-\zeta (x)(\theta-2\zeta (x))\geq \left[1+\frac{\zeta (x)}{2}\right]^{2}-2\zeta (x)^{2}>0,
\end{equation*}
which means $\zeta''(x)<0$.

\subsubsection{Truncated Gamma distribution}

Insert $h$ into \eqref{Eqn_Zeta''}:
\begin{equation*}
\zeta''(x)=-\left[\frac{h(\zeta (x))+2h(x)+4}{\zeta (x)}+\frac{-\lambda}{h(\zeta (x))+h(x)+3}\right]\zeta'(x)^{2}.
\end{equation*}
By direct computation,
\begin{equation*}
[h(\zeta (x))+2h(x)+4][h(\zeta (x))+h(x)+3]-\lambda \zeta (x)\geq 1-\lambda \zeta (x)>0,
\end{equation*}
which implies $\zeta''(x)<0$.

\subsection{An Upper Bound for the Optimal Menu Size}
\label{Sec_MenuSize}

In the setting of \Cref{Sec_2D}, even if $\zeta$ does not have a ``good'' global property, we can obtain an upper bound for the number of pooling bundles in any optimal mechanism. On top of SRS, the only assumption we need is that $\zeta$ crosses the 45-degree line exactly once.

Let $x_{\zeta}$ be the unique solution of $\zeta (x)=x$. The subset of $(0,x_{\zeta})$ where $\zeta$ is convex plays a key role in our characterization:
\begin{equation*}
X_{\cvx}=\{x\in (0,x_{\zeta}): \exists \delta>0\ \text{s.t.}\ \zeta \ \text{is convex on}\ (x-\delta,x+\delta)\}.
\end{equation*}
Since any open subset of $\mathbb{R}$ can be uniquely decomposed as the union of countably many nonempty disjoint open intervals, we denote the interior of $X_{\cvx}$ as $\Int (X_{\cvx})=\bigcup_{i\in I}(\alpha_{i},\beta_{i})$, where $I$ is a countable index set.

\begin{corollary}
\label{Cor_MenuSize}
Suppose that $\zeta$ crosses the 45-degree line exactly once. Then in any symmetric optimal mechanism, $|\{q\in (0,1):(q,1)\text{ is pooling}\}|\leq |I|$.
\end{corollary}

\begin{proof}
Throughout the proof, we fix an optimal $\overline{u}$ and let $x_{\overline{u}}$ be the unique intersection of $1-\overline{u}$ and the 45-degree line. We also denote by $\zeta |_{[\alpha,\beta]}$ the restriction of $\zeta$ to $[\alpha,\beta]$.

By \Cref{Prop_2D}, the grand bundle $\mathbf{1}$ satisfies $\max (1-\overline{u}(a^{1}),a^{1})\leq \zeta (a^{1})$, so $a^{1}<x_{\zeta}$. Suppose that $(q,1)$ is pooling with $q\in (0,1)$ and $a^{q}<b^{q}\leq a^{1}<x_{\zeta}$. Based on the relationship among $a^{q}$, $b^{q}$, and $x_{\overline{u}}$, three cases will be discussed in order.

Case 1: $b^{q}\leq x_{\overline{u}}$ and $1-\overline{u}(x)=\zeta (x)$ for all $x\in (a^{q},b^{q})$. Then $(a^{q},b^{q})\subseteq X_{\cvx}$. Assume that $(a^{q},b^{q})\subseteq (\alpha_{i},\beta_{i})$ for some $i\in I$. Then the convex curve $\zeta |_{[\alpha_{i},\beta_{i}]}$ lies above the concave curve $1-\overline{u}$, and their only intersection is on $[a^{q},b^{q}]$.

Case 2: $b^{q}\leq x_{\overline{u}}$ and $1-\overline{u}(x)>\zeta (x)$ for some $x\in (a^{q},b^{q})$. Then $1-\overline{u}-\zeta$ has a maximum point in $(a^{q},b^{q})$, which we denote by $\hat{x}$. As a result, $\zeta'(\hat{x}-)\leq -q\leq \zeta'(\hat{x}+)$, and $\zeta$ is convex in the neighborhood of $\hat{x}$. Assume that $\hat{x}\in (\alpha_{i},\beta_{i})$ for some $i\in I$. One of the following must hold:

(a) $(\alpha_{i},\beta_{i})\subseteq (a^{q},b^{q})$.

(b) $a^{q}\in (\alpha_{i},\beta_{i})$ and $b^{q}\notin (\alpha_{i},\beta_{i})$. Then $\zeta'(a^{q}-)<-q$. The intersection of $\zeta |_{[\alpha_{i},\beta_{i}]}$ and $1-\overline{u}$ is a subset of $[a^{q},\beta_{i}]$. A similar discussion applies to the situation where $a^{q}\notin (\alpha_{i},\beta_{i})$ and $b^{q}\in (\alpha_{i},\beta_{i})$.

(c) $(a^{q},b^{q})\subset (\alpha_{i},\beta_{i})$. Then $\zeta'(a^{q}-)<-q$ and $\zeta'(b^{q}+)>-q$. The intersection of $\zeta |_{[\alpha_{i},\beta_{i}]}$ and $1-\overline{u}$ is a subset of $[a^{q},b^{q}]$.

Case 3: $x_{\overline{u}}\in (a^{q},b^{q})$. Since $b^{q}<x_{\zeta}$, there cannot be $\max (1-\overline{u}(x),x)=\zeta (x)$ for all $x\in (a^{q},b^{q})$. We must have $1-\overline{u}(x)>\zeta (x)$ for some $x\in (a^{q},x_{\overline{u}})$. The rest of the analysis is similar to case 2.

Case 4: $a^{q}\geq x_{\overline{u}}$. Then $a^{q}\leq \zeta (a^{q})$ and $b^{q}\leq \zeta (b^{q})$, meaning that $\zeta$ crosses the 45-degree line at least twice on $[a^{q},b^{q}]$, a contradiction.

Summarizing cases 1-3, when $a^{q}<x_{\overline{u}}$, there exists $i\in I$ such that either $(\alpha_{i},\beta_{i})\subseteq (a^{q},b^{q})$, or $\zeta |_{[\alpha_{i},\beta_{i}]}$ and $1-\overline{u}$ intersects on a subset of $[a^{q},b^{q}]$. In total, there can be at most $|I|$ pooling bundles from the three cases.
\end{proof}

Note that $\mathbf{e}_{1}$, $\mathbf{e}_{2}$, and $\mathbf{1}$ are excluded from \Cref{Cor_MenuSize}. Thus, when $|I|$ is finite, the number of pooling bundles in any optimal mechanism is capped by $2|I|+3$.

\section{Results Omitted from Section \ref{Sec_SubsComp}}

\subsection{Characterizing Optimal Mechanisms}
\label{Sec_SubsComp_OptMech}

This section presents three corollaries that are direct consequences of \Cref{Prop_SubsComp}. Given their similarity to Corollaries \ref{Cor_Inc}--\ref{Cor_CcvDec}, we only provide concise outlines of their proofs, emphasizing their distinctions relative to the arguments used for Corollaries \ref{Cor_Inc}--\ref{Cor_CcvDec}.

\begin{corollary}
\label{Cor_k=1/2}
Suppose that $k=1/2$ and there exists $x^{*}\in [0,1]$ such that $\zeta_{k}(x)=0$ for all $x\in [0,x^{*})$. Then the following hold for any optimal $\overline{u}$:
\begin{enumerate}
\item If $\zeta_{k}$ is nondecreasing on $[x^{*},1]$, then $\overline{u}'(x)=0$ for $x\in [0,1]$. \label{Cor_k=1/2_1}
\item If $\zeta_{k}$ is convex on $[x^{*},1]$, then there exist $x^{*}<b^{0}\leq 1$ and $0<q\leq k$ such that:
\begin{enumerate}
    \item $\overline{u}'(x)=0$ for $x\in [0,b^{0})$,
    \item $\overline{u}'(x)=q$ for $x\in [b^{0},1]$.
\end{enumerate}
\item If $\zeta_{k}$ is concave on $[x^{*},1]$, then there exist $x^{*}<b^{0}\leq a^{k}\leq 1$ such that:
\begin{enumerate}
    \item $\overline{u}'(x)=0$ for $x\in [0,b^{0})$,
    \item $\overline{u}(x)=1-\zeta_{k}(x)$ for $x\in [b^{0},a^{k})$,
    \item $\overline{u}'(x)=k$ for $x\in [a^{k},1]$.
\end{enumerate}
\end{enumerate}
\end{corollary}

\begin{proof}[Proof Sketch]
There are two key differences between the cases $k=1/2$ and $k=1$. First, $\mathbf{k}$ is not necessarily pooling when $k=1/2$. Second, according to \Cref{Thm_Pooling}, both $\mathbf{e}_{1}$ and $\mathbf{e}_{2}$ must be pooling when $k=1/2$.  Consequently, when $\zeta_{k}$ is nondecreasing, optimal mechanisms are separate selling. When $\zeta_{k}$ is convex (or concave), we allow $b^{0}=1$ (or $a^{k}=1$), but instead require $b^{0}>x^{*}$.
\end{proof}

\begin{corollary}
\label{Cor_1/2<k<1}
Suppose that $1/2<k<1$, that $\zeta_{k}$ crosses the line $x_{2}=(kx_{1}+k-1)/(2k-1)$ exactly once, and there exists $x^{*}\in [0,1]$ such that $\zeta_{k}(x)=0$ for all $x\in [0,x^{*})$. Then the following hold for any optimal $\overline{u}$:
\begin{enumerate}
\item If $\zeta_{k}$ is nondecreasing on $[x^{*},1]$, then there exists $x^{*}<a^{k}<1$ such that: \label{Cor_1/2<k<1_1}
\begin{enumerate}
    \item $\overline{u}'(x)=0$ for $x\in [0,a^{k})$,
    \item $\overline{u}'(x)=k$ for $x\in [a^{k},1]$.
\end{enumerate}
\item If $\zeta_{k}$ is convex on $[x^{*},1]$, then there exist $x^{*}<b^{0}\leq a^{k}<1$ and $0<q<k$ such that:
\begin{enumerate}
    \item $\overline{u}'(x)=0$ for $x\in [0,b^{0})$,
    \item $\overline{u}'(x)=q$ for $x\in [b^{0},a^{k})$.
    \item $\overline{u}'(x)=k$ for $x\in [a^{k},1]$.
\end{enumerate}
\item If $\zeta_{k}$ is concave on $[x^{*},1]$, then there exist $x^{*}<b^{0}\leq a^{k}<1$ such that:
\begin{enumerate}
    \item $\overline{u}'(x)=0$ for $x\in [0,b^{0})$,
    \item $\overline{u}(x)=1-\zeta_{k}(x)$ for $x\in [b^{0},a^{k})$,
    \item $\overline{u}'(x)=k$ for $x\in [a^{k},1]$.
\end{enumerate}
\end{enumerate}
\end{corollary}

\begin{proof}[Proof Sketch]
This case is an intermediate scenario between the cases $k=1/2$ and $k=1$. According to \Cref{Thm_Pooling}, $\mathbf{e}_{1}$, $\mathbf{e}_{2}$, and $\mathbf{k}$ are all pooling in optimal mechanisms. Consequently, when $\zeta_{k}$ is nondecreasing, optimal mechanisms are deterministic. When $\zeta_{k}$ is convex, optimal mechanisms may have two additional pooling bundles relative to \Cref{Cor_Cvx}. When $\zeta_{k}$ is concave, optimal mechanisms exhibit features analogous to those characterized in \Cref{Cor_Ccv}.
\end{proof}

\begin{corollary}
\label{Cor_k>1}
Suppose that $k>1$, that $\zeta_{k}$ crosses the line $x_{2}=(kx_{1}+k-1)/(2k-1)$ exactly once, and and there exists $x^{*}\in [0,1]$ such that $\zeta_{k}(x)=0$ for all $x\in (x^{*},1]$. Then the following hold for any optimal $\overline{u}$:
\begin{enumerate}
\item If $\zeta_{k}$ is nonincreasing on $[0,x^{*}]$, then both $\mathbf{e}_{1}$ and $\mathbf{e}_{2}$ are inactive. \label{Cor_k>1_1}
\item If $\zeta_{k}$ is nondecreasing on $[0,x^{*}]$, then there exist $0\leq a^{k}<1$ and $0\leq q<k$ such that: \label{Cor_k>1_2}
\begin{enumerate}
    \item $\overline{u}'(x)=q$ for $x\in [0,a^{k})$,
    \item $\overline{u}'(x)=k$ for $x\in [a^{k},1]$.
\end{enumerate}
\item If $\zeta_{k}$ is convex on $[0,x^{*}]$, then there exist $0\leq a^{k}<1$ and $0\leq q<k$ such that: \label{Cor_k>1_3}
\begin{enumerate}
    \item $\overline{u}'(x)=q$ for $x\in [0,a^{k})$,
    \item $\overline{u}'(x)=k$ for $x\in [a^{k},1]$.
\end{enumerate}
\item If $\zeta_{k}$ is concave on $[0,x^{*}]$, then there exist $0\leq b^{q}\leq a^{k}<1$ and $0\leq q<k$ such that:\label{Cor_k>1_4}
\begin{enumerate}
    \item $\overline{u}'(x)=q$ for $x\in [0,b^{q})$,
    \item $\overline{u}(x)=1-\zeta_{k}(x)$ for $x\in [b^{q},a^{k})$,
    \item $\overline{u}'(x)=k$ for $x\in [a^{k},1]$.
\end{enumerate}
\end{enumerate}
\end{corollary}

\begin{proof}[Proof Sketch]
Part \ref{Cor_k>1_1} of the corollary is new and we will prove it by contradiction. Suppose that $\zeta_{k}$ satisfies all the features listed in the corollary, and $\mathbf{e}_{2}$ is active. Then $a^{0}=0$, and $\mathcal{D}_{k}(\mathbf{e}_{2})=\{\hat{\mathbf{x}}\in \mathcal{X}:\hat{\mathbf{x}}=(x_{1},1)-(1-x_{2})\mathbf{n}_{k}\text{, }x_{1}<0\text{, and }\max (1-\overline{u}(0),z_{k}(0))\leq x_{2}\leq 1\}$, meaning that $\mathbf{e}_{2}$ is pooling. If $b^{0}=0$, $\mathcal{D}_{k}(\mathbf{e}_{2})$ has no intersection with the top boundary of $\mathcal{X}$, which implies $\MR (\mathbf{e}_{2})>0$. If $b^{0}>0$, then by \Cref{Prop_SubsComp}, $\max (1-\overline{u}(b^{0}),z_{k}(b^{0}))\leq \zeta_{k}(b^{0})$. Since $\zeta_{k}$ is nonincreasing, the single-dipped curve $\max (1-\overline{u}(x),z_{k}(x))$ must lie below $\zeta_{k}$ for all $x\in [0,b^{0})$, which also implies $\MR (\mathbf{e}_{2})>0$. Both cases lead to a contradiction to \Cref{Prop_SubsComp}.

Parts \ref{Cor_k>1_2}--\ref{Cor_k>1_4} of the corollary are similar to Corollaries \ref{Cor_k=1/2} and \ref{Cor_1/2<k<1}. According to \Cref{Thm_Pooling}, $\mathbf{e}_{1}$ and $\mathbf{e}_{2}$ may not be pooling, while $\mathbf{k}$ must be pooling in optimal mechanisms. Consequently, we allow $q=0$ but require $a^{k}<1$ in parts \ref{Cor_k>1_2}--\ref{Cor_k>1_4}.
\end{proof}

\subsection{The Suboptimality of Pure Bundling in Example \ref{Exp_Uniform_k}}

Consider the $k>1$ case. Let $\hat{p}$ be a revenue-maximizing pure bundling mechanism. It can be computed that $\hat{p}(\mathbf{1})=\sqrt{2/3}k$. Let $\hat{u}$ be the indirect utility function induced by $\hat{p}$. Then $\hat{u}(x,1)=k(x+1-\sqrt{2/3})$. By \Cref{Prop_SubsComp}, $\hat{p}$ is optimal only if $\max (1-\hat{u}(0,1),z_{k}(0))\geq 2/3$, which implies $k\geq 1+\sqrt{2/3}$.

\section{Results Omitted from Section \ref{Sec_General}}

\subsection{A Mechanism Design Formulation for the General Model}

In this section, we reformulate the seller's problem in \Cref{Sec_General} as finding the optimal direct mechanism. In particular, a direct mechanism is denoted by $(\mathbf{q},t)$, where $\mathbf{q} :\mathcal{X}\mapsto \mathcal{Q}$ maps a buyer type to an allocation, and $t :\mathcal{X}\mapsto \mathbb{R}$ maps a buyer type to a monetary transfer. A mechanism is \emph{feasible} if it satisfies the incentive compatibility and the individual rationality constraints
\begin{align}
\label{IC}
\mathbf{x}\cdot\mathbf{q}(\mathbf{x})-t(\mathbf{x}) & \geq \mathbf{x}\cdot\mathbf{q}(\hat{\mathbf{x}})-t(\hat{\mathbf{x}}) & \forall\, & \mathbf{x},\hat{\mathbf{x}}\in \mathcal{X}, \tag{IC} \\
\label{IR}
\mathbf{x}\cdot\mathbf{q}(\mathbf{x})-t(\mathbf{x}) & \geq 0 & \forall\, & \mathbf{x}\in \mathcal{X}.
\tag{IR}
\end{align}
Let $u(\mathbf{x})=\mathbf{x}\cdot\mathbf{q}(\mathbf{x})-t(\mathbf{x})$ be the indirect utility function. By standard arguments, $(\mathbf{q},t)$ is feasible if and only if $u$ is nonnegative, convex, and satisfies $\nabla u(\mathbf{x})=\mathbf{q}(\mathbf{x})\in \mathcal{Q}$ whenever $u$ is differentiable at $\mathbf{x}$. The price schedule induced by $u$ is the convex conjugate of $u$, denoted by $p_{u}$:
\begin{equation*}
p_{u}=\sup_{\mathbf{x}\in \mathcal{X}}\{\mathbf{x}\cdot\mathbf{q}-u(\mathbf{x})\}.
\end{equation*}
Let $\mathcal{U}$ be the set of feasible $u$. Then the seller's revenue maximization problem is
\begin{equation}
\label{Eqn_Problem_u}
\max_{u\in U}\int_{\mathcal{X}}u\dd \mu.
\tag{Problem $u$}
\end{equation}

\Cref{Prop_Equiv} establishes the equivalence between \ref{Eqn_Problem_p} and \ref{Eqn_Problem_u}.

\begin{proposition}
\label{Prop_Equiv}
$p$ solves \ref{Eqn_Problem_p} if and only if $u_{p}$ solves \ref{Eqn_Problem_u}. Conversely, $u$ solves \ref{Eqn_Problem_u} if and only if $p_{u}$ solves \ref{Eqn_Problem_p}.
\end{proposition}

\subsection{A Sufficient Condition for Exclusion}
\label{Sec_Exclusion}

The \emph{exclusion set} consists of buyer types that purchase the zero bundle. In our notation, it is simply $\mathcal{D}(\mathbf{0})$. Early studies on multiproduct monopoly, such as \citet{armstrong1996multiproduct} and \citet{rochet1998ironing}, argue that it is always optimal to exclude a positive mass of buyers, meaning that $\mathcal{D}(\mathbf{0})$ should have positive measure with respect to $f$. However, \citet{rochet2003economics} and \citet{barelli2014optimality} later demonstrate that this result relies on the strict convexity of the type space. With \Cref{Thm_MR}, we now gain a clearer perspective on this issue.

\begin{corollary}
\label{Cor_Zero}
Suppose that $\mu (\mathcal{S}(-\mathbf{q}))>-1$ for all $\mathbf{q}\in \mathcal{Q}\setminus \{\mathbf{0}\}$. Then in any optimal mechanism, $\mathcal{D}(\mathbf{0})$ has positive measure with respect to $f$.
\end{corollary}

\begin{proof}
Suppose that $\mathcal{D}(\mathbf{0})$ has zero measure with respect to $f$. It can be verified that $-\mathbf{e}_{n}\in \NC (\mathbf{0})$ for all $n\in \mathcal{N}$, where $\{\mathbf{e}_{n}\}_{n\in \mathcal{N}}$ is the standard basis of $\mathbb{R}^{N}$. That is, $\NC (\mathbf{q})$ is of dimension $N$. By \Cref{Lem_NormalCone}, $\mathcal{D}(\mathbf{0})\subseteq \mathcal{S}(\mathbf{n})$ for some $\mathbf{n}\in \Int (\NC (\mathbf{0}))$. Moreover, if $\mathbf{x}\in \mathcal{D}(\mathbf{0})$, then $\Int (\mathbf{x}+\NC (\mathbf{0}))$ and $\Int (\mathcal{X})$ is separated by $\mathcal{S}(\mathbf{n})$, implying that $-\mathbf{n}\cdot \mathbf{n}_{\mathbf{0}}\leq 0$ for all $\mathbf{n}_{\mathbf{0}}\in \NC (\mathbf{0})$. In other words, $-\mathbf{n}$ belongs to the polar cone of $\NC (\mathbf{0})$. Note that $\NC (\mathbf{0})$ is also the polar cone of $\mathcal{Q}$. By Theorem 14.1 of \citet{rockafellar1970}, $-\mathbf{n}$ belongs to the smallest convex cone that contains $\mathcal{Q}$. Thus, there exists $\mathbf{q}\in \mathcal{Q}$ such that $\mathcal{S}(\mathbf{n})=\mathcal{S}(-\mathbf{q})$. However, letting $Q=\mathcal{Q}\setminus \{\mathbf{0}\}$ in \Cref{Lem_MR} gives us $\mu (\mathcal{D}(Q^{c}))=\mu (\mathcal{D}(\mathbf{0}))\geq \mu (\mathcal{S}(-\mathbf{q}))>-1$, a contradiction to \eqref{Eqn_MR+}. Hence, our supposition is not true, and $\mathcal{D}(\mathbf{0})$ has positive measure with respect to $f$.
\end{proof}

In the current additive value setting, Proposition 1 of \citet{armstrong1996multiproduct} follows directly from \Cref{Cor_Zero}: When $\mathcal{X}$ is strictly convex, we have $\mu (\mathcal{S}(-\mathbf{q}))=0$ for all $\mathbf{q}\in \mathcal{Q}$, ensuring the existence of a nonnegligible exclusion set.

\Cref{Fig_Exclusion} illustrates an example where the type space is not strictly convex. In particular, $\mathcal{X}=[\underline{x},\overline{x}]^{2}$, which is depicted in panel (a). In panel (b), the allocation space is $\mathcal{Q}=[0,1]^{2}$. In this case, whether there exists a nonnegligible exclusion set depends on the $\mu$ measure of $\mathcal{S}(-\mathbf{e}_{1})=\{\mathbf{x}\in \mathcal{X}:x_{2}=\underline{x}\}$ and $\mathcal{S}(-\mathbf{e}_{2})=\{\mathbf{x}\in \mathcal{X}:x_{1}=\underline{x}\}$. The two boundaries are marked in red in panel (a). In panel (c), the allocation space is $\Conv\{\mathbf{0},(1,k),(k,1),\mathbf{1}\}$, where $k\in (0,1)$. In this case, $\mathcal{S}(-\mathbf{e}_{1})$ and $\mathcal{S}(-\mathbf{e}_{2})$ become irrelevant, because $\mathbf{e}_{1}$ and $\mathbf{e}_{2}$ are no longer elements of $\mathcal{Q}$. For all $\mathbf{q}\in \mathcal{Q}$, $\mathcal{S}(-\mathbf{q})$ is a singleton $\{\underline{\mathbf{x}}\}$. Hence, there must be a nonnegligible exclusion set in any optimal mechanism, regardless of the distribution of types.

