\section{Minor Extensions}
\label{Sec_Extension}

\subsection{Quasi-Regular Distribution}
\label{Sec_Quasiregular}

In this section, we show that \Cref{Thm_Active} holds under a weaker regularity assumption. For simplicity, we will focus on the leading case where $\mathcal{X}=\mathcal{Q}=[0,1]^{N}$ and $\mathcal{Q}_{A}=\{\mathbf{q}\in \mathcal{Q}:q_{n}=1\text{ for some }n\in \mathcal{N}\}$.

Define $\mathcal{X}_{+}$ as the closure of $\{\mathbf{x}\in \mathcal{X}:\phi(\mathbf{x})>0\}$. We say that $f$ is \emph{quasi-regular} if $\mathcal{X}_{+}$ is a convex lower set with a nonempty interior, and $\phi(\mathbf{x})\neq 0$ for almost all $\mathbf{x}\in \mathcal{X}$. Intuitively, quasi-regularity requires that $\phi(\mathbf{x})=0$ is a nonincreasing and concave curve separating the type space into two regions, where $\mu$ assigns negative mass to the bottom-left region and positive mass to the top-right region. Obviously, strict regularity implies quasi-regularity.

When $f$ is quasi-regular, we can treat $\mathcal{X}_{+}$ as the ``type space'' that satisfies strict regularity. The top boundary of $\mathcal{X}_{+}$ is
\begin{equation*}
\overline{\bd}(\mathcal{X}_{+})=\{\mathbf{x}\in \bd (\mathcal{X}_{+}):\mathbf{x}\cdot\mathbf{n}_{\mathbf{x}}^{+}>0\text{ for all }\mathbf{n}_{\mathbf{x}}^{+}\text{ that is an outward normal to }\mathcal{X}_{+}\text{ at }\mathbf{x}\}.
\end{equation*}
By applying a similar methodology as in the proof of \Cref{Thm_Active}, we can show that the set of active bundles in any optimal contract is still a subset of $\mathcal{Q}_{A}$ under quasi-regularity. 

\begin{proposition}
\label{Prop_QuasiReg}
Suppose that $\mathcal{X}=\mathcal{Q}=[0,1]^{N}$ and that $f$ is quasi-regular. Then for any optimal mechanism, $\mathbf{q}$ is active only if $\mathbf{q}\in \mathcal{Q}_{A}$. 
\end{proposition}

\begin{proof}
Suppose that $\mathbf{q}\notin \mathcal{Q}_{A}$ is active. Then there exists $\delta_{1}>0$ such that $(\mathbf{q}+\delta B^{N})\cap \mathcal{Q}_{A}=\emptyset$ for $\delta\in (0,\delta_{1})$. If $\mu (\mathcal{D}(\mathbf{q}+\delta B^{N})\cap \overline{\bd}(\mathcal{X}))>0$ for any $\delta>0$, then we can follow the proof of \Cref{Thm_Active} and deduce a contradiction. Therefore, there exists $\delta_{2}>0$ such that $\mu (\mathcal{D}(\mathbf{q}+\delta B^{N})\cap \overline{\bd}(\mathcal{X}))=0$ for $\delta\in (0,\delta_{2})$.

Now we fix a $\delta\in (0,\min(\delta_{1},\delta_{2}))$. By \Cref{Thm_MR} and quasi-regularity, $\mathcal{D}(\mathbf{q}+\delta B^{N})\cap \overline{\bd}(\mathcal{X}_{+})$ has positive measure with respect to the surface measure on $\overline{\bd}(\mathcal{X}_{+})$, and $\mathcal{D}(\mathbf{q}+\delta B^{N})\cap \{\mathbf{x}\in \Int (\mathcal{X}):\phi (\mathbf{x})=0\}$ has positive measure with respect to $f$. It is also easy to see that $\mathcal{D}(\mathbf{q})\cap \overline{\bd}(\mathcal{X}_{+})\cap \Int (\mathcal{X})\neq \emptyset$.

Let $\mathbf{x}\in \mathcal{D}(\mathbf{q})\cap \overline{\bd}(\mathcal{X}_{+})\cap \Int (\mathcal{X})$. Since $\mathcal{X}_{+}$ is a convex lower set, $\mathbf{n}_{\mathbf{x}}^{+}\geq 0$, and there exists $\varepsilon>0$ such that $\mathbf{q}+\varepsilon \mathbf{n}_{\mathbf{x}}^{+}\in \mathcal{Q}_{A}$. The two convex sets $\mathcal{D}(\mathbf{q})$ and $\mathcal{D}(\mathbf{q}+\varepsilon \mathbf{n}_{\mathbf{x}}^{+})$ are separated by a hyperplane with normal vector $\mathbf{n}_{\mathbf{x}}^{+}$. By the same argument, any $\hat{\mathbf{q}}\in (\mathbf{q}+\delta B^{N})$ can be mapped to a bundle in $\mathcal{Q}_{A}$, and the demand sets for them are separated by a hyperplane with normal vector $\mathbf{n}_{\mathbf{x}}^{+}$. Denote by $Q$ the collection of all these vectors in $\mathcal{Q}_{A}$. We can conclude that $\mathcal{D}(\mathbf{q}+\delta B^{N})$ and $\mathcal{D}(Q)$ are separated by the hyperplane $\{\hat{\mathbf{x}}\in \mathbb{R}^{N}: \hat{\mathbf{x}}\cdot\mathbf{n}_{\mathbf{x}}^{+}=\xi\}$ for some $\xi>0$. This also implies that $\mathcal{X}_{+}$ and $\mathcal{D}(Q)$ are separated by the same hyperplane. By \eqref{Eqn_MR-}, $\mu (\mathcal{D}(Q))\leq 0$. Therefore, reducing $\overline{p}(Q)$ by a sufficiently small amount increases revenue, a contradiction to \eqref{Eqn_SOC_1}. Hence, our supposition is not true, and $\mathbf{q}$ is inactive.
\end{proof}

When $N=2$, \Cref{Prop_QuasiReg} allows us to apply the results in \Cref{Sec_2D} with the help of a well-defined $\zeta$. We illustrate this in \Cref{Exp_Beta}. Again, $x_{1}$ and $x_{2}$ are assumed to be i.i.d. with marginal p.d.f. $g$ and c.d.f. $G$.

\begin{example}[Beta distribution]
\label{Exp_Beta}
Let $g(x)=\mathcal{B}(\alpha,\beta)^{-1}x^{\alpha-1}(1-x)^{\beta-1}$, where $\alpha,\beta>0$ and $\mathcal{B}$ is the beta function. Then $f$ is quasi-regular. Moreover, when $\alpha=1$, we can get an explicit expression for $\zeta$ from \eqref{Eqn_Zeta_iid}:
\begin{equation*}
\zeta (x)=
\begin{cases}
\frac{2-(\beta+1)x}{(\beta+2)-(2\beta+1)x} & x\in [0,2/(\beta+1)], \\
0 & x\in (2/(\beta+1),1].
\end{cases}
\end{equation*}
It can be verified that $\zeta$ is concave on $[0,2/(\beta+1)]$. Thus the optimal $\overline{u}$ is characterized by \Cref{Cor_CcvDec}, that is, $\overline{u}(x)=1-\zeta (x)$ for $x\in [0,a^{1})$, and $\overline{u}'(x)=1$ for $x\in [a^{1},1]$.
\end{example}

