\centering
\input{Fig_Beta}
\caption{Beta distribution.}
\label{Fig_Beta}
\end{figure}

\Cref{Exp_Beta} has been studied by \citet[Example 3]{daskalakis2017strong} as an illustration of their Theorem 7.

\subsection{Unbounded Type Space}
\label{Sec_Unbounded}

The marginal revenue approach extends naturally to an unbounded type space. In this section, we demonstrate our method in the setting where $\mathcal{X}=[\underline{x},+\infty )^{2}$ for some $\underline{x}\geq 0$ and $\mathcal{Q}=[0,1]^{2}$. While we continue to assume that $f$ is continuously differentiable, it is also required that $f$ vanishes sufficiently rapidly as $\lVert\mathbf{x}\rVert$ increases. Specifically, we assume
\begin{equation*}
\lim_{\lVert\mathbf{x}\rVert\to +\infty}\lVert\mathbf{x}\rVert^{2}f(\mathbf{x})=0.
\end{equation*}
Under these assumptions, the seller's revenue still admits the indirect-utility representation given by \eqref{Eqn_Rev}, where $\mu$ is given by \eqref{Eqn_mu}.\footnote{See \citet{daskalakis2013mechanism} for a derivation under similar assumptions.} The only difference is that the top boundary no longer exists, since $\bd (\mathcal{X})=\{\mathbf{x}\in \mathcal{X}: x_{n}=\underline{x}\text{ for some }n\}$. As a consequence, when $f$ is regular, $\mu$ becomes a nonpositive measure, implying that $u(\mathbf{x})=0$ is trivially optimal. Therefore, the remainder of this section will deviate from regularity.

We say that the environment is \emph{strictly reversed regular and symmetric (SRRS)} if $\phi (\mathbf{x})<0$ for almost all $\mathbf{x}\in \mathcal{X}$ and $f$ is symmetric. Under reversed regularity, $\mu$ assigns positive mass only to $\Int (\mathcal{X})$ and negative mass only to $\bd (\mathcal{X})$.

\begin{proposition}
\label{Prop_Unbounded}
Suppose that the environment is SRRS. Then pure bundling is optimal.
\end{proposition}

\begin{proof}
For any optimal $u$, let $\underline{u}(\cdot)=(\cdot,\underline{x})$. Then by convexity, $u(\mathbf{x})\leq u(\underline{x},x_{1}+x_{2}-\underline{x})=\underline{u}(x_{1}+x_{2}-\underline{x})$. It can be verified that the function $\hat{u}(\mathbf{x})=\underline{u}(x_{1}+x_{2}-\underline{x})$ is also feasible, and $\int_{\mathcal{X}}(\hat{u}-u)\dd \mu\geq 0$ due to SRRS. Therefore, $\hat{u}$ is also optimal.

Applying the change of variable $r=x_{1}+x_{2}-\underline{x}$ to the total revenue:
\begin{equation*}
\int_{\mathcal{X}}\hat{u}\dd \mu=\int^{+\infty}_{0}\left[\int^{r}_{\underline{x}}\phi (r+\underline{x}-x_{2},x_{2})\dd x_{2}-2cf(r,\underline{x})\right]\underline{u}(r)\dd r,
\end{equation*}
which is a linear functional of $\underline{u}$. By \citet{myerson1981optimal}, there exists an optimal $\underline{u}$ that is determined by a cutoff $r^{*}\geq \underline{x}$, such that $\underline{u}'=0$ for $r\in [\underline{x},r^{*})$ and $\underline{u}'=1$ for $r\geq r^{*}$. For this specific $\underline{u}$, $\hat{u}(\mathbf{x})=\underline{u}(x_{1}+x_{2}-\underline{x})$ corresponds to a pure bundling mechanism. The proposition is thereby proved.
\end{proof}

\Cref{Prop_Unbounded} implies a similar result in \citet[Theorem 6]{hart2014good}, which is obtained under the i.i.d. assumption.

