\begin{table}[htbp]
\caption{\label{tab:table1}Tunability, speed, and accuracy of components used in $f_{rep}$ control loop.}
\begin{tabular}{|c|c|c|c|} 
 \hline
  \textbf{Component} & \textbf{Tunability Range} & \textbf{Response Time} & \textbf{Accuracy} \\ [0.5ex] 
 \hline
