\title{Finitely Summable $K$-homology, the Index Pairing, and Cantor Minimal Systems}
\author{Levi Lorenzo}
\address{Levi Lorenzo, Department of Mathematics, University of Colorado Boulder Campus Box 395, Boulder, CO 80309-0395, USA}
