\section{Preliminaries}
    \subsection{Fredholm Modules and $K$-homology}
 The primary reference for analytic $K$-homology is \cite{HR}. $K$-homology classes are represented by \textit{Fredholm modules}. Specifically, $K^0$ is generated by equivalence classes of \textit{graded} Fredholm modules while $K^1$ is generated by equivalence classes of \textit{ungraded} Fredholm modules.
\begin{Def}
Let $A$ be a $C^*$-algebra. An ungraded \textbf{Fredholm module} over $A$ is a triple $(H, \rho,F)$ where: 
\begin{itemize}
    \item $H$ is a separable Hilbert space
    \item $\rho: A \to B(H)$ is a representation
    \item $F \in B(H)$ satisfies:
    \begin{enumerate}
        \item $(F^2-1)\rho(a) \in K(H)$ for each $a \in A,$
        \item $(F-F^*)\rho(a) \in K(H)$ for each $a \in A,$ and
        \item $[F,\rho(a)] \in K(H)$ for each $a \in A.$
    \end{enumerate}
\end{itemize}
\end{Def}
 A \textit{graded Fredholm module} is of the form: \[ (H,\rho,F) = \left(H_+ \oplus H_-, \rho_+ \oplus \rho_-, \begin{bmatrix} 0 & V \\ U & 0 \end{bmatrix} \right)\] where $U-V^*, V-U^*, UV-1, VU-1 \in \K$ and $\rho_+(a) U - U \rho_-(a), V \rho_-(a) - \rho_+(a) V \in K(H)$ for each $a \in A.$ 

We work with crossed product $C^*$-algebras in this thesis, and the $K$-homology of a crossed-product algebra is obtained from the $K$-homology of the base algebra via the Pimsner-Voiculescu exact sequence:
\begin{prop}\label{PVKhom}
For a $C^*$-algebra $A$ and an action $\alp \in \text{Aut}(A)$ there is a Pimsner-Voiculescu exact sequence in K-homology for the crossed product $A \rtimes_\vp \Z:$
\[\begin{tikzcd}
{K^0(A \rtimes_\alp \Z )} \arrow[d] & K^0(A) \arrow[l] & K^0(A) \arrow[l, "1-\alp^*"]   \\
K^1(A) \arrow[r, "1- \alp^*"]   & K^1(A) \arrow[r]  & {K^1(A \rtimes_\alp \Z)} \arrow[u]
\end{tikzcd}\]
\end{prop}
\subsection{Spectral Triples and Unbounded Fredholm modules}
Some of the Fredholm modules in this paper arise from \textit{spectral triples.}
\begin{Def}
An (odd) \textbf{spectral triple} is a triple $(A, H, D)$ where:
\begin{enumerate}[(1)]
    \item $H$ is a separable Hilbert space,
    \item $A$ is a $*$-subalgebra of $B(H),$ and
    \item $D$ is an unbounded self-adjoint operator in $H$ which satisfies, for each $a \in A$:
    \begin{enumerate}
    \item $a \text{Dom}(D) \sub \text{Dom}(D),$
        \item  $[D,a] \in B(H),$ and
        \item $a(1+D^2)^{-1} \in K(H).$
    \end{enumerate}
\end{enumerate}
\end{Def}
If $H$ is equipped with a $\Z/2\Z$ grading, $A$ is an algebra of even operators, and $D$ is odd, then $(A,H,D)$ is an even spectral triple. 

In the case of a $C^*$-algebra, spectral triples determine \textit{unbounded Fredholm modules}:
\begin{Def}
    Suppose $A$ is a $C^*$-algebra, $\A \sub A$ is dense, and $(\A,H,D)$ is a spectral triple. Denote by $\pi$ the action of $\A$ on $H,$ $\pi: \A \to B(H).$ Then, we denote by $(H,\pi, D)$ the \textbf{spectral triple} or \textbf{unbounded Fredholm module} on $\A$ given by $(\A,H,D).$
\end{Def}
There is a notion of summability for spectral triples:
\begin{Def}
    If $A$ is unital and $\text{Tr}(1+D^2)^{-\f p2} < \infty,$ then $(A,H,D)$ is $p-$summable. If such a $p < \infty$ exists, we say $(A,H,D)$ is finitely summable. The infimum of such $p$ is called the \textbf{spectral dimension} of $(A,H,D).$
\end{Def}
Fredholm modules are obtained from spectral triples via the bounded transform: 
\begin{prop}\label{BT}
Let $A$ be a $C^*$-algebra. Suppose $A$ is represented on a Hilbert Space $H$ via $\pi:A \to B(H)$. Further, suppose $\mathscr{A} \sub A$ is dense and $(\pi(\mathscr{A}), H, D)$ is an (even/odd) spectral triple. Then $\left(H, \pi, \frac{D}{(1+D^2)^{\f 12}}\right)$ is an (even/odd) Fredholm module over $A,$ called the \textbf{bounded transform} of $(\pi(\mathscr{A}), H, D).$ In the case that $D$ is invertible, we can use $D|D|^{-1}$ instead of 
$ \frac{D}{(1+D^2)^{\f 12}}.$ 
\end{prop}


\subsection{Index Pairings and Summability}
Our work concerns the index pairing and circumstances in which we can make it more computable. For a more detailed exposition on index pairings and their formulas see \cite{HR}, \cite{C}.
\begin{Def}
    Let $A$ be a separable $C^*$-algebra. Then there is a bilinear map $\langle -, -\rangle_A: K_*(A) \times K^*(A) \to \Z$ called the \textbf{index pairing}.
\end{Def}
The condition on Fredholm modules which facilitates computation of index pairings using trace formulas is \textit{summability}.
\begin{Def}
An odd (even) Fredholm module $(H, \rho, F)$ over a 
$C^*$-algebra $A$ is \textbf{$p$-summable} if there exists a dense sub-algebra $\mathscr{A} \sub A$ such that, for all $a \in \mathscr{A}:$ \[ \rho(a)(F^2-1),\: \rho(a) (F-F^*) \in L^{\f p2}(H), \text{ and } [F,\rho(a)] \in L^p(H).\]
\end{Def}
 Specifically, index pairings with $p$-summable Fredholm modules can be computed using Connes' trace formulas \cite{C}:
\begin{prop}
    Suppose $(H,\rho,F)$ is an odd Fredholm module that is $p$-summable over $\mathscr{A} \sub A$ and $u \in \mathscr{A}$ is a unitary. Then, \[\langle[u], [H, \rho, F] \rangle = \f{(-1)^{\frac{n-1}{2}-1}}{2^{n}}\text{Tr}(\rho(u^*)([F, \rho(u)][F, \rho(u^*)])^{\frac{n-1}{2}} [F, \rho(u)])\] for $n > p$ odd.
\end{prop}
 \begin{prop}
     Suppose $\left (H_+ \oplus H_-,\rho_+ \oplus \rho_- , \begin{bmatrix} 0 & U \\ V & 0 \end{bmatrix}\right)$ is an even Fredholm module that is $p$-summable over $\mathscr{A} \sub A$ and $p$ is a projection in $\mathscr{A}.$ Then,  \begin{footnotesize} \[ \left \langle[p], \left [H_+ \oplus H_-,\rho_+ \oplus \rho_- , \begin{bmatrix} 0 & U \\ V & 0 \end{bmatrix}\right] \right \rangle =  (-1)^{\f{n(n-1)}{2}} \text{Tr}\left(\begin{bmatrix} 1 &0 \\0 & -1 \end{bmatrix} \rho_+ \oplus \rho_-(p)\left(\left[\begin{bmatrix} 0 & U\\ V & 0\end{bmatrix}, \rho_+ \oplus \rho_-(p)\right]\right)^{n}\right) \]\end{footnotesize} for $n > p$ even.
 \end{prop}
In either case, we can extend these formulas to matrix amplifications over $\mathscr{A}.$ Because they are given in terms of a trace, these formulas are often computable. The desire to compute index pairings using trace formulas motivates the study of \textit{uniformly finitely summable} $K$-homology: 
\begin{Def}
A $C^*$- algebra $A$ is said to have \textbf{uniformly $p$-summable} $K$-homology if for $p > 0$ there is a dense $*$-subalgebra $\mathscr{A} \sub A$ such that each class in $K^*(A)$ (for $*=0$ and $1$) can be represented by a Fredholm module which is $p$-summable on $\mathscr{A}.$
\end{Def}

\begin{prop}
    If $\mathscr{A}$ is a dense $*$-subalgebra of $A$ on which $K^*(A)$ is $p$-summable, then there exists $\mathscr{A} \sub \mathcal{A} \sub A$ where, for each $n,\: M_n(\mathscr{A})$ is closed under the holomorphic functional calculus in $M_n(A)$ so that $\iota_*:K_*(\mathscr{A}) \to K_*(A)$ is an isomorphism, and on which $K^*(A)$ is $p$-summable \cite{C}. 
\end{prop}
Thus, when a $C^*$-algebra $A$ has uniformly $p$-summable $K$-homology, any index pairing between $K_*(A)$ and $K^*(A)$ can be computed via Connes' trace formulas for $p$-summable Fredholm modules because $\bigcup_{k \in \N} M_k(\mathscr{A})$ contains a representative of each $K_*(A)$ class.

\subsection{$KK$-Theory and the UCT}
The tools of Kasparov's $KK$-theory will be useful to translate results between $K$-theory and $K$-homology. For a full exposition on $KK$-theory, see \cite{K}.  Note that, for a separable $C^*$-algebra $A,\: KK_*(\C,A) \cong K_*(A)$ and $KK_*(A,\C) \cong K^*(A).$ $KK$-theory has an associative product. We utilize a case of this product called the \textit{cap product.}

\begin{Def}
    Let $A,B,D$ be separable $C^*$-algebras. There is an associative product $- \otimes_B - : KK(A,B) \times KK(B,D) \to KK(A,D)$ called the \textbf{cap product}.
\end{Def}

Additionally, the index paring is an example of the Kasparov product:
\begin{Ex}\label{IndexKKprod}
    Let $x \in K_*(A), y\in K^*(A).$ Then $\langle x,y \rangle_A = x \otimes_A y \in KK(\C,\C).$
\end{Ex}
\begin{Ex}\label{KKhom}
    Classes in $KK(A,B)$ represent `generalized morphisms' from $A$ to $B.$ When $\vp:A \to B$ is a $*$-homomorphism, $[\vp] = [B, \vp, 0]$ is a $KK_0(A,B)$ class. Further, the cap product satisfies: $[\vp] \otimes_B - = \vp^*(-) : KK(B, D) \to KK(A,D),$ while $- \otimes_A [\vp] = \vp_*(-):KK(D,A) \to KK(D,B),$ which we utilize in Section 6.
\end{Ex} 
\subsection{The Universal Coefficient Theorem} The tool we use to obtain results about $K$-homology from results on $K$-theory is the Universal Coefficient Theorem (UCT): \begin{Def}\label{UCT} We say that a $C^*$-algebra $A$ \textbf{satisfies the UCT} if, for all separable $C^*$-algebras $B,$ the following sequence is exact: \[0 \xrightarrow{} \text{Ext}_\Z^1(K_*(A), K_*(B)) \xrightarrow{\de} KK_*(A,B) \xrightarrow{\gm} \text{Hom}(K_*(A), K_*(B)) \xrightarrow{} 0.\] Recall that $\de$ has degree 1 and $\gm$ has degree 0.
\end{Def}
All $C^*$-algebras in this paper will satisfy the UCT, in particular, AF-algebras do, commutative algebras do, and the property of satisfying the UCT is preserved when taking crossed products by $\Z$ \cite{RS}.
\begin{Def}
    The map $\gm$ is given by $\gm(x):= - \otimes_A [x]:KK(\C,A) \to KK(\C, B)$ where $x \in KK(A,B).$
\end{Def} 
Thus, in the case of Example \ref{IndexKKprod}, we obtain: 
\begin{prop}
    If $A$ satisfies the UCT, $x \in K_*(A),$ and $y \in K^*(A),$ then $\langle x, y \rangle = \gm(y)(x).$
\end{prop}
\section{Cantor Minimal Systems}
The $C^*$-algebras we study in this paper arise from Cantor minimal systems. These are dynamical systems obtained from \textit{minimal homeomorphisms} on the \textit{Cantor set}.
    \begin{Def}
    A topological space $X$ is called a \textbf{Cantor set} if it is a totally disconnected, compact, metrizable space with no isolated points. (There is a unique space with these properties, so we refer to \textbf{the} Cantor Set.)
\end{Def}
We often use a symbolic representation of the Cantor set. \begin{Ex}\label{Cantoralph}
    Common models of the Cantor set include $\Omega^\Z, \Omega^\N,$ or a closed subset of either for a finite set $\Omega.$ 
    \begin{itemize}
        \item The metric on $\Omega^{\Z}$ (or a closed subset of $\Omega^\Z)$ is given by $d((x_i),(y_i)) = 2^{- \min\{|j|||x_j \neq y_j\}}.$
        \item The metric on $\Omega^\N$ (or a closed subset of $\Omega^\N$) is given by $d((x_i),(y_i)) = 2^{- \min\{j||x_j \neq y_j\} + 1}.$
    \end{itemize}  
\end{Ex}
This topology can also be given by a basis of clopen sets. 
\begin{Def}
    Suppose $X \sub \Omega^\Z$ is a Cantor set. Let $(x_n)_{n\in \Z} \in X$ and $a < b \in \Z.$ We denote by $x_{[a,b]} = x_a x_{a+1} \cdots x_{b}.$ Further $x_{(-\infty, b]} = \ldots x_{b-2} x_{b-1} x_b$ and $x_{[b,\infty)} = x_b x_{b+1} \ldots$ will denote the left and right tails of $x$ respectively.
\end{Def}
\begin{Def}
    For any $x \in X,\: a < b \in \Z, \: x_{[a,b]}$ will denote a \textbf{word} in X. For such a word $ \mu = x_{[a,b]}, \: |\mu| = b-a+1,$ is called the \textbf{length} of $\mu.$ The \textit{empty word}, denoted $\ee,$ is the unique word of length 0.
\end{Def}
\begin{Def}
    We denote by $Y$ the set of all words in $X: Y = \{x_{[a,b]} |x \in X, a< b \in \Z\} \cup \{\ee\}.$
\end{Def}
\begin{Def}
    If $\mu, \nu \in Y$ and $\nu = \mu a_1\cdots a_k$ for $a_1, \ldots, a_k \in \Omega,$ we say that $\mu$ is a \textbf{subword} of $\nu.$ Notice that the empty word is a subword of every word in $Y.$
\end{Def}
\begin{Def}\label{cylinder}
    For $\mu \in Y,$ denote by $C_\mu$ the \textbf{cylinder set defined by }$\mu$: \begin{itemize} \item If $X \sub \Omega^\N,$ $C_\mu = \{x \in X| x_{[0,|\mu| -1]} = \mu \}.$
    \item If $X \sub \Omega^\Z, |\mu|$ odd: $C_\mu = \{x \in X| x_{[-\frac{|\mu| -1}{2},\frac{|\mu| -1}{2}]} = \mu\}.$
    \item If $X \sub \Omega^\Z, |\mu|$ even: $C_\mu = \{x \in X| x_{[-\frac{|\mu|-1}{2},\frac{|\mu|}{2}]} = \mu\}.$
    \end{itemize}
\end{Def}
We collect a few facts below:
\begin{prop}
Let $\mu \in Y.$
    \begin{itemize}
        \item In the metric topology, each $C_\mu$ is clopen.
        \item  For any closed $X \sub \Omega^\Z$ (or $\Omega^\N$), the collection $\{ C_\mu | \mu \in Y\}$ forms a basis for the topology on $X.$
        \item Further, for each $n,$ $\mathscr{C}_n =\{C_\mu| \:|\mu| =n\}$ is a partition of $X.$ 
        \item These partitions are \textit{increasing}, in the sense that, for each $m > n,$ and each $Z \in \mathscr{C}_m,$ there is a $Z' \in \mathscr{C}_n$ such that $Z \sub Z'.$ 
    \end{itemize}
\end{prop}
\begin{prop}
    If $X$ is the Cantor set, \[K_0(C(X)) \cong C(X,\Z) \cong \text{span}\{\chi_E | E \text{ clopen } \sub X\}, \: \: K_1(C(X)) \cong \{0\}.\] Thus, by the UCT \[K^0 (C(X)) \cong \text{Hom}(C(X, \Z), \Z), \: \: K_1(C(X)) \cong 0,\] for example, see \cite{P} or \cite{B}.
\end{prop} 
\subsection{Odometers}
    Odometers are a particularly nice class of Cantor minimal systems. We can associate an odometer to each sequence of integers, $\{d_i\}_{i=1}^\infty, d_i \geq 2$ \cite{P}. 
\begin{Def}\label{Odometer}
    We let $X= \prod_{i=1}^\infty X_i$ where $X_i = \{0,1,\ldots, d_i -1\}$ and define $\vp: X \to X $ as follows. First, $\vp(d_1-1,d_2-1, \ldots, d_n -1, \ldots) = (0,0,0, \ldots).$ Now, suppose $(x_1,x_2, \ldots) \in X$ where for some $j, x_j \neq d_j-1.$ Then define $k = \min\{j| x_j \neq d_j -1\}$ and $\vp(x_1,x_2,\ldots) = (0,\ldots, 0, x_k +1, x_{k+1},x_{k+2}, \ldots),$ i.e. $\vp$ acts on $X$ via ``add $(1,0,0,\ldots)$ with carry.''
\end{Def}
\begin{Def}
    The topology on $X$ is induced by a metric $d:X\times X \to \R_{\geq 0}.$ The metric is defined by $d((x_i), (y_i)) = 2^{-\min\{j| x_j \neq y_j\} + 1}.$
\end{Def}
This topology makes $X$ into a Cantor set and makes $\vp$ a minimal homeomorphism. 
\subsection{Ordered Bratteli diagrams and Bratteli-Vershik Systems} 
Bratteli diagrams (and their associated Bratteli-Vershik systems) are a valuable tool for studying Cantor minimal systems. For further details on such systems see \cite{HPS}, \cite{PB}. In particular, every Cantor minimal system is conjugate to a Bratteli-Vershik system associated to a \textit{properly ordered Bratteli diagram} \cite[Theorem 4.6]{HPS}. \begin{Def}
    A \textbf{Bratteli diagram} $(V,E)$ consists of a set of vertices $V = \bigsqcup_{n=0}^\infty V_n,$ a set of edges $E = \bigsqcup_{n=1}^\infty E_n,$ and maps $s:E_n \to V_{n-1}, r: E_n \to V_n,$ called the \textbf{range} and \textbf{source} maps. Moreover, $V_n$ and $E_n$ are finite non-empty disjoint sets and $V_0 = \{v_0\}$ is a one-point set.
\end{Def}
Each edge $e_n \in E_n$ connects the vertex $s(e_n) \in V_{n-1}$ to the vertex $r(e_n) \in V_n.$ We assume that $s^{-1}(v) \neq \es$ for all $v \in V$ and $r^{-1}(v) \neq \es$ for all $v \not \in V_0.$ 
\begin{Def}
    If $|V_{n-1}| = k_{n-1}, |V_n| = k_n,$ then $E_n$ can be described by a $k_n \times k_{n-1}$ \textbf{transition matrix}, $S_n = [S_{ij}^n],$ where $S_{ij}^n$ is the number of edges connecting $v_i^n \in V_n$ with $v_j^{n-1} \in V_{n-1}.$
\end{Def} 

\begin{Def}\label{Bratpath}
    The \textbf{infinite path space} associated to the Bratteli diagram $(V,E)$ is \[X_{(V,E)} = \{(e_1,e_2, \ldots)|\: e_i \in E_i, r(e_i) = s(e_{i+1}) \text{ for all } i \geq 1\}.\]  We topologize $X_{(V,E)}$ using the subspace topology inherited from $\prod_{n=1}^\infty E_n,$ which is endowed with the product topology.
\end{Def}
\begin{Def}\label{Bratorder}
      An \textbf{ordered Bratteli diagram} $(V,E,\geq)$ is a Bratteli diagram $(V,E)$ together with a partial order $\geq$ in $E$ so that edges $e,e' \in E$ are comparable if and only if $r(e) = r(e').$
  \end{Def}  
  We denote by $E_{min},E_{max}$ the minimal and maximal edges of the poset $E.$ 


\begin{Def}\label{BV}
The \textbf{Vershik map} associated to a \textit{properly ordered Bratteli diagram} (see \cite{HPS},\cite{PB}) $(V,E,\geq)$ is the map, $T,$ given by $T(x_{max}) = x_{min}$ and, if $x = (e_1,e_2,\ldots) \neq x_{max}, k$ is the minimal number so that $e_k \not \in E_{max}, f_k$ is the successor of $e_k,$ and $(f_1,f_2, \ldots, f_{k-1})$ be the unique minimum path in $E_1 \circ E_2 \circ \cdots \circ E_{k-1}$ from $s(F_k)$ to $V_0.$ Then $T(e_1,e_2, \ldots) = (f_1,f_2, \ldots, f_k, e_{k+1}, e_{k+2}, \ldots).$ Then $(X_{(V,E)},T)$ is called the \textit{Bratteli-Vershik System} associated to $(V,E, \geq).$ \end{Def} 

Given a Cantor minimal system, $(X,\vp),$ \cite[Section 4]{HPS} shows how to construct a Bratteli-Vershik system conjugate to it. This is the same construction as used to produce the orbit-breaking subalgebras as in Section \ref{subalg}. We will use the following example of a Bratteli-Vershik system as our running example of a non-odometer Cantor minimal system:
