		\end{abstract}

		\section{Introduction}
		\numberwithin{equation}{section}

		In this paper, we consider the Schrödinger equation as follows
		\[
			\left\{\begin{array}{ll}
				i u_{t}-\Delta u=0 & (x, t) \in \mathbb{R}^{d} \times \mathbb{R} \\
				u(x, 0)=f(x) & x \in \mathbb{R}^{d}.
			\end{array}\right.
		\]
		 The solution to this equation can be formally written as
		\[
			e^{i t (-\Delta)} f(x)=\frac{1}{(2\pi)^{d}}\int_{ \mathbb{R}^{d}} e^{i\left(x \cdot \xi+t|\xi|^{2}\right)} \widehat{f}(\xi) d \xi.
		\]
		Carleson \cite{MR0576038} put forward a question about exploring the minimal $s$ such that for any 
		$ f \in H^{s}\left(\mathbb{R}^{d}\right)$,
		there holds the almost everywhere convergence
		\begin{equation}\label{1.2}
		\underset{t \rightarrow 0}{\lim} ~e^{i t (-\Delta)} f(x)=f(x), \quad a.e.
		\end{equation}
		It has been studied by several authors \cite{MR0576038,MR0654188,MR0848141,MR0729347,MR0904948,MR0934859,MR1315543,MR1413873,MR1748920,MR2264734,MR3241836,MR3613507,Demeter2016SchrdingerMF,MR3574661,MR2044636,MR3903115,MR3702674,MR3961084}. In particular, Carleson \cite{MR0576038} pointed \( s \geq \frac{1}{4} \) when \( d=1 \) and  Du--Zhang \cite{MR3961084} proved \(s>\frac{d}{2(d+1)} \) when \( d\geq 2 \) are sharp results according to the counterexamples made by Dahlberg--Kenig \cite{MR0654188} in $d=1$ and
		Bourgain \cite{MR3574661}, Luc\`a--Rogers \cite{MR3903115} in $d\geq  2$.

		Some related issues have also been widely studied, including the pointwise convergence problem of the Schrödinger operator along curves
		\[
			U_\gamma f(x,t)=\frac{1}{(2\pi)^{d}}\int_{ \mathbb{R}^{d}}  e^{i\left(\gamma(x,t) \cdot \xi+t|\xi|^{2}\right)} \widehat{f}(\xi) d \xi.
		\]
		Here, we will always assume \(
		\gamma: \mathbb{R}^{d} \times[-1,1] \rightarrow \mathbb{R}^{d}, \quad \gamma(x, 0)=x
		\) is a continuous function satisfying bilipschitz continuous in \( x \), that is
		\[
		\frac{1}{C_{1}}\left|x-x^{\prime}\right| \leq\left|\gamma(x, t)-\gamma\left(x^{\prime}, t\right)\right| \leq C_{2}\left|x-x^{\prime}\right|, \quad t \in[-1,1], \quad x, x^{\prime} \in \mathbb{R}^{d} .
		\]
		The curve will be divided into tangential case $(0<\alpha<1)$ and non-tangential case $(\alpha=1)$ according to the Hölder continuous condition \( \alpha \in(0,1] \) in \( t \) , that is
		\[
			\left|\gamma(x, t)-\gamma\left(x, t^{\prime}\right)\right| \leq C_{3}\left|t-t^{\prime}\right|^{\alpha}, \quad x \in \mathbb{R}^{d}, \quad t, t^{\prime} \in[-1,1].
		\]

		For non-tangential case, Lee--Rogers \cite{MR2871144} showed the convergence problem is essentially equivalent to the traditional case (\ref{1.2}). The tangential case is more complex. In $d=1$, Cho--Lee--Vargas \cite{MR2970037} observed \( s>\max \left\{\frac{1}{4}, \frac{1-2 \alpha}{2}\right\} \) is the sharp sufficient condition. In $d\geq2$,  Minguill\'on \cite{MR4795804} and Cao--Miao \cite{MR4564456} got  the sharp result $s>\frac{d}{2(d+1)}$ when $\frac{1}{2}\leq \alpha\leq1$. However, the sharp sufficient condition for  $0< \alpha<\frac{1}{2}$ remains open.


		The convergence rate of Schrödinger operator is first considered by Cao-Fan-Wang \cite{MR3922421}, which has been improved to sharp by Wang--Zhao \cite{MR4877623} in $d=1$ and Fan--Wang \cite{Fan-Wang} in higher dimension.  To elucidate, after reaching the minimum regularity requirement $s>\frac{d}{2(d+1)}$ for almost everywhere convergence, if continues to increase the regularity of the function, what kind of convergence rate can it bring? It can be transformed to determine the optimal $s$ for \( f \in H^{s}\left(\mathbb{R}^{d}\right) \) to ensure
		\[
			\lim _{t \rightarrow 0} \frac{e^{i t (-\Delta)} f(x)-f(x)}{t^\delta}=0 \quad \text { a.e. } x \in \mathbb{R}^{d}.
		\]

		The convergence rate of Schrödinger operators along tangential curves is considered by Li--Wang \cite{MR4297035,Li2021OnCP}. In this paper, we investigate the convergence rate of the Schrödinger operator along curves $U_\gamma f(x,t)$, which is sharp to the endpoint.


