		\subsection{Convergence rate of Schrödinger operator along curves}\label{chap2}
		\numberwithin{equation}{section}

		~\\

		When the curve is bilipschitz continuous in \( x \) and Lipschitz continuous in \( t \), we obtain the following theorem. It's consistent with the properties of $e^{it(-\Delta)} f$, which is also intuitive.
		\begin{theorem}\label{theorem1}
			Let $\delta \in[0,1)$. For any curve $\gamma: \mathbb{R}^{d} \times[-1,1] \rightarrow \mathbb{R}^{d} $satisfying $\gamma(x,0)=x$  which is bilipschitz continuous in \( x \) and lipschitz continuous in \( t \), we have
			\begin{equation}\label{pointwise convergence in rn}
				\lim _{t \rightarrow 0} \frac{U_{\gamma} f(x, t)-f(x)}{t^\delta}=0 \quad \text { a.e. } x \in \mathbb{R}^{d} ,\quad \forall f \in H^{s}\left(\mathbb{R}^{d}\right)
			\end{equation}
			whenever 
			\[
			s>s(\delta)=\begin{cases}
				\frac{d}{2(d+1)} +\delta   \quad  &0 \leq \delta\leq \frac{d}{2(d+1)}, \\ 
				2\delta   \quad   &  \delta>\frac{d}{2(d+1)}.  \\
			\end{cases}
			\]
			Conversely, there exists a curve satisfying the previous assumption, while (\ref{pointwise convergence in rn}) fails whenever $s<s(\delta)$.
		\end{theorem}

		When $d=1$, we can discuss the case where the curve is $\alpha$-Hölder continuous in \( t \). We have the following three theorems.

		\begin{theorem}\label{theorem2}
			Let $\delta \in[0,\alpha)$. For any curve $\gamma(x,t): \mathbb{R} \times[-1,1] \rightarrow \mathbb{R}$ satisfying $\gamma(x,0)=x$ which   is bilipschitz continuous in \( x \), and $\alpha$-Hölder continuous in \( t \) with \(  \frac{1}{2}\leq \alpha < 1\), we have
			\begin{equation}\label{pointwise convergence in r1}
				\lim _{t \rightarrow 0} \frac{U_{\gamma} f(x, t)-f(x)}{t^\delta}=0 \quad \text { a.e. } x \in \mathbb{R},\quad \forall f \in H^{s}\left(\mathbb{R}\right)
			\end{equation}
			whenever 
			\[
			s>s(\delta)=\begin{cases}
				\frac{1}{4} +\delta   \quad  &0  \leq\delta\leq \frac{1}{4}, \\ 
				2\delta   \quad   &  \delta>\frac{1}{4}.  \\
			\end{cases}
			\]
			Conversely, there exists a curve satisfying the previous assumption, while (\ref{pointwise convergence in r1}) fails whenever $s<s(\delta)$.

		\end{theorem}

		\begin{theorem}\label{theorem3}
			Let $\delta \in[0,\alpha)$. For any curve $\gamma(x,t): \mathbb{R} \times[-1,1] \rightarrow \mathbb{R}$ satisfying $\gamma(x,0)=x$ which  is bilipschitz continuous in \( x \), and $\alpha$-Hölder continuous in \( t \) with \(  0 \leq \alpha \leq \frac{1}{4}  \), we have (\ref{pointwise convergence in r1}) whenever 
			\[
			s>s(\delta)=\begin{cases}
				\frac{1}{2}-\alpha +2\delta   \quad  &0  <\delta< \frac{\alpha}{2}, \\ 
				\frac{\delta}{\alpha}  \quad   &  \delta\geq\frac{\alpha}{2}.  \\
			\end{cases}
			\]
			Conversely, there exists a curve satisfying the previous assumption, while (\ref{pointwise convergence in r1}) fails whenever $s<s(\delta)$.
		\end{theorem}

		\begin{theorem}\label{theorem4}
			Let $\delta \in[0,\alpha)$. For any curve $\gamma(x,t): \mathbb{R} \times[-1,1] \rightarrow \mathbb{R}$ satisfying $\gamma(x,0)=x$ which is bilipschitz continuous in \( x \), and $\alpha$-Hölder continuous in \( t \) with \(  \frac{1}{4} < \alpha < \frac{1}{2}  \), we have (\ref{pointwise convergence in r1}) whenever
			\[
			s>s(\delta)=\begin{cases}
				\frac{1}{4} +\delta   \quad  &0 \leq \delta\leq \alpha-\frac{1}{4}, \\ 
				\frac{1}{2}-\alpha +2\delta   \quad  &\alpha-\frac{1}{4}  <\delta<\frac{\alpha}{2}, \\ 
				\frac{\delta}{\alpha}   \quad   &  \delta\geq \frac{\alpha}{2}.  \\
			\end{cases}
			\]
			Conversely, there exists a curve satisfying the previous assumption, while (\ref{pointwise convergence in r1}) fails whenever $s<s(\delta)$. \end{theorem}

		The following four graphs depict the relationship between the sharp convergence rate $\delta$ and the regularity $s$ of the Schrödinger operator along curves in four different scenarios: lipschitz continuous in \( t \) for $d\geq 1$, $\alpha$-Hölder continuous in \( t \) with \(  \frac{1}{2}\leq \alpha < 1\) for $d=1$, $\alpha$-Hölder continuous in \( t \) with \(  0 \leq \alpha \leq \frac{1}{4}  \)  for $d=1$ and $\alpha$-Hölder continuous in \( t \) with \(  \frac{1}{4} < \alpha < \frac{1}{2}  \) for $d=1$. More precise, if the pair $(s,\delta)$  is located in the area to the right of the line, endpoint not included, we can get	 (\ref{pointwise convergence in rn}).
