		\section{Convergence rate of fractional Schrödinger operator along curves}\label{chap5}


		The previous method can also be applied to handle the convergence rate of fractional Schrödinger operator along curves in $d=1$. Here, we will only provide results. 



		\begin{theorem}\label{theorem5}
			Let $\delta \in[0,\alpha)$ and $m\in(0,1)$. For any curve $\gamma(x,t): \mathbb{R} \times[-1,1] \rightarrow \mathbb{R}$ satisfying $\gamma(x,0)=x$ which is bilipschitz continuous in \( x \), and $\alpha$-Hölder continuous in \( t \) with \(  \frac{1}{2}< \alpha \leq 1\), we have
			\begin{equation}\label{pt convergence in r1}
				\lim _{t \rightarrow 0} \frac{U_{\gamma}^m f(x, t)-f(x)}{t^\delta}=0 \quad \text { a.e. } x \in \mathbb{R},\quad \forall f \in H^{s}\left(\mathbb{R}\right)
			\end{equation}
			whenever 
			\[
			s>s(\delta)=\begin{cases}
				\frac{2-m}{4}   \quad  &0  \leq\delta\leq \frac{2\alpha-1}{4}, \\ 
				m\delta+\frac{1-m\alpha}{2}   \quad   &  \frac{2\alpha-1}{4}<\delta\leq \frac{\alpha}{2}.  \\
				\frac{\delta}{\alpha} \quad   &  \delta>\frac{\alpha}{2}.  \\
			\end{cases}
			\]
		\end{theorem}

		\begin{theorem}\label{theorem6}
			Let $\delta,m$ satisfy the assumptions in Theorem \ref{theorem5}.  For any curve $\gamma(x,t): \mathbb{R} \times[-1,1] \rightarrow \mathbb{R}$ satisfying $\gamma(x,0)=x$ which is bilipschitz continuous in \( x \), and $\alpha$-Hölder continuous in \( t \) with \(  0< \alpha \leq \frac{1}{2}\), we have (\ref{pt convergence in r1}) whenever
			\[
			s>s(\delta)=\begin{cases}
				m\delta+\frac{1-m\alpha}{2}    \quad  &0  \leq \delta\leq \frac{\alpha}{2}, \\ 
				\frac{\delta}{\alpha} \quad   &  \delta>\frac{\alpha}{2}.  \\
			\end{cases}
			\]. 
		\end{theorem}

		\begin{theorem}\label{theorem7}
			Let $\delta \in[0,\alpha)$ and $m\in(1,\infty )$. For any curve $\gamma(x,t): \mathbb{R} \times[-1,1] \rightarrow \mathbb{R}$ satisfying $\gamma(x,0)=x$ which is bilipschitz continuous in \( x \), and $\alpha$-Hölder continuous in \( t \) with \(  \frac{1}{m} \leq \alpha \leq 1  \), we have (\ref{pt convergence in r1}) whenever  
			\[
			s>s(\delta)=\begin{cases}
				(m-1)\delta+\frac{1}{4}    \quad  &0  \leq \delta\leq \frac{1}{4}, \\ 
				m\delta \quad   &  \delta>\frac{1}{4}.  \\
			\end{cases}
			\]. 
		\end{theorem}

		\begin{theorem}\label{theorem8}
			Let $\delta,m$ satisfy the assumptions in Theorem \ref{theorem7}.  For any curve $\gamma(x,t): \mathbb{R} \times[-1,1] \rightarrow \mathbb{R}$ satisfying $\gamma(x,0)=x$ which is bilipschitz continuous in \( x \), and $\alpha$-Hölder continuous in \( t \) with \( 0< \alpha \leq  \frac{1}{2m}   \), we have (\ref{pt convergence in r1}) whenever 
			\[
			s>s(\delta)=\begin{cases}
				m\delta+\frac{1-m\alpha}{2}    \quad  &0  \leq \delta\leq \frac{\alpha}{2}, \\ 
				\frac{\delta}{\delta} \quad   &  \delta>\frac{\alpha}{2}.  \\
			\end{cases}
			\]. 
		\end{theorem}

		\begin{theorem}\label{theorem9}
			Let $\delta,m$ satisfy the assumptions in Theorem \ref{theorem7}.  For any curve $\gamma(x,t): \mathbb{R} \times[-1,1] \rightarrow \mathbb{R}$ satisfying $\gamma(x,0)=x$ which is bilipschitz continuous in \( x \), and $\alpha$-Hölder continuous in \( t \) with \(  \frac{1}{2m} < \alpha <\min\left\{ \frac{1}{2},\frac{1}{m} \right\} \), we  have (\ref{pt convergence in r1}) whenever\[
			s>s(\delta)=\begin{cases}
				(m-1)\delta+\frac{1}{4}    \quad  &0  \leq \delta\leq \frac{2m\alpha-1}{4}, \\ 
				m\delta+\frac{1-m\alpha}{2}   \quad  &\frac{2m\alpha-1}{4}  <\delta\leq \frac{\alpha}{2}, \\ 
				\frac{\delta}{\alpha} \quad   &  \delta>\frac{\alpha}{2}.  \\
			\end{cases}
			\]. 
		\end{theorem}





		\begin{theorem}\label{theorem10}
			Let $\delta \in[0,\alpha)$ and $m\in(1,2 )$. For any curve $\gamma(x,t): \mathbb{R} \times[-1,1] \rightarrow \mathbb{R}$ satisfying $\gamma(x,0)=x$ which is bilipschitz continuous in \( x \), and $\alpha$-Hölder continuous in \( t \) with \(  \frac{1}{2} \leq \alpha < \frac{1}{m}  \), we have (\ref{pt convergence in r1}) whenever
			\[
			s>s(\delta)=\begin{cases}
				(m-1)\delta+\frac{1}{4}    \quad  &0  \leq \delta\leq \frac{1}{4}, \\ 
				\frac{m-1}{1-\alpha}\delta+\frac{1-m\alpha}{4(1-\alpha)}    \quad  & \frac{1}{4}  <\delta\leq \frac{2\alpha-1}{4}, \\ 
				m\delta+\frac{1-m\alpha}{2}   \quad  &\frac{2\alpha-1}{4}  <\delta\leq \frac{\alpha}{2}, \\ 
				\frac{\delta}{\alpha} \quad   &  \delta>\frac{\alpha}{2}.  \\
			\end{cases}
			\]. 
		\end{theorem}



