\section{Maximal number of connected components and a rationality criterion}
\label{sec:criterion}

In this section we discuss an invariant for real varieties, which encodes the maximal number of connected components in families and prove the main result of this paper. 

\subsection{The invariant $s_X$}
We recall that two smooth complex varieties $Y$ and $Z$ are {\it deformation equivalent}, denoted $Y\overset{\defo}{\sim} Z$ if there exists a finite chain $Y=Y_0,Y_1,\dots,Y_r=Z$ 
 of smooth complex varieties such that $Y_i$ and $Y_{i-1}$ are complex isomorphic to fibers of a smooth morphism over a smooth curve. 
 Note that if $Y\overset{\defo}{\sim} Z$, then $Y(\C)$ and $Z(\C)$ are $\mathcal{C}^\infty$-diffeomorphic, by Ehresmann's theorem.

\begin{definition}\label{def:sx}
Let  $X$ be a smooth real projective variety. Then one defines
$$
s_X:=\max\{\#\pi_0(X'(\R))\,| \,  \,X'_\C\overset{\defo}{\sim} X_\C\}.$$
\end{definition}


Note that $s_X$ is well-defined for any real projective variety by Smith-Thom inequality~\eqref{eq.smiththom}. Note that $s_X$ is in general hard to determine and known only in few cases. Here are some examples.

\begin{examples} 
\label{example:sx}
\begin{enumerate}
\item Let $X,X'$ be real smooth projective curves, then $X'_\C\overset{\defo}{\sim} X_\C$ if and only if they have the same genus $g$. Moreover $s_X=g+1$ by Harnack's Theorem.

\item 
\label{item:dp}
Let $S_d$ be a del Pezzo surface of degree $d$, then $s_{S_1}=5$, $s_{S_2}=4$, $s_{S_3}=s_{S_4}=2$, for $5\leq d \leq 9$, $s_{S_d}=1$, see \cite[Chapter 4]{M20}.
    \item 
Let $X\subset\P^N$ and $X'\subset\P^N$ be real smooth hypersurfaces of the same degree, then $X'_\C\overset{\defo}{\sim} X_\C$. 
\item Let $X_d\subset \mathbb{P}^3$ be a degree-$d$ real smooth surface, then $s_{X_1}=s_{X_2}=1$, $s_{X_3}=2$, $s_{X_4}=10$, but $s_{X_5}$ is not known.
\item Let $N$ be an odd integer, and $X=\P^N$. There exists a unique non-trivial Severi-Brauer variety $X'$, and by definition $X'_\C\overset{\defo}{\sim} X_\C$.
\item Let $X=\P^1\times \P^1$ and $X'=\P^1\times C$ be the product of $\P^1$ with a pointless conic $C$, then $X'$ does not admit a real quadric model in $\P^3$ but $X'_\C\overset{\defo}{\sim} X_\C$.
\item Let $X$, $X'$ be real smooth Fano threefolds such that $X_\C$ and $X'_\C$ belong to the same family then $X'_\C\overset{\defo}{\sim} X_\C$.
\end{enumerate}
\end{examples}

We stress that the number $s_X$ is not a birational invariant (see Remark~\ref{bir_inv}).
Moreover, in what follows, we will always assume that $\xr\ne\varnothing$. For the classification of families containing a member $X$ such that $X(\R)=\varnothing$, see \cite[Proposition~B]{ackm3}.


\subsection{A rationality criterion}

We state now the main result of this paper.

\begin{theorem}
\label{thm_newmain}
Let $X$ be a smooth geometrically rational real Fano threefold  with $\xr\ne\varnothing$.
If $s_X=1$, 
then $X$ is rational.
\end{theorem}




We introduce the following notation.
\begin{definition}
\label{dfn.smn}
Let $X$ be a geometrically rational smooth real Fano threefold  belonging to family \textnumero $m.n$. Then one denotes $s_{m.n}:=s_X.$
\end{definition}


Our strategy consists in going through all families of (sometimes conjecturally) rational complex Fano threefolds and proving that either $s_{m.n}>1$ or the implication $[\xr\ne\varnothing\implies X\ \text{is rational}]$ holds for every real form of a variety belonging to family \textnumero $m.n$.

\begin{lemma}
\label{lem_dp}
Let $X$ be a smooth real Fano threefold such that
$X_\mathbb{C}\cong\mathbb{P}^1\times S_d$ where $S_d$ is a smooth del Pezzo surface of degree $d$ $(S_8=\F_1$ or $S_8=\P^1\times\P^1)$. Then
\begin{enumerate}
\item 
$X$ is rational if and only if its real locus is nonempty and connected. 
\item
 Let $s_d$ be the maximal number of connected components of the real locus of a smooth real del Pezzo surface of degree $d$. If $X$ belongs to family \textnumero $m.n$, then $s_{m.n}=s_{11-m}$.
\end{enumerate}
\end{lemma}

\proof
As $X_\C$ is the product of a curve and a surface, $X$ is as well a product, hence $X\cong U\times V$ where $U$ is a real form of $\P^1$ and $V$ is a real form of a del Pezzo surface 
of degree $10-m$ where $m=\rho(X_\C)$. Then $X$ is rational if and only if $U=\P^1$ and $V$ is rational. By Comessatti's Theorem,
we get that $X$  is rational if and only if $V(\R)$ is connected if and only if $X(\R)$ is connected.
\endproof

\subsection{The proof of Theorem \ref{thm_newmain}}

In what follows, let $X$ be a geometrically rational smooth real Fano threefold. We will study families depending on the Picard rank.

\subsubsection{$\rho(X_\C)=1$}



\begin{proposition}
\label{prop_m=1}
Let $X$ be a geometrically rational smooth real Fano threefold belonging to family \textnumero $1.n$. Assume that $\xr\ne\varnothing$. Then $X$ is rational and $s_{1.n}=1$, unless $n\in\{3,5,8,14\}$.
\end{proposition}
\proof
There are 17 families of smooth Fano threefolds with Picard number $1$.

For $n\in\{1,2,4,7,11,12,13\}$, no $X$ belonging to family \textnumero $1.n$ are geometrically rational.

For $n\in\{3,5\}$, the general member in family \textnumero $1.n$ is not geometrically rational and all members are conjecturally not geometrically rational. Any $X$ belonging to family \textnumero $1.n$, with $n\in\{6,8,9,10,14,15,16,17\}$,  is geometrically rational.

Let $X$ belonging to family \textnumero $1.n$ such that $\xr\ne\varnothing$. By Theorem~\ref{thm_KP} 
for $n\in\{6,10,15,16,17\}$ and by Corollary~\ref{cor:X18} for $n=9$, $X$ is rational.
\endproof



\begin{proposition}
\label{rang_1_more}
The following holds:
\begin{itemize}
\item $s_{1.3}\geqslant 2$;
\item $s_{1.5}\geqslant 10$;
\item $s_{1.8}\geqslant 3$ ;
\item $s_{1.14}=2$.
\end{itemize}
\end{proposition}

\proof
This is a consequence of Propositions~\ref{prop_1.3-5}, \ref{prop:X16} and \ref{proposition:Kra}.
\endproof

\subsubsection{$\rho(X_\C)=2$}

\begin{proposition}
\label{prop_m=2}
Let $X$ be a geometrically rational smooth real Fano threefold belonging to family \textnumero $2.n$. Assume that $\xr\ne\varnothing$. Then $X$ is rational and $s_{2.n}=1$, unless $n\in\{10,12,16,18\}$.
\end{proposition}
\proof
There are 36 families of smooth Fano threefolds with Picard number $2$.

For $n\in\{1,2,3,5,6,8,11\}$, no $X$ belonging to family \textnumero $2.n$ are geometrically rational. Any $X$ belonging to other family \textnumero $2.n$ is geometrically rational.
If $n\in\{4,7,9,13, 14,15,17,19,20,22,23,25,26,27,28,29,30,31,33,35\}$, $X_\C$ admits an extremal birational contraction $f\colon X_\C \to Y$, where $Y$ is $\P^3_\C$, the quadric $Q\subset \P^4_\C$, or the quintic $V_5\subset \P^6_\C$ (see \cite{MM86,MM03,Mat-erratum}). By \cite[Lemma~2.5]{ACKM24}, there exists a birational morphism $g\colon X \to W$, where $W$ is a real form of $Y$. Since $\xr\ne\varnothing$, we deduce that $W(\R)\ne\varnothing$, and therefore $W$ is rational over $\R$. We deduce the statement for these values of $n.$ 
\\Assume $n=21$: if $\rho(X)=1$, then $X$ is rational by Theorem~\ref{thm_KP}, if $\rho(X)=2$, then $X$ admits an extremal birational contraction onto a quadric $Q\subset \P^4_\C$ with $Q(\R)\ne\varnothing$. We conclude that $s_{2.21}=1$.
\\Assume $n\in\{24,34,36\}$: $X_\C$ has an extremal contraction that produces a $\P^1$-bundle $f\colon X_\C \to \P^2_\C$, while the second extremal ray corresponds to a conic bundle for $n=24$, a $\P^2$-bundle for $n=34$ and a divisorial contraction for $n=36$, respectively. This implies that the Galois action cannot exchange the two rays and, as a consequence, that $f$ descends to a $\P^1$-bundle structure over $\R$. We conclude that $X$ is rational and, therefore, $s_{2.n}=1$.
\\Assume $n=32$: if $\rho(X)=1$, then $X$ is rational by Theorem~\ref{thm_KP}, otherwise, it admits two $\P^1$-bundle structure over $\P^2$, hence $X$ is rational and $s_{2.32}=1$.
\endproof

We study now the remaining families with geometric Picard rank two.

\begin{proposition}\label{rang_2_more}
The following holds:
\begin{itemize}
\item[(i)] $s_{2.10}=2$;
\item[(ii)] $s_{2.12}\geq 2$;
\item[(iii)]$s_{2.16}\ge 2$;
\item[(iv)] $s_{2.18}= 3$.
\end{itemize}
\end{proposition}

\proof
Let $X$ be a geometrically rational smooth real Fano threefold belonging to family \textnumero 2.10. By \cite{MM86,MM03,Mat-erratum} and \cite[Lemma~2.5]{ACKM24}, there exists a birational morphism $f\colon X \to Y$, where $Y$ is a real form of a quartic $V_4$ and  $f$ is the blow-up of a genus-one curve, intersection of two hyperplanes. This implies that $s_{2.10}\le 2$. To show the equality, let $Y'$ be a real form of a quartic $V_4$ such that $Y'(\R)$ has two connected components. Now take two general rational points on the two connected components and intersect $Y'$ with two hyperplanes passing through those rational points: this produces a genus-one curve $C'$ in $Y'$ and let $X'$ be the blow up of $Y'$ along $C'$. By construction, $X'(\R)$ has two connected components. This shows that $s_{2.10}=2$.
\\The estimate on $s_{2.12}$ is a consequence of Proposition~\ref{prop:X33}. 
\\We produce now an example in family \textnumero 2.16 with two connected components. Let $Q_1, Q_2\subset\P^5$ be the quadric threefolds given by the equations 
$$x_1^2+x_2^2+x_3^2+x_4^2+x_5^2-x_0^2=0$$
$$\alpha^2(x_1^2+x_2^2+x_3^2+x_4^2)+\beta^2x_5^2-x_0^2=0$$ 
where $1<\alpha$ and $0<\beta<1$. Let $Y=Q_1\cap Q_2$ be their intersection. For general $\alpha$ and $\beta$ the threefold $Y$ is smooth. By construction, $Y$ belongs to family \textnumero 1.14. Moreover, all real points are contained in the affine chart $x_0\neq 0$, where the equations become
\begin{gather*}
x_5^2=1-(x_1^2+x_2^2+x_3^2+x_4^2)\\
\beta^2x_5^2= 1-\alpha^2(x_1^2+x_2^2+x_3^2+x_4^2)
\end{gather*}
One checks that the hyperplane section $\{x_5=0\}\cap Y$ has no real point, since $1<\alpha$, while each half-space $\{\pm x_5>0\}\cap Y$ contains real points. Hence $Y(\R)$ has two connected components. Moreover, the following holds:
\begin{enumerate}
\item $Y$ is contained in the quadric given by $x_5^2=\frac{\alpha^2-1}{\alpha^2-\beta^2}x_0^2$;
\item Let $P$ be the plane given by $\left\{x_1=x_2=0,\ x_5=\sqrt{\frac{\alpha^2-1}{\alpha^2-\beta^2}}x_0\right\}$. 
The curve $Y\cap P$ is a smooth real conic $C$.
\end{enumerate}
Let $X$ be the blow up of $Y$ along $C$, then $X$ is a real smooth Fano threefold belonging to family \textnumero 2.16 and $X(\R)$ has two connected components. This implies $s_{2.16}\ge 2$.
\\The family \textnumero 2.18 was extensively studied in \cite{FJSVV24} and \cite{JJ23}. The construction given in \cite[Example 4.6]{JJ23} implies that $s_{2.18}\ge 3$. One can adapt the argument in \cite[Lemma 2.7]{JJ23} to deduce that, even when the discriminant of the conic bundle is not smooth, the bound 
 $s_{2.18}\le 3$ holds true. We conclude that $s_{2.18}= 3$.
\endproof


\begin{remark}\label{bir_inv}
The previous proposition shows that $s_X$ is not a birational invariant. If $X$ belongs to family \textnumero 1.14, then $s_X=2$. If $Y$ is the blowup of $X$ in an elliptic curve which is an intersection of 2 hyperplanes, i.e. $Y$ belongs to familly \textnumero 2.10, then $s_Y=2$. 
But if $Y'$ is the blowup of $X$ in a line, i.e. $Y'$ belongs to familly \textnumero 2.19, then $s_{Y'}=1$.
Indeed $X$ is rational if and only if it contains a real line by Theorem~\ref{thm_KP}. 
\end{remark}


\subsubsection{$\rho(X_\C)=3$}

\begin{proposition}
\label{prop_m=3}
Let $X$ be a geometrically rational smooth real Fano threefold belonging to family \textnumero $3.n$. Assume that $\xr\ne\varnothing$. Then $X$ is rational and $s_{3.n}=1$, unless $n\in\{2,3,4\}$.
\end{proposition}
\proof
There are 31 families of smooth Fano threefolds with Picard number $3$.
No $X$ belonging to family \textnumero 3.1 are geometrically rational. Any $X$ belonging to other family \textnumero $3.n$ is geometrically rational.
The strategy consists in checking for all families the type of extremal contractions of $X_\C$, studied in \cite{MM86,MM03,Mat-erratum}. See also \cite{ACKM24} for details on the geometry of the extremal contractions.
\begin{itemize}
\item[{Family \textnumero 3.5}.] $X_\C$ admits exactly three extremal divisorial contractions $f_i\colon X_\C \to Y_i$, where $Y_1\simeq\P^1\times \P^2$, while $Y_2$ and $Y_3$ are not Fano, see \cite[\S~III.3, p.~74]{Mat95}. The Galois action fixes $f_1$, which descends to $g_1\colon X \to W_1$. Since $\xr\ne\varnothing$, we deduce that $W(\R)\ne\varnothing$, and therefore $W$ is rational over $\R$. This implies that $X$ is rational.
\item[{Family \textnumero 3.6}.] $X_\C$ admits exactly two extremal divisorial contractions $f_i\colon X_\C \to Y_i$, where $Y_1$ belongs to family 2.25 and $Y_2$ belongs to family 2.33, see \cite[\S~III.3, p.~75]{Mat95}. Since they cannot be exchanged by the Galois action, they descend to $g_i\colon X \to W_i$, where $W_i$, $i=1,2$, are rational by Proposition~\ref{prop_m=2}. This implies that $X$ is rational.
\item[{Family \textnumero 3.7}.] $X_\C$ admits exactly three extremal divisorial contractions $f_i\colon X_\C \to Y_i$, where $Y_1\simeq Y_2 \simeq \P^1\times \P^2$ and $Y_3$ belongs to family 2.32, see \cite[\S~III.3, p.~76]{Mat95}. The Galois action fixes $f_3$, which descends to $g_3\colon X \to W_3$, where $W_3$ is rational by Proposition~\ref{prop_m=2}. This implies that $X$ is rational.
\item[{Family \textnumero 3.8}.] $X_\C$ admits exactly two extremal divisorial contractions $f_i\colon X_\C \to Y_i$, where $Y_1\simeq \P^1\times \P^2$ and $Y_2$ belongs to family 2.24, see \cite[\S~III.3, p.~77]{Mat95}. Since they cannot be exchanged by the Galois action, they descend to $g_i\colon X \to W_i$, where $W_i$, $i=1,2$, are rational by Proposition~\ref{prop_m=2}. This implies that $X$ is rational.
\item[{Family \textnumero 3.9}.] $X_\C$ is isomorphic to the blow-up of the cone over the Veronese of $\P^2$ in $\P^5$ with center the disjoint union of the vertex and a quartic curve on $\P^2$ and admits exactly two extremal divisorial contractions of the form $f_i\colon X_\C \to Y$, $i=1,2$, where $Y$ is the blow-up of the Veronese cone in a quartic curve, see \cite[\S~III.3, p.~79]{Mat95}. If those two contractions are fixed by the Galois action, they descend to $\R$ and induce birational morphisms $h_i\colon X \to W$, where $W$ is the Veronese cone over $\R$ (here the relative Picard rank for $h_1$ is 2). This implies that $X$ is rational. 
\\If these two extremal contractions $f_1$ and $f_2$ are exchanged by the Galois action. Then we still obtain a birational morphism $g\colon X \to W$ over $\R$, where $W$ is the Veronese cone over $\R$ (in this second case, the relative Picard rank for $g$ is 1). As before, we conclude that $X$ is rational.
\item[{Family \textnumero 3.10}.] $X_\C$ is isomorphic to the blow-up of the quadric $Q\subset \P^4_\C$ in two disjoint conics and admits exactly two extremal divisorial contractions of the form $f_i\colon X_\C \to Y$, $i=1,2$, where $Y$ is the blow-up of the quadric $Q$ in one conic, see \cite[\S~III.3, p.~80]{Mat95}. If those two contractions are fixed by the Galois action, they descend to $\R$ and induce birational morphisms $h_i\colon X \to W$, where $W$ is a quadric threefold over $\R$ (here the relative Picard rank for $h_1$ is 2). Since $\xr\ne\varnothing$, we deduce that $W(\R)\ne\varnothing$, and therefore $W$ is rational over $\R$. This implies that $X$ is rational. 
\\Assume now that these two extremal contractions $f_1$ and $f_2$ are exchanged by the Galois action. Then we still obtain a birational morphism $g\colon X \to W$ over $\R$, where $W$ is a quadric threefold over $\R$ (in this second case, the relative Picard rank for $g$ is 1). As before, we conclude that $X$ is rational.
\item[{Family \textnumero 3.11}.] $X_\C$ admits exactly three extremal divisorial contractions $f_i\colon X_\C \to Y_i$, where $Y_1$, $Y_2$ and $Y_3$ belong to the families \textnumero 2.25, \textnumero 2.34 and \textnumero 2.35, respectively, see \cite[\S~III.3, p.~81]{Mat95}. This implies that the Galois action fixes all of them, which, as a consequence, descend to $g_i\colon X \to W_i$ over $\R$, where $W_i$ are rational by Proposition~\ref{prop_m=2}. This implies that $X$ is rational.
\item[{Family \textnumero 3.12}.] $X_\C$ admits exactly three extremal divisorial contractions $f_i\colon X_\C \to Y_i$, where $Y_1$, $Y_2$ and $Y_3$ belong to the families \textnumero 2.27, \textnumero 2.33 and \textnumero 2.34, respectively, see \cite[\S~III.3, p.~83]{Mat95}. This implies that the Galois action fixes all of them, which, as a consequence, descend to $g_i\colon X \to W_i$ over $\R$, where $W_i$ are rational by Proposition~\ref{prop_m=2}. This implies that $X$ is rational.
\item[{Family \textnumero 3.13}.] $X_\C$ admits exactly three extremal divisorial contractions $f_i\colon X_\C \to Y$, where $Y$ belongs to the family \textnumero 2.32, see \cite[\S~III.3, p.~84]{Mat95}. Since the Galois group has order two, there exists at least one contraction which is fixed by it, which descends to $g\colon X \to W$ over $\R$, where $W$ is rational by Proposition~\ref{prop_m=2}. Hence $X$ is rational.
\item[{Family \textnumero 3.14}.] $X_\C$ is isomorphic to the blow-up of $\P^3$ in the disjoint union of a plane cubic curve and a point outside the plane and it admits exactly four extremal divisorial contractions, see \cite[\S~III.3, p.~85]{Mat95}. Three of them are of the form $f_i\colon X_\C \to Y_i$, where $Y_1\simeq \P_{\P^2}(\O\oplus \O(1))$, $Y_2\simeq \P_{\P^2}(\O\oplus \O(2))$ and $Y_3$ is the blow-up of $\P^3$ in a plane cubic curve, while the last morphism contracts a divisor to a singular variety. This implies that the Galois action fixes all of them, so they descend to $g_i\colon X \to W_i$ over $\R$, $i=1,2$, where $W_i$ are rational by Proposition~\ref{prop_m=2}. Hence $X$ is rational.
\item[{Family \textnumero 3.15}.] $X_\C$ admits exactly three extremal divisorial contractions $f_i\colon X_\C \to Y_i$, where $Y_1$, $Y_2$ and $Y_3$ belong to the families \textnumero 2.29, \textnumero 2.31 and \textnumero 2.34, respectively, see \cite[\S~III.3, p.~87]{Mat95}. This implies that the Galois action fixes all of them, which, as a consequence, descend to $g_i\colon X \to W_i$ over $\R$, where $W_i$ are rational by Proposition~\ref{prop_m=2}. This implies that $X$ is rational.
\item[{Family \textnumero 3.16}.] $X_\C$ admits exactly three extremal divisorial contractions $f_i\colon X_\C \to Y_i$, where $Y_1$, $Y_2$ and $Y_3$ belong to the families \textnumero 2.27, \textnumero 2.32 and \textnumero 2.35, respectively, see \cite[\S~III.3, p.~88]{Mat95}. This implies that the Galois action fixes all of them, which, as a consequence, descend to $g_i\colon X \to W_i$ over $\R$, where $W_i$ are rational by Proposition~\ref{prop_m=2}. This implies that $X$ is rational.
\item[{Family \textnumero 3.17}.] $X_\C$ admits a $\P^1$-bundle structure $f\colon X_\C \to \P^1\times\P^1$, see \cite[\S~III.3, p.~89]{Mat95}, \cite[Lemma~6.5.1]{BFT23}. This $\P^1$-bundle structure is unique, so it descends to $g\colon X \to W$ over $\R$, where $W$ is a real form of $\P^1\times \P^1$. Since $\xr\ne\varnothing$, we deduce that $W(\R)\ne\varnothing$, and therefore $W$ is rational over $\R$. This implies that $X$ is rational.
\item[{Family \textnumero 3.18}.] $X_\C$ admits exactly three extremal divisorial contractions $f_i\colon X_\C \to Y_i$, where $Y_1$, $Y_2$ and $Y_3$ belong to the families \textnumero 2.29, \textnumero 2.30 and \textnumero 2.33, respectively, see \cite[\S~III.3, p.~90]{Mat95}. This implies that the Galois action fixes all of them, which, as a consequence, descend to $g_i\colon X \to W_i$ over $\R$, where $W_i$ are rational by Proposition~\ref{prop_m=2}. This implies that $X$ is rational.
\item[{Family \textnumero 3.19}.] $X_\C$ is isomorphic to the blow-up of the quadric $Q\subset \P^4_\C$ in two non-colinear points and admits exactly four extremal divisorial contractions. Two of them are of the form $f_i\colon X_\C \to Y$, $i=1,2$, where $Y$ is the blow-up of the quadric $Q$ in one point, see \cite[\S~III.3, p.~91-p.~92]{Mat95}. If those two contractions are fixed by the Galois action, they descend to $\R$ and induce birational morphisms $h_i\colon X \to W$, where $W$ is a quadric threefold over $\R$ (here the relative Picard rank for $h_1$ is 2). Since $\xr\ne\varnothing$, we deduce that $W(\R)\ne\varnothing$, and therefore $W$ is rational over $\R$. This implies that $X$ is rational. 
\\Assume now that these two extremal contractions $f_1$ and $f_2$ are exchanged by the Galois action. Then we still obtain a birational morphism $g\colon X \to W$ over $\R$, where $W$ is a quadric threefold over $\R$ (in this second case, the relative Picard rank for $g$ is 1). As before, we conclude that $X$ is rational. 
\item[{Family \textnumero 3.20}.] $X_\C$ admits exactly three extremal divisorial contractions $f_i\colon X_\C \to Y_i$, where $Y_1$ and $Y_2$ belong to the family \textnumero 2.31 and $Y_3$ belongs to the family \textnumero 2.32, see \cite[\S~III.3, p.~93]{Mat95}. This implies that the Galois action fixes the third one, which, as a consequence, descends to $g_3\colon X \to W_3$ over $\R$, where $W_3$ is rational by Proposition~\ref{prop_m=2}. This implies that $X$ is rational.
\item[{Family \textnumero 3.21}.] $X_\C$ admits a unique extremal divisorial contraction $f\colon X_\C \to \P^1\times \P^2$, see \cite[\S~III.3, p.~94]{Mat95}, so it descends to $g\colon X \to \P^1\times \P^2$ over $\R$. This implies that $X$ is rational.
\item[{Family \textnumero 3.22}.] $X_\C$ admits exactly two extremal divisorial contractions $f_i\colon X_\C \to Y_i$, where $Y_1\simeq \P^1\times \P^2$ and $Y_2\simeq \P_{\P^2}(\O\oplus \O(2))$, see \cite[\S~III.3, p.~96]{Mat95}. Since they cannot be exchanged by the Galois action, they descend to $g_i\colon X \to W_i$, where $W_i$, $i=1,2$, are rational by Proposition~\ref{prop_m=2}. This implies that $X$ is rational.
\item[{Family \textnumero 3.23}.] $X_\C$ admits exactly three extremal divisorial contractions $f_i\colon X_\C \to Y_i$, where $Y_1\simeq \P_{\P^2}(\O\oplus \O(1))$, $Y_2$ belongs to the family \textnumero 2.30 and $Y_2$ belongs to family \textnumero 2.31, see \cite[\S~III.3, p.~97]{Mat95}. Since they cannot be exchanged by the Galois action, they descend to $g_i\colon X \to W_i$  over $\R$, where $W_i$, $i=1,2,3$, are rational by Proposition~\ref{prop_m=2}. This implies that $X$ is rational.
\item[{Family \textnumero 3.24}.] $X_\C$ admits exactly two extremal divisorial contractions $f_i\colon X_\C \to Y_i$, where $Y_1\simeq \P^1\times \P^2$ and $Y_2$ belongs to the family \textnumero 2.32, see \cite[\S~III.3, p.~98]{Mat95}. Since they cannot be exchanged by the Galois action, they descend to $g_i\colon X \to W_i$ over $\R$, where $W_i$, $i=1,2$, are rational by Proposition~\ref{prop_m=2}. This implies that $X$ is rational.
\item[{Family \textnumero 3.25}.] $X_\C$ admits a $\P^1$-bundle structure $f\colon X_\C \to \P^1\times\P^1$, see \cite[\S~III.3, p.~99]{Mat95}, \cite[Lemma~6.5.1]{BFT23}. This $\P^1$-bundle structure is unique, so it descends to $g\colon X \to W$ over $\R$, where $W$ is a real form of $\P^1\times \P^1$. Since $\xr\ne\varnothing$, we deduce that $W(\R)\ne\varnothing$, and therefore $W$ is rational over $\R$. This implies that $X$ is rational.
\item[{Family \textnumero 3.26}.] $X_\C$ admits exactly three extremal divisorial contractions $f_i\colon X_\C \to Y_i$, where $Y_1\simeq \P^1\times \P^2$, $Y_2\simeq \P_{\P^2}(\O\oplus \O(1))$, and $Y_3$ is the blow-up of $\P^3$ at a line, see \cite[\S~III.3, p.~100]{Mat95}. Since they cannot be permuted by the Galois action, they descend to $g_i\colon X \to W_i$ over $\R$, where $W_i$, $i=1,2,3$, are rational by Proposition~\ref{prop_m=2}. This implies that $X$ is rational.
\item[{Family \textnumero 3.27}.] $X_\mathbb{C}=\P^1\times\P^1\times\P^1$. By Lemma~\ref{lem_dp}, $X$ is rational. 
\item[{Family \textnumero 3.28}.] $X_\mathbb{C}=\mathbb{P}^1\times \F_1$.
By Lemma~\ref{lem_dp}, $X$ is rational.
\item[{Family \textnumero 3.29}.] $X_\C$ admits exactly two extremal divisorial contractions $f_i\colon X_\C \to Y_i$, where $Y_1\simeq \P_{\P^2}(\O\oplus \O(1))$ and $Y_2\simeq \P_{\P^2}(\O\oplus \O(2))$, see \cite[\S~III.3, p.~45]{Mat95}. Since they cannot be exchanged by the Galois action, they descend to $g_i\colon X \to W_i$, where $W_i$, $i=1,2$, are rational by Proposition~\ref{prop_m=2}. This implies that $X$ is rational.
\item[{Family \textnumero 3.30}.] $X_\C$ admits a $\P^1$-bundle structure $f\colon X_\C \to \F_1$, see \cite[\S~III.3, p.~103]{Mat95}, \cite[Lemma~6.5.1]{BFT23}. This $\P^1$-bundle structure is unique, so it descends to $g\colon X \to \F_1$ over $\R$ and therefore $X$ is rational.
\item[{Family \textnumero 3.31}.] $X_\C$ admits a $\P^1$-bundle structure $f\colon X_\C \to \P^1\times \P^1$, see \cite[\S~III.3, p.~104]{Mat95}, \cite[Lemma~6.5.1]{BFT23}. This $\P^1$-bundle structure is unique, so it descends to $g\colon X \to W$, where $W$ is a real form of $\P^1\times \P^1$. Since $\xr\ne\varnothing$, we deduce that $W(\R)\ne\varnothing$, and therefore $W$ is rational over $\R$. This implies that $X$ is rational.
\end{itemize}
\endproof



We now study the remaining families with geometric Picard rank three.

\begin{proposition}\label{rang_3_more}
The following holds:
\begin{itemize}
\item[(i)] $s_{3.2}\ge 3$;
\item[(ii)] $s_{3.3}\ge 4$;
\item[(iii)] $s_{3.4}= 3$.
\end{itemize}
\end{proposition}
\proof\begin{itemize}
\item[{Family \textnumero 3.2}.] $X_\C$ is a divisor from $|\mathcal{L}^{\otimes 2}\otimes \mathcal{O}(2,3)|$ on the $\P^2$-bundle $\P(\mathcal{O} \oplus \mathcal{O}(-1,-1)^{\oplus 2})$ over $\P^1\times \P^1$ such that $X_\C\cap Y$ is irreducible, $\mathcal{L}$ is the tautological bundle, and $Y\in |\mathcal{L}|$. 
As explained in \cite[\S~III.3, p.~70-p.~71]{Mat95} and in \cite[Section~5.11]{Chelbook23}, \cite[Lemma 5.11]{ACKM24}, $X_\C$ admits a divisorial contraction onto a non-$\Q$-factorial Fano threefold with one isolated ordinary double point of degree 16: this is precisely the family of threefolds appearing in the proof of Proposition~\ref{prop:X16}. The same proof implies that $s_{3.2}\ge 3$.
\item[{Family \textnumero 3.3}.] $X_\C$ is a divisor on $\P^1\times \P^1 \times \P^2$ of tridegree $(1,1,2)$. Consider the equations
$$x_3\left(-y_0^2-\frac{1}2y_1^2+y_2^2\right)+x_2\left(\frac{1}2y_0^2+y_1^2-y_2^2\right)+\left(x_0+\frac{1}2x_2\right)y_2^2=0$$
$$x_0^2+x_1^2+x_2x_3=0$$
in $\P^3\times \P^2$ with coordinates $([x_0:x_1:x_2:x_3],[y_0:y_1:y_2])$. This defines a (geometrically non-)standard conic bundle over $\P^2$, with discriminant of degree 4, defined by $\left(-y_0^2-\frac{1}2y_1^2+y_2^2\right)\left(\frac{1}2y_0^2+y_1^2-y_2^2\right)-y_2^4=0$. One can check that this curve has four connected components and the corresponding threefold verifies $\#\pi_0(X(\R))=4$. This implies that $s_{3.3}\ge 4$.
\item[{Family \textnumero 3.4}.] $X_\C$ is the blow-up of a theefold $Y$ belonging to family 2.18 in a smooth fiber of the conic bundle structure over $\P^2$. By \cite[\S~III.3, p.~72-p.~73]{Mat95}, the divisorial contraction to $Y$ descends over $\R$, so it is enough to consider a real form in family 2.18 with three connected components, which exists by Proposition~\ref{rang_2_more} and blow up a smooth fiber with nonempty real locus of the conic bundle structure over $\P^2$. This shows that $s_{3.4}= 3$.
\end{itemize}
\endproof


\subsubsection{$\rho(X_\C)=4,5,6$}
\begin{proposition}
\label{prop_m=456}
Let $X$ be a smooth real Fano threefold 
such that $\rho(X_\C)=4,5,6$. Assume $X$ does not belong to family \textnumero 4.1 and $\xr\ne\varnothing$, then $X$ is rational and then $s_X=1$.
\end{proposition}

\proof
First assume that $\rho(X_\C)=4$. There are 13 families of smooth complex Fano threefolds with Picard number~$4$ and any $X$ belonging to any family \textnumero $4.n$ is geometrically rational. We leave aside $n=1$.

If $n\in\{3,4,5,6,8,9,11,12,13\}$, $X_\C$ admits, among its extremal divisorial contractions, a special one $f\colon X_\C \to Y$, where $Y$ is $\P^3$, the quadric $Q\subset \P^4$, the product $\P^1\times\P^1\times\P^1$, 
the blow up of $\P^3$ in two points, the product $\P^1\times\F_1$ 
or the blow up of $Q$ in two non-colinear points. 
From the description of the Mori cone $\overline{\mathrm{NE}}(X_\C)$ given in \cite[\S~III.3, p.106-p.123]{Mat95} and \cite[Section~4]{Mat-erratum}, we deduce that, for every such family, this special contraction descends to a birational morphism $g\colon X \to W$, where $W$ is a real form of $Y$ (the strategy is the same as for the previous results in lower rank). Since $\xr\ne\varnothing$, we have $W(\R)\ne\varnothing$, and therefore $W$ is rational over $\R$ by Proposition~\ref{prop_m=3}, hence $X$ is rational. 


If $n=2$, the description of the Mori cone $\overline{\mathrm{NE}}(X_\C)$ given in \cite[\S~III.3, p.107-p.109]{Mat95} shows that $X_\C$ admits two extremal birational contractions $f\colon X_\C \to Y$, where $Y$ belongs to family \textnumero 3.31. Looking at the intersection numebers of the corresponding extremal rays $l_1$ and $l_2$ in the table at \cite[p.108]{Mat95}, we see that the Galois action cannot exchange them. 
Thus $X$ admits an extremal birational contraction $f\colon X \to Y$, defined over $\R$, where $Y$ belongs to family \textnumero 3.31. Since $\xr\ne\varnothing$, we have $Y(\R)\ne\varnothing$, and therefore $Y$ is rational over $\R$ by Proposition~\ref{prop_m=3}.

If $n=7$, the description of the Mori cone $\overline{\mathrm{NE}}(X_\C)$ given in \cite[\S~III.3, p.116-p.117]{Mat95} shows that $X$ admits a real birational map $f\colon X \to Y$, where $Y$ belongs to family \textnumero 2.32. Since $\xr\ne\varnothing$, we have $Y(\R)\ne\varnothing$, and therefore $Y$ is rational over $\R$ by Proposition~\ref{prop_m=2}. 

If $n=10$, then $X_\mathbb{C}=\mathbb{P}^1\times S_7$.
By Lemma~\ref{lem_dp}, $X$ is rational.

\medskip
Now assume $\rho(X_\C)=5$ or $6$.
There are 4 families of smooth complex Fano threefolds with Picard number $5$ or $6$ and any $X$ belonging to one of these families is geometrically rational.
Assume that $X_\C$ belongs to family \textnumero 5.1, then it admits three extremal birational contractions $f\colon X_\C \to Y$, where $Y$ belongs to family \textnumero 4.12.
We deduce from the description of the Mori cone $\overline{\mathrm{NE}}(X_\C)$ given in \cite[\S~III.3, p.124-p.125]{Mat95} that at least one of them is defined over $\R$. Since $\xr\ne\varnothing$, then $Y(\R)\ne\varnothing$, thus $Y$ is rational over $\R$ by the previous part of the proof.

Assume that $X_\C$ belongs to family \textnumero 5.2, then, among its extremal birational contractions, $X_\C$ admits a unique one $f\colon X_\C \to Y$, whose target space $Y$ belongs to family \textnumero 4.12 (see the description of the Mori cone $\overline{\mathrm{NE}}(X_\C)$ given in \cite[\S~III.3, p.125-p.126]{Mat95}). We deduce 
that $f$ descends over $\R$. Since $\xr\ne\varnothing$, then $Y(\R)\ne\varnothing$, thus $Y$ is rational over $\R$ by the previous part of the proof. 

Assume that $X_\C$ belongs to family \textnumero 5.3 or \textnumero 6.1, then $X_\mathbb{C}=\mathbb{P}^1\times S_{11-m}$ and by Lemma~\ref{lem_dp}, $X$ is rational.
\endproof

\begin{proposition}
\label{rang_456_more}
The following holds: $s_{4.1}=2$.
\end{proposition}

\proof
By \cite[Example 4.3]{CTZ24-pre}, there exists a smooth real Fano threefold $X$ belonging to family \textnumero 4.1 whose real locus is disconnected, hence $s_{4.1}\geq2$. Conversely let $X$ be a smooth real Fano threefold belonging to family \textnumero 4.1. Then $X$ is a real form of a degree $(1,1,1,1)$ divisor in $\P^1\times\P^1\times\P^1\times\P^1$. In fact, any such form is a degree $(1,1,1,1)$ divisor in a real form $Y$ of $\P^1\times\P^1\times\P^1\times\P^1$. Exactly three of these forms have real points and $X$ can be non rational  iff $Y=Q\times Q$ where $Q$ is the smooth quadric surface whose real locus is a sphere. 
In this case, we have $\rho(X)=2$ and $\rho(X_\C)=4$ and by Proposition~\ref{prop.st.gm}, we get $s_{4.1}\leq 2$ taking into account that $h^{1,2}(X)=1$. 
\endproof

\subsubsection{$\rho(X_\C)\ge 7$}

\begin{proposition}
\label{proposition:78910}
Let $X$ be a smooth real Fano threefold such that $\rho(X_\C)\ge 7$, then $s_X>1$. More precisely, $s_{7.1}=s_{8.1}=2$, $s_{9.1}=4$, $s_{10.1}=5$.
\end{proposition}
\proof
There are 4 families of smooth complex Fano threefolds with Picard number $m\ge 7$ and if $X$ belongs to one of these families, $X_\mathbb{C}=\mathbb{P}^1\times S_{11-m}$ thus Lemma~\ref{lem_dp} applies and we get the result by Example~\ref{example:sx}\ref{item:dp}.
\endproof

\subsubsection{Final remarks}

\proof[Proof of Theorem~\ref{thm_newmain}]
It follows directly from Propositions~\ref{prop_m=1}, \ref{rang_1_more}, \ref{prop_m=2}, \ref{rang_2_more}, \ref{prop_m=3}, \ref{rang_3_more}, \ref{prop_m=456}, \ref{rang_456_more} and \ref{proposition:78910}.
\endproof

\begin{remark}
If $m >6$, we have shown above that $s_{m.n}>1$ but $X$ is rational if and only if its real locus is nonempty and connected by Lemma~\ref{lem_dp} and rational examples exist. Thus, the converse of Theorem~\ref{thm_newmain} is not true.
\end{remark}

\begin{remark}
We do not know whether, in Theorem~\ref{thm_newmain}, we can relax the Fano hypothesis. Indeed in \cite{BP24-pre} one can find a family of real conic bundles  
over rational surfaces
whose elements are irrational with connected real locus. 
Namely, let $U:=\{x^2+y^2=f(u,v)\}\subset \A^4$ where $f\in\R[u,v]$ is a polynomial of even degree $d\geq 12$ such that the closure $C$ of $\{f = 0\}$ in $\P^2$ is a nodal rational curve. Blowing up the nodes of the curve $C$, we get a rational surface $S$ and a real conic bundle $X\to S$ which is a smooth projective models of $U$. Then if the real locus $X(\R)$ is nonempty, it is connected but at the same time it is irrational by \cite[Theorem~4.5]{BP24-pre}.

To prove that the statement of Theorem~\ref{thm_newmain} holds true for this family of examples, one needs to provide a member $X$ of this family of conic bundles with non-trivial automorphism group and a twisted real form $Y$ of $X$ with non-connected real locus $Y(\R)$.
\end{remark}

\begin{question}
Let $n\ge 3$ be an integer and $X$ be a smooth geometrically rational real $n$-dimensional variety with $\xr\ne\varnothing$ and assume that $s_X=1$. Is $X$ rational?
\end{question}

The answer to the same question is positive for $n=1$ (trivial), and for $n=2$ by Comessatti's Theorem.

