&+2\tilde{\rm R}_{(0b)}\Big(t^{ab}t_{0a}-\tilde{\nabla}(t)_{a}{}^{ab}\Big)+\frac{1}{2}t^{ab}t_{ab}\tilde{\rm R}_{00}+\tilde{\nabla}(t)_{a}{}^{ba}\Big[\tilde{\nabla}(t)_{00b}+f_{0}{}^{c}t_{cb}+f_{ab}t_{0}{}^{a}\Big]+\nonumber\\
&+\tilde{\nabla}(t)_{b0}{}^{b}\bigg[\frac{1}{2}\tilde{\nabla}(t)_{a0}{}^{a}-t_{0}{}^{a}t_{0a}\bigg]+t^{ab}t_{0a}\tilde{\nabla}(t)_{00b}+\tilde{\nabla}(t)_{ab0}\Big[\tilde{\nabla}(t)^{(ab)0}+t_{0}{}^{a}t_{0}{}^{b}+2f^{c(a}t_{c}{}^{b)}\Big]+\nonumber\\
&-f_{0}{}^{a}t_{a}{}^{b}t_{b}{}^{c}t_{0c}-\frac{1}{2}f_{0}{}^{a}t^{bc}t_{bc}t_{0a}+\frac{3}{4}t_{0}{}^{a}t_{0a}t_{0}{}^{b}t_{0b}+\frac{5}{8}f^{ab}f_{a}{}^{c}t_{b}{}^{d}t_{cd}+\frac{3}{8}f^{ab}f^{cd}t_{ac}t_{bd}+\nonumber\\
&+2f^{ab}t_{a}{}^{c}t_{0b}t_{0c}+\frac{1}{2}f^{ab}t_{a}{}^{c}t_{c}{}^{d}z_{0(bd)}+\frac{1}{4}t^{ab}t_{ab}z_{0c}{}^{c}z_{0d}{}^{d}-t^{ab}t_{a}{}^{c}z_{0bc}z_{0d}{}^{d}+\frac{1}{8}t^{ab}t_{a}{}^{c}z_{0b}{}^{d}z_{0cd}+\nonumber\\
&+\frac{1}{4}t^{ab}t_{a}{}^{c}z_{0b}{}^{d}z_{0dc}+\frac{1}{8}t^{ab}t_{a}{}^{c}z_{0}{}^{d}{}_{b}z_{0cd}+\frac{1}{2}t^{ab}t^{cd}z_{0ac}z_{0(bd)}\,,\\
\nonumber\\
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\accentset{(0)}{\mathcal{L}}_{\gamma}=&\,  \frac{2}{3}\tilde{R}_{abcd}\bigg[2\tilde{R}^{a(bc)d}-f^{a(b}t^{c)d}+3f^{c(b}t^{d)a}+3t^{ac}z_{0}{}^{(bd)}+\frac{1}{2}t^{cb}z_{0}{}^{(ad)}+\frac{1}{2}t^{cd}z_{0}{}^{(ab)}\bigg]+\nonumber\\
&+\frac{2}{3}\tilde{R}_{ab0c}\Big[2\tilde{\nabla}(t)^{[ba]c}+2\tilde{\nabla}(t)^{cab}-t^{ab}t_{0}{}^{c}+t^{c[a}t_{0}{}^{b]}\Big]+\nonumber\\
&+\frac{2}{3}\tilde{R}_{a0bc}\Big[-2\tilde{\nabla}(t)^{(ab)c}+t^{b(c}t_{0}{}^{a)}\Big]-\tilde{R}_{b00c}t^{ab}t_{a}{}^{c}+\nonumber\\
&+\frac{2}{3}\tilde{\nabla}(t)^{abc}\Big[\tilde{\nabla}(m)_{(ab)c}-\tilde{\nabla}(z)_{0b(ac)}+\tilde{\nabla}(z)_{(ab)0c}-\tilde{\nabla}(z)_{b0(ac)}\Big]+\nonumber\\
&-\frac{2}{3}\tilde{\nabla}(t)_{0}{}^{ab}\Big[\tilde{\nabla}(t)_{0ab}+2\tilde{\nabla}(t)_{a0b}\Big]
+\frac{2}{3}\tilde{\nabla}(t)^{a}{}_{0}{}^{b}\Big[\tilde{\nabla}(t)_{a0b}+2\tilde{\nabla}(t)_{b0a}\Big]+\nonumber\\
&+\tilde{\nabla}(t)_{abc}\bigg[-4f_{0}{}^{(a}t^{b)c}+\frac{2}{3}t_{0}{}^{[a}z_{0}{}^{b]c}-\frac{2}{3}t_{0}{}^{b}z_{0}{}^{ca}+f^{db}z_{d}{}^{(ac)}-\frac{8}{3}f^{b(a}t_{0}{}^{c)}+z^{d(ab)}z_{0d}{}^{c}+z_{0}{}^{(c}{}_{d}z^{a)bd}\bigg]+\nonumber\\
&-2t_{0}{}^{a}t_{0}{}^{b}\tilde{\nabla}(t)_{a0b}+2t^{ab}t_{0a}\tilde{\nabla}(t)_{00b}-\frac{1}{3}t^{ab}t_{0}{}^{c}\tilde{\nabla}(m)_{(ac)b}+t^{ab}t_{a}{}^{c}\tilde{\nabla}(m)_{b0c}-t^{ab}t_{a}{}^{c}\tilde{\nabla}(z)_{00bc}+\nonumber\\
&+\frac{1}{3}t^{ab}t_{0}{}^{c}\Big[\tilde{\nabla}(z)_{a0cb}+\tilde{\nabla}(z)_{[c0]ab}+\tilde{\nabla}(z)_{(a0)bc}\Big]+\nonumber\\
&+\frac{3}{4}t_{0}{}^{a}t_{0a}t_{0}{}^{b}t_{0b}-\frac{4}{3}f^{ab}t_{0}{}^{c}t_{0(c}t_{b)a}+\frac{1}{12}f^{ab}t^{cd}(10f_{a(b}t_{c)d}+3t_{ab}f_{cd})+\nonumber\\
&+f^{ab}t_{a}{}^{c}\bigg[\frac{1}{2}z_{b(dc)}t_{0}{}^{d}+\frac{1}{2}t_{c}{}^{d}z_{0bd}+\frac{4}{3}t_{c}{}^{d}z_{0(bd)}\bigg]-f_{0}{}^{a}t^{bc}t_{b}{}^{d}z_{acd}+\frac{1}{3}t^{ab}t_{0}{}^{c}(t_{0a}z_{0bc}+t_{0(a|}z_{0|c)b})+\nonumber\\
&+\frac{2}{3}t^{ab}z_{0}{}^{cd}t_{ab}z_{0(cd)}
-\frac{2}{3}t^{ab}t_{a}{}^{c}z_{0b}{}^{d}z_{0dc}-\frac{13}{12}t^{ab}t_{a}{}^{c}z_{0b}{}^{d}z_{0cd}-\frac{7}{12}t^{ab}t_{a}{}^{c}z_{0}{}^{d}{}_{b}z_{0dc}+\nonumber\\
