\subsection{Quadratic Ricci Scalar Gravity}\label{sec:HigherOrderEOM}
\noindent We have shown that for the Gauss-Bonnet theory it is possible to get the Poisson equation by taking the limit of the equations of motion by deforming the model with the help of a scalar field. We now aim to further extend the analysis. We consider the quadratic Ricci scalar theory, $\mathcal{L}_{\CA}$, whose action we report here for convenience
\begin{align}
\mathcal{S}=&\,  \int\,d^{D}x\, \sqrt{-g} \bigg[\R-\frac{1}{4}F_{\mu\nu}F^{\mu\nu}+\CA \bigg(\R-\frac{1}{4}F_{\mu\nu}F^{\mu\nu}\bigg)^{2}\bigg]\,.
\end{align}
The relativistic equations of motion in this case are:
\begin{subequations}
\begin{align}
[A]^{\mu}:=&\,  \nabla_{\nu}\bigg[F^{\nu\mu}+2\alpha F^{\nu\mu}\bigg(\R-\frac{1}{4}F^{2}\bigg)\bigg]=0\,,\\
\nonumber\\
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
[G]_{\mu\nu}:=&\,  \Ric_{\mu\nu}-\frac{1}{2}g_{\mu\nu}\R-\frac{1}{2}F_{\mu\rho}F_{\nu}{}^{\rho}+\frac{1}{8}g_{\mu\nu}F^{2}+\nonumber\\
&+2\alpha \bigg(\R-\frac{1}{4}F^{2}\bigg)\bigg(\Ric_{\mu\nu}-\frac{1}{2}F_{\mu\rho}F_{\nu}{}^{\rho}\bigg)-2\alpha\nabla_{(\mu}\nabla_{\nu)}\bigg(\R-\frac{1}{4}F^{2}\bigg)+\nonumber\\
&+\alpha g_{\mu\nu}\bigg[-\frac{1}{2}\bigg(\R-\frac{1}{4}F^{2}\bigg)^{2}+2\nabla_{\rho}\nabla^{\rho}\bigg(\R-\frac{1}{4}F^{2}\bigg)\bigg]=0\,.
\end{align}
\end{subequations}
We consider the same combination \autoref{eq:PoissonCombination} of the two-derivative cases. Expanding we get:
\begin{subequations}
\begin{align}
\accentset{(2)}{[P]}=&\,  \frac{1}{4}(\PC-2\PB)t_{ab}t^{ab}\Big[1+4\Ct_{c0}{}^{c}+2\RicNR_{c}{}^{c}-3t_{0c}t_{0}{}^{c}-2f^{cd}t_{cd}\Big]\,,\\
\nonumber\\
\accentset{(0)}{[P]}=&\,  \frac{1}{2}(3\PA-D\PA+\PC)\RicNR_{a}{}^{a}+\frac{1}{2}(5\PA-D\PA+\PC)\alpha(\RicNR_{a}{}^{a})^2+\nonumber\\
&+2(D\PA-2\PA-\PC)h^{\mu\nu}\nablaNR_{\mu}\nablaNR_{\nu}\RicNR_{a}{}^{a}+...\,,\label{eq:PoissonRSquared}
\end{align}
\end{subequations}
where the dots denote terms proportional to $t_{\mu\nu}$. It is clear  that the order $\cc{2}$ is harmless because of the constraint 
$F_{\mu\nu}=0$, that shifts it to the order $\cc{-2}$.
However, from \autoref{eq:PoissonRSquared} we realize that, at order $\cc{0}$, we do not only get terms proportional to the intrinsic torsion, which can be eliminated using the constraint, but also terms insensitive to it. Just as in Gauss-Bonnet gravity, in this case it is not possible either to cancel all the contributions by choosing the constants $\PA$ and $\PC$ appropriately. To cancel the zero-order term in the expansion we can supplement the system with a further constraint,  
\begin{align}
\langle C \rangle :=\R^{2}+2\nabla_{\mu}\nabla^{\mu}\R=&\,  0\,,
\end{align}
and choose at the same time
\begin{align}
\PC=D\PA-3\PA\,.
\end{align}
In this way, we can make \autoref{eq:PoissonRSquared} vanish. The two constraints after the limit become:
\begin{subequations}
\begin{align}
\RH_{\mu\nu}=&\,  0\,,\\
\accentset{(0)}{\langle C\rangle}:=\RicJ^{2}-2h^{\mu\nu}\nablaNR_{\mu}\nablaNR_{\nu}\RicJ=&\,  0\,,
\end{align}
where the number above recalls at which order of the expansion of the corresponding relativistic constraints the final result appears. Then the Poisson equation is:
 \begin{align}
\accentset{(-2)}{[P_{+}]}:=&\,  (D-2)\PA\RG_{0a}{}^{a}(1-2\CA\RicJ)+2(D-2)\CA\PA\tau^{\mu}\tau^{\nu}\nablaNR_{\mu}\partial_{\nu}\RicJ=0\,. 
\end{align}
In the next section we derive the full set of equations of motion and the corresponding transformations under boost. We will drop the factor $\CA$ and the overall factor $(D-2)\PA$ from the Poisson equations.

\subsubsection{Full Set of Equations of Motion}\label{sec:NRRREOM}
\noindent The full set of non-relativistic equations is:
\begin{align}
\accentset{(-2)}{[P_{+}]}:=&\,  \RG_{0a}{}^{a}(1-2\RicJ)+2\tau^{\mu}\tau^{\nu}\nablaNR_{\mu}\partial_{\nu}\RicJ=0\,,\\
\nonumber\\
\accentset{(0)}{[P_{-}]}:=&\,  \RicJ(1-3\RicJ)=0\,,\\
\nonumber\\
\accentset{(-1)}{[G]}_{0a}:=&\,  -\RicJ_{0a}+2\RicJ_{0a}\RicJ+2\tau^{(\mu}e^{\nu)}{}_{a}\nablaNR_{\mu}\partial_{\nu}\RicJ=0\,,\\
\nonumber\\
\accentset{(0)}{[G]}_{\{ab\}}:=&\,  -\RicJ_{\{ab\}}(1-2\RicJ)+2e^{\mu}{}_{\{a}e^{\nu}{}_{b\}}\nablaNR_{\mu}\partial_{\nu}\RicJ=0\,,
\end{align}
\end{subequations}
where $\accentset{(0)}{[P_{-}]}$ has been obtained by taking the limit of the combination 
\begin{align*}
[P_{-}]:=E^{\mu}{}_{a}E^{\nu a}[G]_{\mu\nu}+(D-3) E^{\mu}{}_{0}E^{\nu}{}_{0}\, [G]_{\mu\nu}\,,
\end{align*}
and the other equations are defined as in \autoref{sec:NRGBEOM}. These should be supplemented with the constraints:
\begin{subequations}
\begin{align}
\RH_{\mu\nu}=&\,  0\,,\\
\accentset{(0)}{\langle C\rangle}:=\RicJ^{2}-2h^{\mu\nu}\nablaNR_{\mu}\partial_{\nu}\RicJ=&\,  0\,.
\end{align}
\end{subequations}
The set of non-relativistic equations and constraints transforms under boosts as:
\begin{subequations}
\begin{align}
\delta_{G}\RH_{\mu\nu}=&\,  0\,,\\
\delta_{G}\accentset{(0)}{\langle C\rangle}=&\,  0\,,\\
\delta_{G}\accentset{(-2)}{[P_{+}]}=&\,  -2\boostp^{a}\accentset{(-1)}{[G]}_{0a}\,,\\
\delta_{G}\accentset{(0)}{[P_{-}]}=&\,  0\,,\\
\delta_{G}\accentset{(-1)}{[G]}_{0a}=&\,  -\boostp^{b}\accentset{(0)}{[G]}_{\{ab\}}+\frac{\boostp_{a}}{D-1}\accentset{(0)}{[P_{-}]}\,,\\
\delta_{G}\accentset{(0)}{[G]}_{\{ab\}}=&\,  0\,.
\end{align}
\end{subequations}
These transformations have to be intended up to the constraints themselves. The action of the boost transformations is visualized in \autoref{fig:diagram3}. The set of equations define a reducible indecomposable representation of the Bargmann algebra. All the equations, except the Poisson equation, can be obtained from the corresponding non-relativistic action.


