\section{Definitions \& Useful Relations}\label{sec:UsRel}
\noindent The Riemann tensor is defined by
\begin{align}
\Riem^{\rho}{}_{\sigma\mu\nu}=&\,  \partial_{\mu}\Gamma_{\nu\sigma}^{\rho}-\partial_{\nu}\Gamma_{\mu\sigma}^{\rho}+\Gamma_{\mu\lambda}^{\rho}\Gamma_{\nu\sigma}^{\lambda}-\Gamma_{\nu\lambda}^{\rho}\Gamma_{\mu\sigma}^{\lambda}
\end{align}
with $\Gamma^{\rho}_{\mu\nu}$ the Christoffel symbols,
\begin{align}
\Gamma_{\mu\nu}^{\rho}=&\,  \frac{1}{2}g^{\rho\sigma}(\partial_{\mu}g_{\nu\sigma}+\partial_{\nu}g_{\mu\sigma}-\partial_{\sigma}g_{\mu\nu})\,.
\end{align}
The Ricci tensor and scalar are defined by
\begin{subequations}
\begin{align}
\Ric_{\mu\nu}=&\,  \Riem^{\rho}{}_{\mu\rho\nu}\,,\\
\R=&\,  g^{\mu\nu}\Ric_{\mu\nu}\,.
\end{align}
\end{subequations}
We report in this section relations that have been used in deriving the relativistic equations of motion and manipulating them
\begin{subequations}
\begin{align}
\delta\sqrt{-g}=&\,  -\frac{1}{2}\sqrt{-g}g_{\mu\nu}\delta g^{\mu\nu}\,,\\
\delta \Riem^{\rho}{}_{\sigma\mu\nu}=&\,  \nabla_{\mu}(\delta\Gamma^{\rho}_{\nu\sigma})-\nabla_{\nu}(\delta\Gamma^{\rho}_{\mu\sigma})\,,\\
\delta \Ric_{\mu\nu}=&\,  \nabla_{\rho}(\delta\Gamma^{\rho}_{\nu\mu})-\nabla_{\nu}(\delta\Gamma^{\rho}_{\rho\mu})\,,\\
\delta \R=&\,  \Ric_{\mu\nu}\delta g^{\mu\nu}+\nabla_{\sigma}(g^{\mu\nu}\delta\Gamma^{\sigma}_{\nu\mu}-g^{\mu\sigma}\delta\Gamma^{\rho}_{\rho\mu})\,,\\
[\nabla_{\alpha},\nabla_{\beta}]F_{\mu\nu}=&\,  -\Riem^{\rho}{}_{\mu\alpha\beta}F_{\rho\nu}-\R^{\rho}{}_{\nu\alpha\beta}F_{\mu\rho}\,.
\end{align}
\end{subequations}
The following relations are also useful:  
\begin{subequations}
\begin{align}
\nabla^{\mu} \Ric_{\mu\nu}=&\,  \frac{1}{2}\nabla_{\nu}\R\,,\\
\nabla_{\alpha}F^{\mu\nu}\nabla_{\mu}F_{\beta\nu}=&\,  -\frac{1}{2}\nabla_{\alpha}F_{\mu\nu}\nabla_{\beta}F^{\mu\nu}\,,\\
\nabla_{\mu}F_{\nu\rho}\nabla^{\rho}F^{\mu\nu}=&\,  \frac{1}{2}\nabla_{\mu}F_{\nu\rho}\nabla^{\mu}F^{\nu\rho}\,,\\
\Riem_{\alpha}{}^{\mu\nu\rho}\Riem_{\beta\nu\mu\rho}=&\,  \frac{1}{2}\Riem_{\alpha}{}^{\mu\nu\rho}\Riem_{\beta\mu\nu\rho}\,,\\
F^{\mu\nu}\Riem_{\alpha\mu\beta\nu}=&\,  \frac{1}{2}F^{\mu\nu}\Riem_{\alpha\beta\mu\nu}\,.
\end{align}
\end{subequations}
In analogy with the relativistic case we define the following non-relativistic tensors:
\begin{align}
\RiemNR^{\rho}{}_{\sigma \mu \nu}=&\,  \partial_{\mu}\GammaNR^{\rho}_{\nu\sigma}- \partial_{\nu}\GammaNR^{\rho}_{\mu\sigma}+\GammaNR^{\rho}_{\mu\xi}\GammaNR^{\xi}_{\nu\sigma}-\GammaNR^{\rho}_{\nu\xi}\GammaNR^{\xi}_{\mu\sigma}\,,\\
\RicNR_{\mu \nu}=&\,  \RiemNR^{\rho}{}_{\mu \rho \nu}\,.
\end{align}
Beyond the formal analogy, useful to organize the calculations, these non-relativistic tensors do not transform covariantly under Galilean boosts. The proper definition of geometric non-relativistic curvatures is discussed in \autoref{sec:Geometry}.

\subsection{Non-Relativistic Curvatures Bianchi  Identities}\label{sec:NRCurvaturesIds}
\noindent A set of non-relativistic Bianchi identities is:
\begin{subequations}
\begin{align}
\nablaNR_{[\mu}t_{\nu\rho]}=&\,  -\tau^{\alpha}t_{\alpha[\mu}t_{\nu\rho]}\,,\\
\nablaNR_{[\mu}z_{\nu\rho]}{}^{a}=&\,  -\tau^{\alpha}z_{\alpha[\mu}{}^{a}t_{\nu\rho]}\,,\\
\nablaNR_{[\mu}f_{\nu\rho]}=&\,  -\tau^{\alpha}f_{\alpha[\mu}t_{\nu\rho]}\,,\\
\RiemNR^{\alpha}{}_{[\mu\nu\rho]}=&\,  -\frac{1}{2}\tau^{\sigma}e^{\alpha}{}_{a}t_{[\mu\nu}z_{\rho]\sigma}{}^{a}+\frac{1}{2}\tau^{\sigma} h^{\alpha\xi}z_{\sigma\xi a}e_{[\mu}{}^{a}t_{\nu\rho]}+\frac{1}{2}h^{\alpha\xi}t_{[\mu\nu}f_{\rho]\xi}+\nonumber\\
&+\frac{1}{2}h^{\alpha\xi}f_{0\xi}\tau_{[\mu}t_{\nu\rho]}\,.
\end{align}
\end{subequations}
Further useful identities are the following:
\begin{subequations}
\begin{align}
\tau_{\sigma}\RiemNR^{\sigma}{}_{\mu\nu\rho}=&\,  0\,,\\
\RicNR_{[ab]}=&\,  -f_{[a}{}^{c}t_{b]c}-t_{ab}z_{0c}{}^{c}+t_{[a}{}^{c}z_{0b]c}+z_{0c[b}t_{a]}{}^{c}\,,\\
\RiemNR_{abcd}=&\,  -\RiemNR_{bacd}\,,\\
\RiemNR^{\sigma}{}_{\rho\mu\nu}=&\,  -\RiemNR^{\sigma}{}_{\rho\nu\mu}\,,\\
\RiemNR_{abcd}=&\,  \RiemNR_{cdab}+\frac{1}{2}(t_{ab}f_{cd}-t_{cd}f_{ab})
-t_{ac}z_{0(bd)}+t_{ad}z_{0(bc)}+t_{bc}z_{0(ad)}-t_{bd}z_{0(ac)}\,,\\
3\RicNR_{a[bcd]}=&\,  \frac{3}{2}(z_{0a[b}t_{cd]}+t_{[bc|}z_{0|d]a}-f_{a[b}t_{cd]})\,.
\end{align}
\end{subequations}

\section{On Newton-Cartan Geometry}\label{sec:Geometry}
\noindent In this section we introduce the basics of the Newton-Cartan geometry to rewrite our results in terms of covariant quantities. We have defined the non-relativistic connection $\GammaNR_{\mu\nu}^{\rho}$ in \autoref{eq:NRConnection} such that the non-relativistic analogue of metric compatibility relations, $\nablaNR_{\mu}\tau_{\nu}= 0 = \nablaNR_{\mu}h^{\nu\rho}$, are satisfied. We can now introduce a boost and transverse rotations spin connections, $\oG_{\mu}{}^{a}$ and $\oJ_{\mu}{}^{a b}$ respectively, following \cite{Bergshoeff:2022fzb}, by considering the analogue of the relativistic vielbein postulate:
\begin{align}
\partial_{\mu}e_{\nu}{}^{a}-\oJ_{\mu}{}^{a}{}_{b}e_{\nu}{}^{b}-\oG_{\mu}{}^{a}\tau_{\nu}-\GammaNR_{\mu\nu}^{\rho}e_{\rho}{}^{a}=&\,  0\,.\label{eq:NRVielbeinPostulate}
\end{align}
Solving for the two spin connections we get
\begin{subequations}
\begin{align}
\oG_{\mu}{}^{a}=&\,  \tau^{\nu}(\partial_{\mu}e_{\nu}{}^{a}-\GammaNR_{\mu\nu}^{\rho}e_{\rho}{}^{a})\,,\\
\oJ_{\mu}{}^{a b}=&\,  e^{\nu b}(\partial_{\mu}e_{\nu}{}^{a}-\GammaNR_{\mu\nu}^{\rho}e_{\rho}{}^{a})\,.
\end{align}
\end{subequations}
Note that the transverse rotations connection is antisymmetric in the flat indices, although in the expression above it is not manifest. The connections just defined transform as follows under $U(1)$ gauge symmetry, Galilean boost and transverse rotations:
\begin{subequations}
\begin{align}
\delta \GammaNR_{\mu\nu}^{\rho}=&\,  \frac{1}{2}\boostp_{a}h^{\rho\sigma}(e_{\nu}{}^{a}t_{\mu\sigma}+e_{\mu}{}^{a}t_{\nu\sigma}-e_{\sigma}{}^{a}t_{\mu\nu})\,,\\
\delta \oG_{\mu}{}^{a}=&\,  \partial_{\mu}\boostp^{a}-\boostp_{b}\oJ_{\mu}{}^{a b}+\lorentzp^{a}{}_{b}\oG_{\mu}{}^{b}-\frac{1}{2}
\boostp_{b}e_{\mu}{}^{b}t_{0}{}^{a}+\frac{1}{2}\boostp^{a}t_{\mu 0}\,,\\
\delta\oJ_{\mu}{}^{a b}=&\,  \partial_{\mu}\lorentzp^{ab}+2\lorentzp^{[b}{}_{c}\oJ_{\mu}{}^{a]c}+\frac{1}{2}\boostp_{c}e_{\mu}{}^{c}t^{a b}+t_{\mu[b}\boostp_{a]}\,.
\end{align}
\end{subequations}
We can define the following covariant curvatures:
\begin{subequations}
\begin{align}
\RH_{\mu\nu}=&\,  t_{\mu\nu}\,,\\
\RP_{\mu\nu}{}^{a}=&\,  z_{\mu\nu}{}^{a}-2\oJ_{[\mu}{}^{ab}e_{\nu]b}-2\oG_{[\mu}{}^{a}\tau_{\nu]}\,,\\
\RM_{\mu\nu}=&\,  f_{\mu\nu}+2\oG_{[\mu}{}^{a}e_{\nu]a}\,,\\
\RG_{\mu\nu}{}^{a}=&\,  2\partial_{[\mu}\oG_{\nu]}{}^{a}-2\oJ_{[\mu}{}^{a b}\oG_{\nu] b}-\oG_{[\nu}{}^{b}e_{\mu] b}t_{0}{}^{a}+\oG_{[\nu}{}^{a}t_{\mu]0}\,,\\
\RJ_{\mu\nu}{}^{ab}=&\,  2\partial_{[\mu}\oJ_{\nu]}{}^{a b}+2\oJ_{[\mu}{}^{a c}\oJ_{\nu]}{}^{b}{}_{c} -2\oG_{[\mu}{}^{[a}t_{\nu]}{}^{b]}-\oG_{[\mu}{}^{c}e_{\nu] c}t^{ab}\,.
\end{align}
\end{subequations}
$\RM_{\mu\nu}$ and $\RP_{\mu\nu}{}^{a}$ vanish once the expression of the spin connection is plugged into their definitions. 
The curvatures transform as
\begin{subequations}
\begin{align}
\delta \RH_{\mu\nu}=&\,  0\,,\\
\delta \RP_{\mu\nu}{}^{a}=&\,  \lorentzp^{a}{}_{b}\RP_{\mu\nu}{}^{b}\,,\\
\delta \RM_{\mu\nu}=&\,  -\boostp_{a}\RP_{\mu\nu}{}^{a}\,,\\
\delta \RG_{\mu\nu}{}^{a}=&\,  \lorentzp^{a}{}_{b}\RG_{\mu\nu}{}^{b}
-\boostp_{b}\RJ_{\mu\nu}{}^{a b}-\frac{1}{2}\boostp^{a}\tau^{\rho}\nablaNR_{\rho}\RH_{\mu\nu}+\nonumber\\
&+\boostp_{b}\tau^{\rho}e^{\sigma a}e_{[\mu}{}^{b}\nablaNR_{\nu]}\RH_{\rho\sigma}+\frac{1}{2}\boostp_{b}e_{[\mu}{}^{b}\RH_{\nu]0}\RH_{0}{}^{a}\,,\\
\delta \RJ_{\mu\nu}{}^{a b}=&\,  -2\lorentzp^{[a}{}_{c}\RJ_{\mu\nu}{}^{b]c}++e^{\rho[a}\boostp^{b]}\nablaNR_{\rho}\RH_{\mu\nu}+\nonumber\\
&+\frac{2}{3}\boostp^{[a}\RH_{0}{}^{b]}\RH_{\mu\nu}+\frac{1}{3}\boostp^{[a}\RH_{[\mu}{}^{b]}\RH_{\nu]0}+\nonumber\\
&+\boostp_{c}e^{\rho a}e^{\sigma b}e_{[\nu}{}^{c}\nablaNR_{\mu]}\RH_{\rho\sigma}-\boostp_{c}e_{[\mu}{}^{c}\RH_{\nu]}{}^{[a}\RH_{0}{}^{b]}\,.
\end{align}
\end{subequations}
We define 
\begin{align}
\RicJ_{a b}=&\,  \RJ_{a c b}{}^{c}\,,
\end{align}
which is symmetric in its indices and transforms as
\begin{align}
\delta \RicJ_{a b}=&\,  2\lorentzp^{(a}{}_{c}\RicJ^{b)}{}_{c}-\boostp^{(a}\CDRH_{d}{}^{b)d}+\boostp_{d}\CDRH^{(ab)d}+\nonumber\\
&+\frac{1}{2}\boostp^{(a}\RH^{b)c}\RH_{0c}-\frac{1}{2}\boostp_{c}\RH_{0}{}^{(a}\RH^{b)c}\,.
\end{align}
The definition above induces the definition
\begin{align}
\RicJ=&\,  \RicJ_{a}{}^{a}=\RJ_{a b}{}^{a b}\,,
\end{align}
transforming as
\begin{align}
\delta \RicJ=&\,  -2\boostp_{a}\CDRH^{ba}{}_{b}+\boostp_{a}\RH_{0b}\RH^{ab}\,.
\end{align}
We also have the following Bianchi identity:
\begin{subequations}
\begin{align}
\nablaNR_{[\mu}\RH_{\nu\rho]}-\tau^{\xi}\RH_{[\mu\nu}\RH_{\rho]\xi}=&\,  0\,,
\end{align}
\end{subequations}
and 
\begin{subequations}
\begin{align}
\RJ_{abcd}=&\,  \RJ_{cdab}\,,\\
\RJ_{a[bcd]}=&\,  0\,,\\
\RG_{ba}{}^{b}=&\,  \RJ_{0ba}{}^{b}=\RicJ_{0a}\,,\\
2\RJ_{0[ab]c}=&\,  \RG_{abc}\,,\\
\RJ_{0[abc]}=&\,  \RG_{[abc]}=0\,.
\end{align}
\end{subequations}
The expression of the non-relativistic tensor $\RicNR_{\mu\nu}$ in terms of the geometric quantities introduced in this section is the following:
\begin{align}
\RicNR_{\mu\nu}=&\,  \tau_{\mu}\RG_{\nu a}{}^{a}-e_{\mu}{}^{a}\RJ_{\nu b a}{}^{b}-\oG_{\nu}{}^{a}\RH_{\mu a}+\frac{1}{2}e^{\rho}{}_{a}\oG_{\rho}{}^{a}\RH_{\mu\nu}+\nonumber \\
&+e^{\rho b}\oG_{\rho a}e_{(\mu}{}^{a}\RH_{\nu)b}\,.
\end{align}
It is also useful to report here the transformation rule of $\CDRH_{\mu\nu\rho}$ under all symmetries except diffeomorphisms:
\begin{align}
\delta\CDRH_{\mu\nu\rho}=&\,  \boostp_{a}\Big(e_{[\nu}{}^{a}\RH_{\rho]b}\RH_{\mu}{}^{b}-\RH_{\mu[\nu}\RH_{\rho]}{}^{a}\Big)\,.
\end{align}

