        &\eqref{eq:quartic_potential}: \eps = 0.1, \quad T \in \{ 100m \, | \, m = 1, \ldots, 20 \}, \quad h < \eps^3.
    \end{align*}
    \item Gradient descent algorithm parameters:
    \begin{align*}
        \beta = 1, \quad \text{initial point: } \vt_{\text{initial}} = 10, \quad  \text{box interval: } (0, \infty), \quad \text{optimizer: L-BFGS}.
    \end{align*}
\end{itemize}
Note that we make a couple of distinctions depending on the chosen drift term. This is because the optimization is numerically more involved for the quartic potential \eqref{eq:quartic_potential}. 

