We introduce the slow variables $\zeta$ and $\tau$ as $\zeta=\epsilon(n-v_g t)$ and $\tau=\epsilon^2 t$, where $v_g$ is the group velocity, $n$ is the cell number, and $\epsilon$ is a small parameter. These variables describe the slow evolution of the wave envelope, smoothing rapid variations between cells and enabling a continuous approximation of the system.

We assume the solution of Eq. (\ref{eq2}) in the form \cite{Kengne2019transmission,Djelah2023rogue}:
\begin{equation}
V_n(t)=\epsilon\psi(\zeta,\tau)e^{i\theta}+\epsilon^2\psi_{10}(\zeta,\tau)+\epsilon^2 \psi_{20}(\zeta,\tau)e^{2i\theta}+\text{c.c}.
\label{eq3}
\end{equation}
where $\theta=(kn-\omega t)$ is the rapidly varying phase with wavenumber $k$ and angular frequency $\omega$. The term 'c.c.' represents the complex conjugate. This assumption accounts for the fundamental term $\psi(\zeta,\tau)$, the DC component $\psi_{10}(\zeta,\tau)$, and the second-harmonic term $\psi_{20}(\zeta,\tau)$, which together provide a comprehensive system description.

Substituting Eq. (\ref{eq3}) into Eq. (\ref{eq2}) and retaining terms proportional to $\epsilon$ and $e^{i\theta}$ yield the linear dispersion relation and group velocity:
\begin{equation}
\omega=\sqrt{\frac{\omega_0^2+4u_0^2\sin^2(\frac{k}{2})}{1+4\gamma\sin^2(\frac{k}{2})}}, \quad
v_g=\frac{d\omega}{dk}=\frac{(u_0^2-\gamma\omega^2)\sin(k)}{\omega(1+4u_0^2\sin^2(\frac{k}{2}))}.
\label{eq5}
\end{equation}
Upon solving the resulting equation that arise from $(\epsilon^4, e^{i0})$ provides the expression for the DC term:
\begin{equation}
\psi_{10}(\zeta,\tau)=\frac{2\alpha v_g^2|\psi|^2}{v_g^2-u_0^2}+c_0(\tau)\zeta+c_1(\tau),
\label{eq8}
\end{equation}
where $c_0(\tau)$ and $c_1(\tau)$ are real-valued functions. 

For $(\epsilon^2, e^{2i\theta})$, weobtain the expression for the second-harmonic term as
\begin{equation}
\psi_{20}(\zeta,\tau)=\frac{4\alpha\omega^2\psi^2}{4\omega^2+ 4(4\gamma\omega^2-u_0^2)\sin^2(k)-\omega_0^2}
\label{eq81}.
\end{equation}
Finally, for the case $(\epsilon^3, e^{i\theta})$, we obtain the extended nonlinear Schr\"odinger equation:
\begin{subequations}
	\label{eq9}
\begin{equation}
\label{eq91}
i\frac{\partial \psi}{\partial \tau}+P\frac{\partial^2\psi}{\partial \zeta^2}+Q|\psi|^2\psi+P \beta_1^2  |\psi|^4\psi-4iP\beta_1  (|\psi|^2)_x \psi+\Gamma(\tau)\zeta\psi=0,
\end{equation} 
where
\begin{align}
P&=\frac{1}{1+4\gamma\sin^2(\frac{k}{2})}\Bigg(-\frac{v_g^2}{2\omega}\left(1+4\gamma \sin^2(\frac{k}{2})\right)+\left(\frac{u_0^2}{2\omega}-\frac{\gamma \omega}{2}\right)\cos(k)-2\gamma v_g \sin(k)\Bigg),\\
Q&=\frac{\omega}{1+4\gamma\sin^2(\frac{k}{2})}\Bigg(\frac{3\beta}{2}-\frac{2\alpha^2v_g^2}{v_g^2-u_0^2}-\frac{4\alpha^2\omega^2}{4\omega^2-\omega_0^2+4(4\gamma\omega^2-u_0^2)\sin^2(k)}\Bigg),\\
\Gamma(\tau)&=-\frac{\alpha\omega}{1+4\gamma\sin^2(\frac{k}{2})}c_0(\tau).
\label{eq10}
\end{align}
\end{subequations}
Here, $P$ represents group velocity dispersion, while $Q$ quantifies nonlinear self-modulation.

Equation (\ref{eq91}) can be transformed to the KE equation. To do this, we consider the following transformation,
\begin{subequations}
	\label{eq11}
\begin{equation}
\psi(\zeta,\tau)=\rho \Psi(X,T)e^{i(\Lambda_1 \zeta+\Lambda_2)},
\end{equation}
\text{with}
\begin{align}
X=\Lambda_3+\rho \sqrt{\frac{Q}{2P}}\zeta,\;\; T=\frac{1}{2}Q\rho^2\tau,\;\; \frac{d\Lambda_1}{d\tau}-\Gamma(\tau)=0,\;\; \frac{d\Lambda_2}{d\tau}+P\Lambda_1^2=0,\nonumber\\ \frac{d\Lambda_3}{d\tau}+2P\rho\Lambda_1 \sqrt{\frac{Q}{2P}}=0.
\label{ex1}
\end{align}
\end{subequations}
Substituting the above expressions (\ref{eq11}) into Eq. (\ref{eq9}) and rearranging, we end up at
\begin{equation}
i\frac{\partial \Psi}{\partial T}+\frac{\partial^2 \Psi}{\partial X^2}+2|\Psi|^2\Psi+4\beta_2^2|\Psi|^4\Psi-4i\beta_2 (|\Psi|^2)_x \Psi=0,\quad \beta_2=\rho\beta_1 \sqrt{\frac{2P}{Q}},
\label{eq12}
\end{equation}
the exact KE equation. The KE Eq. (\ref{eq12}) is integrable and it admits several kinds of localized solutions including soliton, breather, RWs and positon.

The breather solution of the KE equation is given by \cite{Solution1}
\begin{subequations}
\begin{equation}
\Psi_{b}(X,T) = \left( \frac{L_{b11}}{L_{b12}} \right) \exp \left( i \left( \rho_0 + \frac{L_{b13}}{L_{b12}} \right) \right)
\label{s1}
\end{equation}
with
\begin{align}
L_{b11} &= -c \eta_1 \cos(\theta_1) - c^2 \cosh(\theta_2) - 2i K_0 \eta_1 \sinh(\theta_2) + 2\eta_1^2 \cosh(\theta_2), \nonumber\\
L_{b12} &= \eta_1 \cos(\theta_1) - c \cosh(\theta_2), L_{b13} = -4\beta_2 \eta_1 K_0 \sin(\theta_1),\nonumber\\
    K_0 &= \sqrt{c^2 - \eta_1^2}, a = -2\xi_1 + 2\beta_2 c^2, b = -a^2 + 4\beta_2^2 c^4 + 2c^2,\nonumber\\ 
    \theta_1 &= 2K_0 (X + 4\xi_1 T), \theta_2 = 4T K_0 \eta_1, \rho_0 = a X + b T.
\end{align}
\end{subequations}
The positon solution for the KE equation is given by \cite{Solution2}
\begin{subequations}
\begin{equation}
    \Psi_{p}(X,T) = \exp \left( -2i\beta_2 \frac{N_{12}(X,T)}{D_1(X,T)} \right) \times \frac{N_{11}(X,T)}{D_1(X,T)}
    \label{s2}
\end{equation}
with 
\begin{align}
    N_{11}(X,T) &= 16 \eta_2 \left( \cos(4\eta_2^2 T - 4T \xi_2^2 - 2X\xi_2) + i \sin(4\eta_2^2 T - 4T\xi_2^2 - 2X\xi_2) \right) \nonumber \\
&\quad \times \left( 8i\eta_2^2 T \cosh(2\eta_2 h_1(X,T)) - 8\eta_2 T \xi_2 \sinh(2\eta_2 h_1(X,T)) \right. \nonumber \\
&\quad \left. -2\eta_2 X \sinh(2\eta_2 h_1(X,T)) + \cosh(2\eta_2 h_1(X,T)) \right)\\
N_{12}(X,T)& = -2 \eta_2 \left( 32 \eta_2 T \xi_2 + 8 \eta_2 X + e^{4\eta_2 h_1(X,T)} - e^{-4\eta_2 h_1(X,T)} \right)\\
D_1(X,T) &= 256 \eta_2^4 T^2 + 256 \eta_2^2 T^2 \xi_2^2 + 128 \eta_2^2 T X \xi_2 \nonumber \\
&\quad + 16 \eta_2^2 X^2 + e^{4\eta_2 h_1(X,T)} + 2 + e^{-4\eta_2 h_1(X,T)}\\
h_1(X,T) &= 4\xi_2 T + X.
\end{align}
\end{subequations}
