V_n(t)=Re(\epsilon\psi_{b/p}(\zeta,\tau)e^{i\theta}+\epsilon^2\psi_{10}(\zeta,\tau)+\epsilon^2 \psi_{20}(\zeta,\tau)e^{2i\theta}+c.c.),
\label{ep31}
\end{equation}
