	\section{Proof of main result}
	In this section, we will prove the main result theorem \ref{Main thm}. The key argument proceeds by contradiction.

	\subsection{Contradiction assumption}
	 Without loss of generality, let $ (x_0,0) $  be a singular point. Applying the small energy regularity lemma \ref{elbsilon32}, there exist  $\varepsilon_1>0$  and a sequence of positive numbers $\lambda_{k}$ such that $\lambda_{k} \rightarrow 0$ as $k \rightarrow+\infty$. While for any $k \in \NN^+$,
		\begin{align}
			 \sup _{-\lambda_{k}^{2} \leqslant t \leqslant 0} \frac{1}{\lambda_{k}^{\frac{3}{2}}} \int_{B\left(x_{0}, \lambda_{k}\right)}|v(x, t)|^{\frac{3}{2}} d x>\varepsilon_1.
		\end{align}





%%%%%%%%%%%%%%%%%%%%%%%做准备工作，伸缩和压力分解
	First, by performing the scaling $ v(x,t) \mapsto \lambda v(\lambda x, \lambda^2 t)$, we derive the behavior of the velocity $v(x,t)$ in the vicinity of the singular point. Let
		\begin{align}
			& v^{(k)}(y, \tau)=\lambda_{k} v\left(x_{0}+\lambda_{k} y, \lambda_{k}^{2} \tau\right), \label{v的scaling}\\
			& p^{(k)}(y, \tau)=\lambda_{k}^{2} p\left(x_{0}+\lambda_{k} y, t_{0}+\lambda_{k}^{2}. \label{p的scaling}\tau\right).
		\end{align}

	Then $v^{(k)}(y, \tau)$, $p^{(k)}(y, \tau)$ still satisfies the Navier-Stokes equations. And we have
		\begin{align}
			\|v^{(k)}\|_{L_t^\infty L_{x_3}^{p_1} L_{x_h}^{p_2}(\RR^3 \times (-\frac{T}{\lambda^k},0))} =\|v\|_{L_t^\infty L_{x_3}^{p_1} L_{x_h}^{p_2}(Q_T)} =M.
		\end{align}
	For the pressure term $p^{(k)}(y, \tau)$, the following formula is well-known
		\begin{align}
			p^{(k)}(y, \tau)=-\frac{1}{3}|v^{(k)}(y, \tau)|^{2}+\frac{1}{4 \pi} \int_{\mathbb{R}^{3}} K(y-\bar{y}): v^{(k)}(\bar{y}, \tau) \otimes v^{(k)}(\bar{y}, \tau) d \bar{y}.
		\end{align}
	Where $K(x)=\nabla^2(\frac{1}{|x|})$.

	The pressure can be decomposed using the method as mentioned in \cite{kikuchi2007}. For an arbitrary $y_0 \in \RR^3$ and for $y \in B(y_0,\frac{3}{2})$, (where $B(y_0,r)=\{y \in \RR^3 | |y-y_0|<r\}$ ), let
		\begin{align}
			p^{(k)}(y,\tau)=p^{(k)}_{y_0}(y,\tau)+c^{(k)}_{y_0}(\tau)=p^{1(k)}_{y_0}(y,\tau)+p^{2(k)}_{y_0}(y,\tau)+c^{(k)}_{y_0}(\tau).
		\end{align}
	where
		\begin{align}
			p^{1(k)}_{y_0}(y,\tau)&=-\frac{1}{3}|v^{(k)}(y, \tau)|^{2}+\frac{1}{4 \pi} \int_{B(y_0,2)} K(y-\bar{y}): v^{(k)}(\bar{y}, \tau) \otimes v^{(k)}(\bar{y}, \tau) d \bar{y},\label{p1}\\
			p^{2(k)}_{y_0}(y,\tau)&=\frac{1}{4 \pi} \int_{\RR^3\setminus B(y_0,2)} (K(y-\bar{y})-K(y_0-\bar{y})): v^{(k)}(\bar{y}, \tau) \otimes v^{(k)}(\bar{y}, \tau) d \bar{y},\label{p2}\\
			c^{(k)}_{y_0}(\tau)&=\frac{1}{4 \pi} \int_{\RR^3\setminus B(y_0,2)} K(y_0-\bar{y}): v^{(k)}(\bar{y}, \tau) \otimes v^{(k)}(\bar{y}, \tau) d \bar{y}.\label{pconstant}
		\end{align}
	This decomposition isolates the singular part of the integral kernel in the pressure formulation, allowing the pressure at any point to be expressed locally. Since the Navier-Stokes equations involve only the pressure gradient $\nabla p^{(k)}(y,\tau)$. For any $y_0 \in \RR^3$ ,we replace the pressure $p^{(k)}(y,\tau)$ locally with
		\begin{align}\label{pfenjie}
			p^{(k)}_{y_0}(y,\tau)=p^{(k)}(y,\tau)-c^{(k)}_{y_0}(\tau)=p^{1(k)}_{y_0}(y,\tau)+p^{2(k)}_{y_0}(y,\tau),
		\end{align}
	where  $y \in B(y_0,\frac{3}{2})$.

	Through simple calculations,  the following estimate holds
		\begin{align}
			\left\|p_{y_0}^{1(k)}(\cdot, \tau)\right\|_{L^{\frac{3}{2}}\left(B\left(y_0, \frac{3}{2}\right)\right)} & \leq c_1\left(\left\|v^{(k)}(\cdot, \tau)\right\|_{L^3\left(B\left(y_0, 2\right)\right)}^2 + 1\right),\label{p1estimate}\\
			\sup _{y \in B\left(y_{0}, \frac{3}{2}\right)}\left|p_{y_{0}}^{2(k)}(y, \tau)\right| & \leq c_1\left(\left\|v^{(k)}(\cdot, \tau)\right\|_{L_2, \text { unif }}^{2}+1\right).\label{p2estimate}
		\end{align}
	Where
		\begin{align}
			\|f\|_{L_2, \text{unif}} = \sup_{x_0 \in \mathbb{R}^3} \|f\|_{L^2(B(x_0, 1))}.
		\end{align}




%%%%%%%%%%%%%%%%%%%%%%%先验估计
		\subsection{Priori estimates }
	We now establish a priori estimates by exploiting the boundedness of $v^{(k)}(y, \tau)$ in the scaling-invariant $L_t^\infty L_{x_3}^{p_1} L_{x_h}^{p_2}$-norm. Thanks to the scale-invariance property, this step follows directly. For fix $T_0>10$, and for $\tau \in [-T_0,0]$, let
		\begin{align}
			&\alpha (\tau,k)=\|v^{(k)}(\cdot,\tau)\|_{L_2, \text{unif}}^2 \label{L2xiang} \, , \\
			&\beta (\tau,k)= \sup_{y_0 \in \RR^3} \int_{-T_0}^{\tau}\int_{B(y_0,1)}|\nabla v^{(k)}(\bar{y},s)|^2d\bar{y}ds,\label{L6xiang}\\
			&\gamma (\tau,k)= \sup_{y_0 \in \RR^3} \int_{-T_0}^{\tau}\int_{B(y_0,1)}| v^{(k)}(\bar{y},s)|^3d\bar{y}ds.\label{L3xiang}
		\end{align}
	For $\gamma (\tau,k)$, By known multiplicative inequality we have
	\begin{align} \label{L3dechazhi}
		\gamma(\tau,k) \leq c_2 \left( \int_{-T}^{\tau} \alpha^3(s,k) ds \right)^{\frac{1}{4}} \left( \beta(\tau,k) + \int_{-T}^{\tau} \alpha(s,k) ds \right)^{\frac{3}{4}}.
	\end{align}

	Then we have the following lemma.
	\begin{lemma} \label{prioriestimate}
		For $v(x,t)$ and $p(x,t)$ satisfying the conditions of Theorem \ref{Main thm}, we have
		\begin{align}
			\sup_{\tau \in [-T_0,0]}\alpha (\tau,k)+\beta (0,k)+\gamma (0,k) \leqslant c_0(M).
		\end{align}
		Where the constant $c_0(M)$ is independent of $k$.
	\end{lemma}
	\begin{proof}
	Let a positive test function $\phi(y)$ satisfies the following conditions
	\begin{equation}
		\begin{cases}
			 0\leq \phi(y)\leq 1 , \quad \forall \, y \in \RR^3 ;\\
			 \phi(y)\equiv 1 , \quad \forall \,  y \in B(0,1) ;\\
			 \phi(y)\equiv 0 , \quad \forall \, y \in \RR^3 \setminus B(0,\frac{3}{2}).
		\end{cases}
	\end{equation}
	For fix $ y_0 \in \RR^3$, let
		\begin{align}
			\phi_{y_0}(y)=\phi (y-y_0).
		\end{align}
	Since $v^{(k)}(y,\tau)$ is smooth in $(\RR^3 \times (-\frac{T}{\lambda^k},0))$, we have the following energy inequality
		\begin{equation}
			\begin{aligned}
				&\int_{\mathbb{R}^3} \phi_{y_0} (y) |v^{(k)} (y, \tau)|^2 dy + 2 \int_{-T_0}^{\tau} \int_{\mathbb{R}^3} \phi_{y_0} |\nabla v^{(k)}|^2 dy ds \\
				&\leqslant \int_{\mathbb{R}^3} \phi_{y_0} (y) |v^{(k)} (y, -T_0)|^2 dy+ \int_{-T_0}^{\tau} \int_{\mathbb{R}^3} \left[ |v^{(k)}|^2 \Delta \phi_{y_0} + v^{(k)} \cdot \nabla \phi_{y_0} (|v^{(k)}|^2 + 2 p_{y_0}^{(k)}) \right] dy ds.
			\end{aligned}
		\end{equation}
	For $k$ sufficiently large such that $\frac{T}{\lambda^k}>T_0$ , by $\|v^{(k)}\|_{L_t^\infty L_{x_3}^{p_1} L_{x_h}^{p_2}(\RR^3 \times (-T_0,0))} =M$ we have
		\begin{align}
			& \int_{\mathbb{R}^3} \phi_{y_0} (y) |v^{(k)} (y, -T_0)|^2 dy \leqslant c(M), \\
			& \int_{-T_0}^{\tau} \int_{\mathbb{R}^3}  |v^{(k)}|^2 \Delta \phi_{y_0} dy ds \leqslant c(M,T_0).
		\end{align}
	By Young's inequality and H\"older inequality, we have
		\begin{equation}
			\begin{aligned}
				&\int_{-T_0}^{\tau} \int_{\mathbb{R}^3} |v^{(k)}|^3|\nabla \phi_{y_0}|dy ds \leqslant c_3 \gamma (\tau,k) \\
				&\leqslant c_2 c_3 \left( \int_{-T}^{\tau} \alpha^3(s,k) ds \right)^{\frac{1}{4}} \left( \beta(\tau,k) + \int_{-T}^{\tau} \alpha(s,k) ds \right)^{\frac{3}{4}}\\
				&\leqslant \frac{1}{10}\beta (\tau,k)+  c_1(M)\left( \int_{-T}^{\tau} \alpha^3(s,k)+\alpha(s,k) ds \right)d \tau\\
				&\leqslant \frac{1}{10}\beta (\tau,k)+  c_2(M).
			\end{aligned}
		\end{equation}
	For the last term on the right-hand side, we have
		\begin{align*}
			\int_{-T_0}^{\tau} \int_{\mathbb{R}^3} |p_{y_0}^{(k)}||v^{(k)}||\nabla \phi_{y_0}|dy ds \leqslant \int_{-T_0}^{\tau} \int_{\mathbb{R}^3} |p_{y_0}^{(k)}|^{\frac{3}{2}}|\nabla \phi_{y_0}|dy ds +\int_{-T_0}^{\tau} \int_{\mathbb{R}^3} |v^{(k)}|^3|\nabla \phi_{y_0}|dy ds.
		\end{align*}
	Using the estimate of $p^{1(k)}_{y_0}(y,\tau)$ and $p^{2(k)}_{y_0}(y,\tau)$, we have
		\begin{equation}
			\begin{aligned}
				&\int_{-T_0}^{\tau} \int_{\mathbb{R}^3} |p_{y_0}^{(k)}|^{\frac{3}{2}}|\nabla \phi_{y_0}|dy ds \\
				&\leqslant c_4 \left(\int_{-T_0}^{\tau} \int_{B\left(y_0, \frac{3}{2}\right)} |p_{y_0}^{1(k)}|^{\frac{3}{2}}dy ds+\int_{-T_0}^{\tau} \int_{B\left(y_0, \frac{3}{2}\right)} |p_{y_0}^{2(k)}|^{\frac{3}{2}}dy ds\right)\\
				&\leqslant c_3(M)\left(  \int_{-T_0}^{\tau} \int_{B(y_0,2)} |v^{(k)}|^3dy ds +  \int_{-T}^{\tau} \alpha^{\frac{3}{2}}(s,k) ds\right)\\
				&\leqslant \frac{1}{10}\beta (\tau,k)+  c_4(M).
			\end{aligned}
		\end{equation}
	By moving $\frac{1}{10}\beta (\tau,k) $ to the left-hand side, we can conclude that $\beta (0,k)+\sup_{\tau \in [-T_0,0]}\alpha (\tau,k)$ is bounded. And the upper bound is independent of $k$. Then by \eqref{L3dechazhi}, we  can conclude that $\gamma (0,k) $ is bounded. And the upper bound is also independent of $k$.
	\end{proof}



%%%%%%%%%%%%%%%%%%%%%%%收敛问题
	\subsection{Scaling limits}

Using Lemma \ref{prioriestimate}, we now establish the convergence of $v^{(k)}(y,\tau)$ and $p^{(k)}(y,\tau)$. Since this is standard theory, we omit detailed proves.
From Lemma \ref{prioriestimate}, for $\forall \, a>1 $ we have
	\begin{align}
		\sup_{\tau \in [-T_0, 0]}\|v^{(k)}(\cdot,\tau)\|_{L^2(B(a))}^2+\int_{-T_0}^{\tau}\int_{B(a)}|\nabla v^{(k)}(\bar{y},s)|^2d\bar{y}ds \leqslant c(M,a).
	\end{align}
Then we have
	\begin{align*}
		v^{(k)}(y,\tau) \in L^{\frac{10}{3}}\left(B(2a) \times [-T_0,0]\right) \quad \text{ and } \quad v^{(k)}\cdot \nabla v^{(k)} \in L^{\frac{5}{4}}\left(B(2a) \times [-T_0,0]\right).
	\end{align*}
So by the well known interior estimate of Stokes systems (which can be found in \cite{Seregin2002}), for $0<\varepsilon<T_0$, we have
	\begin{align} \label{yizhiestimate}
		\int_{-T_0+\varepsilon }^{0}\int_{B(a)}|v^{(k)}(\bar{y},s)|^{\frac{10}{3}}+|\partial_s v^{(k)}(\bar{y},s)|^{\frac{5}{4}}+|\nabla^2 v^{(k)}(\bar{y},s)|^{\frac{5}{4}}d\bar{y}ds \leqslant c_2(M,a).
	\end{align}
By Aubin-Lions Lemma (see in \cite{Seregin2015book}), we have
	\begin{align}
		&v^{(k)}(y,\tau) \weakstar u(y,\tau) \quad \text{ in } \quad L_{\tau}^\infty L_{y_3}^{p_1} L_{y_h}^{p_2} \left(\RR^3 \times [-T_0,0] \right), \label{Lpqconvergence}\\
		&v^{(k)}(y,\tau) \rightarrow  u(y,\tau) \quad \text{ in }  \quad L^3\left(B(a) \times [-T_0+\varepsilon,0]\right)  \label{L3convergence} ,\\
		&\nabla v^{(k)}(y,\tau) \rightharpoonup   \nabla u(y,\tau) \quad \text{ in }  \quad L^2\left(B(a) \times [-T_0+\varepsilon,0]\right)  \label{nablaL2convergence}, \\
		&v^{(k)}(y,\tau) \rightarrow  u(y,\tau) \quad \text{ in }  \quad C\left([-T_0+\varepsilon,0]; L^{\frac{5}{4}}(B(a))\right) . \label{L3convergence}
	\end{align}
By interpolation inequality and $\|v^{(k)}\|_{L_t^\infty L_{x_3}^{p_1} L_{x_h}^{p_2}(B(a) \times (-T_0,0))} \leqslant M <\infty $,  we have
	\begin{align}\label{continueL32convergence}
		v^{(k)}(y,\tau) \rightarrow  u(y,\tau) \quad \text{ in }  \quad C\left([-T_0+\varepsilon,0]; L^{\frac{3}{2}}(B(a))\right).
	\end{align}
Regarding the pressure, we obtain the following convergence result, for $\forall \, a>1 $ , there exists a function $c_a^{(k)}(\tau)$ that depends solely on time, and $c_a^{(k)}(\tau) \in L^{\frac{3}{2}}([-T_0,0])$ such that
	\begin{align}
		p_a^{(k)}(y,\tau)= p^{(k)}(y,\tau)-c_a^{(k)}(\tau) \rightharpoonup   q(y,\tau) \quad \text{ in }  \quad L^{\frac{3}{2}}\left(B(a) \times [-T_0+\varepsilon,0]\right).  \label{pconvergence}
	\end{align}

Following the approach of \cite{kikuchi2007}, we derive the following result, for $\forall \, a>1 $
	\begin{itemize}
		\item Regularity
			\begin{align}
				 \sup_{\tau \in [-T_0+\varepsilon, 0]}\|u(\cdot,\tau)\|_{L^2(B(a))}^2+\int_{-T_0+\varepsilon}^{\tau}\int_{B(a)}|\nabla u(\bar{y},s)|^2d\bar{y}ds \leqslant c(M,a) \label{uregularity},
			\end{align}
			\begin{align}
				q(y,\tau) \in L^{\frac{3}{2}}(-T_0+\varepsilon,0; L_{loc}^{\frac{3}{2}}(\RR^3)),
			\end{align}
			\begin{align}\label{upqnorm}
				\|u\|_{L_{\tau}^\infty L_{y_3}^{p_1} L_{y_h}^{p_2} \left(\RR^3 \times [-T_0,0] \right)}\leq M.
			\end{align}
		\item Weakly continuous
			\begin{align}
					\int_{\mathbb{R}^{3}} u(y, \tau_1) \cdot w(y) dy \rightarrow \int_{\mathbb{R}^{3}} u(y, \tau_2) \cdot w(y) dy.
	  			\end{align}
				for $\tau_1 \rightarrow \tau_2$ and any compactly supported $w(y) \in L^{2}(\mathbb{R}^{3}).$
		\item Satisfying the Navier-Stokes equations
				\begin{align*}
					& \partial_{\tau} u(y,\tau) + u(y,\tau)\cdot \nabla u(y,\tau) - \Delta u(y,\tau) + \nabla q(y,\tau) = 0, \quad \quad \operatorname{div}  u(y,\tau)=0.
				\end{align*}
			in $\RR^3 \times [-T_0+\varepsilon,0]$ and in the sense of distribution.
		\item The local representation of pressure \\
		For any $y_0 \in \RR^3$, there exists a function $c_{y_0}(\tau)$ that $c_{y_0}(\tau) \in L^{\frac{3}{2}}[-T_0+\varepsilon,0])$ such that for $y \in B(y_0,\frac{3}{2})$
		\begin{align}\label{qfenjie}
			q_{y_0}(y,\tau)=q(y,\tau)-c_{y_0}(\tau)=q^1_{y_0}(y,\tau)+q^2_{y_0}(y,\tau).
		\end{align}
		Where
		\begin{align}
			q^1_{y_0}(y,\tau)&=-\frac{1}{3}|u(y, \tau)|^{2}+\frac{1}{4 \pi} \int_{B(y_0,2)} K(y-\bar{y}): u(\bar{y}, \tau) \otimes u(\bar{y}, \tau) d \bar{y},\label{q1}\\
			q^2_{y_0}(y,\tau)&=\frac{1}{4 \pi} \int_{\RR^3\setminus B(y_0,2)} (K(y-\bar{y})-K(y_0-\bar{y})): u(\bar{y}, \tau) \otimes u(\bar{y}, \tau) d \bar{y}\label{q2}.
		\end{align}
		 And  the following estimate holds
		\begin{align}
			\left\|q_{y_0}^1(\cdot, \tau)\right\|_{L^{\frac{3}{2}}\left(B\left(y_0, \frac{3}{2}\right)\right)} & \leq c_1\left(\left\|u(\cdot, \tau)\right\|_{L^3\left(B\left(y_0, 2\right)\right)}^2 + 1\right),\label{q1estimate}\\
			\sup _{y \in B\left(y_{0}, \frac{3}{2}\right)}\left|q_{y_{0}}^2(y, \tau)\right| & \leq c_1\left(\left\|u(\cdot, \tau)\right\|_{L_2, \text { unif }}^{2}+1\right).\label{q2estimate}
		\end{align}

		\item Local energy inequality\\
		For all non-negative test function $\phi(y) \in  C_0^{\infty}(\RR^4  \times [-T_0, +\infty)$ , for all $\tau \in (-T,0)$,
		\begin{equation}\label{localei}
			\begin{aligned}
				&\int_{\RR^3} |u(y,\tau)|^2 \phi(y,\tau) dy + 2\int_{-T_0}^{\tau}\int_{\RR^3} |\nabla u(y,s)|^2 \phi(y,s) dy ds \\
				&\leq  \int_{-T_0}^{\tau}\int_{\RR^3} |u(y,s)|^2 \left(\partial_s \phi(y,s) + \Delta \phi(y,s)\right) + u(y,s)\cdot\nabla\phi(y,s)\left(|u(y,s)|^2 + 2q(y,s)\right) dy ds.
			\end{aligned}
		\end{equation}
	\end{itemize}

	\subsection{Decay estimates}
	To proceed, we must derive decay estimate for $u(y,\tau)$ and $q(y,\tau)$ when $|y|\to \infty$, which would ensure the desired regularity properties. The case $p_1=\infty , p_2=2$ presents difficulty since $u(y,\tau)$ lacks decay at spatial infinity in the $y_3$-direction. Consequently, we need to adapt our choice of test functions appropriately.

	Fix $k$ sufficiently large(such that $k>100$) and fix $R>3$. Let
		\begin{align*}
			&\Omega ^1=\{y \in \RR^3 : \quad y_3^2 \leqslant k^2(y_1^2+y_2^2) \quad \text{and}\quad |y|> 1\}, \\
			&\Omega ^2=\{y \in \RR^3 : \quad y_3^2 \leqslant  (k-1)^2(y_1^2+y_2^2) \quad \text{and}\quad |y|>2\},\\
			&\Omega_R^2=\{y \in \RR^3 : \quad y_3^2 \leqslant  (k-1)^2(y_1^2+y_2^2) \quad \text{and}\quad |y|>2R\},\\
			&\Omega_R^3=\{y \in \RR^3 : \quad y_3^2 \leqslant  (k-2)^2(y_1^2+y_2^2) \quad \text{and}\quad |y|>3R\}.
		\end{align*}
	Fix a Non-negative smooth function $\Phi (y)$ such that
		\begin{equation}
		\begin{cases}
			 0\leq \Phi(y)\leq 1 , \quad \forall \, y \in \RR^3 \, ;\\
			 \Phi(y)\equiv 1 , \quad \forall \,  y \in \Omega ^2 \,;\\
			 \Phi(y)\equiv 0 , \quad \forall \, y \in \RR^3 \setminus \Omega ^1.
		\end{cases}
	\end{equation}
	Let $\Phi_R(y)=\Phi(\frac{y}{R})$, where $R$ is sufficiently large. Then $\Phi_R(y) \equiv 1 $ in $\Omega_R^2$.  We set
		\begin{align}
			&\alpha_R (\tau,k)=\|\Phi_R(\cdot)u(\cdot,\tau)\|_{L_2, \text{unif}}^2 \, ,\\
			&\beta_R (\tau,k)= \sup_{y_0 \in \RR^3} \int_{-T_0}^{\tau}\int_{B(y_0,1)}|\Phi_R(\bar{y})\nabla u(\bar{y},s)|^2d\bar{y}ds,\\
			&\gamma_R (\tau,k)= \sup_{y_0 \in \RR^3} \int_{-T_0}^{\tau}\int_{B(y_0,1)}|\Phi_R(\bar{y}) u(\bar{y},s)|^3d\bar{y}ds,\\
			&\delta _R (\tau,k)= \sup_{y_0 \in \RR^3} \int_{-T_0}^{\tau}\int_{B(y_0,\frac{3}{2})}|\Phi_R(\bar{y}) q_{y_0}(\bar{y},s)|^{\frac{3}{2}}d\bar{y}ds.
		\end{align}
	by an argument paralleling the approach in \cite{LemarieRieset2002},  we can prove the following lemma
		\begin{lemma}\label{lemma2}
			The $u(y,\tau)$ and $q(y,\tau)$ have the following estimates
				\begin{align}
					\sup_{\tau \in [-T_0,0]}\alpha_R (\tau,k)+\beta_R (0,k)+\gamma_R^{\frac{2}{3}} (0,k)+\delta_R^{\frac{4}{3}} (0,k) \leqslant c_3(M)\left(\|\Phi_Ru(\cdot,-T_0)\|_{L_2, \text{unif}}^2+\frac{1}{R}\right).
				\end{align}
		\end{lemma}
		\begin{remark}
			By \eqref{upqnorm}, we have $$\lim_{R \to \infty} \left(\|\Phi_Ru(\cdot,-T_0)\|_{L_2, \text{unif}}^2+\frac{1}{R}\right)=0.  $$ so we obtain decay estimates for $u(y,\tau)$ in a quasi-conical region when $p_2=2$. When $p_2>2$ the decay estimates of $u(y,\tau)$  follows directly through \eqref{upqnorm}.
		\end{remark}

		\subsection{Contradiction Derivation}
	With these preparations, we are now ready to conclude the proof of our main theorem \ref{Main thm}. By Lemma \ref{lemma2}, for $R_0$ sufficiently large and $y_0 \in \Omega_{R_0}^2$
		\begin{align}
			\int_{-T_0}^{0}\int_{B(y_0,1)} |u(\bar{y},s)|^3+|q_{y_0}(\bar{y},s)|^{\frac{3}{2}}d\bar{y}ds<\varepsilon _0.
		\end{align}
	By  Lemma\ref{smallenergy-lin}, we know that $u(y,\tau)$ is regular in $\Omega_{R_0}^3 \times [-T_0+1,0]$.

	Let $\Omega_{T_0}^3=\Omega_{R_0}^3 \times [-T_0+1,0]$,  then for $n \in \NN_0$,  we have
		\begin{align}\label{regular-of-u}
			\max _{(y,\tau) \in \Omega_{T_0}^3 }|\nabla^n u(y,\tau)|\leq c_{1n}<\infty.
		\end{align}


	Now we make use of the vorticity $\omega(y,\tau)=\nabla \times u(y,\tau)$. It is easy to see that  in $\Omega_{T_0}^3$, the vorticity $\omega(y,\tau)$ satisfies the equation
			\begin{align}
				\partial_{\tau} \omega(y,\tau) + u(y,\tau)\cdot \nabla \omega(y,\tau)-\omega(y,\tau)\cdot \nabla u(y,\tau)-\Delta \omega(y,\tau)=0.
			\end{align}
	By \eqref{regular-of-u} , for $(y,\tau) \in \Omega_{T_0}^3$ we have
			\begin{align}
				|\partial_{\tau} \omega(y,\tau)-\Delta \omega(y,\tau)|\leqslant (c_{00}+c_{01})(| \omega(y,\tau)|+|\nabla \omega(y,\tau)|),
			\end{align}
			\begin{align}
				| \omega(y,\tau)| \leqslant c_{00}+c_{01} < +\infty.
			\end{align}
\\

Next, we claim that for $a.e. \, y \in \RR^3$
	 		\begin{align}
				u(y,0)\equiv 0.
			\end{align}
	To prove this fact, we note that $u \in C([-T_{2}+1, 0] ; L^{\frac{3}{2}}(B(a)))$ for any $a>1$,  by \eqref{continueL32convergence}, for $\forall \, y_0 \in \RR^3$
			\begin{align*}
				& (\int_{B(y_0, 1)}|u(y, 0)|^{\frac{3}{2}} d y)^{\frac{2}{3}} \\
				&  \leqslant(\int_{B(y_0, 1)}\left|v^{(k)}(y, 0)-u(y, 0)\right|^{\frac{3}{2}} d y)^{\frac{2}{3}}+(\int_{B(y_0, 1)}\left|v^{(k)}(y, 0)\right|^{\frac{3}{2}} d y)^{\frac{3}{2}} \\
				&  \leqslant\left\|v^{(k)}-u\right\|_{C(\left[-T_{2}+1, 0\right] ; L^{\frac{3}{2}}(B(y_0, 1)))}+c_6(\int_{ B(y_0, 1)}(\int_{ B(y_0, 1)}\left|v^{(k)}(y, 0)\right|^{p_2}d y_h)^\frac{p_1}{p_2}  d y_3)^{\frac{1}{p_1}} \\
				&  \leqslant\left\|v^{(k)}-u\right\|_{C(\left[-T_{2}+1, 0\right] ; L^{\frac{3}{2}}(B(y_0, 1)))}+c_6(\int_{ B(x_0+\lambda_k y_0, \lambda_k )}(\int_{ B(x_0+\lambda_k y_0, \lambda_k )}\left|v(x, 0)\right|^{p_2}d x_h)^\frac{p_1}{p_2}  d x_3)^{\frac{1}{p_1}}.\\
			\end{align*}
	Let $k \rightarrow \infty$ , for $\forall \, y_0 \in \RR^3$ , we have
			\begin{align*}
				\int_{B(y_0, 1)}|u(y, 0)|^{\frac{3}{2}} d y=0.
			\end{align*}

	Thus we have $u(y, 0)=0$  $a.e.$  $y \in \RR^3$. And $\omega (y,0)=\nabla \times u(y,0)=0$  for $y \in \Omega_{R_0}^3$.\\

	To apply the backward uniqueness principle, we select $k$ sufficiently large such that $ \Omega_{R_0}^3$ can contain a cone satisfying the conditions of Lemma \ref{Backward-uniqueness}. This can be easily achieved by taking, for instance, $k > 100$, since $2\arctan 100 \approx  179^\circ$ clearly satisfies Lemma \ref{Backward-uniqueness} .Then by Lemma \ref{Backward-uniqueness}, we conclude that
			\begin{align}
				\omega(y,\tau)\equiv  0 \quad \quad \text{for} \quad \forall \, (y,\tau) \in \Omega_{T_0}^3.
			\end{align}
	Note that  $v(x,t), p(x,t)$ is smooth in $\RR^3 \times (-T,0)$. So $u(y,\tau), q(y,\tau)$ is smooth in $\RR^3 \times (-T_0,0)$. Thus we can use unique continuation of heat operator (see Lemma \ref{unique-continuation}) and reach the following conclusion
			\begin{align}
				\omega(y,\tau)\equiv  0 \quad \quad \text{in} \quad \RR^3 \times [-T_0+1,0].
			\end{align}
	 By $\operatorname{div} u(y,\tau) = 0 $  and $\omega(y,\tau) =  0$ in $\RR^3 \times [-T_0+1,0]$. We have that $\Delta u(y,\tau)=0$ in $\RR^3 \times [-T_0+1,0)$. Note that \eqref{uregularity} and \eqref{upqnorm}. We get that
			\begin{align}
				u(y,\tau)\equiv  0 \quad \quad \text{in} \quad \RR^3 \times [-T_0+1,0).
			\end{align}
\\


	%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%最后的证明
	Finally, under the assumption that $(x_0,0)$ is a singular point, it means that
			\begin{align}
			 \sup _{-\lambda_{k}^{2} \leqslant t \leqslant 0} \frac{1}{\lambda_{k}^{\frac{3}{2}}} \int_{B\left(x_{0}, \lambda_{k}\right)}|v(x, t)|^{\frac{3}{2}} d x>\varepsilon_1.
		\end{align}
	We conclude that
		\begin{align}
			 \sup _{-1 \leqslant \tau \leqslant 0} \int_{B\left(0, 1\right)}|v^{(k)}(y,\tau)|^{\frac{3}{2}} d y>\varepsilon_1.
		\end{align}
	By \eqref{continueL32convergence} we get that
		\begin{align}
			 \sup _{-1 \leqslant \tau \leqslant 0} \int_{B\left(0, 1\right)}|u(y,\tau)|^{\frac{3}{2}} d y>\varepsilon_1.
		\end{align}
	This contradicts that $u(y,\tau)\equiv 0$ in  $\RR^3 \times [-T_0+1,0)$. Consequently, our initial assumption must be false, proving that no singularity exists at $t=0$.\\





