\section{Some Basic Facts on Sobolev Multipliers} \lb{s0}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

In this section, we recall some fundamental results on Sobolev multipliers. The Schwartz space of rapidly decreasing functions on $\bbR$ is denoted by $\cS(\bbR)$, and $\cS'(\bbR)$ denotes the corresponding set of tempered distributions.  The convention employed for the Fourier transform is:
\begin{equation}\lb{2.1}
\begin{split}
(\cF f)(\xi)\equiv \widehat f (\xi) = (2\pi)^{-1/2} \int_{\bbR} e^{-i\xi\cdot x} f(x)\, dx\, \text{ for a.e.~$\xi\in \bbR$},\\
\big(\cF^{-1} f\big)(x)\equiv \widecheck f (x) = (2\pi)^{-1/2} \int_{\bbR} e^{ix\cdot \xi} f(\xi)\, d\xi\, \text{ for a.e.~$x\in \bbR$}.
\end{split}
\end{equation}
In addition, the convolution is defined according to
\begin{equation}\lb{3.2c}
(f \ast g)(x) = \int_{\bbR} f(y)g(x-y)\, dy = \int_{\bbR} f(x-y)g(y)\, dy,
\end{equation}
and Young's inequality holds in the following form.

%%%%%%%%%%
\begin{theorem}[Young's Inequality]
Let $1\leq p,q,r\leq \infty$ with $p^{-1}+q^{-1} = 1 + r^{-1}$.  If $f\in L^p(\bbR)$ and $g\in L^q(\bbR)$ then $f\ast g\in L^r(\bbR)$ and
\begin{equation}
\|f\ast g\|_{L^r(\bbR)} \leq \|f\|_{L^p(\bbR)}\|g\|_{L^q(\bbR)}.
\end{equation}
\end{theorem}
%%%%%%%%%%

One notes that Young's inequality implies the following inclusions:
\begin{align}
L^1(\bbR)\ast L^1(\bbR)\subset L^1(\bbR),  \quad 
L^1(\bbR)\ast L^2(\bbR)\subset L^2(\bbR),  \quad 
L^2(\bbR)\ast L^2(\bbR)\subset L^{\infty}(\bbR).\no
\end{align}


For each $s\in \bbR$ and $p\in [1,\infty)$, the space of Bessel potentials $H^{s,p}(\bbR)$ is introduced as follows:
\begin{equation}
H^{s,p}(\bbR) = \bigg\{T\in \cS'(\bbR)\,\bigg|\, \Big[\big(1+|\cdot|^2\big)^{s/2}\widehat{T}\,\Big]^{\vee}
\in L^p(\bbR)\bigg\},\quad s\in \bbR,
\end{equation}
where the symbols\; $\widehat{}$\; and\; $\widecheck{}$\; denote the Fourier and inverse Fourier transforms of the distributions involved and $\big(1+|\cdot|^2\big)^{s/2}$ denotes the operator of multiplication by the smooth function $\bbR \ni x\mapsto \big(1+|x|^2\big)^{s/2}$.  The space $H^{s,p}(\bbR)$ is equipped with the norm $\|\cdot\|_{H^{s,p}(\bbR)}$ defined by
\begin{equation}
\|T\|_{H^{s,p}(\bbR)} = \bigg\|\Big[\big(1+|\cdot|^2\big)^{s/2}\widehat{T}\,\Big]^{\vee}\bigg\|_{L^p(\bbR)},\quad T\in H^{s,p}(\bbR),\, s\in \bbR.
\end{equation}

In the special case $p=2$, the shorthand notation $H^s(\bbR):=H^{s,2}(\bbR)$ will be used. Letting $H_0$ denote the self-adjoint realization of $-d^2/dx^2$ in $L^2(\bbR)$; that is,
\begin{equation}\lb{3.12c}
H_0f = - f'',\quad f\in \dom(H_0) = H^2(\bbR),
\end{equation}
so that $\dom\big(H_0^{1/2}\big) = H^1(\bbR)$, one verifies, upon comparison with the notation used in Section \ref{s2} (cf.\ \eqref{5.1}, \eqref{2.11}), that 
\begin{equation}
H^s(\bbR) = \cH_s\big(H_0^{1/2}\big), \quad s \in \bbR.
\end{equation}

 If $s>0$ and $f\in H^s(\bbR)$, then $\big(1+|\cdot|^2\big)^{s/2}\widehat{f}\in L^2(\bbR)$, so there exists $g\in L^2(\bbR)$ such that
\begin{equation}
{}_{\cS(\bbR)}\Big\langle \varphi, \big(1+|\cdot|^2\big)^{s/2}\widehat{f}\,\Big\rangle{}_{\cS'(\bbR)}= \int_{\bbR}\overline{\varphi(x)}g(x)\, dx,\quad \varphi\in \cS(\bbR).
\end{equation}
Furthermore, $\big(1+|\cdot|^2\big)^{-s/2}g\in L^2(\bbR)$ and
\begin{align}
\int_{\bbR} \overline{\varphi(x)}g(x) \big(1+|x|^2\big)^{-s/2}\, dx&= {}_{\cS(\bbR)}
\Big\langle \big(1+|\cdot|^2\big)^{-s/2}\varphi, \big(1+|\cdot|^2\big)^{s/2}\widehat{f}\,\Big\rangle{}_{\cS'(\bbR)}\no\\
&= {}_{\cS(\bbR)}\big\langle \varphi, \widehat{f}\,\big\rangle{}_{\cS'(\bbR)},\quad \varphi\in \cS(\bbR),
\end{align}
so that $\widehat{f} = \big(1+|\cdot|^2\big)^{-s/2}g\in L^2(\bbR)$ and, consequently, $f\in L^2(\bbR)$.  In addition,
\begin{align}
\|f\|_{L^2(\bbR)} = \big\|\widehat{f}\,\big\|_{L^2(\bbR)} \leq \Big\|\big(1+|\cdot|^2\big)^{s/2}\widehat{f}\,\Big\|_{L^2(\bbR)} = \|f\|_{H^s(\bbR)}.
\end{align}
Hence, one obtains the dense and continuous embedding 
\begin{equation}
H^s(\bbR) \hookrightarrow L^2(\bbR),\quad s\in (0,\infty),
\end{equation}
with the inequality
\begin{equation}
\|f\|_{L^2(\bbR)} \leq \|f\|_{H^s(\bbR)},\quad f\in H^s(\bbR).
\end{equation}

%%%%%
\begin{proposition}\lb{p2.1}
Let $n\in \bbN$.  If $\kappa\in (0,\infty)$, then
\begin{equation}
\big(H_0 + \kappa^2I_{L^2(\bbR)}\big)^{-1/2} \in \cB\big(H^{-1}(\bbR),L^2(\bbR)\big).
\end{equation}
\end{proposition}
%%%%%
\begin{proof}
In order to first show that $\big(H_0 + \kappa^2I_{L^2(\bbR)}\big)^{-1/2}$ maps from $H^{-1}(\bbR)$ to $L^2(\bbR)$, let $f\in H^{-1}(\bbR)$ so that $f\in \cS'(\bbR)$ and $\big(1+|\cdot|^2\big)^{-1/2}\widehat{f}\in L^2(\bbR)$.  Then
\begin{align}
\begin{split} 
&\Big[\big(H_0+\kappa^2I_{L^2(\bbR)}\big)^{-1/2}f\Big]\;\widehat{} 
 = \big(|\cdot|^2+\kappa^2\big)^{-1/2}\widehat{f}    \\
&\quad = \big(|\cdot|^2+\kappa^2\big)^{-1/2} \big(|\cdot|^2+1\big)^{1/2} \big(|\cdot|^2+1\big)^{-1/2}\widehat{f} \in L^2(\bbR),
\end{split} 
\end{align}
where the $L^2(\bbR)$ containment follows from the fact that $\big(|\dott|^2+1\big)^{-1/2}\widehat{f} \in L^2(\bbR)$ and the (smooth) function $\bbR\ni x\mapsto \big(|x|^2+\kappa^2\big)^{-1/2} 
\big(|x|^2+1\big)^{1/2}$ is bounded.  Therefore, $\big(H_0+\kappa^2I_{L^2(\bbR)}\big)^{-1/2}f\in L^2(\bbR)$ follows by taking inverse Fourier transforms.  The boundedness property is a consequence of Plancherel's theorem and the definition of $\|\cdot\|_{H^{-1}(\bbR)}$:
\begin{align}
\begin{split} 
& \Big\|\big(H_0+\kappa^2I_{L^2(\bbR)}\big)^{-1/2}f\Big\|_{L^2(\bbR)} = \Big\|\big(|\cdot|^2+\kappa^2\big)^{-1/2}\widehat{f}\,\Big\|_{L^2(\bbR)}     \\
& \quad \leq C(\kappa)\Big\|\big(|\cdot|^2+1\big)^{-1/2}\widehat{f}\,\Big\|_{L^2(\bbR)} 
= C(\kappa)\|f\|_{H^{-1}(\bbR)},\quad f\in H^{-1}(\bbR),
\end{split} 
\end{align}
where
\begin{equation}\lb{2.10}
C(\kappa):=\Big\|\big(|\cdot|^2+\kappa^2\big)^{-1/2} \big(|\cdot|^2+1\big)^{1/2}\Big\|_{L^{\infty}(\bbR)}=
\begin{cases}
\kappa^{-1},&\kappa\in (0,1),\\
1,&\kappa\in [1,\infty).
\end{cases}
\end{equation}
\end{proof}
%%%%%

%%%%%
\begin{proposition}\lb{p2.2}
Let $n\in \bbN$.  If $\kappa\in (0,\infty)$, then
\begin{equation}
\big(H_0 + \kappa^2I_{L^2(\bbR)}\big)^{-1/2} \in \cB\big(L^2(\bbR),H^1(\bbR)\big).
\end{equation}
\end{proposition}
%%%%%
\begin{proof}
To first show that $\big(H_0 + \kappa^2I_{L^2(\bbR)}\big)^{-1/2}$ maps from $L^2(\bbR)$ to $H^1(\bbR)$, let $f\in L^2(\bbR)$.  One then calculates
\begin{align}
& \big(|\cdot|^2+1\big)^{1/2}\Big[\big(H_0+\kappa^2I_{L^2(\bbR)}\big)^{-1/2}f\Big]\;\widehat{}\no\\
&\quad = \big(|\cdot|^2+1\big)^{1/2} \big(|\cdot|^2+\kappa^2\big)^{-1/2}\widehat{f}\in L^2(\bbR),
\end{align}
where the $L^2(\bbR)$ containment follows from the fact that $\widehat{f}\in L^2(\bbR)$ and the function $\bbR\ni x\mapsto \big(|x|^2+1\big)^{1/2} \big(|x|^2+\kappa^2\big)^{-1/2}$ is bounded.  Therefore, the inclusion $\big(H_0 + \kappa^2I_{L^2(\bbR)}\big)^{-1/2}f\in H^1(\bbR)$ holds.   The boundedness property follows from (repeated use of) Plancherel's theorem:
\begin{align}
& \Big\|\big(H_0 + \kappa^2I_{L^2(\bbR)}\big)^{-1/2}f \Big\|_{H^1(\bbR)} = \Big\|\big(|\cdot|^2+1\big)^{1/2} \big(|\cdot|^2+\kappa^2\big)^{-1/2}\widehat{f}\, \Big\|_{L^2(\bbR)}\no\\
&\quad \leq C(\kappa)\big\|\widehat{f}\,\big\|_{L^2(\bbR)} = C(\kappa)\|f\|_{L^2(\bbR)},\quad f\in L^2(\bbR),
\end{align}
with $C(\kappa)$ defined by \eqref{2.10}.
\end{proof}
%%%%%

%%%%%
\begin{remark}
With only minor modification, the same arguments used to prove Propositions \ref{p2.1} and \ref{p2.2} show that
\begin{equation}\lb{2.18aa}
\begin{split}
&\big(H_0 - zI_{L^2(\bbR)}\big)^{-1/2} \in \cB\big(H^{-1}(\bbR),L^2(\bbR)\big),\\
&\big(H_0 - zI_{L^2(\bbR)}\big)^{-1/2} \in \cB\big(L^2(\bbR),H^1(\bbR)\big),\quad z\in \bbC\backslash[0,\infty).
\end{split}
\end{equation}
In particular, 
\begin{equation}
H^1(\bbR) \hookrightarrow L^2(\bbR) = L^2(\bbR)^* \hookrightarrow H^{-1}(\bbR) = \big[H^1(\bbR)\big]^*. 
\end{equation}
\end{remark}
%%%%%

Next, we recall the concept of a Sobolev multiplier from $H^1(\bbR)$ to $H^{-1}(\bbR)$.  If $V\in \cS'(\bbR)$, then $V$ is a multiplier for $\cS(\bbR)$ in the following sense:  If $\varphi\in \cS(\bbR)$, then $V\varphi\in \cS'(\bbR)$, where $V\varphi$ is defined according to
\begin{align}\lb{2.18a}
{}_{\cS(\bbR)}\langle \psi, V\varphi \rangle_{\cS'(\bbR)} := {}_{\cS(\bbR)}\langle \overline{\varphi}\psi, V\rangle_{\cS'(\bbR)},\quad \psi \in \cS(\bbR).
\end{align}
In particular, $\mathfrak{q}_V$ defined by
\begin{equation}\lb{2.19aaaa}
\mathfrak{q}_V[\psi,\varphi] := {}_{\cS(\bbR)}\langle \psi, V\varphi \rangle_{\cS'(\bbR)},\quad \varphi,\psi \in \cS(\bbR),
\end{equation}
is a well-defined sesquilinear form on $\cS(\bbR)$.

%%%%%%%%%%
\begin{definition}\lb{def_multiplier}
The tempered distribution $V\in \cS'(\bbR)$ is called a Sobolev multiplier from $H^1(\bbR)$ to $H^{-1}(\bbR)$ if $\mathfrak{q}_V$, defined on $\cS(\bbR)$ by \eqref{2.19aaaa}, continuously extends from $\cS(\bbR)$ to $H^1(\bbR)$; that is, if
\begin{equation}\lb{2.18}
|\mathfrak{q}_V[\psi,\varphi]| \leq C_V \|\psi\|_{H^1(\bbR)}\|\varphi\|_{H^1(\bbR)},\quad \varphi,\psi\in \cS(\bbR),
\end{equation}
for some $C_V\in (0,\infty)$.
\end{definition}
%%%%%%%%%%

One notes that when \eqref{2.18} holds, $\mathfrak{q}_V$ may be extended to a bounded sesquilinear form, which we denote by $\widetilde{\mathfrak{q}}_V$, on $H^1(\bbR)$ by taking
\begin{equation}\lb{2.19}
\widetilde{\mathfrak{q}}_V[g,f] := \lim_{n\to \infty} \mathfrak{q}_V[\psi_n,\varphi_n],\quad f,g\in H^1(\bbR),
\end{equation}
where $\{\varphi_n\}_{n=1}^{\infty},\{\psi_n\}_{n=1}^{\infty}\subset \cS(\bbR)$ are any sequences such that
\begin{equation}
\lim_{n\to \infty}\|\varphi_n-f\|_{H^1(\bbR)} = \lim_{n\to \infty}\|\psi_n-g\|_{H^1(\bbR)} = 0.
\end{equation}
The definition in \eqref{2.19} is independent of the sequences $\{\varphi_n\}_{n=1}^{\infty},\{\psi_n\}_{n=1}^{\infty}\subset \cS(\bbR)$ chosen and \eqref{2.18} remains valid for the extension:
\begin{equation}\lb{2.21}
|\widetilde{\mathfrak{q}}_V[g,f]| \leq C_V \|g\|_{H^1(\bbR)}\|f\|_{H^1(\bbR)},\quad f,g\in H^1(\bbR).
\end{equation}
In the following, the symbol $\cM\big(H^1(\bbR),H^{-1}(\bbR)\big)$ denotes the set of all Sobolev multipliers from $H^1(\bbR)$ to $H^{-1}(\bbR)$.

If $V\in \cM\big(H^1(\bbR),H^{-1}(\bbR)\big)$, then the distributional pairing on the left-hand side in \eqref{2.18a} extends to $H^1(\bbR)$ as follows:
\begin{equation}
{}_{H^1(\bbR)}\langle g,Vf\rangle{}_{H^{-1}(\bbR)} = \widetilde{\mathfrak{q}}_V[g,f],\quad f,g\in H^1(\bbR).
\end{equation}
The multiplier operator defined by
\begin{equation}
H^1(\bbR)\ni f \mapsto Vf\in H^{-1}(\bbR)
\end{equation}
is linear and bounded by \eqref{2.21} since
\begin{equation}\lb{2.25a}
\|Vf\|_{H^{-1}(\bbR)} = \sup_{g\in H^1(\bbR)\backslash\{0\}}\frac{|\wti{\mathfrak{q}}_V[g,f]|}{\|g\|_{H^1(\bbR)}} \leq C_V\|f\|_{H^1(\bbR)},\quad f\in H^1(\bbR).
\end{equation}
In particular, the operator of multiplication by $V$ is bounded from $H^1(\bbR)$ to $H^{-1}(\bbR)$ with
\begin{equation}\lb{2.26a}
\|V\|_{\cB(H^1(\bbR),H^{-1}(\bbR))}\leq C_V.
\end{equation}
We note that, in a slight abuse of notation, we use the symbol ``$V$'' in \eqref{2.26a} (and elsewhere) to denote the operator of multiplication by $V\in \cM\big(H^1(\bbR),H^{-1}(\bbR)\big)$.

Every $V\in H^{-1}(\bbR)$ is a Sobolev multiplier from $H^1(\bbR)$ to $H^{-1}(\bbR)$; that is, $V$ belongs to $\cM\big(H^1(\bbR),H^{-1}(\bbR)\big)$.  This fact, which we prove for completeness below in Proposition \ref{p2.7}, relies on the following algebraic property of the $H^1(\bbR)$ norm.

%%%%%%%%%%
\begin{lemma}\lb{l2.7a}
If $\varphi,\psi\in \cS(\bbR)$, then $\|\varphi\psi\|_{H^1(\bbR)}^2\leq 2\|\varphi\|_{H^1(\bbR)}^2\|\psi\|_{H^1(\bbR)}^2$.
\end{lemma}
%%%%%%%%%%
\begin{proof}
The one-dimensional Sobolev inequality (see, e.g., \cite[Theorem 8.5]{LL01}) yields:
\begin{equation}\lb{2.36aa}
2\|\varphi\|_{L^{\infty}(\bbR)}^2\leq \|\varphi\|_{H^1(\bbR)}^2,\quad \varphi\in \cS(\bbR).
\end{equation}
If $\varphi,\psi\in \cS(\bbR)$, then basic estimates combined with \eqref{2.36aa} yield:
\begin{align}
\|\varphi\psi\|_{H^1(\bbR)}^2 &= \int_{\bbR} \big\{ |\varphi\psi|^2 + |(\varphi\psi)'|^2\big\}\, dx\no\\ 
&\leq \int_{\bbR}\big\{2|\psi|^2\big[|\varphi|^2+|\varphi'|^2 \big] + 2|\varphi|^2\big[|\psi|^2+|\psi'|^2 \big] \big\}\, dx\no\\
&\leq \int_{\bbR}\big\{\|\psi\|_{H^1(\bbR)}^2\big[|\varphi|^2+|\varphi'|^2 \big] + \|\varphi\|_{H^1(\bbR)}^2\big[|\psi|^2+|\psi'|^2 \big] \big\}\, dx\no\\
&= 2\|\varphi\|_{H^1(\bbR)}^2\|\psi\|_{H^1(\bbR)}^2.
\end{align}
\end{proof}
%%%%%%%%%%

%%%%%%%%%%
\begin{proposition}\lb{p2.7}
If $V\in H^{-1}(\bbR)$, then $V\in \cM\big(H^1(\bbR),H^{-1}(\bbR)\big)$ and
\begin{equation}\lb{2.35a}
\|V\|_{\cB(H^1(\bbR),H^{-1}(\bbR))}\leq 2^{1/2}\|V\|_{H^{-1}(\bbR)}.
\end{equation}
\end{proposition}
%%%%%%%%%%
\begin{proof}
If $\varphi,\psi\in \cS(\bbR)$, then Lemma \ref{l2.7a} (applied to $\overline{\psi}$ and $\varphi$) implies
\begin{align}
|\mathfrak{q}_V[\psi,\varphi]| &= \big|{}_{H^1(\bbR)}\langle \overline{\varphi}\psi,V\rangle_{H^{-1}(\bbR)}\big| \leq \|V\|_{H^{-1}(\bbR)}\|\overline{\varphi}\psi\|_{H^1(\bbR)}\no\\
&\leq 2^{1/2} \|V\|_{H^{-1}(\bbR)} \|\varphi\|_{H^1(\bbR)} \|\psi\|_{H^1(\bbR)}.
\end{align}
Hence, \eqref{2.18} holds with $C_V=2^{1/2}\|V\|_{H^{-1}(\bbR)}$.  Finally, \eqref{2.35a} follows from \eqref{2.26a}.
\end{proof}
%%%%%%%%%%

For additional results on multipliers on Sobolev spaces see, for instance, \cite{BS17}, \cite{BS19}, \cite{NS99}, \cite{NS06}. 

Proposition \ref{p2.7} provides an elementary sufficient condition for a distribution to be a Sobolev multiplier from $H^1(\bbR)$ to $H^{-1}(\bbR)$. Recalling the notion of locally uniformly $L^p$-integrable, $p\in [1,\infty)$,
functions on $\bbR$,
\begin{equation}\lb{4.5}
\begin{split}
L^p_{\locunif}(\bbR; dx) = \bigg\{f \in L^p_{\loc}(\bbR; dx) \,\bigg|\,
\sup_{a\in\bbR} \bigg(\int_a^{a+1} dx \, |f(x)|^p\bigg) < \infty\bigg\},&\\
p\in[1,\infty),&
\end{split}
\end{equation} 
a complete characterization of the Sobolev multipliers from $H^1(\bbR)$ to $H^{-1}(\bbR)$ is given as follows (see also the summary in \cite[Sect.~3]{GW14}).

%%%%%%%%%%
\begin{theorem}[{\cite{BS02}, \cite[Sects.~2.5, 11.4]{MS09}, \cite{MV02a}, \cite{MV05}}]
The following statements $(i)$--$(iii)$ hold:\\[1mm]
$(i)$ $V \in \cS'(\bbR)$ belongs to $\cM\big(H^1(\bbR),H^{-1}(\bbR)\big)$ if and only if $V$ is of the form
\begin{equation}
V=q_1+q_2',\quad \text{where $q_j\in L_{\locunif}^j(\bbR)$, $j=1,2$}.    \lb{4.6}
\end{equation}
In addition to \eqref{4.6}, $V$ is compact as a Sobolev multiplier from $H^1(\bbR)$ to $H^{-1}(\bbR)$ if and only if
\begin{equation}
\lim_{|a|\to \infty} \int_a^{a+1} |q_j(x)|^j\, dx = 0,\quad j=1,2.
\end{equation}
$(ii)$ $V\in \cS'(\bbR)$ belongs to $\cM\big(H^1(\bbR),H^{-1}(\bbR)\big)$ if and only if $V$ is of the form
\begin{equation}
V=q_\infty+q_2',\quad \text{where $q_\infty\in L^{\infty}(\bbR),\, q_2\in L_{\locunif}^2(\bbR)$}.
\end{equation}
$(iii)$ $V\in \cS'(\bbR)$ belongs to $\cM\big(H^1(\bbR),H^{-1}(\bbR)\big)$ if and only if $V$ is of the form
\begin{equation}
V=q_0+q_2',\quad \text{where $q_0, q_2\in L_{\loc}^2(\bbR)$}.
\end{equation}
\end{theorem}
%%%%%%%%%%

By the results of Propositions \ref{p2.1} and \ref{p2.2}, if $V\in \cS'(\bbR)$ is a Sobolev multiplier from $H^1(\bbR)$ to $H^{-1}(\bbR)$, then
\begin{equation}\lb{2.32}
\big(H_0+\kappa^2I_{L^2(\bbR)}\big)^{-1/2}V\big(H_0+\kappa^2I_{L^2(\bbR)}\big)^{-1/2}\in \cB\big(L^2(\bbR)\big),\quad \kappa\in (0,\infty).
\end{equation}

It is clear that all results in this appendix hold for $\bbR$ replaced by $\bbR^n$, $n\in \bbN$, upon suitable modifications. 

