\begin{remark}
For $\lambda\in (-\infty,0)$, the functions $f_{\lambda}:[0,\infty)\to \bbR$ defined by $f_{\lambda}(x) = x^{1/2}(x-\lambda)^{-1/2} = x^{1/2}(x+|\lambda|)^{-1/2}$, $x\in [0,\infty)$ satisfies
\begin{equation}
\|f_{\lambda}\|_{L^{\infty}([0,\infty))} = 1,\quad \lambda\in (-\infty,0).
\end{equation}
In addition, for $\lambda\in (-\infty,0)$, the function $g_{\lambda}:[0,\infty)\to \bbR$ defined by $g_{\lambda}(x) = (x-\lambda)^{-1/2} = (x+|\lambda|)^{-1/2}$, $x\in [0,\infty)$ satisfies
\begin{equation}
\|g_{\lambda}\|_{L^{\infty}([0,\infty))} = |\lambda|^{-1/2},\quad \lambda\in (-\infty,0).
\end{equation}
Thus,
\begin{equation}
\begin{split}
\big\|H_0^{1/2}\big(H_0 - \lambda I_{\cH} \big)^{-1/2} \big\|_{\cB(\cH)} = 1,\quad \big\|\big(H_0 - \lambda I_{\cH} \big)^{-1/2}\big\|_{\cB(\cH)} = |\lambda|^{-1/2},&\\
\lambda\in (-\infty,0).&
\end{split}
\end{equation}
In particular (cf.~\eqref{5.10z}),
\begin{equation}
\lim_{\substack{\lambda\to -\infty \\ \lambda\in \bbR}} M(\lambda) = 1
\end{equation}
\hfill$\diamond$
\end{remark}
