A special but important case of nonnegative closed forms is obtained as
follows:

%%%%%%%
\begin{theorem} \lb{tF.1.8}
Assume that $T\colon \dom(T)\to\cH_2$, $\dom(T)\subseteq \cH_1$, is a densely defined
operator. Consider the nonnegative form $\gga_T\colon \dom(T)\times \dom(T)\to\bbC$ defined by
\begin{equation}
\gga_T(u,v)=(Tu,Tv)_{\cH_2}, \quad u, v \in\dom(T).   \lb{F.42}
\end{equation}
Then the form $\gga_T$ is closed $($resp., closable\,$)$ in $\cH_1$ if and only if $T$ is closed
$($resp., closable\,$)$. If $T$ is closable, then the closure $\gga_T^{cl}$ of $\gga_T$ is given by
\begin{equation}
\gga_T^{cl}(u,v) = \big(\ol T u, \ol T v\big)_{\cH_2}, \quad u, v \in\dom\big({\ol T}\big).   \lb{F.42a}
\end{equation}
If $T$ is closed, the unique nonnegative self-adjoint operator associated
with $\gga_T$ in $\cH_1$ equals $T^*T\geq 0$. $($In particular, $T$ closed and densely defined implies
that $T^* T \geq 0$ is self-adjoint, and $\dom(T^* T)$ is an operator core for $T$, a theorem due to von Neumann.$)$ In this case one obtains in addition to \eqref{F.42},
\begin{equation}
\gga_T(u,v) = (|T|u,|T|v)_{\cH_1}, \quad u, v \in\dom(T)=\dom(|T|).   \lb{F.43}
\end{equation}
\end{theorem}
%%%%%%%

%%%%%%%
\begin{corollary} $(${\rm von Neumann's Theorem}.$)$ \lb{cF.1.9} 
Suppose that $T$ is a densely defined and closed operator in $\cH$. Then $T^* T \geq 0$ and $T^* T$ is self-adjoint in $\cH$.
\end{corollary}
%%%%%%%

%%%%%%%
\begin{remark} \lb{rF.1.10} In connection with Theorem \ref{tF.1.8} and Corollary \ref{cF.1.9} we now briefly sketch Nelson's elegant argument for von Neumann's theorem: Consider the supersymmetric Dirac-type operator (also known as a supercharge, see \eqref{B.4.15}), 
\begin{equation}
Q = \begin{pmatrix}  0 & T^* \\ T & 0 \end{pmatrix}, \quad \dom (Q) = \dom(T) \oplus \dom(T^*), 
\end{equation}
in $\cH_1 \oplus \cH_2$. Then $Q$ is self-adjoint and so is
\begin{equation}
Q^2 = \begin{pmatrix}  T^* T & 0 \\ 0 & T T^* \end{pmatrix} \geq 0,
\end{equation}
implying Corollary \ref{cF.1.9}. In addition, $\dom\big(Q^2\big)$ is a core for $Q$ and hence, $\dom(T^*T)$ is a core for $T$ and $\dom(TT^*)$ is a core for $T^*$.
\hfill $\diamond$
\end{remark}
%%%%%%%

Actually, one has the following converse of von Neumann's theorem:

%%%%%%%
\begin{theorem} \lb{tF.1.10a}
Assume that $T\colon \dom(T)\to\cH_2$, $\dom(T)\subseteq \cH_1$, is a densely defined operator. Then the following items
$(i)$ and $(ii)$ are equivalent\,$:$ \\[1mm]
$(i)$ $T$ is closed. \\[1mm]
$(ii)$ $T^*T$ and $TT^*$ are $($nonnegative\,$)$ self-adjoint operators in $\cH_1$ and $\cH_2$, respectively.
\end{theorem}
%%%%%%%

%%%%%%%
\begin{remark} \lb{rF.1.10A}
It should be noted that it can happen that if $T$ is densely defined and closable in $\cH$, but not closed, that $T^* T$
is self-adjoint in $\cH$. Such an example can be constructed as follows: Let $A$ be densely defined, closed, and
unbounded in $\cH$ and define $T = S\big|_{\dom(A^*A)}$. Then $T$ is closable, but not closed. Since $\dom(A^*A)$
is a core for $A$, one infers that $T^* = A^*$. On the other hand, $\dom(A^*A) = \dom(A)$ holds if and only if $A$
is bounded (see the Notes for Section \ref{sF.1}) and hence $A = \ol{T} \neq T$ and $T^*T = A^*A$
with the latter being self-adjoint by von Neumann's theorem, Corollary \ref{cF.1.9}.
\hfill $\diamond$
\end{remark}
