\section{On Fourier Transforms} \lb{sA}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

Let $n\in \bbN$ be fixed.  If $f\in L^1(\bbR^n)$, then its Fourier transform $\widehat{f}$ and inverse Fourier transform $\widecheck{f}$ are according to:
\begin{equation}
\begin{split}
(\cF f)(\xi) \equiv \widehat{f}(\xi) &= \frac{1}{(2\pi)^{n/2}}\int_{\bbR^n} e^{-i\xi\cdot x}f(x)\, d^nx,\quad \xi\in \bbR^n,\\
\big(\cF^{-1} f\big)(x) \equiv \widecheck{f}(x) &= \frac{1}{(2\pi)^{n/2}}\int_{\bbR^n} e^{ix\cdot \xi} f(\xi)\, d^n\xi,\quad x\in \bbR^n.
\end{split}
\end{equation}
Recall that
\begin{equation}\lb{A.2}
\big\| \widehat{f}\,\big\|_{L^{\infty}(\bbR^n)} \leq \|f\|_{L^1(\bbR^n)},\quad f\in L^1(\bbR^n),
\end{equation}
and $\widehat{f}$ is continuous with $\lim_{|\xi|\to\infty}f(\xi)=0$.

Furthermore, for functions in $L^2(\bbR)$,
\begin{align}
(\cF f)(\xi) &\equiv \widehat{f}(\xi) = (2 \pi)^{-n/2} \LIM_{R\rightarrow \infty} \int_{|x| \leq R} 
e^{- i \xi \cdot x}f(x)\, d^nx,     \no \\
\big(\cF^{-1} f\big)(x) &\equiv \widecheck{f}(x) = (2 \pi)^{-n/2} \LIM_{R\rightarrow \infty} \int_{|\xi| \leq R} 
e^{i x \cdot \xi} f(\xi)\, d^n\xi,\quad f\in L^2(\bbR),      \lb{A.1}
\end{align}
where $\LIM_{R\rightarrow \infty}$ denotes the limit in the norm of $L^2(\bbR^n)$, respectively, in $L^2(\bbR^n)$.  Thus defined, the Fourier transform $\cF$ is a unitary operator in $L^2(\bbR^n)$ with inverse equal to $\cF^{-1}$.  In particular,
\begin{equation}\lb{A.4}
\big\|\widehat{f}\, \big\|_{L^2(\bbR^n)} = \|f\|_{L^2(\bbR^n)},\quad f\in L^2(\bbR^n).
\end{equation}

We recall Young's inequality for convolutions (see, e.g., \cite[Ex.~1, p.~28--29]{RS75}):
%%%%%%%%%%
\begin{lemma}[Young's Inequality]
Let $n\in \bbN$ and $1\leq p,q,r\leq \infty$ with $p^{-1}+q^{-1} = 1 + r^{-1}$.  If $f\in L^p(\bbR^n)$ and $g\in L^q(\bbR^n)$, then the convolution $f\ast g$ of $f$ and $g$ defined by
\begin{equation}\lb{A.5c}
(f\ast g)(x) = \int_{\bbR^n} f(x')g(x-x')\, d^nx'\, \text{ for a.e.~$x\in \bbR^n$}
\end{equation}
satisfies $f\ast g\in L^r(\bbR^n)$ and
\begin{equation}
\|f\ast g\|_{L^r(\bbR^n)} \leq \|f\|_{L^p(\bbR^n)}\|g\|_{L^q(\bbR^n)}.
\end{equation}
\end{lemma}
%%%%%%%%%%

In addition, we recall the convolution theorem for Schwartz functions in the following form (see, e.g., \cite[Theorem IX.3]{RS75})
%%%%%%%%%%
\begin{theorem}\lb{lA.2}
If $f,g\in \cS(\bbR^n)$, then
\begin{equation}
\cF(f\ast g)=(2\pi)^{n/2}(\cF f)\cdot (\cF g)\quad \text{and}\quad \cF^{-1}(f\ast g) = (2\pi)^{n/2} (\cF^{-1}f)\cdot(\cF^{-1}g).
\end{equation}
\end{theorem}
%%%%%%%%%%

The convolution theorem, originally stated for Schwartz functions, extends as follows.
%%%%%%%%%%
\begin{theorem}\lb{tA.3}
Let $n\in \bbN$.  The following statements hold.\\[1mm]
$(i)$ If $f,g\in L^2(\bbR^n)$, then $f\ast g\in L^{\infty}(\bbR^n)$ and
\begin{equation}\lb{A.7}
f\ast g = (2\pi)^{n/2} \cF\big\{(\cF^{-1}f)\cdot(\cF^{-1}g) \big\}.
\end{equation}
$(ii)$ If $f\in L^2(\bbR^n)$ and $g\in L^1(\bbR^n)$, then $f\ast g\in L^2(\bbR^n)$ and
\begin{equation}\lb{A.9z}
\widehat{f\ast g} = (2\pi)^{n/2} \widehat{f}\widehat{g}.
\end{equation}
\end{theorem}
%%%%%%%%%%
\begin{proof}
Let $n\in \bbN$.  To prove $(i)$, let $f,g\in L^2(\bbR^n)$.  Young's inequality with $p=q=2$ and $r=\infty$ implies $f\ast g\in L^{\infty}(\bbR^n)$.  It remains to prove \eqref{A.7}.  Since $\cF^{-1}f,\cF^{-1}g\in L^2(\bbR^n)$, H\"older's inequality implies $\big(\cF^{-1}f\big)\cdot\big(\cF^{-1}g \big)\in L^1(\bbR^n)$.  Thus, $\cF\big\{\big(\cF^{-1}f\big)\cdot\big(\cF^{-1}g \big)\big\}$ is well-defined and belongs to $L^{\infty}(\bbR^n)$.  To prove the equality in \eqref{A.7}, choose sequences $\{f_j\}_{j=1}^{\infty}, \{g_j\}_{j=1}^{\infty}\subset \cS(\bbR^n)$ such that
\begin{equation}
\lim_{j\to \infty}\|f_j-f\|_{L^2(\bbR^n)} = 0 = \lim_{j\to \infty} \|g_j-g\|_{L^2(\bbR^n)}.
\end{equation}
Applying the inequality in \eqref{A.2}, H\"older's inequality, and the unitary property of $\cF^{-1}$, one obtains
\begin{align}
&\big\|\cF\big\{\big(\cF^{-1}f_j\big)\cdot\big(\cF^{-1}g_j \big)\big\} - \cF\big\{\big(\cF^{-1}f\big)\cdot\big(\cF^{-1}g \big)\big\} \big\|_{L^{\infty}(\bbR^n)}\no\\
&\quad\leq \big\|\big(\cF^{-1}f_j\big)\cdot\big(\cF^{-1}g_j \big) - \big(\cF^{-1}f\big)\cdot\big(\cF^{-1}g \big) \big\|_{L^1(\bbR^n)}\no\\
&\quad\leq \|f_j - f\|_{L^2(\bbR^n)}\|g_j \|_{L^2(\bbR^n)} + \|f \|_{L^2(\bbR^n)}\|g_j - g\|_{L^2(\bbR^n)},\quad j\in \bbN.\lb{A.10}
\end{align}
In particular, \eqref{A.10} implies
\begin{equation}
\lim_{j\to \infty} \big\|\cF\big\{\big(\cF^{-1}f_j\big)\cdot\big(\cF^{-1}g_j \big)\big\} - \cF\big\{\big(\cF^{-1}f\big)\cdot\big(\cF^{-1}g \big)\big\} \big\|_{L^{\infty}(\bbR^n)} = 0,
\end{equation}
or equivalently, by Lemma \ref{lA.2},
\begin{equation}\lb{A.12}
\lim_{j\to \infty} \big\|(2\pi)^{-n/2}f_j\ast g_j - \cF\big\{\big(\cF^{-1}f\big)\cdot\big(\cF^{-1}g \big)\big\} \big\|_{L^{\infty}(\bbR^n)} = 0.
\end{equation}
On the other hand,
\begin{align}
&\|(f_j\ast g_j) - (f\ast g) \|_{L^{\infty}(\bbR^n)}\no\\
&\quad\leq \|(f_j-f)\ast g_j\|_{L^{\infty}(\bbR^n)} + \|f\ast (g_j - g) \|_{L^{\infty}(\bbR^n)}\no\\
&\quad\leq \|f_j-f\|_{L^2(\bbR^n)}\|g\|_{L^2(\bbR^n)} + \|f\|_{L^2(\bbR^n)}\|g_j-g\|_{L^2(\bbR^n)},\quad j\in \bbN,
\end{align}
which implies
\begin{equation}\lb{A.14}
\lim_{j\to \infty} \big\|(2\pi)^{-n/2}(f_j\ast g_j) - (2\pi)^{-n/2}(f\ast g) \big\|_{L^{\infty}(\bbR^n)}=0.
\end{equation}
By uniqueness of limits, \eqref{A.12} and \eqref{A.14} imply \eqref{A.7}.

The proof of $(ii)$ is entirely analogous to the proof of $(i)$, with only minor modifications required.  For $f\in L^2(\bbR^n)$ and $g\in L^1(\bbR^n)$, Young's inequality with $p=2$, $q=1$, and $r=2$ implies $f\ast g\in L^2(\bbR^n)$.  In particular $\cF(f\ast g)$ is well-defined and belongs to $L^2(\bbR^n)$.  One chooses $\{f_j\}_{j=1}^{\infty},\{g_j\}_{j=1}^{\infty}\subset \cS(\bbR^n)$ such that
\begin{equation}
\lim_{j\to \infty}\|f_j-f\|_{L^2(\bbR^n)} = 0 = \lim_{j\to \infty}\|g_j-g\|_{L^1(\bbR^n)}.
\end{equation}
Therefore, $f_j\ast g_j \in L^2(\bbR^n)$, $j\in \bbN$, and
\begin{align}
&\|\cF(f_j\ast g_j) - \cF(f\ast j) \|_{L^2(\bbR^n)}\no\\
&\quad=\|(f_j\ast g_j) - (f\ast j) \|_{L^2(\bbR^n)}\no\\
&\quad\leq \|(f_j-f)\ast g_j\|_{L^2(\bbR^n)} + \|f\ast (g_j-g)\|_{L^2(\bbR^n)}\lb{A.17}\\
&\quad\leq \|f_j-f\|_{L^2(\bbR^n)}\|g_j\|_{L^1(\bbR^n)} + \|f\|_{L^2(\bbR^n)}\|g_j-g\|_{L^1(\bbR^n)},\quad j\in \bbN.\no
\end{align}
In addition,
\begin{align}
&\big\|(\cF f_j)(\cF g_j)-(\cF f)(\cF g) \big\|_{L^2(\bbR^n)}\lb{A.18}\\
&\quad\leq \big\|\big(\cF f_j-\cF f\big)(\cF g_j) \big\|_{L^2(\bbR^n)} + \big\|(\cF f)(\cF g_j-\cF g) \big\|_{L^2(\bbR^n)}\no\\
&\quad\leq \big\|\cF(f_j-f) \big\|_{L^2(\bbR^n)}\big\|\cF g_j \big\|_{L^{\infty}(\bbR^n)} + \|\cF f\|_{L^2(\bbR^n)}\big\|\cF(g_j-g) \big\|_{L^{\infty}(\bbR^n)}\no\\
&\quad\leq \big\|f_j-f \big\|_{L^2(\bbR^n)}\|g_j \|_{L^1(\bbR^n)} + \| f\|_{L^2(\bbR^n)}\big\|g_j-g \big\|_{L^1(\bbR^n)},\quad j\in \bbN.\no
\end{align}
Theorem \ref{lA.2} implies $\cF(f_j\ast g_j) = (2\pi)^{n/2} (\cF f_j)\cdot (\cF g_j)$, $j\in \bbN$.  Therefore, \eqref{A.17} and \eqref{A.18}, combined with uniqueness of limits, yield \eqref{A.9z}.
\end{proof}
%%%%%%%%%%

The following result is useful for calculating certain double integrals in momentum space (cf., e.g., \cite[p.~13]{Si71}).

%%%%%%%%%%
\begin{lemma}\lb{l2.9}
Let $n\in \bbN$.  If $f,g,\in L^2(\bbR^n)$ and $h\in L^1(\bbR^n)$, then
\begin{equation}
\int_{\bbR^n\times \bbR^n} \ol{f(x)}h(x-x')g(x')\, d^nx\, d^nx' = (2\pi)^{n/2} \int_{\bbR^n}\ol{\widehat{f}(\xi)}\widehat{h}(\xi)\widehat{g}(\xi)\, d^n\xi.
\end{equation}
\end{lemma}
%%%%%%%%%%
\begin{proof}
Under the hypothesis on $f$, $g$, and $h$, the convolution theorem (Theorem \ref{tA.3} $(ii)$) implies:
\begin{align}
\int_{\bbR^n\times \bbR^n} \ol{f(x)}h(x-x')g(x')\, d^nx\, d^nx' &= \int_{\bbR^n} \ol{f(x)}(h\ast g)(x)\, d^nx\\
&= \int_{\bbR^n} \ol{\widehat{f}(\xi)}\widehat{(h\ast g)}(\xi)\, d^n\xi\no\\
&= (2\pi)^{n/2} \int_{\bbR^n}\ol{\widehat{f}(\xi)}\widehat{h}(\xi)\widehat{g}(\xi)\, d^n\xi.\no
\end{align}
\end{proof}
%%%%%%%%%%

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\section{The Second Form Representation Theorem} \lb{sB}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

In this appendix we hint at a more general construction of the triple 
\begin{equation}
\cH_1(H_0) \hookrightarrow \cH = \cH^* \hookrightarrow \cH_{-1}(H_0) = \big[\cH_1(H_0)\big]^*,
\end{equation} 
associated with a self-adjoint, nonnegative operator $H_0$ in $\cH$ by initially replacing $\cH_1(H_0)$ and $\cH_{-1}(H_0) = \big[\cH_1(H_0)\big]^*$ by an appropriate reflexive Banach space $\cV$ and it's conjugate dual $\cV^*$.

Let $\cH$ be a complex, separable Hilbert space with scalar product
$(\dott,\dott)_{\cH}$ (antilinear in the first and linear in the second
argument), $\cV$ a reflexive Banach space continuously and densely embedded
into $\cH$, in particular, there exists a constant $C_{\cV} \in (0,\infty)$ such that
\begin{equation}
\|u\|_{\cH} \leq C_{\cV} \|u\|_{\cV}, \quad u \in \cV.     \lb{F.0}
\end{equation}
Then also $\cH$ embeds continuously and densely into $\cV^*$,
that is,
\begin{equation}
\cV  \hookrightarrow \cH = \cH^* \hookrightarrow \cV^*.     \lb{F.1}
\end{equation}
Here the continuous embedding $\cH\hookrightarrow \cV^*$ is accomplished via
the identification
\begin{equation}
\cH \ni v \mapsto (\dott,v)_{\cH} \in \cV^*,     \lb{F.2}
\end{equation}
and we use the convention in this manuscript that if $X$ denotes a Banach space,
$X^*$ denotes the {\it adjoint space} of continuous  conjugate linear functionals on $X$, also known as the {\it conjugate dual} of $X$.

In particular, if the sesquilinear form
\begin{equation}
{}_{\cV}\langle \dott, \dott \rangle_{\cV^*} \colon \cV \times \cV^* \to \bbC
\end{equation}
denotes the duality pairing between $\cV$ and $\cV^*$, then
\begin{equation}
{}_{\cV}\langle u,v\rangle_{\cV^*} = (u,v)_{\cH}, \quad u\in\cV, \;
v\in\cH\hookrightarrow\cV^*,   \lb{F.3}
\end{equation}
that is, the $\cV, \cV^*$ pairing ${}_{\cV}\langle \dott,\dott \rangle_{\cV^*}$ is compatible with the
scalar product $(\dott,\dott)_{\cH}$ in $\cH$.

Let $T \in\cB(\cV,\cV^*)$. Since $\cV$ is reflexive, $(\cV^*)^* = \cV$, one has
\begin{equation}
T \colon \cV \to \cV^*, \quad  T^* \colon \cV \to \cV^*   \lb{F.4}
\end{equation}
and
\begin{equation}
{}_{\cV}\langle u, Tv \rangle_{\cV^*}
= {}_{\cV^*}\langle T^* u, v\rangle_{(\cV^*)^*}
= {}_{\cV^*}\langle T^* u, v \rangle_{\cV}
= \ol{{}_{\cV}\langle v, T^* u \rangle_{\cV^*}}, \quad u, v \in \cV.
\end{equation}

%%%%%%
\begin{definition} \lb{dF1.1}
Suppose that $T \in\cB(\cV,\cV^*)$. \\[1mm]
Then {\it self-adjointness} of $T$ is defined by $T=T^*$, that is, 
\begin{equation}
{}_{\cV}\langle u,T v \rangle_{\cV^*}
= {}_{\cV^*}\langle T u, v \rangle_{\cV}
= \ol{{}_{\cV}\langle v, T u \rangle_{\cV^*}}, \quad u, v \in \cV.     \lb{F.5}
\end{equation}
{\it Nonnegativity} of $T$ is defined by 
\begin{equation}
{}_{\cV}\langle u, T u \rangle_{\cV^*} \geq 0, \quad u \in \cV.    \lb{F.6}
\end{equation}
Finally, {\it boundedness from below of $T$ by $c_T \in\bbR$} is defined by 
\begin{equation}
{}_{\cV}\langle u, T u \rangle_{\cV^*} \geq c_T \|u\|^2_{\cH},
\quad u \in \cV.
\lb{F.6a}
\end{equation}
\end{definition}
%%%%%%

One notes that by \eqref{F.3}, \eqref{F.6a} is equivalent to
\begin{equation}
{}_{\cV}\langle u, T u \rangle_{\cV^*} \geq c_T \,
{}_{\cV}\langle u, u \rangle_{\cV^*}, \quad u \in \cV.
\end{equation}

%%%%%%
\begin{definition} \lb{dF.1.2} 
Let $\gga(\dott,\dott)\colon \cV \times \cV \to \bbC$ be a sesquilinear form in $\cH$ $($antilinear in the first and linear in the second argument\,$)$. With a bit of abuse of notation we will identify $\cV$ and the domain, $\dom(\gga)$, of $\gga$ in the following.
\\[1mm]
$(i)$ The form $\gga$ is called {\it $\cV$-bounded} if there exists a $c_{\gga}>0$ such that 
\begin{equation}
|\gga(u,v)| \le c_{\gga} \|u\|_{\cV} \|v\|_{\cV},  \quad u, v \in \cV.
\end{equation}
$(ii)$ The form $\gga$ is called {\it symmetric}, if 
\begin{equation}
\gga(u,v) = \ol{\gga(v,u)},  \quad u,v\in \cV.    \lb{F.9}
\end{equation}
$(iii)$ The form $\gga$ is called {\it $\cV$-coercive} if there exists a constant $C_0>0$ such that 
\begin{equation}
\gga(u,u)  \geq C_0 \|u\|^2_{\cV}, \quad u\in\cV.     \lb{F.10}
\end{equation}
\end{definition}
%%%%%%

%%%%%%
\begin{theorem} \lb{tF.1.3}
Suppose that $\gga(\dott,\dott)\colon\cV \times \cV \to \bbC$ is $\cV$-bounded and define
$\wti A$ by
\begin{equation}
\wti A \colon \begin{cases} \cV \to \cV^*, \\
\, v \mapsto \wti A v = \gga(\dott,v).  \end{cases}    \lb{F.7}
\end{equation}
Then $\wti A$ satisfies
\begin{equation}
\wti A \in\cB(\cV,\cV^*) \, \text{ and } \,
{}_{\cV}\big\langle u, \wti A v \big\rangle_{\cV^*}
= \gga(u,v), \quad  u, v \in \cV.    \lb{F.8}
\end{equation}
Assuming, in addition, that the form $\gga$ is symmetric and $\cV$-coercive, then
\begin{equation}
\wti A \colon \cV \to \cV^* \, \text{ is bounded, self-adjoint, and boundedly
invertible.}    \lb{F.11}
\end{equation}
Moreover, denoting by $A$ the part of $\wti A$ in $\cH$ defined by
\begin{align}
\dom(A) = \big\{u\in\cV \,|\, \wti A u \in \cH \big\} \subseteq \cH, \quad
A= \wti A\big|_{\dom(A)}\colon \dom(A) \to \cH,   \lb{F.12}
\end{align}
then $A$ is a $($possibly unbounded\,$)$ self-adjoint operator in $\cH$ satisfying $($cf.\ \eqref{F.0} and \eqref{F.10}$)$
\begin{align}
& A \geq \big[C_0\big/C_{\cV}^2\big] I_{\cH},   \lb{F.13}  \\
& \dom\big(A^{1/2}\big) = \cV.  \lb{F.14}
\end{align}
In particular,
\begin{equation}
A^{-1} \in\cB(\cH).   \lb{F.15}
\end{equation}
\end{theorem}
%%%%%%%

The facts \eqref{F.8}--\eqref{F.15} are a consequence of the Lax--Milgram theorem.

Next we temporarily permit possibly nondensely defined sesquilinear forms.

%%%%%%%
\begin{definition} \lb{dF.1.4}
Let $\cD \subseteq \cH$ be a linear subspace and consider the sesquilinear
form $\gb(\dott,\dott) \colon \cD\times\cD\to\bbC$ in $\cH$ $($again, antilinear in the first and linear
in the second argument\,$)$.
\\[1mm]
$(i)$ Then $\gb$ is called {\it symmetric}, if 
\begin{equation}
\gb(u,v) = \ol{\gb(v,u)},  \quad u,v\in \cD.    \lb{F.18}
\end{equation}
$(ii)$ The form $\gb$ is called {\it bounded from below} if there exists a constant $c_{\gb}\in\bbR$ such that 
\begin{equation}
\gb(u,u) \geq c_{\gb} \|u\|_{\cH}^2, \quad u\in\cD.  \lb{F.19}
\end{equation}
$\gb$ is called {\it strictly positive} if $c_{\gb} > 0$ and {\it nonnegative} if $\gb(u,u) \geq 0$, $u \in \cD$. 
\\[1mm]
$(iii)$ Assume the form $\gb$ is bounded from below with constant $c_{\gb}\in\bbR$ as in \eqref{F.19}.
Introducing the scalar product $(\dott,\dott)_{\cD_{\gb}}\colon \cD\times\cD\to\bbC$
$($and the associated norm $\|\, \cdot \,\|_{\cD_{\gb}}$$)$ by
\begin{equation}
(u,v)_{\cD_{\gb}} = \gb(u,v) + (1- c_{\gb})(u,v)_{\cH}, \quad u,v\in\cD,  \lb{F.20}
\end{equation}
turns $\cD$ into a pre-Hilbert space $(\cD; (\dott,\dott)_{\cD_{\gb}})$, which we denote by
$\cD_{\gb}$. The form $\gb$ is called {\it closed} in $\cH$ if $\cD_{\gb}$ is actually
complete, and hence a Hilbert space. 
\\[1mm]
$(iv)$ Suppose that the form $\gb$ is bounded from below in $\cH$. Then $\gb$ is called {\it closable} in $\cH$ if it has a closed extension in $\cH$. 
The smallest closed extension of $\gb$ is called the {\it closure} of $\gb$ and denoted by\footnote{We recall our use of the symbol $\gb^{cl}$ rather than $\ol{\gb}$ for the closure of the sesquilinear form $\gb$ to avoid any confusion with the operation of complex conjugation as employed in item $(i)$.} $\gb^{cl}$.
\end{definition}
%%%%%%%

If $\gb_j(\dott,\dott) \colon \cD_j\times\cD_j \to \bbC$ are sesquilinear forms in $\cH$, $j=1,2$,
then $\gb_1$ is a restriction of $\gb_2$, denoted by $\gb_1 \subseteq \gb_2$ if 
\begin{equation}
\cD_1 \subseteq \cD_2 \, \text{ and } \, \gb_1(u,v) = \gb_2(u,v), \; u, v \in \cD_1.
\end{equation}
(In this case $\gb_2$ is a extension of $\gb_1$, denoted by $\gb_2 \supseteq \gb_1$.) 

Returning to forms defined on $\cV$, assume that $\gb(\dott,\dott)\colon\cV \times \cV \to \bbC$ is bounded from below with constant $c_{\gb}\in\bbR$ as in \eqref{F.19}, and closed in $\cH$. Then\footnote{The notation $\cV_{\gb}$ corresponds to $\cD_{\gb}$ as introduced in Definition \ref{dF.1.4}\,$(iii)$.}
\begin{equation}
|\gb(u,v) + (1- c_{\gb})(u,v)_{\cH}| \le \|u\|_{\cV_{\gb}} \|v\|_{\cV_{\gb}},
\quad u,v\in \cV,
\lb{F.21}
\end{equation}
and
\begin{equation}
|\gb(u,u) + (1 - c_{\gb})\|u\|_{\cH}^2| = \|u\|_{\cV_{\gb}}^2, \quad u \in \cV,
\lb{F.22}
\end{equation}
imply that the form $\gb(\dott,\dott)+(1 - c_{\gb})(\dott,\dott)_{\cH}$ is a
symmetric, $\cV$-bounded, and $\cV$-coercive sesquilinear form in $\cH$. Hence,
by \eqref{F.7} and \eqref{F.8}, there exists a linear map
\begin{equation}
\wti B_{c_{\gb}} \colon \begin{cases} \cV_{\gb} \to \cV_{\gb}^*, \\
\hspace*{.17cm}
v \mapsto \wti B_{c_{\gb}} v = \gb(\dott,v) +(1 - c_{\gb})(\dott,v)_{\cH},
\end{cases}
\lb{F.23}
\end{equation}
with
\begin{equation}
\wti B_{c_{\gb}} \in\cB(\cV_{\gb},\cV_{\gb}^*) \, \text{ and } \,
{}_{\cV_{\gb}}\big\langle u, \wti B_{c_{\gb}} v \big\rangle_{\cV_{\gb}^*}
= \gb(u,v)+(1 -c_{\gb})(u,v)_{\cH}, \quad  u, v \in \cV.    \lb{F.24}
\end{equation}

%%%%%%%
\begin{theorem} \lb{tF.1.5}
Let the form $\gb(\dott,\dott)\colon \cV\times\cV\to\bbC$ be symmetric, bounded from below with constant $c_{\gb}\in\bbR$ as in \eqref{F.19}, and closed in $\cH$. Define $\wti B_{c_{\gb}}$ as in \eqref{F.23}, \eqref{F.24}  and introduce the linear map
\begin{equation}
\wti B = \wti B_{c_{\gb}} + (c_{\gb} - 1)\wti I \colon \cV_{\gb}\to\cV_{\gb}^*,
\lb{F.24a}
\end{equation}
where $\wti I\colon \cV_{\gb}\hookrightarrow\cV_{\gb}^*$ denotes
the continuous inclusion $($embedding\,$)$ map of $\cV_{\gb}$ into $\cV_{\gb}^*$.
Then restricting $\wti B$ to $\cH$ yields a $($possibly unbounded\,$)$self-adjoint operator
$B$ in $\cH$,
\begin{align}
\dom(B) = \big\{u\in\cV \,\big|\, \wti B u \in \cH \big\} \subseteq \cH, \quad
B= \wti B\big|_{\dom(B)}\colon \dom(B) \to \cH,   \lb{F.25}
\end{align}
satisfying the following properties:
\begin{align}
& B = B^* \geq c_{\gb} I_{\cH},  \lb{F.26} \\
& \dom\big(|B|^{1/2}\big) = \dom\big((B - c_{\gb}I_{\cH})^{1/2}\big)
= \cV,  \lb{F.27} \\
& \gb(u,v) = \big(|B|^{1/2}u, U_B |B|^{1/2}v\big)_{\cH}    \lb{F.28b} \\
& \hspace*{.97cm}
= \big((B - c_{\gb}I_{\cH})^{1/2}u, (B - c_{\gb}I_{\cH})^{1/2}v\big)_{\cH} + c_{\gb} (u, v)_{\cH}
\lb{F.28} \\
& \hspace*{.97cm}
= {}_{\cV_{\gb}}\big\langle u, \wti B v \big\rangle_{\cV_{\gb}^*},
\quad u, v \in \cV, \lb{F.28a} \\
& \gb(u,v) = (u, Bv)_{\cH}, \quad  u\in \cV, \; v \in\dom(B),  \lb{F.29} \\
& \dom(B) = \{v\in\cV\,|\, \text{there exists an $f_v\in\cH$ such that}  \no \\
& \hspace*{3cm} \gb(w,v)=(w,f_v)_{\cH} \text{ for all $w\in\cV$}\},
\lb{F.30} \\
& Bu = f_u, \quad u\in\dom(B),  \no \\
& \dom(B) \text{ is dense in $\cH$ and in $\cV_{\gb}$}.  \lb{F.31}
\end{align}
Properties \eqref{F.30} and \eqref{F.31} uniquely determine $B$.
Here $U_B$ in \eqref{F.28} is the partial isometry in the polar
decomposition of $B$, that is,
\begin{equation}
B=U_B |B| = \sgn(B) |B|, \quad |B|=(B^*B)^{1/2}.   \lb{F.32}
\end{equation}
\end{theorem}
%%%%%%%

Theorem \ref{tF.1.5} comprises the {\it second representation theorem of forms}. 

%%%%%%%
\begin{definition} \lb{dF.1.6}
The operator $B$ defined in \eqref{F.25} is called the {\it operator associated with the form $\gb$}. 
\end{definition}
%%%%%%%

One recalls that the norm in the complex, separable Hilbert space $\cV_{\gb}^*$ is given by
\begin{equation}
\|\ell\|_{\cV_{\gb}^*} = \sup \{|{}_{\cV_{\gb}}\langle u, \ell \rangle_{\cV_{\gb}^*}| \,|\,
\|u\|_{\cV_{\gb}} \le 1\}, \quad \ell \in \cV_{\gb}^*,   \lb{F.34}
\end{equation}
with associated scalar product,
\begin{equation}
(\ell_1,\ell_2)_{\cV_{\gb}^*}
= {}_{\cV_{\gb}}\big\langle
\big(\wti B+(1-c_{\gb})\wti I\,\big)^{-1}
\ell_1, \ell_2 \big\rangle_{\cV_{\gb}^*},
\quad \ell_1, \ell_2 \in \cV_{\gb}^*.   \lb{F.35}
\end{equation}

%%%%%%%
\begin{corollary} \lb{cF.1.7}
Let $\wti B$ be given as in \eqref{F.24a}. Then
\begin{equation}
\big\|\big(\wti B + (1 - c_{\gb})\wti I\,\big)v \big\|_{\cV_{\gb}^*}
= \|v\|_{\cV_{\gb}}, \quad v\in\cV,   \lb{F.36}
\end{equation}
and the Riesz representation theorem yield
\begin{equation}
\big(\wti B+(1-c_{\gb})\wti I\,\big)\in\cB(\cV_{\gb},\cV_{\gb}^*) \,
\text{ and }\big(\wti B + (1 - c_{\gb})\wti I\,\big) \colon \cV_{\gb}
\to \cV_{\gb}^* \, \text{ is unitary.}   \lb{F.37}
\end{equation}
In addition,
\begin{align}
\begin{split}
{}_{\cV_{\gb}}\big\langle u,\big(\wti B
+ (1 - c_{\gb})\wti I\,\big) v \big\rangle_{\cV_{\gb}^*}
& = \big(\big(B+(1-c_{\gb})I_{\cH}\big)^{1/2}u,
\big(B+(1-c_{\gb})I_{\cH}\big)^{1/2}v \big)_{\cH}  \\
& = (u,v)_{\cV_{\gb}},  \quad  u, v \in \cV_{\gb}.   \lb{F.38}
\end{split}
\end{align}
In particular,
\begin{equation}
\big\|(B+(1-c_{\gb})I_{\cH})^{1/2}u\big\|_{\cH} = \|u\|_{\cV_{\gb}},
\quad u \in \cV_{\gb},   \lb{F.39}
\end{equation}
and hence
\begin{equation}
(B+(1-c_{\gb})I_{\cH})^{1/2}\in\cB(\cV_{\gb},\cH) \, \text{ and }
(B + (1 - c_{\gb})I_{\cH})^{1/2} \colon \cV_{\gb} \to \cH \, \text{ is unitary.}
\lb{F.40}
\end{equation}
\end{corollary}
%%%%%%%

We briefly supplement \eqref{F.19}--\eqref{F.40} with some considerations that point out mapping properties of $\big(\wti B+(1-c_{\gb})\wti I\,\big)^{\pm 1/2}$ on a scale of spaces,
which, for simplicity, we temporarily restrict to the triple of spaces $\cV_{\gb}^{}$, $\cH$, and $\cV_{\gb}^*$. We start by defining
\begin{equation}
\big(\hatt B_{c_{\gb}} + (1-c_{\gb}) \hatt I\,\,\big)^{1/2} \colon \begin{cases} \cV_{\gb}^{} \to \cH, \\
\, v \mapsto (B + (1 - c_{\gb}) I_{\cH})^{1/2} v,
\end{cases}        \lb{F.48a}
\end{equation}
and similarly,
\begin{equation}
\big(\widecheck B_{c_{\gb}} + (1-c_{\gb}) \widecheck I\,\big)^{1/2} \colon \begin{cases}
\cH \to \cV_{\gb}^*, \\
\, f \mapsto \gb \big(\dott, (B + (1 - c_{\gb}) I_{\cH})^{-1/2} f\big) \\
\qquad \; + (1 - c_{\gb}) \big(\dott, (B + (1 - c_{\gb}) I_{\cH})^{-1/2} f \big)_{\cH}.
\end{cases}         \lb{F.49a}
\end{equation}
Then both maps in \eqref{F.48a} and \eqref{F.49a} are bounded and boundedly invertible.
In particular,
\begin{align}
\begin{split}
&\big(\hatt B_{c_{\gb}} + (1-c_{\gb}) \hatt I\,\,\big)^{1/2} \in \cB(\cV_{\gb}^{},\cH), \quad
\big(\hatt B_{c_{\gb}} + (1-c_{\gb}) \hatt I\,\,\big)^{-1/2} \in \cB(\cH,\cV_{\gb}^{}),     \lb{F.50a} \\
&\big(\widecheck B_{c_{\gb}} + (1-c_{\gb}) \widecheck I\,\big)^{1/2} \in \cB(\cH,\cV_{\gb}^*),  \quad
\big(\widecheck B_{c_{\gb}} + (1-c_{\gb}) \widecheck I\,\big)^{-1/2} \in \cB(\cV_{\gb}^*,\cH),
\end{split}
\end{align}
and
\begin{align}
& \big(\hatt B_{c_{\gb}} + (1-c_{\gb}) \hatt I\,\,\big)^{1/2}
\big(\widecheck B_{c_{\gb}} + (1-c_{\gb}) \widecheck I\,\big)^{1/2}
= \big(\wti B+(1-c_{\gb})\wti I\,\,\big) \in \cB(\cV_{\gb}^{},\cV_{\gb}^*),    \no \\
& \big(\widecheck B_{c_{\gb}} + (1-c_{\gb}) \widecheck I\,\big)^{-1/2}
\big(\hatt B_{c_{\gb}} + (1-c_{\gb}) \hatt I\,\,\big)^{-1/2}
= \big(\wti B+(1-c_{\gb})\wti I\,\,\big)^{-1} \in \cB(\cV_{\gb}^*,\cV_{\gb}^{}).   \lb{F.51a}
\end{align}
Due to self-adjointness of $\wti B$ as a bounded map from $\cV_{\gb}^{}$ to $\cV_{\gb}^*$
in the sense of \eqref{F.5}, one finally obtains that
\begin{align}
\begin{split}
&\Big(\big(\hatt B_{c_{\gb}} + (1-c_{\gb}) \hatt I\,\big)^{\pm 1/2}\Big)^*
= \big(\widecheck B_{c_{\gb}} + (1-c_{\gb}) \widecheck I\,\big)^{\pm 1/2},   \\
& \Big(\big(\widecheck B_{c_{\gb}} + (1-c_{\gb}) \widecheck I\,\big)^{\pm 1/2}\Big)^*
= \big(\hatt B_{c_{\gb}} + (1-c_{\gb}) \hatt I\,\,\big)^{\pm 1/2}.    \lb{F.52a}
\end{split}
\end{align}
Hence, in the bulk of this paper we will follow standard practice in connection with chains of
(Sobolev) spaces and refrain from painstakingly distinguishing the\, $\hatt B$-, 
$\widecheck B$-, and $\wti B$-operations and simply resort to the simplified notation
\begin{equation}
(B+(1-c_{\gb}) I )^{\pm 1/2}      \lb{F.53a}
\end{equation}
for the operators in \eqref{F.50a}.

%%%%%%%
\begin{remark} \lb{rF.1.11}
If the sesquilinear form $\gb$ is bounded from below with constant $c_{\gb}\in\bbR$ as in \eqref{F.19},
and closed in $\cH$, then by \eqref{F.21} and \eqref{F.22}, the form
$\gb(\dott,\dott)+(1 - c_{\gb})(\dott,\dott)_{\cH}$ is symmetric, $\cV$-bounded, and $\cV$-coercive
in $\cH$. Conversely, if the sesquilinear form $\gga$ is symmetric, $\cV$-bounded, and $\cV$-coercive, then $\gga$ is densely defined, strictly positive, and closed in $\cH$. \hfill $\diamond$
\end{remark}
%%%%%%%

%%%%%%%
\begin{theorem} \lb{tF.1.8A}
Assume that $T$ is symmetric and bounded from below in $\cH$ $($and hence densely defined in $\cH$ and closable$)$. Let $\gb_T\colon \dom(T)\times \dom(T)\to\bbC$ be the semibounded form defined by
\begin{equation}
\gb_T(u,v)=(u,Tv)_{\cH}, \quad u, v \in\dom(T).   \lb{F.42A}
\end{equation}
Then the form $\gb_T$ is closable in $\cH$. In addition, 
\begin{equation}
\gb_T^{cl} = \gb_{\ol T}^{cl}.      \lb{F.42B}
\end{equation}
\end{theorem}
%%%%%%%

In the special case where $S$ is self-adjoint, $S=S^*$, boundedness from below is not required and one obtains for the closure of 
\begin{equation}
\gs_S(u,v)=(u,Sv)_{\cH}, \quad u, v \in\dom(S),   \lb{F.42C}
\end{equation}
the result
\begin{equation}
\gs_S^{cl}(u,v)=\big(|S|^{1/2}u,\sgn(S)|S|^{1/2}v\big)_{\cH}, \quad u, v \in 
\dom\big(\gs_S^{cl}\big)=\dom\big(|S|^{1/2}\big),   \lb{F.42D}
\end{equation}
with $S= U_S |S| = \sgn(S)|S|$ the polar decomposition of $S$. 


%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\section{One-Dimensional Relativistic Hamiltonians \\ and Some Trace Calculations} \lb{sC}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

In this appendix we record various trace calculations related to the Birman--Schwinger operator for both massless and massive relativistic Hamiltonians with potentials in the Schwartz class $\cS(\bbR)$.

\subsection{The Massless Relativistic Hamiltonian}
Consider the free massless relativistic Hamiltonian,
\begin{equation}
H_{rel,0} = H_0^{1/2},
\end{equation}
defined via Fourier transforms as follows:
\begin{equation}
\begin{split}
&H_{rel,0} f = \cF^{-1}\big[|\dott|(\cF f)\big],\\
&f\in \dom\big(H_{rel,0}\big)=\big\{g\in L^2(\bbR)\,\big|\, |\dott| (\cF g) \in L^2(\bbR)\big\} = H^1(\bbR).
\end{split}
\end{equation}
If $V\in \cS(\bbR)$ is factored according to \eqref{3.18z}, then \cite[Ch.~4]{Si05} implies
\begin{equation}\lb{3.50}
\big(H_0^{1/2}+\kappa I_{L^2(\bbR)}\big)^{-1/2}u, \, v\big(H_0^{1/2}+\kappa I_{L^2(\bbR)}\big)^{-1/2}\in \cB_4\big(L^2(\bbR)\big),\quad \kappa\in(0,\infty).
\end{equation}
In particular,
\begin{align}
&A_V^{rel,0}(-\kappa):=-\big(H_0^{1/2}+\kappa I_{L^2(\bbR)}\big)^{-1/2}V\big(H_0^{1/2}+\kappa I_{L^2(\bbR)}\big)^{-1/2}\in \cB_2\big(L^2(\bbR)\big),\no\\
&\hspace*{9cm} \kappa\in(0,\infty),\lb{3.51}
\end{align}
and
\begin{equation}\lb{3.52}
A_V^{rel,0}(-\kappa)^*A_V^{rel,0}(-\kappa)\in \cB_1\big(L^2(\bbR)\big),\quad \kappa\in (0,\infty).
\end{equation}

%%%%%%%%%%
\begin{remark}
In \eqref{3.50} the trace ideal $\cB_4\big(L^2(\bbR)\big)$ may be replaced by $\cB_3\big(L^2(\bbR)\big)$.  Therefore, $\cB_2\big(L^2(\bbR)\big)$ may be replaced by $\cB_{3/2}\big(L^2(\bbR)\big)$ in \eqref{3.51}.\hfill$\diamond$
\end{remark}
%%%%%%%%%%

The operator $\cF A_V^{rel,0}(-\kappa)\cF^{-1}$, $\kappa\in (0,\infty)$, is an integral operator with integral kernel
\begin{equation}
\begin{split}
\big[\cF A_V^{rel,0}(-\kappa)\cF^{-1}\big](\xi,\xi') = -(2\pi)^{-1/2} (|\xi|+\kappa)^{-1/2} 
\widehat{V}(\xi-\xi')(|\xi'|+\kappa)^{-1/2},&\\
\xi,\xi'\in \bbR.&
\end{split}
\end{equation}
In addition, the operator
\begin{equation}
\begin{split}
\cF A_V^{rel,0}(-\kappa)^*A_V^{rel,0}(-\kappa)\cF^{-1} = \big[\cF A_V^{rel,0}(-\kappa)^*\cF^{-1}\big]\big[\cF A_V^{rel,0}(-\kappa)\cF^{-1}\big],&\\
\kappa\in (0,\infty),&
\end{split}
\end{equation}
is an integral operator with integral kernel
\begin{align}
&\big[\cF A_V^{rel,0}(-\kappa)^*A_V^{rel,0}(-\kappa)\cF^{-1}\big](\xi,\xi')\\
&\quad = (2\pi)^{-1} (|\xi|+\kappa)^{-1/2}\no\\
&\qquad \times\int_{\bbR} \Big\{\overline{\widehat{V}(\xi''-\xi)} \big(|\xi''|+\kappa\big)^{-1}\widehat{V}(\xi''-\xi') 
(|\xi'|+\kappa)^{-1/2}\Big\}\, d\xi'',\quad \xi,\xi'\in \bbR.\no
\end{align}
Hence, one calculates:
\begin{align}
\big\|A_V^{rel,0}(-\kappa)\big\|_{\cB_2(L^2(\bbR))}^2 &= \tr_{L^2(\bbR)}\big(A_V^{rel,0}(-\kappa)^*A_V^{rel,0}(-\kappa) \big)\no\\
&= \tr_{L^2(\bbR)}\big(\cF A_V^{rel,0}(-\kappa)^*A_V^{rel,0}(-\kappa)\cF^{-1} \big)\no\\
&= \frac{1}{2\pi} \int_{\bbR}\Bigg\{(|\xi|+\kappa)^{-1}\int_{\bbR}\frac{\big|\widehat{V}(\xi''-\xi) \big|^2}{|\xi''|+\kappa}\, d\xi'' \Bigg\}\,d\xi\no\\
&= \frac{1}{2\pi} \int_{\bbR}\Bigg\{(|\xi|+\kappa)^{-1} \int_{\bbR} \frac{\big|\widehat{V}(\eta) \big|^2}{|\eta+\xi|+\kappa}\, d\eta \Bigg\}\, d\xi\no\\
&= \frac{1}{2\pi} \int_{\bbR}\Bigg\{ \big|\widehat{V}(\eta)\big|^2 \int_{\bbR} \frac{d\xi}{\big[|\xi|+\kappa\big]\big[|\xi+\eta|+\kappa\big]}\Bigg\}\, d\eta\no\\
&= \frac{1}{2\pi} \int_{\bbR}\Bigg\{ \big|\widehat{V}(\eta)\big|^2 \int_{\bbR} \frac{d\xi}{\big[|\xi|+\kappa\big]\big[|\eta-\xi|+\kappa\big]}\Bigg\}\, d\eta.\lb{3.56}
\end{align}

The inner integral after the final equality in \eqref{3.56} is easily computed for $\eta=0$:
\begin{equation}
\int_{\bbR} \frac{d\xi}{\big[|\xi|+\kappa\big]^2} = 2\int_0^{\infty} \frac{d\xi}{[\xi+\kappa]^2} = \frac{2}{\kappa}.
\end{equation}
For $\eta\in \bbR\backslash\{0\}$, the integral may be computed upon distinguishing the cases $\eta > 0$ and $\eta < 0$.

%%%%%%%%%%
\begin{proposition}\lb{p3.8}
If $\kappa\in (0,\infty)$, then
\begin{equation}
\int_{\bbR} \frac{d\xi}{[|\xi|+\kappa] [|\eta-\xi|+\kappa]} =
\begin{cases}
\displaystyle{\frac{2}{\kappa}},&\eta=0,\\[2mm]
\displaystyle{\frac{4\kappa+4|\eta|}{2\kappa|\eta|+\eta^2}\ln\bigg(\frac{\kappa+|\eta|}{\kappa} \bigg)},&\eta\in \bbR\backslash\{0\}.
\end{cases}
\end{equation}
\end{proposition}
%%%%%%%%%%

Applying Proposition \ref{p3.8} in \eqref{3.56}, one obtains:
%%%%%%%%%%
\begin{proposition}
If $V\in \cS(\bbR)$ and $\kappa\in (0,\infty)$, then \eqref{3.51} holds and
\begin{equation}\lb{3.59}
\big\|A_V^{rel,0}(-\kappa)\big\|_{\cB_2(L^2(\bbR))}^2 = \frac{2}{\pi} \int_{\bbR}\Bigg\{ \big|\widehat{V}(\eta)\big|^2 \frac{\kappa+|\eta|}{2\kappa|\eta|+|\eta|^2}\ln\bigg(\frac{\kappa+|\eta|}{\kappa} \bigg) \Bigg\}\, d\eta.
\end{equation}
\end{proposition}
%%%%%%%%%%

Next, we investigate estimates of the integral on the right-hand side in \eqref{3.59}.  To this end, let $\kappa\in (0,\infty)$, $V\in \cS(\bbR)$, and $\delta\in (0,1/2)$ be fixed.  Choose $R(\kappa,\delta)\in (0,\infty)$ sufficiently large such that
\begin{equation}\lb{C.13}
\big(1+|\eta|^2\big)^{(1/2)-\delta}\cdot \frac{\kappa+|\eta|}{2\kappa|\eta|+|\eta|^2}\ln\bigg(\frac{\kappa+|\eta|}{\kappa} \bigg)\leq 1\, \text{ whenever $\eta\in \bbR$ and $|\eta|\geq R(\kappa,\delta)$.}
\end{equation}
The existence of $R(\kappa,\delta)$ is guaranteed by the fact that the left-hand side in \eqref{C.13} goes to zero as $|\eta|\to \infty$.

We investigate the integrand on the right-hand side in \eqref{3.59} in the three regimes: $(i)$ $0<|\eta|<1$, $(ii)$ $1<|\eta|<R(\kappa,\delta)$, and $(iii)$ $|\eta|>R(\kappa,\delta)$.

\medskip

\noindent
$(i)$ For $0<|\eta|<1$, using $\ln(1+x)\underset{x\downarrow 0}{=}x[1+O(x)]$,
\begin{align}
\frac{\kappa+|\eta|}{2\kappa|\eta|+|\eta|^2}\ln\bigg(\frac{\kappa+|\eta|}{\kappa} \bigg) &\leq \frac{C_1(\kappa)}{2\kappa+|\eta|}\no\\
&= \frac{C_1(\kappa)}{\big(1+|\eta|^2\big)^{(1/2)-\delta}} \cdot \frac{\big(1+|\eta|^2\big)^{(1/2)-\delta}}{2\kappa+|\eta|}\no\\
&\leq \frac{C_1(\kappa,\delta)}{\big(1+|\eta|^2\big)^{(1/2)-\delta}},\quad \eta\in \bbR,\, 0<|\eta|<1,
\end{align}
for some constants $C_1(\kappa),C_1(\kappa,\delta)\in (0,\infty)$.  Therefore,
\begin{align}
&\frac{2}{\pi} \int_{0<|\eta|<1}\Bigg\{ \big|\widehat{V}(\eta)\big|^2 \frac{\kappa+|\eta|}{2\kappa|\eta|+|\eta|^2}\ln\bigg(\frac{\kappa+|\eta|}{\kappa} \bigg) \Bigg\}\, d\eta\no\\
&\quad \leq \frac{2}{\pi}C_1(\kappa,\delta)  \int_{0<|\eta|<1}\frac{\big|\widehat{V}(\eta)\big|^2}{\big(1+|\eta|^2\big)^{(1/2)-\delta}} d\eta.\lb{C.15}
\end{align}

\noindent
$(ii)$ For $1<|\eta|<R(\kappa,\delta)$, choose a constant $C_2(\kappa,\delta)\in (0,\infty)$ such that
\begin{equation}\lb{C.18}
\frac{\big(1+|\eta|^2\big)^{(1/2)-\delta}[\kappa+|\eta|]}{2\kappa|\eta|+|\eta|^2}\ln\bigg(\frac{\kappa+|\eta|}{\kappa} \bigg) \leq C_2(\kappa,\delta),\quad \eta\in \bbR,\, 1<|\eta|<R(\kappa,\delta).
\end{equation}
The existence of $C_2(\kappa,\delta)$ is guaranteed by the fact that the left-hand side in \eqref{C.18} is a continuous function of $\eta$ for $1\leq |\eta|\leq R(\kappa,\delta)$.  By \eqref{C.18},
\begin{align}
\frac{\kappa+|\eta|}{2\kappa|\eta|+|\eta|^2}\ln\bigg(\frac{\kappa+|\eta|}{\kappa} \bigg) &\leq \frac{C_2(\kappa,\delta)}{\big(1+|\eta|^2\big)^{(1/2)-\delta}},\quad \eta\in \bbR,\, 1<|\eta|<R(\kappa,\delta),
\end{align}
and one obtains
\begin{align}
&\frac{2}{\pi} \int_{1<|\eta|<R(\kappa,\delta)}\Bigg\{ \big|\widehat{V}(\eta)\big|^2 \frac{\kappa+|\eta|}{2\kappa|\eta|+|\eta|^2}\ln\bigg(\frac{\kappa+|\eta|}{\kappa} \bigg) \Bigg\}\, d\eta\no\\
&\quad  \leq \frac{2}{\pi}C_2(\kappa,\delta) \int_{1<|\eta|<R(\kappa,\delta)} \frac{\big|\widehat{V}(\eta)\big|^2}{\big(1+|\eta|^2\big)^{(1/2)-\delta}} \, d\eta.\lb{C.20}
\end{align}

\noindent
$(iii)$ For $|\eta|>R(\kappa,\delta)$, \eqref{C.13} implies
\begin{align}
\frac{\kappa+|\eta|}{2\kappa|\eta|+|\eta|^2}\ln\bigg(\frac{\kappa+|\eta|}{\kappa} \bigg) \leq \frac{1}{\big(1+|\eta|^2\big)^{(1/2)-\delta}},\quad \eta\in \bbR,\, |\eta|>R(\kappa,\delta).
\end{align}
Therefore,
\begin{align}
&\frac{2}{\pi} \int_{|\eta|>R(\kappa,\delta)}\Bigg\{ \big|\widehat{V}(\eta)\big|^2 \frac{\kappa+|\eta|}{2\kappa|\eta|+|\eta|^2}\ln\bigg(\frac{\kappa+|\eta|}{\kappa} \bigg) \Bigg\}\, d\eta\no\\
&\quad \leq \frac{2}{\pi} \int_{|\eta|>R(\kappa,\delta)} \frac{\big|\widehat{V}(\eta)\big|^2}{\big(1+|\eta|^2\big)^{(1/2)-\delta}}\, d\eta\lb{C.20a}
\end{align}
Finally, if $C(\kappa,\delta):=(2/\pi)\max\big\{1,C_1(\kappa,\delta),C_2(\kappa,\delta)\big\}$, then \eqref{C.15}, \eqref{C.20}, and \eqref{C.20a} combine to yield:
\begin{align}
\frac{2}{\pi} \int_{\bbR}\Bigg\{ \big|\widehat{V}(\eta)\big|^2 \frac{\kappa+|\eta|}{2\kappa|\eta|+|\eta|^2}\ln\bigg(\frac{\kappa+|\eta|}{\kappa} \bigg) \Bigg\}\, d\eta&\leq C(\kappa,\delta) \int_{\bbR} \frac{\big|\widehat{V}(\eta)\big|^2}{\big(1+|\eta|^2\big)^{(1/2)-\delta}}\, d\eta\\
&= C(\kappa,\delta) \|V\|_{H^{-(1/2)+\delta}(\bbR)}^2.\no
\end{align}
These considerations may be summarized as follows.

%%%%%%%%%%
\begin{lemma}\lb{lC.4}
If $V\in \cS(\bbR)$, $\kappa\in (0,\infty)$, and $\delta\in (0,1/2)$, then there exists a constant $C(\kappa,\delta)\in (0,\infty)$ such that
\begin{equation}
\frac{2}{\pi} \int_{\bbR}\Bigg\{ \big|\widehat{V}(\eta)\big|^2 \frac{\kappa+|\eta|}{2\kappa|\eta|+|\eta|^2}\ln\bigg(\frac{\kappa+|\eta|}{\kappa} \bigg) \Bigg\}\, d\eta \leq C(\kappa,\delta) \|V\|_{H^{-(1/2)+\delta}(\bbR)}^2.
\end{equation}
\end{lemma}
%%%%%%%%%%

Let $\delta\in (0,1/2)$ be fixed.  If $V\in H^{-(1/2)+\delta}(\bbR)$, then $(1 + |\dott|)^{-(1/2)+\delta} \, 
\widehat{V}\in L^2(\bbR)$, say $(1 + |\dott|)^{-(1/2)+\delta} \, \widehat{V}=:g_V\in L^2(\bbR)$.  By inspection, one infers that
\begin{equation}\lb{C.23}
\frac{\kappa+|\dott|}{2\kappa|\dott|+|\dott|^2}\ln\bigg(\frac{\kappa+|\dott|}{\kappa}\bigg)
(1 + |\dott|)^{1-2\delta} \in L^{\infty}(\bbR),\quad \kappa\in (0,\infty).
\end{equation}
In light of \eqref{C.23}, we define
\begin{equation}\lb{C.24}
\begin{split}
&\int_{\bbR}\Bigg\{ \big|\widehat{V}(\eta)\big|^2 \frac{\kappa+|\eta|}{2\kappa|\eta|+|\eta|^2}\ln\bigg(\frac{\kappa+|\eta|}{\kappa} \bigg) \Bigg\}\, d\eta\\
&:= \int_{\bbR} \Bigg\{|g_V(\eta)|^2 (1 + |\eta|)^{1-2\delta} \frac{\kappa+|\eta|}{2\kappa|\eta|+|\eta|^2}\ln\bigg(\frac{\kappa+|\eta|}{\kappa} \bigg)\Bigg\}\, d\eta,\quad \kappa\in (0,\infty).
\end{split}
\end{equation}
The integral on the right-hand side in \eqref{C.24} is well-defined by virtue of \eqref{C.23} and the condition $g_V\in L^2(\bbR)$.

%%%%%%%%%%
\begin{lemma}
Let $\delta\in (0,1/2)$.  If $V\in H^{-(1/2)+\delta}(\bbR)$, then
\begin{equation}\lb{C.25}
\lim_{\kappa\to \infty} \int_{\bbR}\Bigg\{ \big|\widehat{V}(\eta)\big|^2 \frac{\kappa+|\eta|}{2\kappa|\eta|+|\eta|^2}\ln\bigg(\frac{\kappa+|\eta|}{\kappa} \bigg) \Bigg\}\, d\eta = 0.
\end{equation}
\begin{proof}
Let $I_V(\kappa,\eta)$ denote the integrand on the right-hand side in \eqref{C.24}.  The following estimates:
\begin{align}
&I_V(\kappa,\eta)\leq \frac{\kappa + |\eta|}{2\kappa |\eta|}\ln(2) (1+|\eta|)^{1-2\delta}|g_V(\eta)|^2\\
&\leq \ln(2^{1/2}) \bigg(1+\frac{|\eta|}{\kappa}\bigg) (1+|\eta|)^{-2\delta}|g_V(\eta)|^2\no\\
&\leq \ln(2)|g_V(\eta)|^2\,\text{for a.e.~$\eta\in \bbR$, $0<|\eta|\leq1$, $\kappa\in [1,\infty)$,}
\end{align}
and
\begin{align}
I_V(\kappa,\eta)&\leq \frac{\kappa+|\eta|}{2\kappa+|\eta|}\ln(1+|\eta|) (1+|\eta|)^{-2\delta}|g_V(\eta)|^2\no\\
&\leq\bigg\{\frac{\kappa}{2\kappa+|\eta|} + \frac{|\eta|}{2\kappa+|\eta|} \bigg\}\ln(1+|\eta|) 
(1+|\eta|)^{-2\delta}|g_V(\eta)|^2\no\\
&\leq (3/2) \ln(1+|\eta|) (1+|\eta|)^{-2\delta}|g_V(\eta)|^2\,\text{for a.e.~$\eta\in \bbR$, $|\eta|>1$, $\kappa\in[1,\infty)$,}
\end{align}
imply
\begin{align}
I_V(\kappa,\eta) &\leq \big[\ln(2)\chi_{\{x\in \bbR\,|\, |x|\leq1\}}(\eta)   \no \\
& \quad \;\, + (3/2) \ln(1+|\eta|) (1+|\eta|)^{-2\delta}\chi_{\{x\in \bbR\,|\,|x|>1}(\eta) \big]|g_V(\eta)|^2    \lb{C.29} \\
&\hspace*{3.2cm}\text{for a.e.~$\eta\in \bbR$ and for all $\kappa\in [1,\infty)$.}    \no 
\end{align}
The right-hand side in \eqref{C.29} is integrable, so the equality in \eqref{C.25} follows from an application of the dominated convergence theorem.
\end{proof}
\end{lemma}
%%%%%%%%%%

