\begin{remark} \lb{r4.10} 
The calculations in \eqref{3.48y} show that
\begin{equation}\lb{4.57u}
\frac{1}{4\kappa} \int_{\bbR\times \bbR} \ol{V(x)} e^{-2\kappa|x-x'|}V(x') \, dx dx' =  \int_{\bbR} \frac{\big|\widehat{V}(\xi)\big|^2}{4\kappa^2+\xi^2} \, d\xi,\quad \kappa\in (0,\infty).
\end{equation}
The identity in \eqref{4.57u} is reminiscent of the $\xi$-space formulation of the Rollnik Hilbert space norm for real-valued integrable Rollnik potentials as introduced in \cite[p.~15]{Si71}.
One recalls that a real-valued measurable function $V$ on $\bbR^3$ belongs to the Rollnik class 
$\mathfrak{R}$ (see, e.g., \cite[Ch.~I]{Si71}), if and only if
\begin{equation}
\iint_{\bbR^6}\frac{|V(x)||V(y)|}{|x-y|^2}\, d^3x\, d^3y < \infty.
\end{equation}

If $V\in L^1(\bbR^3)\cap L^2(\bbR^3)$ and $a>0$, then
\begin{equation}\lb{4.2}
\iint_{\bbR^6} \frac{V(x)V(y)}{a^2+|x-y|^2}\, d^3x\, d^3y = 2\pi^2 \int_{\bbR^3} \frac{\big|\widehat{V}(\xi)\big|^2}{|\xi|}e^{-a|\xi|}\, d^3\xi.
\end{equation}
The identity in \eqref{4.2} is a restatement of \cite[Equation (I.6)]{Si71}, suitably renormalized in accordance with our convention \eqref{2.1} for the Fourier transform.  By approximation, \eqref{4.2} holds under the condition $V\in L^1(\bbR^3)$.  Furthermore, if $V\in \mathfrak{R}\cap L^1(\bbR^3)$, then separate applications of the dominated and monotone convergence theorems on the left and right-hand sides of \eqref{4.2}, respectively, imply
\begin{equation}
\iint_{\bbR^6} \frac{V(x)V(y)}{|x-y|^2}\, d^3x\, d^3y = 2\pi^2 \int_{\bbR^3} \frac{\big|\widehat{V}(\xi)\big|^2}{|\xi|}\, d^3\xi, \quad V\in \mathfrak{R}\cap L^1(\bbR^3).
\end{equation}
In particular, 
\begin{equation}
\text{if $0 \leq V \in L^1(\bbR^3)$, then $V \in \mathfrak{R}$ if and only if $\int_{\bbR^3} \f{\big|\hatt V(\xi)\big|^2}{|\xi|} \, d^3 \xi < \infty$.} \\
\end{equation} 
${}$ \hfill $\diamond$  
\end{remark} 
