The following example illustrates a possible use of Theorem \ref{t2.3} $(v)$ and \eqref{D.3.60} in an application of the abstract results Theorems \ref{t5.9} and \ref{t2.11c}.

%%%%%%%%%%
\begin{example}
Let $n\in \bbN$ with $n\geq 3$ and $V\in L^p(\bbR^n)$ for some $p\in [2,\infty)$ with $p>n/2$.  By Theorem \ref{t2.3} $(v)$, $V\in \cB(H^1(\bbR^n),H^{-1}(\bbR^n))$.  Therefore,
\begin{equation}\lb{E.1}
\big(H_0-zI_{L^2(\bbR^n)}\big)^{-1/2}V\big(H_0-zI_{L^2(\bbR^n)}\big)^{-1/2}\in \cB\big(L^2(\bbR^n)\big),\quad z\in \bbC\backslash[0,\infty).
\end{equation}
However, \eqref{E.1} may be improved upon.  Factoring $V$ according to
\begin{equation}
V=uv=vu,\quad v=|V|^{1/2},\quad u=|V|^{1/2}e^{i\arg(V)},
\end{equation}
one infers that
\begin{equation}
u,v\in L^{2p}(\bbR).
\end{equation}
Furthermore, $\big(|\dott|^2+\kappa\big)^{-1/2}\in L^{2p}(\bbR^n)$, $\kappa\in (0,\infty)$.  Thus, by Theorem \ref{t2.6},
\begin{align}
&\overline{\big(H_0+\kappa I_{L^2(\bbR^n)}\big)^{-1/2}v}=\big[v(H_0+\kappa I_{L^2(\bbR^n)})^{-1/2}\big]^*\in \cB_{2p}\big(L^2(\bbR^n)\big),\no\\
&u\big(H_0+\kappa I_{L^2(\bbR^n)}\big)^{-1/2}\in \cB_{2p}\big(L^2(\bbR^n)\big),\quad \kappa\in(0,\infty).\lb{E.3}
\end{align}
In turn, \eqref{E.3} implies
\begin{equation}
\big(H_0+\kappa I_{L^2(\bbR^n)}\big)^{-1/2}V\big(H_0+\kappa I_{L^2(\bbR^n)}\big)^{-1/2}\in \cB_p\big(L^2(\bbR^n)\big),\quad \kappa\in(0,\infty).
\end{equation}
(The containment in \eqref{E.3} extends from $-\kappa\in (-\infty,0)$ to all $z\in \bbC\backslash [0,\infty)$.)  In addition, applying \eqref{D.3.61}, one obtains
\begin{align}
&\big\|(H_0+\kappa I_{L^2(\bbR^n)})^{-1/2}V(H_0+\kappa I_{L^2(\bbR^n)})^{-1/2}\big\|_{\cB_p(L^2(\bbR^n))}\no\\
&\quad \leq (2\pi)^{-2n/p}\Big\|\big(|\dott|^2+\kappa\big)^{-1/2}\Big\|_{L^{2p}(\bbR^n)}^2\|v\|_{L^{2p}(\bbR^n)}^2\no\\
&\quad \leq (2\pi)^{-2n/p}\Big\|\big(|\dott|^2+\kappa\big)^{-1}\Big\|_{L^{p}(\bbR^n)}\|V\|_{L^{p}(\bbR^n)},\quad \kappa\in(0,\infty).
\end{align}
Since
\begin{align}
\Big\|\big(|\dott|^2+\kappa\big)^{-1}\Big\|_{L^{p}(\bbR^n)} = \int_{\bbR}\frac{d^nx}{(|x|^2+\kappa)^p},\quad \kappa\in (0,\infty),
\end{align}
an application of the dominated convergence theorem implies
\begin{equation}
\lim_{\kappa\to\infty}\Big\|\big(|\dott|^2+\kappa\big)^{-1}\Big\|_{L^{p}(\bbR^n)} = 0.
\end{equation}
In consequence,
\begin{equation}
\lim_{\kappa\to \infty}\big\|(H_0+\kappa I_{L^2(\bbR^n)})^{-1/2}V(H_0+\kappa I_{L^2(\bbR^n)})^{-1/2}\big\|_{\cB_p(L^2(\bbR^n))}=0.
\end{equation}
Thus, Hypothesis \ref{h5.4} is satisfied with
\begin{equation}
\cH_{\pm 1}(H_0) = H^{\pm 1}(\bbR^n).
\end{equation}

Therefore, invoking Theorem \ref{t5.9}, one may define a (densely defined) $L^2(\bbR)$ realization $H$ of the purely formal sum ``$H_0+V$'' indirectly according to \eqref{5.22} and \eqref{5.28} as follows.  Set
\begin{equation}\lb{E.11}
A_V(z):= - (H_0-zI_{L^2(\bbR^n)})^{-1/2}V (H_0-zI_{L^2(\bbR^n)})^{-1/2},\quad z\in \bbC\backslash[0,\infty),
\end{equation}
and
\begin{equation}\lb{E.12}
\begin{split}
R(z) := (H_0 - zI_{L^2(\bbR^n)})^{-1/2}[I_{\cH}-A_V(z)]^{-1} (H_0 - zI_{L^2(\bbR^n)})^{-1/2},&\\
z\in \{\zeta\in \rho(H_0)\,|\, 1\in \rho(A_V(\zeta))\}=\bbC\backslash([0,\infty)\cup\cD_{H_0,V}),&
\end{split}
\end{equation}
where $\cD_{H_0,V}$ is the discrete set guaranteed to exist by Proposition \ref{p5.6}.  Finally, Theorems \ref{t5.9} and \ref{t2.11c} yield the following result.
%%%%%%%%%%
\begin{theorem}\lb{t3.11}
Let $n\in \bbN$, $p\in (n/2,\infty)$ with $p\geq 2$, and $V\in L^p(\bbR^n)$.  Suppose $A_V(\dott)$ and $R(\dott)$ are defined by \eqref{E.11} and \eqref{E.12}.  The map $R(\dott)$ uniquely defines a densely defined, closed, linear operator $H$ in $L^2(\bbR^n)$ by
\begin{equation}
R(z) = (H-zI_{L^2(\bbR^n)})^{-1},\quad z\in \bbC\backslash([0,\infty)\cup \cD_{H_0,V}).
\end{equation}
In addition, $(\bbC\backslash([0,\infty)\cup \cD_{H_0,V}))\subseteq \rho(H)$ and $H$ has the property:
\begin{equation}
\big[(H-zI_{L^2(\bbR^n)})^{-1} - (H_0-zI_{L^2(\bbR^n)})^{-1}\big] \in \cB_{\infty}(L^2(\bbR^n)),\quad z\in \rho(H_0)\cap\rho(H).
\end{equation}
Moreover, a point $\lambda_0\in \bbC\backslash[0,\infty)$, is an eigenvalue of $H$ with geometric multiplicity $k\in \bbN$ if and only if $1$ is an eigenvalue of $A_V(\lambda_0)$ with geometric multiplicity $k$.
\end{theorem}
%%%%%%%%%%
The conditions on $V$ in Theorem \ref{t3.11} are in line with the standard assumptions on the $L^p(\bbR^n)$-scale when applying the Kato--Rellich and \textit{KLLMN} theorems (cf., e.g., \cite[Theorems A.2.33 and E.3.5]{GNZ24}) to potentials in $L^p(\bbR^n)$, see \cite[Theorems X.20 and X.29]{RS75}.\hfill$\ddagger$
\end{example}
%%%%%%%%%%

The following sufficient conditions for $V\in \cS'(\bbR)$ to be a multiplier from $H^1(\bbR)$ to $H^{-1}(\bbR)$ are special cases of \cite[Theorems 5, 6, and 7]{NS99}.

%%%%%
\begin{theorem}\lb{t2.3}
The following statements $(i)$--\hspace*{.33mm}$(v)$ hold:\\[1mm]
$(i)$  If $n=1$, then every $V\in H^{-1}(\bbR)$ is a multiplier from $H^1(\bbR)$ to $H^{-1}(\bbR)$.\\[1mm]
$(ii)$  If $n=2$ and $p>2$, then every $V\in H^{-1,p}(\bbR^2)$ is a multiplier from $H^1(\bbR^2)$ to $H^{-1}(\bbR^2)$ and
\begin{equation}
\|V\|_{\cB(H^1(\bbR^2),H^{-1}(\bbR^2))} \leq C\|V\|_{H^{-1,p}(\bbR^2)}
\end{equation}
for some $C\in (0,\infty)$ that does not depend on $V$.\\[1mm]
$(iii)$  If $n=2$ and $p>1$, then every $V\in L^p(\bbR^2)$ is a multiplier from $H^1(\bbR^2)$ to $H^{-1}(\bbR^2)$ and
\begin{equation}
\|V\|_{\cB(H^1(\bbR^2),H^{-1}(\bbR^2))} \leq C\|V\|_{L^p(\bbR^2)}
\end{equation}
for some $C\in (0,\infty)$ that does not depend on $V$.\\[1mm]
$(iv)$  If $n\geq 3$ and $p>n$, then every $V\in H^{-1,p}(\bbR)$ is a multiplier from $H^1(\bbR)$ to $H^{-1}(\bbR)$ and
\begin{equation}
\|V\|_{\cB(H^1(\bbR),H^{-1}(\bbR))} \leq C\|V\|_{H^{-1,p}(\bbR)}
\end{equation}
for some $C\in (0,\infty)$ that does not depend on $V$.\\[1mm]
$(v)$ If $n\geq 3$ and $p>n/2$, then every $V\in L^p(\bbR)$ is a multiplier from $H^1(\bbR)$ to $H^{-1}(\bbR)$ and
\begin{equation}
\|V\|_{\cB(H^1(\bbR),H^{-1}(\bbR))} \leq C\|V\|_{L^p(\bbR)}
\end{equation}
for some $C\in (0,\infty)$ that does not depend on $V$.
\end{theorem}
%%%%%

It is interesting to compare item $(v)$ in Theorem \ref{t2.3} with the following result from \cite{RS75}.
%%%%%
\begin{theorem}[{\cite[Theorem X.20]{RS75}}]
Suppose $n\geq 4$ and $p>n/2$.  If $V\in L^p(\bbR)$, then $V$ is infinitesimally bounded with respect to $H_0$.  In particular, $H = H_0 + V$ with $\dom(H)=\dom(H_0)$ is self-adjoint.
\end{theorem}
