		\beq
		|I^{(1)}\rangle=c_1^{\Delta-c_0\lb Q-c_0\rb}\left[|\Delta\rangle +\sum_{k=1}^{\infty}c_1^k\sum_{\lambda\in\mathbb Y,|\lambda|=k}G_{\lambda}\; \mathbb{L}_{-\lambda}|\Delta\rangle\right],
