	\end{eg}

		\subsection{Half-integer ranks\label{subsec_HIR}}
	It was recently realized  that the above construction can be adapted to half-integer ranks. The latter naming means that by analogy with \eqref{virdiff1} we require that $L_{n}\mapsto 0$ for $n>2r\in 2\mathbb N+1$ while keeping the eigenvalue of $L_{2r}$ non-vanishing. An appropriate differential operator realization of $\mathsf{Vir}_+$  was found in \cite{PP23} for $r=\frac52$. In \cite{HNNT24}, it has been suggested that the generalization to arbitrary half-integer ranks can be found by taking a suitable limit of the  integer rank realization. This has led to a conjectural recursive procedure for determining the operators $\mathcal L_{n}^{(r)}$ with $r\in\mathbb N+\frac12$. However,  finding their closed form for any $r$ stayed an open issue.

	It turns out that this problem admits a  concise solution that allows to consider the integer and half-integer ranks on equal footing. Loosely speaking, it suffices to set in \eqref{virdiff1} $Q=0$  (since we only care about the realization of $\mathsf{Vir}_+$, this does not imply any constraint on the central charge)  and let the coefficients $c_k$ to be labeled by positive half-integers (which does not alter the form of commutation relations).

	\begin{prop}\label{PropLs}
		For $s\in \mathbb N$, the mapping
		\beq\label{propLs}
		L_n\mapsto \mathcal L^{(s-\frac12)}_n=\begin{cases}
			0,\qquad & n\ge 2s,\\
			-\sum\limits_{k=n-s+\frac12}^{s-\frac12} c_{k} c_{n-k},\qquad & n=s,\ldots, 2s-1,\\
			-\sum\limits_{k=\frac12}^{s-\frac12} c_{k} c_{n-k}+
			\sum\limits_{k=\frac12}^{s-n-\frac12}kc_{n+k}\ds\frac{\partial}{\partial c_{k}},\qquad & n=0,\ldots, s-1,
			\end{cases}
		\eeq
		is consistent with the commutation relations of the subalgebra $\mathsf{Vir}_+$. Moreover, as an antihomomorphism into the subalgebra of 1st order differential operators in the eigenvalues of $L_s,\ldots,L_{2s-1}$, such a mapping is unique up to gauge transformations $\mathcal L^{(s-\frac12)}_n\mapsto e^{-F}\circ\mathcal L^{(s-\frac12)}_n\circ e^F$.
		\end{prop}
		\pf Straightforward calculation shows that $\left[\mathcal L^{(s-\frac12)}_m,\mathcal L^{(s-\frac12)}_n\right]=\lb n-m\rb \mathcal L^{(s-\frac12)}_{m+n}$ for any $m,n\ge0$. To demonstrate uniqueness, parameterize $\mathcal L^{(s-\frac12)}_{s},\ldots, \mathcal L^{(s-\frac12)}_{2s-1}$ by $c_{_{1/2}},\ldots, c_{_{s-1/2}}$ as in \eqref{propLs} and note that the differential parts of $ \mathcal L^{(s-\frac12)}_{0},\ldots, \mathcal L^{(s-\frac12)}_{s-1}$ are immediately fixed by their commutation relations with $\mathcal L^{(s-\frac12)}_{s},\ldots, \mathcal L^{(s-\frac12)}_{2s-1}$ acting by multiplication. 

		The scalar parts   of $ \mathcal L^{(s-\frac12)}_{0},\ldots, \mathcal L^{(s-\frac12)}_{s-1}$ have to satisfy a system of linear PDEs coming from the commutators $ \mathcal L^{(s-\frac12)}_{0},\ldots, \mathcal L^{(s-\frac12)}_{s-1}$  between themselves. For $n=0,\ldots, s-1$, write $\mathcal L^{(s-\frac12)}_{n}=\tilde{\mathcal L}^{(s-\frac12)}_{n}+D_n$, where $\tilde{\mathcal L}^{(s-\frac12)}_{n}$ is given by the expression of $\mathcal L^{(s-\frac12)}_{n}$ in \eqref{propLs}. Then the compatibility with $\mathsf{Vir}_+$ commutation relations is equivalent to
		\beq\label{PDEs}
		\sum\limits_{k=\frac12}^{s-m-\frac12}kc_{m+k}\ds\frac{\partial D_n}{\partial c_{k}}-
		\sum\limits_{k=\frac12}^{s-n-\frac12}kc_{n+k}\ds\frac{\partial D_m}{\partial c_{k}}=\lb m-n\rb D_{m+n},\qquad 0\leq m< n\leq s-1,
		\eeq
		where $D_k=0$ for $k\ge s$. We can use the gauge freedom to set $D_{s-1}=0$. From \eqref{PDEs} with $m=0,\ldots, s-2$ and $n=s-1$, it follows that $\ds\frac{\partial D_{m}}{\partial c_{_{1/2}}}=0$, and thus the functions $D_0,\ldots,D_{s-2}$ are independent of $ c_{_{1/2}}$. Now we can use the residual gauge freedom to set $D_{s-2}=0$ and iterate the procedure: equations \eqref{PDEs} with $m=0,\ldots, s-3$ and $n=s-2$ shows that $D_0,\ldots, D_{s-3}$ are independent of $ c_{_{3/2}}$ and so on.\epf

	In the  most relevant to us rank $\frac52$ case, the nontrivial operators explicitly read
	\beq
	\label{52equationsV2}
	\begin{gathered}
	\mathcal L_5^{(5/2)}=-c_{_{5/2}}^2,\qquad 
	\mathcal L_4^{(5/2)}=-2c_{_{3/2}}c_{_{5/2}},
	\qquad 
	\mathcal L_3^{(5/2)}=-2c_{_{1/2}}c_{_{5/2}}-c_{_{3/2}}^2,	\\
		\mathcal L_2^{(5/2)}=-2c_{_{1/2}}c_{_{3/2}}+\frac{c_{_{5/2}}}{2}\frac{\partial}{\partial c_{_{1/2}}},\qquad
		\mathcal L_1^{(5/2)}=-c_{_{1/2}}^2+\frac{3c_{_{5/2}}}{2}\frac{\partial}{\partial c_{_{3/2}}}+\frac{c_{_{3/2}}}{2}\frac{\partial}{\partial c_{_{1/2}}},\\
	\mathcal L_0^{(5/2)}=\frac{5 c_{_{5/2}}}{2}\frac{\partial}{\partial c_{_{5/2}}}+
	\frac{3 c_{_{3/2}}}{2}\frac{\partial}{\partial c_{_{3/2}}}+
	 \frac{c_{_{1/2}}}{2}\frac{\partial}{\partial c_{_{1/2}}}.
	 \end{gathered}
	\eeq
	They are of course gauge equivalent to the expressions given in \cite{PP23} and \cite{HNNT24}. E.g. parameterizing $\mathcal L_n^{(5/2)}=\Lambda_n$ for $n=3,4,5$, the other  generators become
	\begin{subequations} \label{L52eq2v2}
\begin{align}
	\mathcal L^{(5/2)}_2=&\,\Lambda_5\frac{\partial}{\partial \Lambda_3}-\frac{\Lambda_4\lb\Lambda^2_4-4\Lambda_3\Lambda_5\rb}{8\Lambda_5^2},\\
	\mathcal L^{(5/2)}_1=&\, 3\Lambda_5\frac{\partial}{\partial \Lambda_4}+2\Lambda_4\frac{\partial}{\partial \Lambda_3}+\frac{\lb\Lambda^2_4-4\Lambda_3\Lambda_5\rb^2}{64\Lambda_5^3},
	\\
	\mathcal L^{(5/2)}_0=&\,5\Lambda_5\frac{\partial }{\partial \Lambda_5}+
	4\Lambda_4\frac{\partial }{\partial \Lambda_4}+
	3\Lambda_3\frac{\partial }{\partial \Lambda_3}.
\end{align}
\end{subequations}
   The gauge transformation with $F=\ds\frac{47\Lambda_4^5}{960\Lambda_5^4}-\ds\frac{5\Lambda_3\Lambda_4^3}{24\Lambda_5^3}+\frac{\Lambda_3^2\Lambda_4}{4\Lambda_5^2}$ then yields the realization of \cite[Eqs. (3.41)--(3.46)]{HNNT24}. Further reparameterization $\Lambda_3=-2c_1c_2$, $\Lambda_4=-c_2^2$ combined with the gauge transformation corresponding to $F=\ds\frac{c_1c_2^4\lb c_2^3+4c_1\Lambda_5\rb}{4\Lambda_5^3}+\ds\frac{17c_2^{10}}{960\Lambda_5^4}$ gives
   \begin{subequations}\label{PPLs}
   \begin{gather}
   \mathcal L^{(5/2)}_{5}=\Lambda_5,\qquad
   \mathcal L^{(5/2)}_{4}=-c_2^2,\qquad
   \mathcal L^{(5/2)}_{3}=-2c_1c_2,\qquad
   \mathcal L^{(5/2)}_2=-\frac{\Lambda_5}{2c_2}\frac{\partial}{\partial c_1},\\
   %+\frac{c_2^3\lb c_2^3+8c_1\Lambda_5\rb}{8\Lambda_5^2},\\
   \mathcal L^{(5/2)}_1=-\frac{3\Lambda_5}{2c_2}\frac{\partial}{\partial c_2}+
   \frac{2c_2^3+3c_1\Lambda_5}{2c_2^2}\frac{\partial}{\partial c_1}-\frac{2c_1^2c_2^2}{\Lambda_5},\\
   %+\frac{c_2^2\lb c_2^3+8c_1\Lambda_5\rb^2}{64\Lambda_5^3}, 	\\
   \mathcal L^{(5/2)}_0=5\Lambda_5\frac{\partial }{\partial \Lambda_5}+
   2c_2\frac{\partial }{\partial c_2}+
   c_1\frac{\partial }{\partial c_1}.
   \end{gather}
   \end{subequations}
   This coincides with \cite[Eq. (2.8)]{PP23} after the sign flip $\Lambda_5\mapsto-\Lambda_5$.


	\subsection{Differential operator approach\label{subsec_Diffopapp}}
	Consider   the rank $2$ irregular state   $\bigl|I^{(2)}\bigr\rangle$ defined by $L_n\bigl|I^{(2)}\bigr\rangle=\mathcal L_n^{(2)}\bigl|I^{(2)}\bigr\rangle$ for all $n\ge0$. In the case $r=2$, the differential operators $\mathcal L^{(2)}_{n}$ in \eqref{virdiff1} are explicitly written as
	\beq
	\begin{gathered}
	\mathcal L^{(2)}_{n\ge 5}=0,\qquad\mathcal L^{(2)}_4=-c_2^2,\qquad \mathcal L^{(2)}_3=-2c_1c_2,\qquad\mathcal L^{(2)}_2=-2c_0c_2-c_1^2+3Qc_2,\\
	\mathcal L^{(2)}_1=2c_1\lb Q-c_0\rb+c_2\frac{\partial }{\partial c_1},\qquad 
	\mathcal L^{(2)}_0=c_0\lb Q-c_0\rb+
	2c_2\frac{\partial }{\partial c_2}+
	c_1\frac{\partial }{\partial c_1}.
	\end{gathered} 
	\eeq
	Let $\langle 0|$ be the Virasoro vacuum state satisfying $\langle 0|L_n=0$ for $n\leq 1$. Define conformal block $\mathcal F^{(2)}\lb c_1,c_2\rb$ by 
	\beq
	\mathcal F^{(2)}\lb c_1,c_2\rb= \bigl \langle 0 \bigr| I^{(2)}\bigr\rangle.
	\eeq
	The pairing between the vacuum module and the rank 2 module is required to satisfy the usual compatibility condition $\langle v|L_n\cdot |w\rangle=\langle v|\cdot L_n|w\rangle$ fixing it up to rescaling. This leads to Ward identities $\mathcal L^{(2)}_{0}\mathcal F^{(2)}=\mathcal L^{(2)}_{1}\mathcal F^{(2)}=0$ which are immediately solved by
	\beq
	\mathcal F^{(2)}\lb c_1,c_2\rb=\operatorname{const}\cdot c_2^{-c_0\lb Q-c_0\rb/2}\exp\frac{\lb c_0-Q\rb c_1^2}{c_2}.
	\eeq
	The constant prefactor is independent of $c_1$, $c_2$ and can be set equal to $1$. Note that if we replace $\langle 0|$ by a generic highest weight state $\langle \Delta|$, the Ward identities alone are no longer sufficient to fix $\langle \Delta|I^{(2)}\rangle$ since the right action of $L_1$ on $\langle \Delta|$ is nontrivial.


	Following the same procedure for $r=\frac52$, let us define conformal block $\mathcal F^{(5/2)}\lb c_1,c_2,\Lambda_5\rb$ by 
	\beq
	\mathcal F^{(5/2)}\lb c_1,c_2,\Lambda_5\rb= \bigl\langle 0 \bigr| I^{(5/2)}\bigr\rangle,
	\eeq
	where $L_n\bigl|I^{(5/2)}\bigr\rangle=\mathcal L_n^{(5/2)}\bigl|I^{(5/2)}\bigr\rangle$ for $n\ge 0$ and the differential operators $\mathcal L^{(5/2)}_n$ are given by \eqref{PPLs}. The equation $\mathcal L^{(5/2)}_{0}\mathcal F^{(5/2)}=0$ implies that if $c_1$, $c_2$ and $\Lambda_5$ are assigned degrees $1$, $2$ and $5$ then $\mathcal F^{(5/2)}\lb c_1,c_2,\Lambda_5\rb$ is homogeneous of degree $0$, so that
	\beq
	\mathcal F^{(5/2)}\lb c_1,c_2,\Lambda_5\rb=G\lb x,y\rb,\qquad \text{with } \quad x=\frac{\Lambda_5}{c_2^{5/2}},
	\; y= 
	\frac{c_1\Lambda_5}{c_2^3}.
	\eeq
	The second constraint $\mathcal L^{(5/2)}_{1}\mathcal F^{(5/2)}=0$ then yields a linear PDE
	\beq\label{exppref}
    \left[15x\frac{\partial }{\partial x}+4\lb 1+6y\rb\frac{\partial }{\partial y}-\frac{8y^2}{x^4}\right]G\lb x,y\rb=0,
	\eeq
	which can be solved by the standard method of characteristics.
	The solution is given by 
	\beq\label{expprefsol}
	G\lb x,y\rb= \exp\left\{-\frac{2 \left(135 y^2+30 y+2\right)}{405 x^4}\right\} F\lb s \rb,\qquad s=\frac{2\lb 1+6 y\rb^{5/4}}{3x^2}.
	\eeq

	The arbitrary function $F\lb s\rb$ represents the nontrivial part of the conformal block and has to be determined by other means. Anticipating the result, we write it in the form of a formal asymptotic series at $s=\infty$ (which corresponds to sending $\Lambda_5\to0$):
	\beq\label{CBansatz}
	F\lb s\rb=s^{-2\alpha}e^{\frac{s^2}{45}+\frac{4i\nu s}{5}}\left[1+\sum_{k=1}^\infty F_k s^{-k}\right].
	\eeq
	The role of $\frac{s^2}{45}$ here is to cancel the most singular term proportional to $\Lambda_5^{-4}$ in the exponential prefactor in \eqref{expprefsol} so that $\ln\mathcal F^{(5/2)}\lb c_1,c_2,\Lambda_5\rb=O\lb \Lambda_5^{-3}\rb$ as $\Lambda_5\to 0$. In fact, there occur more substantial cancellations:
	\beq
	\frac{s^2}{45}-\frac{2 \left(135 y^2+30 y+2\right)}{405 x^4}=\frac{2 c_1^3 c_2}{3 \Lambda_5}+O\lb 1\rb\qquad\text{as }\;\Lambda_5\to 0.
	\eeq
	The parameter $\nu$ in \eqref{CBansatz} is free while $\alpha$ and the coefficients $F_k$ are to be found in terms of $\nu$.

	After these preparations, let us now revisit the construction of \cite{PP23}. The idea is to look for the rank~$\frac52$ irregular state $| I^{(5/2)}\rangle$ in the form of a series in $\Lambda_5$ similar to the expansion \eqref{irr_state_dec}, 
		\beq\label{irr_state_dec_bis}
	\left|I^{\lb 5/2\rb}\right\rangle=f\lb c_1,c_2,\Lambda_5\rb\,|\Psi\rangle,
	\qquad |\Psi\rangle=
	\sum_{k=0}^\infty \Lambda_5^k \bigl|I^{\lb 2\rb}_k\bigr\rangle,
	\eeq
	where $\bigl|I^{\lb 2\rb}_0\bigr\rangle=\bigl|I^{(2)}\bigr\rangle$. The generalized descendants $	\bigl|I^{\lb 2\rb}_k\bigr\rangle$ have the form
	\beq\label{gendes}
	\bigl|I^{\lb 2\rb}_k\bigr\rangle=\sum_{n_1,n_2\in\mathbb Z_{\ge0}}\sum_{\lambda\in\mathbb Y}A^{[k]}_{\lambda;n_1,n_2}\lb c_1,c_2\rb\mathbb L_{-\lambda}\frac{\partial^{n_1}}{\partial c_1^{n_1}}\frac{\partial^{n_2}}{\partial c_2^{n_2}}\bigl|I^{(2)}\bigr\rangle.
	\eeq
	The above considerations suggest the following form of the singular prefactor $f\lb c_1,c_2,\Lambda_5\rb$ in \eqref{irr_state_dec_bis} as
	\begin{subequations}
	\begin{align}
	f\lb c_1,c_2,\Lambda_5\rb=&\,\lb\mathcal F^{(2)}\lb c_1,c_2\rb\rb^{-1}  s^{-2\alpha}\exp\left\{\frac{s^2}{45}+\frac{4i\nu s}{5}-\frac{2 \left(135 y^2+30 y+2\right)}{405 x^4}\right\}=
	 \\ 
	 \label{fsingb}=&\,c_2^{c_0\lb Q-c_0\rb/2}s^{-2\alpha}\exp\left\{\frac{s^2}{45}+\frac{4i\nu s}{5}
	 -\frac{4c_2^{10}}{405\Lambda_5^4}-\frac{4c_1c_2^7}{27\Lambda_5^3}-
	 \frac{2c_1^2c_2^4}{3\Lambda_5^2}+\frac{\lb Q-c_0\rb c_1^2}{c_2}\right\},
	\end{align}
	\end{subequations}
	with 
	\beq\label{irrCR}
	s=\frac{2c_2^5}{3\Lambda_5^2}\lb 1+\frac{6c_1\Lambda_5}{c_2^3}\rb^{5/4}.
	\eeq
	The  formula \eqref{fsingb} is equivalent to \cite[Eqs. (2.12)--(2.14)]{PP23} where this prefactor was found by invoking a Seiberg-Witten curve analysis instead of solving Ward identities.

	Substituting \eqref{irr_state_dec_bis} into the  defining equations of irregular state, we have $L_n|\Psi\rangle=f^{-1}\circ\mathcal L^{(5/2)}_n\circ f\,|\Psi\rangle$. The operators on the right hand side of this relation can be expressed as
	\begin{align}
		f^{-1}\circ\mathcal L^{(5/2)}_n\circ f=
		\begin{cases}
		0,\qquad & n>5,\\
		\Lambda_5, \qquad & n=5,\\
		-c_2^2,\qquad & n=4, \\
		-2c_1c_2,\qquad & n=3, \\	
		-\ds\frac{\Lambda_5}{2c_2}\ds\frac{\partial}{\partial c_1}+\varphi_2,\qquad & n=2,\\
		-\ds\frac{3\Lambda_5}{2c_2}\ds\frac{\partial}{\partial c_2}+
		\ds\frac{2c_2^3+3c_1\Lambda_5}{2c_2^2}\frac{\partial}{\partial c_1}+\varphi_1,\qquad & n=1,\\
		5\Lambda_5\ds\frac{\partial }{\partial \Lambda_5}+
		2c_2\ds\frac{\partial }{\partial c_2}+
		c_1\ds\frac{\partial }{\partial c_1}+c_0\lb Q-c_0\rb,\qquad & n=0,
		\end{cases}	
	\end{align}
	where the functions $\varphi_1$, $\varphi_2$ are readily computed as
	\begin{subequations}
	\begin{gather}
		\varphi_1=\lb Q-c_0\rb\left[ 2c_1+\frac{3\lb 6c_1^2-c_0c_2\rb}{4c_2^3}\Lambda_5\right],\\
	\begin{gathered}
	\varphi_2=\frac{2c_2^6}{27\Lambda_5^2}\left[1+\frac{9c_1\Lambda_5}{c_2^3}-
	\lb1+\frac{6c_1\Lambda_5}{c_2^3}\rb^{3/2}\right]-2i\nu c_2\lb1+\frac{6c_1\Lambda_5}{c_2^3}\rb^{1/4}\\-\frac{\lb Q-c_0\rb c_1}{c_2}\Lambda_5+\frac{15\alpha \Lambda_5^2}{2c_2^4}\lb1+\frac{6c_1\Lambda_5}{c_2^3}\rb^{-1}.
	\end{gathered}
	\end{gather}
	\end{subequations}
	It is important to note that the  $\Lambda_5\to 0$ expansion of $\varphi_2$  does not contain singular terms. Collecting the coefficients of different powers $\Lambda_5^k$ in $L_n|\Psi\rangle=f^{-1}\circ\mathcal L^{(5/2)}_n\circ f\,|\Psi\rangle$ yields a system of recurrence relations for the generalized descendants:
	\begin{subequations}
		\label{recrels1}
	\begin{gather}
		L_{n>5}\bigl|I^{\lb 2\rb}_k\bigr\rangle=0,\qquad 
		L_5 \bigl|I^{\lb 2\rb}_k\bigr\rangle=\bigl|I^{\lb 2\rb}_{k-1}\bigr\rangle,\qquad
		\lb L_4+c_2^2\rb \bigl|I^{\lb 2\rb}_k\bigr\rangle=0,\qquad 
		\lb L_3+2c_1c_2\rb \bigl|I^{\lb 2\rb}_k\bigr\rangle=0,\\
		L_2\bigl|I^{\lb 2\rb}_k\bigr\rangle=-\frac{1}{2c_2}\frac{\partial}{\partial c_1}
		\bigl|I^{\lb 2\rb}_{k-1}\bigr\rangle+\sum_{j=0}^k\varphi_{2,j}\bigl|I^{\lb 2\rb}_{k-j}\bigr\rangle,\\
		\lb L_1 -\mathcal L_1^{(2)}\rb\bigl|I^{\lb 2\rb}_k\bigr\rangle=\lb-\frac{3}{2c_2}\frac{\partial}{\partial c_2}+\frac{3c_1}{2c_2^2}\frac{\partial}{\partial c_1}+\frac{3\lb Q-c_0\rb\lb 6c_1^2-c_0c_2\rb}{4c_2^3}\rb \bigl|I^{\lb 2\rb}_{k-1}\bigr\rangle,\\
		\lb L_0 -\mathcal L_0^{(2)}-5k\rb\bigl|I^{\lb 2\rb}_k\bigr\rangle=0,
	\end{gather}
	\end{subequations}
	where $\varphi_{2,j}$ denote the coefficients in the Taylor expansion $\varphi_2=\sum_{j=0}^\infty \varphi_{2,j}\Lambda_5^j $. For $k=0$, all of these equations are satisfied automatically except for the $L_2$ equation which expresses the corresponding eigenvalue parameter $c_0$ in terms of $\nu$ as $c_0=i\nu+\frac{3Q}{2}$.

	One may attempt to solve the system \eqref{recrels1} recursively by restricting possible values of $n_1,n_2,\lambda$ in \eqref{gendes} to a suitable finite subset of $\mathbb Z_{\ge0}^2\times \mathbb Y$. For example, substituting   $\bigl|I^{\lb 2\rb}_1\bigr\rangle$ in the form
	\beq
	\bigl|I^{\lb 2\rb}_1\bigr\rangle=\lb A L_{-1}+B\frac{\partial }{\partial c_2}+C\frac{\partial }{\partial c_1}+D\rb \bigl|I^{\lb 2\rb}\bigr\rangle
	\eeq
	into the relations \eqref{recrels1} with $k=1$, we see that the $L_{n>5}$ equations are satisfied automatically, the $L_5$ equation determines $A=-\ds\frac{1}{6c_2^2}$, the $L_4$ equation gives $B=-5Ac_1=\ds\frac{5c_1}{6c_2^2}$ and the $L_3$ equation yields
	\beq C=\frac{2A\lb3Qc_2-2c_0c_2-c_1^2\rb-Bc_1}{c_2}=\frac{2c_0-3Q}{3c_2^2}-\frac{c_1^2}{2c_2^3}.
	\eeq
	The $L_2$ equation does not produce new constraints while $L_1$ and $L_0$ equations uniquely determine the remaining coefficient\footnote{This expression differs from its counterpart in Eq. (2.16) in \cite{PP23} because our choice of the singular prefactor $f$ differs from the one in  loc. cit. by a non-singular function $\lb 1-\frac{6c_1\Lambda_5}{c_2^3} \rb^{5\rho_5/8}$ and the sign of $\Lambda_5$.}
	\beq
	D=\ds\frac{\lb c_0-Q\rb\lb 22c_1^2+3c_2\lb 8Q-7c_0\rb \rb c_1}{12c_2^4}.
	\eeq

	Though in principle similar calculations  can be carried  out at higher orders in $\Lambda_5$, they quickly become quite cumbersome. However, the procedure we have just outlined does not take into account the symmetry of conformal block, namely the fact that $\mathcal F^{(5/2)}\lb c_1,c_2,\Lambda_5\rb$ nontrivially depends only on  the irregular cross-ratio  given by \eqref{irrCR}. In the next subsection, we develop a simpler, purely algebraic construction of irregular state which implements this symmetry and effectively sets $c_1=0$, $c_2=-\frac{i}{2}$ from the very beginning.


   \subsection{Algebraic construction}\label{SubsecAlgCon}
   \subsubsection{Whittaker vector of rank $\frac52$}
   Let $\mathbb C\mathcal |J\rangle$ be a one-dimensional representation of the subalgebra $\bigoplus\limits_{n\ge 2}\mathbb C L_n\subset \mathsf{Vir}$ defined by
   \beq\label{Wh2}
   L_{n>4}|J\rangle=0,\qquad L_4|J\rangle=\frac14 |J\rangle,\qquad L_3|J\rangle=0,
   \qquad   L_2|J\rangle=-\nu |J\rangle,
   \eeq
   with $\nu\in\mathbb C$. The vector $|J\rangle$ is called a rank 2 Whittaker state. The Whittaker module $\mathcal V^{[2]}_{\nu}$ is the corresponding induced representation of $\mathsf{Vir}$,
   \beq\label{PBWbasis}
   \mathcal V^{[2]}_{\nu}=\bigoplus_{m_{0,1}\in \mathbb Z_{\ge 0},\lambda\in\mathbb Y}\mathbb C\,\mathbb L_{-\lambda}L_0^{m_0}L_1^{m_1}|J\rangle.
   \eeq

   Our first task to find a vector $|\Psi\rangle\in\mathcal V^{[2]}_{\nu}$ such that
   \beq\label{Wh52}
   L_{n\ge 6}|\Psi\rangle=0,\qquad L_5|\Psi\rangle=\varepsilon |\Psi\rangle,\qquad
     L_4|\Psi\rangle=\frac14 |\Psi\rangle,\qquad L_3|\Psi\rangle=0,
   \eeq
   with $\varepsilon\in\mathbb C$. Any such $|\Psi\rangle$ will be called a Whittaker state of rank $\frac52$. By analogy with the Gaiotto-Teschner construction \eqref{irr_state_dec}, one may look for $|\Psi\rangle$ in the form of a power series in $\varepsilon$:
   \beq\label{Wh52exp}
   |\Psi\rangle=|J\rangle+\sum_{k=1}^{\infty}\varepsilon^k\mathbb G_k|J\rangle,
   \eeq
   where
   \beq \label{Wh52expAux}
   \mathbb G_k=\sum_{m_{0,1}\in\mathbb Z_{\ge0},\lambda\in\mathbb Y} G_{\lambda;m_0,m_1}^{[k]}\mathbb L_{-\lambda}L_0^{m_0}L_1^{m_1},
   \eeq
   and the coefficients $G_{\lambda;m_0,m_1}^{[k]}$ are independent of $\varepsilon$. Rescaling $|\Psi\rangle\mapsto f|\Psi\rangle$ by a power series $f\in\mathbb C[[\varepsilon]]$ such that $f\lb 0\rb=1$ does not change the relations \eqref{Wh52} nor the normalization $|\Psi\rangle_{\varepsilon=0}=|J\rangle$. We fix this ambiguity by requiring that 
   \beq\label{Wh52normalization}
   G_{\emptyset;0,0}^{[k]}=0,\qquad k\in\mathbb N.
   \eeq
   In other words, there are no terms proportional to $|J\rangle$ in the expression of all descendants $\mathbb G_k|J\rangle$ .
   Using the canonical pairing between $\mathcal V^{[2]}_{\nu}$ and Virasoro vacuum module, these conditions can be rewritten as $\langle 0|\Psi\rangle=\langle 0|J\rangle$.
   We will refer to \eqref{Wh52normalization} as the orthogonal gauge.

   \begin{rmk}
   	Fixing the eigenvalues of $L_3$ and $L_4$ as in \eqref{Wh2} involves no loss of generality since the vector $| J'\rangle=e^{\alpha L_0}e^{\beta L_1}|J\rangle$ is also a joint eigenstate of $L_2,L_3,L_4$ and
   	\beq
   	L_{n\ge 5}|J'\rangle=0,\qquad L_4|J'\rangle=\frac{e^{4\alpha}}{4} |J'\rangle,\qquad L_3|J'\rangle=
   	\frac{\beta e^{3\alpha}}{2}|J'\rangle,
   	\qquad   L_2|J'\rangle=\lb \frac{\beta^2}{4}-\nu\rb e^{2\alpha} |J'\rangle.
   	\eeq
   	Similar considerations can be applied to a joint eigenstate of $L_3,L_4,L_5$  to adjust its eigenvalues to \eqref{Wh52}. The latter relations are designed precisely so as to reproduce their lower rank counterparts \eqref{Wh2} in the limit $\varepsilon\to0$.
   \end{rmk}

   The main result of this subsection is the following
   \begin{theo}\label{conjWh52}
   	The rank $\frac52$ Whittaker state $|\Psi\rangle\in\mathcal V^{[2]}_{\nu}$ defined by \eqref{Wh52}--\eqref{Wh52expAux} and normalization \eqref{Wh52normalization} uniquely exists. Moreover,
   	\beq\label{selectionrulesWH}
   	\mathbb G_k=\sum_{\substack{1\leq\ell\leq k \\ \ell=k\;\mathrm{mod}\;2}}\sum_{\substack{m_0,m_1\in\mathbb Z_{\ge0},\lambda\in\mathbb Y \\ m_1+2m_0+|\lambda|=\ell}}G_{\lambda;m_0,m_1}^{[k]}\mathbb L_{-\lambda}L_0^{m_0}L_1^{m_1}.
   	\eeq
   \end{theo}
   \pf   The meaning of the selection rules in \eqref{selectionrulesWH} is as follows. We define $\operatorname{deg}L_{-k}=k$ for $k>0$, $\operatorname{deg}L_0=2$ and ${\operatorname{deg}L_1=1}$. The Virasoro monomials allowed in $\mathbb G_k$ have total degree $k$ modulo $2$. The latter restriction may be traced back to the automorphism $L_n\mapsto \lb -1\rb^n L_n$, $n\in\mathbb Z$ of the Virasoro algebra. The nontrivial part of the proof concerns the restriction 
   $m_1+2m_0+|\lambda|\le k$, and is given in Appendix~\ref{AppProof}. The proof builds upon and refines the ideas from \cite{Nagoya15}.  \epf

   To explain the internal mechanics and practical implications of this statement, let us first note that the joint eigenstate conditions \eqref{Wh52} can be equivalently rewritten as
   \beq\label{Gkrels}
   \left[L_5,\mathbb G_k\right]|J\rangle=
   \mathbb G_{k-1}|J\rangle,\qquad  \left[L_n,\mathbb G_k\right]|J\rangle=0,\qquad n=3,4,6,
   \eeq
   where $\mathbb G_0=1$. The generators $L_{n}$ with $n\ge 7$ can be obtained by commuting $L_3,\ldots ,L_6$, therefore the corresponding equations are satisfied automatically. 


   \begin{itemize}
   	\item For $k=1$, Theorem~\ref{conjWh52} predicts that
   	\beq
   	\mathbb G_1=G^{[1]}_{\ytableausetup
   		{mathmode,  boxsize=0.4em}\ydiagram{1}\,;0,0}L_{-1}+G^{[1]}_{\emptyset;0,1}L_1.
   	\eeq
   	This ansatz automatically satisfies $L_6$ and $L_4$ relation
    in \eqref{Gkrels}. The $L_5$ and $L_3$ relations imply respectively that $\frac32G^{[1]}_{\ytableausetup
   		{mathmode,  boxsize=0.3em}\ydiagram{1}\,;0,0}=1$ and
   		$\frac12 G^{[1]}_{\emptyset;0,1}-4\nu G^{[1]}_{\ytableausetup
   			{mathmode,  boxsize=0.3em}\ydiagram{1}\,;0,0}=0$, so that
   			\beq
   			\mathbb G_1=\frac23  L_{-1}+\frac{16\nu}{3}L_1.
   			\eeq
   	\item Likewise, for $k=2$ we expect at most 5 terms in the descendant state,
   	\beq
   	\mathbb G_2=G^{[2]}_{\ytableausetup
   		{mathmode,  boxsize=0.4em}\ydiagram{2}\,;0,0}L_{-2}+G^{[2]}_{\ytableausetup
   		{mathmode,  boxsize=0.4em}\ydiagram{1,1}\,;0,0}L_{-1}^2+G^{[2]}_{\ytableausetup
   		{mathmode,  boxsize=0.4em}\ydiagram{1}\,;0,1}L_{-1}L_1
   		+G^{[2]}_{\emptyset;1,0}L_0+G^{[2]}_{\emptyset;0,2}L_1^2.
   		\eeq
   The $L_5$ equation determines two coefficients $G^{[2]}_{\ytableausetup
   	{mathmode,  boxsize=0.4em}\ydiagram{1}\,;0,1}=\frac{32\nu}{9}$, $G^{[2]}_{\ytableausetup
   	{mathmode,  boxsize=0.4em}\ydiagram{1,1}\,;0,0}=\frac29$. The $L_6$ equation yields a linear relation $2G^{[2]}_{\ytableausetup
   	{mathmode,  boxsize=0.4em}\ydiagram{2}\,;0,0}+\frac{21}{2}G^{[2]}_{\ytableausetup
   	{mathmode,  boxsize=0.4em}\ydiagram{1,1}\,;0,0}=0$ which in turn implies that $G^{[2]}_{\ytableausetup
   	{mathmode,  boxsize=0.4em}\ydiagram{2}\,;0,0}=-\frac76$. The $L_3$ equation gives two constraints. One of them involves $G^{[2]}_{\ytableausetup
   	{mathmode,  boxsize=0.4em}\ydiagram{1}\,;0,1}$, $G^{[2]}_{\ytableausetup
   	{mathmode,  boxsize=0.4em}\ydiagram{1,1}\,;0,0}$ and turns out to be satisfied by the previously determined expressions. Another one involves 3 already found coefficients and $G^{[2]}_{\emptyset;0,2}$ thereby fixing the latter. The $L_4$ equation produces one relation containing the same 3 coefficients and $G^{[2]}_{\emptyset;1,0}$. The final result is
   	\beq\label{G2}
   	\mathbb G_2=-\frac76L_{-2}+\frac29L_{-1}^2+\frac{32\nu}{9}L_{-1}L_1-\frac{103\nu}{9}L_0+\frac{256\nu^2+57}{18} L_1^2.
   	\eeq
   \end{itemize}
   The pattern described above continues for higher values of $k$. Equations \eqref{Gkrels} generate an overdetermined linear system for the coefficients $G^{[k]}_{\lambda;m_0,m_1}$. The key part of the statement concerns the existence of its solution. It was additionally checked by explicit computation of higher-order descendants $\mathbb G_3,\ldots,\mathbb G_{12}$. The expressions of  $\mathbb G_3$, $\mathbb G_4$, $\mathbb G_5$ (in the case $\nu=0$, also $\mathbb G_6$) are given in Appendix~\ref{AppA1}. For generic $\nu$, all of the coefficients in \eqref{selectionrulesWH} turn out to be non-zero. 


   \subsubsection{Conformal blocks}\label{SubsectionConfBlocks52}
   Let us denote by $L_{\varepsilon}\in\mathsf{Vir}$ the element
   \beq
   L_{\varepsilon}=L_2-2\varepsilon L_1+6\varepsilon^2 L_0,
   \eeq
   and consider the Virasoro subalgebra $\mathsf{Vir}_{\varepsilon}^{(5/2)}=\bigoplus\limits_{n\ge 3}\mathbb C L_n\oplus\mathbb C L_{\varepsilon}$. There exists an anti-homomorphism of $\mathsf{Vir}_{\varepsilon}^{(5/2)}$ into the algebra of 1st order differential operators in $\varepsilon$:
   \beq
   \begin{gathered}
   	L_n\mapsto \mathcal L_n,\qquad n\in \{\varepsilon\}\cup \mathbb N_{\ge3},\\
   \mathcal L_{n\ge 6}= 0,\qquad \mathcal L_5= \varepsilon,\qquad 
   \mathcal L_4=\frac14,
   \qquad \mathcal L_3= 0,\qquad 
   \mathcal L_{\varepsilon}=30\varepsilon^3\frac{\partial}{\partial\varepsilon}-\nu.
   \end{gathered}
   \eeq

   \begin{rmk} The form of $L_{\varepsilon}$ is fixed by the condition for  $\mathcal L_{n\ge 3}$ to reproduce the eigenvalues of $L_n$ in \eqref{Wh52}. Indeed, replace $L_\varepsilon$ by an arbitrary linear combination $\tilde{L}=AL_2+BL_1+CL_0$, then we have 
   	\begin{subequations}
   	\begin{align}
   	\left[L_3,\tilde{L}\right]=&\,AL_5+2BL_4+3CL_3\mapsto A\varepsilon+\frac{B}{2},\\
   	\left[L_4,\tilde{L}\right]=&\,2AL_6+3BL_5+4CL_4\mapsto 3B\varepsilon+C.
   	\end{align}
   	\end{subequations}
   	However, since $\mathcal L_3,\mathcal L_4$ are independent of $\varepsilon$, both of these commutators should be mapped to $0$, which implies that $\tilde L=AL_\varepsilon$. The form of $\mathcal L_{\varepsilon}$ is then determined, up to a gauge transformation, by the remaining commutator $[L_5,L_\varepsilon]=3L_7-8\varepsilon L_6+30\varepsilon^2L_5\mapsto-30\varepsilon^3$. The constant term $-\nu$ is included into the definition of $\mathcal L_{\varepsilon}$ for later convenience.
   	\end{rmk}

    By analogy with \eqref{Ward_eqs}, let us now introduce the irregular state $\bigl|I^{(5/2)}\bigr\rangle\in \mathcal V_{\nu}^{[2]}$ by
    \beq\label{RedIrrStateDec}
    L_n\bigl|I^{(5/2)}\bigr\rangle=\mathcal L_n \bigl|I^{(5/2)}\bigr\rangle,\qquad  n\in \{\varepsilon\}\cup \mathbb N_{\ge3}.
    \eeq
    Up to a scalar prefactor, it must coincide with the Whittaker state $|\Psi\rangle$ defined by \eqref{Wh52}--\eqref{Wh52normalization}:
    \beq\label{IrrStateF}
    \bigl|I^{(5/2)}\bigr\rangle=\mathcal F\lb\varepsilon\,|\,\nu\rb\,|\Psi\rangle.
    \eeq 
    Just as our notation suggests, the prefactor $\mathcal F\lb\varepsilon\,|\,\nu\rb$ is nothing but the sought-for irregular conformal block. Indeed, taking into account the expansions \eqref{Wh52exp}--\eqref{Wh52expAux}and  recalling that $\langle 0|L_{n}=0$ for $n\le 1$, $\mathcal F\lb\varepsilon\,|\,\nu\rb$ can be written as
    \beq
    \mathcal F\lb\varepsilon\,|\,\nu\rb=
    \frac{\bigl\langle 0\,\bigl|I^{(5/2)}\bigr\rangle}{\langle 0|J\rangle\;}.
    \eeq

    The explicit form of conformal block  is obtained from the $L_\varepsilon$ equation in \eqref{RedIrrStateDec}:
    \beq
    \mathcal F\lb\varepsilon\,|\,\nu\rb L_\varepsilon|\Psi\rangle=\mathcal L_\varepsilon \mathcal F\lb\varepsilon\,|\,\nu\rb |\Psi\rangle.
    \eeq
    The procedure is as follows. In a more elaborated form, the last equation reads
    \beq\label{EqForFcal}
    \left[L_2 -2\varepsilon L_1+6\varepsilon^2 L_0+\nu-30\varepsilon^3\frac{\partial }{\partial\varepsilon}-30\varepsilon^3\frac{\partial
    \ln \mathcal F\lb\varepsilon\,|\,\nu\rb}{\partial\varepsilon}\right] 
    \sum_{k=0}^{\infty}\varepsilon^k\mathbb G_k|J\rangle=0.
    \eeq
    The Virasoro commutation relations together with $L_2|J\rangle=-\nu|J\rangle$ can now be used to express the left hand side in the  previously used Poincar\'e-Birkhoff-Witt basis \eqref{PBWbasis}  of $\mathcal V_{\nu}^{[2]}$. 
    \begin{conj} Irregular state $\bigl|I^{(5/2)}\bigr\rangle$ exists. Equations  \eqref{EqForFcal} admit a solution at every order in $\varepsilon$, with 
    \beq\label{CBauxexp}
    \mathcal F\lb\varepsilon\,|\,\nu\rb=\varepsilon^\alpha \Bigl[1+\sum_{k=1}^\infty
     \mathcal F_{k}\lb\nu\rb\varepsilon^{2k}\Bigr],
    \eeq
    and the coefficients $\mathcal F_{k}\lb\nu\rb$ and $\alpha$ are uniquely determined in terms of $\nu$ and  Virasoro central charge $c$.
    \end{conj}


    The only part of the above statement which is hard to prove is existence. If  $\bigl|I^{(5/2)}\bigr\rangle$ exists (which is confirmed by direct calculation at low orders in $\varepsilon$), then its uniqueness follows from that of $|\Psi\rangle$. Indeed, the irregular conformal block $\mathcal F\lb\varepsilon\,|\,\nu\rb$ can be easily computed by projecting the relation \eqref{EqForFcal} onto the vacuum  $\langle 0|$:
    \beq\label{CBalgexp}
    30\varepsilon^3\frac{\partial
    	\ln \mathcal F\lb\varepsilon\,|\,\nu\rb}{\partial\varepsilon}=\frac{\langle 0|\lb L_2+\nu\rb|\Psi\rangle}{\langle 0|J\rangle},
    \eeq
    which implies that the coefficients of the series
    \beq\label{Ugenericc}
    \mathcal U\lb \varepsilon\,|\,\nu\rb=\ln \mathcal F\lb\varepsilon\,|\,\nu\rb=\mathcal U_{\operatorname{ln}}\lb\nu\rb\ln\varepsilon+\sum_{k=1}^{\infty}\mathcal U_{k}\lb \nu\rb\varepsilon^{2k}.
    \eeq
    can be calculated as
    \beq
    \label{L2comms}
    \mathcal U_{\operatorname{ln}}\lb\nu\rb=\alpha=\frac{\langle 0|\left[L_2,\mathbb G_{2}\right]|J\rangle}{30
    	\langle 0|J\rangle},\qquad
    \mathcal U_{k}\lb\nu\rb=\frac{\langle 0|\left[L_2,\mathbb G_{2k+2}\right]|J\rangle}{60k
    	\langle 0|J\rangle},\qquad k\in\mathbb N.
    \eeq

    For any practical purpose, equations \eqref{CBalgexp}--\eqref{L2comms} can be considered the definition of $\mathcal F\lb\varepsilon\,|\,\nu\rb$. The Whittaker state $|\Psi\rangle$ computed up to $o\lb \varepsilon^{12}\rb$ allows us to obtain the coefficients
        \begin{subequations}
        	\label{Ucoefs}
    	\begin{align}
    \label{G2ME}\mathcal U_{\operatorname{ln}}\lb\nu\rb=&\,\nu^2+\frac{1}{30}	-\frac{7\lb c-1\rb}{360},\\
    \label{G4ME}
    \mathcal U_{1}\lb\nu\rb=&\,\frac{\nu\lb 94\nu^2+17\rb}{2}-\frac{77\nu\lb c-1\rb}{24},\\
    \label{G6ME}
    \mathcal U_{2}\lb\nu\rb=&\,\frac{38585 \nu ^4+18385 \nu ^2+336}{10}-\frac{7 (c-1) \left(1433520 \nu ^2-14497 c+124825\right)}{17280},\\
    \mathcal U_{3}\lb\nu\rb=&\,\frac{\nu  \left(5326258 \nu ^4+5019530 \nu ^2+541269\right)}{10} -\frac{49 (c-1) \nu  \left(25241040 \nu ^2-880567 c+8708575\right)}{8640},\\
    \nonumber\mathcal U_{4}\lb\nu\rb=&\,3 \left(31386901 \nu ^6+50078328 \nu ^4+14438609 \nu ^2+188160\right)+\frac{49\lb c-1\rb^2 \left(60185465 \nu ^2+7172941\right)}{960} \\&\,-\frac{7\lb c-1\rb \left(686028420 \nu ^4+509742465 \nu ^2+21788387\right)}{120}
    -\frac{791845439 \lb c-1\rb^3}{34560},\\
    \nonumber\mathcal U_{5}\lb\nu\rb=&\,\frac{3\nu\left(32160819372 \nu ^6+78779679122 \nu ^4+45102923992 \nu ^2+3752724735\right) }{5} \\
    \label{G12ME}&\,-\frac{7\lb c-1\rb \nu \left(51339657369 \nu ^4+72168517621 \nu ^2+12853630497\right) }{30}   \\
    \nonumber &\,+\frac{7 \lb c-1\rb^2 \nu  \left(1354433276168 \nu ^2-34511035493 c+636095673641\right)}{5760}. 
     \end{align}
		 \end{subequations}   


    \begin{rmk} The subset of descendants contributing to  matrix elements on the right of \eqref{CBalgexp} is relatively small. For example, out of 22 Virasoro monomials in the expression \eqref{G4} of $\mathbb G_4$, non-vanishing contributions to $\mathcal U_1\lb \nu\rb$ in \eqref{G4ME} come from only 5 terms: $L_{-2}$, $L_1^2$, $L_0$, $L_0L_1^2$ and $L_0^2$. In the case of $\mathbb G_6$ there are 47 more monomials, yet only 2 of them, namely $L_0^2L_1^2$ and $L_0^3$, contribute to $\mathcal U_2\lb \nu\rb$ given by \eqref{G6ME}. In the general case, one has $2k+3$ contributions to $\mathcal U_{k}\lb \nu\rb$, since
    	\beq
    	\frac{\langle 0|\left[L_2,\mathbb G_{2k}\right]|J\rangle}{
    		\langle 0|J\rangle}=\frac{c}{2}G^{[2k]}_{\ytableausetup
    		{mathmode,  boxsize=0.4em}\ydiagram{2}\,;0,0}+\sum_{\ell=1}^k
    		2^{\ell-2}\lb G^{[2k]}_{\emptyset\,;\,\ell-1,2} -4 \nu\, G^{[2k]}_{\emptyset\,;\,\ell,0}\rb.
    	\eeq
    \end{rmk}

    We are now finally ready to give an algebraic variant of the proposal of \cite{PP23}.
    \begin{conj}\label{CFTPI}
    For $c=1$, irregular conformal block $\mathcal{F}\lb\varepsilon\,|\,\nu\rb$ defined by \eqref{CBalgexp}  reproduces the Painlev\'e I partition function $\mathcal Z\lb s\,|\,\nu\rb$:
    \beq\label{CFTPIstatement}
    \mathcal Z\lb s\,|\,\nu\rb=\varepsilon^{-\nu^2-\frac1{30}}
    \mathcal{F}\lb\varepsilon\,|\,\nu\rb\Bigl|_{c=1},
    \eeq
    under identification $ \varepsilon^{-2}=48is$.
    \end{conj} 	
    A straightforward check of this statement can be made by comparing the expansion coefficients \eqref{Eps1}--\eqref{Eps5} of the \PIeq free energy $\mathcal E\lb s\,|\,\nu\rb$ and the corresponding coefficients \eqref{G4ME}--\eqref{G12ME} in the expansion of $\mathcal U\lb \varepsilon\,|\,\nu\rb$.

    \begin{rmk} The prefactor on the right of \eqref{CFTPIstatement} was introduced to compensate $\varepsilon^{\alpha}$ in \eqref{CBauxexp} thereby ensuring that the corresponding asymptotic expansion starts from $1$. It turns out that this singular prefactor nicely combines with other quantities  in the Fourier representation of the \PIeq tau function. As $t\to -\infty$, one has simply
    \beq
    	\mathcal T\lb t\,|\,\nu\rb\simeq \lb 2\pi \rb^{-\frac{\nu}{2}}G\lb 1+\nu\rb \exp\left\{-\tfrac{\varepsilon^{-4}}{103680}+\tfrac{\nu\varepsilon^{-2}}{60}\right\}
    \mathcal{F}\lb\varepsilon\,|\,\nu\rb\Bigl|_{c=1}. 
    \eeq
    where $\mathcal T\lb t\,|\,\nu\rb$ is the function that appears in the Fourier decomposition \eqref{taufourier2}.
    \end{rmk}

     We have developed an algebraic construction of the rank $\frac52$ Whittaker state $|\Psi\rangle$ and the corresponding irregular  state $\bigl|I^{(5/2)}\bigr\rangle$ by embedding them into a Whittaker module $\mathcal V^{[2]}_{\nu}$ of rank 2. An analog of this construction in the case of embedding into a Whittaker module of rank $\frac32$ is outlined in Appendix~\ref{AppA3}.



    \section{Topological recursion\label{sec_TR}}
    The initial input to the Eynard-Orantin topological recursion (TR) \cite{EO07} is a spectral curve --- a tuple 
    $\lb\Sigma,x,y\rb$ of a compact Riemann surface $\Sigma$  with a Torelli marking (i.e. a fixed symplectic basis of the first homology group $H_1\lb\Sigma,\mathbb Z\rb$), and a pair $\lb x,y\rb$ of meromorphic functions on $\Sigma$. 

    In this work, the pair $\lb x,y\rb$ is assumed to satisfy an irreducible algebraic relation of the form 
    \begin{equation} \label{eq:sp-poly}
    	y^2 = P_3\lb x\rb,
    \end{equation}
    with $P_3\lb x\rb $ a cubic polynomial. 
    The equation \eqref{eq:sp-poly} defines an algebraic curve, 
    which we denote by ${\mathcal C}$, and $\Sigma$ is its normalization. 
    When there can be no confusion, ${\mathcal C}$ will also be referred to 
    as a spectral curve. We regard $x : \Sigma \to {\mathbb P}^1$ as a double covering map, 
    and denote by $\sigma : \Sigma \to \Sigma$ the covering involution
    satisfying $x\lb z\rb = x\lb\sigma\lb z\rb\rb$ and $y\lb z\rb \ne y\lb \sigma\lb z\rb\rb$ for generic $z\in\Sigma$. A zero of $dx$ is called a ramification point. The set of ramification points will be denoted by $R ~ (\subset \Sigma)$.

    The TR output is a doubly-indexed sequence of meromorphic multi-differentials $W_{g,n}\lb z_1,\ldots, z_n\rb$ ($g\ge0$, $n\ge1$) on $\Sigma$, called correlators, and a sequence of numbers $F_g$ ($g\ge0$), called free energies. These quantities have attracted interest of researchers 
    in various fields such as enumerative geometry, topological string theory, 
    integrable systems, quantum topology, and others.

      The \PIeq partition function $\mathcal Z\lb s\,|\,\nu\rb$ turns out to be related to a special case of the generating series for free energies. We start this section by a brief review of the prior results \cite{IS16} on the TR/\PIeq correspondence for $\nu=0$. In order to extend it to generic monodromy, we need an implementation of the topological recursion on the Weierstrass elliptic curve \cite{BCD18}. We then explain how the $\hbar$-expansion of the TR free energy reproduces the  large \PIeq time asymptotic expansion of $\ln\mathcal Z\lb s\,|\,\nu\rb$.

    \subsection{A warm-up example\label{subsec_warmup}}
    The TR implementation dramatically simplifies in the case $\Sigma=\mathbb P^1$. In our setting, this situation corresponds to a degenerate \PIeq elliptic curve \eqref{spcurve},
    \begin{equation} \label{eq:deg-ec}
    	{\mathcal C}_{\rm deg} ~:~ y^2 = 4x^3 + 2 t x + u_0  = 4\lb x-q_0\rb^2 \lb x+ 2q_0\rb,
    \end{equation}
    where $t,u_0$ are parameterized by $q_0$ as
    \begin{equation} \label{eq:u0}
    	t=-6q_0^2,\qquad u_0 = 8q_0^3.
    \end{equation}
    As one might guess, the parameter $t$ will later be  identified with the independent variable of Painlev\'e I. The quantity~$q_0$ will appear as the leading term of its formal power series solution. The spectral curve is a rational parameterization of
    $	{\mathcal C}_{\rm deg}$:
    \begin{equation} \label{eq:sp-degPI}
    	x\lb z\rb = z^2 - 2q_0, \qquad y\lb z\rb = 2z\lb z^2 - 3q_0\rb, 
    \end{equation} 
    where $z$ is the coordinate of ${\mathbb P}^1$. The involution map $\sigma$ for \eqref{eq:sp-degPI} is given by 
    % \begin{equation} \label{eq:inv-deg}
    	$\sigma\lb z\rb = -z$,
    	% \end{equation}
    which induces the covering involution $\lb x,y\rb \mapsto \lb x, -y\rb$ of \eqref{eq:deg-ec}.


    The TR algorithm works as follows:
    \begin{itemize}
    	\item Its
    starting point are the expressions
    \beq
    W_{0,1}\lb z_1\rb=y\lb z_1\rb dx\lb z_1\rb,\qquad W_{0,2}\lb z_1,z_2\rb=\frac{dz_1dz_2}{\lb z_1-z_2\rb^2}.
    \eeq
    The 1st differential is canonically associated to the spectral curve \eqref{eq:sp-poly} and the 2nd one is the unique normalized symmetric bidifferential on $\mathbb P^1$ with a double pole along the diagonal and no other poles.    
    \item The other multi-differentials  are computed by induction in $\chi_{g,n}=2g-2+n$ as 
    \begin{equation}
    	W_{g,n}\lb z_{1},\dots,z_{n}\rb = 
    	\sum_{r \in R}
    	\Res_{z=r} \, K\lb z_1,z\rb R_{g,n}\lb z, z_2, \dots, z_n\rb.  
    	\label{eq:top-rec}
    \end{equation}
    Here 
    \begin{equation} \label{eq:R-gn}
    	R_{g,n}\lb z, z_2, \dots, z_n\rb = 
    	W_{g-1,n+1}\lb z, \sigma(z),z_2, \dots, z_n\rb + 
    	\sum'_{\substack{g_{1}+g_{2}=g \\ I \sqcup J = \{2,\dots,n \}}}
    	W_{g_{1}, |I|+1}\lb z,z_{I}\rb \, W_{g_{2}, |J|+1}\lb  \sigma(z), z_{J}\rb,
    \end{equation}
    and the recursion kernel $K\lb z_1,z\rb$ is 
    given by
    \begin{equation} \label{eq:rec-ker}
    	K(z_1,z) = 
    	\frac{\displaystyle\int^{w=z}_{ w=\tilde z} W_{0,2}\lb z_{1}, w\rb}{\lb y\lb z\rb - y\lb  \sigma(z)\rb\rb  dx(z)} \, ,
    \end{equation}
    where $\tilde z$ denotes an arbitrary basepoint\footnote{One can also replace the integral
    	$\int^{w=z}_{ w=\tilde z}$ by its standard symmetrized version $\frac12\int^{w=z}_{ w=\sigma\lb z\rb}$ ; see \cite[Footnote 3]{BHLMR2013} and \cite[Remark~3.10]{BE16}. The non-symmetrized version is more straightforward to extend to genus 1 case.}.
    We use the convention for a tuple of variables as 
    $z_{I} = (z_{i_1}, \dots, z_{i_{k}})$ if 
    $I = \{i_1, \dots, i_k \}$.  
    The prime in the right hand side of \eqref{eq:R-gn} 
    means that only the indices satisfying $\lb g_i, I_i\rb \ne \lb 0, \emptyset\rb$ are taken into account
    in the summation, which implies that $W_{0,1}$ does not appear  at all in the computation of $W_{g,n}$.
    \item 
    The $g$th free energy $F_g$ is defined for $g\ge 2$ by
    \beq\label{Fgdef}
    F_g=\frac{1}{2-2g}\sum_{r\in R}\Res_{z=r} \,\Phi\lb z\rb W_{g,1}\lb z\rb,
    \eeq
    where $\Phi$ is any primitive of $W_{0,1}$. The free energies $F_0$, $F_1$ may also be defined, but in a different manner, see \cite[Section 4.2]{EO07}  for details.
    \end{itemize}

    In the case at hand, the set $R$ consists of only one ramification point,  $R = \left\{ 0 \right\}$, and we may set
    \beq
    K\lb z_1,z\rb=\frac{dz_1/dz}{8 z^2\lb z^2-3q_0\rb\lb z_1-z\rb},\qquad \Phi\lb z\rb=\frac{4}5z^5-4q_0z^3.
    \eeq
    The differentials $W_{g,n}$ can now be easily calculated by residues.
    For example, at the first three steps of the recursion we obtain
    \begin{subequations}
    \begin{align}	
    &\chi_{g,n}=1:\qquad 
    W_{0,3}\lb z_1,z_2,z_3\rb=\frac{dz_1dz_2dz_3}{12q_0 z_1^2z_2^2z_3^2},\qquad W_{1,1}\lb z_1\rb=\ds\frac{\lb 1+3q_0z_1^{-2}\rb dz_1}{288q_0^2z_1^2},
    \\
    &\chi_{g,n}=2:\qquad  \begin{aligned} &W_{0,4}\lb z_1,z_2,z_3,z_4\rb=\frac{1+3q_0\lb z_1^{-2}+z_2^{-2}+z_3^{-2}+z_4^{-2}\rb}{144q_0^3z_1^2z_2^2z_3^2z_4^2}dz_1dz_2dz_3dz_4,\\ &W_{1,2}\lb z_1,z_2\rb=\frac{2+6q_0\lb z_1^{-2}+z_2^{-2}\rb+3q_0^2\lb 5z_1^{-4}+5z_2^{-4}+3z_1^{-2}z_2^{-2}\rb}{3456q_0^4z_1^2z_2^2}dz_1dz_2, 
    \end{aligned}	\\
    &\chi_{g,n}=3:\qquad W_{2,1}\lb z_1\rb=\frac{7 \left(4 z_1^8+12 q_0 z_1^6+36 q_0^2 z_1^4+87 q_0^3 z_1^2+135 q_0^4\right) dz_1}{1990656 q_0^7 z_1^{10}},\qquad \ldots
    \end{align}
    \end{subequations}
    Next, using $W_{g,1}$ to compute free energies, one finds e.g. that
    \beq\label{FgDeg}
    F_{2}=\frac{7q_0^{-5}}{207360},\qquad  F_{3}=\frac{245 q_0^{-10}}{429981696},\qquad F_4=\frac{259553
    q_0^{-15}}{7430083706880 },\qquad \ldots
    \eeq

    Before proceeding, let us draw the reader's attention to some of the general properties of $W_{g,n}$ and $F_g$ that will be relevant for us (see \cite{EO07} for more details).
    \begin{itemize}
    	\item The differentials $W_{g,n}$ are symmetric in all variables $z_1,\ldots,z_n$, even though this symmetry is not manifest in equations \eqref{eq:top-rec}--\eqref{eq:rec-ker}.
    	\item In each  variable $z_i$, $W_{g,n}$ with $\chi_{g,n}\ge 1$ have poles only at ramification points. The pole order is at most $6g+2n-4$ and the residues at these points vanish.
    	\item $W_{g,n}$ and $F_g$ possess a homogeneity property. In the above case, it means e.g. that for  $g\ge 2$ the free energies are expressible in the form
    	\beq
    	F_g=c_gq_0^{5-5g},
    	\eeq
    	with some constant $c_g\in\mathbb Q$.
    \end{itemize}

    Comparing the numerators of the expressions \eqref{FgDeg} and the successive contributions to the tronqu\'ee  \PIeq  free energy in \eqref{PIFE}, one may guess that these quantities coincide under a suitable identification of parameters. Indeed, the following TR/\PIeq relation has  been proved in \cite{IS16}:
    \begin{theo}\label{thm:0-par-tau}
    The TR free energy for the curve ${\mathcal C}_{\rm deg}$ defined by \eqref{eq:deg-ec},
    \beq
    \mathcal U_{\rm \,TR}^{\rm \,deg}\lb s\rb=\sum_{g=2}^\infty F_g,\qquad s^2+432q_0^5=0,
    \eeq	
    coincides, as a formal power series in $s^{-2}$, with the \PIeq free energy $\mathcal E\lb s\,|\,0\rb$ in \eqref{PIFE}. 
    \end{theo}

    In the context of TR, it is customary to introduce a counting parameter $\hbar$ and define the free energy as
    $\sum_{g\ge 0}F_g\hbar^{2g-2}$. We postpone the inauguration of $\hbar$ to the next subsection, since $q_0$ in our introductory example plays a completely equivalent role. The discussion of $F_0$ and $F_1$ is also postponed to minimize the amount of fuss. We simply mention that the corresponding expressions agree with the prefactor $s^{-1/60}e^{s^2/45}$ in \eqref{bigtau1}. 

    Let us also mention that the degenerate curve ${\mathcal C}_{\rm deg}$ agrees with the spectral curve of the $\lb 2,3\rb$-minimal string, whose relation to \PIeq is known since \cite{BK1990,DS1990,GM1990}.


    \subsection{Weierstrass case\label{subsec_Weierstrass}}
    \subsubsection{General setup}
    Consider a smooth Weierstrass elliptic curve defined by 
    \begin{equation} \label{eq:spcurve}
    	{\mathcal C} ~:~ y^2 = 4x^3 - g_2 x - g_3, \qquad\qquad g_2=- 2 t, \quad g_3=- u,
    \end{equation}
    and fix a symplectic basis $\{A, B\}$ of $H_1({\mathcal C}, {\mathbb Z})$. The quantities  defined by the topological recursion depend on the choice of $\{A, B\}$. We will choose a specific basis when  we will discuss asymptotic expansions as $|t|\to \infty$. 

    Introduce the differential $W_{0,1}=ydx$ on $\mathcal C$ and consider its  normalized period 
    \begin{equation} \label{eq:nu}
   	\nu = \frac{1}{2 \pi i} \oint_A y\, dx.
   \end{equation}
    The parameter $u=u\lb t,\nu\rb$ in \eqref{eq:spcurve} will be considered as a function of two independent variables $t$ and $\nu$, 
    locally defined by the implicit relation \eqref{eq:nu}.  Throughout this subsection, 
    we assume that $\nu \ne 0$ and $\lb t,\nu\rb$ vary 
    in a domain where the discriminant 
    \begin{equation} \label{eq:discriminant}
    	\Delta = g_2^3-27g_3^2=-8t^3 -27 u^2 
    \end{equation}
    does not vanish. We use the following notation for the periods of the differentials of the first and second kind on $\mathcal C$:
     \begin{equation}\label{periodsAB}
     	\omega_{\ast} = \oint_{\ast} \frac{dx}{y}
     	,\qquad
     	\eta_{\ast} = - \oint_{\ast} \frac{x\, dx}{y},
     	\qquad \ast = A, B .
     \end{equation}
     These periods are holomorphic in both $t$ and $\nu$ 
     on the domain which we consider. 

     Let $L = {\mathbb Z} \omega_A + {\mathbb Z} \omega_B$ be the lattice generated by 
     the periods $\omega_{A,B}$, and let
     \begin{equation}
     	\wp(z) = \frac{1}{z^2} 
     	+ \sum_{\omega \in L \setminus \{(0,0) \}} 
     	\left( \frac{1}{\lb z - \omega\rb^2} - \frac{1}{\omega^2} \right) 
     	% + \sum_{(m,n) \in {\mathbb Z}^2 \setminus \{(0,0) \}} 
     	% \left( \frac{1}{(z - m \omega_A - n \omega_B)^2} - \frac{1}{(m \omega_A + n \omega_B)^2} \right) 
     \end{equation}
     denote the associated Weierstrass $\wp$-function. 
     Then, the (non-degenerate) \PIeq spectral curve is given by 
     \begin{equation} \label{eq:sp-PI}
     	\Sigma = {\mathbb C}/L\,, \qquad x\lb z\rb = \wp\lb z\rb, \qquad y\lb z\rb = \wp'\lb z\rb.
     \end{equation}
     Indeed, it is well-known that \eqref{eq:sp-PI} gives a meromorphic parameterization, 
     known as the Weierstarss parameterization, of the elliptic curve \eqref{eq:spcurve}. 
     The involution map 
     \begin{equation}
     	\sigma\lb z\rb \equiv - z  \mod L
     \end{equation}
     also induces the covering involution $\lb x,y\rb \mapsto \lb x, -y\rb$ of \eqref{eq:spcurve}.
     In this case, the set $R$ of ramification points 
     consists of half-periods: 
     \begin{equation} \label{eq:r123}
     	R = \left\{ r_1, r_2, r_3 \right\},\qquad\text{with}\qquad
     	r_1 = \frac{\omega_A}{2}, \quad
     	r_2 = \frac{\omega_B}{2}, \quad
     	r_3 = \frac{\omega_A+\omega_B}{2}.
     \end{equation} 
     Note that the $\wp$-function values at half-periods, $e_i = \wp\lb r_i\rb$ ($i=1,2,3$), give the three simple zeros 
     of the right hand side of \eqref{eq:spcurve} and satisfy ${e_1+e_2+e_3=0}$.   
     The $A$-cycle specified in the definition of the spectral curve is represented by 
     the closed loops encircling $e_2$ and $e_3$.
Sometimes it will be convenient for us to parameterize the curve $\mathcal{C}$, its discriminant $\Delta$ and elliptic invariants $g_2$, $g_3$ as
     \beq\label{invariants_es}
     \begin{gathered}
     y^2=4\lb x-e_1\rb\lb x-e_2\rb\lb x-e_3\rb,\qquad
     \Delta=16\lb e_1-e_2\rb^2 \lb e_2-e_3\rb^2 \lb e_3-e_1\rb^2,
     \\ g_{2}=-4\lb e_1e_2+e_2e_3+e_3e_1\rb,\qquad g_3=4e_1e_2e_3.
     \end{gathered}
     \eeq

     The last ingredient we need to be able to run the topological recursion is an expression for $W_{0,2}$. In general, for a given spectral curve $\lb \Sigma,x,y\rb$, it is given by
     a meromorphic fundamental bidifferential 
     $B = B\lb z_1,z_2\rb$,  
     called the Bergman bidifferential. It is uniquely defined by the following conditions: (i) $B$ is symmetric, (ii) all of its $A$-periods  vanish, and (iii) $B$ has a double pole along the diagonal and no other poles, and such that in any local coordinate $z$, 
     	\begin{equation}
     		B\lb z_1, z_2\rb \sim \left( \frac{1}{\lb z_1 - z_2\rb^2} + {\text{regular}
     	} \right) dz_1 dz_2,\qquad \text{as }z_1\to z_2.
     	\end{equation}
     In the case of the Weierstrass elliptic curve $\mathcal C$, this leads to the expression
     \beq\label{W02ell}
     W_{0,2}\lb z_1,z_2\rb=\lb \wp\lb z_1-z_2\rb+S\rb dz_1dz_2,
     \qquad S=\frac{\eta_A}{\omega_A},
     \eeq
     where $\omega_A,\eta_A$ are defined in \eqref{periodsAB}. The rest of the 
     TR equations of the previous subsection are universal. In particular,  it follows from \eqref{eq:rec-ker} and \eqref{W02ell} that the recursion kernel is given by
     \beq
     K\lb z_1,z\rb=\frac{\lb P\lb z_1-\tilde z\rb-P\lb z_1-z\rb\rb dz_1}{2\wp'\lb z\rb^2dz},\qquad P\lb z\rb=-\zeta\lb z\rb+S z.
     \eeq
     Here 
     \beq
     \zeta\lb z\rb=\frac{1}{z} 
     + \sum_{\omega \in L \setminus \{(0,0) \}} 
     \left( \frac{1}{z - \omega} + \frac{1}{\omega} +\frac{z}{\omega^2} \right) 
     \eeq
     is the Weierstrass zeta function satisfying $\zeta'\lb z\rb=-\wp\lb z\rb$. There is however a subtlety: one has to fix a fundamental domain $D$ by a choice of representatives of the homology basis $\left\{A,B\right\}$, and require that $\tilde z,z\in D$.


     \subsubsection{Correlators}
     In order to illustrate the issues one has to deal with in the elliptic case, let us compute the differentials $W_{0,3}$ and $W_{1,1}$ which correspond to $\chi_{g,n}=1$. From the TR defining relations \eqref{eq:top-rec}--\eqref{eq:R-gn}, we find e.g.
     \begin{align}
     \begin{aligned}
     &W_{0,3}\lb z_1,z_2,z_3\rb=\sum_{i=1,2,3}\Res_{z=r_i} K\lb z_1,z\rb 
     \lb W_{0,2}\lb z,z_2\rb  W_{0,2}\lb -z,z_3\rb+W_{0,2}\lb z,z_3\rb  W_{0,2}\lb -z,z_2\rb\rb=\\
     &=\sum_{i=1,2,3}\Res_{z=r_i} \frac{\lb P\lb z_1-z\rb- P\lb z_1-\tilde z\rb\rb\lb\wp\lb z-z_2\rb+S\rb \lb\wp\lb z+z_3\rb+S\rb}{2\wp'\lb z\rb^2}dz_1dz_2dz_3+\lb z_2\leftrightarrow z_3\rb.
     \end{aligned}
     \end{align}
     The denominator of the above expression has a double zero at every ramification point $r_i\in R$. Moreover, since both $\wp'\lb z\rb^2$ and
     $\lb\wp\lb z-z_2\rb+S\rb \lb\wp\lb z+z_3\rb+S\rb+\lb z_2\leftrightarrow z_3\rb$
     are even elliptic functions of $z$, their expansions around $z=r_i$ contain only even powers of $z-r_i$. The contribution coming from the residue at $z=r_i$ is therefore determined by the derivative $P'_z\lb z_1-z\rb\bigl|_{z=r_i}=-\wp\lb z_1-r_i\rb-S$, so that
     \beq\label{W03ell01}
     W_{0,3}\lb z_1,z_2,z_3\rb=\frac{4}{\Delta}\sum_{i=1,2,3}
     \lb 3e_i^2-g_2\rb \lb \wp\lb z_1-r_i\rb+S\rb \lb \wp\lb z_2-r_i\rb+S\rb \lb \wp\lb z_3-r_i\rb+S\rb  dz_1dz_2dz_3.
     \eeq
     In a completely similar manner, one finds
     \begin{align}
     \nonumber	W_{1,1}\lb z_1\rb
     	=&\,\sum_{i=1,2,3}\Res_{z=r_i} K\lb z_1,z\rb W_{0,2}\lb z,\sigma\lb z\rb\rb=
     	\sum_{i=1,2,3}\Res_{z=r_i}\frac{
     		\lb P\lb z_1-z\rb-P\lb z_1-\tilde z\rb\rb\lb\wp\lb 2z\rb+S\rb}{2\wp'\lb z\rb^2}dz_1=\\
     \label{W11ell01}		
     	=&\,\frac{2}{\Delta}\sum_{i=1,2,3}
     	\lb 3e_i^2-g_2\rb \lb \frac{\wp''\lb z_1-r_i\rb}{24}+\lb S-e_i\rb\lb \wp\lb z_1-r_i\rb+S\rb\rb dz_1,
     \end{align}
     At the last step of the residue computation leading to \eqref{W03ell01} and \eqref{W11ell01}, we have used the identities
     \beq
     \frac{1}{\wp''\lb r_i\rb^{2}}=\frac{4g_2-12e_i^2}{\Delta},
     \qquad  e_i=\ds \frac{\wp^{(4)}\lb r_i\rb}{12\wp''\lb r_i\rb},
     \eeq
      which can be deduced from the  differential equation $\wp''\lb z\rb=6\wp^2\lb z\rb-g_2/2$. 

      The formulas \eqref{W03ell01}--\eqref{W11ell01} reproduce   \cite[Eqs. (A.1)--(A.2)]{BCD18} up to an overall sign\footnote{It is not clear to authors whether this typo also affects higher-level differentials presented in \cite{BCD18}.}. This is, however, not the end of the story, since we need to express the result in terms of elliptic invariants $g_{2,3}$ instead of the ramification points $e_{1,2,3}$. Using the addition formula for $\wp\lb z\rb$, we can write, e.g.
      \beq
      \wp\lb z-r_1\rb-e_1=\frac{12e_1^2-g_2}{4\lb\wp\lb z\rb-e_1\rb}=\frac{\lb 12e_1^2-g_2\rb\lb x\lb z\rb-e_2\rb \lb x\lb z\rb-e_3\rb}{y^2\lb z\rb}.
      \eeq
      After substitution of such expressions into \eqref{W03ell01}--\eqref{W11ell01},  $W_{0,3}$ and $W_{1,1}$ transform into  linear combinations of differentials whose coefficients are symmetric polynomials in $e_{1,2,3}$. The latter can be algorithmically expressed as polynomials in $g_{2,3}$ using the relations \eqref{invariants_es} and  $4e_i^3= g_2 e_i+g_3$. E.g., $W_{1,1}$ is given by
      \beq\label{W11ell02}
      W_{1,1}\lb z_1\rb=\lb-\frac{12g_2 x\lb z_1\rb^2+36g_3 x\lb z_1\rb+g_2^2}{32y\lb z_1\rb^4}-\frac{x\lb z_1\rb+4S}{8 y\lb z_1\rb^2}+\frac{g_2\lb g_2-12S^2\rb}{4\Delta}\rb dz_1.
      \eeq

      The  procedure outlined above can in principle be continued at higher values of $\chi_{g,n}$. The analogs of \eqref{W03ell01} and \eqref{W11ell01} are relatively easy to compute from truncated Laurent expansions of $K\lb z_1,z\rb$ and $W_{g,n}\lb z_1,\ldots,z_n\rb$ at the ramification points. The most computationally involved step is (by far!) the  final symmetrization. We have calculated the  expressions of $W_{0,3}$, $W_{1,2}$ and $W_{2,1}$, but even for $W_{0,3}$ the counterpart of \eqref{W11ell02} is too lengthy to be usefully displayed here.

      To exhibit the homogeneity of $W_{g,n}$, let us define a scaling operator 
      \begin{equation} \label{eq:degree}
      	\varrho_r : \lb z,t,\nu\rb \mapsto \lb r^{- \frac{1}{5}} z, r^{\frac{4}{5}} t, r \, \nu \rb,
      	\qquad r \in {\mathbb R}_{>0}.
      \end{equation}
      Recall that $t=-g_2/2$, $u=-g_3$ and note that e.g. $\varrho_r\lb u,S\rb=\bigl( r^{\frac65}u,r^{\frac25}S\bigr)$. For a function $f\lb z,t,\nu\rb$ and a differential $f\lb z,t,\nu\rb \, dz$, we define 
      \begin{equation}
      	\lb \varrho_r\rb_\ast f\lb z,t,\nu\rb = f\lb r^{-\frac{1}{5}} z, r^{\frac{4}{5}} t, r \, \nu\rb, 
      	\qquad 
      	\lb \varrho_r\rb_\ast f\lb z,t,\nu\rb \, dz = r^{-\frac{1}{5}}f\lb r^{-\frac{1}{5}} z, r^{\frac{4}{5}} t, r \, \nu\rb \, dz, 
      \end{equation}
      and generalize this to multi-differentials in a natural way. Then we have 
      \begin{equation} \label{eq:degree-Wgn}
      	\lb \varrho_r\rb_\ast W_{g,n} = r^{-\chi_{g,n}} \, W_{g,n},
      	% (\varrho_r)_\ast F_g = r^{-(2g-2)} F_g.
      \end{equation}
      which can be proved by induction in $\chi_{g,n}$.

      The definition \eqref{W02ell} of $W_{0,2}$ 
      and the recursion relation \eqref{eq:top-rec} imply that $W_{g,n}$ with $\chi_{g,n} \ge 0$ are polynomial in $S$.
      The general structure of $W_{g,n}$ is described by 

      \begin{prop} \label{prop:pre-quasi-modular}
      		The correlator $W_{g,n}$ of the spectral curve \eqref{eq:sp-PI} with $\chi_{g,n} \ge 1$ 
      		has an expression of the form 
      		\begin{equation} \label{eq:qm-Wgn}
      			W_{g,n}\lb z_1,\ldots, z_n\rb = \frac{w_{g,n}\lb t,u,x\lb z_1\rb, \ldots, x\lb z_n\rb, S\rb}
      			{\Delta^{2g-2+n}  \prod_{i=1}^{n} y\lb z_i\rb^{6g-4+2n}} \, dz_1 \ldots dz_n.
      		\end{equation}
      		Here, the numerator takes the form 
      		\begin{equation} \label{eq:qm-Wgnk}
      			w_{g,n} = \sum_{k=0}^{3g-3+2n} w_{g,n,k}
      			\lb t,u,x\lb z_1\rb, \ldots, x\lb z_n\rb\rb 
      			S^k, 
      		\end{equation}
      		where $w_{g,n,k}$ is a polynomial in its arguments with constant coefficients, 
      		and satisfies 
      		\begin{equation} \label{eq:Pol-gnk-degree}
      			\lb \varrho_r\rb_\ast w_{g, n, k} 
      			= r^{\frac{1}{5}\lb 14g-14-2k+2n(9g+3n-2)\rb} \, w_{g,n, k}.
      		\end{equation}
      \end{prop}

      \pf
      	A proof of a similar result was given in \cite[Theorem 4.4]{FRZZ19}, where 
      	the mirror curves of some local Calabi--Yau 3-folds were discussed.
      	Although our setting is different from \cite{FRZZ19}, 
      	the proof can be carried out along the same lines. 
      	For convenience of the reader, we give a sketch of it. 

      	It may be shown   by induction that $W_{g,n}$ is a polynomial in $S$ 
      	with degree at most $3g-3+2n$.
      	When expressing $W_{g,n} / \lb dz_1 \ldots dz_n\rb$ as a rational function of $x\lb z_i\rb$ and $y\lb z_i\rb$, 
      	it is understood from the above considerations that the denominator is 
      	represented by even powers of $y\lb z_i\rb \, (= x'\lb z_i\rb$), and 
      	the numerator is a polynomial in $x\lb z_i\rb$.
      	When calculating according to the TR formula \eqref{eq:top-rec}, 
      	the discriminant of the denominator of \eqref{eq:qm-Wgn} arises 
      	when putting the residues at ramification points over a common denominator 
      	(by multiplying the series coefficients of $1/y(z)$ in the recursion kernel \eqref{eq:rec-ker}). 
      	Its degree, equal to the recursion level $\chi_{g,n}=2g-2+n$, can also be verified by induction. 
      	The relation \eqref{eq:Pol-gnk-degree} follows from the homogeneity \eqref{eq:degree-Wgn}. 
      \epf

      \subsubsection{Free energies and quasi-modular forms}
      For generic \PIeq  monodromy data, the contribution of the free energies $F_0$, $F_1$ to the function $\mathcal Z\lb s\,|\, \nu\rb$ turns out to be nontrivial. These quantities are separately defined in \cite{EO07} as
      \begin{equation} \label{eq:expression-F0-F1}
      	F_0  = \frac{g_2 g_3}{10} + \frac{\nu}{2} \, \oint_B y dx, \qquad
      	% \notag \\ 
      	% & = \frac{\nu^2}{2} \cdot 2 \pi i \, \frac{\omega_B}{\omega_A}
      	% + \frac{tu}{5} + \frac{2 t \nu}{5} \cdot \frac{2 \pi i}{\omega_A} \notag \\
      	% & = \frac{\nu^2}{2} \cdot 2 \pi i \, \frac{\omega_B}{\omega_A} 
      	%  + \frac{11 tu}{25} - \frac{8t^2}{25} \, \frac{\eta_A}{\omega_A}. 
      	F_1 = - \frac{1}{12} \ln \left( \omega_A^6 \, {\Delta} \right).
      \end{equation}

      The free energies  $F_{g}$ with $g\ge 2$ are determined by the same universal formula \eqref{Fgdef} as in the degenerate case, with the primitive $\Phi\lb z\rb$ now given by 
      \begin{lemma}
      	We have
      \begin{equation}\label{PhiEll}
      	\Phi\lb z\rb=\int^z y\,dx =\frac{1}{5}\lb 2\wp\lb z\rb\wp'\lb z\rb+2g_2\zeta\lb z\rb-3g_3z\rb.    
      \end{equation}
      \end{lemma}
      \pf Differentiate the right hand side and then use the equations $\wp''=6\wp^2-g_2/2$ and $\lb\wp'\rb^2=4\wp^3-g_2\wp-g_3$ to check that the result is indeed $\wp'\lb z\rb^2=y\lb z\rb x'\lb z\rb$. \epf
      \begin{cor}\label{Cor_W01periods}
      	The periods of $W_{0,1}$ can be expressed as
      	\beq\label{W01periods}
      	\oint_* ydx=\frac{2g_2\eta_*-3g_3\omega_*}{5},\qquad *=A,B.
      	\eeq
      \end{cor}
      \pf Straightforward consequence of \eqref{PhiEll} and quasiperiodicity relations  $\zeta\lb z+\omega_*\rb=\zeta\lb z\rb+\eta_*$.  \epf

      Using $\Phi\lb z\rb$, we have obtained surprisingly simple explicit answers for $F_2$ and $F_3$:
       \begin{subequations}
       	\label{F2and3}
     \begin{align}
     	&F_2=\frac{1}{\Delta^2}\left\{
     	\frac{15 }{2}g_2^2 S^3
     	+\frac{297 }{4 }g_2 g_3 S^2
     	+\frac{3}{8 } \left(14 g_2^3+297 g_3^2\right)S
     	+\frac{897 }{80 }g_2^2 g_3\right\},\\
     	&\label{F3ell}
     	\begin{aligned}
     	F_3=&\,\frac{1}{\Delta^4}\left\{405 g_2^4 S^6
     	+9720 g_2^3 g_3 S^5
     	+\frac{81}{4 } \left(56 g_2^3+4293 g_3^2\right) g_2^2 S^4
     	+\frac{27  }
     	{4 } \left(3121 g_2^3+49005 g_3^2\right)g_2 g_3 S^3\right.\\
     	&\qquad +\frac{9  }{80 }\left(1079028 g_2^3 g_3^2+8023 g_2^6+3207600 g_3^4\right)S^2
     	+\frac{729  }
     	{80}\left(899 g_2^3+22463 g_3^2\right)g_2^2 g_3 S\\
     	&\left.\qquad +\frac{1}
     	{2240 } \left(29176497 g_2^3 g_3^2+171350 g_2^6+174573630 g_3^4\right)g_2\right\}.
     	\end{aligned}
     \end{align}
     \end{subequations}
     The first-principles TR derivation of the last equation requires the knowledge of $W_{3,1}$. Although we have not succeeded to compute a symmetrized version of this differential similar to \eqref{W11ell02}, it is still possible to find an analog of the representation \eqref{W11ell01} in terms of $e_{1,2,3}$ and plug it into \eqref{Fgdef} to compute $F_3$. The  resulting 6-fold sum over  ramification points coming from the iterated residue computation can then be symmetrized (i.e. expressed in terms of $g_{2,3}$) which leads to \eqref{F3ell}.

     For free energies, the homogeneity property takes the form 
     \begin{equation} \label{eq:degree-Fg}
     	\lb \varrho_r\rb_\ast F_g = r^{-2\lb g-1\rb} F_g.
     \end{equation}
     % with respect top the scaling operator \eqref{eq:degree}.
     In the special case $g=1$ it is understood that $\lb \varrho_r\rb_\ast F_1$ is equal to $F_1$ up to an additive constant.
     Proposition~\ref{prop:pre-quasi-modular} implies
     that for  $g \ge 2$ the  free energy $F_g$ of the Weierstrass curve $\mathcal C$
     has an expression of the form 
     \begin{equation} \label{eq:rational-expression-Fg}
     	F_{g} = \frac{1} {\Delta^{2g-2}}\sum_{k=0}^{3g-3} f_{g, k}\lb t,u\rb 
     	S^k,
     \end{equation}
     where $f_{g, k}$ is a polynomial in $t$ and $u$ (equivalently, $g_2$ and $g_3$) with constant coefficients
     satisfying 
     \begin{equation} \label{eq:degree-Pol-gk}
     	\lb \varrho_r\rb_\ast f_{g, k} 
     	= r^{\frac{1}{5}(14g-14-2k)} \, f_{g, k}.
     \end{equation}




     In order to fully benefit from the homogeneity, we now define another parameterization. Introduce the elliptic nome and period ratio by
     \beq\label{nome_ratio}
     q=e^{2\pi i\tau},\qquad \tau = \frac{\omega_B}{\omega_A},\qquad \Im \tau>0.
     \eeq
     Note that we use the conventions where $q$ is the square of the usual nome. The quantities $S$, $g_2$ and $g_3$ parameterizing TR free energies with $g\ge2$  can then be rewritten as
     \begin{subequations}\label{eq:t-u-and-eisenstein} 
     \begin{align} 
     	\label{XE2}
     	S =&\, \frac {\pi^2 }{3 \omega_A^2}E_2,\\
     \label{g2E4}	g_2 =&\, \frac {4\pi^4 }{3 \omega_A^4} E_4,\\
     \label{g3E6}	g_3 =&\, \frac {8\pi^6 }{27 \omega_A^6}E_6,
     \end{align}
     \end{subequations}
     where $E_{2n}=E_{2n}\lb q\rb$ denote the Eisenstein series defined by
     \begin{align}\label{eisensteindef}
     	E_{2n}\lb q\rb = 1 - \frac{4n}{B_{2n}} \sum_{k=1}^{\infty} \frac{k^{2n-1} q^k}{1 - q^k},
     	\qquad n\in \mathbb N. 
     \end{align}
     In this definition, $B_{2n}$ stand for Bernoulli numbers (hence e.g. $B_2=\frac16$, $B_4=-\frac1{30}$, $B_6=\frac{1}{42}$). It is useful to keep in mind that later in the paper we will be interested in the asymptotic regime where $q$ is small. 

     The Eisenstein series  $E_2$ is a quasi-modular form with weight 2 and depth 1, while $E_4$ and $E_6$ are modular forms with weights $4$ and $6$, respectively. This means that they have a certain behavior under the transformations  
     \beq
     \tau\mapsto \frac{\alpha\tau+\beta}{\gamma\tau+\delta},\qquad
     \lb\begin{array}{cc}\alpha  & \beta \\ \gamma & \delta\end{array}\rb\in\mathrm{SL}_2\lb\mathbb Z\rb.
     \eeq 


     Using \eqref{nome_ratio}--\eqref{eq:t-u-and-eisenstein} and Corollary~\ref{Cor_W01periods}, the normalized $A$-period of $W_{0,1}$-differential (which will play a role of the monodromy parameter in the relation to \PIeq) can now be expressed as
     \beq\label{numodular}
     \nu=\lb\frac{2\pi i}{\omega_A}\rb^5\frac{E_6-E_2E_4}{360}.
     \eeq
     Similar calculations, together with the Riemann bilinear identity $\eta_A\omega_B-\eta_B\omega_A=2\pi i$, lead to the following representation of the genus 0 free energy:
     \beq\label{F0modular}
     F_0=\nu^2\left[i\pi\tau+\frac{E_4\lb 6E_2E_4-11E_6\rb}{\lb E_6-E_2E_4\rb^2}\right].
     \eeq
     Let us also express the discriminant  $\Delta = g_2^3-27 g_3^2$
     of the elliptic curve $\mathcal C$  as
     \begin{equation} \label{eq:delta-eta}
     	\Delta = 
     	 \left( \frac{2\pi i}{\omega_A} \right)^{12} 
     	\frac{E_4^3 - E_6^2}{1728} 
     	= \left( \frac{2\pi i}{\omega_A} \right)^{12} \eta^{24},
     \end{equation}
     where $\eta = \eta\lb q\rb$ is the Dedekind eta function:
     \begin{equation}
     	\eta\lb q\rb = q^{\frac{1}{24}} \, \prod_{k=1}^{\infty} \lb 1 - q^k\rb.
     \end{equation}
     The free energy $F_1$ is therefore given (here and below, $F_1$ will be considered only up to an irrelevant additive numerical constant) by
     \beq\label{F1modular}
     F_1=-\frac1{12}\ln \lb\frac{2\pi}{\omega_A}\rb^6\lb E_4^3-E_6^2\rb.
     \eeq


        The quasi-modular structure of  $F_{g}$ with $g\ge 2$ is described by the following statement.
    \begin{prop}[{cf. \cite[Theorem 4.4]{FRZZ19}}]\label{prop_FgStructure}
    	The $g$th free energy of the spectral curve \eqref{eq:sp-PI} with $g \ge 2$ has the following expression: 
    	\begin{equation} \label{eq:Fg-quasi-modular-expression}
    		F_g = \left( \frac{\xi}{E_4} \right)^{2g-2} P_{g}\lb E_2, E_4, E_6\rb,
    		% = 
    		% \frac{P_{g}(E_2, E_4, E_6)}{(\eta^{24})^{2g-2}} \,  \left( \frac{\omega_A}{2\pi i} \right)^{10(g-1)},  
