% -\frac{2}{3} + \frac{3 \nu \Lambda}{8} + \frac{259 \nu^2 \Lambda^2}{512} + \frac{7989 \nu^3 \Lambda^3}{8192} + \frac{3430605 \nu^4 \Lambda^4}{2097152} - \frac{3910159 \nu^5 \Lambda^5}{4194304} + O\lb \Lambda^{6} \rb, \\
% -\frac{2}{3} - \frac{i \nu}{2 s} - \frac{259 \nu^2}{288 s^2} + \frac{2663 i \nu^3}{1152 s^3} + \frac{1143535 \nu^4}{221184 s^4} + \frac{3910159 i \nu^5}{995328 s^5} + O\lb s^{-6}\rb, \\
\tilde{e}_2 & = \frac{1}{3} + (\nu \Lambda)^{1/2} - \frac{\nu \Lambda}{2} 
 + \frac{25}{64} (\nu \Lambda)^{3/2} -\frac{49 \nu^2 \Lambda^2}{64} 
 + \frac{8139}{8192} (\nu \Lambda)^{5/2} - \frac{4543 \nu^3 \Lambda^3}{2048} +  O\lb \Lambda^{7/2} \rb,
\label{tilde-e2}
\\
\tilde{e}_3 & = \frac{1}{3} - (\nu \Lambda)^{1/2} - \frac{\nu \Lambda}{2} 
 -  \frac{25}{64} (\nu \Lambda)^{3/2} -\frac{49 \nu^2 \Lambda^2}{64} 
 - \frac{8139}{8192} (\nu \Lambda)^{5/2} - \frac{4543 \nu^3 \Lambda^3}{2048} +  O\lb \Lambda^{7/2} \rb.
\label{tilde-e3}
