\end{subequations}
These behaviors are consistent with the equalities 
\begin{equation}
   4(\tilde{e}_1 \tilde{e}_2+\tilde{e}_1 \tilde{e}_3+\tilde{e}_2 \tilde{e}_3) = -\frac{4}{3}, \qquad 
   -4\tilde{e}_1 \tilde{e}_2 \tilde{e}_3=U.
\end{equation}
Moreover, we can show that the curve \eqref{eq:rescaled-sp-curve} has 
a limit when $\Lambda \to 0$, and the limiting curve 
\begin{equation} \label{eq:singular-elliptic-curve}
{\mathcal C}^{\rm res}_{\rm deg} ~:~ Y^2 = 4(X-1/3)^2 (X+2/3)
\end{equation}
is a degenerate elliptic curve, which is equivalent to 
the degenerate curve ${\mathcal C}_{\rm deg}$ under the same rescaling \eqref{eq:scaling-data}.
The $A$-cycle tends to small closed circle around the double point $1/3$.


\subsubsection{Series expansion of correlators} \label{subsec:TR-expansion}

Let us now compute the series expansion of the correlator $W_{g,n}$ in the limit $\Lambda \to 0$. 
% $s \to \infty$, or equivalently 
Below, we will use the rescaled variable $X$ to express the correlators, 
and regard $X$ (and its copies) as a $\Lambda$-independent variable(s) in analyzing the small $\Lambda$ expansion. 
% More precisely, we will analyze the large $s$ behavior of the meromorphic function $W_{g,n}/(dX_1 \cdots dX_n)$. 


Using \eqref{g2E4}--\eqref{g3E6} and \eqref{nome_expansion_2}, we have 
\begin{equation}
U = \frac{8}{27} - 4 \nu \Lambda + \frac{15 \nu^2 \Lambda^2}{8}  + \frac{705 \nu^3 \Lambda^3 }{256} 
+ \frac{115755 \nu^4 \Lambda^4 }{16384} + \frac{23968161 \nu^5 \Lambda^5 }{1048576}
+ O(\Lambda^{6}).
% \frac{8}{27} + \frac{16 i \nu}{3s} - \frac{10 \nu^2}{3 s^2} + \frac{235 i \nu^3}{36 s^3} 
% + \frac{38585 \nu^4}{1728 s^4} - \frac{2663129 i \nu^5}{27648 s^5} + O\lb s^{-6}\rb.
% \frac{8}{27} \left[1 + \frac{18 i\nu}{s}-\frac{45}{4}\frac{\nu^2}{s^2} +\frac{705}{32}\frac{i\nu^3}{s^3}+\frac{38585}{512}\frac{\nu^4}{s^4} -\frac{2663129}{8192}\frac{i\nu^5}{s^5}+O\lb s^{-6}\rb\right].
\end{equation}
This allows us to see that $Y$ has the following series expansion
\begin{equation} \label{eq:series-Y}
Y = \sqrt{4X^3-4X/3+U} = \sum_{k \ge 0} Y^{[k]}(X) \, (\nu \Lambda )^k
\end{equation}
when $\Lambda \to 0$, where $Y^{[k]}$ are meromorphic functions on 
the degenerate curve ${\mathcal C}^{\rm res}_{\rm deg}$ 
and are explicitly given as 
\begin{equation}
Y^{[0]} = 2(X-1/3)\sqrt{X+2/3}, \quad 
Y^{[1]} = - \frac{1}{(X-1/3) \sqrt{X+2/3}}, \quad
Y^{[2]} = \frac{135X^3-45X-62}{288(X-1/3)^3 (X+2/3)^{3/2}},\ \dots
\end{equation}
These are independent of $\nu$ and $\Lambda$, and can be determined at any order in principle. 
The relation \eqref{eq:rescaled-A-period} implies that the
$A$-cycle tends to negatively-oriented small closed circle around $1/3$ so that
\begin{equation} \label{eq:branch-sqrt}
\frac{1}{2 \pi i} \oint_A  Y^{[k]} \, dX = - \Res_{X=1/3} Y^{[k]} \, dX =
\begin{cases} 
1 & k = 1, \\
0 & k \ne 1.
\end{cases} 
\end{equation}
The series expansion \eqref{eq:series-Y} immediately implies that 
$W_{0,1} = y dx = \Lambda^{-1} Y dX$ admits a series expansion of the form
\begin{equation} \label{eq:ser-W01}
W_{0,1}(X)  = \Lambda^{-1} \sum_{k \ge 0}  W_{0,1}^{[k]}(X) \, (\nu\,\Lambda)^k.
\end{equation}
Here, by definition, $W_{0,1}^{[k]} = Y^{[k]} \, dX$.

Next, let us compute the expansion of $W_{0,2}$. 
Using the addition formula for the $\wp$-function, 
we can express the Bergman bidifferential in \eqref{W02ell} as follows: 
\begin{equation} \label{eq:Bergman-via-XY}
W_{0,2}(X_1, X_2) % ~ \Bigl( = W^{\rm res}_{0,2}(X_1, X_2)  \Bigr) 
= \left( \frac{1}{4}\Bigl( \frac{Y_1 + Y_2}{X_1 - X_2} \Bigr)^2 
- X_1 - X_2 + \frac{\widetilde{\eta}_A}{\widetilde{\omega}_A} \right) 
\frac{dX_1 \, dX_2}{Y_1 \, Y_2}.
\end{equation}
Here, $(X_i, Y_i) = (X_i, Y(X_i))$ ($i=1, 2$) 
denotes the copies of rescaled variables, and 
\begin{equation}  \label{eq:rescaled-omega-eta-A}
\widetilde{\omega}_A = \oint_{A} \dfrac{dX}{Y}, 
\quad
\widetilde{\eta}_A = - \oint_{A} \dfrac{X dX}{Y}.
\end{equation}
Combining the series expansion \eqref{eq:series-Y} of $Y$ with
\begin{equation}
\frac{\widetilde{\eta}_A}{\widetilde{\omega}_A} 
% = \gamma^{-2} \frac{\eta_A}{\omega_A} 
= \gamma^{-2} \frac{\pi^2}{3 \omega_A^2} E_2
= - \frac{1}{3} + \frac{3 \nu \Lambda}{4} + \frac{45 \nu^2 \Lambda^2}{32} 
+ \frac{19035 \nu^3 \Lambda^3}{4096} + \frac{2430855 \nu^4 \Lambda^4}{131072} 
+ \frac{1366185177 \nu^5 \Lambda^5}{16777216} + O(\Lambda^6), 
\end{equation}
which can also be computed by \eqref{nome_expansion_2}, 
we can obtain a series expansion of $W_{0,2}$ of the form 
\begin{equation} \label{eq:expansion-W02}
W_{0,2}(X_1, X_2) = \sum_{k \ge 0} W_{0,2}^{[k]}(X_1, X_2) \, (\nu \, \Lambda)^k.
\end{equation}
Here, the coefficients $W_{0,2}^{[k]}(X_1, X_2)$ are meromorphic bidifferentials 
on ${\mathcal C}^{\rm res}_{\rm deg}$ and are independent of $\nu$ and $\Lambda$. 
The first few coefficients are given explicitly as 
\begin{subequations}
\begin{align}
W_{0,2}^{[0]}(X_1, X_2) & = \frac{4 + 3X_1 + 3X_2 + 6 \sqrt{X_1+2/3} \sqrt{X_2 + 2/3}}
{12(X_1 - X_2)^2 \sqrt{X_1 + 2/3} \sqrt{X_2 + 2/3}}  \, dX_1 dX_2 
\\[+.5em]
W_{0,2}^{[1]}(X_1, X_2) & = \frac{dX_1 dX_2}{432 \, (X_1-1/3)^2(X_2-1/3)^2 (X_1+2/3)^{3/2}(X_2+2/3)^{3/2}}
\notag  \\
& \hspace{-2.5em}
\times \Bigl( 
34 + 66 (X_1 + X_2) + 36 (X_1^2 + X_2^2) + 171 X_1 X_2 + 27 X_1 X_2(X_1+X_2) + 81 X_1^2 X_2^2 \Bigr).
\label{eq:W02-2}
\end{align}
\end{subequations}

% The coefficients at any order term can also be computed in principle. 


For general $(g,n)$, we have 

\begin{prop} \label{prop:expansion-Wgn}
For each  $g \ge 0$ and $n \ge 1$, % with $2g-2+n \ge 1$, 
the correlator $W_{g,n}$ of the spectral curve ${\mathcal C}$
has a convergent series expansion at $\Lambda = 0$ of the following form:
\begin{equation}\label{eq:expansion-Wgn}
W_{g,n}(X_1, \dots, X_n) = 
\Lambda^{2g-2+n} \,  \sum_{k \ge 0} 
W_{g,n}^{[k]}(X_1, \dots, X_n) \, (\nu \, \Lambda)^{k}.
\end{equation}
The coefficients $W_{g,n}^{[k]}$ are meromorphic multi-differentials 
on the degenerate curve ${\mathcal C}^{\rm res}_{\rm deg}$. 
% given in \eqref{eq:singular-elliptic-curve}. 
\end{prop}

\begin{proof}
Since we have already seen that $W_{0,1}$ and $W_{0,2}$ admit a series expansion, 
we will now show by induction that $W_{g,n}$ with $2g-2+n \ge 1$ also admit a series expansion. 

Let ${W}^{\rm res}_{g,n}$ be the correlator of the type $(g,n)$ defined by the topological recursion 
from the rescaled spectral curve ${\mathcal C}^{\rm res}$ defined in \eqref{eq:rescaled-sp-curve}. 
It follows from the relation $W_{0,1} = \Lambda^{-1} {W}^{\rm res}_{0,1}$ 
and the recursion relation \eqref{eq:top-rec} that 
\begin{equation}
W_{g,n}(X_1, \dots, X_n)  = \Lambda^{2g-2+n} {W}^{\rm res}_{g,n}(X_1, \dots, X_n)  
\label{eq:scaling-degree-Wgn}
\end{equation}
hold for all $g$ and $n$. 
Therefore, our task is to show the existence of the power series expansion of ${W}^{\rm res}_{g,n}$
when $\Lambda \to 0$. 
However, we should note that a collision of ramification points (i.e., $\tilde{e}_2, \tilde{e}_3 \to 1/3$) 
happens when $\Lambda \to 0$.
Since the integrand of the defining formula \eqref{eq:top-rec} for the correlator
has singularities at those points,  the original definition \eqref{eq:top-rec} 
is not useful to derive a series expansion. 

To overcome this difficulty, we use the following alternative expression of \eqref{eq:top-rec} 
which can be derived using the residue theorem in a manner analogous to \cite[Lemma B.1]{Iwaki19}:
\begin{align} 
W^{\rm res}_{g,n}(X_1, \dots, X_n) 
& = 
\frac{dX_1}{\widetilde{\omega}_A \, Y(X_1)} \,  
\oint_{X \in A} \frac{{R}^{\rm res}_{g,n}(X, X_2, \dots, X_n)}
{2 W_{0,1}^{\rm res}(X)} % {2 Y(X) \, dX}  
- 2 
\sum_{i=1}^{n}  \Res_{X=X_i} \frac{\int^{X'=X}_{X'=\infty} {W}^{\rm res}_{0,2}(X_1, X')}
{2 W_{0,1}^{\rm res}(X)} % {2 Y(X) \, dX}  
\, {R}^{\rm res}_{g,n}(X, X_2, \dots, X_n).
\label{eq:alternative-TR-scaling}
\end{align}
Here, ${R}^{\rm res}_{g,n}$ is obtained from $R_{g,n}$ given in \eqref{eq:R-gn} 
by replacing $W_{g,n}$ by ${W}^{\rm res}_{g,n}$, and 
we have chosen the base point in \eqref{eq:rec-ker} as $\tilde{z} = 0$.
Under the induction hypothesis, ${R}^{\rm res}_{g,n}$ also has a series expansion of the form 
\begin{equation}
{R}^{\rm res}_{g,n}(X, X_2, \dots, X_n)
= \sum_{k \ge 0} R_{g,n}^{[k]}(X, X_2, \dots, X_n)(\nu \Lambda)^{k}.
\end{equation}
The coefficients $R_{g,n}^{[k]}(X, X_2, \dots, X_n)$ are 
meromorphic multi-differentials on ${\mathcal C}^{\rm res}_{\rm deg}$. 
The aforementioned collision of ramification points 
does not cause the integration cycles in both terms of \eqref{eq:alternative-TR-scaling} to be pinched.
Therefore, the integration over the $A$-cycle and residue calculation at $X = X_i$ can be performed term-wise. 
In particular, the expansion coefficients of the $A$-cycle integral of the first term 
can be obtained term by term by calculating the residue at $X = 1/3$, similarly to \eqref{eq:branch-sqrt}.
Therefore, we can inductively verify that $W_{g,n}$ have a convergent series expansion 
of the form \eqref{eq:expansion-Wgn} when $\Lambda$ tends to $0$. 
% In particular, each coefficients are computable term-by-term at any order. 
% The properties on poles of the coefficients 
% $W_{g,n}^{[k]}$, which is claimed in Proposition \ref{prop:expansion-Wgn}, also follow from the induction hypothesis. 
This completes the proof of Proposition \ref{prop:expansion-Wgn}. 
\end{proof}

From the proof, it can also be seen that the coefficient $W_{g,n}^{[k]}$ 
with $2g-2+n \ge 1$ has poles only at branch points, infinity, and at two preimages of $X_i = 1/3$. 
These coefficients are independent of $\nu$ and $\Lambda$ and are explicitly computable at any order. 
This approach also enables us to derive the series expansion without requiring the explicit form 
of the correlator such as \eqref{W11ell02}. For example, the above algorithm provides
\begin{equation}
W_{0,3}^{[0]}(X_1, X_2, X_3) = 
\frac{dX_1 dX_2 dX_3}{32(X_1+2/3)^{3/2}(X_2+2/3)^{3/2}(X_3+2/3)^{3/2}}, \qquad
W_{1,1}^{[0]}(X_1) =  
\frac{(3X_1+5) dX_1}{192(X_1+2/3)^{5/2}}.
\end{equation}



\subsubsection{Series expansion of $F_g$ and conifold gap property}
\label{sec:series-exp-Fg}

We have already seen in \eqref{expansion_F0}--\eqref{expansion_F3} that 
the first few free energies $F_g$ admit a series expansion at $\Lambda = 0$. 
The main claim of this section, 
which justifies the previous properties \eqref{conigap}--\eqref{eq:kappa_g}, 
is the following. 

\begin{theo}\label{thm:coni-gap}
For each $g \ge 2$, the $g$-th free energy $F_g$ of the spectral curve ${\mathcal C}$ 
has a convergent series expansion at $\Lambda = 0$ of the following form:
\begin{equation} \label{eq:expansion-Fg}
F_g  = % \frac{\kappa_g}{\nu^{2g-2}} 
\frac{B_{2g}}{4g(g-1) \, \nu^{2g-2}} + \Lambda^{2g-2} \sum_{k \ge 0} F_g^{[k]} \, (\nu \, \Lambda)^k. 
\end{equation}
% where the leading term $\chi_g$ is described by the Bernoulli number as
% \begin{equation} \label{eq:Bernoulli-formula} \kappa_g  = \frac{B_{2g}}{2g(2g-2)}, \end{equation}
The coefficients $F_g^{[k]} \in {\mathbb C}$ are 
independent of $\nu$ and $\Lambda$ and are explicitly computable at any order. 
\end{theo}

\begin{proof}
Since $\xi$, given in \eqref{eq:Yukawa}, has an expansion 
\begin{equation}
\xi = \frac{1}{\nu} \left[1  + \frac{141 \nu \Lambda}{32} + \frac{23151 \nu^2 \Lambda^2}{1024} 
 + \frac{7989387 \nu^3 \Lambda^3}{65536} + \frac{1412410545 \nu^4 \Lambda^4}{2097152} 
 + \frac{506532905109 \nu^5 \Lambda^5}{134217728} +O(\Lambda^6)
 \right], 
\end{equation} 
the expression \eqref{eq:Fg-quasi-modular-expression} implies that 
$\nu^{2g-2} F_g$ with $g \ge 2$ has a convergent series expansion with respect to $(\nu \Lambda)$. 
% and the rational coefficients are rational numbers. 
The non-trivial aspects of the statement are as follows:
\begin{itemize}
\item 
The gap property \eqref{conigap}; i.e., the absence of the coefficients of 
$\Lambda^{1}, \dots, \Lambda^{2g-1}$ in \eqref{eq:expansion-Fg}. 

\item 
The expression \eqref{eq:kappa_g} of leading term. 
\end{itemize}

The gap property can be shown as follows. Here we employ the variational formula
\begin{equation} \label{eq:vari-Fg}
\frac{\partial F_g}{\partial t} 
= \Res_{z=0} \frac{W_{g,1}(z)}{z} 
= 2 \Res_{X=\infty} \left( \Lambda^{2g-1 - \frac{1}{5}} \sum_{k \ge 0} 
X^{\frac{1}{2}}  W_{g,1}^{[k]}(X) \, (\nu \Lambda)^{k}  \right),
% \qquad
% \frac{\partial F_g}{\partial \nu} = \oint_B W_{g,1}(z),
\end{equation}
which is valid for $g \ge 1$ (see \cite[Theorem 5.1]{EO07} and \cite[Proposition 3.4]{Iwaki19}). 
Since the residue cycle around $X = \infty$ is not pinched by 
the merging pair $\tilde{e}_2, \tilde{e}_3$ of ramification points, 
we can take the residue in the right hand side of \eqref{eq:vari-Fg} term-wise. 
Thus we can verify that $\partial F_g/ \partial t$ has a series expansion at $\Lambda = 0$, 
and the absence of the coefficients of 
$\Lambda^{1}, \dots, \Lambda^{2g-1}$ in \eqref{eq:expansion-Fg}. 
Moreover, the variational formula \eqref{eq:vari-Fg} fixes all series coefficients of $F_g$ by
\begin{equation} \label{eq:Fgk-formula}
\frac{15(2g-2+k)}{8} \, F_g^{[k]} = 
2 \Res_{X=\infty} X^{\frac{1}{2}} W_{g,1}^{[k]}(X) \qquad (k \ge 0).
\end{equation} 
except for a $t$-independent leading term. 

Next, let us prove the formula \eqref{eq:kappa_g} for the leading term of $F_g$. 
The proof is technical and would be lengthy if presented in full, 
so here we will outline several key equalities, 
with the detailed derivation provided in Appendix \ref{appendix:constant-term}.
To prove \eqref{eq:kappa_g}, we apply the following symplectic transformation 
$(x,y) \mapsto (\widetilde{X}, \widetilde{Y})$ 
to the (unrescaled) spectral curve ${\mathcal C}$: 
\begin{equation} \label{eq:symplectic-tr-to-Weber}
(x,y) = \left( \frac{{e}_2+ {e}_3}{2} + \alpha \widetilde{X}, \alpha^{-1} \widetilde{Y} \right), 
\qquad 
\alpha = \left(-\frac{1}{24 {e}_1}\right)^{1/4},
\end{equation}
where $e_1, e_2, e_3$ are the zeros of the right hand side of \eqref{eq:spcurve}. 
% the defining equation of the spectral curve ${\mathcal C}$.
% whose labels and behaviors at $\Lambda \to 0$ (i.e., $t \to - \infty$) were given in \eqref{eq:series-zeros}. 
It transforms the spectral curve ${\mathcal C}$ into 
\begin{equation} \label{eq:spcurve-Weber-expression}
\widetilde{\mathcal C} ~:~\widetilde{Y}^2 = (1 + 16 \alpha^5  \widetilde{X} ) 
\left( \frac{\widetilde{X}^2}{4} - \frac{({e}_2 - {e}_3)^2}{16 \alpha^2}\right).
\end{equation}
It is known (and easily verified in this case) that 
the symplectic transformation \eqref{eq:symplectic-tr-to-Weber} 
preserves the correlator $W_{g,n}$ and free energy $F_{g}$ (cf. \cite[\S 7]{EO07}). 
% We will compute the limit \eqref{eq:limit-Fg-appendix} through the expression \eqref{eq:spcurve-Weber-expression} of the spectral curve.
%%%
% Here and in what follows, we regard $\widetilde{X}$ as a $t$-independent coordinate. 
The key observation is the following: 
\begin{equation}
\lim_{\Lambda \to 0}(1 + 16 \alpha^5  \widetilde{X} ) 
\left( \frac{\widetilde{X}^2}{4} - \frac{(e_2-e_3)^2}{16 \alpha^2}\right)
= \frac{\widetilde{X}^2}{4} - \nu.
\end{equation}
This follows immediately from the behavior \eqref{tilde-e1}--\eqref{tilde-e3} of $e_i$. 
Therefore, the limit of the spectral curve $\widetilde{\mathcal C}$ becomes
\begin{equation} \label{eq:Weber-curve}
{\mathcal C}_{\rm Web} ~:~ \widetilde{Y}^2 = \frac{\widetilde{X}^2}{4} - \nu, 
\end{equation}
which is called the Weber curve. 
% Here we set $\widetilde{Y}_0(\widetilde{X}) % = \widetilde{Y}_0(\widetilde{X}) 
% = \lim_{\Lambda \to 0} \widetilde{Y}(\widetilde{X})$. 
% We also note that our $A$-cycle in $\widetilde{\mathcal C}$ is reduced to the residue cycle around $\widetilde{X} = \infty$ in this limit. 
As is well-known, the free energy $F_{g}^{\rm Web} $ of 
the Weber curve ${\mathcal C}_{\rm Web}$ is given by 
\begin{equation} \label{eq:Weber-free-energy-explicit}
F_{g}^{\rm Web} = \frac{B_{2g}}{4g(g-1) \, \nu^{2g-2}} \qquad (g \ge 2).
\end{equation}
(See \cite[Theorem 1]{Nor09}, \cite[Theorem 4.9]{IKoT1} for the proof). 
Therefore, the desired property \eqref{eq:kappa_g} is established by proving that 
the topological recursion and limit of the spectral curve commute, that is, 
\begin{equation} \label{eq:limit-Fg-appendix}
\lim_{\Lambda \to 0} F_g = F_{g}^{\rm Web}
\quad (g \ge 2).
\end{equation}
The details of this final step are provided in Appendix \ref{appendix:constant-term}. 
\end{proof}

\begin{rmk}
In cases where a family of spectral curves depending on a parameter arises, as discussed in this paper, 
the commutativity between the limit with respect to the parameter and the application of 
topological recursion often becomes a significant issue.
Indeed, in \cite{BouSul12}, an example is provided where the limit of the spectral curve and the topological recursion do not commute.
The commutativity with the limit has been discussed in a recent paper \cite{BBCKS23}, 
where the "constant genus assumption" is imposed, 
meaning that the genus of the spectral curve remains fixed during the limiting process. 
However, the example treated in this paper provides an example where the elliptic curve 
reduces to the Weber curve with genus $0$, yet the topological recursion commutes with the limit.
\end{rmk}


\begin{rmk}
Slightly digressing from the main discussion, let us make a brief yet meaningful observation here.
As stated in the Proposition \ref{prop:expansion-Wgn}, 
the coefficients $W_{g,n}^{[k]}$ define multi-differentials on the degenerate curve ${\mathcal C}_{\rm deg}^{\rm res}$. 
In fact, the constant term $W_{g,n}^{[0]}$ coincides with the correlator 
of the degenerate curve ${\mathcal C}_{\rm deg}$ discussed in Section \ref{subsec_warmup} 
(through the rescaling in equation \eqref{eq:scaling-data}). 
More specifically, if we denote by $W_{g,n}^{\rm deg}$ the correlator
of ${\mathcal C}_{\rm deg}$, then the following holds:
\begin{equation} \label{eq:Wgn-0-and-deg}
W_{g,n}^{\rm deg}(z_1, \dots, z_n) = \Lambda^{2g-2+n} W_{g,n}^{[0]}(X_1, \dots, X_n)
\end{equation}
under the change of coordinate $X_i = (z_i/ \gamma)^2 - 2/3$ for $i = 1, \dots, n$.
This relation can be easily proved by comparing the first terms of the 
$\Lambda$-expansion on both sides of \eqref{eq:alternative-TR-scaling}. 
(It can be similarly shown that $W_{g,n}^{\rm deg}$ satisfies the same relation; see \cite[Theorem 3.11]{IS16}.) 
Combining the variational formula \eqref{eq:vari-Fg} with \eqref{eq:Wgn-0-and-deg}, 
we can also prove that the the free energy $F_{g}^{\rm deg}$ 
of the degenerate curve ${\mathcal C}_{\rm deg}$ appears in the expansion 
\eqref{eq:expansion-Fg} of $F_g$ as 
\begin{equation} \label{eq:Fgdeg-as-subleading}
F_{g}^{\rm deg} = \Lambda^{2g-2} F_{g}^{[0]} \quad (g \ge 2).
\end{equation}
\end{rmk}




     \section{Holomorphic anomaly equation\label{sec_HAE}}

     This section is devoted to the so-called holomorphic anomaly equation (HAE), 
     given in \eqref{eq:HAE} below. % satisfied by $F_g$. 
     We review a method of recursive computation of the TR free energies, based on the HAE and 
     the conifold gap property shown 
     in Theorem \ref{thm:coni-gap}.
     The method itself is a well-known technique that originated in \cite{BCOV93v2} and has been widely employed in the context of topological string theory (higher genus B-model), supersymmetric gauge theory and quantum mechanics \cite{HK06,HK09,KW10,HK10,HKPK11,CM16,FMP23,FGMS23}. We are concerned here with a proof of existence and uniqueness of the HAE solutions. As explained below, with the rigorous proof of the conifold gap property 
     the existence is established as an application. 
     Besides, we introduce special bases for holomorphic ambiguities and use them to prove uniqueness of the HAE solution.   

     \subsection{General setup}

     In what follows, we will mean by $\partial F_g / \partial E_2$  the derivative of 
     the expression \eqref{eq:Fg-quasi-modular-expression} for $F_g$ obtained by the differentiation of the polynomial $P_g\lb E_2,E_4,E_6\rb$ with respect to $E_2$, regarding the prefactor of $P_g$ as a constant.
     The following theorem relates $\partial F_g / \partial E_2$ to lower genus free energies. 


     \begin{theo}[{\cite[Theorem 6.1]{EO07}}] \label{thm:TR-HAE}
     	For $g \ge 2$, the $g$-th free energy of the \PIeq spectral curve \eqref{eq:sp-PI} satisfies the
     	holomorphic anomaly equation 
     	\begin{equation} \label{eq:HAE}
     		\frac{\partial F_g}{\partial E_2} =  - \frac{1}{24} 
     		\left[ \frac{\partial^2 F_{g-1}}{\partial \nu^2} 
     		+ \sum_{h=1}^{g-1} \frac{\partial F_{h}}{\partial \nu} 
     		\, \frac{\partial F_{g-h}}{\partial \nu} \right]. 
     	\end{equation}
     \end{theo}

     \pf
     	Our Bergman bidifferential \eqref{W02ell} is written as 
     	\begin{equation}
     		W_{0,2}\lb z_1, z_2\rb = \left( \omega_A^2 \wp(z_1 - z_2) + 2 \pi i \kappa \right) \, 
     		\frac{dz_1}{\omega_A} \, \frac{dz_2}{\omega_A}, \qquad
     		\kappa = \frac{\eta_A \omega_A}{2\pi i}.
     	\end{equation}
     	% The correlator $W_{g,n}$ with $2g-2+n \ge 1$ and the free energy $F_g$ with $g \ge 2$ are polynomial in $\kappa$ defined here. 
     	As shown in \cite[Theorem 6.1]{EO07}, the derivatives of $W_{g,n}$ and $F_g$ 
     	with respect to $\kappa$ can be written again by certain period integrals 
     	of $W_{g,n}$ with different $(g,n)$.
     	The explicit formula for $\partial F_g / \partial \kappa$ reads 
     	\begin{align}
     		2\pi i \frac{\partial F_g}{\partial \kappa} & = 
     		\frac{1}{2} \oint_{z_1 \in B} \oint_{z_2 \in B} W_{g-1,2}(z_1,z_2) 
     		+ \frac{1}{2} \sum_{h=1}^{g-1} \left( \oint_{z_1 \in B} W_{h, 1}(z_1)  \right)
     		\, \left( \oint_{z_2 \in B} W_{g-h, 1}(z_2)  \right) \notag  \\
     		& = \frac{1}{2} \left[ \frac{\partial^2 F_{g-1}}{\partial \nu^2}
     		+ \sum_{h=1}^{g-1} \frac{\partial F_{h}}{\partial \nu} 
     		\, \frac{\partial F_{g-h}}{\partial \nu} \right],
     		\qquad g \ge 2. 
     		\label{eq:EO-HAE}
     	\end{align}  
     	Here we have used the variational formula $\ds\frac{\partial F_g}{\partial\nu}=\ds\oint_B W_{g,1}$, where the derivative with respect to $\nu$ is computed at fixed $t$, see 
     	\cite[Theorem 5.1]{EO07}. The result \eqref{eq:HAE} then immediately follows from the relation \eqref{XE2} rewritten as $2 \pi i \kappa = {\pi^2 E_2} / {3}$.
     \epf

     The HAE \eqref{eq:HAE} can be used for very effective recursive computation of $F_g$ starting from $F_1$ given by 
     \eqref{eq:expression-F0-F1}. Just as in the previous section, the free energies $F_g$ can be considered as functions of variables $\lb \nu,t\rb$ or,
     equivalently, of variables $\lb\omega_A,q\rb$. We will rewrite 
     the $\nu$-derivatives for fixed $t$ on the right of \eqref{eq:HAE} in terms of the derivative
     $D_\tau=q\frac{\partial}{\partial q}$, % defined in \eqref{eq:Dtau}
     \begin{equation}\label{eq:nuqchain}
     	\frac{\partial}{\partial \nu} f\lb q\rb =\xi\lb q\rb \cdot D_\tau f(q),
     	\qquad \xi(q)=\frac{\partial}{\partial \nu}\ln q .
     \end{equation}
     Let us show that $\xi\lb q\rb$ is given by \eqref{eq:Yukawa}. We will need the differentiation formulas for the Eisenstein series with respect to the nome $q$,
     \begin{equation}\label{eq:diffE}
     	D_\tau E_2 = \frac{1}{12}\left(E_2^2 -E_4\right),\qquad  
     	D_\tau E_4 = \frac{1}{3}\left(E_2 E_4 -E_6\right), \qquad 
     	D_\tau E_6 = \frac{1}{2}\left(E_2 E_6 -E_4^2\right),
     \end{equation}
     The relation between $\nu$ and $q$ can be deduced from two ways to compute the ratio $g_3^2/g_2^3$:
     \begin{equation}
     	\frac{u^2}{\lb -2t\rb^3}=\frac{g_3^2}{g_2^3}=\frac{E_6^2}{27E_4^3}.
     \end{equation}
     The derivative of the left hand side  with respect to $\nu$ includes 
     \begin{equation}
     	\frac{\partial u}{\partial \nu}=\frac{4\pi i}{\omega_A},
     \end{equation}
     coming from the differentiation of \eqref{eq:nu}. The derivative of the right hand side
     can be computed using the chain rule \eqref{eq:nuqchain} together with \eqref{eq:diffE}. 
     Equating the two results leads to the expression \eqref{eq:Yukawa} for the quantity $\xi\lb q\rb$, known as the Yukawa coupling in topological string theories. Note that   $\xi\lb q\rb$ actually depends not only on the nome $q$ but also on $\omega_A$.

     	Additionally, we will need the $\nu$-derivative of $\omega_A$ for fixed $t$. It follows from the $\nu$-derivative of 
     	$g_2=-2t$ given by \eqref{g2E4} that
     	\begin{equation}\label{eq:dernu-omega}
     		\frac{\partial}{\partial \nu} \ln \omega_A = \frac14 \frac{\partial}{\partial \nu} \ln E_4(q).
     	\end{equation}
     	Equations \eqref{eq:dernu-omega} and \eqref{eq:nuqchain} allow to rewrite 
     	the right hand side of \eqref{eq:HAE} in terms of derivatives in the nome $q$ only.

     	The relation \eqref{eq:HAE} thus determines the coefficients $C_{a,b,k}$ with $k>0$
     	in the expression \eqref{eq:Fg-quasi-modular-expression} for $F_g$.
     	The remaining coefficients $C_{a,b}:=C_{a,b,0}$
     	appear in the $E_2$-independent part of $F_g$, the so-called holomorphic ambiguities
     	\begin{equation} \label{eq:hol-ambiguity}
     		H_g=\left( \frac{\xi}{E_4}  \right)^{2g-2} h_g,
     		\qquad
     		h_g= \sum_{\substack{a,b \ge 0 \\ 4a+6b=14 \lb g-1\rb}} C_{a,b} \, E_4^a E_6^b \in \mathcal{M}_{14\lb g-1\rb},
     	\end{equation}
     	where $\mathcal{M}_k$ is the space of $\mathrm{SL}_2\lb \mathbb{Z}\rb$ modular forms of weight $k$. 
     	In the next subsection, we will discuss how to fix them using the gap condition.

       \subsection{Fixing holomorphic ambiguity}
       \label{subsec:Fixing-holomorphic-ambiguity}
   Here we show that the conifold gap properties 
       % \eqref{conigap}--\eqref{eq:kappa_g} 
       \eqref{eq:expansion-Fg}
       of free energies are sufficient to fix the holomorphic ambiguities \eqref{eq:hol-ambiguity},  
       and give a recursive algorithm for the computation of $F_g$. 
       %%%
       The crucial point here is that after the initial constant term in the asymptotic expansion of $F_g$, 
       the coefficients of all powers from 
       $\Lambda^{1}$ up to $\Lambda^{2g-3}$  
       % $s^{-1}$ up to $s^{-\lb2g-3\rb}$ 
       vanish (indicating the presence of a gap). 
       This gives a set of constraints on the coefficients $C_{a,b}$
       in \eqref{eq:hol-ambiguity}. 

      The gap condition in terms of $\Lambda$-expansion can be reformulated in terms of $q$-expansion 
      with the help of relation \eqref{nome_expansion_2} and its inverse.  
      Indeed, the gap property of $F_g$  described by Theorem~\ref{thm:coni-gap}, 
      is equivalent to vanishing of the coefficients of $q^k$ with $k=1,\ldots,2g-3$, in the $q$-expansion of $\nu^{2g-2} F_g$: 
%        \begin{theo}\label{thm:coni-gap-q}
%       	For each $g \ge 2$, the $g$-th free energy $F_g$ of the \PIeq spectral curve \eqref{eq:sp-PI} 
%       	has a convergent series expansion at $q = 0$ of the following form:
       	\begin{equation} \label{eq:q-expansion-Fg}
       		\nu^{2g-2} F_g  = \frac{B_{2g}}{4g(g-1)} + q^{2g-2} \sum_{k \ge 0} \widetilde F_g^{[k]} \, q^k . 
       	\end{equation}
       	Here the coefficients $\widetilde F_g^{[k]}\in\mathbb C$ are obtained by re-expanding 
	    \eqref{eq:expansion-Fg} as a $q$-series by using the inverse of the relation \eqref{nome_expansion_2}. 
	    % ({\color{red}{here should be the conifold gap formula in terms of $\Lambda$ or $s$}}) in $q$ using \eqref{nome_equation}.  
%        \end{theo}
      The fact that $\nu^{2g-2}F_g$ depends only on $q$   follows 
       from \eqref{eq:Fg-quasi-modular-expression} and the relation 
       \begin{equation}\label{eq:nuxi}
       	\frac{\nu \xi}{E_4}= \frac{E_2E_4-E_6}{720\eta^{24}}=1+42q+840 q^2+11340 q^3+\ldots,
       \end{equation}
       which, in turn, is a consequence of \eqref{numodular} and \eqref{eq:Yukawa}.





       We will use the conifold gap condition described by \eqref{eq:q-expansion-Fg}
       % Theorem~\ref{thm:coni-gap-q} 
       to fix the holomorphic ambiguity $h_g$ given by \eqref{eq:hol-ambiguity} which is 
       a modular form of weight $14(g-1)$. 
       By this  we refer to fixing $h_g$ through the requirement on $\nu^{2g-2}F_g$ to have the coefficients 
       of $q^j$, $j=0,1,\ldots,2g-3$ in accordance with the right hand side of \eqref{eq:q-expansion-Fg}. 
       To implement this, the key idea is to choose a convenient special basis in the corresponding space of modular forms $\mathcal{M}_k$:
       \begin{equation}\label{nice_basis}
       	V_j= E_4^{a_0-3j}E_6^{b_0} \Delta^j\lb q\rb, \qquad j=0,\ldots, \dim \mathcal{M}_k-1,  
       \end{equation}
       where $\Delta\lb q\rb=\eta^{24}\lb q\rb$ is a cusp form of weight 12, and
       \begin{equation}
       	b_0=\begin{cases}
       		1, \quad k=2 \mod 4,\\
       		0, \quad k=0 \mod 4,
       	\end{cases}
       	\qquad a_0=\frac{k-6b_0}{4},\qquad 
       	\dim \mathcal{M}_k =1+[a_0/3].
       \end{equation}
       The cusp form $\Delta\lb q\rb$ is related to, but should not be confused with, the discriminant $\Delta$ of the Weierstrass curve, cf. \eqref{eq:delta-eta}.
      The main reason for choosing the basis \eqref{nice_basis} is its expansion in powers of $q$: 
       \begin{equation}\label{eq:Vj-expansion}
       	V_j=q^j\lb 1+O\lb q\rb\rb.
       \end{equation}
       In this basis, the holomorphic ambiguity takes the form
       \begin{equation}
       	h_g=\sum_{j=0}^{d_g-1} \alpha_j V_j,
       	\qquad
       	d_g=\dim \mathcal{M}_{14\lb g-1\rb}.
       \end{equation}

       The procedure of using HAE \eqref{eq:HAE}  to find all $F_g$ is recursive starting from $F_2$ and using $F_1$. 
       At each recursion step, $F_g$ can be presented in the form  \eqref{eq:Fg-quasi-modular-expression} with 
       unknown $h_g=P_g\lb 0,E_4,E_6\rb$ which is the $E_2$-free part of the polynomial $P_g$. 
       The conifold gap condition gives a system of  $2g-2$ linear constraints on the coefficients 
       $\alpha_j$, ${j=0,\ldots,d_g-1}$. Since the dimension $d_g$ is given by
       \beq
       d_g=\begin{cases}
       	\left[\frac{7g-4}{6}\right],\qquad & g\in2\mathbb N,\vspace{0.1cm}\\
       	\left[\frac{7g-1}{6}\right],\qquad & g\in 2\mathbb N+1,
       \end{cases}
       \eeq
        for any $g\ge 2$ we have $d_g<2g-2$ and the system of constraints is overdetermined. 
       Indeed, already the first $d_g$ constraints corresponding to the first $d_g$ powers of $q$ uniquely fix all $\alpha_j$  due to the unitriangular form of the matrix of coefficients following from \eqref{eq:Vj-expansion}. All the other constraints must be satisfied automatically to ensure the existence of solutions of HAE supplemented with the conifold gap condition. The existence should follow from the properties of modular forms entering the procedure, though we do not have a  direct proof of this fact.
       However, we do know already that the TR free energies $F_g$ satisfy
       both  the conifold gap property (cf. Theorem \ref{thm:coni-gap}) 
       and the holomorphic anomaly equation (cf. Theorem \ref{thm:TR-HAE}), 
       therefore a solution of the overdetermined system of constraints necessarily exists! 

       Summarizing, we have the following
       \begin{theo} \label{thm:sol-HAE-weak}
       	For any $g \ge 2$, the holomorphic anomaly equations \eqref{eq:HAE} 
       	supplemented with the  \underline{weak} conifold gap constraint 
       	\begin{equation} \label{eq:q-expansion-Fg-weak}
       		\nu^{2g-2} F_g  = \kappa_g + O\lb q^{d_g}\rb,  
       	\end{equation}
       	where $d_g=\dim \mathcal{M}_{14\lb g-1\rb}$ and $\kappa_g$ is given by \eqref{eq:kappa_g}, 
       	define $F_g$ uniquely by recursion in $g$ starting from $F_1$ given by \eqref{eq:expression-F0-F1}. 
       \end{theo}

       \begin{cor} \label{cor:existence-strong-coniforld-gap-HAE}
       	For each $g \ge 2$, the free energies $F_g$ defined by Theorem~\ref{thm:sol-HAE-weak} 
       	satisfy the conifold gap property \eqref{eq:q-expansion-Fg} with more vanishing coefficients in the $q$-expansion of
       	$\nu^{2g-2} F_g$ than is required by \eqref{eq:q-expansion-Fg-weak}. 
       \end{cor}


       	In light of  many works on topological string theory such as \cite{HK06,HK09}, 
       	the above claim is believed to hold true generally. 
       	However, to our knowledge, its mathematically rigorous proof 
       	is not known (at least for the TR free energy of our spectral curve \eqref{eq:sp-PI}). 
       	Below we illustrate the method
       	by the computation of $F_2$ and $F_3$.
       	From these examples alone, it becomes apparent that 
       	the existence of solutions for the overdetermined system,
       	stated in Theorem \ref{thm:sol-HAE-weak}  and Corollary \ref{cor:existence-strong-coniforld-gap-HAE}, 
       	is highly nontrivial. Note that analogous computations 
       	have already appeared in e.g. 
       	 \cite[Section 4.1]{FGMS23} and \cite[Section 3]{PP23} (in the unrefined limit). Reproducing them here serves mainly pedagogical purposes.


       %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
       \begin{eg}[Computation of $F_2$]
       	We have already obtained an explicit formula for $F_2$ in \eqref{eq:Fg-quasi-modular-expression}, \eqref{eq:Yukawa}, \eqref{F23modularA} by an \textit{ab initio} TR calculation. Let us now rederive it using the aforementioned method. 
       	     The holomorphic anomaly equation \eqref{eq:HAE} for $F_2$ is 
       \begin{equation}\label{eq:HAEg2}
       	\frac{\partial F_2}{\partial E_2} 
       	= {- } \frac{1}{24} 
       	\left[ \frac{\partial^2 F_1}{\partial \nu^2} + \lb \frac{\partial F_1}{\partial \nu} \rb^2 \right]
       	=  \left( \frac{\xi}{E_4} \right)^{2} \frac{\partial P_2}{\partial E_2} .
       \end{equation}
       Our task is to find the polynomial $P_2=P_2\lb E_2,E_4,E_6\rb$. 
       The right hand side of HAE gives its $E_2$-derivative 
       \begin{equation}\label{eq:derP2}
       	\frac{\partial P_2}{\partial E_2} = - \frac{5E_2^2E_4^2 + 22 E_2 E_4 E_6 + 14 E_4^3 + 11 E_6^2}{13824}  .
       \end{equation}
       To derive this expression, we used that
       \begin{equation}
       	\frac{\partial  F_1 }{\partial \nu }= -\frac{\xi}{E_4} \cdot\frac{E_2E_4+E_6}{24},
       \end{equation}
       for $F_1$ given by  \eqref{eq:expression-F0-F1}, and the $\nu$-derivatives \eqref{eq:nuqchain}, \eqref{eq:dernu-omega}  allowing to compute 
       \begin{equation}
       	\frac{\partial}{\partial \nu } \lb\frac{\xi}{E_4}\rb=-\left(\frac{\xi}{E_4}\right)^2 \frac{7E_2E_4 +5E_6}{12}.
       \end{equation}
       Integrating \eqref{eq:derP2} with respect to $E_2$ leads to 
       \begin{equation}\label{eq:F2modular}
       	F_2 = \left(\frac{\xi}{E_4}\right)^2 
       	\left( - \frac{5E_2^3E_4^2 + 33 E_2^2 E_4 E_6 + E_2 \lb 42 E_4^3 + 33 E_6^2\rb}{41472} + \alpha_0 E_4^2 E_6 \right).
       \end{equation}
       This equation contains an unknown constant $\alpha_0$ multiplying $E_4^2E_6$, the only possible $\mathrm{SL}_2\lb \mathbb Z\rb$ modular form of weight~$14$. 
       To fix  $\alpha_0$, let us look at the series expansion of $\nu^2 F_2$ at $q = 0$ :
       \begin{equation}
       	\nu^2 F_2 = 
       	\alpha_0-\frac{113 }{41472 } 
       	+ \left(60 \alpha_0+\frac{299}{3456}  \right)  q +  O(q^2),
       \end{equation}
       which can be obtained from \eqref{eq:nuxi}. 
       The standard (strong) conifold gap property \eqref{eq:q-expansion-Fg} then imposes two constraints,
       \begin{align}\label{eqsalpha0}
       	\begin{cases} \displaystyle
       		\alpha_0-\frac{113 }{41472 }   & = 
       		\dfrac{B_{2g}}{4g\lb g-1\rb } \Bigl|_{g=2} = 
       		\displaystyle
       		-\frac{1}{240} , 
       		\\[+1.em]
       		\displaystyle
       		60 \alpha_0+\frac{299}{3456}  & =   0,
       	\end{cases}
       \end{align}
       whereas the weak conifold gap condition \eqref{eq:q-expansion-Fg-weak} would only imply the first of them.
       Both equations in \eqref{eqsalpha0} are of course equivalent, and their solution reads
       \begin{equation}%\label{eq:g2alpha0}
       	\alpha_0 = - \frac{299}{207360}. 
       \end{equation}
       This fixes the  holomorphic ambiguity in the expression \eqref{eq:F2modular} for $F_2$, 
       which agrees with \eqref{F23modularA}. 
       The $q$-expansion of $\nu^2F_2$ becomes 
       \begin{equation} \label{eq:F2qexp}
       	\nu^2F_2 =
       	-\frac{1}{240} +\frac{168 q^2}{5} +\frac{70353 q^3}{2} +\frac{25505004 q^4}{5}+ \frac{1790001618 q^5}{5}
       	+O\lb q^6\rb.
       \end{equation}

       \end{eg}


       %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
       \begin{eg}[Computation of $F_3$]

       Let us find the next contribution to free energy, $F_3$, following the same strategy. 
       The holomorphic anomaly equation
       \begin{equation}
       	\frac{\partial F_3}{\partial E_2} = - \frac{1}{24} \left[ \frac{\partial^2 F_2}{\partial \nu^2} 
       	+ 2 \frac{\partial F_2}{\partial \nu} \frac{\partial F_1}{\partial \nu} \right]
       \end{equation}
       fixes $p_3$ in the decomposition 
       \begin{equation}\label{eq:F3modular}
       	F_3=\left(\frac\xi{E_4}\right)^4 \lb p_3+h_3\rb,
       \end{equation}
       where $p_3$ combines all terms with $k\ge 1$ in the sum \eqref{eq:quasi-modular-part}, and $h_3$ is the holomorphic ambiguity: 
       \begin{equation}\label{eq:h3modular}
       	h_3=\alpha_0 V_0+\alpha_1 V_1+\alpha_2 V_2= \alpha_0 E_4^7 +\alpha_1 E_4^4\Delta\lb q\rb +\alpha_2 E_4\Delta^2\lb q\rb.
       \end{equation}
       The explicit formula for $p_3$ reads 
       \begin{align}
       	716636160 p_3= &\, 
       	75E_2^6 E_4^4 
       	+ 1200 E_2^5 E_4^3 E_6 
       	+ 45E_2^4 E_4^2 \lb 56E_4^3+159E_6^2\rb 
       	+ 10E_2^3 E_4 E_6  \lb 3121 E_4^3 + 1815 E_6^2\rb \\
       \nonumber	&\,+ 3 E_2^2 \lb 8023 E_4^6 + 39964 E_4^3 E_6^2 + 4400 E_6^4\rb
       	+ 6 E_2 E_4^2 E_6 \lb 24273 E_4^3 + 22463 E_6^2\rb. 
       \end{align}
       Using it together with \eqref{eq:nuxi}, we can compute the small $q$ expansion of $\nu^4 F_3 $. 
       Imposing the weak gap condition on the coefficients of $1$, $q$, and $q^2$, we obtain  a system of linear equations for $\alpha_{0,1,2}$ with a unitriangular matrix of coefficients
       \begin{align*}
       	\begin{cases} \displaystyle
       		\alpha_0  +\frac{497887}{716636160}   & = 
       		\dfrac{B_{2g}}{4g\lb g-1\rb } \Bigl|_{g=3} = 
       		\displaystyle
       		\frac{1}{1008},  
       		\\[+1.em]
       		\displaystyle
       		1848 \alpha_0+\alpha_1-\frac{72929}{5971968} & =   0,
       		\\[+1.em]
       		\displaystyle
       		1520904 \alpha_0+1104 \alpha_1+\alpha_2-\frac{48826219}{29859840} & =   0.
       	\end{cases}
       \end{align*}
       Its solution reads
       \begin{equation}%\label{eq:g2alpha0}
       	\alpha_0=\frac{1491431}{5016453120},\qquad \alpha_1= -\frac{222793}{414720},
       	\qquad \alpha_3=\frac{3421}{24},
       \end{equation}
       fixing thereby the holomorphic ambiguity \eqref{eq:h3modular} in the decomposition \eqref{eq:F3modular}.
       Finally, the small $q$ expansion for $\nu^4F_3$ becomes
       \begin{equation} \label{eq:F3qexp}
       	\nu^4F_3=\frac{1}{1008} +564480 q^4 +1614901401 q^5 +614954090130 q^6 + \frac{778563472560150 q^7}{7}+O\lb q^8\rb.
       \end{equation}
       It contains an extra vanishing coefficient of $q^3$, in agreement with the strong conifold gap property for $F_3$. 
       \end{eg}


       While we proved the existence of solutions by demonstrating 
       that the TR free energy  satisfies the conifold gap property (Theorem \ref{thm:coni-gap}), 
       we believe it would be also interesting to have a more direct proof 
       based on the properties of quasi-modular forms.



