       \subsection{Refined holomorphic anomaly\label{subsec_betaHAE}}

       Remarkably, the HAE construction described above admits a one-parameter deformation \cite{KW10,HK10} (see also recent works \cite{FMP23,FGMS23} and references therein)  where $\hbar$ is replaced by by two complex parameters $\epsilon_1$ and $\epsilon_2$. For generic values of $\epsilon_1,\epsilon_2$, it is convenient to introduce the notation 
       \begin{equation}
       	\beta=\sqrt{-\frac{\epsilon_1}{\epsilon_2}}, \qquad  \hbar^2=\epsilon_1 \epsilon_2.
       \end{equation}
       In the description of this deformation, the  free energy $F_0$ remains undeformed and is defined by \eqref{eq:expression-F0-F1} which explicitly evaluates to \eqref{F0modular}.
       The free energy $F_1$ is given by  a $\beta$-deformation 
       \begin{equation}\label{eq:expression-F1b}
       	F_1^{(\beta)}=-\frac12 \ln \omega_A -\frac{\beta^2+\beta^{-2}}{24} \ln \frac{\Delta\lb q\rb}{\omega_A^{12}}. 
       \end{equation}
       This expression is used as an initial condition for the same HAE recursion \eqref{eq:HAE}, and defines  $F_g^{(\beta)}$ with $g\ge 2$. 
       Using 
       that $\Delta=\lb 2\pi/\omega_A\rb^{12} \Delta\lb q\rb$, it is easy to check that the free energy $F_1^{(\beta=1)}$ reduces to $F_1$ given by \eqref{eq:expression-F0-F1}  (up to an additive constant).
       The corresponding generalization of Theorem~\ref{thm:sol-HAE-weak} is given by 
       \begin{theo}\label{thm:sol-HAE-weak-b}
       	For any $g \ge 2$, the holomorphic anomaly equations \eqref{eq:HAE} 
       	supplemented with the  $\beta$-deformed \underline{weak} conifold gap condition 
       	\begin{equation} \label{eq:q-expansion-Fg-weak-b}
       		\nu^{2g-2} F_g^{(\beta)}  = \kappa_g^{(\beta)} + O\lb q^{d_g}\rb,  
       	\end{equation}
       	where $d_g=\dim \mathcal{M}_{14\lb g-1\rb}$ and 
       	\begin{equation}\label{eq:kappa-g-b}
       		\kappa_g^{(\beta)}= - \lb 2g-3\rb! \sum_{h=0}^g \hat B_{2h} \hat B_{2g-2h} \beta^{2g-4h},
       		\qquad \hat B_m=\lb1- 2^{1-m}\rb\frac{B_m}{m!},
       	\end{equation} 
       	define $F_g^{(\beta)}$ uniquely by recursion in $g$ starting from $F_1^{(\beta)}$ given by \eqref{eq:expression-F1b}.
       \end{theo}

       \begin{eg} For $g=2$, the HAE recursion yields the following expression:
       \begin{align}
       	F_2^{(\beta)}=&\,-\left(\frac{\xi}{E_4}\right)^2  \left[   \frac{5 E_2^3 E_4^2}{41472} 
       	+\frac{\left(2 \beta^2+7 +2\beta^{-2}\right) E_2^2 E_4E_6}{13824 } 
       	+   \frac{ \left(6 \beta^2-5+6 \beta^{-2}\right) E_2 E_4^3}{6912}\right.\\
