       	O\lb q^3\rb ,
       \end{equation}
       which exhibits the anticipated gap (vanishing coefficient of $q$).
       \end{eg}

       Motivated by the TR/\PIeq correspondence \eqref{TRPIshort}, let us introduce the $\beta$-deformed \PIeq partition function by
       \beq\label{betadefZ}
       \tilde{\mathcal Z}^{(\beta)}\lb \hbar^{-1}s\,|\,\hbar^{-1}\nu\rb= \exp\sum_{g \ge 0} \hbar^{2g-2} F_g^{(\beta)}\lb t,\nu\rb.
       \eeq
       Taking into account Conjecture~\ref{CFTPI} relating the \PIeq partition function to $c=1$ Virasoro conformal blocks, it is natural to guess that its $\beta$-deformed version $\tilde{\mathcal Z}^{(\beta)}\lb s\,|\,\nu\rb$ is similarly related to the irregular block  \eqref{CBalgexp}--\eqref{L2comms} for generic central charge. The precise statement is as follows\footnote{We recall once again that $F_1$ in \eqref{eq:expression-F1b} is defined up to an additive constant independent of $\nu$ and $s$; it may, however, depend on $\beta$. }.
       \begin{conj}\label{CFTHAEcorr}
       	The large $s$ asymptotic expansion of the $\beta$-deformed partition function $\tilde{\mathcal Z}^{(\beta)}\lb s\,|\,\nu\rb$ defined by \eqref{betadefZ} is given by
       	\begin{gather}
       	\tilde{\mathcal Z}^{(\beta)}\lb s\,|\,\nu\rb=C^{\lb\beta\rb}\lb\nu\rb e^{\frac{s^2}{45}+\frac{4}{5}i\nu s}\mathcal F\lb\varepsilon\,|\,\nu\rb,     		
       	\end{gather}
       	where $\mathcal F\lb\varepsilon\,|\,\nu\rb$ is the irregular conformal block defined by \eqref{CBalgexp}--\eqref{L2comms}, with
       	\beq\label{beta_identification}
       	c=1-6\lb\beta-\beta^{-1}\rb^2,\qquad \varepsilon^{-2}=48is.
       	\eeq
       	The $s$-independent prefactor $C^{\lb\beta\rb}\lb\nu\rb$ is given by
       	\beq
       	C^{\lb\beta\rb}\lb\nu\rb=\Gamma_{\beta}^{-1}\left(\frac{\tilde Q}{2}  +\nu\right),\qquad \tilde Q= \beta+\beta^{-1},
       	\eeq
       	 where $\Gamma_\beta(z)$ is expressed in terms of the Barnes gamma and zeta functions (see e.g. \cite{Spr09} for the corresponding definitions)
       	\begin{equation}\label{eq:BarnesGamma}
       		\ln \Gamma_\beta\lb z\rb =
       		\ln \frac{\Gamma_2\lb z;\beta,\beta^{-1}\rb}{\Gamma_2\lb \tilde Q/2;\beta,\beta^{-1}\rb}=
       		\left. \frac{\partial}{\partial s} \left(\zeta_2\lb s;\beta,\beta^{-1},z\rb - \zeta_2\lb s;\beta,\beta^{-1},\tilde Q/2\rb \right)\right|_{s=0}.
       	\end{equation}
       \end{conj}

             We have checked that previously computed coefficients $\mathcal U_{\ln}$, $\mathcal U_1,\ldots,\mathcal U_5$ of the expansion \eqref{Ugenericc} indeed coincide with the expressions predicted by Conjecture~\ref{CFTHAEcorr} under identification \eqref{beta_identification}. This comparison involves the calculation of $\beta$-deformed free energies up to $F_3^{(\beta)}$.

        The role of the $\Gamma_\beta$-function in the above is
       to reproduce the leading terms $\kappa_g^{(\beta)}$ of expansions \eqref{eq:q-expansion-Fg-weak-b} of $F_g^{(\beta)}$. As $z\to\infty$ with $|\arg z|<\frac{\pi}{2}$, we have
       \begin{equation}\label{betaBarnesAs}
       	\ln \Gamma^{-1}_{\beta}\left(\frac{\tilde Q }{2} +z\right) \simeq
       	\frac{z^2}{2}\ln z- \frac{3z^2}{4}-\frac{\beta^2+\beta^{-2}}{24} \ln z +
       	c_0\lb \beta\rb+\sum_{g\ge 2}   \frac{\kappa_g^{(\beta)}}{z^{2g-2}}.
       \end{equation}
       This follows from the integral representation 
       \beq
       \ln \Gamma^{-1}_{\beta}\left(\frac{\tilde Q }{2} +z\right)=\int_0^\infty\frac{dx}{x}
       \left[\frac{1-e^{-zx}}{4\sinh \frac{\beta x}{2}\sinh\frac{x}{2\beta}}+\frac{z^2}{2}e^{-x}-\frac{z}{x}\right],\qquad \Re z>0.
       \eeq
       Indeed, decompose the integral on the right into a sum of three contributions:
       \beq\begin{gathered}
       	\int_0^\infty\left[\lb\frac{z^2}{2}e^{-x}-\frac{z}{x}\rb-\lb \frac{1}{x^2}-\frac{\beta^2+\beta^{-2}}{24}\rb e^{-zx}+\lb \frac{1}{x^2}-\frac{\beta^2+\beta^{-2}}{24}e^{-x}\rb\right]\frac{dx}{x}\\
       	-
       	\int_0^\infty \left(\frac{1}{x^2}-\frac{\beta^2+\beta^{-2}}{24}e^{-x}-\frac{1}{4\sinh \frac{\beta x}{2}\sinh\frac{x}{2\beta}}\right)\frac{dx}{x}+
       	\int_0^\infty \left(\frac{1}{x^2}-\frac{\beta^2+\beta^{-2}}{24}-\frac{1}{4\sinh \frac{\beta x}{2}\sinh\frac{x}{2\beta}}\right)\frac{e^{-z x}}{x}\,dx.
       	\end{gathered}
       \eeq
       The first of these integrals is elementary and evaluates to $\frac{z^2}{2}\ln z- \frac{3z^2}{4}-\frac{\beta^2+\beta^{-2}}{24} \ln z$, which is exactly the divergent part of the asymptotics in \eqref{betaBarnesAs}. The second integral gives its finite part $c_0\lb\beta\rb$. Finally, in the third integral one may use the well-known expansion
       \beq
       \frac{1}{2\sinh x}=\sum_{g=0}^\infty\hat{B}_{2g}x^{2g-1}
       \eeq
       to obtain the last sum in \eqref{betaBarnesAs}. It seems plausible that the asymptotic expansion \eqref{betaBarnesAs} holds in a wider sector $|\arg z|<\pi$, similarly to \cite[Proposition 8.11]{Spr09}. In the non-deformed case, the $\Gamma_\beta$-function reduces to the usual Barnes G-function, $\left.\Gamma^{-1}_{\beta}\left(\tilde Q /2 +\nu\right) \right|_{\beta=1} = \lb 2\pi\rb^{-\nu/2} G\lb 1+\nu\rb$.




