     \subsection{Proof of Theorem~\ref{conjWh52}\label{AppProof}} 

In this Appendix, we prove Theorem~\ref{conjWh52} about embedding of  the rank $\frac52$ Whittaker vector $|\Psi\rangle$ 
into the rank 2 Whittaker module ${\mathcal V}^{[2]}$.
The proof uses several definitions and ideas from \cite{Nagoya15}. 

Slightly generalizing the initial setting, let $\left|\Psi\right\rangle$  denote a vector satisfying
\begin{equation}
    \lb L_n-\mathcal{L}_n^{(5/2)}\rb\left|\Psi\right\rangle=0, \qquad n\ge3, 
\end{equation}
where
\begin{equation}
    \mathcal{L}_n^{(5/2)}=\begin{cases}
        \Lambda_n, \qquad & n=3,4,5,\\
        0, \qquad & n>5,
    \end{cases}
\end{equation}
and it is assumed that $\Lambda_4\ne  0$. Likewise,  the rank 2 Whittaker module ${\mathcal V}^{[2]}$  will be generated from a vector $|J\rangle$ 
that satisfies
\begin{equation}
    \lb L_n-\mathcal{L}_n^{(2)}\rb|J\rangle=0, \qquad n\ge2, 
\end{equation}
\begin{equation}\label{Lambda234}
    \mathcal{L}_n^{(2)}=\begin{cases}
        \Lambda_n, \qquad &n=2,3,4,\\
        0, \qquad &n>4.
    \end{cases}
\end{equation}

We are going to prove that the Whittaker vector $|\Psi\rangle$ can be embedded into the module ${\mathcal V}^{[2]}$ in the form of a formal power series in $\Lambda_5$:
\begin{equation}\label{PsiV2ser}
    |\Psi\rangle=\sum_{k=0}^{\infty}\Lambda_5^k \left|\Psi_k\right\rangle, \qquad \left|\Psi_0\right\rangle=|J\rangle.
\end{equation}
To find $|\Psi_k\rangle\in {\mathcal V}^{[2]}$, we will use a PBW basis labeled by Young diagrams  \cite{Nagoya15}
\begin{equation}\label{PBW_app}
    v_\lambda=\mathbf{L}_{-\lambda} |J\rangle, \qquad \mathbf{L}_{-\lambda}=L_{-\lambda_1+2}\cdots L_{-\lambda_\ell+2}, \qquad \lambda=\lb \lambda_1,\ldots,\lambda_\ell\rb\in\mathbb Y, 
    \qquad \lambda_1\ge \ldots \ge \lambda_n \ge 1,
\end{equation}
\begin{equation}
    v_\emptyset=|J\rangle, \quad \mathbf{L}_{-\emptyset} = 1.
\end{equation}
The difference between $\mathbf{L}_{-\lambda}$ and the notation $\mathbb{L}_{-\lambda}$ previously used in \eqref{notation_young} is the shift of indices of all Virasoro generators by $2$.

Let us define a degree for the basis elements by
\begin{equation}\label{degL}
    \deg\,v_\lambda=\deg\,\mathbf L_{-\lambda} \left|J\right\rangle=|\lambda|.
\end{equation}
The degree of  an arbitrary vector $v \in {\mathcal V}^{[2]}$ is defined as the maximal degree of its non-zero components, 
\begin{equation}
    \mathrm{deg}\,v=\max\,\lb\mathrm{deg}\,  v_\lambda\rb, \qquad v=\sum_\lambda c_\lambda v_\lambda, \qquad c_\lambda \ne 0.
\end{equation}
With respect to this degree, we are going to consider an infinite flag  $U_0\subset U_1\subset U_2\subset \ldots$ of subspaces $U_m \subset {\mathcal V}^{[2]}$ given by
\begin{equation}\label{DefUm}
    U_m=\mathrm{span}\,\left(v_\lambda\, | \,\mathrm{deg}\,v_\lambda \leq m\right).
\end{equation}
It will also be convenient to introduce a linear functional $\xi$ on  ${\mathcal V}^{[2]}$  defined as the coefficient of $|J\rangle$ in the decomposition in the PBW basis \eqref{PBW_app},
\begin{equation}
    \xi(v)=c_{\emptyset}, \qquad v=\sum_\lambda c_\lambda v_\lambda.
\end{equation}

We will use the following modification  of Virasoro generators:
\begin{equation}
    \widetilde{L}_n=\begin{cases}
        L_n-\Lambda_n, \qquad & n=3,4,\\
        L_n, \qquad & n>4.
    \end{cases}
\end{equation}
The products of such shifted generators will be similarly labeled by a Young diagram $\mu\in \mathbb Y$, 
\begin{equation}
    \widetilde{\mathbf L}_\mu = \widetilde{L}_{\mu_1+2}\cdots \widetilde{L}_{\mu_n+2}, \qquad \mu=\lb \mu_1,\ldots, \mu_n\rb, \qquad 
    \mu_1\ge \mu_2 \ge \cdots \ge \mu_n\ge 1.
\end{equation}
Note that the products $\mathbf L_{-\lambda}$ and $\widetilde{\mathbf L}_\mu$ involve the generators $L_n$ with $n\leq 1$ and $n\geq 3$, respectively.
We further define a bilinear form $M$ on ${\mathcal V}^{[2]}$ by
\begin{equation}
    M\lb v_\mu, v_\lambda\rb=\xi\left(\widetilde{\mathbf L}_\mu \mathbf L_{-\lambda}\left|J\right\rangle\right).
\end{equation}

The main result we need  from \cite{Nagoya15} is Lemma~2.22 therein, which states that 
\begin{equation}\label{Mform}
    M\lb v_\mu, v_\lambda\rb=\begin{cases}
        0, \qquad &|\mu|>|\lambda|, \\
        0, \qquad &|\mu|=|\lambda|,\ \mu\neq \lambda, \\
        \neq 0, \qquad &\mu=\lambda.
    \end{cases}
\end{equation}
Let us introduce the matrix $M_k$ of pairings defined by the form $M$ restricted to the space $U_k$, 
\begin{equation}
    M_k = \left(M\lb v_\mu,v_\lambda\rb\right)_{0\leq |\mu|,|\lambda|\leq k}.
\end{equation}
Ordering the basis vectors in descending order with respect to the size of Young diagrams, 
it follows from \eqref{Mform} that $M_k$ becomes a triangular matrix with non-zero determinant. 
Note that the ordering of basis vectors corresponding to Young diagrams of the same size  does not affect the triangularity of $M_k$ thanks to 
\eqref{Mform}.

The problem of finding the rank $\frac52$ Whittaker vector $|\Psi\rangle$ in the form \eqref{PsiV2ser} 
can be rewritten as a problem of solving the following recurrence relations for descendants $\left|\Psi_k\right\rangle$ in terms of the action of shifted Virasoro generators $\widetilde{L}_n$:
\begin{equation}\label{recdesc}
    \widetilde{L}_n \left|\Psi_k\right\rangle = \begin{cases}
        \left|\Psi_{k-1}\right\rangle, \qquad &n=5,\\
        0, \qquad &n\ge 3, n\neq 5.
    \end{cases}
\end{equation}
In order to ensure uniqueness of solution,  we impose the
{\em orthogonal gauge} defined by the following conditions on the components of $|\Psi\rangle$:
\begin{equation}\label{orthgauge}
    \xi\left(\left|\Psi_k\right\rangle\right)=\delta_{k,0}.
\end{equation} 
From \eqref{recdesc} it follows that
\begin{equation}
    \xi\left(\cdots\widetilde{L}_5^{m_5}\widetilde{L}_4^{m_4}\widetilde{L}_3^{m_3} |\Psi_k\rangle\right)=\begin{cases}
        1, \qquad m_5=k, m_3=m_4=m_6=\cdots = 0,\\
        0, \qquad  \text{otherwise}, 
    \end{cases}
\end{equation}
or, equivalently,
\begin{equation}\label{xiLtPsi}
    \xi\lb \widetilde{\mathbf L}_\mu \left|\Psi_k\right\rangle\rb=\begin{cases}
        1, \qquad \mu=\lb 3^k\rb,\\
        0, \qquad \text{otherwise}.
    \end{cases}
\end{equation}

\begin{theo} \label{Wh52deg} 
The following holds:
\begin{enumerate}
\item The rank $\frac52$ Whittaker vector $\left|\Psi\right\rangle$ in the form \eqref{PsiV2ser} exists.
\item For any $k\in\mathbb N$, its component $\left|\Psi_k\right\rangle$ belongs to $U_{3k}$. 
\item The vector $|\Psi\rangle$ is unique in the orthogonal gauge \eqref{orthgauge}.
\end{enumerate}
\end{theo}
\pf 
We will prove the above statements by induction in $k$ for components $ \left|\Psi_k\right\rangle$ in \eqref{PsiV2ser}. 
Assume that $\left|\Psi_{k-1}\right\rangle\in U_{3(k-1)}$ satisfies the recursion \eqref{recdesc}. 
We are looking for $\left|\Psi_k\right\rangle$ in the form
\begin{equation}\label{psikgen}
    \left|\Psi_k\right\rangle=\sum_{1\leq |\lambda|\leq N}c_\lambda^{(k)}\mathbf L_{-\lambda}\left|J\right\rangle,
\end{equation}
where $N$ is an integer satisfying $N\ge 3k$. Let us show that such a vector exists and is unique. 
Moreover, it will be shown that $c_\lambda^{(k)}=0$ for $|\lambda| > 3k$ and therefore we may set $N=3k$. 

\noindent
{\it \underline{Step 1} (uniqueness).}  We will prove uniqueness
by showing that the coefficients $c_\lambda^{(k)}$ satisfy a system of linear equations having a unique solution. 
This system comes from computing $\xi\lb \widetilde{\mathbf L}_\mu \left|\Psi_k\right\rangle\rb$ for $1\le |\mu|\leq N$ in two different ways: by 
direct computation using \eqref{psikgen} and by recursion relations \eqref{recdesc} for the components $\left|\Psi_j\right\rangle$ of $|\Psi\rangle$ leading to 
\eqref{xiLtPsi}:
\begin{equation}\label{syst1step}
    \sum_{1\leq |\lambda|\leq N}M\lb v_\mu,v_\lambda\rb c_\lambda^{(k)}=\xi\lb \widetilde{\mathbf L}_\mu \left|\Psi_k\right\rangle\rb=\delta_{\mu,\lb 3^k\rb}.
\end{equation}
Due to \eqref{Mform},  the matrix of the system is non-degenerate, which implies uniqueness of solution for $c_\lambda^{(k)}$.
As a corollary,  with such $c_\lambda^{(k)}$, the vector $|\Psi_k\rangle$ ($k\in\mathbb N$) given by \eqref{psikgen} satisfies
\begin{equation}\label{relstep2}
    \xi\lb \widetilde{\mathbf L}_\mu \left|\Psi_k\right\rangle\rb=\delta_{\mu,\lb 3^k\rb}
\end{equation}
for any $\mu\in\mathbb Y$. Indeed, for $\mu=\emptyset$ this follows from  \eqref{orthgauge}, the case $0<|\mu|\leq N$ follows from 
\eqref{syst1step}, and the case $|\mu|>N$  follows from the first relation in \eqref{Mform}.\vspace{0.1cm}

\noindent
{\it \underline{Step 2} (restriction of support of $|\Psi_k\rangle$).} Let us show that 
the solution of \eqref{syst1step} satisfies $c_\lambda^{(k)}=0$ for $|\lambda| > 3k$.
The starting point here is that
the only non-zero coefficient in the right hand side of \eqref{syst1step}  corresponds to $\mu=\lb 3^k\rb$.
Therefore, if we order the basis vectors of $U_N$ in \textit{any} descending order, denoted by $\succ$ (not necessarily coming from the degree introduced above), such that the matrix of coefficients 
of \eqref{syst1step}  is lower triangular, then $c_\lambda^{(k)}=0$ for all $\lambda \succ \lb 3^k\rb$.

In particular, due to \eqref{Mform}, for any order of basis elements $v_\lambda$  consistent with the non-ascending degree \eqref{degL}, 
the corresponding matrix of coefficients becomes  lower triangular  and hence $c_\lambda^{(k)}=0$ for $\left|\lambda\right| > |\lb 3^k\rb|= 3k$.
Therefore, if $\left|\Psi_k\right\rangle$ exists, then it should verify $\left|\Psi_k\right\rangle\in U_{3k}$ and  we may impose the restriction $N=3k$. 

In what follows, a similar idea will be used to even further restrict the subspace of $\mathcal V^{[2]}$ to which $\left|\Psi_k\right\rangle$ belongs using other orderings of basis elements.\vspace{0.1cm}



\noindent
{\it \underline{Step 3} (existence).} 
The requirement  for $\left|\Psi_k\right\rangle$ in the form \eqref{psikgen} to satisfy  \eqref{recdesc}
leads to an overdetermined linear system for the coefficients $c_\lambda^{(k)}$ in \eqref{psikgen}.
Its subsystem \eqref{syst1step} has a unique solution and one needs to check that it solves the whole overdetermined system too.
Let us show that \eqref{psikgen}, with $c_\lambda^{(k)}$ defined by the solution of \eqref{syst1step}, indeed  satisfies \eqref{recdesc}.
Equivalently, we need to check that for $n\ge 3$ the vectors 
\begin{equation}\label{syst2step}
    w_n=\widetilde{L}_{n} |\Psi_k\rangle-\delta_{n,5}|\Psi_{k-1}\rangle \in U_{3k-n+2}
\end{equation}
are equal to zero. (The restriction on the degree comes from Lemma~2.19 of \cite{Nagoya15}.)
In turn, thanks to non-degeneracy of the bilinear form $M_m$ on $U_m$, it is sufficient to show that
\begin{equation}
    M\lb v_\mu,w_n\rb=0
\end{equation}
for all $n\ge 3$ and all $|\mu|\leq 3k-n+2$.

For $n\neq 5$, we need to show that
\begin{equation}
    \xi\left(\widetilde{\mathbf L}_\mu \widetilde{L}_{n} \left|\Psi_k\right\rangle\right)=0,
\end{equation}
which follows from \eqref{relstep2} by PBW ordering of $\widetilde{\mathbf L}_\mu \widetilde{L}_{n}$.
Similar arguments work for $n=5$ with $\mu\ne\lb 3^{k-1}\rb$.
In the case $\mu=\lb 3^{k-1}\rb$, we have
\begin{equation}
    \xi\left(\widetilde{L}_5^{k-1}\left( \widetilde{L}_{5} \left|\Psi_k\right\rangle-\left|\Psi_{k-1}\right\rangle\right)\right)=\xi\left(\widetilde{L}_5^{k} \left|\Psi_k\right\rangle\right)-\xi\left(\widetilde{L}_5^{k-1} \left|\Psi_{k-1}\right\rangle\right)=0.
\end{equation}
The 1st term is equal to $1$ by \eqref{relstep2} and the 2nd term is equal to $1$ by induction.  This completes the proof. \epf


\begin{rmk}    
The explicit form of $\left|\Psi_1\right\rangle$ reads
\begin{equation}\label{Psi1deg}
    \left|\Psi_1\right\rangle=\left(\frac{1}{6\Lambda_4}L_{-1}-\frac{5\Lambda_3}{24\Lambda_4^2}L_0+\frac{15\Lambda_3^2-16\Lambda_2\Lambda_4}{48\Lambda_4^3}L_1+0\cdot L_1^2+0\cdot L_0 L_1+0\cdot L_1^3\right)
    \left|J\right\rangle.
\end{equation}
Observe that some coefficients of the decomposition of $\left|\Psi_1\right\rangle\in U_3$ are equal to zero. The number of vanishing coefficients becomes even larger for higher orders. 
This means that the restriction $\left|\Psi_k\right\rangle\in U_{3k}$ is not optimal and
$\left|\Psi_k \right\rangle \in V_k \varsubsetneq U_{3k}$.
\end{rmk}
We are now going to improve the statement of Theorem~\ref{Wh52deg} by explaining why a part of the coefficients in the decompositions such as \eqref{Psi1deg} are equal to zero. 
To do this, let us introduce two more degrees for basis elements $v_\lambda$, denoted  by $\deg_{\,\delta}$ with $\delta=1,2$ and defined by
\begin{equation}
    {\mathrm{deg}_{\,\delta}}v_\lambda=n_1+\delta n_2+\sum_{k>2}n_k\lb k-2\rb, \qquad \lambda=\lb\cdots\, 3^{n_3}2^{n_2}1^{n_1}\rb,
\end{equation}
or, in other words,
\begin{equation}
    {\mathrm{deg}_{\,\delta}} L_{-k}=k, \quad k>0,\qquad\quad {\mathrm{deg}_{\,\delta}} L_{0}=\delta, \qquad {\mathrm{deg}_{\,\delta}} L_{1}=1.
\end{equation}
These degrees can be used to show partial triangularity of the bilinear form $M$ in other bases. 
\begin{lemma}\label{deg12-lemma}
For all $\lambda,\mu\in\mathbb Y$ and arbitrary $\Lambda_4\ne 0$, $\Lambda_3$, and $\Lambda_2$ in the definition of rank 2 Whittaker module ${\mathcal V}^{[2]}$ (see \eqref{Lambda234}), we have 
\begin{equation}\label{Mform1}
    M\lb v_\mu, v_\lambda\rb=0 \qquad \mathrm{if} \qquad {\mathrm{deg}_1}v_\mu>{\mathrm{deg}_1}v_\lambda.
\end{equation}
If $\Lambda_3=0$,  we have 
\begin{equation}\label{Mform2}
    M\lb v_\mu, v_\lambda\rb=0 \qquad \mathrm{if} \qquad {\mathrm{deg}_2}v_\mu>{\mathrm{deg}_2}v_\lambda.
\end{equation}
\end{lemma}
\begin{rmk}   
Note that the relations \eqref{Mform1} and \eqref{Mform2} do not follow from \eqref{Mform} because there are cases when $|\mu|<|\lambda|$ for which
${\mathrm{deg}_{\,\delta}}v_\mu>{\mathrm{deg}_{\,\delta}}v_\lambda$. For example, $\mu=\lb 1^2\rb$ and $\lambda=\lb 3\rb$.
\end{rmk}

\begin{rmk}   
The degrees ${\mathrm{deg}_{\,\delta}}$ alone do not imply a triangularity of the matrix associated to the form~$M$, since $M\lb v_\mu,v_\lambda\rb$ does not necessarily vanish if $\mathrm{deg}_\delta v_\mu = \mathrm{deg}_\delta v_\lambda$ with $\lambda\ne \mu$, cf. \eqref{Mform}. In other words, we can only ensure that the relevant matrix is \textit{block} lower-triangular, different blocks being labeled by ${\mathrm{deg}_{\,\delta}}$. The triangularity can however be restored  if we use in addition the previous degree \eqref{degL} inside each block.
\end{rmk}
\begin{rmk} Equations \eqref{Wh2} in the main text satisfy the restriction $\Lambda_3=0$. Accordingly, the degree $\deg_2$ appears explicitly in the selection rules \eqref{selectionrulesWH}.
\end{rmk}


For $\delta=1,2$, the space $U_{3k}$ defined by \eqref{DefUm} can be decomposed into a direct sum of two subspaces $U_{3k}=W_k^{(\delta)} \bigoplus V_k^{(\delta)}$, where
\begin{equation}
    W_k^{(\delta)}=\mathrm{span}\left(v_\lambda\in U_{3k}|\, {\mathrm{deg}_{\,\delta}}v_\lambda> k\right) , \qquad 
    V_k^{(\delta)}=\mathrm{span}\left(v_\lambda\in U_{3k}|\, {\mathrm{deg}_{\,\delta}}v_\lambda\leq k\right).
\end{equation}
Note that for $k>0$ we have a strict inclusion $V_k^{(2)}\varsubsetneq   V_k^{(1)}$.


The matrix $M_{3k}$ of bilinear form $M$ restricted to $U_{3k}=W_k^{(\delta)}\bigoplus V_k^{(\delta)}$ has the form of a $2\times 2$ block matrix
\begin{equation}\label{MMatrix_delta}
    M_{3k}^{(\delta)}=\begin{pmatrix}
        M_{WW} & M_{WV} \\
        M_{VW} & M_{VV}
    \end{pmatrix},
\end{equation}
where the indices $W$ and $V$ correspond to restrictions to $W_k^{(\delta)}$ and $V_k^{(\delta)}$, and additionally inside each block we use a descending order of basis elements with respect to $\operatorname{deg} v_\lambda =|\lambda|$. Then,  it follows from \eqref{Mform} that $M_{WW}$ and $M_{VV}$ are lower-triangular and non-degenerate matrices, while Lemma~\ref{deg12-lemma} ensures that $M_{WV}=0$. 
The matrix $M_{3k}^{(\delta)}$ is therefore lower-triangular. Using this fact, we can now formulate an enhanced version of Theorem~\ref{Wh52deg}.

\begin{theo} \label{Wh52deg12} 
The rank $\frac52$ Whittaker vector $\left|\Psi\right\rangle$ exists and is unique in the orthogonal gauge. For any $k\in\mathbb N$, its component $\left|\Psi_k\right\rangle$ belongs to the subspace $V_k^{(1)}$.
If in addition $\Lambda_3=0$, then $|\Psi_k\rangle\in V_k^{(2)}\subset  V_k^{(1)}$.
\end{theo}
\pf
Theorem~\ref{Wh52deg} already proves the existence and uniqueness of $|\Psi\rangle$ with components $|\Psi_k\rangle\in U_{3k}$. 
The only thing that needs to be adjusted is Step~2 in its proof. Namely, we will now use the lower triangular matrix $M_{3k}^{(\delta)}$ 
given by \eqref{MMatrix_delta} associated to the bilinear form $M$.
To complete the proof, it suffices to note that $v_{\lb 3^k\rb}=L_{-1}^k|J\rangle\in V_k^{(\delta)}$.
\epf 

Finally, let us note that Lemma~\ref{deg12-lemma} follows immediately from the part $(b)$ of the following lemma.
\begin{lemma} Let $\lambda,\mu\in\mathbb Y$ be arbitrary Young diagrams.
For the degree $\deg_1$, and, if $\Lambda_3=0$, also for the degree $\deg_2$, we have  
\begin{enumerate}
\item[(a)]  If $\tilde L_{2+j} v_\lambda \ne 0$ with $j\ge 1$, then
\begin{equation}
    \deg_{\,\delta} \tilde L_{2+j} v_\lambda \le \deg_{\,\delta}  v_\lambda - \deg_{\,\delta} L_{2-j}\,.
\end{equation}
\item[(b)]  If $\deg_{\,\delta} v_\mu > \deg_{\,\delta} v_\lambda$, then 
\begin{equation}
    \widetilde{\mathbf L}_\mu  v_\lambda =0.
\end{equation}
\end{enumerate}
\end{lemma}

\pf 
The first claim can be proved by straightforward case-by-case analysis of different values of $j$ for the case $\delta=1$ and (if $\Lambda_3=0$) also for $\delta=2$.
Statement $(b)$ is obtained by recursive application of  $(a)$. \epf

    \subsection{Rank $\frac52$ state in the rank $\frac32$ Whittaker module\label{AppA3}}
      We start by adapting the computations from Subsection \ref{subsec_Diffopapp} for the representation of Virasoro generators given by \eqref{52equationsV2}. The main steps are as follows. First, define conformal block as
    	\beq
    	\mathcal F^{(5/2)}\lb c_{_{1/2}},c_{_{3/2}},c_{_{5/2}}\rb= \bigl\langle 0 \bigr| I^{(5/2)}\bigr\rangle,
    	\eeq
    	where $L_n\bigl|I^{(5/2)}\bigr\rangle=\mathcal L_n^{(5/2)}\bigl|I^{(5/2)}\bigr\rangle$ for $n\ge 0$ and the differential operators $\mathcal L^{(5/2)}_n$ are defined by \eqref{52equationsV2}. Next, consider the Ward identities
    	\beq 
    	\mathcal L^{(5/2)}_{0}\mathcal F^{(5/2)}=0, \qquad  \mathcal L^{(5/2)}_{1}\mathcal F^{(5/2)}=0.
    	\eeq 
    	Their general solution reads
    	\beq
    	\mathcal F^{(5/2)}\lb c_{_{1/2}},c_{_{3/2}},c_{_{5/2}}\rb = \exp\left\{\frac{4c_{_{3/2}}^5}{405c_{_{5/2}}^3}-\frac{4c_{_{1/2}}c_{_{3/2}}^3}{27c_{_{5/2}}^2}
    	+\frac{2c_{_{1/2}}^2c_{_{3/2}}}{3c_{_{5/2}}}\right\} F\lb \xi\rb,
    	\eeq
    	where the irregular cross-ratio $\xi$ is given by
    	\beq \label{sc52}
    	\xi=-\frac{2i}{3} \frac{c_{_{3/2}}^{5/2}}{c_{_{5/2}}^{3/2}}\left(1-\frac{6c_{_{1/2}}c_{_{5/2}}}{c_{_{3/2}}^2}\right)^{5/4},
    	\eeq
    	and  $F\lb \xi\rb$ is an arbitrary function. It represents the part of conformal block which is not fixed by the Ward identities. 

    	At the next step, we would like to embed the rank $\frac52$ irregular state into the rank $\frac32$ Whittaker module in a way similar to \eqref{irr_state_dec}. Write 
    	\beq\label{auxI52}
    	\bigl| I^{(5/2)}\bigr\rangle=f\lb c_{_{1/2}},c_{_{3/2}},c_{_{5/2}}\rb |\tilde\Psi\rangle,
    	\eeq
    	where the normalized state $|\tilde \Psi\rangle$ and the singular prefactor $f$ are required to satisfy
    	\beq\label{fcond5232}
    	|\tilde\Psi\rangle=\bigl|I^{(3/2)}\bigr\rangle+o\lb 1\rb,\qquad f^{-1}\mathcal L_n^{(5/2)}f=\mathcal L_n^{(3/2)}+o\lb 1\rb.
    	\eeq
    	as $c_{_{5/2}}\to0$. The nontrivial operators  $\mathcal L_n^{(3/2)}$ are given by 
    	\beq
    	\begin{gathered}
    	\mathcal L_3^{(3/2)}=-c_{_{3/2}}^2,\qquad \mathcal L_2^{(3/2)}=-2c_{_{1/2}}c_{_{3/2}},\\
    	\mathcal L_1^{(3/2)}=-c_{_{1/2}}^2+\frac{c_{_{3/2}}}{2}\frac{\partial}{\partial c_{_{1/2}}},\qquad
    	\mathcal L_0^{(3/2)}=
    	\frac{3 c_{_{3/2}}}{2}\frac{\partial}{\partial c_{_{3/2}}}+
    	\frac{c_{_{1/2}}}{2}\frac{\partial}{\partial c_{_{1/2}}},
    	\end{gathered}
    	\eeq
    	cf Proposition~\ref{PropLs}.
    	The singular prefactor can be chosen in a form that incorporates the as-yet undetermined conformal block:
    	\beq\label{orthogauge32}
    	f\lb c_{_{1/2}},c_{_{3/2}},c_{_{5/2}}\rb=\frac{\bigl\langle 0 \bigr| I^{(5/2)}\bigl\rangle}{\bigl\langle 0 \bigr| I^{(3/2)}\bigr\rangle}.
    	\eeq
        Indeed, projecting  \eqref{auxI52} onto the vacuum and using \eqref{orthogauge32}, one obtains $\langle 0 |\tilde \Psi\rangle=\bigl\langle 0 \bigr| I^{(3/2)}\bigr\rangle$. The above choice therefore amounts to working in the orthogonal gauge.
    	Also note that the rank $\frac32$ conformal block  $\mathcal F^{(3/2)}\lb c_{_{1/2}},c_{_{3/2}}\rb=\bigl\langle 0\bigr|I^{(3/2)}\bigr\rangle$ can be easily found from the Ward identities: 
    	\beq
    	\mathcal F^{(3/2)}\lb c_{_{1/2}},c_{_{3/2}}\rb=\exp \frac{2c_{_{1/2}}^3}{3c_{_{3/2}}}.
    	\eeq


    	The leading  singular behavior of the  function $F\lb \xi \rb$ as $c_{_{5/2}}\to 0$ is determined by the condition \eqref{fcond5232}
    	\beq
    	\ln F\lb \xi\rb=\frac{\xi^2}{45}+O\lb \xi\rb,\qquad \xi\to\infty.
    	\eeq
    	The results obtained in the case of rank 2 reduction suggest that $\ln F\lb \xi\rb$ should admit an expansion in integer powers of $\xi$. This, however, immediately implies (cf \eqref{sc52}) that  $|\tilde \Psi\rangle$ should be expanded in \textit{half-integer} powers of $c_{_{5/2}}$:
    	\beq
    	|\tilde \Psi\rangle=\bigl| I^{(3/2)}\bigr\rangle+\sum_{k=1}^{\infty} c_{_{5/2}}^{k/2}
    	\bigl|I^{(3/2)}_{k/2}\bigr\rangle, \qquad \bigl\langle 0\bigr|I^{(3/2)}_{k/2}\bigr\rangle=0.
    	\eeq

    	We will now use the ideas of Subsection~\ref{SubsecAlgCon} to develop an algebraic construction of the normalized 
    	Whittaker state $|\tilde \Psi\rangle$.
    		Let $|\tilde J\rangle$ satisfy
    	\beq
    	L_{n>3}|\tilde J\rangle=0,\qquad L_{3}|\tilde J\rangle=|\tilde J\rangle,\qquad L_2|\tilde J\rangle=0,
    	\eeq 
    	and consider the corresponding Whittaker module
    	\beq
    	\mathcal V^{[3/2]}=\bigoplus_{m_{0,1}\in \mathbb Z_{\ge 0},\lambda\in\mathbb Y}\mathbb C\,\mathbb L_{-\lambda}L_0^{m_0}L_1^{m_1}|\tilde J\rangle.
    	\eeq
    	We would like to find $|\tilde\Psi\rangle\in \mathcal V^{[3/2]}$ such that
    	\beq\label{Wh52version32}
    	L_{n>5}|\tilde\Psi\rangle=0,\qquad L_5|\tilde\Psi\rangle=\varepsilon^2 |\tilde\Psi\rangle,
    	\qquad L_4|\tilde\Psi\rangle=-2\varepsilon  |\tilde\Psi\rangle,\qquad 
    	L_3|\tilde\Psi\rangle= |\tilde\Psi\rangle.
    	\eeq
    	The parameterization of eigenvalues is suggested by \eqref{52equationsV2} and corresponds to setting $c_{_{1/2}}=0$, $c_{_{3/2}}=-i$, ${c_{_{5/2}}=i\varepsilon}$ therein. The parameter $\varepsilon$  should not be confused with the one used in Subsection~\ref{SubsecAlgCon}. It is related to the parameter $\xi$ as
    	\beq
    	\xi=-\frac{2i}{3}\varepsilon^{-3/2}.
    	\eeq
    	As $\varepsilon\to0$, the relations \eqref{Wh52version32} are verified not only by $|\tilde{J} \rangle$ but also by $L_1^p|\tilde{J}\rangle$ for any $p\in\mathbb N$. This constitutes a major difference as compared to the rank $2$ embedding. We look for  $|\tilde\Psi\rangle$ in the form
    	\beq \label{psit32ser}
    	|\tilde\Psi\rangle=|\tilde J\rangle+\sum_{k=1}^{\infty} \varepsilon^{k/2}\mathbb{G}_{k/2}|\tilde J\rangle, \qquad \mathbb G_{k/2}=\sum_{m_0,m_1\in\mathbb Z_{\ge0},\lambda\in\mathbb Y}G_{\lambda;m_0,m_1}^{[k/2]}\mathbb L_{-\lambda}L_0^{m_0}L_1^{m_1}, 
    	\eeq
    	and impose the orthogonal gauge conditions
    	\beq\label{OGII}
    	G_{\emptyset;0,0}^{[k/2]}=0,\qquad k\in\mathbb N.
    	\eeq

    	In contrast to the rank $2$ embedding, the algebraic relations \eqref{Wh52version32} are not sufficient for the construction of $|\tilde\Psi\rangle$. We will also need an analog of~$L_\varepsilon$. It can be found by constructing an antihomomorphism of a suitable subalgebra of $\mathsf{Vir}$ into the algebra of 1st order differential operators along the lines of Subsection~\ref{SubsectionConfBlocks52}. Consider a linear combination $ L_\varepsilon=AL_2+BL_1+CL_0$ and require that
    	\beq
    	\begin{gathered}
    		L_n\mapsto \mathcal L_n,\qquad n\in \{\varepsilon\}\cup \mathbb N_{\ge3},\\
    		\mathcal L_{n\ge 6}= 0,\qquad \mathcal L_5= \varepsilon^2,\qquad 
    		\mathcal L_4=-2\varepsilon,
    		\qquad \mathcal L_3= 1,\qquad 
    		\mathcal L_{\varepsilon}=f\lb \varepsilon\rb\frac{\partial}{\partial\varepsilon}.
    	\end{gathered}
    	\eeq
    	Computing the commutators
    	\begin{subequations}
    		\begin{align}
    			\left[L_3,L_{\varepsilon}\right]=&\,AL_5+2BL_4+3CL_3\mapsto A\varepsilon^2-4B\varepsilon+3C,\\
    			\left[L_4,L_{\varepsilon}\right]=&\,2AL_6+3BL_5+4CL_4\mapsto 3B\varepsilon^2-8C\varepsilon,\\
    			\left[L_5,L_{\varepsilon}\right]=&\,3AL_7+4BL_6+5CL_5\mapsto 5C\varepsilon^2,
    		\end{align}
    	\end{subequations}
    	and comparing them with
    	\beq
    	\left[\mathcal L_{\varepsilon},\mathcal L_3\right]=0,\qquad 
    	\left[\mathcal L_{\varepsilon},\mathcal L_4\right]=-2f\lb \varepsilon\rb,\qquad
    	\left[\mathcal L_{\varepsilon},\mathcal L_5\right]=2\varepsilon f\lb \varepsilon\rb,
    	\eeq
    	we can set 
    	\beq
    	L_\varepsilon=L_2+\varepsilon L_1+\varepsilon^2 L_0,\qquad \mathcal L_{\varepsilon}=\frac{5\varepsilon^3}{2}\frac{\partial}{\partial\varepsilon}.
    	\eeq

    	Note that we can add to $\mathcal L_{\varepsilon}$ an arbitrary function of $\varepsilon$ without changing the commutation relations. This freedom corresponds to different embeddings of the rank $\frac52$ Whittaker vector into rank $\frac32$ Whittaker module. 
    	Let us define the action of $L_\varepsilon$ as
    	\beq \label{lepsil32}
    	L_\varepsilon|\tilde{\Psi}\rangle=\left(\frac{5\varepsilon^3}{2}\frac{\partial}{\partial\varepsilon}+\sum_{k=1}^{\infty}\alpha_k \varepsilon^{\frac{3k}{2}-1}\right)|\tilde{\Psi}\rangle,
    	\eeq
    	where the coefficients of the formal series in the second term can be chosen arbitrarily.
    	\begin{conj} The state $|\tilde{\Psi}\rangle$ defined by the relations \eqref{Wh52version32}, \eqref{psit32ser}--\eqref{OGII} and \eqref{lepsil32} exists
    		and is uniquely determined in terms of $\left\{\alpha_n\right\}_{n\in\mathbb N}$ and the central charge $c$. Moreover,
    		\beq\label{selectionrulesWHv2}
    		\mathbb G_{k/2}=\sum_{\substack{1\leq\ell\leq k \\ \ell=k\;\mathrm{mod}\;3}}\sum_{\substack{m_0,m_1\in\mathbb Z_{\ge0},\lambda\in\mathbb Y \\ m_1+3m_0+2|\lambda|=\ell}}G_{\lambda;m_0,m_1}^{[k/2]}\mathbb L_{-\lambda}L_0^{m_0}L_1^{m_1}.
    		\eeq
    		where the coefficients $G_{\lambda;m_0,m_1}^{[k/2]}$ depend only on $\alpha_1, \ldots, \alpha_{\left[(k+2)/3\right]}$.
    	\end{conj}



    	The $\mathrm{mod}\;3$ selection rule stems from the $\mathbb Z_3$-symmetry of the relations \eqref{Wh52version32} defining the irregular vector~$|\tilde{\Psi}\rangle$. Namely, their form is preserved by the transformation
    	\beq
    	L_n\mapsto \omega^{-n}L_n, \qquad \varepsilon\mapsto \omega^2 \varepsilon, \qquad \omega^3=1.
    	\eeq
    	The restriction $m_1+3m_0+2|\lambda|=\ell$ was observed experimentally. It can be reformulated using the following definition of degree of the Virasoro generators:
    	\beq
    	\mathrm{deg}\, L_1=\frac{1}{2}, \qquad \mathrm{deg}\, L_0=\frac{3}{2}, \qquad \mathrm{deg}\, L_{-k}=k, \qquad k\in \mathbb{N}.
    	\eeq
    	Under such assignments, the corresponding selection rule can be rewritten as $\operatorname{deg}\, \mathbb G_{k/2}\leq \frac{k}{2}$.

    		The irregular state is thus fixed by a single function (formal series) that has to be determined from other considerations. A similar phenomenon was observed in a related but different context in \cite[Conjecture~3.2]{Nagoya18}.
    	The first  descendant contributions to $|\tilde{\Psi}\rangle$ are explicitly given by 
    	\begin{subequations}
    	\begin{align}
    		&\, \mathbb G_{1/2}=-2\nu L_1, \qquad \mathbb G_{1}=-\frac{2}{5}L_{-1}+\frac{20 \nu ^2+1}{10}L_1^2,\\
    	&\, \mathbb G_{3/2}=-\frac{16\nu}{15} L_0+\frac{4\nu}{5}L_{-1}L_1
    	-\frac{\nu\left(20 \nu ^2+3  \right)}{15} L_1^3,\\
    	&\,\begin{aligned}
    		\mathbb G_{2}=&\,-\frac{1}{5}L_{-2}+\frac{2}{25}L_{-1}^2+\frac{160 \nu ^2+9}{75} L_0 L_1-\frac{20 \nu ^2+1}{25} L_{-1}L_1^2
    		+\frac{400 \nu ^4+120 \nu ^2+3}{600} L_1^4\\&\,-\frac{640 \nu ^2-1125 \alpha -15 c+36}{150} L_1,
    	\end{aligned}\\
    	&\,\begin{aligned}
    		\mathbb G_{5/2}=&\,\frac{2\nu}{5} L_{-2}L_1+\frac{32\nu}{75} L_{-1}L_0-\frac{28\nu}{25} L_{-1}-\frac{2\nu\left(80 \nu ^2+13  \right)}{75}  L_0 L_1^2 +\frac{2\nu\left(20 \nu ^2+3 \right)}{75}  L_{-1}L_1^3\\
    		&\,+\frac{4\nu}{25} L_{-1}L_1^2-\frac{\nu\left(80 \nu ^4+40 \nu ^2+3 \right)}{300}  L_1^5
    		+\frac{\nu\left(2560 \nu ^2-4500 \alpha   -60c  +377  \right)}{300}  L_1^2,
    	\end{aligned}
    	\end{align}
    \end{subequations}	
    where we parameterize $\alpha_1=-2\nu$, $\alpha_2=\frac{15\alpha}{2}$.




\section{Completion of the proof of the conifold gap property}
\label{appendix:constant-term}


Here, we present the final part of the proof of Theorem \ref{thm:coni-gap},  
specifically addressing the proof of equation \eqref{eq:limit-Fg-appendix}. 
Before proceeding, let us briefly recall the proof strategy outlined in Section 4.4.3. Starting from the original spectral curve 
${\mathcal C}$ defined in equation \eqref{eq:spcurve}, 
we performed a symplectic transformation \eqref{eq:symplectic-tr-to-Weber}, 
resulting in a new spectral curve 
$\widetilde{\mathcal C}$ as defined in equation \eqref{eq:spcurve-Weber-expression}. 
Importantly, both spectral curves ${\mathcal C}$ and $\widetilde{\mathcal C}$
share the same free energy $F_g$. 
While the defining equation for 
${\mathcal C}$ has diverging coefficients as $\Lambda \to 0$, 
the symplectic transformation absorbs this divergence, 
and the Weber curve ${\mathcal C}_{\rm Web}$, which is given in \eqref{eq:Weber-curve},  
appears as the limit of $\widetilde{\mathcal C}$ as $\Lambda \to 0$.
The claim to be shown is that the limit of $F_g$ of ${\mathcal C}$ 
as $\Lambda \to 0$ exists and coincides with that of 
${\mathcal C}_{\rm Web}$. 
In this Appendix, we provide the proof of this statement.





%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsection{Review of topological recursion for the Weber curve}

First, we recall several results regarding the topological recursion for 
the Weber curve ${\mathcal C}_{\rm Web}$, which plays an essential role in the proof.
The Weber curve is known as the spectral curve for the Gaussian matrix model, 
whose correlator and free energy were studied from the viewpoint of TR by many authors; 
see \cite{Nor09, IKoT1} for example. 


We can apply TR to the Weber curve \eqref{eq:spcurve-Weber-expression} 
through the Zhukovsky parametrization
\begin{equation}  \label{eq:Weber-paranetrization}
(\widetilde{X},\widetilde{Y}) = 
\left( \sqrt{\nu}\,(w + w^{-1}) ,  \frac{\sqrt{\nu}}{2}\,(w - w^{-1}) \right).
\end{equation}
The ramification points are $w = \pm 1$, 
and $\sigma(w) = w^{-1}$ gives the covering involution map. 
We denote by $W_{g,n}^{\rm Web}$ the correlators of the Weber curve. 
The first few correlators are 
\begin{equation} \label{eq:W01-02-Web}
W_{0,1}^{\rm Web}(w_1) % \left( = \widetilde{Y}_0(w_1) d\widetilde{X}(w_1) \right)
= \frac{\nu (w_1^2-1)^2 }{2w_1^3} \, dw_1, \qquad
W_{0,2}^{\rm Web}(w_1, w_2) = \frac{dw_1 dw_2}{(w_1 - w_2)^2}, 
\end{equation}
\begin{equation}
W_{0,3}^{\rm Web}(w_1, w_2, w_3) = 
\frac{dw_1 dw_2 dw_3}{2\nu} \biggl( \frac{1}{(w_1-1)^2(w_2-1)^2(w_3-1)^2} 
+ \frac{1}{(w_1+1)^2(w_2+1)^2(w_3+1)^2} \biggr), 
\end{equation}
\begin{equation}
W_{1,1}^{\rm Web}(w_1) = - \frac{w_1^3 \, dw_1}{\nu (w_1^2-1)^4}.
\end{equation}
The correlators with $2g-2+n \ge 1$ are holomorphic except for the ramification points. 
Particularly, the fact that they are holomorphic at $w_i = 0, \infty$, 
which corresponds to the $\widetilde{X} = \infty$, 
will be crucial in the following discussion. 
We will also use the following alternative expression of TR 
which can be obtained by the residue theorem, similarly to \eqref{eq:alternative-TR-scaling}:
\begin{equation} \label{eq:alt-Weber}
W_{g,n}^{\rm Web}(w_1, \dots, w_n) = 
-2
\sum_{i=1}^{n}  \Res_{\widetilde{X}=\widetilde{X}_i} 
\frac{\int^{\widetilde{X}'=\widetilde{X}}_{\widetilde{X}'=\infty} {W}^{\rm Web}_{0,2}(\widetilde{X}_1, \widetilde{X}')}
{2W_{0,1}^{\rm Web}(\widetilde{X})} \, {R}^{\rm Web}_{g,n}(\widetilde{X}, \widetilde{X}_2, \dots, \widetilde{X}_n),
% -2 \sum_{j=1}^{n} \Res_{w = w_j} K^{\rm Web}(w_1,w) R^{\rm Web}_{g,n}(w, w_2, \dots, w_n),
\end{equation}
where % $K^{\rm Web}$ and 
$R_{g,n}^{\rm Web}$ is 
% \eqref{eq:rec-ker} and 
\eqref{eq:R-gn} for the Weber curve, and the relation between the coordinates 
$w_i$ and $\widetilde{X}_i$ are given in \eqref{eq:Weber-paranetrization}; that is,
\begin{equation} \label{eq:coord-wi}
\widetilde{X}_i = \nu (w_i + w_{i}^{-1}),  \qquad i = 1,\dots, n.
\end{equation} 

As we have seen in \eqref{eq:Weber-free-energy-explicit}, 
an explicit formula for the free energy $F^{\rm Web}_g$ in terms of Bernoulli numbers is known, 
and it plays an essential role in the derivation of \eqref{eq:limit-Fg-appendix}, which will be discussed below.


%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsection{Another series expansion of $W_{g,n}$}




Here we show that the correlator $W_{g,n}$ of the spectral curve ${\mathcal C}$
has a series expansion when $\Lambda \to 0$ 
when we regard $\widetilde{X}$,  given in \eqref{eq:symplectic-tr-to-Weber}, as $t$-independent. 
% The series expansion is different from \eqref{eq:expansion-Wgn}
% because different variables are considered $t$-independent in computing the series expansion.  
We note that, since the coordinate $X$, introduced in \eqref{eq:scaling-data}, 
%  and used to compute the series expansion of $W_{g,n}$ and $F_g$ in \S \ref{section:TR-expansion}, 
is related to $\widetilde{X}$ through $t$-depending functions as 
\begin{equation} \label{eq:rel-coord}
X = \gamma^{-2} x =  \frac{\tilde{e}_2 + \tilde{e}_3}{2} + \gamma^{-2} \alpha \widetilde{X}, \qquad \gamma^{-2}=(3a)^{-1}(-t)^{-1/2}.
\end{equation}
the expansion we will obtain below will be different from \eqref{eq:expansion-Wgn}. 

Let us look at the expansion of $W_{0,1}$. 
Using the series expansion \eqref{tilde-e1}--\eqref{tilde-e3} of $e_i$
and the relation \eqref{eq:rel-coord} among the coordinates, we have
\begin{align} 
\widetilde{Y} & = (1 + 16 \alpha^5  \widetilde{X} )^{1/2} 
\left( \frac{\widetilde{X}^2}{4} - \frac{(e_2-e_3)^2}{16 \alpha^2}\right)^{1/2} \notag \\
& 
=  \frac{\sqrt{\widetilde{X}^2- 4\nu}}{2} + \frac{\widetilde{X} \sqrt{\widetilde{X}^2- 4\nu}}{8} \, \Lambda^{1/2} 
- \frac{\widetilde{X}^4 - 4\nu \widetilde{X}^2 + 2 \nu^2}{64 \sqrt{\widetilde{X}^2- 4\nu} } \Lambda 
+ \frac{\widetilde{X}^5 + 56 \nu \widetilde{X}^3 - 242 \nu^2 \widetilde{X}}{256 \sqrt{\widetilde{X}^2- 4\nu}} \Lambda^{3/2}
+ O\lb \Lambda^{2} \rb.
\label{eq:alt-expansion-tildeY} 
\end{align}
Here and in what follows, the branch of $\sqrt{\widetilde{X}^2 - 4\nu}$ 
% (which will also appear in the series coefficients of $\widetilde{W}_{g,n}$), 
is chosen so that
\begin{equation} \label{eq:branch-weber-limit}
\frac{\sqrt{\widetilde{X}^2- 4\nu}}{2} \, d\widetilde{X} 
= \frac{\nu (w^2-1)^2 }{2w^3} \, dw
\end{equation}
holds under the change of coordinate \eqref{eq:Weber-paranetrization}.
The equality \eqref{eq:alt-expansion-tildeY} shows that 
$W_{0,1} = \widetilde{Y} d\widetilde{X}$ has the series expansion 
of the form 
\begin{equation}
W_{0,1}(\widetilde{X}) = 
\sum_{\ell \ge 0} \widetilde{W}_{0,1}^{[\ell]}(\widetilde{X}) \, \Lambda^{\ell/2} 
\end{equation}
with certain meromorphic differentials $\widetilde{W}_{0,1}^{[\ell]}$
on the Weber curve ${\mathcal C}_{\rm Web}$. 
In particular, \eqref{eq:branch-weber-limit} implies that 
the leading term $\widetilde{W}_{0,1}^{[0]}$ agrees with $W_{0,1}^{\rm Web}$ 
under the change of coordinate \eqref{eq:Weber-paranetrization}.
Even when taking into account the coordinate transformation \eqref{eq:rel-coord}, 
it should be noted that $\widetilde{W}_{0,1}^{[\ell]}(\widetilde{X})$ 
defined here and $W_{0,1}^{[\ell]}(X)$ given in \eqref{eq:expansion-Wgn}
are entirely different differentials. 




It also follows from the expression \eqref{eq:Bergman-via-XY} 
of Bergman bidifferential and the above expansion \eqref{eq:alt-expansion-tildeY} 
that $W_{0,2}$ also has the series expansion of the form 
\begin{equation}
W_{0,2}(\widetilde{X}_1, \widetilde{X}_2) = 
\sum_{\ell \ge 0} 
\widetilde{W}_{0,2}^{[\ell]}(\widetilde{X}_1, \widetilde{X}_2) \, \Lambda^{\ell/2} 
\end{equation}
with certain meromorphic bidifferentials $\widetilde{W}_{0,2}^{[\ell]}$ 
on ${\mathcal C}_{\rm Web}$. 
The first few terms are 
\begin{subequations}
\begin{align}
\widetilde{W}_{0,2}^{[0]}(\widetilde{X}_1, \widetilde{X}_2) & = 
\frac{\widetilde{X}_1 \widetilde{X}_2 + \sqrt{\widetilde{X}_1^2- 4\nu} \sqrt{\widetilde{X}_2^2- 4\nu} - 4 \nu}
{2(\widetilde{X}_1 - \widetilde{X}_2)^2 \sqrt{\widetilde{X}_1^2- 4\nu} \sqrt{\widetilde{X}_2^2- 4\nu}} \, 
d\widetilde{X}_1 d\widetilde{X}_2, \\
\widetilde{W}_{0,2}^{[1]}(\widetilde{X}_1, \widetilde{X}_2) & = 0, \\
\widetilde{W}_{0,2}^{[2]}(\widetilde{X}_1, \widetilde{X}_2) & = 
\frac{\widetilde{X}_1^3 \widetilde{X}_2^3 - 4 \nu \widetilde{X}_1 \widetilde{X}_2(\widetilde{X}_1^2+\widetilde{X}_2^2) 
+ 18 \nu^2 \widetilde{X}_1 \widetilde{X}_2 + 8 \nu^3}
{64(\widetilde{X}_1^2- 4\nu)^{3/2} (\widetilde{X}_2^2- 4\nu)^{3/2}} \, 
d\widetilde{X}_1 d\widetilde{X}_2, \\
\widetilde{W}_{0,2}^{[3]}(\widetilde{X}_1, \widetilde{X}_2) & =
-\frac{(\widetilde{X}_1+\widetilde{X}_2)(\widetilde{X}_1\widetilde{X}_2-2\nu)}{128\sqrt{\widetilde{X}_1^2- 4\nu} \sqrt{\widetilde{X}_2^2- 4\nu}} \, d\widetilde{X}_1 d\widetilde{X}_2.
\end{align}
\end{subequations}
We can also confirm that $\widetilde{W}_{0,2}^{[0]} = W_{0,2}^{\rm Web}$ 
holds under the coordinate transform \eqref{eq:coord-wi}. 

More generally, we have

\begin{prop}
For each  $g \ge 0$, $n \ge 1$, %  satisfying $2g-2+n \ge 0$ 
the correlator $W_{g,n}$ of the spectral curve $\widetilde{\mathcal C}$ 
(and ${\mathcal C}$)
has the following convergent series expansion at $\Lambda = 0$:
\begin{equation}\label{eq:alt-expansion-Wgn}
W_{g,n}(\widetilde{X}_1, \dots, \widetilde{X}_n) = 
\sum_{\ell \ge 0} \widetilde{W}_{g,n}^{[\ell]}(\widetilde{X}_1, \dots, \widetilde{X}_n)
% (w_1, \dots, w_n) 
\, \Lambda^{\ell/2}.
\end{equation}
The coefficients $\widetilde{W}_{g,n}^{[\ell]}$ are meromorphic multi-differentials 
on the Weber curve ${\mathcal C}_{\rm Web}$, and independent of $\Lambda$. 
In particular, the leading term coincides with the correlator of the Weber curve 
\begin{equation} \label{eq:leading-Weber}
W_{g,n}^{\rm Web}(w_1, \dots, w_n) = 
\widetilde{W}_{g,n}^{[0]}(\widetilde{X}_1, \dots, \widetilde{X}_n)
\end{equation} 
under the change of the coordinate \eqref{eq:coord-wi}.
% \eqref{eq:Weber-paranetrization}.
% that is, $X_i = \sqrt{\nu} (w_i + w_i^{-1})$. %\eqref{eq:coord-wi}.
\end{prop}


\begin{proof} 

Since the case for $(g,n) = (0,1)$ and $(0,2)$ have already been shown above, 
we will now provide the proof for general $(g,n)$ using the induction.

Similarly to the proof of Proposition \ref{prop:expansion-Wgn}, 
it is necessary to rewrite the original TR formula \eqref{eq:top-rec} 
in order to avoid difficulties arising from the 
collision of ramification points (i.e., $e_2, e_3 \to 1/3$) in $\Lambda \to 0$.
As well as \eqref{eq:alternative-TR-scaling}, the residue theorem provides 
the following alternative expression of TR formula (c.f., \cite[Lemma B.1]{Iwaki19}):
\begin{align} 
W_{g,n}(\widetilde{X}_1, \dots, \widetilde{X}_n) 
& =  
\frac{d\widetilde{X}_1}{{\omega}_A \, \widetilde{Y}(\widetilde{X}_1)} \,  
\oint_{\widetilde{X} \in A} \frac{{R}_{g,n}(\widetilde{X}, \widetilde{X}_2, \dots, \widetilde{X}_n)}
{2W_{0,1}(\widetilde{X})}  % {2\widetilde{Y}(\widetilde{X}) \, d\widetilde{X}}  
- 2 
\sum_{i=1}^{n}  \Res_{\widetilde{X}=\widetilde{X}_i} 
\frac{\int^{\widetilde{X}'=\widetilde{X}}_{\widetilde{X}'=\infty} {W}_{0,2}(\widetilde{X}_1, \widetilde{X}')}
{2W_{0,1}(\widetilde{X})}  % {2\widetilde{Y}(\widetilde{X}) \, d\widetilde{X}}  
\, {R}_{g,n}(\widetilde{X}, \widetilde{X}_2, \dots, \widetilde{X}_n). 
\label{eq:alt-TR}
\end{align}
Under the induction hypothesis, ${R}_{g,n}$ has a series expansion of the form 
\begin{equation} \label{eq:ser-Rgn-Web}
{R}_{g,n}(\widetilde{X}, \widetilde{X}_2, \dots, \widetilde{X}_n)
= \sum_{\ell \ge 0}
\widetilde{R}^{[\ell]}_{g,n}(\widetilde{X}, \widetilde{X}_2, \dots, \widetilde{X}_n) \, \Lambda^{\ell/2}.
\end{equation}
The coefficients $\widetilde{R}^{[\ell]}_{g,n}$ are meromorphic quadratic differentials 
on ${\mathcal C}_{\rm Web}$ in the first variable $\widetilde{X}$. 

We note that, under the change \eqref{eq:Weber-paranetrization} of the coordinate, 
the $A$-cycle is now represented by a lift of closed curve on $\widetilde{X}$-plane 
which encircles the two ramification points $\widetilde{X} = \pm (e_2 - e_3)/2 \alpha$ 
of \eqref{eq:spcurve-Weber-expression}.
Then, we can use the same argument which we have used 
in the proof of Proposition \ref{prop:expansion-Wgn};
that is, the $A$-cycle integral can be reduced to term-wise residue calculus
at $\widetilde{X} = \infty$ 
(i.e., $w = \infty$ in the parametrization \eqref{eq:Weber-paranetrization}). 
This allows us to obtain a series expansion of $W_{g,n}$ of the form \eqref{eq:alt-expansion-Wgn}, 
and each coefficient can be explicitly computed term-by-term at any order in principle.


Next, let us show \eqref{eq:leading-Weber}. 
Looking at the leading terms of the both sides of \eqref{eq:alt-TR}, we have
\begin{align} 
\widetilde{W}^{[0]}_{g,n}(\widetilde{X}_1, \dots, \widetilde{X}_n) 
& = - \frac{d\widetilde{X}_1}{\omega^{[0]}_A \, \widetilde{Y}^{[0]}(\widetilde{X}_1)} \,  
\oint_{\widetilde{X} \in A} \frac{\widetilde{R}^{[0]}_{g,n}(\widetilde{X}, \widetilde{X}_2, \dots, \widetilde{X}_n)}
{2\widetilde{W}_{0,1}^{[0]}(\widetilde{X})}  
% \notag \\ & \qquad 
- 2  \, 
\sum_{i=1}^{n}  \Res_{\widetilde{X}=\widetilde{X}_i} \frac{\int^{\widetilde{X}'=\widetilde{X}}_{\widetilde{X}'=\infty} 
\widetilde{W}^{[0]}_{0,2}(\widetilde{X}_1, \widetilde{X}')}
{2\widetilde{W}_{0,1}^{[0]}(\widetilde{X})} \, \widetilde{R}^{[0]}_{g,n}(\widetilde{X}, \widetilde{X}_2, \dots, \widetilde{X}_n),
\label{eq:alternative-TR-Web}
\end{align} 
where 
$\widetilde{Y}^{[0]}(\widetilde{X}) = \frac{1}{2}\sqrt{\widetilde{X}^2 - 4\nu}$  
% \sqrt{\widetilde{X}^2 - 4\nu} \,/2
is the leading term of $\widetilde{Y}$ (c.f., \eqref{eq:alt-expansion-tildeY}).  
Under the induction hypothesis, 
$\widetilde{R}^{[0]}_{g,n}$ coincides with $R_{g,n}^{\rm Web}$ 
under the coordinate change \eqref{eq:coord-wi}.
Since $\widetilde{X}=\infty$ is not the ramification point of the Weber curve ${\mathcal C}_{\rm Web}$,
$W_{g,n}^{\rm Web}$ are holomorphic there. 
This implies that 
$\widetilde{R}^{[0]}_{g,n}/\widetilde{W}_{0,1}^{[0]} = R_{g,n}^{\rm Web}/W_{0,1}^{\rm Web}$ 
is holomorphic at $\widetilde{X} = \infty$, and hence, 
the first term of \eqref{eq:alternative-TR-Web} becomes trivial.
Therefore, we can conclude that the leading term $\widetilde{W}^{[0]}_{g,n}$ satisfies 
the same equation \eqref{eq:alt-Weber} as $W_{g,n}^{\rm Web}$, which implies 
the desired equality \eqref{eq:leading-Weber}. This completes the proof.
\end{proof}






%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsection{Proof of ~ $\lim_{\Lambda \to 0} F_g  = F_g^{\rm Web}$.}

Here we provide the final step in the proof of \eqref{eq:limit-Fg-appendix}. 

First, we show that the residue at $r_1$ in the definition \eqref{Fgdef} of $F_g$ 
does not contribute to the constant term in \eqref{eq:expansion-Fg}, as follows. 
Since $e_1 = x(r_1)$ is away from the collision of the ramification points $e_2, e_3$,  
no singular points of the integrant of \eqref{Fgdef} hits the residue cycle around $r_1$.
Consequently, we have 
\begin{equation}
\Res_{z=r_1} \,\Phi\lb z\rb W_{g,1}\lb z\rb 
= \Lambda^{2g-2} \Res_{X = e_1} \left( \int^{X} W^{\rm res}_{0,1}(X) \right) W^{\rm Res}_{g,1}(X) 
~\rightarrow~ 0, \qquad \Lambda \to 0,
\end{equation}
for $g \ge 2$. Here we have used \eqref{eq:scaling-degree-Wgn}. 

On the other hand, by taking the coordinate $\widetilde{X}$ 
given in \eqref{eq:Weber-paranetrization}, 
the aforementioned collision of the ramification points is resolved,
and it can be seen from \eqref{tilde-e1}--\eqref{tilde-e3} that 
the points corresponding to $e_2, e_3$ converge to the ramification points 
$\pm 2\sqrt{\nu}$ of the Weber curve ${\mathcal C}_{\rm Web}$ when $\Lambda \to 0$. 
Therefore, we have 
\begin{equation} 
\lim_{\Lambda \to 0} F_g 
= % \lim_{\Lambda \to 0} 
\frac{1}{2-2g} \left(  \Res_{\widetilde{X} = 2 \sqrt{\nu}} + \Res_{\widetilde{X} = - 2 \sqrt{\nu}} \right) 
\left(\int^{\widetilde{X}} \widetilde{W}^{[0]}_{0,1}(\widetilde{X}) \right) \widetilde{W}_{g,1}^{[0]}(\widetilde{X}).
\end{equation}
Then, the result \eqref{eq:leading-Weber} shows that 
the right hand side of the above equality is identical to $F_{g}^{\rm Web}$. 
Thus we have obtained the desired result \eqref{eq:limit-Fg-appendix}, 
and this also completes the proof of Theorem \ref{thm:coni-gap}. 
% (thanks to the known result \eqref{eq:Weber-free-energy-explicit}).





\section{Verification of a resurgence formula}
\label{appendix:conjecture-resurgence}


In recent years, the study of resurgence properties of the free energy and partition function 
in topological string theory has advanced significantly. 
% In \cite{cesv1, cesv2}, Couso-Santamar{\'\i}a--Edelstein--Schiappa--Vonk proposed 
% a method for constructing trans-series solutions to the holomorphic anomaly equation. 
% Furthermore, 
Recently, Gu--Mari\~no discovered a conjectural formula describing 
the alien derivatives of the free energy in \cite{gm22} through 
the non-perturbative analysis of the holomorphic anomaly equation, based on earlier works \cite{cesv1, cesv2}. 
Since the TR free energy also satisfies the holomorphic anomaly equation, 
it is expected to fulfill the above conjectural formula.  
Indeed, in \cite{IM24}, it was derived based on heuristic observations of 
the monodromy preserving deformations of the quantum curve 
that the TR free energy considered in this paper satisfies the conjectural formula of \cite{gm22}. 

In the following, we review this conjectural formula and compare it with known studies on 
the Stokes phenomenon for Painlev\'e transcendents. 
In conclusion, it can be confirmed that the formula conjectured in \cite{gm22, IM24} 
for the free energy $F^{\rm deg}(t; \hbar) = \sum_{g \ge 0} \hbar^{2g-2} F^{\rm deg}_g(t)$ 
defined by a degenerate elliptic curve ${\mathcal C}_{\rm deg}$ 
is consistent with the connection formula for the tri-tronqu\'ee solution of the P$_{\rm I}$ 
obtained by Kapaev, Kitaev, and others. The purpose of this section is to introduce this fact.

Unfortunately, as of now, there is no mathematically rigorous proof that 
the free energy is Borel summable and resurgent. 
% \footnote{
% For some spectral curves of genus 0, a rigorous proof has been provided, for example, in \cite{IK-II}.}. 
Below, we will proceed under the assumption that TR partition function and free energy are 
Borel summable and resurgent, and compare it with the Stokes phenomenon of the Painlev\'e equations.
See \cite{Sauzin14} for the foundation of resurgence theory. 


\subsection{Conjectural resurgence formula} 

Let 
\begin{equation}
\widehat{F}(t, \nu;\hbar) = \sum_{g \ge 2} \hbar^{2g-2} F_g(t, \nu) 
\quad \Bigl( = {F}(t, \nu;\hbar) - \hbar^{-2} F_0(t, \nu) - F_1(t,\nu) \Bigr)
\end{equation}
be the ``stable part'' of the TR free energy of the spectral curve ${\mathcal C}$. 
% \eqref{eq:sp-PI}
The conjecture of Drukker--Mari\~no--Putrov \cite{dmp-np} claims that 
the singularities of the Borel transform 
\begin{equation}
{\mathcal B}\widehat{F}(t, \nu;\zeta) = \sum_{g \ge 2} \frac{F_g(t,\nu)}{(2g-3)!} \, \zeta^{2g-3}
\end{equation}
are contained in the lattice 
\begin{equation}
{\mathcal P} = \left\{ m \oint_A ydx + n \oint_B ydx ~;~ m,n \in \mathbb Z \right\} ~ \subset ~ {\mathbb C}_\zeta
\end{equation}
of periods of $W_{0,1} = y dx$ on the complex $\zeta$-plane, which is called the Borel plane. 
These singularities are called the Borel singularities. 
% In our case, the lattice is generated by 
% \begin{equation}
% \phi(t) = 2\int^{q_0(t)}_{-2q_0(t)} y \, dx = - \frac{48 \sqrt{3}}{5} q_0(t)^{5/2}.
% \end{equation} 
% The lattice ${\mathcal P} = {\mathbb Z} \cdot \phi(t)$ becomes rank 1 since the $A$-cycle is reduced to the point $x = q_0(t)$, 
% and the above $\phi(t)$ can be understood as the pinched $B$-cycle integral. 
We also assume that ${\mathcal B}\widehat{F}(t, \nu;\zeta)$ has analytic continuation along 
any path in ${\mathbb C}_\zeta \setminus {\mathcal P}$, 
and the Borel sum 
\begin{equation} \label{eq:Borel-sum}
{\mathcal S}F(t,\nu; \hbar) = \hbar^{-2} F_0(t, \nu) + F_1(t,\nu) + 
\int^{+\infty}_{0} e^{-\zeta/\hbar} {\mathcal B} \widehat{F}(t, \nu;\zeta) \, d\zeta
\end{equation}
of the free energy is well-defined if the integration contour never hits the points in ${\mathcal P}$. 
% The Borel sum of the TR partition function is given by ${\mathcal S}Z(t,\nu;\hbar) = \exp\left( {\mathcal S} F(t,\nu; \hbar) \right)$.

Now, let us focus on the contribution of integer multiples of the $B$-period 
\begin{equation} \label{eq:Borel-B-period}
\phi(t,\nu) = \oint_{B} y \, dx
\end{equation}
to the Borel sum.
% \footnote{
% The appearance of the Borel singularity at the $A$-period $\oint_A y dx = 2 \pi i \nu$ 
% is quite natural in view of the conifold gap property (Theorem \ref{thm:coni-gap}), 
% as discussed by Pasquetti--Schiappa \cite{ps09}.
% }. 
We assume that our parameters $t, \nu$ are chosen so that the above $B$-period is real and positive.
As in \cite[\S 2.3]{IM24}, it is possible to realize the situation by choosing 
$t \in {\mathbb R}_{<0}$ with $|t|$ being sufficiently large, 
and an appropriate $A$-cycle with gives $\nu \in {\mathbb R}_{>0}$ by \eqref{eq:nu}. 
Actually, the choice of cycles in \cite[\S 2.3]{IM24} differs from that in Section \ref{subsec:rescale} of this paper. 
However, through similar calculations, it can be seen that the $B$-period exhibits the following asymptotic behavior
\begin{equation}
\phi(t,\nu) =\frac{1}{\Lambda} \left(  \frac{16}{15} 
+ \nu \Lambda \left(-1 + \log \Bigl(\frac{\Lambda \nu}{64}\Bigr) \right)
+ \frac{141 \nu^2 \Lambda^2}{64} + \frac{7717 \nu^3 \Lambda^3}{2048} 
+ \frac{2663129 \nu^4 \Lambda^4}{262144} 
+ O(\Lambda^5)
\right)
\end{equation}
as $t \to - \infty$.
This asymptotic behavior is obtained when choosing $a = 1/\sqrt{6}$ 
and $\sqrt{3a} = (3/2)^{1/4}$ in \eqref{eq:scaling-data}, where we have $\Lambda = 4/(3s)$ 
with $s = 24^{1/4}(-t)^{5/4}$. 
Let us consider this choice in what follows. 
% \footnote{ 
% We note that, in this case, the other (expected) Borel singularity $\oint_A y dx = 2 \pi i \nu$ does not line on the integration contour in \eqref{eq:Borel-sum}, and hence, we can investigate the contribution of the $B$-period only.This means that our parameter $(t,\nu)$ doesn't lie on the wall of marginal stability.
% } 
% Below, we will see that the situation is realized by choosing $a = 1/\sqrt{6}$ in the rescaling \eqref{}; see Remark \ref{rem:choice-of-cycle-and-branch}.

In this situation, the Borel sum is expected to be ill-defined 
since the Borel singularities $n \phi(t,\nu)$ lies 
on the integration contour in \eqref{eq:Borel-sum}.  
In such a case, one can consider the lateral Borel summation ${\mathcal S}_{\pm}$ 
which assigns the same Laplace integral \eqref{eq:Borel-sum} but the path of integration 
is rotated by angle $\pm \epsilon$ with a sufficiently small $\epsilon > 0$. 
These lateral Borel sums ${\mathcal S}_{+}F$ and ${\mathcal S}_{-}F$ differ 
by exponentially small terms due to the Borel singularities on the positive real axis, 
and this is understood as the Stokes phenomenon.

Now we can formulate the conjecture of \cite{IM24}. 
It reads the following explicit formula for the action of the Stokes automorphism 
${\mathfrak S}$ $(= ``{\mathcal S}_{-}^{-1} \circ {\mathcal S}_{+}")$ 
on the partition function associated with the Borel singularity \eqref{eq:Borel-B-period}: 
\begin{equation} \label{eq:Stokes-rel}
{\mathfrak S}F(t,\nu;\hbar) = \sum_{n=0}^{\infty} F^{(n)}(t,\nu;\hbar), 
\end{equation}
where the right hand side is 
% the lateral Borel sum of the trans-series $\sum_{k=0}^{\infty} F^{(k)}(t,\nu;\hbar)$, which is 
obtained through the action of the following differential-difference operator with respect to $\nu$: 
\begin{equation} \label{eq:trans-series}
\exp\left( \sum_{n=0}^{\infty} F^{(n)}(t,\nu;\hbar) \right) 
= \exp\left( \frac{1}{2 \pi i} {\rm Li}_2 (e^{- \hbar \partial_\nu})  
- \frac{\hbar \partial_\nu}{2 \pi i} \log(1 - e^{- \hbar \partial_\nu})  \right) Z(t,\nu; \hbar). % e^{F(t,\nu; \hbar)}.
\end{equation}
The formal series $F^{(n)}$ is called the $n$-instanton amplitude.  
$F^{(0)}$ is identical to the original free energy $F$, 
and the 1-instanton amplitude is explicitly given as follows
(which was conjectured earlier in \cite{gm22}):  
\begin{equation} \label{eq:1-inst}
F^{(1)}(t, \nu;\hbar) 
= \frac{1}{2 \pi i} \left( 1 + \hbar
\frac{\partial F}{\partial \nu}(t, \nu - \hbar; \hbar) \right) 
\exp\Bigl(  F(t,\nu - \hbar; \hbar) - F(t,\nu; \hbar) \Bigr).
% \exp\left( F(t,\nu - k\hbar; \hbar) - F(t,\nu; \hbar) \right).
\end{equation}
% This is consistent with the conjecture of \cite{gm-multi}. 
The variation formula $\partial_\nu F_0 = \phi$
% \begin{equation}
% \frac{\partial F_0}{\partial \nu}(t,\nu) = \phi(t,\nu),
% \end{equation}
% which is also known as the Seiberg--Witten relation, 
implies that the right hand side of \eqref{eq:1-inst} is a formal power series with the exponential factor $e^{- \phi(t,\nu)/\hbar}$. 
This makes the right hand side of \eqref{eq:trans-series} a well-defined trans-series. 


\subsection{Non-linear Stokes phenomenon for tri-tronque\'e solution of P$_{\rm I}$} 

Finally, let us compare the formula \eqref{eq:1-inst} with the known results of Stokes phenomenon 
for the $0$-parameter solution of P$_{\rm I}$. 
The behavior of the solutions of P$_{\rm I}$ that exhibit Stokes phenomena on 
the negative real axis of the $t$-plane is discussed, for instance in \cite{Kapaev2004}, 
where the exponentially small terms arising from the Stokes phenomena are explicitly described. 
% For comparison with this result, unlike in Section \ref{subsec:rescale}, we need the asymptotic behavior of the partition function and tau function for the topological recursion, where $a = 1/\sqrt{6}$ is chosen in \eqref{eq:scaling-data}. 
% Actually, for the period given by \eqref{eq:Borel-B-period} to be a negative real number, $a$ must be chosen in this manner.
% The calculation of the series expansion of TR quantities proceeds in a manner completely parallel to that in Section \ref{subsec:TR-expansion}.


As we have seen in \S \ref{subsec_warmup}, the $0$-parameter solution $q(t;\hbar)$ 
is obtained from TR free energy $F^{\rm deg}(t;\hbar)$ of the degenerate elliptic curve ${\mathcal C}_{\rm deg}$
by taking $t$-derivative. 
On the other hand, \eqref{eq:Fgdeg-as-subleading} implies that the Borel sum of the $0$-parameter solution 
can be obtained as
% \footnote{
% We note that, although $F_g$ contains a term $\kappa_g/\nu^{2g-2}$ which is singular at $\nu = 0$, 
% it disappears after differentiation by $t$.
% This singularity is further explained in Remark \ref{rem:limit-nu-0}.} 
\begin{equation} \label{eq:stokes-auto-PIsol}
{\mathcal S}_{\pm}q(t;\hbar) 
= {\mathcal S}_{\pm} \left[ - \hbar^2 \frac{d^2}{dt^2} F^{\rm deg}(t;\hbar) \right]
= \lim_{\nu \to +0} {\mathcal S}_{\pm} \left[ - \hbar^2 \frac{d^2}{dt^2} F(t,\nu; \hbar) \right]% \Biggl|_{\nu \to +0}
\end{equation}
Therefore, the difference of ${\mathcal S}_{\pm}q(t;\hbar)$, 
or the action of Stokes automorphism on the 0-parameter solution, 
should be obtained from \eqref{eq:Stokes-rel} by taking $t$-derivative and setting $\nu \to +0$. 


Here, it is important to note that due to the conifold gap property \eqref{conigap} 
(or \eqref{eq:expansion-Fg}), 
the evaluation $\nu = 0$ cannot be made at the level of the formal series. 
The constant term $\kappa_{g}/ \nu^{2g-2}$ of $F_g$ has singularities at $\nu=0$, 
but these singularities are resolved by taking the Borel sum. 
In fact, the following equation holds (cf. \eqref{BarnesGas}):
\begin{equation}
{\mathcal S} \left( \sum_{g \ge 2} \hbar^{2g-2} \frac{B_{2g}}{4g(g-1) \nu^{2g-2}} \right) 
=  \log G\left( 1 + \frac{\nu}{\hbar} \right) 
- \Bigl(\frac{\nu^2}{2 \hbar^2} - \frac{1}{12} \Bigr) \log \frac{\nu}{\hbar}
+ \frac{3\nu^2}{4\hbar^2}
- \frac{\nu}{2 \hbar} \log 2\pi
- \frac{1}{12} + \log A.
\end{equation}
where $A$ is the Glaisher's constant.
This is valid at when $|\arg \nu| < \pi$, and hence, 
the formula is valid for our current situation $\nu \in {\mathbb R}_{>0}$.
Using this expression, we can verify that the aforementioned singularity at $\nu=0$ cancels with the other terms, 
and we can evaluate the behavior of \eqref{eq:trans-series} at $\nu \to +0$. 
The resulting formula takes the form
\begin{equation}
{\mathfrak S}q(t;\hbar) = \sum_{k \ge 0} q^{(k)}(t; \hbar), % e^{k \phi_0 /\hbar}
\end{equation}
% where $q^{(k)}(t;\hbar)$ is a formal power series of $\hbar$ with an overall exponential factor 
% $e^{- k \phi_0(t)/\hbar}$ with
% \begin{equation} \label{eq:phi0}
% \phi_0(t) = \frac{16 }{15 \Lambda} ~ \left(= \lim_{\nu \to 0} \phi(t,\nu) \right).
% \end{equation}
where the series $q^{(0)}(t;\hbar)$ is identical to the original 0-parameter solution $q(t;\hbar)$, 
and \eqref{eq:1-inst}--\eqref{eq:stokes-auto-PIsol} implies that the 1-instanton amplitude $q^{(1)}$ reads
\begin{equation} \label{eq:quasi-linear-Stokes-PI}
q^{(1)}(t;\hbar) = \exp\left( - \frac{2^{{11}/{4}} \, 3^{{1}/{4}} }{5 \hbar}(-t)^{{5}/{4}} \right)
\frac{i \hbar^{1/2}}{\pi^{1/2}} \,2^{-11/8} \, 3^{-1/8}\, (-t)^{- {1}/{8}} 
\Bigl( 1 + O(\Lambda) \Bigr).
\end{equation}
Here we have used the series expansion \eqref{eq:expansion-Fg} (and explicit values of some of $F_{g}^{[k]}$)
to compute the asymptotic behavior.
A remarkable observation here is that, the leading term of 
the right hand side of \eqref{eq:quasi-linear-Stokes-PI} 
precisely agrees with the connection formula of the tritronqu\'ee solutions of \PIeq 
(e.g., \cite[eq. (2.67)]{Kapaev2004}), which was found in 
\cite{Kapaev88, JK1992, Takei, CCH15} etc. by various methods.
We can also verify that the next few terms also agree with 
series expansion of trans-series solution of \PIeq which can be found in \cite{GIKM12} for example. 
%Our derivation based on the conjectural formula \eqref{eq:trans-series}  recovers the same formula, at least in first few terms. 
This fact supports the validity of conjectures of \cite{gm22, IM24}.

The Stokes phenomenon for the general solution of P$_{\rm I}$, 
which has a representation different from the Fourier series type discussed in this paper, 
is addressed in \cite{BSSV23, Takei2000}. 
The connection formula is derived by using the fact that P$_{\rm I}$ describes isomonodromic deformations. 
Since the conjectured formula \eqref{eq:trans-series} above is also a consequence of monodromy invariance, 
we expect that performing an analysis similar to the one conducted here for general values of 
$\nu$ and $\rho$ could lead to the derivation of results such as \cite[(7.73)]{BSSV23}.







