\begin{definition}
Let $(X,F)$ be a CR-dynamical system. We say that $(X,F)$ has
\begin{enumerate}
	\item \emph{the specification property} (or $\mathcal{SP}$) if for each $\varepsilon >0$, there is a positive integer $N$ such that for any $N$-spaced specification $\mathcal S$ in $(X,F)$, there is $y\in X$ such that $\mathcal S$ is $\varepsilon$-traced in $(X,F)$ by $y$.
\item \emph{the Hausdorff specification property} (or $\mathcal{HSP}$) if for each $\varepsilon >0$, there is a positive integer $N$ such that for any $N$-spaced specification $\mathcal S$ in $(X,F)$, there is $y\in X$ such that $\mathcal S$ is Hausdorff  $\varepsilon$-traced in $(X,F)$ by $y$.
%	\item   strong specification property (or $\mathcal{SSP}$) if for each $\varepsilon >0$, there is a positive integer $N$ such that for any $N$-spaced strong specification $\mathbf S$ in $(X,F)$, there is $y\in X$ such that $\mathbf S$ is $\varepsilon$-traced in $(X,F)$ by $y$.
%\item strong Hausdorff  specification property (or $\mathcal{SHSP}$) if for each $\varepsilon >0$, there is a positive integer $N$ such that for any $N$-spaced strong specification $\mathbf S$ in $(X,F)$, there is $y\in X$ such that $\mathbf S$ is Hausdorff  $\varepsilon$-traced in $(X,F)$ by $y$.
%\item   weak specification property (or $\mathcal{WSP}$) if for each $\varepsilon >0$, there is a positive integer $N$ such that for any $N$-spaced weak specification $\mathbf W$ in $(X,F)$, there is $y\in X$ such that $\mathbf W$ is $\varepsilon$-traced in $(X,F)$ by $y$.
%\item weak Hausdorff  specification property (or $\mathcal{WHSP}$) if for each $\varepsilon >0$, there is a positive integer $N$ such that for any $N$-spaced weak specification $\mathbf W$ in $(X,F)$, there is $y\in X$ such that $\mathbf W$ is Hausdorff  $\varepsilon$-traced in $(X,F)$ by $y$.
\end{enumerate} 
\end{definition}
\begin{observation}
	Note that if $(X,F)$ is a CR-dynamical system such that for some $x_0\in X$, 
	$$
	X\times \{x_0\}\subseteq F,
	$$
	Then for any $x,y\in X$, $d(F(x),F(y))=0$, and, therefore, $(X,F)$ has the specification property.
\end{observation}
\begin{theorem}\label{klavz}
	Let $\mathcal P\in \{\mathcal{SP},\mathcal{HSP}\}$. Then the following hold.
	\begin{enumerate}
		\item $\mathcal P$ is a CR-dynamical property that generalizes the specification property.
		\item For any dynamical system $(X,f)$, 
		$$
		(X,f) \textup{ has the specification property } ~~~ \Longrightarrow ~~~ (X,f) \textup{ has } \textup{Power}(\mathcal P).    
		$$ 
	\end{enumerate}
\end{theorem}
\begin{proof}
	 First, we prove that $\mathcal P$ is a CR-dynamical property that generalizes the specification property. To see that $\mathcal P$ is a CR-dynamical property, let $(X,F)$ and $(Y,G)$ be CR-dynamical systems that are topologically conjugate and let $\varphi:X\rightarrow Y$ be a homeomorphism such that for each $(x,y)\in X\times X$, the following holds
 $$
 (x,y)\in F  \Longleftrightarrow (\varphi(x), \varphi(y))\in G.
 $$
Let $d_X$ be the metric on $X$ and $d_Y$ the metric on $Y$ and suppose that $(X,F)$ has property $\mathcal P$. We prove  that $(Y,G)$ has property $\mathcal P$ by considering the following cases. 
	\begin{enumerate}
		\item $\mathcal P=\mathcal{SP}$.  We show that for each $\varepsilon >0$, there is a positive integer $N$ such that for any $N$-spaced specification $\mathcal S$ in $(Y,G)$, there is $y\in Y$ such that $\mathcal S$ is $\varepsilon$-traced in $(Y,G)$ by $y$. Let $\varepsilon >0$ and let $\delta>0$ be such that for all $x_1,x_2\in X$,
$$
d_X(x_1,x_2)<\delta ~~~ \Longrightarrow ~~~ d_Y(\varphi(x_1),\varphi(x_2))<\varepsilon.
$$ 
Since $(X,F)$ has property $\mathcal P$, there is a positive integer $N$ such that for any $N$-spaced specification $\mathcal S$ in $(X,F)$, there is $x\in X$ such that $\mathcal S$ is $\frac{\delta}{2}$-traced in $(X,F)$ by $x$. Choose and fix such a positive integer $N$ and let 
$$
\mathcal S=\Bigg(G^{[k_1,\ell_1]}(y_1),G^{[k_2,\ell_2]}(y_2),G^{[k_3,\ell_3]}(y_3),\ldots ,G^{[k_n,\ell_n]}(y_n)\Bigg)
$$
 be an $N$-spaced specification in $(Y,G)$.  Then 
 $$
\mathcal C=\Bigg(F^{[k_1,\ell_1]}(\varphi^{-1}(y_1)),F^{[k_2,\ell_2]}(\varphi^{-1}(y_2)),F^{[k_3,\ell_3]}(\varphi^{-1}(y_3)),\ldots ,F^{[k_n,\ell_n]}(\varphi^{-1}(y_n))\Bigg)
$$
 is an $N$-spaced specification in $(X,F)$. Let $x$ be such that $\mathcal C$ is $\frac{\delta}{2}$-traced in $(X,F)$ by $x$ and let $y=\varphi(x)$. To prove that $\mathcal S$ is $\varepsilon$-traced in $(Y,G)$ by $y$, let $i\in \{1,2,3,\ldots,n\}$ and let $j\in \{k_i,k_i+1,k_i+2,\ldots,\ell_i\}$. We prove that $d_Y(G^j(y),G^j(y_i))\leq \varepsilon$. First, note that 
 $d_X(F^j(x),F^j(\varphi^{-1}(y_i)))\leq\frac{\delta}{2}$. Let $t_1\in F^j(x)$ and let $t_2\in F^j(\varphi^{-1}(y_i))$ be such that $d_X(t_1,t_2)\leq \frac{\delta}{2}$. Then $\varphi(t_1)\in \varphi(F^j(x))$ and $\varphi(t_2)\in \varphi(F^j(\varphi^{-1}(y_i)))$.   By Theorem \ref{dekanicaMaja}, $\varphi(t_1)\in G^j(\varphi(x))$ and $\varphi(t_2)\in G^j(\varphi(\varphi^{-1}(y_i)))$. Note that $G^j(\varphi(x))=G^j(y)$, that $G^j(\varphi(\varphi^{-1}(y_i)))=G^j(y_i)$, and that  $d_Y(\varphi(t_1),\varphi(t_2))<\varepsilon$. Therefore, 
 $$
 d_Y(G^j(y),G^j(y_i))\leq \varepsilon.
 $$ 
 This proves that $\mathcal P$ is a CR-dynamical property. It follows from the definition of property $\mathcal{SP}$ that $\mathcal P$ generalizes the specification property.
 \item $\mathcal P=\mathcal{HSP}$.  We show  that for each $\varepsilon >0$, there is a positive integer $N$ such that for any $N$-spaced specification $\mathcal S$ in $(Y,G)$, there is $y\in Y$ such that $\mathcal S$ is Hausdorff $\varepsilon$-traced in $(Y,G)$ by $y$. Let $\varepsilon >0$ and let $\delta>0$ be such that for all $x_1,x_2\in X$,
$$
d_X(x_1,x_2)<\delta ~~~ \Longrightarrow ~~~ d_Y(\varphi(x_1),\varphi(x_2))<\varepsilon.
$$ 
Since $(X,F)$ has property $\mathcal P$, there is a positive integer $N$ such that for any $N$-spaced specification $\mathcal S$ in $(X,F)$, there is $x\in X$ such that $\mathcal S$ is Hausdorff $\frac{\delta}{2}$-traced in $(X,F)$ by $x$. Choose and fix such a positive integer $N$ and let 
$$
\mathcal S=\Bigg(G^{[k_1,\ell_1]}(y_1),G^{[k_2,\ell_2]}(y_2),G^{[k_3,\ell_3]}(y_3),\ldots ,G^{[k_n,\ell_n]}(y_n)\Bigg)
$$
 be an $N$-spaced specification in $(Y,G)$.  Then 
 $$
\mathcal C=\Bigg(F^{[k_1,\ell_1]}(\varphi^{-1}(y_1)),F^{[k_2,\ell_2]}(\varphi^{-1}(y_2)),F^{[k_3,\ell_3]}(\varphi^{-1}(y_3)),\ldots ,F^{[k_n,\ell_n]}(\varphi^{-1}(y_n))\Bigg)
$$
 is an $N$-spaced specification in $(X,F)$. Let $x$ be such that $\mathcal C$ is Hausdorff $\frac{\delta}{2}$-traced in $(X,F)$ by $x$ and let $y=\varphi(x)$. To prove that $\mathcal S$ is Hausdorff $\varepsilon$-traced in $(Y,G)$ by $y$, let $i\in \{1,2,3,\ldots,n\}$ and let $j\in \{k_i,k_i+1,k_i+2,\ldots,\ell_i\}$. We prove that $H_{d_Y}(G^j(y),G^j(y_i))\leq \varepsilon$ by showing that 
 \begin{enumerate}
 \item for each $z\in G^j(y)$, there is $w\in G^j(y_i)$ such that $d_Y(z,w)\leq \varepsilon$, and 
 \item for each $z\in G^j(y_i)$, there is $w\in G^j(y)$ such that $d_Y(z,w)\leq \varepsilon$. 
 \end{enumerate} 
 First, let $z\in G^j(y)$. Then  $\varphi^{-1}(z)\in \varphi^{-1}(G^j(y))$ and, and it follows from  Theorem \ref{tehnika} that $\varphi^{-1}(G^j(y))\subseteq F^j(\varphi^{-1}(y))$. Therefore, $\varphi^{-1}(z)\in F^j(x)$. Since $H_{d_X}(F^j(x),F^j(\varphi^{-1}(y_i)))\leq\frac{\delta}{2}$, it follows that there is $t\in F^j(\varphi^{-1}(y_i))$ such that $d_X(\varphi^{-1}(z),t)<\frac{\delta}{2}$. Choose and fix such a point $t$ and let $w=\varphi(t)$. Therefore,  $d_y(z,w)<\varepsilon$.  

 Next, let $z\in G^j(y_i)$. Then  $\varphi^{-1}(z)\in \varphi^{-1}(G^j(y_i))$ and, it follows from Theorem \ref{tehnika} that $\varphi^{-1}(G^j(y_i))\subseteq F^j(\varphi^{-1}(y_i))$. Therefore, $\varphi^{-1}(z)\in F^j(\varphi^{-1}(y_i))$. Again, it follows that there is $t\in F^j(x)$ such that $d_X(\varphi^{-1}(z),t)<\frac{\delta}{2}$. Choose and fix such a point $t$ and let $w=\varphi(t)$. Therefore,  $d_y(z,w)<\varepsilon$.  This proves that  $H_{d_Y}(G^j(y),G^j(y_i))\leq \varepsilon$ and, therefore, $\mathcal P$ is a CR-dynamical property. It follows from the definition of property $\mathcal{HSP}$ that $\mathcal P$ generalizes the specification property.
