		Let $(X,f)$ be a dynamical system and suppose that $(X,f)$ has the specification property. We show that $(X,f)$ has the property $\textup{Power}(\mathcal P)$ by showing that there is a CR-dynamical system $(Z,F)$ such that 
		\begin{enumerate}
		\item $(Z,F)$ has property $\mathcal P$, and
		\item $(X,f)$ and $(Z_F^+,\sigma_F^+)$ are topological conjugates.
		\end{enumerate}
		Let $(Z,F)=(X,f)$. Note that $(Z,F)$ has property $\mathcal P$. Also, let $\varphi:X\rightarrow Z_F^+$ be defined by
		$$
		\varphi(x)=(x,f(x),f^2(x),f^3(x),\ldots)
		$$
		for each $x\in X$.  Then $\varphi\circ f=\sigma_F^+\circ \varphi$ and it follows that $(X,f)$ and $(Z_F^+,\sigma_F^+)$ are topological conjugates. 
		\end{proof}
		\begin{observation}
		Let $\mathcal P\in \{\mathcal{SP},\mathcal{HSP}\}$. Note that for any dynamical system $(X,f)$, where $f$ is a homeomorphism, 
		$$
		(X,f) \textup{ has the specification property } ~~~ \Longrightarrow ~~~ (X,f) \textup{ has } \textup{FPower}(\mathcal P).    
		$$ 
		\end{observation}

		\begin{theorem}\label{Hausdorff}
	Let $(X,F)$ be a CR-dynamical system. If $(X,F)$ has the Hausdorff specification property, then $(X,F)$ has the specification property.
\end{theorem}
\begin{proof}
	Suppose that $(X,F)$ has the Hausdorff specification property. To prove that $(X,F)$ has the specification property, let $\varepsilon >0$ and let $N$ be a positive integer such that for any specification in $(X,F)$, there is a point $y\in X$ such that $\mathcal S$ is Hausdorff $\varepsilon$-traced in $(X,F)$ by $y$. We prove that for any $N$-spaced  specification $\mathcal S$ in $(X,F)$, there is $y\in X$ such that $\mathcal S$ is $\varepsilon$-traced in $(X,F)$ by $y$. To do so, let 
$$
	\mathcal S=\Big((x_{k_1}^{1},x_{k_1+1}^{1},x_{k_1+2}^{1},\ldots,x_{\ell_1}^{1}),\ldots ,(x_{k_n}^{n},x_{k_n+1}^{n},x_{k_n+2}^{n},\ldots,x_{\ell_n}^{n})\Big)
	$$
	 be an $N$-spaced specification in $(X,F)$ and let $y\in X$ be such that $\mathcal S$ is Hausdorff $\varepsilon$-traced in $(X,F)$ by $y$. To see that $\mathcal S$ is $\varepsilon$-traced in $(X,F)$ by $y$, let $i\in \{1,2,3,\ldots,n\}$ and let $j\in \{k_i,k_i+1,k_i+2,\ldots,\ell_i\}$. Then 
$$
d(F^j(y),F^j(x_i))\leq H_d(F^j(y),F^j(x_i))\leq \varepsilon.
$$
\end{proof}

		\begin{corollary}
		Let $(X,f)$ be a dynamical system.	Note that
		\begin{enumerate}
			\item if $(X,f)$ has $\textup{Power}(\mathcal{HSP})$, then $(X,f)$ has $\textup{Power}(\mathcal{SP})$.
			\item if $(X,f)$ has $\textup{FPower}(\mathcal{HSP})$, then $(X,f)$ has $\textup{FPower}(\mathcal{SP})$.
			%\item if $(X,f)$ has $\textup{(F)Power}(\mathcal{SHSP})$, then $(X,f)$ has $\textup{(F)Power}(\mathcal{SSP})$.
			%\item if $(X,f)$ has $\textup{(F)Power}(\mathcal{WHSP})$, then $(X,f)$ has $\textup{(F)Power}(\mathcal{WSP})$.
			%\item if $(X,f)$ has $\textup{(F)Power}(\mathcal{WSP})$, then $(X,f)$ has $\textup{(F)Power}(\mathcal{SSP})$.
			%\item if $(X,f)$ has $\textup{(F)Power}(\mathcal{SSP})$, then $(X,f)$ has $\textup{(F)Power}(\mathcal{SP})$.
			%\item if $(X,f)$ has $\textup{(F)Power}(\mathcal{WHSP})$, then $(X,f)$ has $\textup{(F)Power}(\mathcal{SHSP})$.
			%\item if $(X,f)$ has $\textup{(F)Power}(\mathcal{SHSP})$, then $(X,f)$ has $\textup{(F)Power}(\mathcal{HSP})$.
		\end{enumerate} 
		\end{corollary}
		\begin{proof}
			The corollary follows directly from Theorem \ref{Hausdorff}.
		\end{proof}

In the following example, we give a CR-dynamical system $(X,F)$ that has the specification property but does not have the Hausdorff specification property.	
	\begin{example}\label{monica}
		Let $X = [0,1]$ and let
$$
F = \left( \left[0, \frac{1}{2} \right] \times \{0\} \right) \cup \left( \left[ \frac{1}{2}, 1 \right] \times \{1\} \right) \cup (\{1\} \times [0,1]).
$$   
To prove that $(X,F)$ has   the specification property, let $\varepsilon>0$. Next, let $N=5$, let  
	$$
	\mathcal S=\Bigg(F^{[k_1,\ell_1]}(x_1),F^{[k_2,\ell_2]}(x_2),F^{[k_3,\ell_3]}(x_3),\ldots ,F^{[k_n,\ell_n]}(x_n)\Bigg)
	$$
	 be a specification in $(X,F)$, and let $y=x_1$. To see that $\mathcal S$ is $\varepsilon$-traced in $(X,F)$ by $y$, let $i\in \{1,2,3,\ldots,n\}$ and let $j\in \{k_i,k_i+1,k_i+2,\ldots,\ell_i\}$. We consider the following possible cases. 
	 \begin{enumerate}
	 	\item $j<4$. Then $j\in \{k_1,k_1+1,k_1+2,\ldots,\ell_1\}$ and it follows that $i=1$. Therefore, 
$$
d(F^j(y),F^j(x_i))=d(F^j(y),F^j(x_1))=d(F^j(x_1),F^j(x_1))=0\leq \varepsilon.
$$
\item $j\geq 4$. Then $F^j(y),F^j(x_i)\in \{\{0\},[0,1]\}$ and, therefore, 
$$
d(F^j(y),F^j(x_i))=0\leq \varepsilon.
$$
	 \end{enumerate}

Next we show that $(X,F)$ does not have the Hausdorff specification property.
Let $\varepsilon=\frac{1}{4}$ and let $N$ be any positive integer. Take the 2-specification 
$$
\mathcal S= \left( F^{[k_1,\ell_1]} (0), F^{[k_2,\ell_2]}(1) \right)
$$
 where $k_1>1$ and $k_2 - \ell_1 \geq N$. Note that $F^k(0)=\{ 0\}$ for all $k\in \mathbb N$ and $F^{\ell}(1)=[0,1]$ for all $\ell \in \mathbb N$. Let $y\in X$ be any point. We show that $\mathcal S$ is not $\varepsilon$-traced in $(X,F)$ by $y$.
We consider the following two possible cases:
\begin{enumerate}
    \item $y\in[0,\frac{1}{2})$. For all $j \in \{ k_2,k_2+1,\ldots,\ell_2\}$ we have 
    $$
    H_d(F^j(y),F^j(1))=H_d(\{0\},[0,1])=1\nleq \varepsilon.
    $$
    \item $y\in[\frac{1}{2},1].$ For all $j \in \{ k_1,k_1+1,\ldots,\ell_1\}$ we have
    $$
    H_d(F^j(y),F^j(0))=H_d([0,1], \{0\})=1\nleq \varepsilon.
    $$
\end{enumerate}
	\end{example}	


\section{Initial-specification-type properties for Mahavier dynamical systems}\label{s3}
In this section, we generalize the initial specification property from topological dynamical systems to CR-dynamical systems. Then we study dynamical systems that are (fully) powered by these properties.

\begin{definition}
	Let $(X,F)$ be a CR-dynamical system, let $x\in X$, and let $\ell$ be a non-negative integer.  We say that $F^{[0,\ell]}(x)$ is \emph{an initial $\ell$-orbit segment of the point $x$}. 
\end{definition}
\begin{definition}
	Let $(X,F)$ be a CR-dynamical system, let $n$ be a positive integer, and for each $j\in \{1,2,3,\ldots,n\}$, let
	\begin{enumerate}
		\item $\ell_j$ be non-negative integers,
		\item $x_j\in X$. 
	\end{enumerate}
	We say that the $n$-tuple
	$$
	\Bigg(F^{[0,\ell_1]}(x_1),F^{[0,\ell_2]}(x_2),F^{[0,\ell_3]}(x_3),\ldots,F^{[0,\ell_n]}(x_n)\Bigg)
	$$
	 is \emph{an initial $n$-specification} or just \emph{an initial specification in $(X,F)$}.
	\end{definition}

\begin{definition}
	Let $(X,F)$ be a CR-dynamical system, let $d$ be the metric on $X$, let $H_d$ be the Hausdorff metric on $2^X$, let $n$ be a positive integer, let $m_1,m_2,m_3\ldots,m_{n-1}$ be positive integers, let $\varepsilon>0$, let $y\in X$, and let 
	$$
	\mathcal S=\Bigg(F^{[0,\ell_1]}(x_1),F^{[0,\ell_2]}(x_2),F^{[0,\ell_3]}(x_3),\ldots ,F^{[0,\ell_n]}(x_n)\Bigg)
	$$
	be an initial specification in $(X,F)$. We say that
	\begin{enumerate}
		\item the initial specification $\mathcal S$ is \emph{$\left(\varepsilon,m_1,m_2,m_3,\ldots,m_{n-1}\right)$-traced in $(X,F)$ by $y$} if for each $i\in \{1,2,3,\ldots,n\}$ and for each $j\in \{0,1,2,\ldots,\ell_i\}$,
		$$
		d(F^{\ell_1+m_1+\ell_2+m_2+\ell_3+m_3+\cdots+\ell_{i-1}+m_{i-1}+j}\left(y\right),F^j\left(x_i\right))\leq \varepsilon.
		$$
		\item the initial specification $\mathcal S$ \emph{is Hausdorff  $\left(\varepsilon,m_1,m_2,m_3,\ldots,m_{n-1}\right)$-traced in $(X,F)$ by $y$} if for each $i\in \{1,2,3,\ldots,n\}$ and for each $j\in \{0,1,2,\ldots,\ell_i\}$,
		$$
		H_d(F^{\ell_1+m_1+\ell_2+m_2+\ell_3+m_3+\cdots+\ell_{i-1}+m_{i-1}+j}\left(y\right),F^j\left(x_i\right))\leq \varepsilon.
		$$
	\end{enumerate} 
\end{definition}
