		 \begin{enumerate}
			\item for each positive integer $n$
			\item for all positive integers $m_1,m_2,m_3,\ldots,m_{n-1}$ such that for each $i\in\left\lbrace 1,2,\ldots,n-1\right\rbrace$, $m_i\geq N$, 		
\end{enumerate} 
		and for any initial specification $\mathcal S$ in $(X,F)$ there is $y\in X$ such that $\mathcal S$ is Hausdorff  $\left(\varepsilon,m_1,m_2,m_3,\dots,m_{n-1}\right)$-traced in $(X,F)$ by $y$.
