\begin{theorem}\label{klavz1}
	Let $\mathcal P\in \{\mathcal{ISP},\mathcal{HISP}\}$. Then the following holds.
	\begin{enumerate}
		\item $\mathcal P$ is a CR-dynamical property that generalizes the initial specification property.
		\item For any dynamical system $(X,f)$, 
		$$
		(X,f) \textup{ has the initial specification property } ~~~ \Longrightarrow ~~~ (X,f) \textup{ has } \textup{Power}(\mathcal P).    
		$$ 
	\end{enumerate}
\end{theorem}
\begin{proof}
The proof of this theorem is analogous to the proof of Theorem \ref{klavz}. We leave the details to the reader.
\end{proof}
\begin{observation}
		Let $\mathcal P\in \{\mathcal{ISP},\mathcal{HISP}\}$. Note that for any dynamical system $(X,f)$, where $f$ is a homeomorphism, 
		$$
		(X,f) \textup{ has the initial specification property } ~~~ \Longrightarrow ~~~ (X,f) \textup{ has } \textup{FPower}(\mathcal P).    
		$$ 
		\end{observation}

		\begin{theorem}\label{Hausdorfff}
	Let $(X,F)$ be a CR-dynamical system. If $(X,F)$ has the Hausdorff initial specification property, then $(X,F)$ has the initial specification property.
\end{theorem}
\begin{proof}
	Suppose that $(X,F)$ has the Hausdorff initial specification property. To prove that $(X,F)$ has the initial specification property, let $\varepsilon>0$ and let $N$ be a positive integer such that for each positive integer $n$, for all positive integers $m_1,m_2,m_3,\ldots,m_{n-1}$ such that for each $i\in \{1,2,3,\ldots,n\}$, $m_i\geq N$, and for each initial $n$-specification $\mathcal S$ in $(X,F)$, there is $y\in X$ such that $\mathcal S$ is Hausdorff $(\varepsilon,m_1,m_2,m_3,\ldots,m_{n-1})$-traced in $(X,F)$ by $y$. We prove that for each positive integer $n$, for all positive integers $m_1,m_2,m_3,\ldots,m_{n-1}$ such that for each $i\in \{1,2,3,\ldots,n\}$, $m_i\geq N$, and for each initial $n$-specification $\mathcal S$, there is $y\in X$ such that $\mathcal S$ is $(\varepsilon,m_1,m_2,m_3,\ldots,m_{n-1})$-traced in $(X,F)$ by $y$.  So, let $n$ be a positive integer, let $m_1,m_2,m_3,\ldots,m_{n-1}$ be positive integers such that for each $i\in \{1,2,3,\ldots,n\}$, $m_i\geq N$, and let 
$$
	\mathcal S=\Big((x_{0}^{1},x_{1}^{1},x_{2}^{1},\ldots,x_{\ell_1}^{1}),\ldots ,(x_{0}^{n},x_{1}^{n},x_{2}^{n},\ldots,x_{\ell_n}^{n})\Big)
	$$
	 be an initial specification in $(X,F)$. Also, let $y\in X$ be such that $\mathcal S$ is Hausdorff $(\varepsilon,m_1,m_2,m_3,\ldots,m_{n-1})$-traced in $(X,F)$ by $y$. We show that the initial specification $\mathcal S$ is $(\varepsilon,m_1,m_2,m_3,\ldots,m_{n-1})$-traced in $(X,F)$ by $y$. To do so, let $i\in \{1,2,3,\ldots,n\}$ and let $j\in \{0,1,2,\ldots,\ell_i\}$. Then 
\begin{align*}
	&d(F^{\ell_1+m_1+\ell_2+m_2+\ell_3+m_3+\cdots+\ell_{i-1}+m_{i-1}+j}\left(y\right),F^j\left(x_i\right))\leq \\
	&H_d(F^{\ell_1+m_1+\ell_2+m_2+\ell_3+m_3+\cdots+\ell_{i-1}+m_{i-1}+j}\left(y\right),F^j\left(x_i\right))\leq \varepsilon.
\end{align*}
This completes the proof. 
\end{proof}

		\begin{corollary}
		Let $(X,f)$ be a dynamical system.	Note that
		\begin{enumerate}
			\item if $(X,f)$ has $\textup{Power}(\mathcal{HISP})$, then $(X,f)$ has $\textup{Power}(\mathcal{ISP})$.
			\item if $(X,f)$ has $\textup{FPower}(\mathcal{HISP})$, then $(X,f)$ has $\textup{FPower}(\mathcal{ISP})$.
			%\item if $(X,f)$ has $\textup{(F)Power}(\mathcal{SHSP})$, then $(X,f)$ has $\textup{(F)Power}(\mathcal{SSP})$.
