\section{Specification properties Versus initial specification properties}\label{s4}
In this section, we study relationships between specification properties ($\mathcal{SP}$ and $\mathcal{HSP}$) and corresponding initial specification properties ($\mathcal{ISP}$ and $\mathcal{HISP}$).
\subsection{$\mathcal{SP}$ Versus $\mathcal{ISP}$}
The following example shows that, in general, the   specification property is not equivalent to the   initial specification property. 
\begin{example}
	Let $X=[0,1]$ and let $F=[0,1]\times \{1\}$. To prove that $(X,F)$ has   the specification property, let $\varepsilon>0$. Then, let $N=1$, let  
	$$
	\mathcal S=\Bigg(F^{[k_1,\ell_1]}(x_1),F^{[k_2,\ell_2]}(x_2),F^{[k_3,\ell_3]}(x_3),\ldots ,F^{[k_n,\ell_n]}(x_n)\Bigg)
	$$
	 be an $N$-spaced specification in $(X,F)$, and let $y=x_1$. To see that $\mathcal S$ is $\varepsilon$-traced in $(X,F)$ by $y$, let $i\in \{1,2,3,\ldots,n\}$ and let $j\in \{k_i,k_i+1,k_i+2,\ldots,\ell_i\}$. We consider the following possible cases. 
	 \begin{enumerate}
	 	\item $j=0$. Then $j=k_1$ and it follows that  
$$
d(F^j(y),F^j(x_i))=d(F^{k_1}(x_1),F^{k_1}(x_1))=d(\{x_1\},\{x_1\})=0\leq \varepsilon.
$$
	 	\item $j\neq 0$. Then 
$$
d(F^j(y),F^j(x_i))=d(\{1\},\{1\})=0\leq \varepsilon.
$$
	 \end{enumerate}
Next, we show that $(X,F)$ does not have  the initial specification property. To see this, let $\varepsilon=\frac{1}{4}$ and let $N$ be any positive integer. Also, let $m_1$ be a positive integer such that $m_1\geq N$, and let $\mathcal S=\Bigg(F^{[0,1]}(1),F^{[0,1]}(0)\Bigg)$ be an initial $2$-specification in $(X,F)$. Note that in this case, $x_1=1$, $x_2=0$, and $\ell_1=\ell_2=1$. Finally, let $y\in X$ be any point. We show that $\mathcal S$ is not $(\varepsilon,m_1)$-traced in $(X,F)$ by $y$. We prove this by showing that it does not hold that for each $i\in \{1,2\}$ and for each $j\in \{0,1,2,\ldots,\ell_i\}$,
		$$
		d(F^{\ell_1+m_1+\ell_2+m_2+\ell_3+m_3+\cdots+\ell_{i-1}+m_{i-1}+j}\left(y\right),F^j\left(x_i\right))\leq \varepsilon.
		$$
Let $i=2$ and let $j=0$. Then 
\begin{align*}
		&d(F^{\ell_1+m_1+\ell_2+m_2+\ell_3+m_3+\cdots+\ell_{i-1}+m_{i-1}+j}\left(y\right),F^j\left(x_i\right))=\\
		&d(F^{\ell_1+m_1+j}\left(y\right),F^j\left(x_i\right))=d(F^{1+1+0}\left(y\right),F^0\left(0\right))=d(\{1\},\{0\})=1\not\leq \varepsilon.
\end{align*}
\end{example}

\begin{theorem}\label{prvi}
	Let $(X,F)$ be a CR-dynamical system. If there is a positive integer $n_0$ such that for all $x,y\in X$,   $F^{n_0}(x)\cap F^{n_0}(y)\neq \emptyset$, then $(X,F)$ has the specification property. 
\end{theorem}
\begin{proof}
	Let $n_0$ be a positive integer such that for all $x,y\in X$, $F^{n_0}(x)\cap F^{n_0}(y)\neq \emptyset$. Note that it follows that $p_1(X)=X$. To prove that $(X,F)$ has   the specification property, let $\varepsilon>0$. Next, let $N=n_0$, let  
	$$
	\mathcal S=\Bigg(F^{[k_1,\ell_1]}(x_1),F^{[k_2,\ell_2]}(x_2),F^{[k_3,\ell_3]}(x_3),\ldots ,F^{[k_n,\ell_n]}(x_n)\Bigg)
	$$
	 be an $N$-spaced specification in $(X,F)$, and let $y=x_1$. To see that $\mathcal S$ is $\varepsilon$-traced in $(X,F)$ by $y$, let $i\in \{1,2,3,\ldots,n\}$ and let $j\in \{k_i,k_i+1,k_i+2,\ldots,\ell_i\}$. We consider the following possible cases. 
	 \begin{enumerate}
	 	\item $j<N$. Then $j\in \{k_1,k_1+1,k_1+2,\ldots,\ell_1\}$ and it follows that $i=1$. Therefore, 
$$
d(F^j(y),F^j(x_i))=d(F^j(x_1),F^j(x_1))=0\leq \varepsilon.
$$
\item $j\geq N$. Then $F^j(y)\cap F^j(x_i)\neq \emptyset$ and, therefore, $d(F^j(y),F^j(x_i))=0\leq \varepsilon$.
	 \end{enumerate}
\end{proof}

\begin{theorem}\label{drugi}
	Let $(X,F)$ be a CR-dynamical system. If there is a positive integer $n_0$ such that for each $x\in X$,   $F^{n_0}(x)=X$, then $(X,F)$ has   the specification property as well as  the initial specification property. 
\end{theorem}
\begin{proof}
	It follows from Theorem \ref{prvi} that $(X,F)$ has   the specification property.
	 To prove that $(X,F)$ has  the initial specification property, let $\varepsilon>0$ and let $N=n_0$. Also, let $n$ be a positive integer, let $m_1,m_2,m_3,\ldots,m_{n-1}$ be positive integers such that for each $i\in \{1,2,3,\ldots ,n-1\}$, $m_i\geq N$, and let  
	$$
	\mathcal S=\Bigg(F^{[0,\ell_1]}(x_1),F^{[0,\ell_2]}(x_2),F^{[0,\ell_3]}(x_3),\ldots ,F^{[0,\ell_n]}(x_n)\Bigg)
	$$
	 be an initial specification in $(X,F)$, and let $y=x_1$. To see that the initial specification $\mathcal S$ is $(\varepsilon,m_1,m_2,m_3,\ldots,m_{n-1})$-traced in $(X,F)$ by $y$, let $i\in \{1,2,3,\ldots,n\}$ and let $j\in \{0,1,2,\ldots,\ell_i\}$. We consider the following possible cases. 
	 \begin{enumerate}
	 	\item $i=1$. Then $j\in \{0,1,2,\ldots,\ell_1\}$ and it follows that 
$$
		d(F^{\ell_1+m_1+\ell_2+m_2+\ell_3+m_3+\cdots+\ell_{i-1}+m_{i-1}+j}\left(y\right),F^j\left(x_i\right))=		d(F^{j}\left(x_1\right),F^j\left(x_1\right))\leq \varepsilon.
$$
\item $i>1$. Then $F^{\ell_1+m_1+\ell_2+m_2+\ell_3+m_3+\cdots+\ell_{i-1}+m_{i-1}+j}\left(y\right)=X$ (since $m_1\geq N=n_0$) and, therefore, 
$$
d(F^{\ell_1+m_1+\ell_2+m_2+\ell_3+m_3+\cdots+\ell_{i-1}+m_{i-1}+j}\left(y\right),F^j\left(x_i\right))=d(X,F^j\left(x_i\right))=0\leq \varepsilon
$$
since $F^j\left(x_i\right)$ is a non-empty subset of $X$. 
	 \end{enumerate}
\end{proof}
\begin{example}
	Let $X=[0,1]$ and let 
	$$
	F=\left(\left[0,\frac{1}{2}\right]\times \{0\}\right)\cup \left(\{0\}\times \left[0,\frac{1}{2}\right]\right)\cup \left(\left[\frac{1}{2},1\right]\times \{1\}\right)\cup\left(\{1\}\times \left[\frac{1}{2},1\right]\right).
	$$
	Then for each $x\in X$, $F^{4}(x)=X$. Therefore, by Theorem \ref{drugi}, $(X,F)$ has   the specification property as well as  the initial specification property. 
\end{example}
In the following example, we demonstrate that even if $p_1(F)=p_2(F)=X$, the    specification property and   the initial specification property may not be equivalent.
\begin{example}\label{ex3}
	Let $X=[0,1]$ and let 
	$$
	F=\left(\left[0,\frac{1}{2}\right]\times \{0\}\right)\cup \left(\left[\frac{1}{2},1\right]\times \{1\}\right)\cup\left(\{1\}\times \left[0,1\right]\right).
	$$
	 We already know that $(X,F)$ has   the specification property; see Example \ref{monica}. 
Next, we show that $(X,F)$ does not have  the initial specification property. To see this, let $\varepsilon=\frac{1}{8}$ and let $N$ be any positive integer. Also, let $m_1$ be a positive integer such that $m_1\geq N$, and let $\mathcal S=\Big(F^{[0,1]}(0),F^{[0,1]}(\frac{3}{4})\Big)$ be an initial $2$-specification in $(X,F)$. Note that in this case, $x_1=0$, $x_2=\frac{3}{4}$, and $\ell_1=\ell_2=1$. Finally, let $y\in X$ be any point. We show that $\mathcal S$ is not $(\varepsilon,m_1)$-traced in $(X,F)$ by $y$. We prove this by showing that it does not hold that for each $i\in \{1,2\}$ and for each $j\in \{0,1,2,\ldots,\ell_i\}$,
		$$
		d(F^{\ell_1+m_1+\ell_2+m_2+\ell_3+m_3+\cdots+\ell_{i-1}+m_{i-1}+j}\left(y\right),F^j\left(x_i\right))\leq \varepsilon.
		$$
		 We consider the following two possible cases.
\begin{enumerate}

\item $y\in [0,\frac{1}{2})$. Let $i=2$ and let $j=0$. Then 
\begin{align*}
		&d(F^{\ell_1+m_1+\ell_2+m_2+\ell_3+m_3+\cdots+\ell_{i-1}+m_{i-1}+j}\left(y\right),F^j\left(x_i\right))=\\
		&d(F^{\ell_1+m_1+j}\left(y\right),F^j\left(x_2\right))=d\left(F^{1+m_1+0}\left(y\right),F^0\left(\frac{3}{4}\right)\right)=d\left(\{0\},\left\{\frac{3}{4}\right\}\right)=\frac{3}{4}\not\leq \varepsilon.
\end{align*}
\item $y\in [\frac{1}{2},1]$. Let $i=1$ and let $j=0$. Then 
\begin{align*}
		&d(F^{\ell_1+m_1+\ell_2+m_2+\ell_3+m_3+\cdots+\ell_{i-1}+m_{i-1}+j}\left(y\right),F^j\left(x_i\right))=\\
		&d(F^{j}\left(y\right),F^j\left(x_1\right))=d\left(F^{0}\left(y\right),F^0\left(0\right)\right)=d\left(\{y\},\{0\}\right)=y\not\leq \varepsilon.
\end{align*}
\end{enumerate}
\end{example}
In Example \ref{ex3}, a CR-dynamical system $(X,F)$ is constructed in such a way that $p_1(F)=p_2(F)=X$ and such that
\begin{enumerate}
	\item $(X,F)$ has   the specification property, and
	\item $(X,F)$ does not have  the initial specification property.
\end{enumerate}
This means that   the specification property does not imply  the initial specification property (even in the case $p_1(F)=p_2(F)=X$).
In the following theorem, we prove that % if $p_1(F)=p_2(F)=X$, then 
the   initial specification property implies   the specification property.
\begin{theorem}\label{tretji}
	Let $(X,F)$ be a CR-dynamical system. %If $p_1(F)=p_2(F)=X$, then the following statements are equivalent.
	Suppose that $(X,F)$ has the  initial specification property. Then $(X,F)$ has the specification property. 
\end{theorem}
\begin{proof} 
Let $\varepsilon > 0$. Also, let $N$ be a positive integer such that for each positive integer $n$, for all positive integers $m_1,m_2,m_3,\ldots,m_{n-1}$ such that for each $i\in \{1,2,3,\ldots,n\}$, $m_i\geq N$, and for each initial $n$-specification $\mathcal S$, there is $y\in X$ such that $\mathcal S$ is $(\varepsilon,m_1,m_2,m_3,\ldots,m_{n-1})$-traced in $(X,F)$ by $y$. Such $N$ does exist since  $(X,F)$ has  the initial specification property. We prove that for any $N$-spaced specification $\mathcal S$ in $(X,F)$, there is $y\in X$ such that $\mathcal S$ is $\varepsilon$-traced in $(X,F)$ by $y$. Let 
$$
\mathcal S=\Bigg(F^{[k_1,\ell_1]}(x_1),F^{[k_2,\ell_2]}(x_2),F^{[k_3,\ell_3]}(x_3),\ldots ,F^{[k_n,\ell_n]}(x_n)\Bigg)
$$
be an $N$-spaced specification in $(X,F)$. Also, for each $i\in \{1,2,3,\ldots, n\}$, let $z_i\in F^{k_i}(x_i)$. Then 
$$
\mathcal C=\Bigg(F^{[0,\ell_1-k_1]}(z_1),F^{[0,\ell_2-k_2]}(z_2),F^{[0,\ell_3-k_3]}(z_3),\ldots ,F^{[0,\ell_n-k_n]}(z_n)\Bigg)
$$
is an initial $n$-specification. For each $i\in \{1,2,3,\ldots, n-1\}$, let $m_i=k_{i+1}-\ell_i$. Note that for each $i\in \{1,2,3,\ldots, n-1\}$, $m_i\geq N$. Let $z\in X$ be such that $\mathcal C$ is $(\varepsilon,m_1,m_2,m_3,\ldots,m_{n-1})$-traced in $(X,F)$ by $z$. Also, let $y\in X$ be such that $z\in F^{k_1}(y)$. We claim that $\mathcal S$ is $\varepsilon$-traced in $(X,F)$ by $y$.
Let $i\in \{1,2,3,\ldots,n\}$ and let $j\in \{k_i,k_i+1,k_i+2,\ldots,\ell_i\}$. Then 
\begin{align*}
&d(F^j(y),F^j(x_i))=d(F^{j-k_1+k_1}(y),F^{j-k_i+k_i}(x_i))=d(F^{j-k_1}(F^{k_1}(y)),F^{j-k_i}(F^{k_i}(x_i)))=\\
&d(F^{(\ell_1-k_1)+m_1+(\ell_2-k_2)+m_2+(\ell_3-k_3)+m_3+\ldots+(\ell_{i-1}-k_{i-1})+m_{i-1}+(j-k_i)}(F^{k_1}(y)),F^{j-k_i}(F^{k_i}(x_i)))\leq\\
&d(F^{(\ell_1-k_1)+m_1+(\ell_2-k_2)+m_2+(\ell_3-k_3)+m_3+\ldots+(\ell_{i-1}-k_{i-1})+m_{i-1}+(j-k_i)}(z),F^{j-k_i}(z_i))\leq \varepsilon.
\end{align*}
This completes the proof. 
\end{proof}
