\begin{theorem}\label{prvi11}
	Let $(X,F)$ be a CR-dynamical system. If for each $\varepsilon>0$, there is a positive integer $n_0$ such that for all $x,y\in X$ and for each non-negative integer $j$,     $H_d(F^{n_0+j}(x),F^{n_0+j}(y))\leq \varepsilon$, then $(X,F)$ has the Hausdorff specification property. 
\end{theorem}
\begin{proof}
To prove that $(X,F)$ has the Hausdorff specification property, let $\varepsilon>0$. Let $n_0$ be a positive integer such that for all $x,y\in X$, $H_d(F^{n_0}(x),F^{n_0}(y))\leq \varepsilon$. Next, let $N=n_0$, let  
	$$
	\mathcal S=\Bigg(F^{[k_1,\ell_1]}(x_1),F^{[k_2,\ell_2]}(x_2),F^{[k_3,\ell_3]}(x_3),\ldots ,F^{[k_n,\ell_n]}(x_n)\Bigg)
	$$
	 be an $N$-spaced specification in $(X,F)$, and let $y=x_1$. To see that $\mathcal S$ is Hausdorff $\varepsilon$-traced in $(X,F)$ by $y$, let $i\in \{1,2,3,\ldots,n\}$ and let $j\in \{k_i,k_i+1,k_i+2,\ldots,\ell_i\}$. We consider the following possible cases. 
	 \begin{enumerate}
	 	\item $j<N$. Then $j\in \{k_1,k_1+1,k_1+2,\ldots,\ell_1\}$ and it follows that $i=1$. Therefore, 
$$
H_d(F^j(y),F^j(x_i))=H_d(F^j(x_1),F^j(x_1))=0\leq \varepsilon.
$$
\item $j\geq N$. Then $j\geq n_0$ and, therefore, $H_d(F^j(y),F^j(x_i))=0\leq \varepsilon$.
	 \end{enumerate}
\end{proof}	
\begin{corollary}\label{prvi1}
	Let $(X,F)$ be a CR-dynamical system. If there is a positive integer $n_0$ such that for all $x,y\in X$,   $F^{n_0}(x)=F^{n_0}(y)$, then $(X,F)$ has  the Hausdorff specification property. 
\end{corollary}
\begin{proof}
	Let $n_0$ be a positive integer such that for all $x,y\in X$, $F^{n_0}(x)=F^{n_0}(y)$. Note that it follows that for each for each $\varepsilon>0$, for all $x,y\in X$, and for each non-negative integer $j$, $H_d(F^{n_0+j}(x),F^{n_0+j}(y))=0\leq \varepsilon$.
\end{proof}
In the following example, we show that  even if there is a positive integer $n_0$ such that for each $x\in X$,   $F^{n_0}(x)=X$, $(X,F)$ does not need to have the Hausdorff initial specification property.

\begin{example}\label{exi}
	Let $X=[0,1]$ and let 
	$$
	F=\left(\left[0,\frac{1}{2}\right]\times \{0\}\right)\cup \left(\{0\}\times \left[0,\frac{1}{2}\right]\right)\cup \left(\left[\frac{1}{2},1\right]\times \{1\}\right)\cup\left(\{1\}\times \left[\frac{1}{2},1\right]\right).
	$$
	Then for each $x\in X$, $F^{4}(x)=X$. Therefore, by Corollary \ref{prvi1}, $(X,F)$ has the Hausdorff specification property. 

	Next, we show that $(X,F)$ does not have the Hausdorff initial specification property. To see this, let $\varepsilon=\frac{1}{4}$ and let $N$ be any positive integer. Also, let $m_1$ be a positive integer such that $m_1\geq N$, and let $\mathcal S=\Bigg(F^{[0,1]}\left(\frac{1}{4}\right),F^{[0,1]}\left(\frac{3}{4}\right)\Bigg)$ be an initial $2$-specification in $(X,F)$. Note that in this case, $x_1=\frac{1}{4}$, $x_2=\frac{3}{4}$, and $\ell_1=\ell_2=1$. Finally, let $y\in X$ be any point. We show that $\mathcal S$ is not Hausdorff $(\varepsilon,m_1)$-traced in $(X,F)$ by $y$. We prove this by showing that it does not hold that for each $i\in \{1,2\}$ and for each $j\in \{0,1,2,\ldots,\ell_i\}$,
		$$
		H_d(F^{\ell_1+m_1+\ell_2+m_2+\ell_3+m_3+\cdots+\ell_{i-1}+m_{i-1}+j}\left(y\right),F^j\left(x_i\right))\leq \varepsilon.
		$$
		We consider the following cases.
		\begin{enumerate}
			\item $y=0$. Let $i=2$ and let $j=0$. Then 
\begin{align*}
		&H_d(F^{\ell_1+m_1+\ell_2+m_2+\ell_3+m_3+\cdots+\ell_{i-1}+m_{i-1}+j}\left(y\right),F^j\left(x_i\right))=H_d(F^{\ell_1+m_1+j}\left(y\right),F^j\left(x_i\right))=\\
		&H_d(F^{1+1+0}\left(0\right),F^0\left(0\right))=H_d\left(\left[0,\frac{1}{2}\right]\cup \{1\},\{0\}\right)=1\not\leq \varepsilon.
\end{align*}
\item $y\in (0,\frac{1}{2})$. Let $i=2$ and let $j=0$. Then 
\begin{align*}
		&H_d(F^{\ell_1+m_1+\ell_2+m_2+\ell_3+m_3+\cdots+\ell_{i-1}+m_{i-1}+j}\left(y\right),F^j\left(x_i\right))=H_d(F^{\ell_1+m_1+j}\left(y\right),F^j\left(x_i\right))=\\
		&H_d(F^{1+1+0}\left(y\right),F^0\left(0\right))=H_d\left(\left[0,\frac{1}{2}\right],\{0\}\right)=\frac{1}{2}\not\leq \varepsilon.
\end{align*}
\item $y=\frac{1}{2}$. Let $i=2$ and let $j=0$. Then 
\begin{align*}
		&H_d(F^{\ell_1+m_1+\ell_2+m_2+\ell_3+m_3+\cdots+\ell_{i-1}+m_{i-1}+j}\left(y\right),F^j\left(x_i\right))=H_d(F^{\ell_1+m_1+j}\left(y\right),F^j\left(x_i\right))=\\
		&H_d\left(F^{1+1+0}\left(\frac{1}{2}\right),F^0\left(0\right)\right)=H_d\left(\left[0,1\right],\{0\}\right)=1\not\leq \varepsilon.
\end{align*}
\item $y\in (\frac{1}{2},1)$. Let $i=2$ and let $j=0$. Then 
\begin{align*}
		&H_d(F^{\ell_1+m_1+\ell_2+m_2+\ell_3+m_3+\cdots+\ell_{i-1}+m_{i-1}+j}\left(y\right),F^j\left(x_i\right))=H_d(F^{\ell_1+m_1+j}\left(y\right),F^j\left(x_i\right))=\\
		&H_d\left(F^{1+1+0}\left(y\right),F^0\left(0\right)\right)=H_d\left(\left[\frac{1}{2},1\right],\{0\}\right)=1\not\leq \varepsilon.
\end{align*}
\item $y=1$. Let $i=2$ and let $j=0$. Then 
\begin{align*}
		&H_d(F^{\ell_1+m_1+\ell_2+m_2+\ell_3+m_3+\cdots+\ell_{i-1}+m_{i-1}+j}\left(y\right),F^j\left(x_i\right))=H_d(F^{\ell_1+m_1+j}\left(y\right),F^j\left(x_i\right))=\\
		&H_d\left(F^{1+1+0}\left(1\right),F^0\left(0\right)\right)=H_d\left(\{0\}\cup \left[\frac{1}{2},1\right],\{0\}\right)=1\not\leq \varepsilon.
\end{align*}
		\end{enumerate}
\end{example}
Among other things, Example \ref{exi} demonstrates that even if $p_1(F)=p_2(F)=X$, the Hausdorff specification property and the Hausdorff initial specification property may not be equivalent. This means that the Hausdorff specification property does not imply the Hausdorff  initial specification property (even in the case $p_1(F)=p_2(F)=X$). 

