\includegraphics[width=0.44\linewidth]{std-dANDsd-d.png}}
\caption[]{$\rm D^0$-tagged $\Delta R_{\rm STD-D^0}$ (red) compared to $\Delta R_{\rm WTA-D^0}$ (brown) in Fig. \ref{fig:jetaxes}(a), and to $\Delta R_{\rm SD-D^0}$ in Fig. \ref{fig:jetaxes}(b) with $z_{\rm cut}=0.1$ (dark blue) and $z_{\rm cut}=0.2$ (light blue) in the $10 < p_{\rm T}^{\rm ch~jet} < 20~{\rm GeV}/c$ interval with a $5 < p_{\rm T}^{\rm D^0} < 20~{\rm GeV}/c$ selection applied. The measurements are compared to predictions from PYTHIA 8 \cite{jetaxes}.} 
\label{fig:jetaxes}
