\section{Properties of Hecke operators} \label{Sec:Hecke}

The method will use some properties of Hecke operators, which were proven in \cite{clgp}.
In this section, $G$ will denote a finite subgroup of $\G = \Gal(\overline{K}/K)$.

\begin{df}
    Let $H$ be a subgroup of $G$, then the set $\Z[G/H]$ has a structure of $\Z[G]$-module. We call \emph{permutation modules} the sums of modules of this form.
\end{df}

\begin{df} \label{def_coset_Hecke}
    If $R$ is a ring and $V$ a $R[G]$-module, and $H,J$ two subgroups of $G$, then there is a morphism of $R$-modules $$R[H \backslash G / J] \rightarrow \Hom_{R}(V^H, V^J).$$
    This isomorphism is described in \cite[Fact 1.4]{clgp}. The morphisms of $R$-modules associated with cosets of the form $HgJ$ for $g$ in $G$ by this isomorphism are called \emph{Hecke operators}.
\end{df}


\begin{pro} \label{pseudo_inv}
    Let $H_1, \cdots, H_n$ and $J_1, \cdots, J_m$ be subgroups of $G$.
    If $\Phi \colon \bigoplus_i \Z[G/H_i] \rightarrow \bigoplus_i \Z[G/J_i]$ is a morphism of $\Z[G]$-modules whose image is of finite index in $\bigoplus_i \Z[G/J_i]$, then there exists an injective morphism $\Psi \colon \bigoplus_i \Z[G/J_i] \rightarrow \bigoplus_i \Z[G/H_i]$ such that $\Phi \circ \Psi = k \cdot \id$, where $k$ is a positive integer that divides $|G|^2$.
\end{pro}

\begin{proof}
    See \cite[Proposition 2.13]{clgp} for the existence of $\Psi$, and \cite[Theorem 2.16]{clgp} for the proof that $k$ divides $|G|^2$.
\end{proof}

\begin{pro} \label{im_S_unit}
    Let $H,J$ be two subgroups of $G$, $L_1 = \overline{K}^H$ and $L_2 = \overline{K}^J$. Let $S$ be a set of prime numbers. If $\Phi: L_1^\times \rightarrow L_2^\times$ is defined by a sum of Hecke operators, then $$\Phi( \Z_{S, L_1}^\times) \subset \Z_{S, L_2}^\times. $$
\end{pro}

\begin{proof}

This is a direct consequence of \cite[Theorem 1.18]{clgp}.

\end{proof}


\section{Finding a resolution with Hecke operators} \label{Sec:resolution}

In all of the article, $M$ will be a finite Galois module.

Let $G$ be the image of the action $\G \rightarrow \Aut(M)$. It is isomorphic to a finite quotient of $\G$.
Note that the action of $\G$ over $M$ can be factorized to be seen as an action of $G$ over $M$.

\begin{req} \label{req:G_galois}
    If $\mathcal{N}$ denotes the kernel of the action $\G \rightarrow \Aut(M)$, then $G$ is the Galois group of the Galois extension $\overline{K}^{\mathcal{N}}/K$.
\end{req}

Suppose we have $\Z[G]$-modules $P_i$ for every integer $i$, which are permutation modules, as well as some morphisms of $G$-modules $s$ and  $d_i^*$ such that the sequence $$\cdots \xrightarrow{d_2^*} P_2 \xrightarrow{d_1^*} P_1 \xrightarrow{d_0^*} P_0 \xrightarrow{s} M^* \rightarrow 0 $$ is exact, where $M^*$ is the dual module of $M$.

We will see in section \ref{Sec:Algo} that we can always find such an exact sequence, and we will give an algorithm (algorithm \ref{alg_resolution}) to compute such $P_i$ and $d_i^*$ up to any integer $i$.


In this article, we will only need to compute such sequences up to~$P_2$. We will denote by (\ref{suite_ex_1}) an exact sequence of the form \begin{equation} \label{suite_ex_1}
     P_2 \xrightarrow{d_1^*} P_1 \xrightarrow{d_0^*} P_0 \xrightarrow{s} M^* \rightarrow 0. \end{equation}

\begin{lm} \label{lm_ex_fct}
    The functor $P \mapsto P^* = \Hom_\Z(P, \K)$, on the category of $\G$-modules that are finitely generated $\Z$-modules, is exact.
\end{lm}


\begin{proof}

Let $A, B, C$ be $G$-modules such that there is an exact sequence $$ 0 \rightarrow A \xrightarrow{i} B \xrightarrow{s} C \rightarrow 0.$$

Let $s^*$ be the map $C^* = \Hom(C, \K) \rightarrow \Hom(B, \K) = B^*; f \mapsto f \circ s$. Since $s$ is surjective, the map $s^*$ is injective.

Likewise, let $i^*$ be the map $B^* \rightarrow A^*, f \mapsto f \circ i$. Again, since $i$ is injective, the map $i^*$ is surjective.

Since we know that $i \circ s = 0$, we have $\im(s^*) \subseteq \Ker(i^*)$ . We also need to show that $\Ker(i^*) \subseteq \im(s^*)$.

Let $f$ be an element of $\Ker(i^*)$. That is to say $f \circ i = 1$. Then that means $\Ker(f) \subset \im(i) = \Ker(s)$. So, by the structure of finitely generated abelian groups, there exists $g \in C^*$ such that $f = g \circ s$.

In conclusion, the short sequence $$0 \rightarrow C^* \xrightarrow{s^*} B^* \xrightarrow{i^*} A^*\rightarrow 0$$ is exact.

\end{proof}


Once we obtain an exact sequence of the form (\ref{suite_ex_1}), by lemma ~\ref{lm_ex_fct}, we can take the dual and get an exact sequence of the form \begin{equation} \label{suite_ex_2}
     0 \rightarrow M \rightarrow I_0 \xrightarrow{d_0} I_1 \xrightarrow{d_1} I_2 \end{equation}

where $I_i = P_i^*$ for all $i$.

Consider an exact sequence of the form (\ref{suite_ex_2}) obtained with the construction described above. The modules $P_0$, $P_1$, $P_2$ are permutations modules. In the rest of the section, let us denote $P_i = \bigoplus_j \Z[G/H_{i,j}]$ for $i \in \{1, 2, 3\}$. And for every pair $(i,j)$, let us define $L_{i,j} := \overline{K}^{H_{i,j}}$.


\begin{pro} \label{pro:alg_étales}
    With the above notations, for $i \in  \{1, 2, 3\}$, we have $$I_i = \bigoplus_j \Ind_{\G / G_{L_{i,j}}} \overline{K}^\times = \bigoplus_j \overline{L_{i,j}}^\times$$
    where $G_{L_{i,j}}$ is the absolute Galois group of $L_{i,j}$.
    And $$I_i^G = \bigoplus_j L_{i,j}^\times.$$
\end{pro}

\begin{proof}
    See \cite[Section 3.12, Example 19]{Voskresenskii}.
\end{proof}

The morphisms $d_0 \colon I_0 \rightarrow I_1$ and $d_1 \colon I_1 \rightarrow I_2$ induce some morphisms respectively from $I_0^G$ to $I_1^G$ and from $I_1^G$ to $I_2^G$, that we will denote $d_0^G$ and $d_1^G$.

\begin{pro} \label{coh_grp}
    With the above notations, we have $$H^1(\G,M) = \frac{\Ker (d_1^G \colon I_1^G \rightarrow I_2^G ) }{\im (d_0^G \colon I_0^G \rightarrow I_1^G)}.$$
\end{pro}

\begin{proof}

Let $J \subset I_1$ be the image of $d_0$. Then we have a short exact sequence $$ 0 \rightarrow M \rightarrow I_0 \xrightarrow{d_0} J \rightarrow 0. $$

The associated long exact sequence starts with $$ 0 \rightarrow M^\G \rightarrow I_0^\G \xrightarrow{d_0} J \rightarrow H^1(\G, M) \rightarrow H^1(\G, I_0)  $$
and $H^1(\G, I_0) =  \bigoplus_j H^1(G_{L_{0,j}}, \overline{L}_{0,j}^\times)$ by Shapiro's lemma, and  $  H^1(G_{L_{0,j}},\overline{L}_{0,j}^\times) = 0 $ by Hilbert 90th theorem.

This last exact sequence allows us to deduce that $$H^1(\G, M) = \frac{J^G}{\im (d_0^G \colon I_0^G \rightarrow I_1^G)}. ~~ (*)$$

What's more, by definition of $J$, we also have an exact sequence $$0 \rightarrow J \rightarrow I_1 \xrightarrow{d_1} I_2.$$

Hence the exact sequence $$0 \rightarrow J^G \rightarrow I_1^G \xrightarrow{d_1} I_2^G$$
from which we can deduce that $$J^G = \Ker (d_1^G \colon I_1^G \rightarrow I_2^G ).$$ 

Combining that result with $(*)$, we get $$H^1(\G,M) = \frac{\Ker (d_1^G \colon I_1^G \rightarrow I_2^G ) }{\im (d_0^G \colon I_0^G \rightarrow I_1^G)}.$$

\end{proof}

\begin{pro} \label{pro:res_compatible}
    For every subgroup $\HH < \G_K$, the map $$\Res: H^1(\G_K, M) \rightarrow H^1(\HH, M)$$ is the natural restriction $$H^1(\G, M) = \frac{\Ker (d_1^\G \colon I_1^\G \rightarrow I_2^\G ) }{\im (d_0^\G \colon I_0^\G \rightarrow I_1^\G)} \rightarrow H^1(\HH, M) = \frac{\Ker (d_1^\HH \colon I_1^\HH \rightarrow I_2^\HH ) }{\im (d_0^\HH \colon I_0^\HH \rightarrow I_1^\HH)}$$.
\end{pro}

\begin{proof}

Let $J \subset I_1$ be the image  of $d_0$. Then we have a short exact sequence $$ 0 \rightarrow M \rightarrow I_0 \xrightarrow{d_0} J \rightarrow 0. $$

The associated long exact sequence starts with $$0 \rightarrow M^\G \rightarrow I_0^\G \rightarrow J_1^\G \rightarrow H^1(\G, M).$$

We can then apply the restriction map to obtain 

\[ 
\xymatrix@C4.5pc{
0 \ar[r] & M^\G \ar[r] \ar[d]^{\Res} &  I_0^\G \ar[r] \ar[d]^{\Res} & J_1^\G \ar[r] \ar[d]^{\Res} & H^1(\G, M) \ar[d]^{\Res} \\
0 \ar[r] & M^{\HH} \ar[r] & I_0^{\HH} \ar[r] & J_1^{\HH} \ar[r] & H^1({\HH}, M)
}
\] 

Moreover, for every field $F$ such that $K \subset F$, and for all $i$, we have $I_i ^\G = L_i^\times$ and $I_i^{\Gal(\overline{F}/F)} = (L_i \otimes_K F)^\times$. So $I_i^{\HH} = \overline{L_i}^\HH$, hence the conclusion.

\end{proof}


\section{A remarkable Selmer group}
\label{Sec:Selm}

Let $M$ be a finite Galois module, suppose we have the Galois modules $I_0$, $I_1$, $I_2$ and the morphisms of $G$-modules $d_0$ and $d_1$ obtained as in section \ref{Sec:resolution}, such that the sequence $$ 0 \rightarrow M \rightarrow I_0 \xrightarrow{d_0} I_1 \xrightarrow{d_1} I_2 $$ is exact.
By proposition \ref{coh_grp}, we have $$H^1(\G,M) = \frac{\Ker (d_1^G \colon I_1^G \rightarrow I_2^G ) }{\im (d_0^G \colon I_0^G \rightarrow I_1^G)}.$$ where for all $i \in \{0, 1, 2\}$, $I_i^G$ is of the form $\bigoplus_j L_{i,j}^\times$ and the $L_{i,j}$ are intermediary fields between $K$ and $\overline{K}$. 


In the rest of the article, we will denote by $L_i$ the étale algebra $\prod_j L_{i,j}$. We will allow ourself to extend to étale algebras the notions of class groups and $S$-unit groups.



\begin{df} \label{df:H1S}

Let $S$ be a set of prime numbers. Let us define the group $H^1_S(\G, M) := \frac{\Ker( d_1^G \colon \bigoplus_j \Z_{L_{1,j},S}^\times \rightarrow \bigoplus_j \Z_{L_{2,j},S}^\times) }{\im ( d_0^G \colon \bigoplus_j \Z_{L_{0,j},S}^\times \rightarrow \bigoplus_j \Z_{L_{1,j},S}^\times)}$.

\end{df}

By proposition \ref{im_S_unit}, the images of $S$-units by $d_1^G$ and $d_0^G$ are $S$-units, so the group $H^1_S(\G, M)$ is well defined.



When the context is clear, we will also allow ourself to write $H^1$ and $H^1_S$ instead of $H^1(\G,M)$ and $H^1_S(\G,M)$.


The goal of this section will be to prove that $H^1_S(\G, M)$ is a Selmer group.
We will use the following notations:
\begin{itemize}
    \item $Z^1 := \Ker (d_1^G \colon I_1^G \rightarrow I_2^G) $
    \item $B^1 := \im (d_0^G \colon I_0^G \rightarrow I_1^G)$
    \item $Z^1_S := \Ker( d_1^G \colon \bigoplus_j \Z_{L_{1,j},S}^\times \rightarrow \bigoplus_j \Z_{L_{2,j},S}^\times)$
    \item $B^1_S := \im ( d_0^G \colon \bigoplus_j \Z_{L_{0,j},S}^\times \rightarrow \bigoplus_j \Z_{L_{1,j},S}^\times)$ .
\end{itemize}


\begin{pro}
We have an injection $H^1_S(\G, M) \hookrightarrow H^1(\G, M)$ 
\end{pro}

\begin{proof}

We have trivially $Z^1_S \subset Z^1$. So in order to prove the proposition, it is enough to show that $B^1 \cap \Z_{L_1, S}^\times \subset B^1_S $.
In other words, we need to show that if an element $y$ in the image of $d_0^G$ is an $S$-unit, then there exists an $S$-unit $x$ in $I_0^G = L_0^\times$ such that $d_0^G(x) = y$.\

If we take the tensor product of the exact sequence (\ref{suite_ex_2}) with $\Q$, we obtain 
$$0 \rightarrow I_0 \otimes \Q \xrightarrow{d_0} I_1 \otimes \Q \xrightarrow{d_1} I_2 \otimes \Q$$
because $M$ is finite, so that $M \otimes \Q = 0$.

Then, by proposition \ref{pseudo_inv}, there exists a surjective morphism of $G$-modules $f \colon I_1 \rightarrow I_0$ such that $f \circ d_0 = k \cdot \id$, with $k$ dividing $|G|^2$.

Now, let $y$ be an element of $B^1 \cap \Z_{L_1, S}^\times$. Since $x$ is in $B^1$, there exists $x \in L_0^\times$ such that $d_0^G(x) = y$. So $s \circ d_0^G (x) = k \cdot x$ (or $x^k$ in multiplicative notation). But $d_0^G(x) = y$ is an $S$-unit, so its image by $f$ is also an $S$-unit by \ref{im_S_unit}.
Hence $k \cdot x$ is an $S$-unit. And since $\Z_{S, L_0}^\times$ is saturated as a subgroup of $L_0^\times$, that means $x$ is also an $S$-unit.

So $y$ is the image of an $S$-unit by $d_0^G$, ie $y \in B_S^1$. Hence $B^1_S \subset B^1 \cap \Z_{L_1, S}^\times$.


\end{proof}


\begin{df} \label{df:notations}

In the rest of the section, if $v$ is a finite place of $K$, we will use the following notations:
\begin{itemize}
    %\item $H^1_{\units} = \frac{Z^1_{\units}}{B^1_{\units}} = \frac{\Ker(\Z_{L_1}^\times \xrightarrow{d_1} \Z_{L_2}^\times)}{\im(\Z_{L_0}^\times \xrightarrow{d_0} \Z_{L_1}^\times)}$,
    \item $Z^1_{\units, v} = \Ker(\Z_{L_1,v}^\times \xrightarrow{d_1} \Z_{L_2,v}^\times)$,
    \item $B^1_{\units, v} = \im(\Z_{L_0,v}^\times \xrightarrow{d_0} \Z_{L_1,v}^\times)$,
    \item$H^1_{\units, v} = \frac{Z^1_{\units, v}}{B^1_{\units, v}}$,
    \item $K_v^{\ur}$ the largest unramified extension of $K_v$, and $I_{K_v} = \Gal(\overline{K_v}/K_v^{\ur})$ the inertia group, and $\G_{K_v} = \Gal(\overline{K_v}/K)$.
    \item $Z^1_{\ram, v} = \Ker((L_0 \otimes K_v^{\ur})^\times \xrightarrow{d_1} (L_1 \otimes K_v^{\ur})^\times)$,
    \item $B^1_{\ram, v} = \im((L_1 \otimes K_v^{\ur})^\times \xrightarrow{d_0} (L_2 \otimes K_v^{\ur})^\times)$,
    \item $H^1_{\ram,v} = \frac{Z^1_{\ram, v}}{B^1_{\ram, v}}$.

\end{itemize}

When the context is clear, we will allow ourself to write $H^1_{\ram}$, $Z^1_{\ram}$ and $B^1_{\ram}$.

For every place $v$ of $K$, we also denote:
\begin{itemize}
    \item $Z^1_v = \Ker(L_{1,v}^\times \xrightarrow{d_{1,v}} L_{2,v}^\times)$
    \item $B^1_v = \im(L_{0,v}^\times \xrightarrow{d_{0,v}} L_{1,v}^\times)$
    \item $H^1_v = \frac{Z^1_v}{B^1_v}$.
\end{itemize}

where $d_{0,v}$ and $d_{1,v}$ are defined respectively by the two 
