\section{Exporting and importing maps}\label{sec: exporting and importing maps}

A key result to prove \cref{large group actions hypertoral manifolds} is the following theorem.

\begin{thm}\label{pE torus}\cite[Theorem 4.1]{mundet2021topological}
	Let $M$ be a closed oriented manifold of dimension $n$ which admits a continuous map $f:M\longrightarrow T^n$ of non-zero degree and let $G$ be a finite group acting effectively on $M$ and trivially on $H^1(M,\Z)$, then there exist a group action of $G$ on $T^n$ and a continuous map $f_G:M\longrightarrow T^n$ which is $G$-equivariant and homotopic to $f$.
\end{thm}

\begin{rem}
	The constructed action of $G$ on $T^n$ is not necessarily effective. If $K$ denotes the kernel of ineffectiveness, then $|K|\leq \deg f$ and the effective action of $G/K$ on $T^n$ is free and by rotations. Thus the induced group morphism $G/K\longrightarrow \Gl(n,\Z)$ is trivial.
\end{rem}

\Cref{pE torus} inspires the following definition:

\begin{defn}\label{pE defn}
	Let $M$ and $M'$ be closed oriented manifolds of the same dimension and let $f:M\longrightarrow M'$ be a continuous map. We say that $f$ exports group actions, or $f$ is an exporting map, if there exists a constant $C$ such that every finite group $G$ acting effectively on $M$ (which we denote by $\phi:G\longrightarrow \Homeo(M)$) has a subgroup $H\leq G$ such that:
	\begin{itemize}
		\item[1.] $[G:H]\leq C$
		\item[2.] There exists an action $H$ on $M'$ (denoted by $\phi':H\longrightarrow \Homeo(M')$).
		\item[3.] There exists an $H$-equivariant map $f_H:M\longrightarrow M'$ homotopic to $f$.
	\end{itemize} 
\end{defn}

By Minkowski's lemma, given a closed connected manifold $M$ there exists a constant $C$ such that any finite group $G$ acting effectively on $M$ has a finite index subgroup $H$ of index $[G:H]\leq C$ such that $H$ acts trivially on $H^1(M,\Z)$. Thus, \cref{pE torus} states that any non-zero degree map $f:M\longrightarrow T^n$ is an exporting map. Another example of this property in the smooth setting is provided by the following theorem of R.Schoen and S.T.Yau.

\begin{thm}\cite[Theorem 8]{schoen1979compact}\label{pE harmonic}
	Let $M$ and $M'$ be closed connected orientable smooth manifolds of the same dimension. Assume that $M'$ has a Riemannian metric of non-positive curvature and there is a non-zero degree smooth map $f:M\longrightarrow M'$ such that $f_*:\pi_1(M)\longrightarrow \pi_1(M')$ is surjective. Let $A(M')$ denote the group of affine transformations on $M'$ (that is, the group of diffeomorphisms preserving the Levi-Civita connection) and let $\overline{A}(M')$ denote the subgroup of the identity component of $A(M')$ generated by the parallel vector fields of $M'$. Given a finite group $G$ acting effectively and smoothly on $M$, suppose that for each $g\in G$ there exists an element $g'\in \overline{A}(M')$ such that $f\circ g$ is freely homotopic to $g'\circ f$ ($g'$ is not necessarily unique or non-trivial). Then there exist a group morphism $\gamma:G\longrightarrow \overline{A}(M')$ and a $\gamma$-equivariant smooth map $f_G:M\longrightarrow M'$ homotopic to $f$. Moreover, $|\ker\gamma|\leq \deg(f)$.
\end{thm} 

If there exists a constant $C$ such that every finite group $G$ acting smoothly and effectively on $M$ has a subgroup $H\leq G$ satisfying the conditions of \cref{pE harmonic} and $[G:H]\leq C$ then $f$ is an exporting map. Some examples can be found in \cite[Theorem 11, Theorem 13]{schoen1979compact}.

\begin{thm}\cite[Theorem 11, Theorem 13]{schoen1979compact}\label{exporitng maps SY}
	Let $M$ and $M'$ be closed connected orientable smooth manifolds of the same dimension. Assume that there is a degree one map $f:M\longrightarrow M'$ such that $f_*:\pi_1(M)\longrightarrow \pi_1(M')$ is surjective. Furthermore, assume that $M'$ satisfy one of the following set of conditions:
	\begin{itemize}
		\item[1.] $M'$ is diffeomorphic to a locally symmetric space $\Gamma\setminus G/H$, where all the factors of $G$ have real rank equal or greater than $2$.
		\item[2.] $M'$ is flat and $\Zc\pi_1(M')$ is trivial.
	\end{itemize}
	Then for any finite group $G$ acting effectively and smoothly on $M$ there exist a smooth effective action of $G$ on $M'$ and a $G$-equivariant map $f_G:M\longrightarrow M'$ homotopic to $f$.
\end{thm}

Note that in \cref{exporitng maps SY} we do not need to replace the finite group by a suitable subgroup of bounded index. 

The aim of this section is to study exporting maps.

\begin{lem}\label{exporting map non-zero degree}
	Let $f:M\longrightarrow M'$ be a non-zero degree exporting map. With the notation as in \cref{pE defn}, we have $|\ker\phi'|\leq \deg(f)$.
\end{lem}

The proof of the lemma is a consequence of the next fact.

\begin{lem}\label{quotient map image degree}\cite[Lemma 4.4]{mundet2021topological}
	Let $M$ be a closed oriented $n$-manifold and suppose that $G$ is a finite group acting on $M$ effectively and preserving the orientation. If we denote by $\pi:M\longrightarrow M/G$ the quotient map and by $d$ the cardinal of $G$ then $\pi^*(H^n(M/G,\Z))\subseteq dH^n(M,\Z)$.  
\end{lem}

\begin{proof}[Proof of \cref{exporting map non-zero degree}]
	Since $f_H$ is $H$-equivariant, we can restrict the action of $H$ on $M$ to the subgroup $\ker\phi'\leq H$, obtaining a commutative diagram
	\[
	\begin{tikzcd}
		M\ar{r}{f_H}\ar{d}{\pi} & M'\\
		M/\ker\phi'\ar{ru}{\overline{f}_H} &\\
	\end{tikzcd}
	\]
	In consequence, $\pi^*\circ \overline{f}^*_H=f^*_H$. Since $f$ and $f_H$ are homotopic, we have $f^*_H=f^*:H^n(M',\Z)\longrightarrow H^n(M,\Z)$. By \cref{quotient map image degree}, we obtain that $|\ker\phi'|$ divides $\deg(f)$. In particular $|\ker\phi'|\leq \deg(f)$.
\end{proof}

The next lemma studies the composition of two exporting maps.

\begin{lem}\label{pE composition}
	Let $M$, $M'$ and $M''$ be closed oriented manifolds and let $f:M\longrightarrow M'$ and $g:M'\longrightarrow M''$ be exporting non-zero degree maps with constants $C$ and $D$ respectively. Then $g\circ f:M\longrightarrow M''$ exports group actions with constant $C\cdot D$.
\end{lem}

\begin{proof}
	Assume that $G$ is a finite group acting effectively on $M$ and take the subgroup $H\leq G$ of \cref{pE defn}. Thus, there exists an action of $H$ on $M'$, denoted by $\phi':H\longrightarrow \Homeo(M')$, a $H$-equivariant map $f_H:M\longrightarrow M'$ homotopic to $f$ and $[G:H]\leq C$. Since $\phi'(H)$ acts effectively on $M'$, there exist a subgroup $K\leq \phi'(H)$, an action $\phi'':K\longrightarrow \Homeo(M'')$ satisfying $[\phi'(H):K]\leq D$, and a $K$-equivariant map $g_K:M'\longrightarrow M''$ homotopic to $g$. We can consider the subgroup $H'=\phi'^{-1}(K)\leq H$ and the action of $H'$ on $M''$ given by the group morphism $\phi''\circ\phi':H'\longrightarrow K\leq \Homeo(M'')$. The map $g_K\circ f_H$ is $H'$-equivariant and homotopic to $g\circ f$. In addition, $[G:H']\leq C\cdot D$ and hence the claim is proved.
\end{proof}

Before stating the main result of this section, we introduce two more properties of large finite group actions on manifolds.

\begin{defn}\label{stabilizers properties def}
	Let $M$ be a closed connected manifold. Then:
	\begin{itemize}
		\item[1.] We say that $M$ has the small stabilizers property if there exist a constant $C$ such that if $G$ is a finite group acting effectively on $M$ then $|G_x|\leq C$ for all $x\in M$.
		\item[2.] We say that $M$ has the almost fixed point property if there exists a constant $C$ such that if $G$ is a finite group acting effectively on $M$ then there exist $x\in M$ such that $[G:G_x]\leq C$.
	\end{itemize}
\end{defn}

The first property is new and it has not been studied yet. We will show that the manifolds studied in this article have this property. The second property was studied in \cite{riera2024jordan}.

\begin{thm}\cite[Theorem 1.5]{riera2024jordan}\label{almost fix point euler char}
	Let $M$ be a closed connected manifold with $\chi(M)\neq 0$. Then $M$ has the almost fixed point property.
\end{thm}

The almost fixed point property and the small stabilizers property are dual in the following sense:

\begin{lem}\label{small stab+almost fixed point=almost asymmetric}
	A closed manifold $M$ with the small stabilizers and the almost fixed point property is almost asymmetric.
\end{lem}

\begin{proof}
	Let $C$ be the constant of the almost fixed point property and $D$ the constant of the small stabilizers property. Assume that we have a finite group $G$ acting effectively on $M$. Then there exists $x\in M$ such that $[G:G_x]\leq C$. In addition, $|G_x|\leq D$. Consequently, $|G|\leq C\cdot D$. Thus, $M$ is almost asymmetric.
\end{proof}

The main result of this section is that properties introduced in \cref{large finite group actions def} behave well with respect exporting maps. It is one of the main ingredients to prove \cref{main theorem2 intro}.

\begin{thm}\label{pE jordan and discsym}
	Let $M$ and $M'$ closed oriented manifolds which admit a non-zero degree exporting map $f:M\longrightarrow M'$. Then:
	\begin{itemize}
		\item[1.] If $\Homeo(M')$ is Jordan, then $\Homeo(M)$ is Jordan.
		\item[2.] $\D(M)\leq \D(M')$.
		\item[3.] If $M'$ has the small stabilizer property then $M$ has the small stabilizer property.
		\item[4.] If $M'$ is almost asymmetric, then $M$ is almost asymmetric.
	\end{itemize} 
\end{thm}

In order to prove this theorem we need the three following group-theoretic lemmas.

\begin{lem}\label{Jordan ses}\cite[Lemma 2.2]{IgnasiMundetiRiera2010Jtft}
	Let $d$ and $r$ be natural numbers. There exists a natural number $C(d,r)$ such that if we have a short exact sequence of groups 
	$$1\longrightarrow K\longrightarrow G \longrightarrow A\longrightarrow 1 $$
	where $|K|\leq d$ and $A$ is abelian and generated by $r$ elements, then $G$ has an abelian subgroup of index at most $C(d,r)$.
\end{lem}


\begin{lem}\label{subgroup elementary abelian groups}\cite[Lemma 2.1]{mundet2021topological}
	Let $a$,$b$ and $C$ be natural numbers and suppose that $G'$ is a subgroup of $(\Z/a)^b$ satisfying $[(\Z/a)^b:G']\leq C $. Then there exist a number $a'$ and a subgroup $G''\leq G'$ such that $G''\cong (\Z/a')^b$ and $C!a'\geq a$. 
\end{lem}

To state the last lemma we need to introduce two new invariants:

\begin{defn}\label{def: discsym primes}
	Let $M$ be a manifold. We define
	$$P\D(M)=\max\{\{0\}\cup\{r:(\Z/p)^r \text{ acts effectively on $M$ for arbitrarily large prime $p$}\}\}.$$ 

	For a fixed prime $p$, we define
	$$\D_p(M)=\max\{\{0\}\cup\{r:(\Z/p^s)^r \text{ acts effectively on $M$ for arbitrarily large $s$}\}\}. $$
\end{defn}

\begin{lem}\label{discsym prime version}
	Let $M$ be a closed manifold, then
	$$\D(M)=\max(\{P\D(M)\}\cup\{\D_p(M): \text{$p$ prime} \}).$$ 
\end{lem}

\begin{proof}
	Clearly, $P\D(M)\leq \D(M)$ and $\D_p(M)\leq \D(M)$ for every prime $p$. Conversely, assume that $\D(M)=b$ and therefore there exists a sequence of natural numbers $\{a_i\}_{i\in \mathbb{N}}$ such that $(\Z/a_i)^b$ acts effectively on $M$ for all $i$ and $a_i\longrightarrow \infty$ when $i\longrightarrow\infty$. Let $\mathcal{P}$ be the set of primes which divide $a_i$ for some $i$.

	If $|\mathcal{P}|=\infty$ then there exists a subsequence $\{a_k\}_{k\in\mathbb{N}}$ of $\{a_i\}_{i\in\mathbb{N}}$ such that each $a_k$ is divided by a prime $p_k$ satisfying that $p_k<p_{k+1}$. Thus, by taking $(\Z/p_k)^b\leq (\Z/a_k)^b$ we have an effective action of $(\Z/p_k)^b$ on $M$. Consequently, $b\leq P\D(M)$. 

	If $|\mathcal{P}|<\infty$ then there exist $m$ primes $p_1$,\dots, $p_m$ such that $a_i=p_1^{x_{1,i}}\dots p_m^{x_{m,i}}$ for all $i$. Since $a_i\longrightarrow \infty$ when $i\longrightarrow\infty$, by the pigeonhole principle there exists a subsequence $\{a_k\}_{k\in\mathbb{N}}$ and a number $l\in \{1,\dots,m\}$ such that $x_{l,k}\longrightarrow \infty$ when $k\longrightarrow \infty$. Thus, we have effective group actions of $(\Z/p_l^{x_{l,k}})^b$ on $M$. Consequently, $b\leq \D_{p_{l}}(M)$. 

	By combining these two cases we obtain the desired result.
\end{proof}

We are almost ready to give the proof of \cref{pE jordan and discsym}. The last result we need is a corollary of a theorem by L.N. Mann and J.C. Su.

\begin{thm}\cite{mann1963actions}\label{MannSu thm}
	Let $M$ be a closed manifold of dimension $n$. For a prime $p$, we define $b_p(M)=\sum_{i=0}^{n}\dim H^i(M,\Z/p)$. There exists a number $C_p$ only depending on $n$ and $b_p(M)$ such that if $(\Z/p)^r$ acts effectively on $M$ then $r\leq C_p$.
\end{thm}

\begin{cor}\cite{mann1963actions}\label{bound rank finite groups}
	Let $M$ be a closed manifold of dimension $n$. There exists a number $r$ such that if $A$ is a finite abelian group acting effectively on $M$ then $\rank(A)\leq r$. 
\end{cor}

\begin{proof}[Proof of \cref{pE jordan and discsym}]
	For the first statement of the theorem assume that $G$ is a finite group acting effectively on $M$. Then there exist a subgroup $H$ of $G$ such that $[G:H]\leq C$, an action of $H$ on $M'$ and a continuous map $f_H:M\longrightarrow M'$ which is $H$-equivariant and homotopic to $f$. Let $H_0=\ker\phi'$. By \cref{exporting map non-zero degree}, we known that $|H_0|\leq \deg(f)$. The group $\phi'(H)$ acts effectively on $M'$. Thus there exists an abelian subgroup $A'\leq \phi'(H)$ such that $[\phi'(H):A']\leq C'$, where $C'$ is the Jordan constant of $\Homeo(M')$. By \cref{bound rank finite groups}, there exists a constant $r'$ such that any abelian finite group acting effectively on $M'$ has rank at most $r'$. 

	We consider the commutative diagram 
	\[
	\begin{tikzcd}
		1\ar{r}{} & H_0\ar{r}{}\ar{d}{Id} & \phi'^{-1}(A')\ar{r}{\phi'}\ar[hook]{d}{} & A'\ar{r}{}\ar[hook]{d}{} &1\\	
		1\ar{r}{} & H_0\ar{r}{} & H\ar{r}{\phi} & \phi(H)\ar{r}{} &1\\
	\end{tikzcd}
	\]
	Note that $[H:\phi'^{-1}(A')]\leq C'$. We can use \cref{Jordan ses} on the upper short exact sequence to find a constant $D$, which only depends on $d$ and $r'$, and an abelian subgroup $A$ of $\phi'^{-1}(A')$ such that $[\phi'^{-1}(A'):A]\leq D$. In conclusion, we have found a subgroup $A$ of $G$ such that $[G:A]\leq C\cdot C'\cdot D$ and we can conclude that $\Homeo(M)$ is Jordan.

	We note that by \cref{subgroup elementary abelian groups} we can assume that given an increasing sequence  $\{a_i\}_{i\in\mathbb{N}}$ such that $a_i\longrightarrow \infty$ and groups $(\Z/a_i)^b$ acting effectively on $M$ then $(\Z/a_i)^b$ also act on $M'$ for all $i$ and that we can replace $f$ by an homotopic equivariant map for each $i$. 

	By \cref{discsym prime version} we can divide the prove in two parts. Firstly assume that we have an increasing sequence of primes $\{p_k\}_{k\in\mathbb{N}}$ and groups $(\Z/p_k)^b$ acting effectively on $M$. Like in the first part of the proof, we consider the group action $\phi'_{{p_k,b}}:(\Z/p_k)^b\longrightarrow \Homeo(M')$ AND the exact sequence 
	\[
	\begin{tikzcd}
		1\ar{r}{} &K_{(p_k,b)}\ar{r}{} & (\Z/p_k)^b\ar{r}{\phi'_{{p_k,b}}} & \phi'_{{p_k,b}}((\Z/p_k)^b)\ar{r}{} &1\\
	\end{tikzcd}
	\]
	for each $k$, where $K_{(p_k,b)}=\ker\phi'_{{p_k,b}}$.
	Since $K_{(p_k,b)}$ is a subgroup of $(\Z/p_k)^b$, there exists $x(k)\in \mathbb{N}$ such that
	$|K_{(p_k,b)}|=p_k^{x(k)}$. On the other hand, $|K_{(p_k,b)}|\leq d $. Since $p_k\longrightarrow\infty$ when $k\longrightarrow \infty$, there exist $k_0$ such that $p_k>d$ for all $k\geq k_0$. This implies that $x(k)=0$ for $k\geq k_0$ and that $(\Z/p_k)^b$ acts effectively on $M'$ for $k\geq k_0$. Thus, $P\D(M)\leq \D(M')$.

	We fix a prime number $p$ and denote by $c\in \mathbb{N}$ the largest number such that $p^c\leq d$. Assume that we have an increasing sequence $\{a_k\}_{k\in\mathbb{N}}$ such that $(\Z/p^{a_k})^b$ acts effectively on $M$. Since $a(k)\longrightarrow\infty$ when $k\longrightarrow \infty$, there exists a $k_0$ such that $a_{k_0}>c$ for all $k\geq k_0$. Then $K_{(p^{a_k},b)} $ is a subgroup of $(\Z/p^{c})^b\leq (\Z/p^{a_k})^b$ and $$(\Z/p^{a_k-c})^b\cong (\Z/p^{a_k})^b/(\Z/p^{c})^b\leq (\Z/p^{a_k})^b/K_{(p^{a_k},b)}\cong \phi'_{{p^{a_k},b}}((\Z/p^{a_k})^b)$$ for $k\geq k_0$. Hence,  $(\Z/p^{a_k-c})^b$ acts effectively on $M'$ for $k\geq k_0$ and $\D_p(M)\leq \D(M')$.

	Joining the two cases we obtain that $\D(M)\leq \D(M')$.

	To prove the third part assume that $G$ is a finite group acting effectively on $M$ with a fix point $x$. Let $C$ be the constant provided by the exporting map property and let $H$, $\phi':H\longrightarrow \Homeo(M')$ and $f_H$ be respectively the subgroup of $G$, the action on $M'$ and the continuous map homotopic to $f$ given by the assumptions. Since $x$ is a fixed point of the action of $H$ on $M$, $f_H(x)$ is a fixed point of the action of the effective $\phi'(H)$ on $M'$. If $C'$ is the small stabilizer constant on $M'$, then $|\phi'(H)|\leq C'$. We obtain the exact sequence 
	\[
	\begin{tikzcd}
		1\ar{r}{} &H_0\ar{r}{} &H\ar{r}{\phi'} &\phi'(H)\ar{r}{} &1
	\end{tikzcd}
	\]
	where $|H_0|\leq d=\deg(f)$ and $|\phi'(H)|\leq C'$. In consequence, $|H|\leq C'\cdot d$ and $|G|\leq C\cdot C'\cdot d$.

	The proof of the fourth part is analogous to the proof of the third part. If $C'$ denotes now the constant provided by the almost-asymmetric property of $M'$, then we have $|\phi'(H)|\leq C'$ and hence $|G|\leq C\cdot C'\cdot d$.
\end{proof}

Since $\Homeo(S^4)$ is Jordan and $\Homeo(T^2\times S^2)$ is not Jordan, we can deduce:

\begin{cor}
	Any non-zero degree map $f:T^2\times S^2\longrightarrow S^4$ is not an exporting map.
\end{cor}
Note also that $\D(T^2\times S^2)\geq 3> \D(S^4)=2$.

The next definition is the converse of the exporting map property.

\begin{defn}\label{pI defn}
	Let $M$ and $M'$ be closed oriented manifolds of the same dimension and let $f:M\longrightarrow M'$ be continuous map. We say that $f$ imports group actions, or it is an importing map, if there exists a constant $C$ such that any finite group $G$ acting on $M'$  has a subgroup $H\leq G$ such that:
	\begin{itemize}
		\item[1.] $[G:H]\leq C$.
		\item[2.] There exists a finite group $\tilde{H}$ acting effectively on $M$ and a surjective group morphism $\rho:\tilde{H}\longrightarrow H$.
		\item[3.] There exists a map $f_H:M\longrightarrow M'$ homotopic to $f$ which is $\rho$-equivariant ($f_H(hx)=\rho(h)f_H(x)$ for all $x\in M$ and $h\in\tilde{H}$).
	\end{itemize}
\end{defn}

\begin{rem}
	The property of importing group actions is similar to the property of propagating of group actions (see \cite[Definition 3.1]{adem2002topics}). Given a continuous map between closed manifolds $f:M\longrightarrow M'$ and a finite group $G$ acting effectively on $M'$, we that the action of $G$ on $M'$ propagates to $M$ across $f$ if there exists an effective action of $G$ on $M$ and an equivariant map $f_G:M\longrightarrow M'$ homotopic to $f$. Propagation of group actions was used to study group actions on homology spheres (see \cite[\S 3.2.2]{adem2002topics} and references therein).
\end{rem}

Importing and exporting maps have similar properties. The next lemma has an analogous proof to \cref{pE composition}.

\begin{lem}\label{pI composition}
	Let $M$, $M'$ and $M''$ be closed oriented manifolds and let $f:M\longrightarrow M'$ and $g:M'\longrightarrow M''$ be importing maps with constants $C$ and $D$ respectively. Then $g\circ f:M\longrightarrow M''$ imports group actions with constant $C\cdot D$.
\end{lem}

\begin{proof}
	Let $G$ be a finite group acting effectively on $M''$. Then there exist a subgroup $H\leq G$ satisfying that $[G:H]\leq D$, a group $\tilde{H}$ acting effectively on $M'$, a surjective group morphism $\rho':\tilde{H}\longrightarrow H$ and a $\rho$-equivariant map $g_H:M'\longrightarrow M''$. Since $\tilde{H}$ acts effectively on $M'$, there exist a subgroup $K\leq \tilde{H}$ satisfying that $[\tilde{H}:K]\leq C$, a group $\tilde{K}$ acting effectively on $M$, a surjective group morphism $\rho:\tilde{K}\longrightarrow K$ and a $\rho$-equivariant map $f_K:M\longrightarrow M'$. 

	We consider now the subgroup $\rho'(K)\leq G$. We note that $[G:\rho'(K)]\leq C\cdot D$, that $\rho'_{|K}\circ\rho: \tilde{K}\longrightarrow \rho'(K)$ is a surjective group morphism and that $g_H\circ f_K$ is $\rho'_{|K}\circ\rho$-equivariant and homotopic to $g\circ f$. Consequently, $g\circ f$ is an importing map.
\end{proof}

\begin{lem}\label{pI kernel non-zero degree}
	Let $M$ and $M'$ be closed oriented manifolds and $f:M\longrightarrow M'$ a non-zero degree importing map. Then $|\ker\rho|\leq \deg(f)$.
\end{lem}

\begin{proof}
	Since $f_H$ is $\rho$-equivariant, we have a commutative diagram 
	\[
	\begin{tikzcd}
		M \ar{r}{f_H}\ar{d}{\pi} & M'\\
		M/\ker\rho\ar{ru}{\overline{f}_H} &
	\end{tikzcd}
	\]

	By \cref{quotient map image degree}, $\pi^*(H^n(M/\ker\rho,\Z))\subseteq \deg(f)H^n(M,\Z)$. Therefore, $|\ker\rho|$ divides $\deg(f)$. Thus, $|\ker\rho|\leq \deg(f)$.
\end{proof}

The main example of importing maps are coverings of manifolds.

\begin{lem}\label{pI covering maps}
	Let $p:M\longrightarrow M'$ be a finite covering between closed oriented manifolds. Then $p$ imports group actions.
\end{lem}

\begin{proof}
	Assume that $p:M\longrightarrow M'$ is a $n$-sheeted covering and $G$ is a finite group acting effectively on $M'$. Then $G$ also acts on $\operatorname{Cov}_n(M')$, the set of $n$-sheeted coverings of $M'$ by pull-backs. On the other hand  $\operatorname{Cov}_n(M')\cong\Hom(\pi_1(M'),S_n)/\sim$ where $S_n$ is the $n$-th symmetric group and the equivalence relation is given by conjugation of elements of $S_n$. Therefore $\operatorname{Cov}_n(M')$ is finite, which implies that there exists a constant $C$ only depending on $M'$ and $n$ such that any finite group $G$ acting effectively on $M'$ has a subgroup $H$ which acts trivially on $\operatorname{Cov}_n(M')$ and $[G:H]\leq C$. Then we can lift the action of $H$ on $M'$ to an effective action of a group $\tilde{H}$ on $M$. In addition, there exists a surjective group morphism $\rho:\tilde{H}\longrightarrow H$ which makes the covering map $p:M\longrightarrow N$ $\rho$-equivariant. 
\end{proof}

We have the analogous result to \cref{pE jordan and discsym} for importing maps.

\begin{thm}\label{pI jordan and discsym}
	Let $M$ and $M'$ closed oriented manifolds which admit an importing map $f:M\longrightarrow M'$. Then:
	\begin{itemize}
		\item[1.] If $\Homeo(M)$ is Jordan, then $\Homeo(M')$ is Jordan.
		\item[2.] $\D(M')\leq \D(M)$.
		\item[3.] If $M$ has the almost fixed point property, then $M'$ has the almost fixed point property.
		\item[4.] If $M$ is almost asymmetric, then $M'$ is almost asymmetric.
	\end{itemize} 
\end{thm}

\begin{proof}
	The proof of items 1. and 2. are the same as in the case of finite coverings (see \cite{IgnasiMundetiRiera2010Jtft,mundet2021topological}). We prove the third part in detail.

	Let $G$ be a group acting effectively on $M'$. Let $C$ be the constant of the definition of the importing map $f$ and $H\leq G$, $f_H:M\longrightarrow M'$ and $\rho:\tilde{H}\longrightarrow H$ the data provided by the definition. Recall that $[G:H]\leq C$ and $\rho$ is surjective. The group $\tilde{H}$ acts effectively on $M$. Since $M$ has the almost fixed point property with constant $D$ there exists $x\in M$ such that $[\tilde{H}:\tilde{H}_x]\leq D$. We use now that $f_H$ is $\rho$-equivariant, therefore $\phi(\tilde{H}_x)\leq H_{f_H(x)}$. Since $\rho$ is surjective, $[H:H_{f_H(x)}]\leq [H:\rho(\tilde{H}_x)]\leq D$. Finally. we have $[G:G_{f_H(x)}]\leq [G:H_{f_H(x)}]\leq C\cdot D$. We have seen that $M'$ has the almost fixed point property with constant $C\cdot D$.

	The proof of the fourth part is analogous to the third part.
\end{proof}

With \cref{pI jordan and discsym} it is straightforward to find example of maps which are not importing. For example, since $\Homeo(T^4)$ is Jordan and $\Homeo(T^2\times S^2)$ is not Jordan, we have:

\begin{cor}
	Any non-zero degree map $f:T^4\longrightarrow T^2\times S^2$ is not an importing map.
\end{cor}

\begin{cor}
	Let $M$ and $M'$ be closed oriented manifolds and $f:M\longrightarrow M'$ a map which exports and imports group actions. Then $\D(M)=\D(M')$ and $\Homeo(M)$ is Jordan if and only if $\Homeo(M')$ is Jordan.
\end{cor}

We will see that finite coverings between nilmanifolds are an example of importing and exporting map.

\section[Large finite group actions and non-zero degree maps to nilmanifolds]{Large finite group actions on manifolds admitting a non-zero degree map to a nilmanifold}\label{sec: group action on hypernilmanifolds}

The goal of this section is to prove \cref{main theorem2 intro} and to give some applications of it. 

\subsection{Proof of \cref{main theorem2 intro}}

The main tool to prove \cref{main theorem2 intro} is the following result:

\begin{thm}\label{thm: exporting map hypernilmanifolds}
	Let $M$ be a closed oriented connected manifold and $f:M\longrightarrow N/\Gamma$ a non-zero degree map to a nilmanifold $N/\Gamma$. Then $f$ is an exporting map.
\end{thm}

We divide the proof of \cref{thm: exporting map hypernilmanifolds} in three parts. 

\textbf{Part 1:} In the first part we reduce the proof of \cref{thm: exporting map hypernilmanifolds} to the case where $f:M\longrightarrow N/\Gamma$ induces a surjective map between fundamental groups. 

First, we note that $f_*(\pi_1(M))$ is a finite index subgroup of $\Gamma$. Indeed, consider the diagram
\[\begin{tikzcd}
	& X \ar{d}{p}\\
	M\ar{ru}{f'}\ar{r}{f} & N/\Gamma
\end{tikzcd}\]
where $X$ is the covering space of $N/\Gamma$ associated to the subgroup $f_*(\pi_1(M))\leq \Gamma$ and $f'$ is a lift of $f$ (which exists by general properties of covering spaces). Since $f=p\circ f'$, the non-zero map  $f^*:H^n(N/\Gamma,\Z)\longrightarrow H^n(M,\Z)$ factors through $H^n(X,\Z)$. This implies that $H^n(X,\Z)$ is not zero and therefore $X$ is a  compact manifold. Since $p:X\longrightarrow N/\Gamma$ is a covering between compact manifolds, $p$ is a finite covering and $[\Gamma:f_*(\pi_1(M))]$ is finite.

Consequently, $f_*(\pi_1(M))=\Gamma'$ is also a lattice of $N$ and $X\cong N/\Gamma'$. By \cref{pE composition}, if we prove that $f'$ and $p$ are exporting maps then $f$ will be an exporting map.

\begin{lem}\label{pE nilmanifold covering}
	The covering $p$ is an exporting map. 
\end{lem}

\begin{proof}
	Since $\Gamma'$ is finitely generated and nilpotent, the group $\Out(\Gamma')$ is Minkowski by \cite{Wehrfritz1994}. Consequently, there exists a constant $C$ depending only on $\Gamma'$ satisfying that, if $G$ is a finite group acting effectively on $N/\Gamma'$ and $H$ is the kernel of the group morphism $\psi:G\longrightarrow \Out(\Gamma')$, then $[G:H]\leq C$. By \cite[Theorem 3.1.16]{lee2010seifert}, $H$ is isomorphic to a subgroup of the torus $\Zc N/\Zc \Gamma'$, and hence it is abelian. 

	Let $G$ be a finite group acting effectively on $N/\Gamma'$ and $H=\ker(\psi:G\longrightarrow \Out(\Gamma'))$. We claim that the action of $H$ on $N/\Gamma'$ is free. Given a point $x\in N/\Gamma'$, the isotropy subgroup $H_x$ injects into $\Aut(\Gamma')$. Since the action of $H$ on $N/\Gamma'$ is inner, $H_x$ is a subgroup of $\Inn(\Gamma')=\Gamma'/\Zc\Gamma'$. Since $\Gamma'$ is a finitely generated torsion-free nilpotent group, $\Inn(\Gamma')$ is torsion-free and therefore $H_x$ is trivial, as claimed. 

	The action of $H$ can be conjugated to an action of $H\leq\Zc N/\Zc \Gamma'$ obtained by restricting the standard torus action of $\Zc N/\Zc\Gamma'$ on $N/\Gamma'$ (see \cite[Remark 11.7.18.2]{lee2010seifert}). Thus, we can assume without loss of generality that $H\leq\Zc N/\Zc \Gamma'$ and the action of $H$ on $N/\Gamma'$ is induced by the restriction of the torus action $\Zc N/\Zc\Gamma'$ on $N/\Gamma'$. 

	The covering $p:N/\Gamma'\longrightarrow N/\Gamma$ is given by $p(n\Gamma')=n\Gamma$ for $n\in N$ and hence it is $N$-equivariant. Since $\Zc\Gamma'=\Zc N\cap \Gamma'$ and $\Zc\Gamma=\Zc N\cap \Gamma$, we have that $\Zc\Gamma'\leq\Zc\Gamma\leq \Zc N$. Consequently, we have a group morphism $\rho:\Zc N/\Zc\Gamma'\longrightarrow \Zc N/\Zc\Gamma$ between tori of the same dimension. 	

	We note that $p:N/\Gamma'\longrightarrow N/\Gamma$ is $\rho$-equivariant. Since $H\leq \Zc N/\Zc\Gamma'$, we have an action of $H$ on $N/\Gamma$ 
	given by $h(n\Gamma)=\rho(h)(n\Gamma)$. This implies that $p$ is an exporting map, as we wanted to prove.
\end{proof}

In particular, $p:N/\Gamma'\longrightarrow N/\Gamma$ is an exporting map. It remains to prove that $f'$ is also an exporting map. 

Thus, from now on we will assume that $f:M\longrightarrow N/\Gamma$ induces a surjective morphism $f_*:\pi_1(M)\longrightarrow \Gamma$.

\textbf{Part 2:} Let $i:\Gamma\hookrightarrow N$ denote the inclusion of the lattice $\Gamma$ in $N$. For this part of the proof we consider the set of isomorphism classes $N$-local systems $X(\pi_1(M),N)=\Hom(\pi_1(M),N)/\!\!\sim$, where $\sim$ denotes the equivalence relation given by the conjugation by elements of $N$. An effective action of a finite group $G$ on $M$ induces an action of $G$ on $X(\pi_1(M),N)$ (this action is described explicitly in the proof of \cref{pE local systems}). Our goal is to prove that if $G$ fixes the class $[i\circ f_*]\in X(\pi_1(M),N)$ then there exists an action of $G$ on $N/\Gamma$ and a $G$-equivariant map $f_G:M\longrightarrow N/\Gamma$ which is homotopic to $f$. We will use induction on the dimension of $N$.

%Recall that this set is in one to one correspondence with principal $N$-bundles over $M$ which admit a collection of local trivializations which cover $M$ and whose transition maps are locally constant. If $M$ is a smooth manifold, then $\Hom(\pi_1(M),N)/\sim$ is in one to one correspondence with flat $N$-bundles over $M$ (see \cite[Chapter 2]{morita2001geometry}).

We start with the following lemma, which is a generalization of \cite[Lemma 4.2]{mundet2021topological} to non-compact manifolds. The arguments used to prove \cref{pE S1} and \cite[Lemma 4.2]{mundet2021topological} are essentially the same. 

%\begin{lem}\label{pE S1}\cite[Lemma 4.2]{mundet2021topological}
%	Let $M$ be a closed connected manifold, let $f:M\longrightarrow S^1$ be a continuous map and let $\theta$ be a generator of $H^1(S^1,\Z)$. Suppose that $G$ is a finite group acting effectively on $M$ fixing $f^*\theta$. Then there exists a group action of $\phi':G\longrightarrow\Homeo(S^1)$ such that $G/\ker\phi'$ acts by rotations on $S^1$ and a $G$-equivariant map $f_G:M\longrightarrow S^1$ homotopic to $f$.
%\end{lem}

\begin{lem}\label{pE S1}
	Let $M$ be a connected manifold, let $f:M\longrightarrow S^1$ be a continuous map and let $\theta$ be a generator of $H^1(S^1,\Z)$. Suppose that $H$ is a finite group of cardinal $r$ acting effectively on $M$ fixing $f^*\theta$. Consider the group extension $$1\longrightarrow \pi_1(M)\longrightarrow \tilde{H}\longrightarrow H\longrightarrow 1,$$ where the group $\tilde{H}$ acts effectively on the universal cover $\tilde{M}$. Then there exists a group morphism $\tilde{\mu}:\tilde{H}\longrightarrow \R$ and a $\tilde{\mu}$-equivariant map $\tilde{f}_H: \tilde{M}\longrightarrow \R$ such that $\tilde{\mu}_{|\pi_1(M)}=f_*$.
\end{lem}

\begin{proof}
	Define $F:M \to S^1$ by $\zeta(x) = \sum_{h \in H} f(h \cdot x)$ for every $x \in M$. Then $F$ is continuous and constant on the orbits of the action of $H$. Let $\phi_h: M \to M$ be the homeomorphism induced by the action of $h\in H$. By assumption, $\phi_h^* f^* \theta = f^* \theta$ for every $h\in H$. We have $F^* \theta = \sum_{h \in H} \phi_h^* (f^* \theta) = r f^* \theta$.

	Consider the $\Z/r$-covering $p_r:S^1\longrightarrow S^1$ defined as $p_r(t)=rt$. Let $q_r:M_r \longrightarrow M$ the pull-back of $p_r$ by $F$. Recall that $M_r=\{(x, t) \in M \times S^1 :F(x)=rt\}$ and $q_r:M_r \longrightarrow M$ satisfies $q_r(x,t)=x$ for $(x,t)\in M_r$. Moreover, $q_r:M_r \longrightarrow M$ has a structure of principal $\Z/r$ given by the action $(x,t)\cdot\alpha=(x,t\alpha)$ for $(x,t)\in M_r$ and $\alpha\in\Z/r$. 

	We claim that $q_r$ is a trivial principal bundle. This is equivalent to the triviality of the monodromy of $q_r$, which we denote by $\nu:\pi_1(M, x_0) \to \Z/r$, where $x_0\in M$ is an arbitrary base point. If there existed some $\gamma \in \pi_1(X, x_0)$ such that $\nu(\gamma) \neq 0$, then the pairing of $f^* \theta$ with $[\gamma] \in H_1(X,\Z)$ would not be divisible by $r$, which contradicts $F^* \theta = r f^* \theta$.
	Hence $\nu$ is trivial and consequently, the bundle $q_r$ is a trivial, so we may choose a section $\sigma: M\longrightarrow  M_r$. 

	Define $f_H: M\longrightarrow S^1$ by the condition that $\sigma(x) = (x, f_H(x))$. Then $f_H$ is continuous and we have $rf_H(x)=F(x)$ for every $x\in M$. For any $h\in H$, define $\chi_h: M \to S^1$ by $$\chi_h(x) = f_H(h \cdot x) - f_H(x).$$

	We have $$r\chi_h(x) = r f_H(h \cdot x) - r f_H(x) = F(h\cdot x) - F(x) = 0$$
	because $F$ is $H$-invariant. Hence $\chi_h$ takes values in $\Z/r\leq S^1$. Consequently, since $\chi_h$ is continuous, it is a constant map. We may thus define a map $\mu: H \longrightarrow \Z/r$ by the condition that $\mu(h)= \chi_h(x)$ for every $x \in X.$

	Let $h,h'\in H$ and let $x \in X$. We have $$
	\chi_{hh'}(x) = f_H(hh' \cdot x) - f_H(x) = f_H(hh' \cdot x) - f_H(h' \cdot x) + f_H(h' \cdot x) - f_H(x) = \chi_h(h' \cdot x) + \chi_{h'}(x),$$
	which proves that $\mu(hh') = \mu(h) + \mu(h')$, so $\mu$ is a morphism of groups. 
	From the definition of $\mu$, it is immediate that $f_H$ is $\mu$-equivariant.

	To conclude the proof, note that $rf_H^* \theta = F^* \theta = rf^* \theta$. 
	Since $H^1(X; \mathbb{Z})$ has no torsion, we conclude that $f_H^* \theta = f^*\theta$. Thus, $f_*:\pi_1(M)\longrightarrow \Z$ and $f_{H*}:\pi_1(M)\longrightarrow \Z$ are equal. We can lift $f_H$ to a map between the universal coverings $\tilde{f}_H:\tilde{M}\longrightarrow \R$. Since $f_H$ is $\mu$-equivariant, we have a commutative diagram 
	\[\begin{tikzcd}
		1\ar{r}{}&\pi_1(M)\ar{r}{}\ar{d}{f_{H*}}&\tilde{H}\ar{r}{}\ar{d}{\tilde{\mu}}&H\ar{r}{}\ar{d}{\mu}&1\\
		1\ar{r}{}&\Z\ar{r}{}&\Z\ar{r}{\tilde{\pi}}&\Z/r\ar{r}{}&1.
	\end{tikzcd}\]
\end{proof}

\begin{lem}\label{pE local systems}
	Let $M$ be a closed connected oriented manifold and let $f:M\longrightarrow N/\Gamma$ be a map such that $f_*(\pi_1(M))=\Gamma$. Assume that $H$ is a finite group acting effectively on $M$ which fixes the local system $[i\circ f_*]\in X(\pi_1(M),N)$. Consider the group extension $$1\longrightarrow \pi_1(M)\longrightarrow \tilde{H}\longrightarrow H\longrightarrow 1,$$ where the group $\tilde{H}$ acts effectively on the universal cover $\tilde{M}$. Then there exists a group morphism $\tilde{\mu}:\tilde{H}\longrightarrow N$ and a $\tilde{\mu}$-equivariant map $\tilde{f}_H: \tilde{M}\longrightarrow N$ such that $\tilde{\mu}_{|\pi_1(M)}=f_*$.
\end{lem}

Before proving \cref{pE local systems}, we deduce the next corollary.

\begin{cor}
	Let $M$ be a closed connected oriented manifold and $f:M\longrightarrow N/\Gamma$ be a non-zero degree map such that $f_*(\pi_1(M))=\Gamma$. Assume that $H$ is a finite group acting effectively on $M$ which fixes the local system $[i\circ f_*]\in X(\pi_1(M),N)$. Then there exists a group action of $H$ on $N/\Gamma$ and an equivariant map $f_H:M\longrightarrow N/\Gamma$ homotopic to $f$.
\end{cor}

\begin{proof}
	Since $\tilde{\mu}_{|\pi_1(M)}=i\circ f_*$, the map $\tilde{f}_H:\tilde{M}\longrightarrow N$ induces a map $f_H:M\longrightarrow N/\Gamma$. Moreover, $\tilde{\mu}:\tilde{H}\longrightarrow N$ induces a surjective group morphism $\mu':\tilde{H}/\pi_1(M)=H\longrightarrow \tilde{\mu}(\tilde{H})/\Gamma$ such that $f_H$ is $\mu'$-equivariant. Thus, we have an action $H\longrightarrow \tilde{\mu}(\tilde{H})/\Gamma\longrightarrow \Homeo(N/\Gamma)$ and $f_H$ is $H$-equivariant. Finally, since $N/\Gamma$ is a model of the Eilenberg-MacLane space $K(\Gamma,1)$ and $[\tilde{\mu}_{|\pi_1(M)}]=[i\circ f_*]$, the maps $f$ and $f_H$ are homotopic. 
\end{proof}

\begin{rem}
	Note that the action of $\tilde{\mu}(\tilde{H})/\Gamma$ is free and the quotient $(N/\Gamma)/(\tilde{\mu}(\tilde{H})/\Gamma) $ is the nilmanifold $N/\tilde{\mu}(\tilde{H})$.
\end{rem}

\begin{proof}[Proof of \cref{pE local systems}]
	We proceed by induction on the dimension of the nilmanifold $N/\Gamma$. Assume that $\dim(N/\Gamma)=1$. Then $N/\Gamma\cong S^1$ and the statement is a consequence of \cref{pE S1}. For the induction step, we can take central exact sequences 
	\[\begin{tikzcd}
		1\ar{r}{}&\R\ar{r}{}&N\ar{r}{\tilde{\pi}}&N'\ar{r}{}&1
	\end{tikzcd}\]
	and 
	\[\begin{tikzcd}
		1\ar{r}{}&\R\cap\Gamma\cong\Z\ar{r}{}&\Gamma\ar{r}{\pi_*}&\Gamma'\ar{r}{}&1,
	\end{tikzcd}\] where $\pi_*=\tilde{\pi}_{|\Gamma}$. They induce a principal $S^1$-bundle, $\pi:N/\Gamma\longrightarrow N'/\Gamma'$. Since the short exact sequences are central, we can choose a normalized 2-cocycle $c:N'\times N'\longrightarrow \R$ such that $N\cong \R\times_c N'$ and $\Gamma\cong \Z\times_{c_{|\Gamma'\times\Gamma'}}\Gamma'$. Note that $\dim(N'/\Gamma')=\dim(N/\Gamma)-1$.

	We denote $\mu=i\circ f_*$. We have an action of $\tilde{H}$ on $X(\pi_1(M),N)$ satisfying that $\tilde{h}[\nu]=[\nu\circ c_{\tilde{h}|\pi_1(M)}]$ for all $\tilde{h}\in\tilde{H}$ and $[\nu]\in X(\pi_1(M),N)$. If the action of $H$ on $X(\pi_1(M),N)$ fixes $[\mu]$ then the action of $\tilde{H}$ also fixes $[\mu]$. This is a consequence of the fact that the action of $\tilde{H}$ on $X(\pi_1(M),N)$ factors through the action of $H$ on $X(\pi_1(M),N)$, since the restriction to $\pi_1(M)$ of the action of $\tilde{H}$ on $X(\pi_1(M),N)$ is trivial.

	This condition implies that there exists a map (which is not a group morphism in general) $a:\tilde{H}\longrightarrow N$ such that $\mu\circ c_{\tilde{h}|\pi_1(M)}=c_{a(\tilde{h})}\circ \mu$. Note that $a:\tilde{H}\longrightarrow N$ is not unique. If we have another map $a':\tilde{H}\longrightarrow N$ with the same property, then $c_{a'(\tilde{h})}\circ \mu=\mu\circ c_{\tilde{h}|\pi_1(M)} =c_{a(\tilde{h})}\circ \mu$ and hence $c_{a(\tilde{h})^{-1}a'(\tilde{h})}\circ \mu=\mu$. Therefore, $a(\tilde{h})^{-1}a'(\tilde{h})$ centralizes the lattice $\Gamma$ and hence $a(\tilde{h})^{-1}a'(\tilde{h})\in\Zc N$ for all $\tilde{h}\in\tilde{H}$.

	The action of $\tilde{H}$ fixes $[\tilde{\pi}\circ \mu]\in X(\pi_1(M),N')$. Since $\pi_*:\Gamma\longrightarrow\Gamma'$ is surjective, the group morphism $\pi_*\circ f_*:\pi_1(M)\longrightarrow \Gamma'$ is surjective and, by induction, there exists a group morphism $\tilde{\mu}_B:\tilde{H}\longrightarrow N'$ and a $\tilde{\mu}_B$-equivariant map $\tilde{f}'_B:\tilde{M}\longrightarrow N'$ such that $\tilde{\mu}_{B|\pi_1(M)}=\tilde{\pi}\circ \mu$. 

	Consequently, we have a surjective group morphism $\mu_B:\tilde{H}/\pi_1(M)\cong H\longrightarrow \tilde{\mu}_B(\tilde{H})/\Gamma'$. Thus, we can define an action of $H$ on $N'/\Gamma'$ (which may not be effective) given by $h(n\Gamma')=\mu_B(h)(n\Gamma')$. The map $\tilde{f}'_B:\tilde{M}\longrightarrow N'$ induces an $H$-equivariant map $f'_B:M\longrightarrow N'/\Gamma'$ homotopic to $\pi\circ f$. Since $f'_{B*}:\pi_1(M)\longrightarrow \Gamma'$ factors through $\pi_*:\Gamma\longrightarrow\Gamma'$, there exists a map $f_B:M\longrightarrow N/\Gamma$ homotopic to $f$ such that $\pi\circ f_B=f'_B$.
	We can lift $f_B$ to a map $\tilde{f}_B:\tilde{M}\longrightarrow N\cong \R\times_c N'$. Note that $\tilde{f}_B$ is $\mu$-equivariant and $\tilde{\pi}\circ \tilde{f}_B$ is $\tilde{\mu}_B$-equivariant.

	We now consider the group $\tilde{H}_0=\ker\tilde{\mu}_B$ and $Z_0=\mu^{-1}(\ker\tilde{\pi})\leq\pi_1(M)$ (recall that $\ker\tilde{\pi}\cong\R$). Notice that $Z_0=\tilde{H}_0\cap \pi_1(M)$. Let $g\in \tilde{H}_0\cap \pi_1(M)$. Then $\tilde{\mu}_B(g)=\tilde{\pi}(\mu(g))=0$, which implies that $g\in Z_0$. Conversely, if $g\in Z_0$, then $g\in \pi_1(M)$. Therefore, $\tilde{\mu}_B(g)=\tilde{\pi}(\mu(g))=0$, which implies that $g\in\tilde{H}_0$. Consequently, $g\in \tilde{H}_0\cap \pi_1(M)$. In conclusion, $Z_0=\mu^{-1}(\ker\tilde{\pi})\leq\pi_1(M)$. Therefore $Z_0$ is a normal subgroup of $\tilde{H}_0$. Moreover, $H_0=\tilde{H}_0/Z_0$ is a subgroup of $H$ and hence $Z_0$ is a finite index subgroup of $\tilde{H}_0$. 

	Since $Z_0\leq\pi_1(M)$, $\tilde{f}_B:\tilde{M}\longrightarrow N$ induces a map $\tilde{M}/Z_0\longrightarrow N/\Z\cong S^1\times_c N'$. We obtain a map $f_Z:\tilde{M}/Z_0\longrightarrow S^1$ by composing it with the projection to the $S^1$ factor. We also get an effective action of the finite group $H_0$ on $\tilde{M}/Z_0$. We consider $\mu_Z:Z_0\longrightarrow \R$, which is the composition $f_{Z*}:Z_0\longrightarrow \Z$ and the inclusion $i_Z=i_{|\Z}:\Z\longrightarrow \R\leq \Zc N$. The group morphism $\mu_Z$ is the restriction of the map $\mu$ to $Z_0$, $\mu_Z=\mu_{|Z_0}$. 

	The action of $H_0$ on $X(Z_0,\R)=\Hom(Z_0,\R)$ induces an action of $\tilde{H}_0$ on $X(Z_0,\R)$ satisfying $\tilde{h}\cdot\nu=\nu\circ c_{\tilde{h}|Z_0}$ for $\nu\in X(Z_0,\R)$ and $\tilde{h}\in \tilde{H}_0$. This action satisfies $$\tilde{h}\cdot\mu_{Z}=\mu_{|Z_0}\circ c_{\tilde{h}|Z_0}=c_{a(\tilde{h})}\circ \mu_{|Z_0}=\mu_{|Z_0}$$ where the last equality holds because the image of $\mu_{|Z_0}$ lies on the center of $N$. Consequently, the group $\tilde{H}_0$ (and hence $H_0$) fixes $\mu_Z\in X(Z_0,\R)$. We can use \cref{pE S1} to conclude that there exists a group morphism $\tilde{\mu}_Z:\tilde{H}_0\longrightarrow \R$ satisfying $\tilde{\mu}_{Z|Z_0}=\mu_Z$ and a $\tilde{\mu}_Z$-equivariant map $\tilde{f}_Z:\tilde{M}\longrightarrow \R$. 

	Summarizing the proof until this point, we have obtained two group morphisms $\tilde{\mu}_B$ and $\tilde{\mu}_Z$ satisfying
	\[\begin{tikzcd}
		1\ar{r}{}&\tilde{H}_0\ar{r}{}\ar{d}{\tilde{\mu}_Z}&\tilde{H}\ar{r}{\tilde{\pi}}&\tilde{H}/\tilde{H}_0\ar{r}{}\ar{d}{\overline{\mu}_B}&1\\
		1\ar{r}{}&\R\ar{r}{}&N\ar{r}{\tilde{\pi}}&N'\ar{r}{}&1
	\end{tikzcd}\]
	where $\overline{\mu}_B:\tilde{H}/\tilde{H}_0\longrightarrow N'$ is an injective group morphism induced by $\tilde{\mu}_B$. We also have a map $\tilde{f}:\tilde{M}\longrightarrow N$ of the form $\tilde{f}=(\tilde{f_Z},\tilde{f}'_B)$. Our goal is to construct a group morphism $\tilde{\mu}:\tilde{H}\longrightarrow N$ making the above diagram commutative.

	Firstly, we note that $\ker\mu$ is a normal subgroup of $\tilde{H}$, since the action of $\tilde{H}$ fixes $[\mu]$. Let $\tilde{\Gamma}=\tilde{H}/\ker\mu$, let $\tilde{\Gamma}_0=\tilde{H}_0/\ker\mu$ and let $\tilde{\nu}_Z:\tilde{\Gamma}_0\longrightarrow \R$ be the group morphism induced by $\tilde{\mu}_Z$. We have a commutative diagram
	\[\begin{tikzcd}
		1\ar{r}{}&\tilde{\Gamma}_0\ar{r}{}\ar{d}{\tilde{\nu}_Z}&\tilde{\Gamma}\ar{r}{\tilde{\pi}}&\tilde{H}/\tilde{H}_0\ar{r}{}\ar{d}{\overline{\mu}_B}&1\\
		1\ar{r}{}&\R\ar{r}{}&N\ar{r}{\tilde{\pi}}&N'\ar{r}{}&1
	\end{tikzcd}\]
	Let $K$ denote $\ker \tilde{\nu}_Z=\ker\tilde{\mu}_Z/\ker\mu$. We note that $K$ injects in $H_0$ and therefore it is finite. Since $\tilde{\nu}_Z(\tilde{\Gamma}_0)$ is torsion-free, the subgroup $K$ is characteristic in $\tilde{\Gamma}_0$. Thus, $K$ is a normal subgroup of $\tilde{\Gamma}$. Let $\Lambda=\tilde{\Gamma}/K$, $\Lambda_0=\tilde{\Gamma}_0/K\cong\Z$ and $\Lambda'=\tilde{H}/\tilde{H}_0$. We also denote by $\overline{\mu}_B: \Lambda_0\longrightarrow \R$ the group morphism induced by $\tilde{\nu}_Z$. We have a commutative diagram 
	\[\begin{tikzcd}
		1\ar{r}{}&{\Lambda}_0\ar{r}{}\ar{d}{\overline{\mu}_Z}&\Lambda\ar{r}{\tilde{\pi}}&\Lambda'\ar{r}{}\ar{d}{\overline{\mu}_B}&1\\
		1\ar{r}{}&\R\ar{r}{}&N\ar{r}{\tilde{\pi}}&N'\ar{r}{}&1
	\end{tikzcd}\]
	Moreover, note that $\Gamma\cap K$ is the identity element, therefore $\Gamma$ is a finite index subgroup of $\Lambda$. Note also that $\Lambda$ is torsion-free, finitely generated and nilpotent, hence $\Lambda$ is a lattice of $N$. Using the inclusion $i:\Gamma\longrightarrow N$, we can define inclusions $i_B:\Gamma'\longrightarrow N'$ and $i_Z:\Gamma_0\cong\Z\longrightarrow \R$, obtaining the following commutative diagram
	\[\begin{tikzcd}
		1\ar{r}{}&{\Gamma}_0\ar{rr}{}\ar[hook]{rd}{}\ar[swap]{rdd}{i_Z}&&\Gamma\ar{rr}{}\ar[hook]{rd}{}\ar[swap]{rdd}{i}&&\Gamma'\ar{r}{}\ar[hook]{rd}{}\ar[swap]{rdd}{i_B}&1&\\
		&1\ar{r}{}&{\Lambda}_0\ar{rr}{}\ar{d}{\overline{\mu}_Z}&&\Lambda\ar{rr}{\tilde{\pi}}&&\Lambda'\ar{r}{}\ar{d}{\overline{\mu}_B}&1\\
		&1\ar{r}{}&\R\ar{rr}{}&&N\ar{rr}{\tilde{\pi}}&&N'\ar{r}{}&1
	\end{tikzcd}\]

	The inclusion $\Gamma\leq \Lambda$ induces the identity map between the real Mal'cev completions $\Gamma_\R$ and $\Lambda_\R$ (see the survey \cite{dekimpe2016users} for the definition and main properties of the Mal'cev completion of torsion-free finitely generated nilpotent groups). Consequently, we have a commutative diagram
	\[\begin{tikzcd}
		1\ar{r}{}&({\Gamma}_0)_\R\ar{rr}{}\ar{rd}{Id}\ar[swap]{rdd}{(i_Z)_\R}&&\Gamma_\R\ar{rr}{}\ar{rd}{Id}\ar[swap]{rdd}{i_\R}&&\Gamma'_\R\ar{r}{}\ar{rd}{Id}\ar[swap]{rdd}{(i_B)_\R}&1&\\
		&1\ar{r}{}&({\Lambda}_0)_\R\ar{rr}{}\ar{d}{(\overline{\mu}_Z)_\R}&&\Lambda_\R\ar{rr}{\tilde{\pi}}&&\Lambda'_\R\ar{r}{}\ar{d}{(\overline{\mu}_B)_\R}&1\\
		&1\ar{r}{}&\R\ar{rr}{}&&N\ar{rr}{\tilde{\pi}}&&N'\ar{r}{}&1
	\end{tikzcd}\]
	Therefore, if we set $\overline{\mu}=i_{\R|\Lambda}:\Lambda\longrightarrow N$, we obtain a commutative diagram
	\[\begin{tikzcd}
		1\ar{r}{}&{\Lambda}_0\ar{r}{}\ar{d}{\overline{\mu}_Z}&\Lambda\ar{r}{\tilde{\pi}}\ar{d}{\overline{\mu}}&\Lambda'\ar{r}{}\ar{d}{\overline{\mu}_B}&1\\
		1\ar{r}{}&\R\ar{r}{}&N\ar{r}{\tilde{\pi}}&N'\ar{r}{}&1
	\end{tikzcd}\]
	The desired group morphism $\tilde{\mu}:\tilde{H}\longrightarrow N$ is obtained by composing the $\overline{\mu}$ with the projection $\tilde{H}\longrightarrow\Lambda$. By construction, the map $\tilde{f}:\tilde{M}\longrightarrow N$ is $\tilde{\mu}$-equivariant and $\tilde{\mu}_{|\pi_1(M)}=\mu$, as we wanted to see.
\end{proof}

\textbf{Part 3:} The last step of the proof of \cite[Theorem 4.1]{mundet2021topological} is a consequence of Minkowski's lemma.

\begin{lem}\label{pE local systems trivial action}
	Let $M$ be a closed connected oriented manifold and let $f:M\longrightarrow N/\Gamma$ be a non-zero degree map such that $f_*(\pi_1(M))=\Gamma$. There exists a constant $C$ such that any finite group $G$ acting effectively on $M$ has a finite subgroup $H\leq G$ such that $[G:H]\leq C$ and $H$ acts trivially on $X(\pi_1(M),N)$.
\end{lem}

\begin{proof}
	We denote by $\pi_1(M)^j$ the $j$-th element of the lower central series. Assume that the nilpotency class of $N$ is $c$, then for any $\nu\in \Hom(\pi_1(M),N)$ we have $\pi_1(M)^{c}\leq \ker \nu$. In consequence, the projection $\pi_1(M)\longrightarrow \pi_1(M)/\pi_1(M)^c$ induces a bijection $\Hom(\pi_1(M)/\pi_1(M)^c,N)\longrightarrow \Hom(\pi_1(M),N)$. This bijection descends to a bijection between the sets of isomorphism classes of $N$-local systems $X(\pi_1(M),N)$ and $X(\pi_1(M)/\pi_1(M)^c,N)$.

	Since $\pi_1(M)^{c}$ is a characteristic subgroup of $\pi_1(M)$, any automorphism $\phi:\pi_1(M)\longrightarrow \pi_1(M)$ induces and automorphism $\overline{\phi}:\pi_1(M)/\pi_1(M)^{c}\longrightarrow \pi_1(M)/\pi_1(M)^{c}$ given by $\overline{\phi}(\gamma\pi_1(M)^{c})=\phi(\gamma)\pi_1(M)^{c}$. Hence there is a group morphism $\rho:\Out(\pi_1(M))\longrightarrow \Out(\pi_1(M)/\pi_1(M)^{c})$ which sends $[\phi]$ to $[\overline{\phi}]$. 

	Notice that the bijection between $X(\pi_1(M),N)$ and $X(\pi_1(M)/\pi_1(M)^c,N)$ is $\rho$-equivariant. If $\psi: G\longrightarrow \Out(\pi_1(M))$ is the map induced by the action of $G$ on $M$, then we have an action of $G$ on $X(\pi_1(M)/\pi_1(M)^c,N)$ given by $[f]g=[f](\rho\circ\psi)(g)$. Since $\pi_1(M)/\pi_1(M)^{c}$ is finitely generated and nilpotent, $ \Out(\pi_1(M)/\pi_1(M)^c)$ is Minkowski by \cite{Wehrfritz1994}. Hence, there exists a constant $C$ such that any finite subgroup of $\Out(\pi_1(M)/\pi_1(M)^{c})$ is at most of order $C$. Thus, $H=\ker(\rho\circ\psi)$ is a subgroup of $G$ such that $[G:H]\leq C$ which acts trivially on $X(\pi_1(M)/\pi_1(M)^c,N)$ and hence it also acts trivially on $X(\pi_1(M),N)$.
\end{proof}

By combining \cref{pE local systems}, \cref{pE local systems trivial action} and \cref{pE nilmanifold covering} we complete the proof of \cref{thm: exporting map hypernilmanifolds}. 

Finally, we prove \cref{main theorem2 intro}. 

\begin{proof}[Proof of \cref{main theorem2 intro}]
	By \cite[Theorem 1.6, Theorem 1.9]{daura2024actions}, we have that:
	\begin{itemize}
		\item[1.] $\Homeo(N/\Gamma)$ is Jordan.
		\item[2.] $\D(N/\Gamma)\leq\rank\Zc\Gamma$.
		\item[3.] $N/\Gamma$ has small stabilizers.
	\end{itemize}

	Thus, the first part of \cref{main theorem2 intro} is a direct consequence of \cref{pE jordan and discsym} and \cref{thm: exporting map hypernilmanifolds}. For the second part, the bound of the discrete degree of symmetry is also a consequence of \cref{pE jordan and discsym} and \cref{thm: exporting map hypernilmanifolds}. If we assume $\D(M)=n$, then $\rank\Zc\Gamma\geq n$. This implies that $\Gamma\cong\Z^n$ and $N/\Gamma\cong T^n$. In consequence, the theorem follows from \cref{large group actions hypertoral manifolds}.

	For the third part, note that $M$ has the almost fixed point property by \cref{almost fix point euler char}. Since $M$ has the small stabilizers property (by \cref{pE jordan and discsym} and \cref{thm: exporting map hypernilmanifolds}) and the almost fixed point property, $M$ is almost asymmetric, by \cref{small stab+almost fixed point=almost asymmetric}.

	The fourth part is a consequence of $M$ having the small stabilizers property and $\Homeo(M)$ being Jordan, see \cite[Lemma 3.6]{daura2024actions}.
\end{proof}

Note that the conclusion of \cite[Corollary 1.6]{mundet2021topological} also holds for closed connected oriented manifolds admitting a non-zero degree map to a nilmanifold.

\begin{cor}
	Let $M$ be a closed connected oriented $n$-dimensional manifold admitting a non-zero degree map to a nilmanifold $f:M\longrightarrow N/\Gamma$. If $\D(M)=n$ and $\pi_1(M)$ is virtually solvable then $M$ is homeomorphic to $T^n$.
\end{cor}

Let us show some applications and remarks of \cref{main theorem2 intro}, which we divide in four subsections.

\subsection{The toral rank and stable Carlsson's conjecture}

The first application is \cref{TRC hypernilmanifolds intro}, where we show new examples where the toral rank conjectures and the stable Carlsson's conjecture are true. To do so, we need the following lemma.

\begin{lem}\label{TRC=SCC}
Let $M$ be a closed connected aspherical locally homogeneous space. The toral rank conjecture holds for $M$ if and only if the stable Carlsson's conjecture holds for $M$.
\end{lem}

\begin{proof}
Since $H^*(M,\Z)$ is finitely generated, we can use the universal coefficients theorem to conclude that there exists a constant $C_1$ such that for all prime $p>C_1$ we have $\dim H^*(M,\Q)=\dim H^*(M,\Z/p)$. By \cite[Theorem 1.9]{daura2024actions}, $\Out(\pi_1(M))$ and $\Aut(\pi_1(M))$ are Minkowski. Let $C_2$ and $C_3$ denote the Minkowski constant of $\Out(\pi_1(M))$ and $\Aut(\pi_1(M))$ respectively. 

For all primes $p>C_2$, we have that $\rank_p(M)\leq \rank \Zc\pi_1(M)$, by \cite[Theorem 3.1.16]{lee1987manifolds}. In addition, for all primes $p>C_3$ any effective action of a $p$-group on $M$ is free, by \cite[Corollary 3.1.17]{lee2010seifert}. Consequently, $\rank(M)\leq \rank_p(M)$ for $p>C_3$. Finally, $\rank(M)=\rank\Zc\pi_1(M)$ by \cite[Theorem 1.10]{daura2024actions} and \cite[Corollary 3.1.17]{lee2010seifert}. Thus, if $p>\max\{C_2,C_3\}$, then $\rank(M)=\rank_p(M)=\rank\Zc\pi_1(M)$. Set $C=\max\{C_1,C_2,C_3\}$.

We assume now that the toral rank conjecture holds for $M$, hence $\dim H^*(M,\Q)\geq 2^{\rank(M)}=2^{\rank(\Zc\pi_1(M))}$. For all primes $p>C$ we have $\dim H^*(M,\Z/p)=\dim H^*(M,\Q)\geq 2^{\rank(\Zc\pi_1(M))}=2^{\rank_p(M)}$ and therefore the stable Carlsson's conjecture holds for $p>C$.

Now, we prove the converse statement. Thus, we assume that there exists a constant $D$ such that for all primes $p>D$, we have $\dim H^*(M,\Z/p)\geq 2^{\rank_p(M)}$. Choose a prime $p>\max\{D,C\}$. Then $\rank_p(M)=\rank(M)$ and we have $\dim H^*(M,\Q)=\dim H^*(M,\Z/p)\geq 2^{\rank_p(M)}= 2^{\rank(M)}$. Hence, the toral rank conjecture holds for $M$. 
\end{proof}


\begin{proof}[Proof of \cref{TRC hypernilmanifolds intro}]
	Let $f:M\longrightarrow N/\Gamma$ be a non-zero degree map and assume that the toral rank conjecture holds for $N/\Gamma$. Recall that $\D(N/\Gamma)=\rank(N/\Gamma)=\rank\Zc\Gamma$ (this is a consequence of \cref{main theorem1 intro} and \cite[Corollary 11.7.4, Theorem 11.7.7]{lee2010seifert}). 
	Thus, $\rank(M)\leq \A(M)\leq \D(M)\leq \rank\Zc\Gamma$. Since $f$ has non-zero degree, the induced morphism $f^*:H^*(N/\Gamma,\Q)\longrightarrow H^*(M,\Q)$ is injective and therefore 
	$$\dim H^*(M,\Q)\geq \dim H^*(N/\Gamma,\Q)\geq 2^{\rank(\Zc\Gamma)}\geq 2^{\rank(M)}, $$
	as we wanted to see.

	Since the toral rank conjecture holds for $N/\Gamma$, the stable Carlsson's conjecture also holds for $N/\Gamma$ by \cref{TRC=SCC}. Let $C$ denote the constant provided stable Carlsson's conjecture.

	Let $D$ denote the exporting map constant of $f$. Note that if $(\Z/p)^r$ acts freely on $M$ with $p\geq \max\{D,\deg(f)\}$, then $(\Z/p)^r$ acts freely on $N/\Gamma$. In particular, $\rank_p(M)\leq \rank_p(N/\Gamma)$ for all $p>\max\{D,\deg(f)\}$. Let $C'=\max\{D,\deg(f),C\}$. Then for all $p>C'$ we have $$\dim H^*(M,\Z/p)\geq \dim H^*(N/\Gamma,\Z/p)\geq 2^{\rank_p(N/\Gamma)}\geq 2^{\rank_p(M)},$$
	and the stable Carlsson's conjecture holds for $M$.
\end{proof}

\subsection{Closed connected manifolds with non-zero degree maps to solvmanifolds}

\Cref{main theorem2 intro} is false if we replace nilmanifold by solvmanifold. In order to give an example of a non-zero degree map between solvmanifolds which does not export group actions we need the following elementary group theoretic lemma.

\begin{lem}\label{center semidriect product}
	Let $G_1$ and $G_2$ be groups and let $\phi:G_2\longrightarrow \Aut(G_1)$ be a group morphism. Then $$\Zc(G_1\rtimes_\phi G_2)=\{(g_1,g_2)\in G_1\rtimes_\phi G_2: g_2\in \Zc G_2, g_1\in \operatorname{Fix}(\phi) \text{ and }\phi(g_2)=c_{g_1}  \},$$ 
	where $\operatorname{Fix}(\phi)=\{g_1\in G_1:\phi(g_2)(g_1)=g_1 \text{ for all } g_2\in G_2\}$.
\end{lem}

\begin{proof}
	Let $(g_1,g_2)\in \Zc(G_1\rtimes_\phi G_2)$. For any $(g'_1,g'_2)\in G_1\rtimes_\phi G_2$ we have that $(g_1,g_2)(g'_1g'_2)=(g_1\phi(g_2)(g'_1),g_2g'_2)$ is equal to $(g'_1,g'_2)(g_1g_2)=(g'_1\phi(g'_2)(g_1),g'_2g_2)$. Hence $g_1\phi(g_2)(g'_1)=g'_1\phi(g'_2)(g_1)$ and $g_2g'_2= g'_2g_2$ for all $g_1'\in G_1$ and $g_2'\in G_2$. 

	By the second condition, $g_2\in \Zc G_2$. If we set $g'_1=e$, then $g_1=\phi(g'_2)(g_1)$ for all $g'_2\in G_2$ and therefore $g_1\in \operatorname{Fix}(\phi)$. Finally, by using that $g_1=\phi(g'_2)(g_1)$, we obtain that $g_1\phi(g_2)(g'_1)=g'_1g_1$, which implies that $\phi(g_2)(g'_1)=g_1^{-1}g'_1g_1$ and $\phi(g_2)=c_{g_1}$. 
\end{proof}

We consider a non-trivial group morphism $\phi:\Z\longrightarrow \Gl(n,\Z)$ such that $\phi(1)$ has finite order $a$. The group morphism $\phi(1)$ induces a finite order homeomorphism $f:T^n\longrightarrow T^n$ which we use to construct the mapping torus $T^n_f$. We claim that:
\begin{itemize}
	\item[1.] $T_f^n$ is a compact solvmanifold. This is a consequence of the fact that $T^n_f$ is the total space of a fibration $T^n\longrightarrow T^n_f\longrightarrow S^1$. In particular, $\pi_1(T^n_f)=\Z^n\rtimes_\phi \Z$ is polycyclic.
	\item[2.] $T^n_f$ is finitely covered by the torus $T^{n+1}$. This is because the subgroup $\Z^n\rtimes_\phi a\Z \cong \Z^{n+1}$ is a normal subgroup of index $a$. Therefore, we have a regular covering $p:T^{n+1}\longrightarrow T_f^n$. In particular $T^n_f$ is a flat manifold.
\end{itemize} 

\begin{prop}
	We have $\D(T^n_f)\leq n$.
\end{prop}

\begin{proof}
	Since $T^n_f$ is a flat manifold, we know that $\D(T^n_f)=\rank\Zc(\Z^n\rtimes_\phi \Z)$ by \cite{daura2024actions}. By \cref{center semidriect product}, $\Zc(\Z^n\rtimes_\phi \Z)=\operatorname{Fix}(\phi)\times a\Z$. Since $\phi(1)\neq Id$, we obtain that $\rank\operatorname{Fix}(\phi)\leq n-1$ and therefore $\D(T^n_f)=\rank\Zc(\Z^n\rtimes_\phi \Z)\leq n$.
\end{proof}

\begin{cor}
	The map $p:T^{n+1}\longrightarrow T^n_f$ does not export group actions.
\end{cor}

\subsection{Examples where $\D(M)=\rank\Zc\Gamma$}

Now we present examples of closed orientable manifolds $M$ admitting a non-zero degree map to a nilmanifold $f:M\longrightarrow N/\Gamma$ such that $\D(M)=\D(N/\Gamma)$ but $H^*(M,\Z)\ncong H^*(N/\Gamma,\Z)$.  

Let $H$ be the Heisenberg group of dimension 3,

\[H=\{(x,y,z)=\left(\begin{array}{ccc} 1 & x & z\\  0 & 1 & y \\  0 & 0 & 1 \end{array} \right):x,y,z\in \R\}, \] which is a simply connected nilpotent Lie group. Any lattice of $H$ is isomorphic to a lattice of the form
\[\Gamma_k=\{(x,y,z)=\left(\begin{array}{ccc} 1 & x & \tfrac{1}{k}z\\  0 & 1 & y \\  0 & 0 & 1 \end{array} \right):x,y,z\in \Z\}.\]

Consider $\Gamma_1$ and $\Gamma_2$ lattices of $H$. Note that the covering map $p:H/\Gamma_1\longrightarrow H/\Gamma_2$ induced by the inclusion $\Gamma_1\hookrightarrow \Gamma_2$ is a non-zero degree map between and $\D(H/\Gamma_1)=\D(H/\Gamma_2)=1$. However, a straightforward computation shows that $H_1(H/\Gamma,\Z)\cong \Z^2$ and $ H_1(H/\Gamma_2,\Z)\cong \Z^2\oplus\Z/2$, therefore $H^*(H/\Gamma_1,\Z)\ncong H^*(H/\Gamma,\Z)$. 

Note that $H^*(H/\Gamma_1,\Q)\cong H^*(H/\Gamma_2,\Q)$. Our next goal is to prove the next proposition:

\begin{prop}\label{discsym  not enough}
	There exists a closed orientable manifold $M$ admitting a map to a nilmanifold $f:M\longrightarrow N/\Gamma$ satisfying $\deg(f)=1$, $\D(M)=\D(N/\Gamma)=1$ and $H^*(M,\Q)\ncong H^*(N/\Gamma,\Q)$.
\end{prop}

Firstly, we recall some facts on principal $S^1$-bundles.

\begin{lem}
	Let $p:E\longrightarrow B$ be a principal $S^1$-bundle, then $p^*:H^1(B,\Q)\longrightarrow H^1(E,\Q)$ is injective. It is an isomorphism if and only if the first Chern class $c_1(E)\neq 0$.
\end{lem}

\begin{lem}
	Let $M$ be a closed manifold of dimension $n\geq 4$ and let $D\subseteq M$ be a disk. Then the inclusion $i:M\setminus D\longrightarrow M$ induces an isomorphism $i^*:H^2(M,\Q)\longrightarrow H^2(M\setminus D,\Q)$.
\end{lem}

The first lemma is a consequence of the Gysin exact sequence and the second lemma is a consequence of the Mayer-Vietoris sequence.

Given a principal bundle $p:E\longrightarrow B$, then we have a principal $S^1$-bundle $p':E\setminus p^{-1}(D)\longrightarrow B\setminus D$. Then $c_1(E\setminus p^{-1}(D))=i^*c_1(E)$. 

Note that $\partial(E\setminus p^{-1}(D))\cong S^{n-1}\times S^1$ has a right $S^1$ action induced by the action of the principal $S^1$-bundle. 

Given principal $S^1$-bundles $p_i:E_i\longrightarrow B_i$ with $i=1,2$, we can construct a $S^1$-equivariant homeomorphism $f:\partial(E_1\setminus p_1^{-1}(D_1))\longrightarrow \partial(E_2\setminus p_2^{-1}(D_2))$. There is a principal $S^1$-bundle $p: E_1\setminus p_1^{-1}(D_1)\cup_f E_2\setminus p_2^{-1}(D_2)\longrightarrow B_1\#B_2$. 

\begin{lem}
	If $\dim(B_i)\geq 4$ then $$c_1(E_1\setminus p_1^{-1}(D_1)\cup_f E_2\setminus p_2^{-1}(D_2)\longrightarrow B_1\#B_2)=(c_1(E_1),c_1(E_2))\in H^2(B_1,\Q)\oplus H^2(B_2,\Q)$$.
\end{lem}

Finally note that we have $S^1$-equivariant maps of degree one, $f_i:E\longrightarrow E_i$ for $i=1,2$. We are ready to prove \cref{discsym  not enough}.

\begin{proof}[Proof of \cref{discsym  not enough}]
	Now we consider the Heisenberg manifold of dimension $5$, $H_5/\Gamma$, which is the total space of a principal $S^1$-bundle over a torus $T^4$ (see \cite[Chapter I]{goze2013nilpotent} and \cite{gordon1986spectrum}). We also consider a nilmanifold modeled over the filiform Lie group of dimension 5 (for details on filiform Lie algebras and Lie groups, see \cite[\S2.I]{goze2013nilpotent} and \cite{hamrouni2008discrete,remm2017filiform}), $F_5/\Lambda$, which is the total space of a principal $S^1$-bundle over a filiform nilmanifold of dimension $4$, $F_4/\Lambda'$. By construction, $\D(F_5/\Lambda)=1$ and $H^1(F_4/\Lambda')\cong H^1(F_5/\Lambda)\cong \Q^2$. Note that the discrete degree of symmetry of both nilmanifolds is $1$. Let $E=H_5/\Gamma\setminus p_1^{-1}(D_1)\cup_f F_5/\Lambda\setminus p_2^{-1}(D_2)$ and consider the degree one maps $f_1: E\longrightarrow H_5/\Gamma$ and $f_2:E\longrightarrow F_5/\Lambda$. Observe that $p:E\longrightarrow T^4\# F_4/\Lambda'$ is a principal $S^1$-bundle and therefore $\D(E)\geq 1$. On the other hand, $\D(E)\leq 1$, since the maps $f_i$ export group actions. In conclusion, $\D(E)=1$. However, since $c_1(E)\neq 0$, one can compute that $H^1(E,\Q)\cong H^1(T^4\# F_4/\Lambda',\Q)\cong \Q^5$. On the other hand, we have $H^1(H_5/\Gamma,\Q)\cong H^1(T^4,\Q)\cong \Q^4$ and $H^1(F_5/\Lambda,\Q)\cong H^1(F_4/\Lambda',\Q)\cong \Q^2$, therefore $H^*(E,\Q)\ncong H^*(H_5/\Gamma,\Q)$ and $H^*(E,\Q)\ncong H^*(F_5/\Lambda,\Q)$.
\end{proof}

\subsection{Large finite group actions on admissible manifolds}

One possible generalization of closed connected aspherical manifolds are closed connected admissible manifolds (see \cite[Definition 3.2.7]{lee2010seifert}), which are manifolds where the only periodic self-homeomorphisms of $\tilde{M}$ commuting with the deck transformations group $\pi_1(M)$ are elements of $\Zc\pi_1(M)$. Closed connected oriented manifolds admitting a non-zero degree map to a torus or a nilmanifold are admissible manifolds. One could use the same arguments used to prove \cite[Theorem 1.6]{daura2024actions} together with \cite[Theorem 3.2.2]{lee2010seifert} to obtain:

\begin{prop}\label{finite group actions admissible}
	Let $M$ be a closed connected admissible manifold. Assume that $\Out(\pi_1(M))$ is Minkowski and that $\Zc\pi_1(M)$ is finitely generated. Then:
	\begin{itemize}
		\item[1.] $\Homeo(M)$ is Jordan.
		\item[2.] $\D(M)\leq \rank(\Zc\pi_1(M)/\operatorname{Torsion}(\Zc\pi_1(M)))$.
		\item[3.] If $\chi(M)\neq 0$ and $\Aut(\pi_1(M))$ is Minkowski then $M$ is almost asymmetric.
		\item[4.] If $\Aut(\pi_1(M))$ is Minkowski then $M$ has few stabilizers.
	\end{itemize}
\end{prop}

\begin{proof}
	The proofs of items 1, 2 and 4 are the same as in \cite[Theorem 1.6]{daura2024actions}. If $\Aut(\pi_1(M))$ is Minkowski then $M$ has small stabilizers by \cite[Theorem 3.2.2]{lee2010seifert}. Thus, item 3 follows from \cref{almost fix point euler char} and \cref{small stab+almost fixed point=almost asymmetric}.
\end{proof}

An application of \cref{finite group actions admissible} is the following. Suppose that $M$ is a closed connected oriented aspherical manifold satisfying the hypothesis of \cref{main theorem1 intro} and $M'$ is a closed simply-connected manifold of the same dimension as $M$, then $M\# M'$ is a closed admissible manifold such that $\Homeo(M\#M')$ is Jordan, $\D(M\# M')\leq \rank\Zc\pi_1(M)$ and $M\#M'$ has few stabilizers. The discrete degree of symmetry inequality is usually strict. For example, assume that $M'$ is a closed simply-connected even dimensional manifold such that $\chi(M')\neq 2$. Then $\chi(T^n\#M')=\chi(M')-2\neq 0$ and hence $\D(T^n\#M')=0<n=\rank \Zc\pi_1(T^n\#M')$, by \cref{finite group actions admissible}(3).

\Cref{finite group actions admissible} and \cref{main theorem2 intro} have a non-trivial overlap, but neither is more general than the other. On one hand, not all admissible manifolds admit a non-zero degree maps to a nilmanifold. On the other hand, there exist closed connected orientable manifolds admitting anon-zero degree map to a torus such that the outer automorphism group of their fundamental group is not Minkowski. In \cite[Theorem 1.1.1]{bloomberg1975manifolds} it is proved that if $\Gamma$ and $\Lambda$ are isomorphic neither to a non-trivial free product nor to a infinite cyclic group then $\Out(\Gamma*\Lambda)\cong\Aut(\Gamma)\times\Aut(\Lambda)$ if $\Gamma\ncong\Lambda$ and $\Out(\Gamma*\Lambda)\cong(\Aut(\Gamma)\times\Aut(\Lambda))\times\Z/2$ if $\Gamma\cong\Lambda$. In particular, if $M$ is a closed connected 4-manifold with fundamental group the Baumslag-Solitar group $B(m,ml)=\langle a,b| ba^mb^{-1}=a^{ml}\rangle$ with $m,l\geq 2$. Note that $B(m,ml)$ is not a proper free product of groups (see \cite[II.5.13]{lyndon1977combinatorial} or)  Then $\Out(\pi_1(M\#T^4))\cong\Aut(B(m,ml))\times\Gl(4,\Z)$ is not Minkowski (see \cite[Lemma 3.8]{collins1983automorphisms} or \cite{levitt2007automorphism}), but $M\#T^4$ is hypertoral and hence $\Homeo(M\#T^4)$ is Jordan by \cref{large group actions hypertoral manifolds}.

\section{Free iterated actions}\label{sec: free iterated actions}

Recall that if $G$ is a finite group acting freely on a manifold $M$ then $M/G$ is also a manifold and $p:M\longrightarrow M/G$ is a regular covering. Moreover, we have a short exact sequence $1\longrightarrow \pi_1(M)\longrightarrow \pi_1(M/G)\longrightarrow G\longrightarrow 1$.   Therefore, if we have an iterated free action of $\mathcal{G}=\{G_i\}_{i=1,..,n}$ on a manifold $M$, then every $M_i$ is a manifold, $p_i:M_{i-1}\longrightarrow M_i$ is a regular cover and the map $p:M\longrightarrow M_n$ is a covering on $M$. A free iterated action of $\mathcal{G}=\{G_i\}_{i=1,\dots,n}$ on $M$ induces a series of groups 
$$ \pi_1(M)=\pi_1(M_0)\trianglelefteq\pi_1(M_1)\trianglelefteq\cdots \trianglelefteq \pi_1(M_n) $$
where $\pi_1(M_i)/\pi_1(M_{i-1})\cong G_i$. 

\begin{lem}\label{iterated action equivalent fundamental group}
	Let $\mathcal{G}\acts M$ and $\mathcal{G}'\acts M$ be a free iterated actions of finite groups inducing coverings $p:M\longrightarrow M/\mathcal{G}$ and $p':M\longrightarrow M/\mathcal{G}'$ respectively. If $\mathcal{G}\acts M\sim\mathcal{G}'\acts M$ then there exists an isomorphism $\phi:\pi_1(M/\mathcal{G})\longrightarrow \pi_1(M/\mathcal{G}') $ satisfying $\phi(p_*(\pi_1(M)))=p'_*(\pi_1(M))$. 
\end{lem}

\begin{proof}
	Let $f:M/\mathcal{G}\longrightarrow M/\mathcal{G}'$ be the homeomorphism provided by \cref{iterated action equivalent}. By construction, the coverings $f\circ p:M\longrightarrow M/\mathcal{G}'$ and $p': M\longrightarrow M/\mathcal{G}'$ are isomorphic. Therefore, there exists $\gamma\in \pi_1(M/\mathcal{G}')$ such that $f_*(p_*(\pi_1(M))))=c_\gamma(p'_*(\pi_1(M)))$. We can write $\phi(p_*(\pi_1(M)))=p'_*(\pi_1(M))$, where $\phi=c_{\gamma^{-1}}\circ f_*$.
\end{proof}

\Cref{iterated action equivalent fundamental group} shows that to study free iterated actions up to equivalence, we can focus on the inclusion $p_*:\pi_1(M)\longrightarrow \pi_1(M/\mathcal{G})$ induced by the covering. For example: 

\begin{cor}\label{free iterated action simplifiable regular covering}
	Let $\mathcal{G}\acts M$ and $\mathcal{G}'\acts M$ be equivalent free iterated actions of finite groups inducing coverings $p:M\longrightarrow M/\mathcal{G}$ and $p':M\longrightarrow M/\mathcal{G}'$ respectively. Then $p_*(\pi_1(M))\trianglelefteq\pi_1(M/\mathcal{G})$ if and only if $p'_*(\pi_1(M))\trianglelefteq\pi_1(M/\mathcal{G}')$.
\end{cor}

In particular:

\begin{lem}\label{free itertaed action simplifiable}
	A free iterated action of a collection of finite groups $\mathcal{G}=\{G_i\}_{i=1,..,n}$ on $M$ is simplifiable if and only if $\pi_1(M)\trianglelefteq\pi_1(M/\mathcal{G})$.
\end{lem}

\begin{cor}\label{free itertaed action simplifiable when simply connected}
	A free iterated action on a simply connected manifold $M$ is simplifiable.
\end{cor}

However, $M$ being simply connected is not a necessary condition to have simplifiability of all free iterated actions on $M$.

\begin{lem}\label{free itertaed action simplifiable S1 and T2}
	Any free iterated action on $S^1$ or $T^2$ is simplifiable.
\end{lem}

\begin{proof}
	Let $\mathcal{G}\acts S^1$ be a free iterated group action. Then $S^1/\mathcal{G}$ is a closed 1-dimensional manifold and hence $S^1/\mathcal{G}\cong S^1$. This implies that $\pi_1(M)\cong \Z\trianglelefteq \pi_1(S^1/\mathcal{G})\cong \Z$ and hence the free iterated group action is simplifiable. All the groups of $\mathcal{G}$ are cyclic and the simplification is given by group action of a cyclic group of order $|\mathcal{G}|$.

	The proof for the second case is similar. Assume that we have a free iterated group action $\mathcal{G}\acts T^2$. Then $T^2/\mathcal{G}$ is homeomorphic to $T^2$ or the Klein bottle $K$. Then the result follows from the fact that any subgroup of $\pi_1(T^2)\cong\Z^2$ or $\pi_1(K)\cong\Z\rtimes\Z$ isomorphic to $\Z^2$ is normal, hence the action is simplifiable.
\end{proof}

\begin{rem}\label{iterated action T2 not simplfiable}
	\Cref{free itertaed action simplifiable S1 and T2} cannot be extended to $T^n$ for $n\geq 3$. Consider the Bieberbach group with presentation
	$$\Gamma=\langle t_1,t_2,t_3,\alpha|[t_i,t_j]=e\text{ $\forall i,j$},\alpha^3=t_1,\alpha t_2\alpha^{-1}=t_3,\alpha t_3\alpha^{-1}=t_2^{-1}t_3^{-1}\rangle.$$

	The group generated by $t_1$, $t_2$ and $t_3$ is normal and isomorphic to $\Z^3$, which we denote by $Z$. Note that $\Gamma/Z\cong \Z/3$. Let $Z'$ be the subgroup generated by $t_1$, $t_2$ and $t_3^2$, which is also isomorphic to $\Z^3$. We have a normal series $Z'\trianglelefteq Z \trianglelefteq \Gamma$ with $\Gamma/ Z\cong \Z/3$ and $Z/Z'\cong \Z/2$. On the other hand, $Z'$ is not normal in $\Gamma$, since $\alpha t_2\alpha^{-1}=t_3\notin Z'$. Now we can define a free iterated action $\{\Z/2,\Z/3\}\acts T^3$ such that $\pi_1(T^3)\cong Z'$, $\pi_1(T^3/\Z/2)\cong Z$ and $\pi_1((T^3/\Z/2)/\Z/3)\cong \Gamma$. This free iterated action is not simplifiable.
\end{rem}

We have seen that free iterated actions produce a covering map that is not necessarily regular. Conversely, given a finite covering map $q:M\longrightarrow M'$ we can ask whether there exists an iterated action $\mathcal{G}$ on $M$ such that $p:M\longrightarrow M/\mathcal{G} $ is isomorphic to $q:M\longrightarrow M'$. The next example shows that this does not happen in general.

