			Take a non-trivial subgroup $G\leq A_5$ and consider the finite covering of closed flat manifold $q:M'\longrightarrow M$, where  $\pi_1(M')=\rho^{-1}(G)$. If $q$ were induced by a free iterated action, then there would exist a group $\Gamma$ such that $\pi_1(M')\leq \Gamma\trianglelefteq \pi_1(M)$. This would imply that $G\leq \Gamma/\Z^n\trianglelefteq A_5$, which is not possible since $A_5$ is simple.
		\end{ex}

		Let $k$ be a natural number and let $\Cov_k(M)$ be the set of all coverings of $M$ of $k$-sheets up to equivalence of coverings. Let $p:\tilde{M}\longrightarrow M$ be a $k$-covering and pick $x\in M$. We can enumerate the points of the fiber $p^{-1}(x)=\{x_1,\dots,x_k\}$. Given $\alpha\in\pi_1(M,x)$ there is a unique lift $a_i:I\longrightarrow \tilde{M}$ such that $a_i(0)=x_i$. Thus, we can define an element in the group of permutations of $k$ letters $\sigma_\alpha$  such that $x_i$ goes to $a_i(1)$. If we remove the choice of the base point $x$, then $\Cov_k(M)\cong \Hom(\pi_1(M),S_k)/\sim$, where $S_k$ is the permutation group of $k$ elements acting by conjugations on $\Hom(\pi_1(M),S_k)$.

		Assume that a finite group $G$ acts effectively on $M$, then we have an action of $G$ on $\Cov_k(M)$ given by the pull-back of each element of $G$. Explicitly, $g[\tilde{M}\longrightarrow M]=[g^*\tilde{M}\longrightarrow M]$ for all $g\in G$ and $[\tilde{M}\longrightarrow M]\in\Cov(M)_k $. The induced action of $G$ on  $\Hom(\pi,S_k)/S_k$ is given by $g[f:\pi\longrightarrow S_k]=[f\circ g_*:\pi\longrightarrow S_k]$, where $g_*:\pi_1(M)\longrightarrow \pi_1(M)$ is the group morphism induced by $g$ on the fundamental group.

		We also recall the lifting condition of continuous maps. Assume that we have $f:M'\longrightarrow M$ a continuous map such that $f(y)=x$ for some $y\in M'$. Then, there exists $\tilde{f}:M'\longrightarrow \tilde{M}$ such that $f=p\circ\tilde{f}$ if and only if $f_*(\pi_1(M',y))\leq p_*(\pi_1(\tilde{M},\tilde{x}))$. In particular, a homeomorphism $f:M\longrightarrow M$ can be lifted to a homeomorphism  $\tilde{f}:\tilde{M}\longrightarrow\tilde{M}$ if and only if $f_*(p_*(\pi_1(\tilde{M},\tilde{y})))\leq p_*(\pi_1(\tilde{M},\tilde{x}))$.


		\begin{lem}\label{free itertaed actions simplifiable coverings}
			Assume that we have a free iterated action of $\mathcal{G}=\{G_1,G_2\} $ on a manifold $M$. Then, the following statements are equivalent:
			\begin{itemize}
				\item[(1)] $\mathcal{G}$ is simplifiable
				\item[(2)] We can lift ${g_2}:M/G_1\longrightarrow M/G_1$ to a homeomorphism $\tilde{g}_2:M\longrightarrow M$ for all $g_2\in G_2$.
				\item[(3)] The action of $G_2$ on $\Cov_{|G_1|}(M/G_1)$ fixes $[p_1:M\longrightarrow M/G_1]$.
			\end{itemize}
		\end{lem}

		\begin{proof}
			We will prove the chain of implications $(1)\implies (2)\implies (3)\implies (1)$. If the action of $\mathcal{G}$ is simplifiable then there exists a group $G$ fitting in the exact sequence $1\longrightarrow G_1\longrightarrow G\longrightarrow G_2\longrightarrow 1$ which acts freely on $M$ and $p:M\longrightarrow M/G=p_2\circ p_1$. Given any $g_2\in G_2$ we choose an element $\tilde{g}_2\in G$ which inside the preimage of $G\longrightarrow G_2$. The induced homeomorphism $\tilde{g}_2:M\longrightarrow M$ is a lift of ${g_2}:M/G_1\longrightarrow M/G_1$.

			We now prove the second implication. Note that if we can lift $g_2:M\longrightarrow M$, then $p_1:M\longrightarrow M/G_1$ and the pullback $g_2^*M\longrightarrow M/G_1$ are isomorphic as regular $G_1$-coverings. If $[p_1]\in \Cov_{|G_1|}(M/G_1)$ denotes the class of the covering $p_1:M\longrightarrow M/G_1$ then $g_2[p_1]=[p_1]$ for all $g_2\in G_2$.

			Finally, if $G_2$ fixes $[p_1]$ then there exists a group $G$ of the form $1\longrightarrow G_1\longrightarrow G\longrightarrow G_2\longrightarrow 1$ acting freely on $M$. This action extends the action of $G_1$ on $M$ and it also covers the action of $G_2$ on $M/G_1$. Therefore $p:M\longrightarrow M/G=p_2\circ p_1$ and the free iterated action is simplifiable.
		\end{proof}

\section{The iterated discrete degree of symmetry}\label{sec: discsym2}

Recall that if $G$ is a finite group, then $\rank G$ is the minimum number of elements which are needed to generate $G$. We want to extend this notion to iterated group actions. 

\begin{defn}
	Given a free iterated action $\mathcal{G}\acts X$, the rank of the iterated action is $$\rank(\mathcal{G}\acts X)=\min\{\sum_{i=1}^{n}\rank G'_i:\mathcal{G}'=\{G_1',\dots,G_n'\}\acts X\in [\mathcal{G}\acts X]\}.$$
	The iterated rank of the space $X$ is $$\rank(X)=\max\{\rank(\mathcal{G}\acts X): \text{ free iterated action }\mathcal{G}\acts X\}.$$
\end{defn}

\begin{lem}\label{rank iterated aciton simplifiable}
	Assume that we have a free iterated action of $\mathcal{G}=\{G_1,\dots,G_n\}$ on $X$. If $\mathcal{G}\acts X$ is simplifiable with a group $G$, then $\rank(\mathcal{G}\acts X)=\rank G$.
\end{lem}

\begin{proof}
	By definition, $\rank(\mathcal{G}\acts X)\leq\rank G$. Since $\mathcal{G}\acts X$ is simplifiable there exists a subnormal series $G^0=\{e\}\trianglelefteq G^1\trianglelefteq\cdots\trianglelefteq G^n=G$ such that $G^i/G^{i-1}\cong G_{i}$. In particular, $\rank G^{i}\leq \rank G^{i-1}+\rank G_i$ for all $1\leq i\leq n$. This implies that $\rank G=\rank G^n\leq\sum_{i=1}^{n}\rank G_i+\rank G^0=\rank(\mathcal{G}\acts X)$.
\end{proof}

Note that $\rank(\mathcal{G}\acts X)$ depends on the free iterated group action, see \cref{example iterated action torus} below.

We also note that $l(X)\leq \rank (X)$ and therefore we cannot bound the iterated rank of a closed manifold. To generalize the discrete degree of symmetry we will need a notion of rank which only uses abelian groups.

\begin{defn}\label{iterated abelian rank def}
	Let $\mathcal{G}=\{G_1,\dots,G_n\}$ act freely on $X$ and assume that $G_i$ is solvable for all $i$. The abelian rank of the iterated action is $$\rank_{ab}(\mathcal{G}\acts X)=\min\{\sum_{i=1}^{m}\rank A'_i:\{A_1',\dots,A_m'\}\acts X\in [\mathcal{G}\acts X], \text{ $A_i'$ abelian for all $i$}\}.$$
\end{defn} 

Note that $\rank(\mathcal{G}\acts X)\leq \rank_{ab}(\mathcal{G}\acts X)$. We would like to define an invariant of free iterated actions with similar properties to the discrete degree of symmetry. An essential property of the discrete degree of symmetry is that if $M$ is a closed manifold, then $\D(M)<\infty$. The proof of this fact is a direct consequence of \cref{MannSu thm}. We can generalize this theorem to the context of free iterated actions. Recall that given a closed manifold $M$ of dimension $n$, we define $b(M)=\sum_{i=1}^{n} \rank H_i(M,\Z)$, where $\rank$ is understood to be the minimum number of generators needed to generate $H_i(M,\Z)$ (note that $b(M)$ is not the Betti number of $H_*(M,\Z)$, since we also count the torsion part of $H_*(M,\Z)$). If $p$ is a prime number, then $b_p(M)=\sum_{i=1}^{n} \dim H_i(M,\Z/p)$. The next results generalizes \cref{MannSu thm} to the context of free iterated actions.

\begin{thm}\label{iterated MannSu thm}
	Let $M$ be a closed connected $n$-dimensional manifold. There exists a sequence of numbers $\{f_i\}_{i\in\mathbb{N}}$ depending only on $n$ and $b(M)$ such that for any prime $p$, any sequence of positive integers $\{k_i\}$ and any free iterated action $\{(\Z/p^{k_i})^{a_i}\}_{i=1,\dots,r}\acts M$, the numbers $a_i$ satisfy $a_i\leq f_i$ for all $i$.
\end{thm}

To prove \cref{iterated MannSu thm}, we need the following lemma.

\begin{lem}\label{cohomology bound Borel fibration}
	Let $M$ be a closed connected manifold and $p$ a prime number. Assume that we have an effective action of a finite $p$-group $G$ on $M$. Then $$\dim H_k(M/G,\Z/p)\leq\sum_{i+j=k}\dim H_i(BG,\Z/p)\dim H_j(M,\Z/p).$$
\end{lem} 

We refer to \cite[Lemma 1.46]{saez2019finite} for a detailed proof of the lemma.

\begin{proof}[Proof of \cref{iterated MannSu thm}]
	We construct the sequence $f_i$ recursively. For the first step, if $(\Z/p^{k_1})^{a_1}$ acts freely on $M$ then so it does the group $(\Z/p)^{a_1}$. Thus, we can take $f_1=f(n,b_p(M))$, where $f$ is the function defined in \cref{MannSu thm}. 

	By \cref{cohomology bound Borel fibration}, if $\Z/p^{k_1}$ acts freely on $M$, then 
	$$\dim H_k(M/(\Z/p^{k_1}),\Z/p)\leq \sum_{i+j=k} \dim H_i(B\Z/p^{k_1},\Z/p)\dim H_j(M,\Z/p)$$ for any $k$. Moreover, $H_i(B\Z/p^{k_1},\Z/p)\cong\Z/p$ for all $i\geq 0$ (see \cite[Chapter III, \S1]{brown2012cohomology}). Thus,
	$\dim H_k(M/(\Z/p^{k_1}),\Z/p)\leq b_p(M)$ for all $k$ and therefore $b_p(M/(\Z/p^{k_1}))\leq nb_p(M)$. Using this inequality recursively, we obtain that $b_p(M/(\Z/p^{k_1})^{a_1})\leq n^{a_1}b_p(M)\leq n^{f_1}b_p(M)$. 

	We can use \cref{MannSu thm} on $M/(\Z/p^{k_1})^{a_1}$ to deduce that $$a_2\leq f(n,b_p(M/(\Z/p^{k_1})^{a_1}))\leq f(n,n^{f_1}b_p(M)).$$ Set $f_2=f(n,n^{f_1}b_p(M))$. Repeating the same argument as above, we obtain $$f_i=f(n,n^{f_1+\dots+f_{i-1}}b_p(M))$$ for all $1\leq i\leq r$. 

	By the universal coefficients theorem, $b_p(M)\leq 2b(M)$. Thus, by replacing  $b_p(M)$ with $2b(M)$ we obtain a bound not depending on the prime $p$.
\end{proof}

We are ready to define an iterated discrete degree of symmetry for free iterated actions of length $2$. In $\mathbb{N}^2$ we have a partial order relation called the lexicographic order defined as follows: If $(n,m),(n',m')\in \mathbb{N}^2$ then $(n,m)\geq (n',m')$ if and only if $n>n'$ or $n=n'$ and $m\geq m'$. 

\begin{defn}
	We define $\mu_2(M)$ as the set of all pairs $(f,b)\in \mathbb{N}^2$ which satisfy:
	\begin{itemize}
		\item[1.] There exist an increasing sequence of prime numbers $\{p_i\}$, a sequence of natural numbers $\{a_i\}$ and a collection of free iterated actions $\{(\Z/p_i^{a_i})^f,(\Z/p_i)^b\}\acts M$ for each $i\in\mathbb{N}$.
		\item[2.] $\rank_{ab}(\{(\Z/p_i^{a_i})^f,(\Z/p_i)^b\}\acts M)=f+b$ for each $i\in\mathbb{N}$.
	\end{itemize}

	We define the iterated discrete degree of symmetry of $M$ as
	$$\D_2(M)=\max\{(0,0)\cup\mu_2(M)\}.$$
\end{defn}

To understand better the definition of the iterated discrete degree of symmetry, let us compute it for tori.

\begin{lem}\label{iterated discsym Tn}
	We have $\D_2(T^n)=(n,0)$.
\end{lem}

\begin{proof}
	Let $C$ be the Minkowski constant of $\Gl(n,\Z)$. Assume that $\D_2(T^n)=(d_1,d_2)$. Since $T^n$ admits actions of $(\Z/p)^n$ for any prime $p$ and $\D(T^n)=n$, we have $d_1=n$. By hypothesis there exists an increasing sequence of prime numbers $\{p_i\}_{i\in\mathbb{N}}$ with $p_i>C$ and free iterated group actions of $\{(\Z/p_i^{a_i})^n,(\Z/p_i)^{d_2}\}\acts T^n$ such that $\rank_{ab}(\{(\Z/p_i^{a_i})^n,(\Z/p_i)^{d_2}\}\acts T^n)=n+d_2$.

	The action of $(\Z/p_i^{a_i})^n$ on $T^n$ is by rotations for all $i$, therefore $T^n/(\Z/p_i^{a_i})^n\cong T^n$.  Since $p_i>C$ the group $(\Z/p_i)^{d_2}$ also acts by rotations on $T^n$, hence $T^n/(\{(\Z/p_i^{a_i})^n,(\Z/p_i)^{d_2}\})$ is homeomorphic to $T^n$. In consequence, the free iterated action  $\{(\Z/p_i^{a_i})^n,(\Z/p_i)^{d_2}\}\acts T^n$ is simplifiable for all $i$. The simplification gives a group $G_i$ and a short exact sequence
	$$1\longrightarrow  (\Z/p_i^{a_i})^n\longrightarrow G_i\longrightarrow (\Z/p_i)^{d_2}\longrightarrow 1.$$

	Moreover, we also have that a short exact sequence 
	$$1\longrightarrow \Z^n\longrightarrow \Z^n\longrightarrow G_i\longrightarrow 1 $$
	induced by the regular covering $p:T^n\longrightarrow T^n/\{(\Z/p_i^{a_i})^n,(\Z/p_i)^{d_2}\}$. This implies that $G_i$ is abelian and $\rank G_i\leq n$. On the other hand, $$\rank G_i=\rank_{ab}(\{(\Z/p_i^{a_i})^n,(\Z/p_i)^{d_2}\}\acts T^n)=n+d_2\leq n,$$ which implies that $d_2=0$.
\end{proof}

