	Let us describe explicitly these two free iterated actions. The first step of both free iterated actions is by rotations on the horizontal plane. More explicitly, given $g\in\Z/p$ and $[x,y]\in T^2=\R^2/\Z^2$, we have $g[x,y]=[x+\tfrac{g}{p},y]$. The quotient is $T^2/(\Z/p)\cong T^2$. The second step of the first iterated action is by rotations on the horizontal plane. The free iterated action is simplifiable by an action of $\Z/p^2$ on $T^2$ such that $g[x,y]=[x+\tfrac{g}{p^2},y]$ for $g\in\Z/p^2$ and $[x,y]\in T^2$. Note that $\rank_{ab}(\{\Z/p,\Z/p\}\acts T^2)=1<2$. Hence, this free iterated action is not considered in the definition of the iterated discrete degree of symmetry.

	The second step of the second iterated actions is by rotations such that $g[x,y]=[x,y+\tfrac{g}{p}]$ for $g\in\Z/p$ and $[x,y]\in T^2$. The free iterated action is simplifiable by an action of $(\Z/p)^2$ on $T^2$ such that $(g,h)[x,y]=[x+\tfrac{g}{p},y+\tfrac{h}{p}]$ for $(g,h)\in(\Z/p)^2$ and $[x,y]\in T^2$. In this case $\rank_{ab}(\{\Z/p,\Z/p\}\acts T^2)=2$, but it does not satisfy the maximality condition on the definition of the iterated discrete degree of symmetry, since we have a free iterated action $\{(\Z/p)^2,\{e\}\}\acts T^2$. 
\end{rem}

\begin{cor}
	Let $M$ be a closed manifold. There exists $(f,b)\in\mathbb{N}^2$ such that $\D_2(M)\leq (f,b)$.
\end{cor}

\begin{proof}
	We can choose $f=f_1$ and $b=f_2$ from \cref{iterated MannSu thm}.
\end{proof}

Note that if $\D_2(M)=(d_1,d_2)$ then $d_1\leq\D(M)$. We want to investigate the value $d_2$. 

\begin{rem}
	If $M$ is a manifold such that $\D(M)=0$ then $\D_2(M)=(0,0)$.
\end{rem}

The next lemma shows a case where $d_2=0$, so we do not have large iterated group actions.

\begin{lem}\label{iterated discsym Jordan}
	Let $M$ be a closed manifold. Assume that $l(M)=1$ and $\Homeo(M)$ is Jordan. Then $\D_2(M)=(d,0)$.
\end{lem}

\begin{proof}
	Assume that $C$ is the Jordan constant of $\Homeo(M)$ and that $\D_2(M)=(d_1,d_2)$. We have an increasing sequence of prime numbers $\{p_i\}_{i\in\mathbb{N}}$ and free iterated group actions of $\{(\Z/p_i^{a_i})^{d_1},(\Z/p_i)^{d_2}\}$ on $M$ such that $\rank_{ab}(\{(\Z/p_i^{a_i})^{d_1},(\Z/p_i)^{d_2}\}\acts M)=d_1+d_2$.
	We may assume without loss of generality that $p_i>C$. Since all actions are simplifiable, for each $i$ there exists a $p_i$-group $G_i$ acting freely on $M$ which fits in the short exact sequence
	$$1\longrightarrow  (\Z/p_i^{a_i})^{d_1}\longrightarrow G_i\longrightarrow (\Z/p_i)^{d_2}\longrightarrow 1.$$

	Any proper subgroup $H$ of $G_i$ has index $[G:H]>p_i>C$. Since $\Homeo(M)$ is Jordan of constant $C$, we can conclude that $G_i$ is abelian. Consequently, we have $\rank G_i=\rank_{ab}(\{(\Z/p_i^{a_i})^{d_1},(\Z/p_i)^{d_2}\}\acts M)=d_1+d_2$. Therefore, $G_i\cong (\Z/p_i^{a_i})^{d_1}\oplus (\Z/p_i)^{d_2}$. We can take a subgroup $(\Z/p_i)^{d_1+d_2}\leq G_i$, which acts freely on $M$ for all $i$. This implies that $(d_1+d_2,0)\leq (d_1,d_2)$ and since $d_1,d_2\geq 0$, $d_2=0$.
\end{proof}

\begin{prop}
	Let $p:M'\longrightarrow M$ be a regular finite covering. Then $\D_2(M')\geq \D_2(M)$.
\end{prop}

\begin{proof}
	Firstly, we need to prove the following group theoretic fact. Let $G$ be a finite group and $p$ a prime such that $p>|G|!$. If $G'$ is a group which fits in the short exact sequence $1\longrightarrow G\longrightarrow G'\longrightarrow (\Z/p^r)^b\longrightarrow 1$ then $G'\cong G\times (\Z/p^r)^b$.

	The abstract kernel $\psi:(\Z/p^r)^b\longrightarrow \Out(G)$ is trivial since $|\Out(G)|\leq |G|!<p$. This leads to the following diagram
	\[
	\begin{tikzcd}
		& 1\ar{d}{}& 1\ar{d}{}& & \\
		1\ar{r}{} & \Zc G \ar{r}{}\ar{d}{} & H\ar{r}{}\ar{d}{}& (\Z/p^r)^b\ar{r}{}\ar{d}{Id} &1\\
		1\ar{r}{} & G \ar{r}{}\ar{d}{} & G'\ar{r}{}\ar{d}{}& (\Z/p^r)^b\ar{r}{} &1\\
		& \Inn G\ar{d}{}\ar{r}{Id} & \Inn G\ar{d}{} & &\\
		& 1 &1 & & \\
	\end{tikzcd}
	\]
	where the above short exact sequence is central. Since $(\Z/p^r)^b$ is abelian, there is a cocycle $\beta: (\Z/p^r)^b\times (\Z/p^r)^b\longrightarrow \Zc G$ which is a group morphism. More explicitly, $\beta(x,y)=[\tilde{x},\tilde{y}]$, where $\tilde{x},\tilde{y}\in H$ are preimages of $x$ and $y$ respectively. We use that $|\Zc G|<p$ to conclude that $\beta$ is trivial. This implies that the central short exact sequence is trivial and $H\cong \Zc G\times(\Z/p^r)^b$.

	We can construct a group morphism $(\Z/p^r)^b\longrightarrow H\longrightarrow G$ which makes the short exact sequence split. Therefore $G'\cong G\rtimes_\phi (\Z/p^r)^b$. The group morphism $\phi:(\Z/p^r)^b\longrightarrow \Aut(G)$ is trivial since $|\Aut(G)|\leq |G|!<p$. In conclusion, $G'\cong G\times (\Z/p^r)^b$.

	Assume now that we have a regular $G$-covering  $p:M'\longrightarrow M$ and $\D_2(M)=(d_1,d_2)$. There is an increasing sequence of prime numbers $\{p_i\}_{i\in\mathbb{N}}$ such that $p_i>|G|!$ for all $i$ and free iterated group actions of $\{(\Z/p_i^{a_i})^{d_1},(\Z/p_i)^{d_2}\}\acts M$. They induce free iterated actions of $\{G,(\Z/p_i^{a_i})^{d_1},(\Z/p_i)^{d_2}\}\acts M'$.

	Since $p_i>|G|!$, the actions of $(\Z/p_i^{a_i})^{d_1}$ on $\Cov_{|G|}(M)$ are trivial. By \cref{free itertaed actions simplifiable coverings} the free iterated action $\{G,(\Z/p_i^{a_i})^{d_1},(\Z/p_i)^{d_2}\}\acts M'$ is equivalent to a free iterated action of $\{G_i',(\Z/p_i)^{d_2}\}\acts M'$ for all $i$. For each $i$ there exists a short exact sequence $$1\longrightarrow G\longrightarrow G'_i\longrightarrow (\Z/p_i^{a_i})^{d_1}\longrightarrow 1.$$ Since $p_i>|G|!$, $G_i'\cong G\times (\Z/p_i^{a_i})^{d_1}$. Thus, the free iterated action $\{G_i',(\Z/p_i)^{d_2}\}\acts M'$ is equivalent to $\{(\Z/p_i^{a_i})^{d_1},G,(\Z/p_i)^{d_2}\}\acts M'$ for all $i$. Repeating the same argument we can show that $\{(\Z/p_i^{a_i})^{d_1},G,(\Z/p_i)^{d_2}\}\acts M'$ is equivalent to $\{(\Z/p_i^{a_i})^{d_1},(\Z/p_i)^{d_2},G\}\acts M'$ for all $i$.

	We have free iterated actions $\{(\Z/p_i^{a_i})^{d_1},(\Z/p_i)^{d_2}\}\acts M'$ for all $i$, thus $\D_2(M)=(d_1,d_2)\leq \D_2(M')$. 
\end{proof}   

We start now the study of the iterated discrete degree of symmetry on nilmanifolds. We need 3 preliminary lemmas.

\begin{lem}\cite[Lemma 3.1.14]{lee2010seifert}\label{aspherical manifolds big diagram}
	Let $G$ be a finite group acting effectively on a closed manifold $M$. Then, there is a commutative diagram with exact rows and columns
	\[\begin{tikzcd}
		& 1\ar{d}{} & 1 \ar{d}{}& 1 \ar{d}{} & \\
		1\ar{r}{}& \Zc\pi_1(M)\ar{r}{}\ar{d}{} & C_{\tilde{G}}(\pi_1(M)) \ar{r}{}\ar{d}{}& \ker\psi\ar{r}{}\ar{d}{} & 1\\
		1\ar{r}{}& \pi_1(M)\ar{r}{}\ar{d}{} & \tilde{G} \ar{r}{}\ar{d}{}& G\ar{r}{}\ar{d}{\psi} & 1\\
		1\ar{r}{}& \Inn(\pi_1(M))\ar{r}{}\ar{d}{} & \Aut(\pi_1(M)) \ar{r}{}& \Out(\pi_1(M))\ar{r}{} & 1\\
		&1 &&&
	\end{tikzcd}\]
	where $C_{\tilde{G}}(\pi_1(M))$ is the centralizer of $\pi_1(M)$ in $\tilde{G}$.
\end{lem}

\begin{lem}\label{inner actions aspherical manifolds}\cite[Proposition 3.1.21]{lee2010seifert}
	Let $M$ be a closed aspherical manifold and let $\Zc\pi_1(M)$ be finitely generated. Assume that we have a free action of an abelian group $A$ on $M$ such that $\psi:A\longrightarrow \Out(\pi_1(M))$ is trivial. Then $\Zc\pi_1(M/A)=C_{\pi_1(M/A)}(\pi_1(M))$ and it is an extension of $\Zc\pi_1(M)$ by $A$. In particular, $\rank(\Zc\pi_1(M/A))=\rank(\Zc\pi_1(M))$.
\end{lem}

\begin{lem}\label{inner actions simplifiable}
	Let $\{A,A'\}\acts M$ be a free iterated action of abelian groups on a closed connected aspherical manifold such that $\psi:A\longrightarrow \Out(\pi_1(M))$ and $\psi':A'\longrightarrow\Out(\pi_1(M/A))$ are trivial. Then $\{A,A'\}\acts M$ is simplifiable by an abelian group.
\end{lem}

\begin{proof}
	We have a commutative diagram 
	\[
	\begin{tikzcd}
		1\ar{d}{} & 1\ar{d}{} & 1\ar{d}{} \\
		\Zc \pi_1(M) \ar{r}{}\ar{d}{} &\Zc \pi_1(M/A)\ar{r}{}\ar{d}{}& \Zc \pi_1((M/A)/A')\ar{d}{}\\
		\pi_1(M) \ar{r}{}\ar{d}{p} & \pi_1(M/A)\ar{r}{}\ar{d}{q}& \pi_1((M/A)/A')\ar{d}{q'} \\
		\Inn \pi_1(M)\ar{r}{Id}\ar{d}{} & \Inn \pi_1(M)\ar{r}{Id}\ar{d}{} &\Inn \pi_1(M)\ar{d}{}\\
		1& 1 & 1
	\end{tikzcd}
	\]
	Given $\gamma\in\pi_1(M)$ and $g'\in \pi_1((M/A)/A')$, we want to see that $g'\gamma g'^{-1}\in\pi_1(M)$. Let $\gamma'\in \pi_1(M)$ such that $p(\gamma')=q'(g')$, then $g'\gamma g'^{-1}=(g'\gamma'^{-1})\gamma'' (g'\gamma'^{-1})^{-1}$ with $\gamma''\in\pi_1(M)$. Since $q'(g'\gamma'^{-1})$ is trivial then $g'\gamma'^{-1}\in\Zc \pi_1((M/A)/A')$ and therefore $g'\gamma g'^{-1}=\gamma''\in\pi_1(M)$, as we wanted to see. 

	Note that $\pi_1((M/A)/A')/\pi_1(M)\cong \Zc \pi_1((M/A)/A')/\Zc\pi_1(M)$, which is abelian of rank at most $\rank\Zc\pi_1(M)$.
\end{proof}

The next result shows that the definition of the iterated degree of symmetry is suitable to study 2-step nilmanifolds.

\begin{thm}\label{iterated discsym nilmanifolds}
	Let $N/\Gamma$ be a nilmanifold of dimension $n$, $f=\rank\Zc\Gamma$ and $\D_2(N/\Gamma)=(d_1,d_2)$. Then $d_1=f$ and $d_2\leq n-f$. If $d_2= n-f$ then $N/\Gamma$ is a 2-step nilmanifold. Conversely, if $N/\Gamma$ is a 2-step nilmanifold then $\D_2(N/\Gamma)=(f,n-f)$.
\end{thm}

\begin{proof}
	Let $\{p_i\}_{i\in \mathbb{N}}$ be the increasing sequence of primes and $\{(\Z/p_i^{a_i})^{d_1},(\Z/p_i)^{d_2}\}\acts N/\Gamma$ be the free iterated actions provided by the condition $\D_2(N/\Gamma)=(d_1,d_2)$. Let $C$ be the Minkowski constant of $\Out(\Gamma)$. Assume that all $p_i>C$ and hence the group morphism $\psi_i:(\Z/p_i^{a_i})^{d_1}\longrightarrow \Out(\Gamma)$ is trivial for all $i$. By \cref{aspherical manifolds big diagram} and \cref{inner actions aspherical manifolds}, each action induces a commutative diagram of fundamental groups 
	\[
	\begin{tikzcd}
		& 1\ar{d}{}& 1\ar{d}{}& & \\
		1\ar{r}{} & \Zc\Gamma\cong \Z^f \ar{r}{}\ar{d}{} & \Zc\Gamma_i\cong\Z^f\ar{r}{}\ar{d}{}& (\Z/p_i^{a_i})^{f}\ar{r}{}\ar{d}{Id} &1\\
		1\ar{r}{} & \Gamma \ar{r}{}\ar{d}{} & \Gamma_i\ar{r}{}\ar{d}{}& (\Z/p_i^{a_i})^{f}\ar{r}{} &1\\
		& \Gamma'\ar{d}{}\ar{r}{Id} & \Gamma'\ar{d}{} & &\\
		& 1 &1 & & \\
	\end{tikzcd}
	\]	
	where $\Gamma_i$ is the fundamental group of the nilmanifold $(N/\Gamma)/(\Z/p_i^{a_i})^{f}$ and the identity map of the third row is induced by the inclusion $\Inn(\Gamma)\longrightarrow\Aut(\Gamma)$. Moreover, notice that $\rank\Zc\Gamma_i=f$ for all $i$.

	We claim that the group morphism $\psi_i':(\Z/p_i)^{d_2}\longrightarrow \Out(\Gamma_i)$ is injective for big enough $i$. If not, there exists $\Z/p_i\leq \ker\psi_i'$ such that the action $\Z/p_i\acts N/\Gamma_i$ is inner. The first step of the iterated action is also inner. Thus, by \cref{inner actions simplifiable}, the free iterated action $\{(\Z/p_i^{a_i})^{f},\Z/p_i\}\acts N/\Gamma$ is equivalent to a free action of an abelian $p_i$-group $G_i$ of $\rank G_i=f$. The free iterated action $\{(\Z/p_i^{a_i})^{d_1},(\Z/p_i)^{d_2}\}\acts N/\Gamma$ is equivalent to $\{G_i,(\Z/p_i)^{d_2-1}\}\acts N/\Gamma$, which contradicts the fact that $\rank_{ab}(\{(\Z/p_i^{a_i})^{d_1},(\Z/p_i)^{d_2}\}\acts N/\Gamma)=f+d_2$.

	In consequence, we have a commutative diagram
	\[
	\begin{tikzcd}
		& 1\ar{d}{}& 1\ar{d}{}& & \\
		& \Z^f \ar{r}{Id}\ar{d}{} & \Z^f\ar{d}{}&  &\\
		1\ar{r}{} & \Gamma_i \ar{r}{}\ar{d}{} & \Gamma_{i_2}\ar{r}{}\ar{d}{}& (\Z/p_i)^{d_2}\ar{r}{}\ar{d}{\phi} &1\\
		1\ar{r}{} & \Gamma'\ar{d}{}\ar{r}{} & \Gamma_i'\ar{d}{}\ar{r}{} &(\Z/p_i)^{d_2}\ar{r}{} &1\\
		& 1 &1 & & \\
	\end{tikzcd}
	\]	
	where $\Gamma_{i_2}$ is the fundamental group of the quotient $(N/\Gamma)/\{(\Z/p_i^{a_i})^{d_1},(\Z/p_i)^{d_2}\}$. We claim that $\Gamma_i'$ is torsion-free for $i$ large enough. Firstly, $\Gamma_i'\leq\Aut(\Gamma_i)$. For each $i$ we have an injective morphism $\Aut(\Gamma_i)\longrightarrow \Aut(\Gamma_\Q)$, since all lattices $\Gamma_i\leq N$ are commensurable to $\Gamma$. Moreover, $\Aut(\Gamma_\Q)=\Aut(\mathcal{L}(\Gamma_\Q))\leq\Gl(m,\Q)$ for some $m$, where $\mathcal{L}(\Gamma_\Q)$ denotes the rational Lie algebra of $\Gamma_\Q$. Since any finite subgroup of $\Gl(m,\Q)$ is conjugated to a finite subgroup of $\Gl(m,\Z)$, we can conclude that each $\Gamma_i'$ is Minkowski with a constant $C'$ which does not depend on $i$. Finally, since $\Gamma'$ is torsion-free the torsion of $\Gamma_i'$ injects in $(\Z/p_i)^{d_2}$. Thus, $\Gamma_i'$ is torsion-free if $p_i>C$. 

	Since $\Out(\Gamma')$ is Minkowski with a constant not depending on $i$, we have a commutative diagram for $i$ large enough.
	\[
	\begin{tikzcd}
		& 1\ar{d}{}& 1\ar{d}{}& & \\
		1\ar{r}{} & \Zc \Gamma' \ar{r}{}\ar{d}{} & C_{\Gamma_{i}'}(\Gamma')\ar{r}{}\ar{d}{}& (\Z/p_i)^{d_2}\ar{r}{}\ar{d}{Id} &1\\
		1\ar{r}{} & \Gamma' \ar{r}{}\ar{d}{} & \Gamma_{i}'\ar{r}{}\ar{d}{}& (\Z/p_i)^{d_2}\ar{r}{} &1\\
		& \Inn\Gamma'\ar{d}{}\ar{r}{Id} & \Inn\Gamma'\ar{d}{} & &\\
		& 1 &1 & & \\
	\end{tikzcd}
	\]	

	Since $\Gamma_i'$ is torsion-free, the group $C_{\Gamma_i'}(\Gamma')$ is torsion-free. The first row of the diagram is central, hence $C_{\Gamma_{i}'}(\Gamma')$ is abelian and $d_2\leq \rank\Zc\Gamma'$. Furthermore, $\Gamma'$ is the fundamental group of the nilmanifold $N'/\Gamma'$, obtained as the orbit space of the free action of $\Zc N/\Zc\Gamma\cong T^f$ on $N/\Gamma$. Therefore, $\rank\Zc\Gamma'\leq\dim(N'/\Gamma')=n-f$. In conclusion, $d_2\leq n-f$. If $d_2=n-f$ then $N'/\Gamma'\cong T^{n-f}$ and $N/\Gamma$ is a $2$-step nilmanifold with $\rank\Zc\Gamma=f$, as we wanted to see.

	Let us now prove the converse implication. Suppose that $N/\Gamma$ is a 2-step nilmanifold with $f=\rank\Zc\Gamma$ and let $b=n-f$. Then $\Gamma\cong \Z^f\times_c\Z^b$, where $c:\Z^b\times\Z^b \longrightarrow \Z^f$ is a 2-cocycle representing a cohomology class $[c]\in H^2(\Z^b,\Z^f)=H^2(T^b,\Z^f)$ which determines the principal $T^f$-bundle $\pi:N/\Gamma\longrightarrow T^b$. The cocycle can be chosen to be of the form $$c((x_1,\dots,x_b),(y_1,\dots,y_b))=(\sum_{1\leq i<j\leq b} c_{i,j}^1x_iy_j,\dots,\sum_{1\leq i<j\leq b} c_{i,j}^fx_iy_j)$$ where $c_{i,j}^k\in\Z$ for all $1\leq i,j\leq f$ and $1\leq k\leq b$.

	For any prime $p$ we can define a free iterated action $\{(\Z/p^{2})^{f},(\Z/p)^{b}\}\acts N/\Gamma$. The first action is by right multiplication on the fiber $T^f$. The orbit space is a nilmanifold with fundamental group $\Gamma_p\cong (\tfrac{1}{p^2}\Z)^f\times_c\Z^b$, where $c:\Z^b\times\Z^b \longrightarrow \Z^f\subseteq (\tfrac{1}{p^2}\Z)^f$. The second step of the iterated action is by rotations on the torus of the basis $T^b$. More explicitly, we define the lattice $\Gamma'_p\cong (\tfrac{1}{p^2}\Z)^f\times_{c_p}(\tfrac{1}{p}\Z)^b$, where $c_p:(\tfrac{1}{p}\Z)^b\times(\tfrac{1}{p}\Z)^b \longrightarrow \Z^f\subseteq (\tfrac{1}{p^2}\Z)^f$ is of the form $$c((\tfrac{1}{p}x_1,\dots,\tfrac{1}{p}x_b),(\tfrac{1}{p}y_1,\dots,\tfrac{1}{p}y_b))=(\sum_{1\leq i<j\leq b} \tfrac{c_{i,j}^1}{p^2}x_iy_j,\dots,\sum_{1\leq i<j\leq b} \tfrac{c_{i,j}^f}{p^2}x_iy_j).$$ 
	We have that $\Gamma_p\trianglelefteq \Gamma_p'$ and  $\Gamma_p'/\Gamma_p\cong(\Z/p)^b$, which defines a free action of $(\Z/p)^b$ on $N/\Gamma_p$. 

	Moreover, $\rank_{ab}(\{(\Z/p^{2})^{f},(\Z/p)^{b}\}\acts N/\Gamma)=n$, therefore $(f,b)\leq \D_2(N/\Gamma)$. But the first part of the theorem implies that $\D_2(N/\Gamma)\leq(f,b)$. In consequence $\D_2(N/\Gamma)=(f,b)$.
\end{proof}

\section[Free iterated group actions and non-zero degree map to a nilmanifold]{Free iterated group actions on manifolds admitting a non-zero degree map to a nilmanifold}\label{sec: iterated actions hypernilmanifolds}

The aim of this section is to study the relation between the iterated discrete degree of symmetry and rigidity on manifolds which admit a non-zero degree map to a nilmanifold. In particular, we prove \cref{main theorem11 intro}. We start with a result on closed connected oriented manifolds admitting a non-zero degree map to a torus.

\begin{prop}\label{discsym2 hypertoral}
	Let $M$ be a closed oriented connected manifold of dimension $n$ and $f:M\longrightarrow T^n$ a non-zero degree map. Then $\D_2(M)\leq (n,0)$.
\end{prop}

\begin{proof}
	Suppose that $\D_2(M)=(d_1,d_2)$. Let $\{p_i\}_{i\in\mathbb{N}}$ be the increasing sequence of primes and let $\{(\Z/p_i^{a_i})^{d_1},(\Z/p_i)^{d_2}\}\acts M$ be the collection of free iterated actions given by the definition of the iterated discrete degree of symmetry. Note that we can assume without loss of generality that $p_i>\max\{\deg(f),C\}$ for all $i$, where $C$ is the Minkowski constant of $\Gl(r,\Z)$ with $r=\rank H^1(M,\Z)$. Consequently, the induced action of $(\Z/p_i^{a_i})^{d_1}$ on $H^1(M,\Z)$ is trivial for all $i$.

	By \cref{pE torus}, for each $i$ there exists a group morphism $\eta_i:(\Z/p_i^{a_i})^{d_1}\longrightarrow T^n$, which is injective since $|\ker\eta_i|\leq d<p_i$. Moreover, for each $i$ there exists a $\eta_i$-equivariant map $f_i:M\longrightarrow T^n$ homotopic to $f$. We consider the commutative diagram
	\[
	\begin{tikzcd}
		M \ar{r}{f_i}\ar{d}{} & T^n\ar{d}{}\\
		{M}_i\cong M/(\Z/p_i^{a_i})^{d_1} \ar{r}{f'_i} & T^n/(\Z/p_i^{a_i})^{d_1}\cong T^n
	\end{tikzcd}
	\]

	Note that $\deg(f'_i)=\deg(f)$ for all $i$. The first cohomology group does not have torsion, hence $\rank H^1({M}_i,\Z)=\rank H^1({M}_i,\Q)=\rank H^1(M,\Q)^{(\Z/p_i^{a_i})^{d_1}}=\rank H^1(M,\Q)=r$, where the last equality holds because the action of $(\Z/p_i^{a_i})^{d_1}$ on $H^1(M,\Q)$ is trivial. Since we have assumed that $p_i> C$ for all $i$ then the action of $(\Z/p_i)^{d_2}$ on $H^1({M}_i,\Z)$ is trivial for all $i$.

	Consequently, by \cref{pE torus}, for each $i$ there exists an injective group morphism $\eta'_i:(\Z/p_i)^{d_2}\longrightarrow T^n$ and a $\eta'_i$-equivariant map $h_i':{M}_i\longrightarrow T^n$ homotopic to $f'_i$. Since $T^n\longrightarrow T^n/(\Z/p_i^{a_i})^{d_1}$ is a principal $(\Z/p_i^{a_i})^{d_1}$-bundle, for each $i$ there exists a $(\Z/p_i^{a_i})^{d_1}$-equivariant homeomorphism between the total space of the pull-back $T^n\longrightarrow T^n/(\Z/p_i^{a_i})^{d_1}$ by $h'_i$ and $M$, which we denote by $\phi_i:(h'_i)^*T^n\longrightarrow M$. It induces a commutative diagram
	\[
	\begin{tikzcd}
		(h'_i)^*T^n\ar{rd}{h_i}\ar{d}{\phi_i} &\\	
		M \ar{r}{f_i} & T^n\\
	\end{tikzcd}
	\]
	Note that each $h_i$ is a $\{(\Z/p_i^{a_i})^{d_1},(\Z/p_i)^{d_2}\}$-equivariant map of degree $\deg(f)$. We have a commutative diagram 
	\[
	\begin{tikzcd}
		M \ar{r}{h_i}\ar{d}{} & T^n\ar{d}{}\\
		M_i \ar{r}{h_i'}\ar{d}{} & T^n/(\Z/p_i^{a_i})^{d_1}\cong T^n\ar{d}{}\\
		M_i/(\Z/p_i)^{d_2} \ar{r}{} & T^n/(\Z/p_i)^{d_2}\cong T^n
	\end{tikzcd}
	\]
	The induced iterated action $\{(\Z/p_i^{a_i})^{d_1},(\Z/p_i)^{d_2}\}\acts T^n$ is simplifiable by an abelian $p_i$-group $G_i$ for each $i$. 

	The map $h_i$ maps bijectively iterated orbits of $\{(\Z/p_i^{a_i})^{d_1},(\Z/p_i)^{d_2}\}\acts T^n$ to orbits of the action of $G_i$ on $T^n$. In consequence, we can simplify $\{(\Z/p_i^{a_i})^{d_1},(\Z/p_i)^{d_2}\}\acts M$ with a free action of $G_i$ on $M$. This implies that $d_1+d_2=\rank_{ab}(\{(\Z/p_i^{a_i})^{d_1},(\Z/p_i)^{d_2}\})=\rank(G_i)\leq n$. If $d_1<n$ then $\D_2(M)<(n,0)=\D_2(T^n)$. If $d_1=n$ then $d_2=0$ and therefore $\D_2(M)=(n,0)=\D_2(T^n)$.

\end{proof}

\begin{thm}\label{free iterated actions rigidity hypernilmanifolds}
	Let $M$ be a closed oriented connected $n$-dimensional manifold $M$ and $f:M\longrightarrow N/\Gamma$ a non-zero degree map where $N/\Gamma$ is a $2$-step nilmanifold. Then:
	\begin{itemize}
		\item[1.] $\D_2(M)\leq \D_2(N/\Gamma)$.
		\item[2.] If the map $f_*:\pi_1(M)\longrightarrow \Gamma$ is surjective and $\D_2(M)= \D_2(N/\Gamma)$ then $H^*(M,\Z)\cong H^*(N/\Gamma,\Z)$.
	\end{itemize}
\end{thm}

Before proving the theorem, let us show what happens if we remove the hypothesis of $f_*:\pi_1(M)\longrightarrow \Gamma$ being surjective from \cref{free iterated actions rigidity hypernilmanifolds}.2.

\begin{cor}\label{iterated action rational cohomology}
	Let $M$ be a closed oriented connected $n$-dimensional manifold $M$ and $f:M\longrightarrow N/\Gamma$ a non-zero degree map where $N/\Gamma$ is a $2$-step nilmanifold. If $\D_2(M)= \D_2(N/\Gamma)$ then $H^*(M,\Q)\cong H^*(N/\Gamma,\Q)$.
\end{cor}  

\begin{proof}
	The condition $d=\deg(f)\neq0$ implies that $[\Gamma:f_*\pi_1(M)]<\infty$. Therefore $f_*\pi_1(M)$ is a lattice of $N$ and we have a finite covering $N/f_*\pi_1(M)\longrightarrow N/\Gamma$. We can lift the map $f$ to a map $f'$, obtaining a commutative diagram 
	\[
	\begin{tikzcd}
		& N/f_*\pi_1(M)\ar{d}{}\\
		M\ar{r}{f}\ar{ru}{f'}& N/\Gamma
	\end{tikzcd}
	\]

	Note that $\deg(f')\neq 0$ and $f'_*:\pi_1(M)\longrightarrow f_*\pi_1(M)$ is surjective. Thus, we have a chain of isomorphisms $$H^*(M,\Q)\cong H^*(N/f_*\pi_1(M),\Q)\cong H^*(\mathcal{L}(N),\Q)\cong H^*(N/\Gamma,\Q).$$ 
\end{proof}

The proof of \cref{free iterated actions rigidity hypernilmanifolds} is a generalization of the arguments used to prove \cref{large group actions hypertoral manifolds}.2. in \cite{mundet2021topological}. We will divide the proof in six parts. The first two parts are analogous to \cref{discsym2 hypertoral} and will prove the first part of \cref{free iterated actions rigidity hypernilmanifolds}. We denote by $\tilde{M}$ the total space of the pull-back of $\rho:N\longrightarrow N/\Gamma$ by $f$. In the third and fourth part of the proof, we assume that $\D_2(M)=\D_2(N/\Gamma)$ and we discuss the structure of $H^*(\tilde{M},\Z)$ as $\Z\Gamma$-module. In part 5, we use non-commutative ring theory to prove that $\tilde{M}$ is an acyclic manifold. From this fact we deduce that $H^*(M,\Z)\cong H^*(N/\Gamma,\Z)$ in part 6.

Before starting the proof we fix some notation. We set $a=\dim \Zc N$ and $b=\dim N/\Zc N$. We have a projection map $\pi:N\longrightarrow \R^b$ with $\ker\pi=\Zc N$. thus, we have a short exact sequence \[\begin{tikzcd}
	1\ar{r}{}& \R^a\ar{r}{}& N\ar{r}{\pi}& \R^b\ar{r}{}& 1
\end{tikzcd}\]
Since $\Zc N$ is lattice hereditary, we have $\Zc\Gamma=\Zc N\cap \Gamma\cong \Z^a$ and $\pi(\Gamma)\cong \Z^b$. We have a normalized 2-cocycle $c:\Z^b\times \Z^b\longrightarrow \Z^a$ such that $\Gamma\cong \Z^a\times_c \Z^b$ and $N\cong \R^a\times_c \R^b$. We can write the 2-cocycle $c$ $$c((x_1,\dots,x_b),(y_1,\dots,y_b))=(\sum_{1\leq j,k\leq b}c_{jk}^1x_jy_k,\dots,\sum_{1\leq j,k\leq b}c_{jk}^ax_jy_k)$$
where $c_{jk}^l\in\Q$ and $c_{jk}^l=-c_{kj}^l$ for all $j,k,l$ and $c(\pi(\Gamma)\times\pi(\Gamma))\subseteq \Zc\Gamma$. 

We denote $e_i=((0,\dots,1,\dots,0),0)\in \Z^a\times_c \Z^b$, where the $1$ is in the $i$-th position. Similarly, we denote $e_i'=(0,(0,\dots,1,\dots,0))\in \Z^a\times_c \Z^b$, where the $1$ is in the $i$-th position. Note that the set $\{e_1,\dots,e_a,e_1',\dots,e'_b\}$ generates $\Gamma$.

Denote by $\tilde{M}$ the pull-back by $f$ of the universal cover $N\longrightarrow N/\Gamma$. %They fit in the commutative diagram
%\[
%\begin{tikzcd}
%	\tilde{M}\ar{d}{}\ar{r}{\tilde{f}} & N \ar{d}{}\\
%	\overline{M}\ar{d}{}\ar{r}{\overline{f}} & N/\Zc\Gamma \ar{d}{}\\
%	M\ar{r}{f} & N/\Gamma
%\end{tikzcd}
%\]

\textbf{Part 1. First step of the iterated actions:} Assume $\D_2(M)=(d_1,d_2)$ and $\D_2(N/\Gamma)=(a,b)$. 

Let $\{p_i\}$ be the sequence of increasing primes and let $\{a_i\}$ be a sequence of natural numbers such that we have a free action $\{(\Z/p_i^{a_i})^{d_1},(\Z/p_i)^{d_2}\}\acts M$ for each $i$. We can assume without loss of generality that $p_i>\max\{\deg(f),C\}$, where $C$ is the exporting map constant of $f$ (see \cref{pE defn} and \cref{thm: exporting map hypernilmanifolds}). In consequence, there exists an inner free action $(\Z/p_i^{a_i})^{d_1}$ on $N/\Gamma$ and a $(\Z/p_i^{a_i})^{d_1}$-equivariant map $f_i:M\longrightarrow N/\Gamma$ which is homotopic to $f$ for each $i$. In particular, $d_1\leq a$. If the inequality is strict then the first part of the theorem is proven. Thus, we will assume that $d_1=a$.

\textbf{Part 2. Second step of the iterated action:} Before we continue with the proof we introduce some notation. We denote by $M_i$ the orbit space $M/(\Z/p_i^{a_i})^{d_1}$ and by $\pi_i:M\longrightarrow M_i$ the orbit map. The quotient $(N/\Gamma)/(\Z/p_i^{a_i})^{d_1}$ is a nilmanifold with the same simply connected nilpotent Lie group $N$ and lattice $\Gamma_i$, which fits into the short exact sequence
\[
\begin{tikzcd}
	1 \ar{r}{}& \Gamma \ar{r}{}& \Gamma_i \ar{r}{}& (\Z/p_i^{a_i})^{d_1}  \ar{r}{}&1 .
\end{tikzcd}
\]

The map $f_i$ induces a map $f_i':M_i\longrightarrow N/\Gamma_i$ for each $i$. We have a commutative diagram
\[
\begin{tikzcd}
	M\ar{dd}{\pi_i}\ar{rr}{f_i} && N/\Gamma\ar{dd}{}\ar{rd}{q}&\\
	&&& T^b\ar{dd}{id}\\
	M_i\ar{rr}{f'_i} && N/\Gamma_i\ar{rd}{q_i}&\\
	&&& T^b
\end{tikzcd}
\]

Note that $q_i\circ f_i'\circ\pi_i$ is homotopic to $q\circ f$ and $\deg(f_i')=\deg(f)$. 

By Minkowski's lemma, there exists a constant $C'$ such that $(\Z/p_i^{a_i})^{d_1}$ acts trivially on $H^*(M,\Q)$ for all $p_i\geq C'$. The map $\pi_i$ induces an isomorphism in cohomology $H^*(M_i,\Q)\cong H^*(M,\Q)^{(\Z/p_i^{a_i})^{d_1}}=H^*(M,\Q)$. Since the first cohomology group has no torsion, we have $H^1(M_i,\Z)\cong H^1(M,\Z)$. The action of $(\Z/p_i)^{d_2}$ on $M_i$ induces an action of $(\Z/p_i)^{d_2}$ on $H^1(M_i,\Z)$. Since $H^1(M_i,\Z)$ does not depend on $i$ up to isomorphism, we can use Minkowski's lemma again to conclude that there exists a constant $C''>C'$ such that the action of $(\Z/p_i)^{d_2}$ on $H^1(M_i,\Z)$ is trivial for $p_i\geq C''$. Thus, we can assume without loss of generality that the action of $(\Z/p_i)^{d_2}$ on $H^1(M_i,\Z)$ is trivial.

We consider the map $q_i\circ f_i':M_i\longrightarrow T^b$, for each $i$. Since $(\Z/p_i)^{d_2}$ acts trivially on $H^1(M_i,\Z)$, there exist a group morphism $\eta_i':(\Z/p_i)^{d_2}\longrightarrow T^b$ and a $\eta_i'$-equivariant map $F_i:M_i\longrightarrow T^b$ homotopically equivalent to $q_i\circ f_i'$. If $\eta_i'$ is injective then $\D_2(M)=(a,d_2)\leq (a,b)=\D_2(N/\Gamma)$ and the first part of the theorem would be proved.

Our next goal is to prove that $\eta_i'$ is injective. We divide the proof in two lemmas, since the first lemma will be also useful in other steps of the proof. Recall that $X(\pi_1(M_i),N)$ is the set of isomorphism classes of $N$-local systems, $X(\pi_1(M_i),N)=\Hom(\pi_1(M),N)/\sim$.

\begin{lem}\label{eta trivial action}
	There exists a constant $D$ such that the action of $(\Z/p_i)^{d_2}$ on $X(\pi_1(M_i),N)$ is trivial for $p_i\geq D$.
\end{lem}

\begin{proof}
	We will prove that the restriction of the action of $(\Z/p_i)^{d_2}$ on $X(\pi_1(M_i),N)$ to any cyclic subgroup of $\Z/p_i$ is trivial. Thus, we will study actions of $\Z/p_i$ on $X(\pi_1(M_i),N)$. Recall that we also assume that $p_i>C''$ and therefore $\Z/p_i$ acts trivially on $H^1(M_i,\Z)$.  

	Let us fix some more notation. Let $\phi_i\in\Homeo(M_i)$ be the homeomorphism induced by the action of $\Z/p_i$ on $M_i$ corresponding to $\overline{1}\in\Z/p_i$, $\pi:N\longrightarrow \R^b$ is the projection such that $\ker \pi=\Zc N\cong \R^a$ and $\iota_i:\Gamma_i\longrightarrow N$ is an injective morphism. Set $\mu_i=\iota_i\circ f'_{i*}$ and consider the representative $[\mu_i]\in X(\pi_1(M_i),N)$. We consider the morphism $q_i\circ \mu_i\in X(\pi_1(M_i),\R^b)=\Hom(\pi_1(M_i),\R^b)$ (note that we do not have the conjugation equivalence relation since $\R^b$ is abelian). Since $\Z/p_i$ acts trivially on $H^1(M_i,\Z)$, we have $q_i\circ \mu_i \circ \phi_{i*}=q_i\circ \mu_i$. Therefore, we can define a map $\zeta_i:\pi_1(M_i) \longrightarrow \R^f$ such that 
	$$\zeta_i(\alpha)=\mu_i(\phi_{i*}(\alpha))\mu_i(\alpha)^{-1} $$ for $\alpha\in\pi_1(M_i)$. It is well defined since the image is inside $\ker \pi=\Zc N\cong \R^a$ and it is also a group morphism. Indeed, we have

	\begin{align*}
		\zeta_i(\alpha\beta)&=\mu_i(\phi_{i*}(\alpha))\mu_i(\phi_{i*}(\beta))\mu_i(\beta)^{-1}\mu_i(\alpha)^{-1}\\&=\mu_i(\phi_{i*}(\alpha))\mu_i(\alpha)^{-1}\mu_i(\phi_{i*}(\beta))\mu_i(\beta)^{-1}=\zeta_i(\alpha)\zeta_i(\beta)
	\end{align*}

	for $\alpha,\beta\in \pi_1(M_i)$, where we use that $\mu_i(\phi_{i*}(\beta))\mu_i(\beta)^{-1}\in\Zc N$. Consequently, $\zeta_i\in\Hom(\pi_1(M_i),\R^a)$. Note that $\Z/p_i$ acts on $\Hom(\pi_1(M_i),\R^a)$ by precomposition, therefore it fixes a lattice of $\R^a$. Thus, by Minkowski lemma, there exists a constant $D>C''$ such that $\Z/p_i$ acts trivially on $\Hom(\pi_1(M_i),\R^a)$. From now on we assume that $p_i\geq D$. This implies that $\zeta_i\circ\phi_{i*}=\zeta_i$.

	On the other hand $[\mu_i\circ \phi^p_{i*}]=[\mu_i]$ and therefore there exists $n\in N$ such that $n\mu_i (\phi^p_{i*}(\alpha))=\mu_i(\alpha)n$ for all $\alpha\in \pi_1(M_i)$. A computation shows that
	$$[\mu_i(\alpha),n]=\sum_{j=0}^{p_i-1}\zeta_i(\phi^{j}_{i*}(\alpha))=\zeta_i(\alpha)^{p_i}.$$

	Recall that $N=\R^a\times_c\R^b$ where $c:\R^b\times \R^b\longrightarrow \R^a$ is a normalized $2$-cocycle such that $c(\pi(\Gamma)\times\pi(\Gamma))\subseteq\Zc\Gamma$. Since $\pi(\Gamma)=\pi(\Gamma_i)$ for all $i$, we have $c(\pi(\Gamma_i)\times\pi(\Gamma_i))\subseteq\Zc\Gamma\subseteq\Zc\Gamma_i$ for all $i$. Using $N\cong \R^a\times_c \R^b$, we can write $n=(x,y)$ and $\mu_i(\alpha)=(\mu_i'(\alpha),\pi(\mu_i(\alpha)))$.

	A straightforward computation shows that the conjugation by $n$ takes the form 
	$$c_n(\mu_i(\alpha))=(\mu_i'(\alpha)+c(y,\pi(\mu_i(\alpha)))-c(\pi(\mu_i(\alpha)),y),\pi(\mu_i(\alpha))).$$ 
	Hence
	$$\zeta_i(\alpha)^{p_i}=c(y,\pi(\mu_i(\alpha)))-c(\pi(\mu_i(\alpha)),y).$$
	We define $m=(x,\tfrac{y}{p})\in \R^a\times_c\R^b$, which satisfies
	$$\zeta_i(\alpha)=c(\tfrac{y}{p},\pi(\mu_i(\alpha)))-c(\pi(\mu_i(\alpha)),\tfrac{y}{p}).$$ Summarising the previous computations, we showed that $\mu_i\circ\phi_{i*}=c_{m}\circ\mu_i$ which implies that $[\mu_i\circ\phi_{i*}]=[\mu_i]\in X(\pi_1(M_i),N)$, as we wanted to prove.
\end{proof}

\begin{lem}\label{eta injective}
	The morphism $\eta_i'$ is injective for all $p_i\geq D$.
\end{lem}
\begin{proof}
	Assume that $\eta'_i$ is not injective and take $\Z/p_i\leq \ker\eta'_i$. Then, the free iterated action of $\{(\Z/p_i^{a_i})^{a},\Z/p_i,(\Z/p_i)^{d_2-1}\}\acts M$ is equivalent to $\{(\Z/p_i^{a_i})^a,(\Z/p_i)^{d_2}\}\acts M$. We will prove that $\{(\Z/p^{a_i}_i)^{a},\Z/p_i\}\acts M$ is simplifiable by an abelian group of rank $a$. This will imply that $\rank_{ab}(\{(\Z/p_i^{a_i})^a,(\Z/p_i)^{d_2}\}\acts M)<a+d_2$, which is a contradiction with the assumption that $\D_2(M)=(a,d_2)$.

	Firstly, note that $F_i(gx)=\eta'_i(g)F_i(x)=F_i(x)$ for all $g\in\Z/p$ and $x\in M_i$. Using the homotopy lifting property, we can replace $f_i'$ by a homotopic map $f''_i:M_i\longrightarrow N/\Gamma_i$ such that $f''_i=q_i\circ F_i$. Note that the orbits of the action of $\Z/p_i$ are inside the fibers of $q_i:N/\Gamma_i\longrightarrow T^b$.

	By \cref{eta trivial action} and \cref{pE local systems trivial action}, there exists a $\Z/p_i$ action on $N/\Gamma_i$ and a $\Z/p_i$-equivariant map $h'_i:M_i\longrightarrow N/\Gamma_i$ homotopic to $f_i''$, and hence homotopic to $f_i'$. The orbit space $(N/\Gamma_i)/(\Z/p_i)$ is a nilmanifold $N/\Gamma_i'$. The equality $\eta_i'(\Z/p_i)=0$ implies that $\pi(\Gamma_i)=\pi(\Gamma_i')$ which leads to the commutative diagram \[\begin{tikzcd}
		& 1\ar{d}{}& 1 \ar{d}{}& & \\
		1\ar{r}{}& \Zc\Gamma_i\ar{d}{}\ar{r}{}& \Zc\Gamma_i \ar{d}{}\ar{r}{}& \Z/p_i \ar{d}{id}\ar{r}{}& 1\\
		1\ar{r}{}& \Gamma_i\ar{d}{}\ar{r}{}& \Gamma'_i \ar{d}{}\ar{r}{p}&\Z/p_i \ar{r}{}& 1\\
		& \pi(\Gamma_i)\ar{d}{}\ar{r}{id}&  \pi(\Gamma'_i) \ar{d}{}& & \\	
		& 1& 1 &  & \\
	\end{tikzcd}\]

	The action of $\Z/p_i$ on $N/\Gamma_i$ is inner, hence $\{(\Z/p^{a_i}_i)^{a},\Z/p_i\}\acts N/\Gamma$ is simplifiable by an abelian group $A_i$ (see \cref{inner actions simplifiable}). Thus, $\rank_{ab}(A_i)\leq a=\rank\Zc\Gamma$. In conclusion $\{(\Z/p_i^{a_i})^{a},(\Z/p_i)^{d_2}\}\acts M$ is equivalent to $\{A_i,(\Z/p_i)^{d_2-1}\}\acts M$ and therefore $\rank_{ab}(\{(\Z/p_i^{a_i})^{a},(\Z/p_i)^{d_2}\}\acts M)\leq a+d_2-1$, as we wanted to see.
\end{proof}

Since $\eta'_i:(\Z/p_i)^{d_2}\longrightarrow T^b$ is injective, $d_2\leq b$. Thus, the proof of item 1 of \cref{free iterated actions rigidity hypernilmanifolds} is completed.

If $\eta_i':(\Z/p_i)^{d_2}\longrightarrow T^b$ is injective then the action of $(\Z/p_i)^{d_2}$ on $\Hom(\pi_1(M_i),\R^b)$ is trivial. By \cref{eta trivial action}, the action of $(\Z/p_i)^{d_2}$ on $\Hom(\pi_1(M_i),N)$ is trivial. Thus, we can construct a $(\Z/p_i)^{d_2}$ action on $N/\Gamma_i$ and a $(\Z/p_i)^{d_2}$-equivariant map $h'_i:M_i\longrightarrow N/\Gamma_i$ such that $q_i\circ h'_i:M_i\longrightarrow T^b$ is $\eta_i'$-equivariant.

\textbf{Part 3. $H^*(\tilde{M},\Z)$ as a $\Z\Gamma$-module:} The action of $\Gamma$ on $\tilde{M}$ induces an action on $H^*(\tilde{M},\Z)$, which we denote by $\Phi:\Gamma\longrightarrow \Aut_\Z(H^*(\tilde{M},\Z))$. Thus, $H^*(\tilde{M},\Z)$ has a structure of $\Z\Gamma$-module. To prove the following lemma we use the same argument as in \cite[Lemma 8.2]{mundet2021topological}

\begin{lem}\label{cohomology fg group ring}
	$H^*(\tilde{M},\Z)$ is finitely generated as a $\Z\Gamma$-module.
\end{lem}

\begin{proof}
	Recall that compact manifolds are Euclidean Neighbourhood Retracts (see, for example, \cite[Corollary A.9]{hatcher2002algebraic}) and therefore we can identify $M$ with a closed subset of $\R^m$ for some $m$ large enough such that there exist an open neighbourhood $U\subseteq \R^m$ of $M$ and a retraction $r:U\longrightarrow M$. Given $x\in M$ let $B_x$ denote an open ball centred at $x$ and contained in $U$. By the compactness of $M$ there exists a collection of point $x_1,\dots, x_s$ in $M$ such that $M\subseteq\bigcup_{i=1}^s B_{x_i}=B$. Let $F=f\circ r:B\longrightarrow N/\Gamma$, $B_i=B_{x_i}$ and $F_i=f\circ r:B_i\longrightarrow N/\Gamma$.

	Since $B_{i}$ is contractible, the principal $\Gamma$-bundle $F_i^*\pi:F_i^*N\longrightarrow B_i$ obtained by pulling back the universal covering $\pi:N\longrightarrow N/\Gamma$ by $F_i$ is trivial. This implies that for every subset $S\subseteq B_i$, we have $H^*((F_i^*\pi)^{-1}(S),\Z)\cong H^*(S,\Z)\otimes_\Z\Z\Gamma$. So if $H^*(S,\Z)$ is finitely generated then $H^*((F_i^*\pi)^{-1}(S),\Z)$ is finitely generated as $\Z\Gamma$-module.

	Let $B_{\leq j}=B_1\cup\dots\cup B_j$ and $F_{\leq j}=f\circ r_{|B_{\leq j}}:B_{\leq j}\longrightarrow N/\Gamma$. To ease notation, we set $X_i=(F_i^*\pi)^{-1}(B_i)$ and $X_{\leq i}=(F_{\leq i}^*\pi)^{-1}(B_{\leq i})$. We will prove using the Mayer-Vietoris long exact sequence that $H^*(X_{\leq j},\Z)$ is finitely generated as $\Z\Gamma$-module. 

	If $j=1$ then $H^*(X_{\leq 1},\Z)\cong H^*(X_{1},\Z)\cong\Z\Gamma$ and hence it is finitely generated. Assume now that $H^*(X_{\leq j-1},\Z)$ is a finitely generated $\Z\Gamma$-module. By using that $B_{\leq j}=B_{\leq j-1}\cup B_j$, we have a long exact sequence of $\Z\Gamma$-modules:
	$$
	\dots \longrightarrow H^{k}(X_{\leq j},\Z)\longrightarrow H^{k}(X_{\leq j-1},\Z)\oplus H^{k}(X_{j},\Z)\longrightarrow H^{k}(X_{\leq j}\cap X_{j},\Z)\longrightarrow \dots 
	$$

	Since $H^*(B_{\leq j-1}\cap B_j,\Z)$ is finitely generated and it is a subset of $B_j$, the cohomology group $H^{k}(X_{\leq j}\cap X_{j},\Z)$ is a finitely generated $\Z\Gamma$-module. By induction hypothesis, we have that $H^{k}(X_{\leq j-1},\Z)\oplus H^{k}(X_{j},\Z)$ is finitely generated. We can conclude that $H^k(X_{\leq j},\Z)$ is finitely generated. Finally, $H^k(X_{\leq j},\Z)=0$ for $k>m$ implies that $H^*(X_{\leq j},\Z)$ is a finitely generated $\Z\Gamma$-module.

	Since we have an inclusion $i:M\longrightarrow B$ and a retraction $r:B\longrightarrow M$, the $\Z\Gamma$-module $H^*(\tilde{M},\Z)$ is a $\Z\Gamma$-submodule of $H^*((F^*\pi)^{-1}(B),\Z)$. Since $H^*((F^*\pi)^{-1}(B),\Z)$ is finitely generated and $\Z\Gamma$ is Noetherian (see \cite[Theorem 1.16]{goodearl2004introduction}), $H^*(\tilde{M},\Z)$ is finitely generated as $\Z\Gamma$-module.
\end{proof}

\textbf{Part 4. Setting for the proof of the second part of the theorem:} We suppose now that $(d_1,d_2)=(a,b)$. %By \cref{eta injective}, we can assume without loss of generality that $\eta_i'$ is injective. Then  $\eta_i'((\Z/p_i)^b)\cong\langle[\tfrac{1}{p_i},0,\dots,0],\dots,[0,0,\dots,\tfrac{1}{p_i}]\rangle$. 
By \cref{thm: exporting map hypernilmanifolds}, there exists a $\{(\Z/p_i^{a_i})^a,(\Z/p_i)^b\}$-equivariant map $h_i:M\longrightarrow N/\Gamma$ homotopic to $f$ for all $i$. Hence, for each $i$ there exist non-zero degree maps $h_i':M_i\longrightarrow N/\Gamma_i$ and $h_i'':M_i/(\Z/p_i)^b=M_i'\longrightarrow N/\Gamma_i'$ such that the following diagram commutes
\[
\begin{tikzcd}
	M\ar{d}{}\ar{r}{h_i} & N/\Gamma \ar{d}{}\\
	M_i\ar{d}{}\ar{r}{h_i'} & N/\Gamma_i \ar{d}{}\\
	M_i'\ar{r}{h_i''} & N/\Gamma_i'
\end{tikzcd}
\]
The vertical arrows are the orbit maps of the iterated group actions on $M$ and $N/\Gamma$. 

In this part of the proof we show that there exists group morphism $\Phi'_i:\Gamma'_i\longrightarrow \Aut_\Z(H^*(\tilde{M},\Z))$ such that $\Phi'_{i|\Gamma}=\Phi$ for each $i$. We will construct $\Phi'_i$ in two steps. First, we construct a group morphism $\Phi_i:\Gamma_i\longrightarrow \Aut_\Z(H^*(\tilde{M},\Z))$ such that $\Phi_{i|\Gamma}=\Phi$. Thereafter, we construct a group morphism $\Phi'_i:\Gamma'_i\longrightarrow \Aut_\Z(H^*(\tilde{M},\Z))$ such that $\Phi'_{i|\Gamma_i}=\Phi_i$. 

\begin{lem}\label{Gamma-modules 1}
	The action of $\Gamma_i$ on $H^*(\tilde{M},\Z)$ induces a morphism $\Phi_i:\Gamma_i\longrightarrow \Aut_\Z(H^*(\tilde{M},\Z))$ such that $\Phi_{i|\Gamma}=\Phi$ for all $i$.
\end{lem}

\begin{proof} 
	We denote by $\tilde{M}_i$ the total space of the pull-back of $N\longrightarrow N/\Gamma$ by $h_i:M\longrightarrow N/\Gamma$. Similarly, we denote by $\tilde{M}_i'$ the pull-back of $N\longrightarrow N/\Gamma_i$ by $h_i':M_i\longrightarrow N/\Gamma_i$. 

	We also have a free action of $\Gamma_i'$ on $\tilde{M}_i'$. We consider the commutative diagram
	\[\begin{tikzcd}
		\tilde{M}_i\ar{dd}{}\ar{rr}{}\ar{rd}{\zeta_i'} & & N\ar{rd}{Id_N}\ar{dd}{}&\\
		& \tilde{M}_i'\ar{dd}{}\ar{rr}{} & & N\ar{dd}{}\\
		M\ar{rr}{h_i}\ar{rd}{} & & N/\Gamma\ar{rd}{}&\\
		& M'_i\ar{rr}{h_i'} & & N/\Gamma_i
	\end{tikzcd}\]

	The maps $\tilde{M}_i'\longrightarrow M_i$ and $\tilde{M}_i\longrightarrow M_i$ are isomorphic coverings. Thus, $\tilde{M}_i$ admits a free action of $\Gamma_i$ and the map $\zeta_i':\tilde{M}_i\longrightarrow \tilde{M}'_i$ is a $\Gamma_i$ equivariant homeomorphism. By construction, the restriction to $\Gamma$ of the action of $\Gamma_i$ on $\tilde{M}_i$ is the action induced by the pull-back of $N\longrightarrow N/\Gamma$ by $h_i:M\longrightarrow N/\Gamma$. Thus, the action of $\Gamma_i$ on $\tilde{M}_i$ induces a group morphism $\Psi'_i:\Gamma_i\longrightarrow \Aut_\Z(H^*(\tilde{M_i},\Z))$ such that $\Psi'_{i|\Gamma}=\Psi_i$.


	Since, $h_i$ is homotopic to $f$, there exists a $\Gamma$-equivariant homeomorphism $\zeta_i:\tilde{M}\longrightarrow \tilde{M}_i$ which induces an isomorphism of $\Z\Gamma$-modules $\zeta_i^*:H^*(\tilde{M}_i,\Z)\longrightarrow H^*(\tilde{M},\Z)$. We define $\Phi_i:\Gamma_i\longrightarrow \Aut_\Z(H^*(\tilde{M},\Z))$ as $\Phi_i(\gamma)=\zeta_i^*\circ\Psi_i(\gamma)\circ(\zeta_i^*)^{-1}$. Since $\zeta_i^*$ is an isomorphism of $\Z\Gamma$, we have $\Phi_{i|\Gamma}=\Phi$.
\end{proof}

The proof of the next lemma is analogous to the proof of \cref{Gamma-modules 1}.

\begin{lem}\label{Gamma-module 2}
	The action of $\Gamma'_i$ on $H^*(\tilde{M},\Z)$ induces a morphism $\Phi'_i:\Gamma'_i\longrightarrow \Aut_\Z(H^*(\tilde{M},\Z))$ such that $\Phi'_{i|\Gamma}=\Phi$.
\end{lem}

\begin{proof}
	We continue using the same notation introduced in \cref{Gamma-modules 1}. We denote by $\tilde{M}_i''$ the pull-back of $N\longrightarrow N/\Gamma'_i$ by $h_i'':M_i\longrightarrow N/\Gamma'_i$.

	We also have a free action of $\Gamma'_i$ on $\tilde{M}_i'$. We consider the commutative diagram
	\[\begin{tikzcd}
		\tilde{M}'_i\ar{dd}{}\ar{rr}{}\ar{rd}{\zeta_i''} & & N\ar{rd}{Id_N}\ar{dd}{}&\\
		& \tilde{M}''_i\ar{dd}{}\ar{rr}{} & & N\ar{dd}{}\\
		M_i\ar{rr}{h'_i}\ar{rd}{} & & N/\Gamma_i\ar{rd}{}&\\
		& M'_i\ar{rr}{h_i''} & & N/\Gamma'_i
	\end{tikzcd}\]

	The maps $\tilde{M}_i'\longrightarrow M_i'$ and $\tilde{M}''_i\longrightarrow M_i'$ are isomorphic coverings. Thus, $\tilde{M}_i'$ admits a free action of $\Gamma_i'$ and the map $\zeta_i'':\tilde{M}_i\longrightarrow \tilde{M}'_i$ is a $\Gamma_i'$-equivariant homeomorphism. By construction, the restriction to $\Gamma_i$ of the action of $\Gamma_i'$ on $\tilde{M}_i$ is the action induced by the pull-back of $N\longrightarrow N/\Gamma$ by $h_i:M\longrightarrow N/\Gamma$. Thus, the action of $\Gamma_i'$ on $\tilde{M}_i'$ induces a group morphism $\Psi''_i:\Gamma_i'\longrightarrow \Aut_\Z(H^*(\tilde{M}_i',\Z))$ satisfying $({\zeta_i'}^*\circ \Psi''_i \circ ({\zeta_i'}^*)^{-1})_{|\Gamma_i}=\Psi_i'$, where ${\zeta_i'}^*:H^*(\tilde{M}'_i,\Z)\longrightarrow H^*(\tilde{M}_i,\Z)$ is the isomorphism of $\Z\Gamma_i$-modules induced by $\zeta_i'$ defined in \cref{Gamma-modules 1}.

	Finally, we can define $\Phi_i''$ as $\Phi_i''(\gamma)=({\zeta_i^*\circ\zeta_i'}^*)\circ \Psi''_i(\gamma) \circ ({\zeta_i^*\circ\zeta_i'}^*)^{-1}$. Since ${\zeta_i'}^*$ is an isomorphism of  $\Z\Gamma_i$-modules, we have $\Phi''_{i|\Gamma_i}=\Phi_i$.
\end{proof}

\textbf{Part 5. $H^*(\tilde{M},\Z)$ is a finitely generated $\Z$-module:} 
Our objective in part 5 of the proof will be to prove that $H^*(\tilde{M},\Z)$ is finitely generated as a $\Z$-module. 

Recall that $\Gamma_i/\Gamma\cong \Zc\Gamma_i/\Zc\Gamma\cong (\Z/p_i^{a_i})^a$ and $\Gamma'_i/\Gamma_i\cong q(\Gamma_i)/q(\Gamma)\cong (\Z/p_i)^b$. Note that $\Gamma_i\cong (\tfrac{1}{p_i^{a_i}}\Z)^f\times_c\Z^b$ and $\Gamma_i'\cong (\tfrac{1}{p_i^{a_i}}\Z)^f\times_c(\tfrac{1}{p_i}\Z)^b$. The lattice $\Gamma_i'$ is generated $\{\tfrac{1}{p_i^{a_i}}e_1,\dots,\tfrac{1}{p_i^{a_i}}e_a,e_1',\dots,e'_b\}$ and $\Gamma_i''$ is generated by $\{\tfrac{1}{p_i^{a_i}}e_1,\dots,\tfrac{1}{p_i^{a_i}}e_a,\tfrac{1}{p_i}e_1',\dots,\tfrac{1}{p_i}e'_b\}$.

By \cref{Gamma-modules 1} and \cref{Gamma-module 2}, for each $1\leq j\leq a$ there exists a collection $\{w_{j,i}\}_{i\in\mathbb{N}}$ of automorphisms of $H^*(M,\Z)$ satisfying that $(w_{j,i})^{p_i^{a_i}}=\Phi(e_j)$. Similarly, for each $1\leq j\leq b$ there exists a collection $\{w'_{j,i}\}_{i\in\mathbb{N}}$ of automorphisms of $H^*(M,\Z)$ satisfying that $(w_{j,i}')^{p_i}=\Phi(e'_j)$.

Recall that $\Z\Gamma$ is an iterated skew-Laurent ring generated by $\{e_1^{\pm1},\dots,e_a^{\pm1},{e_1'}^{\pm1},\dots,{e_b'}^{\pm1}\}$ (see \cite[pg. xvii]{goodearl2004introduction}). Explicitly, $\Z\Gamma\cong \Z[e_1^{\pm1},\dots,e_a^{\pm1},{e_1'}^{\pm1},\dots,{e_b'}^{\pm1};\alpha_1,\cdots,\alpha_{a+b}]$ where the automorphism are defined using the cocycle $c$. 

The main theorem of this part is the generalization of \cite[Theorem 6.1]{mundet2021topological}. Be aware that the ring $R$ involved in the theorem below is in general not commutative. We refer to \cite{bell1988notes} and \cite{goodearl2004introduction} for an introduction to the theory of non-commutative Noetherian rings and, in particular, to the theory of localization on those rings.

\begin{thm}\label{non commutative finitely generation modules}
	Let $R$ be a prime Noetherian ring such that any prime ideal $\mathfrak{p}$ is right localizable. Given an automorphism $\alpha:R\longrightarrow R$, we consider the skew-polynomial ring $R[z;\alpha]$. Suppose that $X$ is a finitely generated $R[z;\alpha]$-module and that there exists a sequence of positive integers $r_j\longrightarrow\infty$ and a collection of automorphisms $w_j:X\longrightarrow X$ such that $w_j^{r_j}$ coincides with the multiplication by $z$ on the right. Then $X$ is finitely generated as $R$-module. 
\end{thm}

\begin{proof}
	Let $S=\{x_1,\dots,x_s\}$ be a generating set of $X$ as a $R[z;\alpha]$-module and let $X_0\subseteq X$ be the $R$-module generated by $S$. Consider the increasing sequence of finitely generated $R$-modules $X_0\subseteq X_1\subseteq X_2\subseteq\cdots$ defined by the condition $X_i=X_{i-1}+X_{i-1}z$. Multiplication by $z$ induces surjective morphisms of $R$-modules $\mu_i:X_{i-1}/X_{i-2}\longrightarrow X_{i}/X_{i-1}$ and thus we can define surjective maps $\nu_i=\mu_i\circ\cdots\circ \mu_1:X_0\longrightarrow X_{i}/X_{i-1}$. We have an increasing sequence $K_0\subseteq K_1\subseteq K_2\subseteq \cdots$ of submodules of $X_0$ where $K_i=\ker\nu_i$. Since $R$ is Noetherian and $X_0$ is finitely generated there exists a $i_0$ such that $K_i=K_{i_0}$ for all $i\geq i_0$. In particular, $\mu_i$ is an isomorphism for all $i_0$.

	Let $Y=X_{i_0}/X_{i_0-1}$. If $Y=0$ then $X=X_{i_0-1}$ and we are done. Thus we will assume that $Y\neq 0$ and reach a contradiction. Since $Y$ is a finitely generated $R$-module and $R$ is Noetherian, there exists an increasing series of submodules $0=Y_0\subseteq Y_1\subseteq \cdots \subseteq Y_r=Y$ such that $Y_i/Y_{i-1}$ is a prime module (see \cite[Proposition 3.13, Proposition 3.14]{goodearl2004introduction}). Let $\mathfrak{p}$ denote a minimal prime ideal of the collection of the associated prime ideals $\{\mathfrak{p}_1,\dots,\mathfrak{p}_r\}$. We can now consider the right localization $R_\mathfrak{p}$ and we can also consider the localization $Y_\mathfrak{p}$. Since localizing is an exact functor (see \cite[Lemma 1.3]{bell1988notes}), $(Y_{i\mathfrak{p}}/Y_{i-1\mathfrak{p}})=(Y_{i}/Y_{i-1})_{\mathfrak{p}}$. Moreover, $R_\mathfrak{p}/\mathfrak{p}R_\mathfrak{p}$ is simple Artinian (see \cite[Theorem 1.10]{bell1988notes} and \cite[Corollary 2.2]{bell1988notes}), hence the length $\lenght(Y_\mathfrak{p})=\lambda $ of the composition series is finite. % and since $(R/\mathfrak{p}_i)_\mathfrak{p}$ is either $0$ or simple Artinian, the length of the composition series is precisely $\lenght(N_\mathfrak{p})=|\{\mathfrak{p}_i:\mathfrak{p}=\mathfrak{p}_i\}|$.

	We will now prove that there cannot exists any $R[z;\alpha]$-module automorphism $w$ such that $w^r=z$ with $r>\lambda$ by reaching a contradiction. Thus, assume that there exists an automorphism $w:X\longrightarrow X$ such that $w^r=z$ and $r>\lambda$. Consider the following $R$-modules defined recursively as $X'_0=X_0$ and $X_i'=X'_{i-1}+w(X'_{i-1})$ for $i\geq 1$. Using the same arguments as above, there exists a $i_0'$ such that $\mu_i':X'_{i-1}/X'_{i-2}\longrightarrow X'_{i}/X'_{i-1}$ is an isomorphism for all $i\geq i_0'$. Let $Y'=X'_{i_0'}/X'_{i_0'-1}$.

	It is clear that $X_i\subseteq X'_{ri}$ for all $i$. On the other hand, since $X$ is finitely generated as a $R[z;\alpha]$-module we can write $$w^j(x_k)=x_1P_{jk1}+\cdots+x_sP_{jks}$$ for $j=1,\dots, r-1$ and $k=1,\dots, s$, where $P_{jkl}$ are polynomials in $z$ with coefficients in $R$. Let $e=\max\deg P_{jkl}$. Then $w^j(x_k)\in X_e$ for $j=1,\dots r-1$ and $k=1,\dots, s$. This implies that $X_i'\subseteq X_{[i/r]+e}$ for any $i$. Thus, we have inclusions $X_{i}\subseteq X'_{ir}\subseteq X_{i+e}$. 

	The next step is to localize at $\mathfrak{p}$ in order to use the length of the composition series. Firstly, we consider the inclusions $X_{i+L}\subseteq X'_{(i+L)r}\subseteq X_{i+L+e}$ where $L$ is  large number which we will determine below. If we fix $i$ such that $i\geq i_0$ and $i\geq i_0'r$ these inclusions imply that $$ 0\leq \lenght(X_{i+L+e,\mathfrak{p}}/X'_{(i+L)r,\mathfrak{p}})\leq \lenght(X_{i+L+e,\mathfrak{p}}/X_{(i+L)r,\mathfrak{p}})=e\lambda.$$

	Moreover, the chain of inclusion $X_{i,\mathfrak{p}}\subseteq X'_{ir,\mathfrak{p}}\subseteq X'_{(i+1)r,\mathfrak{p}}\subseteq \cdots\subseteq X'_{(i+L)r,\mathfrak{p}}\subseteq X_{i+L+e,\mathfrak{p}}$ imply that $$(i+L)\lambda=\lenght(X'_{(i+L)r,\mathfrak{p}}/X'_{ir,\mathfrak{p}})+\lenght(X_{i+L+e,\mathfrak{p}}/X'_{(i+L)r,\mathfrak{p}}) $$ and 
	$$\lenght(X'_{(i+L)r,\mathfrak{p}}/X'_{ir,\mathfrak{p}})=rL\lenght(Y'_\mathfrak{p}). $$

	In conclusion, $$\lambda/r\leq \lenght(Y'_\mathfrak{p})\leq \tfrac{L+e}{Lr}\lambda.$$

	Note that the lower bound is inside the interval $(0,1)$ and if $L$ is big enough then the upper bound also is inside the interval $(0,1)$, contradicting the fact that $\lenght(Y'_\mathfrak{p})$ is an integer.
\end{proof}

We want now to extend \Cref{non commutative finitely generation modules} to skew-Laurent rings. Thus, we consider the skew-Laurent ring $R[z^{\pm 1};\alpha]$, where $\alpha\in \Aut(R)$. We now construct an iterated skew-polynomial ring as follows (see \cite[Exercise 1R]{goodearl2004introduction}). First, we consider the skew-polynomial ring $R[t_+;\alpha_+]$ where $\alpha_+=\alpha$. We now define a map $\alpha_-:R[t_+;\alpha_+]\longrightarrow R[t_+;\alpha_+]$ satisfying that $\alpha_-(\sum t^ir_i)=\sum t^i\alpha^{-1}(r_i)$. Using that $rt=t\alpha^{-1}(r)$ and that $\alpha$ is an automorphism, it is straightforward to prove that $\alpha_-$ is an automorphism of $R[t_+;\alpha_+]$. Thus, we can consider the iterated skew-polynomial ring $(R[t_+;\alpha_+])[t_-;\alpha_-]$. Consider the map $\mu: (R[t_+;\alpha_+])[t_-;\alpha_-]\longrightarrow R[z^{\pm1};\alpha]$ defined as $\mu(\sum t_-^i(\sum t_+^jr_{ij}))=\sum z^{j-i}r_{ij}$. As before, a routine check shows that $\mu$ is a surjective ring morphism. Thus, if $X$ is a finitely generated $R[z_{\pm1};\alpha]$-module then $X$ is finitely generated as a $(R[t_+;\alpha_+])[t_-;\alpha_-]$-module. Assume that there exists a sequence of positive integers $r_i\longrightarrow\infty$ and a collection of $R[z^{\pm1};\alpha]$-automorphisms $w_i:X\longrightarrow X$ such that $w_i^{r_i}$ coincides with the multiplication by $z$ on the right. We define automorphisms $w_{i+}:X\longrightarrow X$ and $w_{i-}:X\longrightarrow X$ satisfying that $w_{i+}=w_i$ and $w_{i-}=w_i^{-1}$ for all $i$. By construction, $w_{i+}^{r_i}$ coincides with the right multiplication by $t_+$ and $w_{i+}^{r_i}$ coincides with the right multiplication by $t_-$. Thus, we have:

\begin{cor}\label{non commutative finitely generation modules skew-Laurent}
	Let $R$ be a prime Noetherian ring such that any prime ideal $\mathfrak{p}$ is right localizable. Suppose that $M$ is a finitely generated $R[z^{{\pm1}};\alpha]$-module and that there exists a sequence of positive integers $r_j\longrightarrow\infty$ and a collection of automorphisms $w_j:M\longrightarrow M$ such that $w_j^{r_j}$ coincides with the right multiplication by $z$. Finally, assume that $R[t_+;\alpha_+]$ defined as above is also a prime Noetherian ring such that any prime ideal $\mathfrak{p}$ is right localizable. Then $M$ is finitely generated as $R$-module.
\end{cor}

Recall that $\tilde{M}$ denotes the total space of the pull-back of the covering $N\longrightarrow N/\Gamma$ by $f:M\longrightarrow N/\Gamma$. Since the group ring $\Z\Gamma$ satisfies the conditions of \cref{non commutative finitely generation modules skew-Laurent} (see \cite[(A) Connell's Theorem]{lam1991first} and \cite[pg. 17, Appendix B]{bell1988notes}) and they are iterated skew-Laurent rings, we can use downward induction to prove:

\begin{cor}\label{cohomology fg group}
	$H^*(\tilde{M},\Z)$ is a finitely generated $\Z$-module.
\end{cor}

\begin{proof}
	By \cref{cohomology fg group ring}, $H^*(\tilde{M},\Z)$ is a finitely generated as $\Z\Gamma$-module. Recall also that $\Z\Gamma\cong \Z[e_1^{\pm1},\dots,e_a^{\pm1},{e_1'}^{\pm1},\dots,{e_b'}^{\pm1};\alpha_1,\cdots,\alpha_{a+b}]$. By \cref{Gamma-modules 1} and \cref{Gamma-module 2}, there exists a collection of $\{w'_{b,i}\}_{i\in\mathbb{N}}$ of automorphisms satisfying that $(w_{b,i}')^{p_i}$ coincides with the multiplication of $e'_b$. Thus, by \cref{non commutative finitely generation modules skew-Laurent}, $H^*(\tilde{M},\Z)$ is a finitely generated as $\Z\Gamma\cong \Z[e_1^{\pm1},\dots,e_a^{\pm1},{e_1'}^{\pm1},\dots,{e'}^{\pm1}_{b-1};\alpha_1,\cdots,\alpha_{a+b-1}]$. We can repeat this process with each generator to conclude that $H^*(\tilde{M},\Z)$ is a finitely generated as $\Z$-module.
\end{proof}

\textbf{Part 6. Concluding the proof} The last step of the proof \cref{free iterated actions rigidity hypernilmanifolds} is to prove that $H^*(\tilde{M},\Z)$ is acyclic (that is, $H^0(\tilde{M},\Z)\cong\Z$ and $H^i(\tilde{M},\Z)=0$ for all $i>0$). We will prove this statement by contradiction.

Assume that $\tilde{M}$ is not $\Z$-acyclic. Note that $f_*(\pi_1(M))=\Gamma$ implies $H^0(\tilde{M},\Z)\cong \Z$. Hence if $\tilde{M}$ is not $\Z$-acyclic there exists $j>0$ such that $H^j(\tilde{M},\Z)\neq 0$.

By the universal coefficients theorem, there exists a prime $l$ such that $\tilde{M}$ is not $\Z/l$-acyclic. Let $k=\max\{j:H^j(\tilde{M},\Z/l)\neq 0\}>0$. Since $H^*(\tilde{M},\Z)$ is a finitely generated abelian group, then $\Aut(H^*(\tilde{M},\Z/l))$ is finite. Let $\Phi_{(l)}:\Gamma\longrightarrow \Aut(H^*(\tilde{M},\Z/l))$ be the group morphism induced by the action of $\Gamma$ on $\tilde{M}$. The kernel of the morphism $\Phi_{(l)}:\Gamma\longrightarrow \Aut(H^*(\tilde{M},\Z/l))$, which we denote by $\Lambda$, has finite index in $\Gamma$. Hence $\Lambda$ is a lattice of $N$. Consider the diagram
\[\begin{tikzcd}
	\tilde{M}\times_\Lambda N\ar{d}{\pi}\ar{r}{\Theta} & \tilde{M}/\Lambda\\
	N/\Lambda &
\end{tikzcd}\]
where $\Theta$ and $\pi$ are the natural projections. Since $N$ is contractible the map $\Theta$ is a homotopy equivalence and $H^j(\tilde{M}\times_\Lambda N,\Z/l)\cong H^j(\tilde{M}/\Lambda,\Z/l)=0$ for $j>n$.

To compute the cohomology of the other fibration we need to use the Serre spectral sequence. The monodromy action of $\Lambda$ on $H^j(\tilde{M},\Z/l)$ is trivial, thus
$$E_2^{r,s}=H^r(N/\Lambda,H^s(\tilde{M},\Z/l))\cong H^r(N/\Lambda,\Z/l)\otimes H^s(\tilde{M},\Z/l)\implies H^{r+s}(\tilde{M}\times_\Lambda N,\Z/l).$$

We have $E_2^{k,n}\neq 0$, but for dimensional reasons $E_2^{k,n}$ does not belong to the image of any differential. Furthermore, $E_2^{k,n}$ is not inside the kernel of any differential. Consequently, $H^{k+n}(\tilde{M}\times_\Lambda N,\Z/l)\neq 0$ which is a contradiction because $\tilde{M}\times_\Lambda N\cong \tilde{M}/\Lambda$ and $\tilde{M}/\Lambda$ has dimension $n$.

Finally, we take the fibration \[\begin{tikzcd}
	\tilde{M}\times_\Gamma N\ar{d}{\pi}\\
	N/\Gamma
\end{tikzcd}\]
with fiber $\tilde{M}$. Since $\tilde{M}$ is acyclic the Serre spectral sequence collapses on the second page. This implies that $H^*(M,\Z)\cong H^*(\tilde{M}\times_\Gamma N,\Z)\cong H^*(N/\Gamma,\Z)$ as we wanted to see.

\begin{cor}
	With the same assumptions as in \cref{free iterated actions rigidity hypernilmanifolds}.2, suppose also that $\pi_1(M)$ is virtually solvable. Then $M$ is homeomorphic to $N/\Gamma$.
\end{cor}

\begin{proof}
	Firstly, recall that $f:M\longrightarrow N/\Gamma$ induces a surjective map $f_*:\pi_1(M)\longrightarrow \Gamma$. Since $\pi_1(M)$ is virtually solvable there exists a finite covering $q:M'\longrightarrow M$ such that $\pi_1(M')$ is solvable. We have a commutative diagram\[
	\begin{tikzcd}
		M' \ar{d}{r}\ar{r}{f'} & N/\Gamma'\ar{d}{}\\
		M	\ar{r}{f} & N/\Gamma
	\end{tikzcd}\]

	where $f'_*:\pi_1(M')\longrightarrow \Gamma'$ is surjective. Notice that $\D_2(N/\Gamma')=\D_2(N/\Gamma)$ and that $\D_2(M')\geq \D_2(M)$. Consequently, we have $\D_2(N/\Gamma')=\D_2(M')$. The next step is to prove that $M'$ is a nilmanifold.  

	The acyclic manifold $\tilde{M}'$ has solvable fundamental group. This implies, since $H_1(\tilde{M}',\Z)$ is trivial, that $\tilde{M}'$ is simply connected. Consequently, $\tilde{M}'$ is contractible by Hurewicz theorem (see \cite[Corollary 4.33]{hatcher2002algebraic}) and $M'$ is a closed connected aspherical manifold. The map $\pi:\tilde{M}' \times_{\Gamma'}N\longrightarrow N/\Gamma'$ is a homotopy equivalence. Since $\Theta$ is also a homotopy equivalence we can construct a homotopy equivalence $M'\longrightarrow N/\Gamma'$. Since the Borel conjecture is true for nilmanifolds, we can conclude that $M'$ is homeomorphic to $N/\Gamma$.

	Finally, $M$ is also a closed connected aspherical manifold, since the finite covering $r:M'\longrightarrow M$ is obtained via pullback by $f$ of the covering of nilmanifolds $N/\Gamma'\longrightarrow N/\Gamma$, we have $\pi_1(M)\cong \Gamma$. Thus, $M$ is homeomorphic to $N/\Gamma$, as we wanted to see.
\end{proof}

\begin{rem}
	Using the same argument as in \cref{iterated action rational cohomology}, we can remove the assumption that $f_*:\pi_1(M)\longrightarrow \Gamma$ is surjective. In this case, if $\pi_1(M)$ is virtually solvable then $M$ is homeomorphic to a nilmanifold and $\pi_1(M)$ is commensurable to $\Gamma$.
\end{rem}

